        private void Awake()

        {

            if (Instance != null && Instance != this)

            {

                Destroy(gameObject);

                return;

            }

            Instance = this;

            if (_skillThemeSpriteCache == null)

                _skillThemeSpriteCache = new Dictionary<string, Sprite>();

            else

                _skillThemeSpriteCache.Clear();

            if (_slantedSpriteCache == null)

                _slantedSpriteCache = new Dictionary<string, Sprite>();

            else

                _slantedSpriteCache.Clear();

            // Instatitate Raycast Debugger

            new GameObject("KOURaycastDebugger").AddComponent<KOURaycastDebugger>();

            // Fısıltı (PM) yöneticisini ekle

            gameObject.AddComponent<KOWhisperManager>();

            // İnceleme (Inspect) yöneticisini ekle

            gameObject.AddComponent<KOInspectManager>();

            // Arkadaş listesi yöneticisini ekle

            gameObject.AddComponent<KOFriendManager>();

        }

        private void Start()
        {
            EnsureBuffBarContainer();
            if (KONetworkManager.Instance != null)
            {
                KONetworkManager.Instance.OnDisconnected += OnServerDisconnected;
            }
        }

        private void OnServerDisconnected()
        {
            if (KOMessageBox.Instance != null)
            {
                KOMessageBox.Instance.Show(
                    "Disconnected from server",
                    "",
                    MsgBoxStyle.MB_OK,
                    MsgBoxBehavior.BEHAVIOR_DISCONNECT,
                    onYes: () => {
                        // Load LoginScene to allow clean reconnection
                        UnityEngine.SceneManagement.SceneManager.LoadScene("LoginScene");
                    },
                    forceFixedCenter: true,
                    useBlocker: true
                );
            }
            else
            {
                // Fallback: directly load LoginScene
                UnityEngine.SceneManagement.SceneManager.LoadScene("LoginScene");
            }
        }

        public void ChangeChattingMode(byte mode)

        {

            _chatMode = mode;

            UpdateChatModeButtonStates();

        }

        private void HandleChatTargetResult(byte[] rawData)

        {

            var r = new KOPacketReader(rawData);

            string targetName = r.ReadKOString();

            if (string.IsNullOrEmpty(targetName))

            {

                AddMsgOutput("The user is not online or does not exist.", D3DColorToUnity(0xffffff00));

                ChangeChattingMode(1);

            }

            else

            {

                // AddMsgOutput($"Whisper target is set to {targetName}.", D3DColorToUnity(0xffffff00));

                ChangeChattingMode(2);

                KOWhisperManager.Instance?.ShowWhisperWindow(targetName);

            }

        }

        private void OnEnable()

        {

            KOPacketHandler.OnShoppingMall += HandleShoppingMallPacket;

            KOPacketHandler.OnChatTargetResult += HandleChatTargetResult;

            KOPacketHandler.OnClassChange += HandleClassChange_KO;

            KOPacketHandler.OnMarketBBS += HandleMarketBBSPacket;

        }

        private void OnDisable()

        {

            KOPacketHandler.OnShoppingMall -= HandleShoppingMallPacket;

            KOPacketHandler.OnChatTargetResult -= HandleChatTargetResult;

            KOPacketHandler.OnClassChange -= HandleClassChange_KO;

            KOPacketHandler.OnMarketBBS -= HandleMarketBBSPacket;

        }

        private void HandleMarketBBSPacket(byte[] rawData)

        {

            var reader = new KOPacketReader(rawData);

            byte subType = reader.ReadByte();

            byte bbsKind = reader.ReadByte();

            byte result = reader.ReadByte();

            // Eğer Auction House arayüzü açıksa, bu paketleri TradeBBS'e yönlendirme

            if (_uiAuctionHouse != null && _uiAuctionHouse.IsVisible)

            {

                return;

            }

            var passReader = new KOPacketReader(rawData);

            if (subType == TradeBBSSub.N3_SP_TYPE_BBS_OPEN && result == 0x01 && bbsKind == 0)

            {

                ShowTradeBBSSelector(true);

                if (KOInventory.Instance != null)

                {

                    for (int i = 0; i < KOInventory.MAX_ITEM_INVENTORY; i++)

                    {

                        var slot = KOInventory.Instance.m_pMyInvWnd[i];

                        if (slot != null && slot.itemId == 800085000)

                        {

                            slot.byFlag = 1;

                            if (slot.serverData != null)

                            {

                                slot.serverData.byFlag = 1;

                            }

                            break;

                        }

                    }

                }

            }

            else

            {

                if (_tradeBBS != null)

                {

                    _tradeBBS.MsgRecv_TradeBBS(passReader);

                }

            }

        }

        private void HandleShoppingMallPacket(byte[] rawData)

        {

            var reader = new KOPacketReader(rawData);

            byte subOpcode = reader.ReadByte();

            if (subOpcode == (byte)ShoppingMallOpcodes.STORE_OPEN)

            {

                short errorCode = reader.ReadInt16();

                short freeSlot = reader.ReadInt16();

                if (errorCode == 1)

                {

                    OpenShoppingMallUI();

                }

                else

                {

                    string errorMsg = "Could not open Power Up Store.";

                    if (errorCode == -2) errorMsg = "You cannot open Power Up Store while dead.";

                    else if (errorCode == -3) errorMsg = "You cannot open Power Up Store while trading.";

                    else if (errorCode == -4) errorMsg = "You cannot open Power Up Store while selling.";

                    else if (errorCode == -7) errorMsg = "Power Up Store is already open.";

                    else if (errorCode == -8) errorMsg = "Not enough space in inventory!";

                    ShowToast(errorMsg);

                }

            }

        }

        public void OpenShoppingMallUI()

        {

            if (_uiShoppingMall != null)

            {

                _uiShoppingMall.SetActive(true);

                var pusUI = _uiShoppingMall.GetComponent<KOPowerUpStoreUI>();

                if (pusUI != null)

                {

                    pusUI.Init();

                }

                RepositionSkillBarForPanel();

            }

        }

        public void CloseShoppingMallUI()

        {

            if (_uiShoppingMall != null)

            {

                _uiShoppingMall.SetActive(false);

                RepositionSkillBarForPanel();

            }

        }

        private void OnDestroy()

        {

            if (Instance == this) Instance = null;

            if (KONetworkManager.Instance != null)
            {
                KONetworkManager.Instance.OnDisconnected -= OnServerDisconnected;
            }

        }

        /// <summary>

        /// Her frame minimap UV güncelle.

        /// C++ UIStateBar.cpp Tick() satır 489-510 birebir:

        /// TickMiniMap() → player pozisyonuna göre UV rect hesapla.

        /// </summary>

        private void Update()

        {

            if (_msgOutputDirty)

            {

                _msgOutputDirty = false;

                UpdateMsgOutputTextImmediate();

            }

            if (_chatDirty)

            {

                _chatDirty = false;

                RebuildChatVisibleTextImmediate();

            }

            if (_uiCountableEdit != null && _uiCountableEdit.activeSelf)

            {

                var rt = _uiCountableEdit.GetComponent<RectTransform>();

                if (rt != null)

                {

                    rt.anchorMin = new Vector2(0.5f, 0.5f);

                    rt.anchorMax = new Vector2(0.5f, 0.5f);

                    rt.pivot = new Vector2(0.5f, 0.5f);

                    rt.anchoredPosition = Vector2.zero;

                }

            }

            if (KOMessageBox.Instance != null && KOMessageBox.Instance.IsVisible)

            {

                var activePanel = KOMessageBox.Instance.ActivePanel;

                var caller = KOMessageBox.Instance.CallerPanel;

                if (activePanel != null && activePanel.activeSelf && caller != null && caller.activeSelf)

                {

                    CenterPanelOnPanel(activePanel, caller);

                }

            }

            RepositionSkillBarForPanel();

            var gm = EntropyOnline.Core.GameManager.Instance;

            if (gm != null)

            {

                UpdatePositionText(gm.PlayerPosX, gm.PlayerPosZ);

                // C++ UIStateBar.cpp Tick() satır 508: TickMiniMap()

                if (_miniMapImage != null && _miniMapSizeX > 0 && _miniMapSizeZ > 0

                    && _miniMapGroup != null && _miniMapGroup.activeSelf)

                {

                    UpdateMiniMapUV(gm.PlayerPosX, gm.PlayerPosZ);

                }

                if (_zoneMapGroup != null && _zoneMapGroup.activeSelf)

                {

                    UpdateZoneMap();

                }

                // Karakterin oturma/kalkma durumuna göre Sit ve Stand butonlarının görünürlüğünü güncelle

                if (_uiCmdBar != null)

                {

                    // Ekran boyutu değiştiğinde alttaki komut barı butonlarının ve Draco Online yazısının sabit pixel boyutunda kalmasını sağla

                    if (_canvas != null)

                    {

                        float s = _canvas.scaleFactor;

                        if (s > 0f && Mathf.Abs(s - _lastScaleFactor) > 0.0001f)

                        {

                            _lastScaleFactor = s;
                            _uiCmdBar.transform.localScale = new Vector3(UIScaleMultiplier / s, UIScaleMultiplier / s, UIScaleMultiplier / s);

                            if (_uiStateBar != null)

                            {

                                _uiStateBar.transform.localScale = new Vector3(UIScaleMultiplier / s, UIScaleMultiplier / s, UIScaleMultiplier / s);

                            }

                            if (_uiCountableEdit != null)

                            {

                                _uiCountableEdit.transform.localScale = new Vector3(UIScaleMultiplier / s, UIScaleMultiplier / s, UIScaleMultiplier / s);

                            }

                            if (_uiQuestTracker != null)

                            {

                                _uiQuestTracker.transform.localScale = new Vector3(UIScaleMultiplier / s, UIScaleMultiplier / s, UIScaleMultiplier / s);

                                var rt = _uiQuestTracker.GetComponent<RectTransform>();

                                if (rt != null)

                                {

                                    rt.anchoredPosition = new Vector2(5f / s, -200f / s);

                                }

                            }

                            if (_uiAuctionHouse != null)

                            {

                                _uiAuctionHouse.UpdateScale(s);

                            }

                            if (_uiPersonalTrade != null && _uiPersonalTrade.activeSelf)

                            {

                                _uiPersonalTrade.transform.localScale = new Vector3(UIScaleMultiplier / s, UIScaleMultiplier / s, UIScaleMultiplier / s);

                            }

                            if (_uiShoppingMall != null)

                            {

                                var pusUI = _uiShoppingMall.GetComponent<KOPowerUpStoreUI>();

                                if (pusUI != null)

                                {

                                    pusUI.UpdateScale(s);

                                }

                            }

                            if (_uiPartyBBS != null)

                            {

                                _uiPartyBBS.transform.localScale = new Vector3(UIScaleMultiplier / s, UIScaleMultiplier / s, UIScaleMultiplier / s);

                            }

                            if (_uiPartyBBSSelector != null)

                            {

                                _uiPartyBBSSelector.transform.localScale = new Vector3(UIScaleMultiplier / s, UIScaleMultiplier / s, UIScaleMultiplier / s);

                            }

                            // Chat ve Savaş Günlüğü panellerinin de sabit ölçekte kalmasını ve hizalanmasını güncelle

                            RearrangePanelsPosition();

                            if (EntropyOnline.UI.KOWhisperManager.Instance != null)

                            {

                                EntropyOnline.UI.KOWhisperManager.Instance.UpdatePanelsScaleAndPosition(s);

                            }

                        }

                    }

                    var sitTrans = _uiCmdBar.transform.Find("btn_sit");

                    var standTrans = _uiCmdBar.transform.Find("btn_stand");

                    if (sitTrans != null && standTrans != null)

                    {

                        var pc = FindAnyObjectByType<EntropyOnline.Character.PlayerController>();

                        bool isSitting = pc != null && pc.State() == EntropyOnline.Character.PlayerStateAction.PSA_SITDOWN;

                        if (sitTrans.gameObject.activeSelf == isSitting)

                        {

                            sitTrans.gameObject.SetActive(!isSitting);

                        }

                        if (standTrans.gameObject.activeSelf != isSitting)

                        {

                            standTrans.gameObject.SetActive(isSitting);

                        }

                    }

                }

            }

            // C++ UIStateBar.cpp Tick() satır 509: TickMagicIcon()

            TickBuffIcons();

            // C++ UIChat.cpp Tick() — Continue Notice scroll animasyonu

            // C++ birebir: m_ContinueMsgBuffer sola doğru kayar, bitince sağdan yeniden başlar

            TickContinueNoticeScroll();

            // C++ birebir: CUIState::UpdateHP/UpdateMSP/UpdateExp/UpdateStrength/vb.

            // C++'ta her stat paketi geldiginde (MsgRecv_MyInfo_HP, MsgRecv_MyInfo_EXP, vb.)

            // ilgili CUIState::UpdateXxx fonksiyonu cagrilir ve text guncellenir.

            // Unity'de panel acikken her frame RefreshPageState ile ayni davranis saglanir.

            if (_uiVarious != null && _uiVarious.activeSelf)

            {

                RefreshPageState();

            }

            // C++ birebir: CUIKnights — m_fTimeLimit_* her frame artan cooldown timer'ları

            float dt = Time.deltaTime;

            _fTimeLimit_Refresh += dt;

            _fTimeLimit_Admit   += dt;

            _fTimeLimit_Remove  += dt;

            _fTimeLimit_Appoint += dt;

            // Keyboard shortcut for map (M key -> ZoneMap)

            var kb = UnityEngine.InputSystem.Keyboard.current;

            if (kb != null)

            {

                if (kb.f8Key.wasPressedThisFrame)

                {

                    SetTitleNotice("GM: ARES-1 sunucusu 5 dakika icinde bakima girecektir. Lutfen guvenli cikis yapiniz.");

                    AddChatMessage(9, "GM : ARES-1 sunucusu 5 dakika icinde bakima girecektir. Lutfen guvenli cikis yapiniz.");

                }

                if (kb.f9Key.wasPressedThisFrame)

                {

                    SetContinueNotice("Castle Siege Warfare basladi! Tum klanlara basarilar dileriz. Savas suresi 60 dakikadir.");

                    AddChatMessage(11, "GM : Castle Siege Warfare basladi! Tum klanlara basarilar dileriz. Savas suresi 60 dakikadir.");

                }

                if (kb.mKey.wasPressedThisFrame)

                {

                    if (!IsAnyInputFieldFocused())

                    {

                        ToggleZoneMap();

                    }

                }

                if (kb.qKey.wasPressedThisFrame)

                {

                    if (!IsAnyInputFieldFocused())

                    {

                        ToggleQuestJournal();

                    }

                }

            }

        }

        public static bool IsAnyInputFieldFocused()

        {

            if (UnityEngine.EventSystems.EventSystem.current == null) return false;

            var sel = UnityEngine.EventSystems.EventSystem.current.currentSelectedGameObject;

            if (sel == null) return false;

            return sel.GetComponent<UnityEngine.UI.InputField>() != null || sel.GetComponent<TMPro.TMP_InputField>() != null;

        }

        /// <summary>

        /// C++ UIChat.cpp Continue Notice scroll — her frame text'i sola kaydırır.

        /// C++ referans: UIChat.cpp satır 462-489 birebir scroll mantığı.

        /// </summary>

        private void TickContinueNoticeScroll()

        {

            if (_continueNoticeText != null && !string.IsNullOrEmpty(_continueNoticeMsg) && _continueNoticeText.transform.parent.gameObject.activeSelf)

            {

                var rt = _continueNoticeText.rectTransform;

                float containerWidth = rt.parent.GetComponent<RectTransform>().rect.width;

                float textWidth = _continueNoticeText.preferredWidth;

                _continueScrollOffset -= 40f * Time.deltaTime;

                if (_continueScrollOffset < -textWidth)

                    _continueScrollOffset = containerWidth;

                rt.anchoredPosition = new Vector2(_continueScrollOffset, 0f);

            }

            // New Integrated Notice Bar tick

            if (_isNoticeBarActive && _uiNoticeBar != null && _uiNoticeBarText != null && _uiNoticeBarTextRT != null)

            {

                // Smooth Fade-in and Fade-out processing using CanvasGroup alpha

                if (_uiNoticeBarCG != null)

                {

                    if (_noticeFadeDirection > 0f)

                    {

                        _uiNoticeBarCG.alpha = Mathf.MoveTowards(_uiNoticeBarCG.alpha, 1f, _noticeFadeSpeed * Time.deltaTime);

                        if (_uiNoticeBarCG.alpha >= 1f)

                        {

                            _noticeFadeDirection = 0f;

                        }

                    }

                    else if (_noticeFadeDirection < 0f)

                    {

                        _uiNoticeBarCG.alpha = Mathf.MoveTowards(_uiNoticeBarCG.alpha, 0f, _noticeFadeSpeed * Time.deltaTime);

                        if (_uiNoticeBarCG.alpha <= 0f)

                        {

                            _noticeFadeDirection = 0f;

                            _uiNoticeBar.SetActive(false);

                            _isNoticeBarActive = false;

                            _isNoticeScrolling = false;

                            _uiNoticeBarText.text = "";

                        }

                    }

                }

                // Only perform movement / countdown while we are not fading out

                if (_noticeFadeDirection >= 0f)

                {

                    if (_isNoticeScrolling)

                    {

                        // Scrolling mode (Continue Notice)

                        float containerWidth = _uiNoticeBar.GetComponent<RectTransform>().rect.width;

                        float textWidth = _uiNoticeBarText.preferredWidth;

                        float currentX = _uiNoticeBarTextRT.anchoredPosition.x;

                        currentX -= _noticeScrollSpeed * Time.deltaTime;

                        if (currentX < -textWidth)

                        {

                            // Trigger smooth fade-out

                            _noticeFadeDirection = -1f;

                        }

                        else

                        {

                            _uiNoticeBarTextRT.anchoredPosition = new Vector2(currentX, 0f);

                        }

                    }

                    else

                    {

                        // Static mode (Title Notice)

                        _noticeActiveTimer -= Time.deltaTime;

                        if (_noticeActiveTimer <= 0f)

                        {

                            // Trigger smooth fade-out

                            _noticeFadeDirection = -1f;

                        }

                    }

                }

            }

        }

        /// <summary>

        /// Zone ID'den minimap DXT dosya adı döndürür.

        /// C++ __TABLE_ZONE::szMiniMapFN karşılığı — Zones/ dizinindeki dosyalar.

        /// Open-KO Zone tablosundan birebir eşleme.

        /// </summary>

        public static string GetMiniMapFileName(short zoneId)

        {

            // Zones.tbl'den decrypt edilerek çıkarılmış GERÇEK eşlemeler.

            // Zones.tbl dwID = server zoneId * 10. szMiniMapFN = 8. alan.

            // Decrypt anahtarları: key_r=0x0816, key_c1=0x6081, key_c2=0x1608

            // (C++ N3TableBaseImpl.cpp satır 51-77)

            return zoneId switch

            {

                1   => "Zones\\karus2004.dxt",         // ZONE_KARUS (TBL ID: 10)

                2   => "Zones\\elmo2004.dxt",          // ZONE_ELMORAD (TBL ID: 20)

                11  => "Zones\\EslantZone.dxt",        // ZONE_ESLANT_KARUS (TBL ID: 110)

                12  => "Zones\\EslantZone.dxt",        // ZONE_ESLANT_ELMORAD (TBL ID: 120)

                21  => "Zones\\Moradon_xmas.dxt",      // ZONE_MORADON (TBL ID: 210)

                30  => "Zones\\war_a.dxt",             // ZONE_DELOS (TBL ID: 300)

                31  => "Zones\\dungeon_a.dxt",         // ZONE_BIFROST (TBL ID: 310)

                32  => "Zones\\dungeon_b1th.dxt",      // ZONE_DESPERATION_ABYSS (TBL ID: 320)

                33  => "Zones\\dungeon_b2th.dxt",      // ZONE_HELL_ABYSS (TBL ID: 330)

                48  => "Zones\\arena.dxt",             // ZONE_ARENA (TBL ID: 480)

                101 => "Zones\\BattleZone.dxt",        // ZONE_BATTLE (TBL ID: 1010)

                102 => "Zones\\BattleZone_b.dxt",      // ZONE_BATTLE2 (TBL ID: 1020)

                103 => "Zones\\BattleZone_c.dxt",      // ZONE_BATTLE3 (TBL ID: 1030)

                111 => "Zones\\BattleZone_b.dxt",      // ZONE_SNOW_BATTLE (TBL ID: 1110)

                201 => "Zones\\FreeZone_b.dxt",        // ZONE_FRONTIER (TBL ID: 2010)

                _   => "Zones\\Moradon_xmas.dxt"       // Fallback: Moradon

            };

        }

        /// <summary>

        /// InitUI() — C++ GameProcMain::InitUI() birebir portu.

        /// Nation'a göre doğru prefix ile UIF dosyalarını yükler.

        ///

        /// C++ referans: GameProcMain.cpp satır 3884

        /// </summary>

        public void InitUI(int nation = 2) // 2 = ELMORAD, 1 = KARUS

        {

            // Canvas oluştur — KO orijinal çözünürlüğü ile

            CreateCanvas();

            // İkon pipeline

            KOItemIconLoader.SetAssetsPath(KO_ASSETS_ROOT);

            // Nation prefix: el_ = Elmorad, ka_ = Karus

            // C++ referans: __TABLE_UI_RESRC — GameDef.h satır 672

            string prefix = (nation == 1) ? "ka_" : "el_";

            string uiDir = "UI_US";

            // ================================================

            // C++ InitUI() sırası birebir:

            // ================================================

            // 1. Command bar (alt orta)

            // C++: m_pUICmd->LoadFromFile(pTbl->szCmd)

            // C++: SetPos((iW - width) / 2, iH - height)

            _uiCmdBar = LoadModernUIPanelDirect(prefix + "cmd_us");

            if (_uiCmdBar != null)

            {

                // CmdBar: ekranın en altına ortala (bottom-center anchor)

                var rt = _uiCmdBar.GetComponent<RectTransform>();

                if (rt != null)

                {

                    rt.anchorMin = new Vector2(0.5f, 0); // bottom-center

                    rt.anchorMax = new Vector2(0.5f, 0);

                    rt.pivot = new Vector2(0.5f, 0);     // pivot alt-orta

                    rt.anchoredPosition = new Vector2(0, 0); // tam altda

                }

                if (IsModernPrefab(_uiCmdBar.transform))

                {

                    BindCmdBarPrefab(_uiCmdBar.transform);

                }

                else

                {

                    BindCmdBarButtons(_uiCmdBar.transform);

                    RestructureCmdBar(_uiCmdBar.transform);

                }

            }

            // 2. Chat paneli (sol alt, cmd üstünde — bottom-left anchor)

            _uiChatDlg = LoadModernUIPanelDirect(prefix + "chat_us");

            if (_uiChatDlg != null && _uiCmdBar != null)

            {

                var rcCmd = GetKORegion(_uiCmdBar);

                var rt = _uiChatDlg.GetComponent<RectTransform>();

                if (rt != null)

                {

                    rt.anchorMin = new Vector2(0, 0); // bottom-left

                    rt.anchorMax = new Vector2(0, 0);

                    rt.pivot = new Vector2(0, 0);     // pivot sol-alt

                    rt.anchoredPosition = new Vector2(2f, 48f); // Butonların üstünde, sol kenardan 2px boşluk

                }

                // Raycast engelleme: Chat alanına dokunulduğunda arkadaki joystick tetiklenmesin

                var img = _uiChatDlg.GetComponent<Image>();

                if (img == null)

                {

                    img = _uiChatDlg.AddComponent<Image>();

                    img.color = Color.clear;

                }

                img.raycastTarget = true;

                BindChatPanel(_uiChatDlg.transform);

            }

            // 3. Message output (chat'in sağında, aynı Y — bottom anchor)

            _uiMsgOutput = LoadModernUIPanelDirect(prefix + "msgoutput_us");

            if (_uiMsgOutput != null && _uiChatDlg != null && _uiCmdBar != null)

            {

                var rcChat = GetKORegion(_uiChatDlg);

