                }

                BindMsgOutput(_uiMsgOutput.transform);

            }

            // 4. State bar + MiniMap (sol üst)

            // C++: m_pUIStateBarAndMiniMap->LoadFromFile(pTbl->szStateBar)

            // C++: SetPos(0, 0)

            _uiStateBar = LoadModernUIPanelDirect(prefix + "statebar_us");

            if (_uiStateBar != null)

            {

                SetKOPosition(_uiStateBar, 0, 0);

                // Raycast engelleme: HP/MP/EXP/MiniMap alanına dokunulduğunda arkadaki joystick tetiklenmesin

                var img = _uiStateBar.GetComponent<Image>();

                if (img == null)

                {

                    img = _uiStateBar.AddComponent<Image>();

                    img.color = Color.clear;

                }

                img.raycastTarget = true;

                FindProgressBars(_uiStateBar.transform);

                BindStateBarElements(_uiStateBar.transform);

                BindStateBarButtons(_uiStateBar.transform);

                BindMiniMap(_uiStateBar.transform);

                RebuildMobileStateBar(_uiStateBar.transform);

                if (_canvas != null && _canvas.scaleFactor > 0f)

                {

                    float s = _canvas.scaleFactor;

                    _uiStateBar.transform.localScale = new Vector3(1f / s, 1f / s, 1f / s);

                }

