                // C++ Open(): SetPos(-(rc.right-rc.left), 80) → animasyonla (0, 80)'e gelir

                SetPanelPosLeftCenter(_uiVarious);

                BindVariousElements(_uiVarious.transform);

                // Add slide-in animation component

                var slide = _uiVarious.AddComponent<KOUIPanelSlideIn>();

