        private void InitializeSkillTreePool()

        {

            if (_uiSkillTree == null) return;

            Transform stRoot = _uiSkillTree.transform;

            // Arka planı ve diğer bileşenleri prosedürel oluşturup cache'e yazıyoruz (Böylece açılışta 0ms sürer ve PNG diske ihtiyaç duymaz)

            GetSkillThemePanelBgSprite("skilltree_bg", 378, 510, 0,

                new Color(0.12f, 0.10f, 0.08f, 0.98f),

                new Color(0.04f, 0.04f, 0.04f, 0.98f),

                new Color(0.6f, 0.48f, 0.22f, 0.9f),

                2);

            GetSkillThemeRoundedRectSprite("skill_close_btn", 24, 24, 0, new Color(0.18f, 0.18f, 0.18f, 1), new Color(0.45f, 0.35f, 0.15f, 1), 1);

            GetSkillThemeRoundedRectSprite("skill_btn_left", 20, 20, 0, new Color(0.15f, 0.15f, 0.15f, 1), new Color(0.45f, 0.35f, 0.15f, 0.8f), 1);

            GetSkillThemeRoundedRectSprite("skill_btn_right", 20, 20, 0, new Color(0.15f, 0.15f, 0.15f, 1), new Color(0.45f, 0.35f, 0.15f, 0.8f), 1);

            GetSkillThemeRoundedRectSprite("btn_plus", 14, 14, 0, new Color(0.25f, 0.2f, 0.05f, 1), Color.clear, 0);

            GetSkillThemeRoundedRectSprite("btn_skill_point_bg_106_22_10", 106, 22, 10, new Color(0.25f, 0.2f, 0.05f, 1), Color.clear, 0);

            GetSkillThemeRoundedRectSprite("skill_desc_box", 336, 130, 0, new Color(0.06f, 0.06f, 0.06f, 0.92f), new Color(0.55f, 0.45f, 0.20f, 0.8f), 1);

            GetSkillThemeRoundedRectSprite("skill_tab_divider", 336, 1, 0, new Color(0.6f, 0.48f, 0.22f, 0.4f), Color.clear, 0);

            GetSkillThemeRoundedRectSprite("tab_active", 75, 22, 0, new Color(0.28f, 0.22f, 0.08f, 1), Color.clear, 0);

            GetSkillThemeRoundedRectSprite("tab_inactive", 75, 22, 0, new Color(0.08f, 0.08f, 0.08f, 0.9f), Color.clear, 0);

            _stSkillObjs = new GameObject[ST_MAX_KIND, ST_MAX_PAGE, ST_MAX_SLOT];

            _stSkillIds = new int[ST_MAX_KIND, ST_MAX_PAGE, ST_MAX_SLOT];

            for (int a = 0; a < ST_MAX_KIND; a++)

                for (int b = 0; b < ST_MAX_PAGE; b++)

                    for (int c = 0; c < ST_MAX_SLOT; c++)

                        _stSkillIds[a, b, c] = -1;

            // Alanları 1 kez önbelleğe al

            RectTransform[] cachedAreas = new RectTransform[ST_MAX_SLOT];

            for (int slot = 0; slot < ST_MAX_SLOT; slot++)

            {

                cachedAreas[slot] = KOUIRenderer.FindChildAreaByiOrder(stRoot, 7, slot);

            }

            // Oyun başlamadan önce (yükleme ekranında) 480 boş slot objesini oluşturup pasif şekilde hazır tutuyoruz

            for (int kindOf = 0; kindOf < ST_MAX_KIND; kindOf++)

            {

                for (int page = 0; page < ST_MAX_PAGE; page++)

                {

                    for (int slot = 0; slot < ST_MAX_SLOT; slot++)

                    {

                        var areaRT = cachedAreas[slot];

                        var itemObj = new GameObject("Skill_empty_slot");

                        itemObj.transform.SetParent(stRoot, false);

                        var itemRT = itemObj.AddComponent<RectTransform>();

                        if (areaRT != null)

                        {

                            itemRT.anchorMin = areaRT.anchorMin;

                            itemRT.anchorMax = areaRT.anchorMax;

                            itemRT.offsetMin = areaRT.offsetMin;

                            itemRT.offsetMax = areaRT.offsetMax;

                        }

                        else

                        {

                            itemRT.anchorMin = new Vector2(0, 1);

                            itemRT.anchorMax = new Vector2(0, 1);

                            itemRT.pivot = new Vector2(0, 1);

                            float iconSize = 32f;

                            float gapX = 3f;

                            int col = slot % 6;

                            int row = slot / 6;

                            itemRT.anchoredPosition = new Vector2(8f + col * (iconSize + gapX), -200f - row * (iconSize + gapX));

                            itemRT.sizeDelta = new Vector2(iconSize, iconSize);

                        }

                        var img = itemObj.AddComponent<UnityEngine.UI.Image>();

                        img.color = Color.clear; // Başlangıçta şeffaf

                        img.raycastTarget = false;

                        var borderObj = new GameObject("BorderFrame");

                        borderObj.transform.SetParent(itemObj.transform, false);

                        var borderImg = borderObj.AddComponent<UnityEngine.UI.Image>();

                        borderImg.sprite = GetSkillThemeRoundedRectSprite("slot_border_locked", 36, 36, 0, Color.clear, new Color(0.35f, 0.35f, 0.35f, 0.7f), 1);

                        borderImg.raycastTarget = false;

                        var borderRT = borderObj.GetComponent<RectTransform>();

                        borderRT.anchorMin = Vector2.zero;

                        borderRT.anchorMax = Vector2.one;

                        borderRT.offsetMin = Vector2.zero;

                        borderRT.offsetMax = Vector2.zero;

                        itemObj.SetActive(false);

                        _stSkillObjs[kindOf, page, slot] = itemObj;

                        _skillTreeListItems.Add(itemObj);

                    }

                }

            }

        }

        private System.Collections.IEnumerator PrewarmPanelsCoroutine()

        {

            var panels = new List<GameObject> {

                _uiInventory, _uiTransaction, _uiSkillTree, _uiKnightsOp,

                _uiWarehouse, _uiWarp, _uiVarious, _uiDead, _uiExitMenu,

                _uiDroppedItem, _uiParty, _uiItemUpgrade, _uiNotice, _uiHelp,

                _uiLevelGuide, _uiQuestJournal, _uiNpcEvent,

                _uiMerchantControl, _uiGameOptions

            };

            foreach (var panel in panels)

            {

                if (panel != null) panel.SetActive(true);

            }

            yield return new WaitForEndOfFrame();

            // 1 kare boyunca yerleşimler ve shader'lar GPU'ya aktarıldı.

            // Şimdi statik paneller üzerindeki otomatik düzenleyicileri kapatıyoruz ki takılma yaşanmasın.

            foreach (var panel in panels)

            {

                if (panel == null) continue;

                var layoutGroups = panel.GetComponentsInChildren<UnityEngine.UI.LayoutGroup>(true);

                foreach (var lg in layoutGroups)

                {

                    string name = lg.gameObject.name.ToLower();

                    // Dinamik listeler ve sohbet alanları hariç tutuluyor

                    if (!name.Contains("content") && !name.Contains("scroll") && !name.Contains("list") && !name.Contains("chat"))

                    {

                        lg.enabled = false;

                    }

                }

                var fitters = panel.GetComponentsInChildren<UnityEngine.UI.ContentSizeFitter>(true);

                foreach (var cf in fitters)

                {

                    string name = cf.gameObject.name.ToLower();

                    if (!name.Contains("content") && !name.Contains("scroll") && !name.Contains("list") && !name.Contains("chat"))

                    {

                        cf.enabled = false;

                    }

                }

            }

            foreach (var panel in panels)

            {

                if (panel != null) panel.SetActive(false);

            }

        }

