        private void CreateCanvas()

        {

            var canvasObj = new GameObject("KOCanvas");

            canvasObj.transform.SetParent(transform, false);

            _canvas = canvasObj.AddComponent<Canvas>();

            _canvas.renderMode = RenderMode.ScreenSpaceOverlay;

            _canvas.sortingOrder = 100;

            var scaler = canvasObj.AddComponent<CanvasScaler>();

            scaler.uiScaleMode = CanvasScaler.ScaleMode.ScaleWithScreenSize;

            scaler.referenceResolution = new Vector2(KO_SCREEN_W, KO_SCREEN_H);

            scaler.screenMatchMode = CanvasScaler.ScreenMatchMode.Shrink;

            canvasObj.AddComponent<GraphicRaycaster>();

            // Create HUDContainer
            var hudContainerGo = new GameObject("HUDContainer", typeof(RectTransform));
            hudContainerGo.transform.SetParent(canvasObj.transform, false);
            _hudContainer = hudContainerGo.GetComponent<RectTransform>();
            _hudContainer.anchorMin = Vector2.zero;
            _hudContainer.anchorMax = Vector2.one;
            _hudContainer.offsetMin = Vector2.zero;
            _hudContainer.offsetMax = Vector2.zero;

            // Create global item tooltip to ensure it is always available to all panels at startup

            var tooltipGo = new GameObject("KOItemTooltip");

            tooltipGo.transform.SetParent(_canvas.transform, false);

            tooltipGo.AddComponent<KOItemTooltip>();

        }

