        /// <summary>

        /// UIF dosyasından UI panel yükler.

        /// Open-KO birebir: CN3UIBase::LoadFromFile() karşılığı.

        /// Public — KOMessageBox gibi harici sınıflar tarafından da kullanılır.

        /// <summary>

        /// Sadece modern prefab'ları yükleyen ve asla .uif dosyalarına veya eski binary parser sistemine başvurmayan temiz yükleyici.

        /// </summary>

        public GameObject LoadModernUIPanelDirect(string prefabName)

        {

            var prefab = Resources.Load<GameObject>($"ModernUI/{prefabName}");

            if (prefab == null)

            {

                Debug.LogError($"[KOUIMGR] Modern Prefab bulunamadı: ModernUI/{prefabName}");

                return null;

            }

            var panel = Instantiate(prefab, _hudContainer != null ? _hudContainer.transform : _canvas.transform);

            panel.name = prefab.name;

            // Cache uyumluluğu için _loadedPanels'e ekliyoruz

            _loadedPanels[prefabName + ".uif"] = panel;

            ApplyConstantPixelScaleOnLoad(panel);

            return panel;

        }

        public GameObject LoadUIPanel(string uiDir, string uifFileName)

        {

            string prefabName = Path.GetFileNameWithoutExtension(uifFileName);

            // 0. Yeni yerel Modern UI klasöründen yüklemeyi dene

            var modernPrefab = Resources.Load<GameObject>($"ModernUI/{prefabName}");

            if (modernPrefab != null)

            {

                var panel = Instantiate(modernPrefab, _hudContainer != null ? _hudContainer.transform : _canvas.transform);
                panel.name = modernPrefab.name;

                 // "(Clone)" suffix'ini kaldır

                _loadedPanels[uifFileName] = panel;

                ApplyConstantPixelScaleOnLoad(panel);

                return panel;

            }

            // 1. Prefab'dan yükle (build-time convert edilmiş)

            var prefab = Resources.Load<GameObject>($"KOPrefabs/UI/{prefabName}");

            if (prefab != null)

            {

                var panel = Instantiate(prefab, _hudContainer != null ? _hudContainer.transform : _canvas.transform);
                panel.name = prefab.name; // "(Clone)" suffix'ini kaldır

                _loadedPanels[uifFileName] = panel;

                // C++ birebir: CN3UIString::WordWrap() — prefab'lardaki text wrap fix

                KOUIRenderer.PostProcessTextComponents(panel);

                ApplyConstantPixelScaleOnLoad(panel);

                return panel;

            }

            string uifPath = uifFileName;

            var panelRT = KOUIRenderer.LoadUI(uifPath, _hudContainer != null ? _hudContainer.transform : _canvas.transform);

            if (panelRT == null)

            {

                Debug.LogError($"[KOUIMGR] UIF yüklenemedi: {uifFileName}");

                return null;

            }

            _loadedPanels[uifFileName] = panelRT;

            ApplyConstantPixelScaleOnLoad(panelRT);

            Debug.LogWarning($"[KOUIMGR] Runtime fallback: {uifFileName} — prefab bulunamadı, KO Tools → Convert UIF to Prefabs çalıştırın");

            return panelRT;

        }

        private void ApplyConstantPixelScaleOnLoad(GameObject panel)
        {
            if (panel == null || _canvas == null) return;

            var rt = panel.GetComponent<RectTransform>();
            if (rt != null)
            {
                if (GameOptionsManager.Instance != null)
                {
                    float scaleMultiplier = Mathf.Lerp(1.3f, 0.7f, GameOptionsManager.Instance.Graphic3_UIScale);
                    float refX = KO_SCREEN_W * scaleMultiplier;
                    float refY = KO_SCREEN_H * scaleMultiplier;
                    float expectedScale = Mathf.Min(Screen.width / refX, Screen.height / refY);

                    if (expectedScale > 0f)
                    {
                        float finalScale = UIScaleMultiplier / expectedScale;
                        rt.localScale = new Vector3(finalScale, finalScale, finalScale);
                        rt.anchoredPosition = new Vector2(rt.anchoredPosition.x / expectedScale, rt.anchoredPosition.y / expectedScale);
                    }
                }
                else
                {
                    float s = _canvas.scaleFactor;
                    if (s > 0f)
                    {
                        rt.localScale = new Vector3(1f / s, 1f / s, 1f / s);
                        rt.anchoredPosition = new Vector2(rt.anchoredPosition.x / s, rt.anchoredPosition.y / s);
                    }
                }
            }
        }

        // ================================================

        // KO Koordinat Sistemi

        // ================================================

        /// <summary>

        /// KO absolute koordinatında pozisyon ayarla.

        /// KO: sol-üst (0,0), sağ-alt (1024,768).

        /// Unity: sol-üst anchor, aşağı negatif Y.

        /// </summary>

        private void SetKOPosition(GameObject obj, int x, int y)

        {

            var rt = obj.GetComponent<RectTransform>();

            if (rt == null) return;

            rt.anchorMin = new Vector2(0, 1); // top-left anchor

            rt.anchorMax = new Vector2(0, 1);

            rt.pivot = new Vector2(0, 1);

            rt.anchoredPosition = new Vector2(x, -y);

        }

        /// <summary>

        /// KO region boyutlarını okur (root node'un region'ı).

        /// </summary>

        private (int width, int height) GetKORegion(GameObject obj)

        {

            var rt = obj.GetComponent<RectTransform>();

            if (rt == null) return (0, 0);

            return ((int)rt.sizeDelta.x, (int)rt.sizeDelta.y);

        }

        // ================================================

        // Anchor-Based Panel Positioning (Mobil Uyum)

        // ================================================

        /// <summary>

        /// Panel anchor noktalarını tanımlar.

        /// Mobil ekranlarda farklı aspect ratio'lara uyum sağlar.

        /// matchWidthOrHeight=1.0 ile yükseklik sabit, genişlik değişken.

        /// </summary>

        /// <summary>

        /// C++ birebir: CN3UIBase::SetPos(int x, int y) (N3UIBase.cpp:152-158)

        /// UIF loader anchor=(0,1), pivot=(0,1) ile yükler.

        /// Anchor/pivot DEĞİŞTİRİLMEZ — sadece anchoredPosition ayarlanır.

        /// C++ SetPos(x,y) = sol-üst köşeden piksel offset.

        /// Unity'de anchor=(0,1) pivot=(0,1) ile: anchoredPosition = (x, -y)

        /// </summary>

        private void SetPanelPos(GameObject obj, float x, float y)

        {

            var rt = obj.GetComponent<RectTransform>();

            if (rt == null) return;

            // Anchor/pivot'e dokunma — UIF loader'ın ayarladığı değerleri koru

            rt.anchoredPosition = new Vector2(x, -y);

        }

        /// <summary>

        /// UIF panel yüklendikten sonra TÜM direct child'ları fixed anchor (0,1) pivot (0,1)'e çevirir.

        /// C++ birebir: KO'da tüm pozisyonlar absolute piksel. Panel resize (SetRegion ile bottom uzatma)

        /// mevcut child'ları etkilemez. Unity stretch anchor'larda parent resize child'ları kaydırır.

        /// Bu fonksiyon bunu engeller.

        /// </summary>

        private void ConvertAllChildrenToFixed(GameObject panel)

        {

            var panelRT = panel.GetComponent<RectTransform>();

            if (panelRT == null) return;

            float parentW = panelRT.sizeDelta.x;

            float parentH = panelRT.sizeDelta.y;

            for (int i = 0; i < panelRT.childCount; i++)

            {

                var childRT = panelRT.GetChild(i).GetComponent<RectTransform>();

                if (childRT == null) continue;

                bool isCollapsed = Mathf.Approximately(childRT.anchorMin.x, childRT.anchorMax.x) &&

                                   Mathf.Approximately(childRT.anchorMin.y, childRT.anchorMax.y);

                float posX, posY, w, h;

                if (isCollapsed)

                {

                    // CreateString/CreateButton: collapsed anchor, pivot (0,1), sizeDelta = gerçek boyut

                    w = childRT.sizeDelta.x;

                    h = childRT.sizeDelta.y;

                    posX = parentW * childRT.anchorMin.x + childRT.anchoredPosition.x;

                    posY = parentH * (childRT.anchorMin.y - 1f) + childRT.anchoredPosition.y;

                }

                else

                {

                    // SetRectRelativeToParent: stretch anchor, offsetMin/Max = (0,0)

                    float left = parentW * childRT.anchorMin.x + childRT.offsetMin.x;

                    float right = parentW * childRT.anchorMax.x + childRT.offsetMax.x;

                    float bottom = parentH * childRT.anchorMin.y + childRT.offsetMin.y;

                    float top = parentH * childRT.anchorMax.y + childRT.offsetMax.y;

                    w = right - left;

                    h = top - bottom;

                    posX = left;

                    posY = top - parentH;

                }

                childRT.anchorMin = new Vector2(0, 1);

                childRT.anchorMax = new Vector2(0, 1);

                childRT.pivot = new Vector2(0, 1);

                childRT.sizeDelta = new Vector2(w, h);

                childRT.anchoredPosition = new Vector2(posX, posY);

            }

        }

        /// <summary>

        /// Klonlanmış template'ın RectTransform'unu zorla ayarlar.

        /// savedPos/savedSize: ConvertAllChildrenToFixed sonrası, SetParent(null) öncesi kaydedilen değerler.

        /// moveDown: C++ MoveOffset(0, i*iIH) karşılığı piksel offset.

        /// </summary>

        private void SetClonePosition(GameObject clone, Vector2 savedPos, Vector2 savedSize, float moveDown)

        {

            var rt = clone.GetComponent<RectTransform>();

            if (rt == null) return;

            rt.anchorMin = new Vector2(0, 1);

            rt.anchorMax = new Vector2(0, 1);

            rt.pivot = new Vector2(0, 1);

            rt.sizeDelta = savedSize;

            rt.anchoredPosition = savedPos - new Vector2(0, moveDown);

            rt.localScale = Vector3.one;

        }

        /// <summary>

        /// C++ birebir: CN3UIBase::SetPosCenter() (N3UIBase.cpp:160-173)

        public void SetPanelPosTrueCenter(GameObject obj)

        {

            var rt = obj.GetComponent<RectTransform>();

            if (rt == null) return;

            rt.anchorMin = new Vector2(0.5f, 0.5f);

            rt.anchorMax = new Vector2(0.5f, 0.5f);

            rt.pivot = new Vector2(0.5f, 0.5f);

            rt.anchoredPosition = Vector2.zero;

        }

        public void SetPanelPosCenter(GameObject obj)

        {

            var rt = obj.GetComponent<RectTransform>();

            if (rt == null) return;

            // KO absolute koordinat sistemi için anchor ve pivot'u sol-üst (0,1) yapıyoruz.

            rt.anchorMin = new Vector2(0, 1);

            rt.anchorMax = new Vector2(0, 1);

            rt.pivot = new Vector2(0, 1);

            var canvas = obj.GetComponentInParent<Canvas>();

            if (canvas != null && canvas.gameObject == obj)

            {

                canvas = obj.transform.parent != null ? obj.transform.parent.GetComponentInParent<Canvas>() : null;

            }

            if (canvas == null) return;

            var canvasRT = canvas.GetComponent<RectTransform>();

            float iW = canvasRT.rect.width;

            float iH = canvasRT.rect.height;

            float panelW = rt.sizeDelta.x;

            float panelH = rt.sizeDelta.y;

            float iX = (iW - panelW) / 2f;

            float iY = (iH - panelH) / 2f;

            rt.anchoredPosition = new Vector2(iX, -iY);

        }

        /// <summary>

        /// C++ birebir: CountableItemEditDlg.cpp:223-228

        /// iCX = (rc.right + rc.left) / 2; iCY = (rc.bottom + rc.top) / 2;

        /// SetPos(iCX - thisW/2, iCY - thisH/2);

        /// Bir paneli başka bir panelin merkezine konumlandırır.

        /// </summary>

        public void CenterPanelOnPanel(GameObject panel, GameObject callerPanel)

        {

            var rt = panel.GetComponent<RectTransform>();

            var callerRT = callerPanel.GetComponent<RectTransform>();

            if (rt == null || callerRT == null) return;

            // Set anchors and pivot to center to ensure perfect alignment

            rt.anchorMin = new Vector2(0.5f, 0.5f);

            rt.anchorMax = new Vector2(0.5f, 0.5f);

            rt.pivot = new Vector2(0.5f, 0.5f);

            // Center the panel robustly in world space to handle mismatched anchors and pivots

            var corners = new Vector3[4];

            callerRT.GetWorldCorners(corners);

            Vector3 center = (corners[0] + corners[2]) / 2f;

            rt.position = center;

        }

        /// <summary>

        /// C++ birebir: GameProcMain.cpp:4056 — SetPos(iW - (rc.right - rc.left), 10)

        /// Paneli ekranın sağ kenarına yaslar.

        /// Anchor/pivot değiştirilmez — KO koordinat sistemi sol-üst orijin (0,1).

        /// </summary>

        private void SetPanelPosRightCenter(GameObject obj)

        {

            var rt = obj.GetComponent<RectTransform>();

            if (rt == null) return;

            rt.anchorMin = new Vector2(1, 0.5f);

            rt.anchorMax = new Vector2(1, 0.5f);

            rt.pivot = new Vector2(1, 0.5f);

            rt.anchoredPosition = new Vector2(-50f, 0); // Eski konumuna geri getirildi

        }

        private void SetPanelPosLeftCenter(GameObject obj)

        {

            var rt = obj.GetComponent<RectTransform>();

            if (rt == null) return;

            rt.anchorMin = new Vector2(0, 0.5f);

            rt.anchorMax = new Vector2(0, 0.5f);

            rt.pivot = new Vector2(0, 0.5f);

            rt.anchoredPosition = new Vector2(50f, 0f);

        }

        private void SetPanelPosRight(GameObject obj, float offsetY = 10f)

        {

            var rt = obj.GetComponent<RectTransform>();

            if (rt == null) return;

            // C++ birebir: SetPos(iW - panelW, offsetY) — sağa yasla

            // Unity: anchor=(1,1) right-top, pivot=(1,1) → sağ kenara yapışır

            // anchoredPosition.x = 0 → tam sağ kenar, negatif → içeri çeker

            rt.anchorMin = new Vector2(1, 1); // right-top

            rt.anchorMax = new Vector2(1, 1);

            rt.pivot = new Vector2(1, 1);     // sağ-üst köşe

            rt.anchoredPosition = new Vector2(0, -offsetY);

        }

        // ================================================

        // Cmd Bar Buton Binding

        // C++ referans: UICmd.cpp ReceiveMessage()

        // ================================================

        private void BindCmdBarButtons(Transform cmdRoot)

        {

            // Tüm Button component'lerini tara

            var buttons = cmdRoot.GetComponentsInChildren<Button>(true);

            foreach (var btn in buttons)

            {

                string btnName = btn.gameObject.name;

                // C++ UICmd.cpp satır 47-66 GetChildByID eşleştirmesi

                switch (btnName)

                {

                    case "btn_inventory":

                        btn.onClick.AddListener(ToggleInventory);

                        break;

                    case "btn_character":

                        btn.onClick.AddListener(ToggleCharacterInfo);

                        break;

                    case "btn_skill":

                        btn.onClick.AddListener(ToggleSkillTree);

                        break;

                    case "btn_exit":
                        btn.onClick.AddListener(() => ShowExitMenu(true));
                        break;

                    case "btn_option":

                        // C++: CommandToggleCmdList — option/command listesi

                        btn.onClick.AddListener(ToggleCmdList);

                        break;

                    case "btn_map":

                        btn.onClick.AddListener(ToggleZoneMap);

                        break;

                    case "btn_control":

                        btn.onClick.AddListener(SendTradeRequestToTarget);

                        break;

                    case "btn_sit":

                    case "btn_stand":

                        btn.onClick.AddListener(ToggleSitStand);

                        break;

                    case "btn_attack":

                        btn.onClick.AddListener(ToggleAutoAttack);

                        break;

                    case "btn_walk":

                    case "btn_run":

                        btn.onClick.AddListener(ToggleWalkRun);

                        break;

                    case "btn_invite":

                        btn.onClick.AddListener(SendPartyInviteToTarget);

                        break;

                    case "btn_disband":

                        btn.onClick.AddListener(SendPartyLeaveRequest);

                        break;

                    case "btn_camera":

                        break;

                    case "btn_pm":

                        btn.onClick.AddListener(() => {

                            KOWhisperManager.Instance?.ShowWhisperDirectory();

                        });

                        break;

                    case "btn_town":

                        btn.onClick.AddListener(() => {

                            ParseChattingCommand("/town");

                        });

                        break;

                    default:

                        break;

                }

            }

        }

        private void SendTradeRequestToTarget()

        {

            var gm = EntropyOnline.Core.GameManager.Instance;

            if (gm == null || gm.TargetId < 0)

            {

                AddMsgOutput("Please select a target first.", D3DColorToUnity(0xffffff00));

                return;

            }

            var entityMgr = EntropyOnline.World.EntityManager.Instance;

            if (entityMgr == null) return;

            var tradeTarget = entityMgr.GetRemotePlayer(gm.TargetId);

            if (tradeTarget == null)

            {

                AddMsgOutput("You can only trade with other players.", D3DColorToUnity(0xffffff00));

                return;

            }

            if (EntropyOnline.Trade.KOTradeManager.Instance != null)

            {

                EntropyOnline.Trade.KOTradeManager.Instance.SendExchangeReq((short)gm.TargetId);

            }

            AddMsgOutput($"Requesting trade with {tradeTarget.Name ?? "target"}...", D3DColorToUnity(0xffffff00));

            if (KOMessageBox.Instance != null)

            {

                System.Action onReject = null;

                System.Action onOpen = null;

                System.Action onClose = null;

                onReject = () => {

                    KOMessageBox.Instance.Hide();

                    CleanupEvents();

                };

                onOpen = () => {

                    KOMessageBox.Instance.Hide();

                    CleanupEvents();

                };

                onClose = () => {

                    KOMessageBox.Instance.Hide();

                    CleanupEvents();

                };

                void CleanupEvents() {

                    if (EntropyOnline.Trade.KOTradeManager.Instance != null)

                    {

                        EntropyOnline.Trade.KOTradeManager.Instance.OnTradeRejected -= onReject;

                        EntropyOnline.Trade.KOTradeManager.Instance.OnTradeWindowOpen -= onOpen;

                        EntropyOnline.Trade.KOTradeManager.Instance.OnTradeWindowClose -= onClose;

                    }

                }

                if (EntropyOnline.Trade.KOTradeManager.Instance != null)

                {

                    EntropyOnline.Trade.KOTradeManager.Instance.OnTradeRejected += onReject;

                    EntropyOnline.Trade.KOTradeManager.Instance.OnTradeWindowOpen += onOpen;

                    EntropyOnline.Trade.KOTradeManager.Instance.OnTradeWindowClose += onClose;

                }

                string szTitle = "Trade Proposal";

                string szMsg = $"Waiting for {tradeTarget.Name ?? "target"} to accept the trade...";

                KOMessageBox.Instance.Show(

                    szMsg,

                    szTitle,

                    MsgBoxStyle.MB_CANCEL,

                    MsgBoxBehavior.BEHAVIOR_NOTHING,

                    onNo: () =>

                    {

                        if (EntropyOnline.Trade.KOTradeManager.Instance != null)

                        {

                            EntropyOnline.Trade.KOTradeManager.Instance.SendExchangeCancel();

                        }

                        CleanupEvents();

                    },

                    callerPanel: null,

                    countdownDuration: 30,

                    forceFixedCenter: true,

                    autoClickOnTimeout: true

                );

            }

        }

        private void SendPartyInviteToTarget()

        {

            var gm = EntropyOnline.Core.GameManager.Instance;

            if (gm == null || gm.TargetId < 0)

            {

                AddMsgOutput("Please select a target first.", D3DColorToUnity(0xffffff00));

                return;

            }

            if (PartyUI.Instance != null)

            {

                PartyUI.Instance.SendPartyInvite(gm.TargetId);

            }

        }

        private void SendPartyLeaveRequest()

        {

            if (PartyUI.Instance != null)

            {

                PartyUI.Instance.SendPartyLeave();

            }

        }

        private void ToggleSitStand()

        {

            var pc = FindAnyObjectByType<EntropyOnline.Character.PlayerController>();

            if (pc == null) return;

            if (pc.State() == EntropyOnline.Character.PlayerStateAction.PSA_SITDOWN)

            {

                pc.Action(EntropyOnline.Character.PlayerStateAction.PSA_BASIC, true);

            }

            else

            {

                pc.Action(EntropyOnline.Character.PlayerStateAction.PSA_SITDOWN);

            }

        }

        private void ToggleAutoAttack()

        {

            var pc = FindAnyObjectByType<EntropyOnline.Character.PlayerController>();

            if (pc == null) return;

            if (pc.IsAutoAttacking)

            {

                pc.StopAutoAttack();

                return;

            }

            var gm = EntropyOnline.Core.GameManager.Instance;

            if (gm == null || gm.TargetId < 0)

            {

                AddMsgOutput("Please select a target first.", D3DColorToUnity(0xffffff00));

                return;

            }

            var target = EntropyOnline.World.KOTargetSelector.Instance?.SelectedEntity;

            if (target == null) return;

            pc.StartAutoAttack(target);

        }

        private void ToggleWalkRun()

        {

            var pc = FindAnyObjectByType<EntropyOnline.Character.PlayerController>();

            if (pc == null) return;

            if (pc.StateMove() == EntropyOnline.Character.PlayerStateMove.PSM_RUN)

            {

                pc.ActionMove(EntropyOnline.Character.PlayerStateMove.PSM_WALK);

            }

            else

            {

                pc.ActionMove(EntropyOnline.Character.PlayerStateMove.PSM_RUN);

            }

        }

        // ================================================

