        private void FindProgressBars(Transform root)

        {

            var fills = root.GetComponentsInChildren<KOProgressFill>(true);

            foreach (var fill in fills)

            {

                string parentName = fill.transform.parent != null ?

                    fill.transform.parent.gameObject.name : "";

                if (parentName == "Progress_HP")

                {

                    _hpFill = fill;

                }

                else if (parentName == "Progress_MSP")

                {

                    _mpFill = fill;

                }

                else if (parentName == "Progress_ExpC" || parentName == "Progress_ExpP")

                {

                    if (_expFill == null)

                    {

                        _expFill = fill;

                    }

                }

            }

        }

