        /// <summary>

        /// Transaction panel butonlarını ve başlık image'larını bağlar.

        /// C++ referans: UITransactionDlg.cpp InitIconWnd() satır 190-218

        /// ShowTitle() satır 1654-1672: img_inn/img_blacksmith/img_store arasında geçiş

        /// </summary>

        private GameObject _imgInn, _imgBlacksmith, _imgStore;

        private void BindTransactionButtons(Transform root)

        {

            // C++ UITransactionDlg.cpp birebir: Btn_Buy → seçili NPC item'ı satın al

            var btnBuy = KOUIRenderer.FindChildButton(root, "Btn_Buy");

            if (btnBuy != null)

            {

                btnBuy.onClick.AddListener(() =>

                {

                    if (_selectedShopItemIndex >= 0 && _currentShopItems != null &&

                        _selectedShopItemIndex < _currentShopItems.Length)

                    {

                        var item = _currentShopItems[_selectedShopItemIndex];

                        // C++ birebir: SendToServerBuyMsg (UITransactionDlg.cpp:775-788)

                        // İlk boş veya eşleşen inventory slot'unu bul

                        int destSlot = GetTradeInvDestinationIndex(item.ItemDefId, item.ByContable);

                        if (destSlot < 0)

                        {

                            Debug.LogWarning("[KOUIMGR] Btn_Buy: envanter dolu!");

                            return;

                        }

                        var shopUI = ShopUI.Instance;

                        if (shopUI != null)

                        {

                            SetShopPendingInfo(true, item.ItemDefId, destSlot, _shopNpcId, _shopTradeId, 1);

                            shopUI.BuyItem(_shopTradeId, (byte)destSlot, (uint)item.ItemDefId, 1);

                            ApplyPendingTradeToInventory();

                            RefreshShopInventory();

                        }

                    }

                });

            }

            // Open-KO birebir: UITransactionDlg.cpp satır 1732:

            // N3_VERIFY_UI_COMPONENT(m_pBtnClose, GetChildByID<CN3UIButton>("btn_close"));

            var btnClose = KOUIRenderer.FindChildButton(root, "btn_close");

            if (btnClose != null)

            {

                // Open-KO birebir: satır 1479-1480:

                // if (pSender == m_pBtnClose) LeaveTransactionState();

                btnClose.onClick.AddListener(() => ShowTransaction(false));

            }

            // C++ UITransactionDlg.cpp InitIconWnd() satır 215-217:

            // N3_VERIFY_UI_COMPONENT(m_pUIInn, GetChildByID<CN3UIImage>("img_inn"));

            // N3_VERIFY_UI_COMPONENT(m_pUIBlackSmith, GetChildByID<CN3UIImage>("img_blacksmith"));

            // N3_VERIFY_UI_COMPONENT(m_pUIStore, GetChildByID<CN3UIImage>("img_store"));

            var innTr = KOUIRenderer.FindChildByID(root, "img_inn");

            _imgInn = innTr != null ? innTr.gameObject : null;

            var bsTr = KOUIRenderer.FindChildByID(root, "img_blacksmith");

            _imgBlacksmith = bsTr != null ? bsTr.gameObject : null;

            var storeTr = KOUIRenderer.FindChildByID(root, "img_store");

            _imgStore = storeTr != null ? storeTr.gameObject : null;

            // C++ ShowTitle() birebir: başlangıçta hepsini gizle

            if (_imgInn != null) _imgInn.SetActive(false);

            if (_imgBlacksmith != null) _imgBlacksmith.SetActive(false);

            if (_imgStore != null) _imgStore.SetActive(false);

            // Tasarım özgünleştirme: Paneli modern dolgulu temaya geçir

            ModernizeTransactionPanel(root);

        }

        /// <summary>

        /// Open-KO birebir: UITransactionDlg.cpp ShowTitle() satır 1654-1672

        /// tradeID / 1000 değerine göre başlık image'ını seçer.

        /// EnterTransactionState() satır 403-413:

        ///   case 122/222: ShowTitle(UI_BLACKSMITH)

        ///   default:      ShowTitle(UI_STORE)

        /// </summary>

        private void ShowTransactionTitle(int tradeId)

        {

            // C++ ShowTitle birebir: hepsini gizle

            if (_imgInn != null) _imgInn.SetActive(false);

            if (_imgBlacksmith != null) _imgBlacksmith.SetActive(false);

            if (_imgStore != null) _imgStore.SetActive(false);

            // C++ EnterTransactionState satır 403-413

            int sellGroup = tradeId / 1000;

            switch (sellGroup)

            {

                case 122:

                case 222:

                    if (_imgBlacksmith != null) _imgBlacksmith.SetActive(true);

                    break;

                default:

                    if (_imgStore != null) _imgStore.SetActive(true);

                    break;

            }

            // Tasarım özgünleştirme: Başlık yazısını dinamik güncelle (NPC ismi yazdır)

            if (_uiTransaction != null)

            {

                var titleObj = _uiTransaction.transform.Find("StoreTitle")?.gameObject;

                if (titleObj != null)

                {

                    var txt = titleObj.GetComponent<Text>();

                    if (txt != null)

                    {

                        string npcName = null;

                        var em = EntropyOnline.World.EntityManager.Instance;

                        if (em != null && _shopNpcId != 0)

                        {

                            npcName = em.GetEntityName(_shopNpcId);

                        }

                        if (string.IsNullOrEmpty(npcName))

                        {

                            var gm = EntropyOnline.Core.GameManager.Instance;

                            if (gm != null)

                            {

                                npcName = gm.TargetName;

                            }

                        }

                        if (!string.IsNullOrEmpty(npcName))

                        {

                            txt.text = npcName;

                        }

                        else

                        {

                            if (sellGroup == 122 || sellGroup == 222)

                                txt.text = "EXCHANGE / REPAIR";

                            else

                                txt.text = "STORE";

                        }

                    }

                }

            }

        }

        /// <summary>

        /// Sunucudan gelen shop item'larını panele doldurur.

        /// C++ referans: UITransactionDlg.cpp EnterTransactionState() satır 305-371

        /// InitIconUpdate() satır 221-247: CN3UIIcon + SetTex(szIconFN) + SetUVRect(0,0,45/64,45/64)

        /// GetChildAreaByiOrder(UI_AREA_TYPE_TRADE_NPC, i) ile area'lara yerleştirir.

        /// </summary>

        public void PopulateShopList(int npcId, int tradeId, ShopItemData[] items)

        {

            if (_uiTransaction == null) return;

            _shopNpcId = npcId;

            _currentShopItems = items;

            _selectedShopItemIndex = -1;

            _shopCurrentPage = 0;

            _shopTradeId = tradeId;

            // Open-KO birebir: EnterTransactionState (UITransactionDlg.cpp:403-413)

            ShowTransactionTitle(tradeId);

            // Sayfa butonlarını bağla

            BindShopPageButtons();

            // İlk sayfayı göster

            ShowShopPage(0);

            // C++ birebir: UITransactionDlg.cpp:399 — ItemMoveFromInvToThis()

            // Önce m_pMyInvWnd'den m_pMyTradeInv'ye taşı, SONRA UI'ı doldur

            ItemMoveFromInvToThis();

            PopulateShopInventory();

        }

        // Open-KO birebir: GameDef.h:1248-1249

        private const int MAX_ITEM_TRADE = 24;       // sayfa başı item

        private const int MAX_ITEM_TRADE_PAGE = 12;   // maks sayfa

        // C++ birebir: N3UIArea.h:18 — UI_AREA_TYPE_TRADE_NPC = 3

        private const int UI_AREA_TYPE_TRADE_NPC = 3;

        // C++ birebir: N3UIArea.h:24 — UI_AREA_TYPE_TRADE_MY = 11

        private const int UI_AREA_TYPE_TRADE_MY_SHOP = 11;

        private int _shopCurrentPage = 0;

        private int _shopTradeId = 0;

        private readonly List<GameObject> _shopInvItems = new();

        public bool IsMultipleSellingActive { get; private set; } = false;

        private readonly HashSet<int> _selectedSellSlots = new HashSet<int>();

        private int _totalSelectedSellAmount = 0;

        /// <summary>

        /// C++ birebir: UITransactionDlg::ItemMoveFromInvToThis() (UITransactionDlg.cpp:450-477)

        /// Envanter item'larını shop panelinin TRADE_MY area'larına yerleştirir.

        /// </summary>

        private void PopulateShopInventory()

        {

            // Eski ikonları temizle

            foreach (var obj in _shopInvItems)

                if (obj != null) Destroy(obj);

            _shopInvItems.Clear();

            if (_uiTransaction == null) return;

            var inv = KOInventory.Instance;

            if (inv == null) return;

            Transform root = _uiTransaction.transform;

            // C++ birebir: UITransactionDlg.cpp satır 904-914

            // Tüm TRADE_MY area'ları drop hedefi — dolu/boş fark etmez.

            // Boş slotlara da KOItemSlotHandler eklenir ki NPC'den item

            // sürükleyip bırakılabilsin.

            for (int i = 0; i < KOInventory.MAX_ITEM_INVENTORY; i++)

            {

                // C++ birebir: m_pMyTradeInv'den oku (m_pMyInvWnd yerine)

                var slot = m_pMyTradeInv[i];

                bool hasItem = slot != null && !m_pMyTradeInvHidden[i];

                // C++ satır 468: GetChildAreaByiOrder(UI_AREA_TYPE_TRADE_MY, i)

                var areaRT = KOUIRenderer.FindChildAreaByiOrder(root, UI_AREA_TYPE_TRADE_MY_SHOP, i);

                var itemObj = new GameObject($"ShopInvItem_{i}");

                itemObj.transform.SetParent(root, false);

                var itemRT = itemObj.AddComponent<RectTransform>();

                if (areaRT != null)

                {

                    // UIF area pozisyonunu birebir kullan

                    itemRT.anchorMin = areaRT.anchorMin;

                    itemRT.anchorMax = areaRT.anchorMax;

                    itemRT.pivot = areaRT.pivot;

                    itemRT.anchoredPosition = areaRT.anchoredPosition;

                    itemRT.sizeDelta = areaRT.sizeDelta;

                }

                else

                {

                    // Fallback: panel alt kısmında grid

                    itemRT.anchorMin = new Vector2(0, 0);

                    itemRT.anchorMax = new Vector2(0, 0);

                    itemRT.pivot = new Vector2(0, 0);

                    int col = i % 7;

                    int row = i / 7;

                    itemRT.anchoredPosition = new Vector2(5f + col * 40f, 5f + row * 40f);

                    itemRT.sizeDelta = new Vector2(38f, 38f);

                }

                if (hasItem)

                {

                    // C++ birebir: GameBase.cpp:617-621

                    // pItem = s_pTbl_Items_Basic.Find(iItemID / 1000 * 1000)

                    // szIconFN = MakeIconFileName(pItem->dwIDIcon)

                    int dwIDIcon = ResolveIconId(slot.itemId);

                    var icon = KOItemIconLoader.LoadItemIcon(dwIDIcon);

                    if (icon != null)

                    {

                        var img = itemObj.AddComponent<UnityEngine.UI.Image>();

                        img.sprite = icon;

                        img.preserveAspect = true;

                        img.raycastTarget = true;

                    }

                    else

                    {

                        var img = itemObj.AddComponent<UnityEngine.UI.Image>();

                        img.color = new Color(0.3f, 0.3f, 0.3f, 0.5f);

                        img.raycastTarget = true;

                    }

                    // ============================================================

                    // C++ birebir: UITransactionDlg.cpp Tick() satır 130-155

                    // Countable itemlerin iCount değerini göster.

                    // cpp:132-134: if (m_pMyTradeInv[i] && (byContable == COUNTABLE || byContable == COUNTABLE_SMALL))

                    // cpp:149:     pStr->SetStringAsInt(m_pMyTradeInv[i]->iCount);

                    // ============================================================

                    byte byContableCheck = 0;

                    byte byAttachPointCheck = 0;

                    if (KOInventory.s_pTbl_Items_Basic != null &&

                        KOInventory.s_pTbl_Items_Basic.TryGetValue((uint)(slot.itemId / 1000 * 1000), out var basicCount))

                    {

                        byContableCheck = basicCount.byContable;

                        byAttachPointCheck = basicCount.byAttachPoint;

                    }

                    int displayCount = slot.count;

                    bool showCount = false;

                    if (byContableCheck == 1 || byContableCheck == 2)

                    {

                        showCount = true;

                    }

                    else if (byAttachPointCheck == 15 && slot.durability > 1)

                    {

                        displayCount = slot.durability;

                        showCount = true;

                    }

                    if (showCount)

                    {

                        var countObj = new GameObject("CountText");

                        countObj.transform.SetParent(itemObj.transform, false);

                        var countRT = countObj.AddComponent<RectTransform>();

                        countRT.anchorMin = new Vector2(1, 0);

                        countRT.anchorMax = new Vector2(1, 0);

                        countRT.pivot = new Vector2(1, 0);

                        countRT.anchoredPosition = new Vector2(-2, 2);

                        countRT.sizeDelta = new Vector2(30, 12);

                        var countText = countObj.AddComponent<UnityEngine.UI.Text>();

                        countText.text = displayCount.ToString();

                        countText.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");

                        countText.fontSize = 9;

                        countText.color = Color.white;

                        countText.alignment = TextAnchor.LowerRight;

                        countText.raycastTarget = false;

                    }

                }

                else

                {

                    // Boş slot — şeffaf ama raycast target (drop hedefi)

                    var img = itemObj.AddComponent<UnityEngine.UI.Image>();

                    img.color = new Color(0, 0, 0, 0); // Tamamen şeffaf

                    img.raycastTarget = true; // Drop hedefi olarak çalışsın

                }

                // İsim lookup

                string itemName = "";

                if (hasItem && KOInventory.s_pTbl_Items_Basic != null &&

                    KOInventory.s_pTbl_Items_Basic.TryGetValue((uint)slot.itemId, out var basicName))

                    itemName = basicName.szName ?? $"Item #{slot.itemId}";

                // C++ birebir: ShopInvSlot — envanter slot'u (dolu/boş)

                var handler = itemObj.AddComponent<KOItemSlotHandler>();

                handler.slotType = KOItemSlotHandler.SlotType.ShopInvSlot;

                handler.slotIndex = i;

                if (hasItem)

                {

                    handler.itemData = new InventoryItemData

                    {

                        ItemDefId = slot.itemId,

                        StackCount = (short)slot.count,

                        Durability = (short)slot.durability,

                        SlotIndex = (byte)i,

                        Name = itemName

                    };

                    handler.tooltipItemDefId = slot.itemId;

                    handler.tooltipShowPrice = true;

                    handler.tooltipIsBuy = false; // Sell price

                    handler.shopNpcId = _shopNpcId;

                    handler.shopTradeId = _shopTradeId;

                    handler.shopItemCount = slot.count;

                    // ByContable bilgisini set et

                    byte byContable = 0;

                    if (KOInventory.s_pTbl_Items_Basic != null &&

                        KOInventory.s_pTbl_Items_Basic.TryGetValue((uint)slot.itemId, out var basicInfo))

                        byContable = basicInfo.byContable;

                    handler.shopByContable = byContable;

                }

                else

                {

                    handler.tooltipItemDefId = 0;

                    handler.shopNpcId = _shopNpcId;

                    handler.shopTradeId = _shopTradeId;

                }

                // Shop inv slot'lara KOItemDragDrop ekle — drag-drop ile satış

                if (itemObj.GetComponent<KOItemDragDrop>() == null)

                    itemObj.AddComponent<KOItemDragDrop>();

                // Tasarım özgünleştirme: Çoklu satışta seçilmişse kırmızı çerçeve ve SELECTED yazısı ekle

                if (hasItem && _selectedSellSlots.Contains(i))

                {

                    var highlightObj = new GameObject("MultipleSellHighlight", typeof(RectTransform));

                    highlightObj.transform.SetParent(itemObj.transform, false);

                    var hlRT = highlightObj.GetComponent<RectTransform>();

                    if (hlRT != null)

                    {

                        hlRT.anchorMin = Vector2.zero;

                        hlRT.anchorMax = Vector2.one;

                        hlRT.offsetMin = Vector2.zero;

                        hlRT.offsetMax = Vector2.zero;

                    }

                    var hlImg = highlightObj.AddComponent<Image>();

                    hlImg.sprite = GetSkillThemeRoundedRectSprite("sell_highlight_red", 48, 48, 0,

                        new Color(0f, 0f, 0f, 0f),

                        new Color(0.9f, 0.1f, 0.1f, 0.95f),

                        2);

                    hlImg.raycastTarget = false;

                    // Kırmızı SELECTED Şeridi (SelectedBanner)

                    var bannerObj = new GameObject("SelectedBanner", typeof(RectTransform));

                    bannerObj.transform.SetParent(highlightObj.transform, false);

                    var bRT = bannerObj.GetComponent<RectTransform>();

                    if (bRT != null)

                    {

                        bRT.anchorMin = new Vector2(0f, 1f);

                        bRT.anchorMax = new Vector2(1f, 1f);

                        bRT.pivot = new Vector2(0.5f, 1f);

                        bRT.anchoredPosition = Vector2.zero;

                        bRT.sizeDelta = new Vector2(0f, 10f);

                    }

                    var bImg = bannerObj.AddComponent<Image>();

                    bImg.color = new Color(0.9f, 0.1f, 0.1f, 1f);

                    bImg.raycastTarget = false;

                    // SELECTED Metni (Text)

                    var txtObj = new GameObject("Text", typeof(RectTransform));

                    txtObj.transform.SetParent(bannerObj.transform, false);

                    var txtRT = txtObj.GetComponent<RectTransform>();

                    if (txtRT != null)

                    {

                        txtRT.anchorMin = Vector2.zero;

                        txtRT.anchorMax = Vector2.one;

                        txtRT.offsetMin = Vector2.zero;

                        txtRT.offsetMax = Vector2.zero;

                    }

                    var txt = txtObj.AddComponent<Text>();

                    txt.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");

                    txt.text = "SELECTED";

                    txt.color = Color.white;

                    txt.fontStyle = FontStyle.Bold;

                    txt.fontSize = 7;

                    txt.alignment = TextAnchor.MiddleCenter;

                    txt.raycastTarget = false;

                }

                _shopInvItems.Add(itemObj);

            }

        }

        /// <summary>

        /// C++ birebir: Trade success sonrası shop envanter UI güncelleme.

        /// UITransactionDlg::ItemMoveFromInvToThis/ItemMoveFromThisToInv sonrası

        /// envanter ikonları güncellenir.

        /// </summary>

        public void RefreshShopInventory()

        {

            if (_uiTransaction == null || !_uiTransaction.activeSelf) return;

            PopulateShopInventory();

        }

        /// <summary>Shop (transaction) dialog'u açık mı?</summary>

        public bool IsTransactionActive() => _uiTransaction != null && _uiTransaction.activeSelf;

        /// <summary>

        /// C++ birebir: UITransactionDlg.cpp ReceiveIconDrop (buy: cpp:1072-1096)

        /// ve ItemCountOK (buy: cpp:628-666, sell: cpp:687-695)

        /// Item lokal olarak m_pMyTradeInv'ye eklenir/çıkarılır.

        /// </summary>

        public void ApplyPendingTradeToInventory()

        {

            if (_shopPendingIsBuy)

            {

                // C++ birebir buy: m_pMyTradeInv'ye ekle

                int slotIdx = _shopPendingSlotIndex;

                if (slotIdx < 0 || slotIdx >= KOInventory.MAX_ITEM_INVENTORY)

                {

                    // İlk boş m_pMyTradeInv slot'u bul

                    for (int i = 0; i < KOInventory.MAX_ITEM_INVENTORY; i++)

                    {

                        if (m_pMyTradeInv[i] == null) { slotIdx = i; break; }

                    }

                }

                if (slotIdx >= 0 && slotIdx < KOInventory.MAX_ITEM_INVENTORY)

                {

                    var existing = m_pMyTradeInv[slotIdx];

                    if (existing != null && existing.itemId == _shopPendingItemDefId)

                    {

                        // C++ birebir: cpp:631 — m_pMyTradeInv[destSlot]->iCount += iGold

                        existing.count += _shopPendingAmount;

                    }

                    else

                    {

                        // C++ birebir: cpp:1072-1078 — yeni spItemNew oluştur

                        var pItem = KOTableReader.FindItemBasic(KOInventory.s_pTbl_Items_Basic, _shopPendingItemDefId);

                        m_pMyTradeInv[slotIdx] = new KOInventory.ItemSlot

                        {

                            itemId      = _shopPendingItemDefId,

                            count       = _shopPendingAmount,

                            durability  = (pItem != null) ? (int)pItem.siMaxDurability : 1000,

                            attachPoint = (pItem != null) ? pItem.byAttachPoint : 0,

                            itemClass   = (pItem != null) ? pItem.byClass : 0,

                            iconFN      = (pItem != null) ? pItem.dwIDIcon.ToString() : ""

                        };

                    }

                    // Güncel slot index'i kaydet (revert için)

                    _shopPendingSlotIndex = slotIdx;

                }

                else

                {

                    Debug.LogWarning("[KOUIMGR] ApplyPendingTrade BUY: m_pMyTradeInv dolu!");

                }

            }

            else

            {

                // C++ birebir sell: m_pMyTradeInv'de azalt veya gizle

                int slotIdx = _shopPendingSlotIndex;

                if (slotIdx >= 0 && slotIdx < KOInventory.MAX_ITEM_INVENTORY)

                {

                    var existing = m_pMyTradeInv[slotIdx];

                    if (existing != null && existing.itemId == _shopPendingItemDefId)

                    {

                        if ((existing.count - _shopPendingAmount) > 0)

                        {

                            // C++ birebir: cpp:690 — spItem->iCount -= iGold

                            existing.count -= _shopPendingAmount;

                        }

                        else

                        {

                            // C++ birebir: cpp:694 — spItem->pUIIcon->SetVisible(false)

                            m_pMyTradeInvHidden[slotIdx] = true;

                        }

                    }

                }

            }

        }

        /// <summary>

        /// C++ birebir: s_sRecoveryJobInfo — pending trade bilgisini kaydet.

        /// Non-countable buy/sell için KOItemDragDrop'tan çağrılır.

        /// </summary>

        public void SetShopPendingInfo(bool isBuy, int itemDefId, int slotIndex,

            int npcId, int tradeId, int amount)

        {

            _shopPendingIsBuy = isBuy;

            _shopPendingItemDefId = itemDefId;

            _shopPendingSlotIndex = slotIndex;

            _shopPendingNpcId = npcId;

            _shopPendingTradeId = tradeId;

            _shopPendingAmount = amount;

        }

        /// <summary>

        /// C++ birebir: UITransactionDlg.cpp ReceiveResultTradeFromServer

        /// Buy fail: cpp:1200-1246 — m_pMyTradeInv'den sil.

        /// Sell fail: cpp:1267-1294 — m_pMyTradeInv'de geri göster.

        /// </summary>

        public void RevertPendingTradeFromInventory()

        {

            if (_shopPendingIsBuy)

            {

                // C++ birebir: cpp:1200-1246 — Buy fail → m_pMyTradeInv'den sil

                int slotIdx = _shopPendingSlotIndex;

                if (slotIdx >= 0 && slotIdx < KOInventory.MAX_ITEM_INVENTORY)

                {

                    var existing = m_pMyTradeInv[slotIdx];

                    if (existing != null && existing.itemId == _shopPendingItemDefId)

                    {

                        existing.count -= _shopPendingAmount;

                        if (existing.count <= 0)

                        {

                            // C++ birebir: cpp:1213-1216 — m_pMyTradeInv[..] = nullptr

                            m_pMyTradeInv[slotIdx] = null;

                        }

                        else

                        {

                            // C++ birebir: cpp:1208 — iCount -= iGold

                        }

                    }

                }

            }

            else

            {

                // C++ birebir: cpp:1267-1294 — Sell fail → geri göster

                int slotIdx = _shopPendingSlotIndex;

                if (slotIdx >= 0 && slotIdx < KOInventory.MAX_ITEM_INVENTORY)

                {

                    var existing = m_pMyTradeInv[slotIdx];

                    if (existing != null)

                    {

                        if (m_pMyTradeInvHidden[slotIdx])

                        {

                            // C++ birebir: cpp:1282-1285 veya cpp:1292

                            // SetVisible(true) — geri göster

                            m_pMyTradeInvHidden[slotIdx] = false;

                        }

                        else

                        {

                            // C++ birebir: cpp:1277 — iCount += iGold

                            existing.count += _shopPendingAmount;

                        }

                    }

                }

            }

        }

        /// <summary>

        /// Open-KO birebir: UITransactionDlg.cpp satır 379-397

        /// Belirli sayfadaki item'ları gösterir. Area pozisyonlarını kullanır.

        /// </summary>

        private void ShowShopPage(int page)

        {

            // Eski item objelerini temizle

            foreach (var item in _shopListItems)

                if (item != null) Destroy(item);

            _shopListItems.Clear();

            if (_currentShopItems == null) return;

            int totalPages = (_currentShopItems.Length + MAX_ITEM_TRADE - 1) / MAX_ITEM_TRADE;

            if (page < 0) page = 0;

            if (page >= totalPages) page = totalPages - 1;

            _shopCurrentPage = page;

            int startIdx = page * MAX_ITEM_TRADE;

            int endIdx = Mathf.Min(startIdx + MAX_ITEM_TRADE, _currentShopItems.Length);

            Transform root = _uiTransaction.transform;

            // Sayfa numarasını güncelle

            var pageStr = KOUIRenderer.FindChildByID(root, "string_page");

            if (pageStr != null)

            {

                var pageText = pageStr.GetComponent<Text>();

                if (pageText != null) pageText.text = (page + 1).ToString();

            }

            for (int i = startIdx; i < endIdx; i++)

            {

                var entry = _currentShopItems[i];

                if (entry == null || entry.ItemDefId == 0 || string.IsNullOrEmpty(entry.Name) || entry.Name.Trim() == "")
                {
                    _shopListItems.Add(null);
                    continue;
                }

                int slotIdx = i - startIdx; // 0..23 arası slot indeksi

                // C++ birebir: GetChildAreaByiOrder(UI_AREA_TYPE_TRADE_NPC, slotIdx)

                var areaRT = KOUIRenderer.FindChildAreaByiOrder(root, UI_AREA_TYPE_TRADE_NPC, slotIdx);

                var itemObj = new GameObject($"ShopItem_{i}");

                itemObj.transform.SetParent(root, false);

                var itemRT = itemObj.AddComponent<RectTransform>();

                if (areaRT != null)

                {

                    // UIF area pozisyonunu birebir kullan

                    itemRT.anchorMin = areaRT.anchorMin;

                    itemRT.anchorMax = areaRT.anchorMax;

                    itemRT.pivot = areaRT.pivot;

                    itemRT.anchoredPosition = areaRT.anchoredPosition;

                    itemRT.sizeDelta = areaRT.sizeDelta;

                }

                else

                {

                    // Fallback: grid hesapla

                    itemRT.anchorMin = new Vector2(0, 1);

                    itemRT.anchorMax = new Vector2(0, 1);

                    itemRT.pivot = new Vector2(0, 1);

                    int col = slotIdx % 6;

                    int row = slotIdx / 6;

                    itemRT.anchoredPosition = new Vector2(5f + col * 48f, -5f - row * 48f);

                    itemRT.sizeDelta = new Vector2(45f, 45f);

                }

                // C++ MakeResrcFileNameForUPC: pItem->dwIDIcon → ikon dosya adı

                int dwIDIcon = 0;

                if (!string.IsNullOrEmpty(entry.IconId))

                    int.TryParse(entry.IconId, out dwIDIcon);

                var icon = KOItemIconLoader.LoadItemIcon(dwIDIcon);

                if (icon != null)

                {

                    var img = itemObj.AddComponent<UnityEngine.UI.Image>();

                    img.sprite = icon;

                    img.preserveAspect = true;

                    img.raycastTarget = true;

                }

                else

                {

                    var img = itemObj.AddComponent<UnityEngine.UI.Image>();

                    img.color = new Color(0.3f, 0.3f, 0.3f, 0.5f);

                }

                // C++ birebir: UITransactionDlg.cpp — shop item slot interaction

                // single-tap = tooltip, double-tap = buy

                var shopHandler = itemObj.AddComponent<KOItemSlotHandler>();

                shopHandler.slotType = KOItemSlotHandler.SlotType.ShopNpcSlot;

                shopHandler.slotIndex = slotIdx;

                shopHandler.tooltipItemDefId = entry.ItemDefId;

                shopHandler.tooltipShowPrice = true;

                shopHandler.tooltipIsBuy = true;

                shopHandler.shopNpcId = _shopNpcId;

                shopHandler.shopTradeId = _shopTradeId;

                shopHandler.shopByContable = entry.ByContable; // C++ pItemBasic->byContable

                // Shop slot'lara KOItemDragDrop ekle — drag-drop ile alım/satım

                if (itemObj.GetComponent<KOItemDragDrop>() == null)

                    itemObj.AddComponent<KOItemDragDrop>();

                _shopListItems.Add(itemObj);

            }

            // ============================================================

            // C++ birebir: UITransactionDlg::ReceiveIconDrop (satır 873-900)

            // C++'da drop kontrolü AREA bazlı — UI_AREA_TYPE_TRADE_NPC alanının

            // tamamına düşen drop → sell/buy tetikler. Tek tek ikon değil.

            // Unity karşılığı: NPC alanını kaplayan arka plan drop zone.

            // SetAsFirstSibling ile item slot'larının ARKASINA yerleştir,

            // böylece önce gerçek slot'lar kontrol edilir, onlara çarpmazsa

            // bu catch-all zone devreye girer.

            // ============================================================

            var npcDropZone = new GameObject("ShopNpcDropZone");

            npcDropZone.transform.SetParent(root, false);

            npcDropZone.transform.SetAsFirstSibling(); // En arkada — diğer slot'lar öncelikli

            var dzRT = npcDropZone.AddComponent<RectTransform>();

            // NPC area'larının kapladığı bölgeyi bul

            var firstArea = KOUIRenderer.FindChildAreaByiOrder(root, UI_AREA_TYPE_TRADE_NPC, 0);

            var lastArea = KOUIRenderer.FindChildAreaByiOrder(root, UI_AREA_TYPE_TRADE_NPC, MAX_ITEM_TRADE - 1);

            if (firstArea != null && lastArea != null)

            {

                // İlk ve son area'dan bounding box hesapla

                float minX = Mathf.Min(firstArea.anchoredPosition.x - firstArea.sizeDelta.x * firstArea.pivot.x,

                                       lastArea.anchoredPosition.x - lastArea.sizeDelta.x * lastArea.pivot.x);

                float maxX = Mathf.Max(firstArea.anchoredPosition.x + firstArea.sizeDelta.x * (1 - firstArea.pivot.x),

                                       lastArea.anchoredPosition.x + lastArea.sizeDelta.x * (1 - lastArea.pivot.x));

                float minY = Mathf.Min(firstArea.anchoredPosition.y - firstArea.sizeDelta.y * firstArea.pivot.y,

                                       lastArea.anchoredPosition.y - lastArea.sizeDelta.y * lastArea.pivot.y);

                float maxY = Mathf.Max(firstArea.anchoredPosition.y + firstArea.sizeDelta.y * (1 - firstArea.pivot.y),

                                       lastArea.anchoredPosition.y + lastArea.sizeDelta.y * (1 - lastArea.pivot.y));

                dzRT.anchorMin = firstArea.anchorMin;

                dzRT.anchorMax = firstArea.anchorMax;

                dzRT.pivot = new Vector2(0, 1);

                dzRT.anchoredPosition = new Vector2(minX, maxY);

                dzRT.sizeDelta = new Vector2(maxX - minX, maxY - minY);

            }

            else

            {

                // Fallback: panel üst yarısı

                dzRT.anchorMin = new Vector2(0, 0.5f);

                dzRT.anchorMax = new Vector2(1, 1);

                dzRT.pivot = new Vector2(0.5f, 0.5f);

                dzRT.anchoredPosition = Vector2.zero;

                dzRT.sizeDelta = Vector2.zero;

            }

            var dzImg = npcDropZone.AddComponent<UnityEngine.UI.Image>();

            dzImg.color = new Color(0, 0, 0, 0); // Tamamen şeffaf

            dzImg.raycastTarget = true; // Drop hedefi olarak çalışsın

            var dzHandler = npcDropZone.AddComponent<KOItemSlotHandler>();

            dzHandler.slotType = KOItemSlotHandler.SlotType.ShopNpcSlot;

            dzHandler.slotIndex = -1; // Arka plan zone — spesifik slot değil

            dzHandler.tooltipItemDefId = 0;

            dzHandler.shopNpcId = _shopNpcId;

            dzHandler.shopTradeId = _shopTradeId;

            _shopListItems.Add(npcDropZone); // Temizlik için listeye ekle

        }

        /// <summary>

        /// Open-KO birebir: UITransactionDlg.cpp Msg_BtnPageDown/Up

        /// Sayfa ileri/geri butonlarını bağla.

        /// </summary>

        private void BindShopPageButtons()

        {

            if (_uiTransaction == null) return;

            Transform root = _uiTransaction.transform;

            // C++ birebir: m_pBtnPageUp, m_pBtnPageDown

            var btnUp = KOUIRenderer.FindChildButton(root, "btn_page_up");

            if (btnUp == null) btnUp = KOUIRenderer.FindChildButton(root, "Btn_PageUp");

            if (btnUp != null)

            {

                btnUp.onClick.RemoveAllListeners();

                btnUp.onClick.AddListener(() => {

                    if (_shopCurrentPage > 0)

                        ShowShopPage(_shopCurrentPage - 1);

                });

            }

            var btnDown = KOUIRenderer.FindChildButton(root, "btn_page_down");

            if (btnDown == null) btnDown = KOUIRenderer.FindChildButton(root, "Btn_PageDown");

            if (btnDown != null)

            {

                btnDown.onClick.RemoveAllListeners();

                btnDown.onClick.AddListener(() => {

                    int totalPages = (_currentShopItems.Length + MAX_ITEM_TRADE - 1) / MAX_ITEM_TRADE;

                    if (_shopCurrentPage < totalPages - 1)

                        ShowShopPage(_shopCurrentPage + 1);

                });

            }

        }

        private void SelectShopItem(int index)

        {

            if (_currentShopItems == null || index < 0 || index >= _currentShopItems.Length) return;

            _selectedShopItemIndex = index;

            // C++ UISTYLE_ICON_HIGHLIGHT karşılığı — ikon Image rengini ayarla

            for (int i = 0; i < _shopListItems.Count; i++)

            {

                var item = _shopListItems[i];

                if (item == null) continue;

                var img = item.GetComponent<UnityEngine.UI.Image>();

                if (img != null)

                    img.color = (i == index) ? new Color(0.7f, 0.9f, 1f, 1f) : Color.white;

            }

        }

        // Shop buy/sell pending info — C++ s_sRecoveryJobInfo karşılığı

        private bool _shopPendingIsBuy;

        /// <summary>

        /// C++ birebir: s_sRecoveryJobInfo.UIWndSourceStart.UIWndDistrict

        /// UIWND_DISTRICT_TRADE_NPC = buy, UIWND_DISTRICT_TRADE_MY = sell

        /// </summary>

        public bool IsShopPendingBuy => _shopPendingIsBuy;

        private int _shopPendingItemDefId;

        private int _shopPendingSlotIndex;

        private int _shopPendingNpcId;

        private int _shopPendingTradeId;

        private int _shopPendingAmount;

        // ================================================

        // C++ birebir: UITransactionDlg.h

        // m_pMyTradeInv[MAX_ITEM_INVENTORY] — Transaction dialog'un KENDI envanter kopyası.

        // m_pMyInvWnd'den ayrı tutulur. Shop açılınca m_pMyInvWnd'den taşınır,

        // kapanınca geri taşınır.

        // ================================================

        private KOInventory.ItemSlot[] m_pMyTradeInv = new KOInventory.ItemSlot[KOInventory.MAX_ITEM_INVENTORY];

        /// <summary>

        /// C++ birebir: spItem->pUIIcon->SetVisible(false) karşılığı.

        /// Sell onayında item gizlenir (silinmez), success'te silinir, fail'de gösterilir.

        /// </summary>

        private bool[] m_pMyTradeInvHidden = new bool[KOInventory.MAX_ITEM_INVENTORY];

        /// <summary>

        /// C++ birebir: UITransactionDlg.cpp ItemMoveFromInvToThis() satır 450-477

        /// Shop açılırken m_pMyInvWnd'den m_pMyTradeInv'ye TAŞI (move, copy değil).

        /// </summary>

        private void ItemMoveFromInvToThis()

        {

            var inv = KOInventory.Instance;

            if (inv == null) return;

            for (int i = 0; i < KOInventory.MAX_ITEM_INVENTORY; i++)

            {

                // C++ birebir: cpp:458

                m_pMyTradeInv[i] = null;

                m_pMyTradeInvHidden[i] = false;

                // C++ birebir: cpp:460-461

                if (inv.m_pMyInvWnd[i] == null) continue;

                // C++ birebir: cpp:463-466,475 — pointer MOVE

                m_pMyTradeInv[i] = inv.m_pMyInvWnd[i];

                inv.m_pMyInvWnd[i] = null;

            }

        }

        /// <summary>

        /// C++ birebir: UITransactionDlg.cpp ItemMoveFromThisToInv() satır 498-523

        /// Shop kapanırken m_pMyTradeInv'den m_pMyInvWnd'ye GERİ TAŞI.

        /// </summary>

        private void ItemMoveFromThisToInv()

        {

            var inv = KOInventory.Instance;

            if (inv == null) return;

            for (int i = 0; i < KOInventory.MAX_ITEM_INVENTORY; i++)

            {

                // C++ birebir: cpp:506-520

                if (m_pMyTradeInv[i] != null)

                {

                    inv.m_pMyInvWnd[i] = m_pMyTradeInv[i];

                    m_pMyTradeInv[i] = null;

                }

                m_pMyTradeInvHidden[i] = false;

            }

        }

        /// <summary>

        /// C++ birebir: UITransactionDlg.cpp ReceiveResultTradeFromServer satır 1305-1308

        /// Sell success'te item'ı m_pMyTradeInv'den tamamen sil.

        /// </summary>

        public void CompleteSellInTradeInv()

        {

            int slotIdx = _shopPendingSlotIndex;

            if (slotIdx >= 0 && slotIdx < KOInventory.MAX_ITEM_INVENTORY)

            {

                // C++ birebir: cpp:1305-1308

                // Countable + hidden VEYA non-countable → sil

                var slot = m_pMyTradeInv[slotIdx];

                if (slot != null && m_pMyTradeInvHidden[slotIdx])

                {

                    m_pMyTradeInv[slotIdx] = null;

                    m_pMyTradeInvHidden[slotIdx] = false;

                }

                else if (slot != null && slot.count <= 0)

                {

                    m_pMyTradeInv[slotIdx] = null;

                }

            }

        }

        /// <summary>

        /// Trade envanterindeki belirli bir slotun verisini getirir.

        /// </summary>

        public KOInventory.ItemSlot GetTradeInvItem(int slotIndex)

        {

            if (slotIndex >= 0 && slotIndex < KOInventory.MAX_ITEM_INVENTORY)

            {

                if (!m_pMyTradeInvHidden[slotIndex])

                    return m_pMyTradeInv[slotIndex];

            }

            return null;

        }

        /// <summary>

        /// Sayılı (stackable) item'lar için m_pMyTradeInv'de mevcut slotu arar.

        /// Yoksa ilk boş slotu döner.

        /// </summary>

        public int GetTradeInvDestinationIndex(int itemId, byte byContable)

        {

            byte realContable = byContable;

            if (realContable == 0 && KOInventory.s_pTbl_Items_Basic != null &&

                KOInventory.s_pTbl_Items_Basic.TryGetValue((uint)(itemId / 1000 * 1000), out var basic))

            {

                realContable = basic.byContable;

            }

            if (realContable == 1 || realContable == 2)

            {

                for (int i = 0; i < KOInventory.MAX_ITEM_INVENTORY; i++)

                {

                    if (m_pMyTradeInv[i] != null && m_pMyTradeInv[i].itemId == itemId)

                    {

                        return i;

                    }

                }

            }

            for (int i = 0; i < KOInventory.MAX_ITEM_INVENTORY; i++)

            {

                if (m_pMyTradeInv[i] == null)

                {

                    return i;

                }

            }

            return -1;

        }

        public int GetStallInvDestinationIndex(int itemId, byte byContable)

        {

            var koInv = KOInventory.Instance;

            if (koInv == null) return -1;

            byte realContable = byContable;

            if (realContable == 0 && KOInventory.s_pTbl_Items_Basic != null &&

                KOInventory.s_pTbl_Items_Basic.TryGetValue((uint)(itemId / 1000 * 1000), out var basic))

            {

                realContable = basic.byContable;

            }

            if (realContable == 1 || realContable == 2)

            {

                for (int i = 0; i < 28; i++)

                {

                    var slotItem = koInv.m_pMyInvWnd[i];

                    if (slotItem != null && !slotItem.IsEmpty && slotItem.itemId == itemId)

                    {

                        return i;

                    }

                }

            }

            for (int i = 0; i < 28; i++)

            {

                var slotItem = koInv.m_pMyInvWnd[i];

                if (slotItem == null || slotItem.IsEmpty)

                {

                    return i;

                }

            }

            return -1;

        }

        /// <summary>

        /// Sayılı (stackable) item'lar için m_pMyWareInv'de mevcut slotu arar.

        /// Yoksa ilk boş slotu döner.

        /// </summary>

        public int GetWareInvDestinationIndex(int itemId, byte byContable)

        {

            byte realContable = byContable;

            if (realContable == 0 && KOInventory.s_pTbl_Items_Basic != null &&

                KOInventory.s_pTbl_Items_Basic.TryGetValue((uint)(itemId / 1000 * 1000), out var basic))

            {

                realContable = basic.byContable;

            }

            if (realContable == 1 || realContable == 2)

            {

                for (int i = 0; i < KOInventory.MAX_ITEM_INVENTORY; i++)

                {

                    if (m_pMyWareInv[i] != null && m_pMyWareInv[i].itemId == itemId)

                    {

                        return i;

                    }

                }

            }

            for (int i = 0; i < KOInventory.MAX_ITEM_INVENTORY; i++)

            {

                if (m_pMyWareInv[i] == null)

                {

                    return i;

                }

            }

            return -1;

        }

        /// <summary>

        /// Sayılı (stackable) item'lar için tüm Warehouse sayfalarında mevcut slotu (ve sayfasını) arar.

        /// Yoksa aktif sayfadan başlayarak ilk boş slotu döner.

        /// </summary>

        public (int page, int slot) GetWareDestinationIndex(int itemId, byte byContable, int currentPage)

        {

            var mgr = KOWarehouseManager.Instance;

            if (mgr == null) return (currentPage, -1);

            byte realContable = byContable;

            if (realContable == 0 && KOInventory.s_pTbl_Items_Basic != null &&

                KOInventory.s_pTbl_Items_Basic.TryGetValue((uint)(itemId / 1000 * 1000), out var basic))

            {

                realContable = basic.byContable;

            }

            if (realContable == 1 || realContable == 2)

            {

                for (int iPage = 0; iPage < KOWarehouseManager.MAX_ITEM_WARE_PAGE; iPage++)

                {

                    for (int i = 0; i < KOWarehouseManager.MAX_ITEM_TRADE; i++)

                    {

                        var wSlot = mgr.GetSlot(iPage, i);

                        if (wSlot != null && wSlot.ItemId == itemId)

                        {

                            return (iPage, i);

                        }

                    }

                }

            }

            // Aksi halde en yakın boş slotu ara (mevcut sayfadan başlayarak)

            for (int offset = 0; offset < KOWarehouseManager.MAX_ITEM_WARE_PAGE; offset++)

            {

                int iPage = (currentPage + offset) % KOWarehouseManager.MAX_ITEM_WARE_PAGE;

                for (int i = 0; i < KOWarehouseManager.MAX_ITEM_TRADE; i++)

                {

                    var wSlot = mgr.GetSlot(iPage, i);

                    if (wSlot == null || wSlot.ItemId == 0)

                    {

                        return (iPage, i);

                    }

                }

            }

            return (-1, -1);

        }

