        {

            _shopPendingIsBuy = isbuying;

            _shopPendingItemDefId = itemDefId;

            _shopPendingSlotIndex = slotIndex;

            _shopPendingNpcId = npcId;

            _shopPendingTradeId = tradeId;

            _countableEditMode = CountableEditMode.ShopBuy;

            ShowCountableEdit(false);

        }

        /// <summary>

        /// C++ birebir: UITransactionDlg.cpp satır 1119-1123

        /// Normal (non-countable) item satma — onay mesajı gösterir.

        /// m_pUIMsgBoxOkCancel->ShowWindow(CHILD_UI_MSGBOX_OKCANCEL, this)

        /// m_pUIMsgBoxOkCancel->SetText(IDS_TRANSACTION_OK_CANCEL_MESSAGE)

        /// OK → OnConfirm() → SendToServerSellMsg

        /// </summary>

        public void ShowShopSellConfirm(int itemDefId, int slotIndex,

            int npcId, int tradeId, int count)

        {

            _shopPendingIsBuy = false;

            _shopPendingItemDefId = itemDefId;

            _shopPendingSlotIndex = slotIndex;

            _shopPendingNpcId = npcId;

            _shopPendingTradeId = tradeId;

            // C++ birebir: IDS_TRANSACTION_OK_CANCEL_MESSAGE

            // "Bu eşyayı satmak istediğinizden emin misiniz?"

            string itemName = GetFormattedItemName(itemDefId);

            // C++ birebir: co_MsgBoxOkCancel_us.uif — gerçek UIF dosyasını kullan

            if (KOMessageBox.Instance != null)

            {

                long totalCost = GetItemSellPrice(itemDefId, count);

                string msg = $"Do you want to sell {itemName} for {totalCost:N0} Coins?";

                KOMessageBox.Instance.ShowYesNo(

                    msg,

                    "Sell Item",

                    MsgBoxBehavior.BEHAVIOR_NOTHING,

                    onYes: () =>

                    {

                        var shopUI = ShopUI.Instance;

                        if (shopUI != null)

                        {

                            // C++ birebir: UITransactionDlg.cpp OnConfirm (satır 740-749)

                            // Önce pending amount kaydet

                            _shopPendingAmount = count;

                            // Lokal envanterden çıkar — C++ satır 745: spItem->pUIIcon->SetVisible(false)

                            ApplyPendingTradeToInventory();

                            RefreshShopInventory();

                            // SONRA paketi gönder — C++ satır 747-748: SendToServerSellMsg

                            shopUI.SellItem(_shopPendingTradeId, (byte)_shopPendingSlotIndex,

                                (uint)_shopPendingItemDefId, (short)count);

                        }

                    },

                    onNo: () =>

                    {

                    },

                    callerPanel: _uiTransaction);

            }

        }

        /// <summary>

        /// Warp panel butonlarını ve text referanslarını bağlar.

        /// C++ referans: UIWarp.cpp Load() satır 27-38

        /// </summary>

        private void BindWarpButtons(Transform root)

        {

            // C++ UIWarp.cpp satır 32: m_pBtn_Ok = GetChildByID<CN3UIButton>("Btn_Ok")

            var btnOk = KOUIRenderer.FindChildButton(root, "Btn_Ok");

            if (btnOk != null)

            {

                btnOk.onClick.AddListener(() =>

                {

                    // C++ UIWarp.cpp satır 44-47: MsgSend_Warp → warpId + gold kontrolü + close

                    MsgSend_Warp();

                });

            }

            // C++ UIWarp.cpp satır 33: m_pBtn_Cancel = GetChildByID<CN3UIButton>("Btn_Cancel")

            var btnCancel = KOUIRenderer.FindChildButton(root, "Btn_Cancel");

            if (btnCancel != null)

            {

                btnCancel.onClick.AddListener(() =>

                {

                    // C++ UIWarp.cpp satır 48-51: close

                    ShowWarp(false);

                });

            }

            // C++ UIWarp.cpp satır 35: m_pText_Agreement = GetChildByID<CN3UIString>("Text_Agreement")

            _textAgreement = KOUIRenderer.FindChildText(root, "Text_Agreement");

            ModernizeWarpPanel(root);

        }

        private void ModernizeWarpPanel(Transform root)

        {

            try

            {

                var rootRT = root.GetComponent<RectTransform>();

                if (rootRT == null) return;

                // 0. Force panel dimension and Right-Center anchoring (280 x 450)

                rootRT.anchorMin = new Vector2(1f, 0.5f);

                rootRT.anchorMax = new Vector2(1f, 0.5f);

                rootRT.pivot = new Vector2(1f, 0.5f);

                rootRT.sizeDelta = new Vector2(280f, 450f);

                // 1. Disable legacy background/border images

/* Loop Removed */

/* Loop Removed */

                // 2. Clear graphic component on root itself (if any)

                var rootImg = root.GetComponent<Image>();

                if (rootImg != null) rootImg.enabled = false;

                var rootRaw = root.GetComponent<RawImage>();

                if (rootRaw != null) rootRaw.enabled = false;

                // 3. Create or update custom background (WarpCustomBg)

                var customBg = root.Find("WarpCustomBg")?.gameObject;

                Image bgImg = null;

                if (customBg == null)

                {

                    customBg = new GameObject("WarpCustomBg", typeof(RectTransform));

                    customBg.transform.SetParent(root, false);

                    customBg.transform.SetAsFirstSibling();

                    bgImg = customBg.AddComponent<Image>();

                    var rt = customBg.GetComponent<RectTransform>();

                    if (rt != null)

                    {

                        rt.anchorMin = Vector2.zero;

                        rt.anchorMax = Vector2.one;

                        rt.offsetMin = Vector2.zero;

                        rt.offsetMax = Vector2.zero;

                    }

                }

                else

                {

                    bgImg = customBg.GetComponent<Image>() ?? customBg.AddComponent<Image>();

                }

                if (bgImg != null)

                {

                    bgImg.sprite = GetSkillThemePanelBgSprite("warp_custom_bg_280_450", 280, 450, 0,

                        new Color(0.12f, 0.10f, 0.08f, 0.98f),

                        new Color(0.04f, 0.04f, 0.04f, 0.98f),

                        new Color(0.6f, 0.48f, 0.22f, 0.9f),

                        2);

                    bgImg.color = Color.white;

                }

                // 3.5 Style the scroll/list container background area

                var listArea = KOUIRenderer.FindChildByID(root, "List_Infos") ?? KOUIRenderer.FindChildByID(root, "List_Warp");

                if (listArea != null)

                {

                    var listAreaImg = listArea.GetComponent<Image>() ?? listArea.gameObject.AddComponent<Image>();

                    if (listAreaImg != null)

                    {

                        var rt = listArea.GetComponent<RectTransform>();

                        if (rt != null)

                        {

                            rt.anchorMin = new Vector2(0.5f, 1f);

                            rt.anchorMax = new Vector2(0.5f, 1f);

                            rt.pivot = new Vector2(0.5f, 1f);

                            rt.sizeDelta = new Vector2(256f, 190f);

                            rt.anchoredPosition = new Vector2(0f, -45f);

                        }

                        listAreaImg.sprite = GetSkillThemeRoundedRectSprite("warp_list_area_bg_256_190", 256, 190, 0,

                            new Color(0.06f, 0.05f, 0.04f, 0.6f),

                            new Color(0.4f, 0.3f, 0.15f, 0.5f),

                            1);

                        listAreaImg.color = Color.white;

                    }

                }

                // Create or find combined container for preview image and description text (WarpInfoContainer)

                var infoContainer = root.Find("WarpInfoContainer")?.gameObject;

                Image infoContainerImg = null;

                if (infoContainer == null)

                {

                    infoContainer = new GameObject("WarpInfoContainer", typeof(RectTransform));

                    infoContainer.transform.SetParent(root, false);

                    infoContainerImg = infoContainer.AddComponent<Image>();

                    var rt = infoContainer.GetComponent<RectTransform>();

                    if (rt != null)

                    {

                        rt.anchorMin = new Vector2(0.5f, 1f);

                        rt.anchorMax = new Vector2(0.5f, 1f);

                        rt.pivot = new Vector2(0.5f, 1f);

                        rt.sizeDelta = new Vector2(256f, 140f);

                        rt.anchoredPosition = new Vector2(0f, -245f);

                    }

                }

                else

                {

                    infoContainerImg = infoContainer.GetComponent<Image>() ?? infoContainer.AddComponent<Image>();

                }

                if (infoContainerImg != null)

                {

                    infoContainerImg.sprite = GetSkillThemeRoundedRectSprite("warp_info_container_bg_sharp_v2", 256, 140, 0,

                        new Color(0.06f, 0.05f, 0.04f, 0.8f),

                        new Color(0.4f, 0.3f, 0.15f, 0.5f),

                        1);

                    infoContainerImg.color = Color.white;

                }

                // 3.7 Create or update zone preview box inside WarpInfoContainer

                var previewGo = infoContainer.transform.Find("WarpZonePreview")?.gameObject;

                if (previewGo == null)

                {

                    previewGo = new GameObject("WarpZonePreview", typeof(RectTransform));

                    previewGo.transform.SetParent(infoContainer.transform, false);

                    previewGo.AddComponent<RawImage>();

                }

                else

                {

                    previewGo.transform.SetParent(infoContainer.transform, false);

                    // Temizlik: Ekranda üst üste binmiş mükerrer kopya varsa temizle

                    for (int c = infoContainer.transform.childCount - 1; c >= 0; c--)

                    {

                        var child = infoContainer.transform.GetChild(c);

                        if (child.gameObject != previewGo && child.gameObject.name == "WarpZonePreview")

                        {

                            DestroyImmediate(child.gameObject);

                        }

                    }

                }

                var previewRT = previewGo.GetComponent<RectTransform>();

                if (previewRT != null)

                {

                    previewRT.anchorMin = new Vector2(0.5f, 1f);

                    previewRT.anchorMax = new Vector2(0.5f, 1f);

                    previewRT.pivot = new Vector2(0.5f, 1f);

                    previewRT.sizeDelta = new Vector2(254f, 85f); // fits inside 256px wide container with 1px border

                    previewRT.anchoredPosition = new Vector2(0f, -1f);

                }

                // Clean up legacy border object if exists

                var borderObj = previewGo.transform.Find("Border")?.gameObject ?? root.Find("Border")?.gameObject;

                if (borderObj != null) DestroyImmediate(borderObj);

                // Add or update vertical gradient overlay at the bottom of the preview box

                var overlayObj = previewGo.transform.Find("GradientOverlay")?.gameObject;

                if (overlayObj == null)

                {

                    overlayObj = new GameObject("GradientOverlay", typeof(RectTransform));

                    overlayObj.transform.SetParent(previewGo.transform, false);

                    var overlayRT = overlayObj.GetComponent<RectTransform>();

                    if (overlayRT != null)

                    {

                        overlayRT.anchorMin = new Vector2(0f, 0f);

                        overlayRT.anchorMax = new Vector2(1f, 0f);

                        overlayRT.pivot = new Vector2(0.5f, 0f);

                        overlayRT.sizeDelta = new Vector2(0f, 25f);

                        overlayRT.anchoredPosition = Vector2.zero;

                    }

                    var overlayImg = overlayObj.AddComponent<Image>();

                    overlayImg.sprite = GetVerticalGradientSprite("warp_preview_bottom_shadow_v3", 254, 25, new Color(0f, 0f, 0f, 0f), new Color(0.06f, 0.05f, 0.04f, 1f));

                    overlayImg.type = Image.Type.Simple;

                    overlayImg.color = Color.white;

                    overlayImg.raycastTarget = false;

                }

                else

                {

                    var overlayRT = overlayObj.GetComponent<RectTransform>();

                    if (overlayRT != null)

                    {

                        overlayRT.anchorMin = new Vector2(0f, 0f);

                        overlayRT.anchorMax = new Vector2(1f, 0f);

                        overlayRT.pivot = new Vector2(0.5f, 0f);

                        overlayRT.sizeDelta = new Vector2(0f, 25f);

                        overlayRT.anchoredPosition = Vector2.zero;

                    }

                    var overlayImg = overlayObj.GetComponent<Image>();

                    if (overlayImg != null)

                    {

                        overlayImg.sprite = GetVerticalGradientSprite("warp_preview_bottom_shadow_v3", 254, 25, new Color(0f, 0f, 0f, 0f), new Color(0.06f, 0.05f, 0.04f, 1f));

                    }

                }

                // 4. Style buttons (Btn_Ok: Green, Btn_Cancel: Red, identical to KOMessageBox, sized 85x30)

                var btnOk = KOUIRenderer.FindChildButton(root, "Btn_Ok");

                if (btnOk != null)

                {

                    var rt = btnOk.GetComponent<RectTransform>();

                    if (rt != null)

                    {

                        rt.anchorMin = new Vector2(0.5f, 1f);

                        rt.anchorMax = new Vector2(0.5f, 1f);

                        rt.pivot = new Vector2(0.5f, 1f);

                        rt.sizeDelta = new Vector2(85f, 30f);

                        rt.anchoredPosition = new Vector2(-55f, -400f);

                    }

                    // Destroy legacy RawImage first to prevent conflict with Image component

                    var raw = btnOk.GetComponent<RawImage>();

                    if (raw != null) DestroyImmediate(raw);

                    int w = 85;

                    int h = 30;

                    Texture2D tex = new Texture2D(w, h, TextureFormat.RGBA32, false);

                    Color fillColor = new Color(0.12f, 0.28f, 0.12f, 0.95f);

                    Color borderColor = new Color(0.25f, 0.55f, 0.25f, 0.95f);

                    for (int y = 0; y < h; y++)

                    {

                        for (int x = 0; x < w; x++)

                        {

                            if (x < 1 || x >= w - 1 || y < 1 || y >= h - 1)

                                tex.SetPixel(x, y, borderColor);

                            else

                                tex.SetPixel(x, y, fillColor);

                        }

                    }

                    tex.Apply();

                    var img = btnOk.gameObject.GetComponent<Image>() ?? btnOk.gameObject.AddComponent<Image>();

                    img.sprite = Sprite.Create(tex, new Rect(0, 0, w, h), new Vector2(0.5f, 0.5f));

                    img.type = Image.Type.Simple;

                    img.color = Color.white;

                    btnOk.transition = Selectable.Transition.ColorTint;

                    btnOk.targetGraphic = img;

                    var txt = btnOk.GetComponentInChildren<Text>();

                    if (txt == null || txt.gameObject.name != "Text")

                    {

                        var txtObj = new GameObject("Text", typeof(RectTransform));

                        txtObj.transform.SetParent(btnOk.transform, false);

                        txt = txtObj.AddComponent<Text>();

                        var txtRT = txtObj.GetComponent<RectTransform>();

                        if (txtRT != null)

                        {

                            txtRT.anchorMin = Vector2.zero;

                            txtRT.anchorMax = Vector2.one;

                            txtRT.offsetMin = Vector2.zero;

                            txtRT.offsetMax = Vector2.zero;

                        }

                    }

                    txt.text = "OK";

                    txt.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");

                    txt.fontSize = 14;

                    txt.color = Color.white;

                    txt.fontStyle = FontStyle.Bold;

                    txt.alignment = TextAnchor.MiddleCenter;

                }

                var btnCancel = KOUIRenderer.FindChildButton(root, "Btn_Cancel");

                if (btnCancel != null)

                {

                    var rt = btnCancel.GetComponent<RectTransform>();

                    if (rt != null)

                    {

                        rt.anchorMin = new Vector2(0.5f, 1f);

                        rt.anchorMax = new Vector2(0.5f, 1f);

                        rt.pivot = new Vector2(0.5f, 1f);

                        rt.sizeDelta = new Vector2(85f, 30f);

                        rt.anchoredPosition = new Vector2(55f, -400f);

                    }

                    // Destroy legacy RawImage first to prevent conflict with Image component

                    var raw = btnCancel.GetComponent<RawImage>();

                    if (raw != null) DestroyImmediate(raw);

                    int w = 85;

                    int h = 30;

                    Texture2D tex = new Texture2D(w, h, TextureFormat.RGBA32, false);

                    Color fillColor = new Color(0.45f, 0.05f, 0.08f, 0.95f);

                    Color borderColor = new Color(0.75f, 0.15f, 0.15f, 0.95f);

                    for (int y = 0; y < h; y++)

                    {

                        for (int x = 0; x < w; x++)

                        {

                            if (x < 1 || x >= w - 1 || y < 1 || y >= h - 1)

                                tex.SetPixel(x, y, borderColor);

                            else

                                tex.SetPixel(x, y, fillColor);

                        }

                    }

                    tex.Apply();

                    var img = btnCancel.gameObject.GetComponent<Image>() ?? btnCancel.gameObject.AddComponent<Image>();

                    img.sprite = Sprite.Create(tex, new Rect(0, 0, w, h), new Vector2(0.5f, 0.5f));

                    img.type = Image.Type.Simple;

                    img.color = Color.white;

                    btnCancel.transition = Selectable.Transition.ColorTint;

                    btnCancel.targetGraphic = img;

                    var txt = btnCancel.GetComponentInChildren<Text>();

                    if (txt == null || txt.gameObject.name != "Text")

                    {

                        var txtObj = new GameObject("Text", typeof(RectTransform));

                        txtObj.transform.SetParent(btnCancel.transform, false);

                        txt = txtObj.AddComponent<Text>();

                        var txtRT = txtObj.GetComponent<RectTransform>();

                        if (txtRT != null)

                        {

                            txtRT.anchorMin = Vector2.zero;

                            txtRT.anchorMax = Vector2.one;

                            txtRT.offsetMin = Vector2.zero;

                            txtRT.offsetMax = Vector2.zero;

                        }

                    }

                    txt.text = "CANCEL";

                    txt.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");

                    txt.fontSize = 14;

                    txt.color = Color.white;

                    txt.fontStyle = FontStyle.Bold;

                    txt.alignment = TextAnchor.MiddleCenter;

                }

                // 5. Add or style header title text (Style matching SKILL PAGE)

                var titleText = KOUIRenderer.FindChildText(root, "ui_String_Title") ?? KOUIRenderer.FindChildText(root, "Text_Title") ?? root.Find("Text_Title")?.GetComponent<Text>();

                if (titleText == null)

                {

                    var titleObj = new GameObject("Text_Title", typeof(RectTransform));

                    titleObj.transform.SetParent(root, false);

                    titleText = titleObj.AddComponent<Text>();

                }

                if (titleText != null)

                {

                    titleText.gameObject.SetActive(true);

                    var rt = titleText.GetComponent<RectTransform>();

                    if (rt != null)

                    {

                        rt.anchorMin = new Vector2(0.5f, 1f);

                        rt.anchorMax = new Vector2(0.5f, 1f);

                        rt.pivot = new Vector2(0.5f, 1f);

                        rt.sizeDelta = new Vector2(200f, 30f);

                        rt.anchoredPosition = new Vector2(0f, -12f);

                    }

                    titleText.text = "TELEPORT";

                    titleText.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");

                    titleText.color = new Color(0.95f, 0.85f, 0.35f, 1f);

                    titleText.fontStyle = FontStyle.Bold;

                    titleText.fontSize = 14;

                    titleText.alignment = TextAnchor.MiddleCenter;

                    AddSkillThemeTextShadow(titleText);

                }

                // 6. Style Agreement description text (Gold, centered, placed inside WarpInfoContainer)

                if (_textAgreement != null && infoContainer != null)

                {

                    _textAgreement.transform.SetParent(infoContainer.transform, false);

                    _textAgreement.transform.SetAsLastSibling();

                    var rt = _textAgreement.GetComponent<RectTransform>();

                    if (rt != null)

                    {

                        rt.anchorMin = new Vector2(0.5f, 0f);

                        rt.anchorMax = new Vector2(0.5f, 0f);

                        rt.pivot = new Vector2(0.5f, 0f);

                        rt.sizeDelta = new Vector2(240f, 50f); // Constrained absolute width of exactly 240px to wrap properly

                        rt.anchoredPosition = new Vector2(0f, 2f);

                    }

                    _textAgreement.color = new Color(0.95f, 0.85f, 0.35f, 1f);

                    _textAgreement.fontSize = 11;

                    _textAgreement.alignment = TextAnchor.MiddleCenter;

                    _textAgreement.horizontalOverflow = HorizontalWrapMode.Wrap;

                    _textAgreement.verticalOverflow = VerticalWrapMode.Overflow;

                    AddSkillThemeTextShadow(_textAgreement);

                }

                // 7. Deactivate legacy question text and other misplaced/stray text objects

                var texts = root.GetComponentsInChildren<Text>(true);

                foreach (var txt in texts)

                {

                    if (txt == null || txt == titleText || txt == _textAgreement) continue;

                    // Skip newly created button text labels

                    if (txt.gameObject.name == "Text")

                    {

                        var pTrans = txt.transform.parent;

                        if (pTrans != null && (pTrans.name == "Btn_Ok" || pTrans.name == "Btn_Cancel"))

                        {

                            continue;

                        }

                    }

                    txt.gameObject.SetActive(false);

                }

            }

            catch (System.Exception ex)

            {

                Debug.LogError($"[KOUIMGR] Error in ModernizeWarpPanel: {ex.Message}");

            }

        }

        /// <summary>

        /// Open-KO birebir: MsgSend_Warp (GameProcMain.cpp:4344-4365)

        /// InfoGetCur → gold kontrolü → WIZ_WARP_LIST + warpId gönder.

        /// Btn_Ok ve double-tap tarafından çağrılır.

        /// </summary>

        private void MsgSend_Warp()

        {

            // C++ UIWarp.cpp satır 44-51 birebir:

            //   case BTN_OK: MsgSend_Warp(); break;

            //   this->SetVisible(false);  ← OK/Cancel dışında, HER ZAMAN çalışır

            // Unity: önce gönder, sonra panel'i kapat (C++ sırası birebir)

            // C++ cpp:4347: if (!m_pUIWarp->InfoGetCur(WI) || WI.szName.empty()) return

            if (_selectedWarpIndex >= 0 && _currentWarpEntries != null &&

                _selectedWarpIndex < _currentWarpEntries.Length)

            {

                var entry = _currentWarpEntries[_selectedWarpIndex];

                if (!string.IsNullOrEmpty(entry.Name) && WarpUI.Instance != null)

                {

                    WarpUI.Instance.SendWarpSelect(entry.WarpId, entry.Name, entry.GoldCost);

                    return; // SendWarpSelect zaten ShowWarp(false) çağırır

                }

            }

            // C++ birebir: UIWarp.cpp satır 51 — SetVisible(false) HER ZAMAN çalışır

            // Seçim yoksa bile panel kapanır

            ShowWarp(false);

        }

        /// <summary>

        /// Sunucudan gelen warp noktalarını panele doldurur.

        /// C++ referans: UIWarp.cpp UpdateList() satır 90-104

        /// → m_pList_Infos->ResetContent()

        /// → m_pList_Infos->AddString(it->szName)

        /// → m_pList_Infos->SetCurSel(0)

        /// → UpdateAgreement()

        ///

        /// C++ MsgRecv_WarpList (GameProcMain.cpp:6775-6804):

        ///   m_pUIWarp->Reset()

        ///   for each warp: m_pUIWarp->InfoAdd(WI)

        ///   m_pUIWarp->UpdateList()

        ///   m_pUIWarp->SetVisible(true)

        /// </summary>

        public void PopulateWarpList(WarpListEntry[] entries)

        {

            if (_uiWarp == null) return;

            _currentWarpEntries = entries;

            _selectedWarpId = -1;

            _selectedWarpIndex = -1;

            // C++ UIWarp.cpp:95: m_pList_Infos->ResetContent()

            foreach (var item in _warpListItems)

            {

                if (item != null) Destroy(item);

            }

            _warpListItems.Clear();

            // Warp panelinin root transform'unu al

            var warpRoot = _uiWarp.transform;

            // C++ UIWarp.cpp:34: m_pList_Infos = GetChildByID<CN3UIList>("List_Infos")

            Transform listParent = warpRoot;

            var listArea = KOUIRenderer.FindChildByID(warpRoot, "List_Infos");

            if (listArea == null)

                listArea = KOUIRenderer.FindChildByID(warpRoot, "List_Warp");

            if (listArea != null)

                listParent = listArea;

            // Her warp noktası için tıklanabilir entry oluştur

            var warpRT = _uiWarp.GetComponent<RectTransform>();

            float panelWidth = warpRT != null ? warpRT.sizeDelta.x : 200f;

            float startY = -5f; // Start with a slight offset to prevent top border overlap

            float itemHeight = 28f;

            // C++ UIWarp.cpp:96-100: iterate m_ListInfos, AddString(szName)

            for (int i = 0; i < entries.Length; i++)

            {

                var entry = entries[i];

                int index = i; // Closure için

                // Text GameObject oluştur

                var itemObj = new GameObject($"WarpItem_{i}");

                itemObj.transform.SetParent(listParent, false);

                var itemRT = itemObj.AddComponent<RectTransform>();

                itemRT.anchorMin = new Vector2(0, 1);

                itemRT.anchorMax = new Vector2(1, 1);

                itemRT.pivot = new Vector2(0.5f, 1);

                itemRT.anchoredPosition = new Vector2(0, startY - (i * itemHeight));

                itemRT.sizeDelta = new Vector2(0, itemHeight);

                // C++ UIWarp.cpp:99: m_pList_Infos->AddString(it->szName)

                var text = itemObj.AddComponent<Text>();

                text.text = entry.Name;

                text.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");

                text.fontSize = 14;

                text.color = Color.white;

                text.alignment = TextAnchor.MiddleCenter;

                text.raycastTarget = true;

                // Background (seçim göstergesi)

                var bgObj = new GameObject("BG");

                bgObj.transform.SetParent(itemObj.transform, false);

                bgObj.transform.SetAsFirstSibling();

                var bgRT = bgObj.AddComponent<RectTransform>();

                bgRT.anchorMin = Vector2.zero;

                bgRT.anchorMax = Vector2.one;

                bgRT.sizeDelta = Vector2.zero;

                var bgImage = bgObj.AddComponent<UnityEngine.UI.Image>();

                bgImage.sprite = GetFadeGradientSprite("warp_selection_fade_bg_256_28", 256, 28, Color.white, Color.clear, 0);

                bgImage.type = UnityEngine.UI.Image.Type.Simple;

                bgImage.color = new Color(0, 0, 0, 0); // Başlangıçta şeffaf

                bgImage.raycastTarget = false;

                // Tek tıklama — seçim (C++ UIMSG_LIST_SELCHANGE)

                var btn = itemObj.AddComponent<Button>();

                btn.transition = Selectable.Transition.None;

                btn.onClick.AddListener(() =>

                {

                    SelectWarpEntry(index);

                });

                // C++ UIWarp.cpp satır 60-64: UIMSG_LIST_DBLCLK → MsgSend_Warp + close

                // Mobilde double-tap → KODoubleTapDetector ile tespit

                var doubleTap = itemObj.AddComponent<KODoubleTapDetector>();

                doubleTap.onDoubleTap = () =>

                {

                    SelectWarpEntry(index);

                    MsgSend_Warp();

                };

                // Add horizontal divider line

                var dividerObj = new GameObject("Divider");

                dividerObj.transform.SetParent(itemObj.transform, false);

                var dividerRT = dividerObj.AddComponent<RectTransform>();

                dividerRT.anchorMin = new Vector2(0f, 0f);

                dividerRT.anchorMax = new Vector2(1f, 0f);

                dividerRT.pivot = new Vector2(0.5f, 0f);

                dividerRT.sizeDelta = new Vector2(0f, 1f); // 1px height

                dividerRT.anchoredPosition = new Vector2(0f, 0f);

                var dividerImg = dividerObj.AddComponent<Image>();

                dividerImg.sprite = GetSkillThemeFadingDividerSprite("warp_item_divider", 200, 1, new Color(0.6f, 0.48f, 0.22f, 0.35f));

                dividerImg.color = Color.white;

                _warpListItems.Add(itemObj);

            }

            // C++ UIWarp.cpp:102-103: SetCurSel(0) + UpdateAgreement()

            if (entries.Length > 0)

                SelectWarpEntry(0);

        }

        /// <summary>

        /// Warp listesinde bir entry seçer.

        /// C++ UIWarp.cpp ReceiveMessage satır 53-58: UIMSG_LIST_SELCHANGE → UpdateAgreement()

        /// </summary>

        private void SelectWarpEntry(int index)

        {

            if (_currentWarpEntries == null || index < 0 || index >= _currentWarpEntries.Length)

                return;

            _selectedWarpId = _currentWarpEntries[index].WarpId;

            _selectedWarpIndex = index;

            // Tüm item'ların arka planını sıfırla, seçiliyi vurgula

            for (int i = 0; i < _warpListItems.Count; i++)

            {

                var item = _warpListItems[i];

                if (item == null) continue;

                var bg = item.transform.Find("BG");

                if (bg != null)

                {

                    var bgImg = bg.GetComponent<UnityEngine.UI.Image>();

                    if (bgImg != null)

                        bgImg.color = (i == index)

                            ? new Color(0.6f, 0.48f, 0.22f, 0.35f) // Seçili: gold vurgu

                            : new Color(0, 0, 0, 0);              // Seçili değil: şeffaf

                }

                var text = item.GetComponent<Text>();

                if (text != null)

                    text.color = (i == index) ? new Color(0.95f, 0.85f, 0.35f, 1f) : Color.white;

            }

            UpdateWarpAgreement();

            // Dynamic preview image loading based on selected warp destination name

            if (_uiWarp != null)

            {

                var previewGo = _uiWarp.transform.Find("WarpInfoContainer/WarpZonePreview") ?? _uiWarp.transform.Find("WarpZonePreview");

                if (previewGo != null)

                {

                    var previewImg = previewGo.GetComponent<RawImage>();

                    if (previewImg != null)

                    {

                        string entryName = _currentWarpEntries[index].Name.ToLower();

                        string assetName = "castle_preview"; // fallback default

                        if (entryName.Contains("moradon"))

                        {

                            assetName = "moradon_preview";

                        }

                        else if (entryName.Contains("eslant"))

                        {

                            assetName = "eslant_preview";

                        }

                        else if (entryName.Contains("luferson"))

                        {

                            assetName = "luferson_preview";

                        }

                        else if (entryName.Contains("el morad"))

                        {

                            assetName = "elmorad_preview";

                        }

                        else if (entryName.Contains("colony zone") || entryName.Contains("colony"))

                        {

                            assetName = "colonyzone_preview";

                        }

                        else if (entryName.Contains("lunar valley") || entryName.Contains("lunar"))

                        {

                            assetName = "lunarvalley_preview";

                        }

                        else if (entryName.Contains("delos"))

                        {

                            assetName = "delos_preview";

                        }

                        else if (entryName.Contains("castle"))

                        {

                            assetName = "castle_preview";

                        }

                        else if (entryName.Contains("land") || entryName.Contains("war") || entryName.Contains("arena") || entryName.Contains("zone") || entryName.Contains("valley"))

                        {

                            assetName = "warzone_preview";

                        }

                        var tex = Resources.Load<Texture2D>($"WarpPreviews/{assetName}");

                        if (tex != null)

                        {

                            previewImg.texture = tex;

                            previewImg.enabled = true;

                        }

                        else

                        {

                            previewImg.enabled = false;

                        }

                    }

                }

            }

        }

        /// <summary>

        /// Open-KO birebir: UIWarp::UpdateAgreement (UIWarp.cpp:106-118)

        /// Seçili warp noktasının szAgreement metnini Text_Agreement'a yazar.

        /// </summary>

        private void UpdateWarpAgreement()

        {

            // C++ cpp:108: if (m_pList_Infos == nullptr || m_pText_Agreement == nullptr) return

            if (_textAgreement == null) return;

            if (_currentWarpEntries == null || _selectedWarpIndex < 0 ||

                _selectedWarpIndex >= _currentWarpEntries.Length)

            {

                _textAgreement.text = "";

                return;

            }

            // C++ birebir: CN3UIString::SetString() otomatik word-wrap + clip yapar

            // Unity Text component'ında bunu elle ayarla — taşma olmasın

            _textAgreement.horizontalOverflow = HorizontalWrapMode.Wrap;

            _textAgreement.verticalOverflow = VerticalWrapMode.Overflow;

            // C++ cpp:117: m_pText_Agreement->SetString(it->szAgreement)

            _textAgreement.text = _currentWarpEntries[_selectedWarpIndex].Agreement ?? "";

        }

