            _textAlive = KOUIRenderer.FindChildText(root, "Text_Alive");

            if (_textAlive != null)

            {

                // C++'da CN3UIString tıklanabilir — UIMSG_STRING_LCLICK mesajı oluşturur

                // Unity'de Text'e Button component ekle

                var btn = _textAlive.gameObject.GetComponent<Button>();

                if (btn == null) btn = _textAlive.gameObject.AddComponent<Button>();

                btn.onClick.AddListener(() =>

                {

