        private void ModernizeDeadPanel(Transform root)

        {

            try

            {

                // 1. Ortalama ve boyutlandırma (280 x 140)

                var rootRT = root.GetComponent<RectTransform>();

                if (rootRT != null)

                {

                    rootRT.anchorMin = new Vector2(0.5f, 0.5f);

                    rootRT.anchorMax = new Vector2(0.5f, 0.5f);

                    rootRT.pivot = new Vector2(0.5f, 0.5f);

                    rootRT.sizeDelta = new Vector2(280f, 140f);

                    rootRT.anchoredPosition = Vector2.zero;

                }

                // 2. Koyu premium MessageBox arka planı oluştur ve ata

                var customBg = root.Find("DeadCustomBg")?.gameObject;

                Image bgImg = null;

                if (customBg == null)

                {

                    customBg = new GameObject("DeadCustomBg", typeof(RectTransform));

                    customBg.transform.SetParent(root, false);

                    customBg.transform.SetAsFirstSibling();

                    bgImg = customBg.AddComponent<Image>();

                    var rt = customBg.GetComponent<RectTransform>();

                    rt.anchorMin = Vector2.zero;

                    rt.anchorMax = Vector2.one;

                    rt.offsetMin = Vector2.zero;

                    rt.offsetMax = Vector2.zero;

                }

                else

                {

                    bgImg = customBg.GetComponent<Image>();

                }

                if (bgImg != null)

                {

                    bgImg.sprite = GetSkillThemePanelBgSprite("dead_custom_bg", 280, 140, 0,

                        new Color(0.15f, 0.12f, 0.10f, 0.98f),

                        new Color(0.06f, 0.05f, 0.05f, 0.98f),

                        new Color(0.6f, 0.48f, 0.22f, 0.9f),

                        2);

                    bgImg.color = Color.white;

                }

                // 3. Bilgilendirme metni oluştur (MsgBox tarzı)

                var descObj = root.Find("Text_Description")?.gameObject;

                Text descTxt = null;

                if (descObj == null)

                {

                    descObj = new GameObject("Text_Description", typeof(RectTransform));

                    descObj.transform.SetParent(root, false);

                    descTxt = descObj.AddComponent<Text>();

                    var rt = descObj.GetComponent<RectTransform>();

                    rt.anchorMin = new Vector2(0.5f, 0.5f);

                    rt.anchorMax = new Vector2(0.5f, 0.5f);

                    rt.pivot = new Vector2(0.5f, 0.5f);

                    rt.sizeDelta = new Vector2(240f, 50f);

                    rt.anchoredPosition = new Vector2(0f, 20f);

                }

                else

                {

                    descTxt = descObj.GetComponent<Text>();

                }

                if (descTxt != null)

                {

                    descTxt.text = "You died.\nDo you want to respawn at town?";

                    descTxt.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");

                    descTxt.fontSize = 12;

                    descTxt.color = new Color(0.9f, 0.85f, 0.75f, 1f);

                    descTxt.fontStyle = FontStyle.Bold;

                    descTxt.alignment = TextAnchor.MiddleCenter;

                    AddSkillThemeTextShadow(descTxt);

                }

                // 4. Can taşından kalkış butonunu (Text_Alive) gizle

                if (_textAlive != null)

                {

                    _textAlive.gameObject.SetActive(false);

                }

                // 5. Town butonunu (Text_Town) "OK" butonu olarak modernize et (Parent konteyner yöntemiyle)

                if (_textTown != null)

                {

                    var btnOkObj = root.Find("DeadBtnOk")?.gameObject;

                    Image img = null;

                    Button btn = null;

                    if (btnOkObj == null)

                    {

                        btnOkObj = new GameObject("DeadBtnOk", typeof(RectTransform));

                        btnOkObj.transform.SetParent(root, false);

                        img = btnOkObj.AddComponent<Image>();

                        btn = btnOkObj.AddComponent<Button>();

                        btn.transition = Selectable.Transition.ColorTint;

                        btn.targetGraphic = img;

                        // Parent the original Text_Town to this button

                        _textTown.transform.SetParent(btnOkObj.transform, false);

                        var rtTxt = _textTown.GetComponent<RectTransform>();

                        rtTxt.anchorMin = Vector2.zero;

                        rtTxt.anchorMax = Vector2.one;

                        rtTxt.pivot = new Vector2(0.5f, 0.5f);

                        rtTxt.offsetMin = Vector2.zero;

                        rtTxt.offsetMax = Vector2.zero;

                        // Transfer listeners from _textTown's button component (if any) to the parent button

                        var oldBtn = _textTown.GetComponent<Button>();

                        if (oldBtn != null)

                        {

                            btn.onClick = oldBtn.onClick;

                            DestroyImmediate(oldBtn);

                        }

                    }

                    else

                    {

                        img = btnOkObj.GetComponent<Image>() ?? btnOkObj.AddComponent<Image>();

                        btn = btnOkObj.GetComponent<Button>() ?? btnOkObj.AddComponent<Button>();

                    }

                    // Her zaman güncel boyut ve konumlandırmayı uygula (yeşil buton boyutlarında)

                    var rtBtn = btnOkObj.GetComponent<RectTransform>();

                    if (rtBtn != null)

                    {

                        rtBtn.anchorMin = new Vector2(0.5f, 0.5f);

                        rtBtn.anchorMax = new Vector2(0.5f, 0.5f);

                        rtBtn.pivot = new Vector2(0.5f, 0.5f);

                        rtBtn.sizeDelta = new Vector2(90f, 24f); // NPC adet kutusundakiyle aynı boyut (90 x 24)

                        rtBtn.anchoredPosition = new Vector2(0f, -35f); // Tam ortalı alt konum

                    }

                    if (img != null)

                    {

                        // Yeşil dolgulu, yeşil çerçeveli ve sharp köşeli buton stilini ata

                        img.sprite = GetSkillThemeRoundedRectSprite("dead_btn_ok_green", 90, 24, 0, // 0 = sharp köşeler

                            new Color(0.12f, 0.28f, 0.12f, 0.95f), // Yeşil dolgu

                            new Color(0.25f, 0.55f, 0.25f, 0.95f), // Yeşil çerçeve

                            1); // 1px kalınlık

                        img.color = Color.white;

                        img.enabled = true;

                        img.raycastTarget = true;

                    }

                    _textTown.gameObject.SetActive(true);

                    _textTown.text = "OK";

                    _textTown.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");

                    _textTown.fontSize = 12;

                    _textTown.color = new Color(0.95f, 0.92f, 0.85f); // Açık krem/beyaz renk

                    _textTown.fontStyle = FontStyle.Bold;

                    _textTown.alignment = TextAnchor.MiddleCenter;

                    AddSkillThemeTextShadow(_textTown);

                }

            }

            catch (System.Exception ex)

            {

                Debug.LogError($"[KOUIMGR] Error modernizing Dead Panel: {ex.Message}");

            }

        }

        /// <summary>

        /// Inventory text referanslarını ve butonlarını bağlar.

        /// C++ referans: UIInventory.cpp InitIconWnd() satır 365-392, ReceiveMessage() satır 1517-1534

        /// </summary>

        private void BindInventoryElements(Transform root)

        {

            // C++ UIInventory.cpp satır 158: GetChildByID<CN3UIString>("text_gold")

            _textGold = KOUIRenderer.FindChildText(root, "text_gold");

            // C++ UIInventory.cpp satır 375: m_pText_Weight = GetChildByID<CN3UIString>("text_weight")

            _textWeight = KOUIRenderer.FindChildText(root, "text_weight");

            // C++ UIInventory.cpp satır 1517-1523: ReceiveMessage() → btn_close → Close()

            var btnClose = KOUIRenderer.FindChildButton(root, "btn_close");

            if (btnClose != null)

            {

                btnClose.onClick.AddListener(() =>

                {

                    // C++ UIInventory.cpp satır 1519-1523: Close()

                    ShowInventory(false);

                });

            }

            // C++ birebir: UIInventory.cpp — m_pUIINV_MsgBox (gömülü destroy onay diyaloğu)

            // Inventory UIF'inin içinde gömülü bir child Base paneli var:

            //   text_msg + btn_ok + btn_cancel

            // Bu panel sadece item destroy onayında gösterilir, varsayılan gizli olmalı.

            // C++ birebir: m_pUIINV_MsgBox->SetVisible(false) — Init'te gizle

            HideEmbeddedMsgBoxChildren(root);

            // Mobil adaptasyon: Arka plan ve dekoratif görsellerin raycast target'larını kapat

            // Böylece altlarındaki veya üstlerindeki slotlara tıklama engellenmez.

            CleanupInventoryRaycastTargets(root);

            // Tasarım özgünleştirme (Koyu premium tema, altın detaylar, özel butonlar)

            ModernizeInventoryPanel(root);

        }

                private Sprite GetTrashCanIcon()

        {

            string key = "trash_can_icon";

            if (_skillThemeSpriteCache.TryGetValue(key, out Sprite sp))

                return sp;

            int w = 32;

            int h = 32;

            Texture2D tex = new Texture2D(w, h, TextureFormat.RGBA32, false);

            tex.filterMode = FilterMode.Bilinear;

            tex.wrapMode = TextureWrapMode.Clamp;

            Color gold = new Color(0.85f, 0.75f, 0.35f, 0.9f);

            Color clear = Color.clear;

            for (int y = 0; y < h; y++)

            {

                for (int x = 0; x < w; x++)

                {

                    bool paint = false;

                    if (y >= 26 && y <= 28 && x >= 13 && x <= 18)

                    {

                        if (y == 28 || x == 13 || x == 18) paint = true;

                    }

                    else if (y >= 23 && y <= 25 && x >= 6 && x <= 25)

                    {

                        paint = true;

                    }

                    else if (y >= 4 && y <= 21)

                    {

                        int dx = (int)((21 - y) * 0.06f);

                        int lx = 8 + dx;

                        int rx = 23 - dx;

                        if (x >= lx && x <= rx)

                        {

                            if (x == lx || x == rx || y == 4)

                            {

                                paint = true;

                            }

                            else if (y >= 7 && y <= 18)

                            {

                                if (x == 11 || x == 15 || x == 19)

                                {

                                    paint = true;

                                }

                            }

                        }

                    }

                    tex.SetPixel(x, y, paint ? gold : clear);

                }

            }

            tex.Apply();

            Sprite sprite = Sprite.Create(tex, new Rect(0, 0, w, h), new Vector2(0.5f, 0.5f));

            _skillThemeSpriteCache[key] = sprite;

            return sprite;

        }

        private Sprite GetNoahCoinIcon()

        {

            string key = "noah_coin_icon_v2";

            if (_skillThemeSpriteCache.TryGetValue(key, out Sprite sp))

                return sp;

            int w = 32;

            int h = 32;

            Texture2D tex = new Texture2D(w, h, TextureFormat.RGBA32, false);

            tex.filterMode = FilterMode.Bilinear;

            tex.wrapMode = TextureWrapMode.Clamp;

            Color goldDark = new Color(0.6f, 0.45f, 0.15f, 1f);

            Color goldMid = new Color(0.85f, 0.7f, 0.2f, 1f);

            Color goldBright = new Color(0.98f, 0.9f, 0.5f, 1f);

            Color clear = Color.clear;

            float cx = 16f;

            float cy = 16f;

            float rOuter = 14f;

            float rInner = 11f;

            for (int y = 0; y < h; y++)

            {

                for (int x = 0; x < w; x++)

                {

                    float dx = x - cx;

                    float dy = y - cy;

                    float dist = Mathf.Sqrt(dx * dx + dy * dy);

                    if (dist > rOuter)

                    {

                        tex.SetPixel(x, y, clear);

                    }

                    else if (dist >= rInner && dist <= rOuter)

                    {

                        float angle = Mathf.Atan2(dy, dx);

                        float reflection = Mathf.Sin(angle * 2f + 1f);

                        Color c = Color.Lerp(goldDark, goldBright, (reflection + 1f) * 0.5f);

                        tex.SetPixel(x, y, c);

                    }

                    else

                    {

                        bool isN = false;

                        float lx = dx + 3f;

                        float rx = dx - 3f;

                        if (Mathf.Abs(lx) < 1.2f && Mathf.Abs(dy) <= 5.5f) isN = true;

                        else if (Mathf.Abs(rx) < 1.2f && Mathf.Abs(dy) <= 5.5f) isN = true;

                        else if (dx >= -3f && dx <= 3f)

                        {

                            float lineY = -1.8f * dx;

                            if (Mathf.Abs(dy - lineY) < 1.5f) isN = true;

                        }

                        if (isN)

                        {

                            tex.SetPixel(x, y, goldBright);

                        }

                        else

                        {

                            float grad = (dy + 11f) / 22f;

                            Color c = Color.Lerp(goldDark, goldMid, grad);

                            tex.SetPixel(x, y, c);

                        }

                    }

                }

            }

            tex.Apply();

            sp = Sprite.Create(tex, new Rect(0, 0, w, h), new Vector2(0.5f, 0.5f));

            _skillThemeSpriteCache[key] = sp;

            return sp;

        }

        private Sprite GetSortIcon()

        {

            string key = "sort_inventory_icon_v2";

            if (_skillThemeSpriteCache.TryGetValue(key, out Sprite sp))

                return sp;

            int w = 128;

            int h = 128;

            Texture2D tex = new Texture2D(w, h, TextureFormat.RGBA32, false);

            tex.filterMode = FilterMode.Bilinear;

            tex.wrapMode = TextureWrapMode.Clamp;

            Color gold = new Color(0.85f, 0.75f, 0.35f, 0.9f);

            float cx = 64f;

            float cy = 64f;

            float rOut = 44f;

            float rIn = 32f;

            float smooth = 1.5f;

            // Arrowhead vertices (pointing counter-clockwise at 45 degree edge)

            float x1 = 64f + 38f * Mathf.Cos(30f * Mathf.Deg2Rad);

            float y1 = 64f + 38f * Mathf.Sin(30f * Mathf.Deg2Rad);

            float x2 = 64f + 48f * Mathf.Cos(45f * Mathf.Deg2Rad);

            float y2 = 64f + 48f * Mathf.Sin(45f * Mathf.Deg2Rad);

            float x3 = 64f + 28f * Mathf.Cos(45f * Mathf.Deg2Rad);

            float y3 = 64f + 28f * Mathf.Sin(45f * Mathf.Deg2Rad);

            bool PointInTriangle(float px, float py, float tx1, float ty1, float tx2, float ty2, float tx3, float ty3)

            {

                float d1 = (px - tx2) * (ty1 - ty2) - (tx1 - tx2) * (py - ty2);

                float d2 = (px - tx3) * (ty2 - ty3) - (tx2 - tx3) * (py - ty3);

                float d3 = (px - tx1) * (ty3 - ty1) - (tx3 - tx1) * (py - ty1);

                bool has_neg = (d1 < 0) || (d2 < 0) || (d3 < 0);

                bool has_pos = (d1 > 0) || (d2 > 0) || (d3 > 0);

                return !(has_neg && has_pos);

            }

            for (int y = 0; y < h; y++)

            {

                for (int x = 0; x < w; x++)

                {

                    float dx = x - cx;

                    float dy = y - cy;

                    float dist = Mathf.Sqrt(dx * dx + dy * dy);

                    // Smooth antialiasing for the ring

                    float ringAlpha = Mathf.Min(

                        Mathf.Clamp01((rOut - dist) / smooth),

                        Mathf.Clamp01((dist - rIn) / smooth)

                    );

                    // Angle in degrees (0 to 360)

                    float angle = Mathf.Atan2(dy, dx) * Mathf.Rad2Deg;

                    if (angle < 0) angle += 360f;

                    // Create the gap between 45 and 105 degrees

                    float gapAlpha = 1.0f;

                    if (angle >= 45f && angle <= 105f)

                    {

                        gapAlpha = 0f;

                    }

                    else

                    {

                        float d45 = Mathf.Abs(angle - 45f);

                        if (d45 > 180f) d45 = 360f - d45;

                        float d105 = Mathf.Abs(angle - 105f);

                        if (d105 > 180f) d105 = 360f - d105;

                        float edgeDist = Mathf.Min(d45, d105);

                        if (edgeDist < 3.0f)

                        {

                            gapAlpha = edgeDist / 3.0f;

                        }

                    }

                    float finalRing = ringAlpha * gapAlpha;

                    // Arrowhead alpha

                    float arrowAlpha = PointInTriangle(x, y, x1, y1, x2, y2, x3, y3) ? 1.0f : 0f;

                    float combinedAlpha = Mathf.Max(finalRing, arrowAlpha);

                    Color pixelColor = gold;

                    pixelColor.a *= combinedAlpha;

                    tex.SetPixel(x, y, pixelColor);

                }

            }

            tex.Apply();

            Sprite sprite = Sprite.Create(tex, new Rect(0, 0, w, h), new Vector2(0.5f, 0.5f));

            _skillThemeSpriteCache[key] = sprite;

            return sprite;

        }

