        private void ModernizeInventoryMsgBox(Transform root)

        {

            var allTexts = root.GetComponentsInChildren<Text>(true);

            foreach (var txt in allTexts)

            {

                if (txt.gameObject.name == "text_msg" || txt.gameObject.name == "string_Destroy" || (txt.text != null && txt.text.Contains("destroy")))

                {

                    Transform panel = txt.transform.parent;

                    while (panel != null && panel != root)

                    {

                        bool hasOk = false, hasCancel = false;

                        foreach (Transform ch in panel)

                        {

                            string n = ch.gameObject.name.ToLowerInvariant();

                            if (n.Contains("btn_ok") || n == "ok") hasOk = true;

                            if (n.Contains("btn_cancel") || n.Contains("cancel")) hasCancel = true;

                        }

                        if (hasOk || hasCancel)

                        {

                            var bgImg = panel.GetComponent<Image>();

                            var imgDestroyTr = panel.Find("img_Destroy");

                            if (imgDestroyTr != null)

                            {

                                var rawImg = imgDestroyTr.GetComponent<RawImage>();

                                if (rawImg != null)

                                {

                                    DestroyImmediate(rawImg);

                                }

                                bgImg = imgDestroyTr.GetComponent<Image>() ?? imgDestroyTr.gameObject.AddComponent<Image>();

                            }

                            if (bgImg != null)

                            {

                                var panelRT = panel.GetComponent<RectTransform>();

                                int pw = panelRT != null ? (int)panelRT.rect.width : 280;

                                int ph = panelRT != null ? (int)panelRT.rect.height : 120;

                                bgImg.sprite = GetSkillThemePanelBgSprite("inv_msgbox_bg", pw, ph, 4,

                                    new Color(0.15f, 0.12f, 0.10f, 0.95f),

                                    new Color(0.06f, 0.05f, 0.05f, 0.95f),

                                    new Color(0.6f, 0.48f, 0.22f, 0.9f),

                                    2);

                                bgImg.color = Color.white;

                            }

                            var btnOk = KOUIRenderer.FindChildButton(panel, "btn_ok") ?? KOUIRenderer.FindChildButton(panel, "ok");

                            if (btnOk != null)

                            {

                                var rt = btnOk.GetComponent<RectTransform>();

                                if (rt != null) rt.sizeDelta = new Vector2(90f, 24f);

                                SetButtonThemeSprite(btnOk, GetSkillThemeRoundedRectSprite("inv_msgbox_btn_ok_green", 90, 24, 0, // sharp

                                    new Color(0.12f, 0.28f, 0.12f, 0.95f), // Green

                                    new Color(0.25f, 0.55f, 0.25f, 0.95f), // Green border

                                    1));

                                var btnTxt = btnOk.GetComponentInChildren<Text>();

                                if (btnTxt != null)

                                {

                                    btnTxt.color = new Color(0.95f, 0.92f, 0.85f); // Açık krem

                                    btnTxt.fontStyle = FontStyle.Bold;

                                    AddSkillThemeTextShadow(btnTxt);

                                }

                            }

                            var btnCancel = KOUIRenderer.FindChildButton(panel, "btn_cancel") ?? KOUIRenderer.FindChildButton(panel, "cancel");

                            if (btnCancel != null)

                            {

                                var rt = btnCancel.GetComponent<RectTransform>();

                                if (rt != null) rt.sizeDelta = new Vector2(90f, 24f);

                                SetButtonThemeSprite(btnCancel, GetSkillThemeRoundedRectSprite("inv_msgbox_btn_cancel_red", 90, 24, 0, // sharp

                                    new Color(0.45f, 0.05f, 0.08f, 0.95f), // Red

                                    new Color(0.75f, 0.15f, 0.15f, 0.95f), // Red border

                                    1));

                                var btnTxt = btnCancel.GetComponentInChildren<Text>();

                                if (btnTxt != null)

                                {

                                    btnTxt.color = new Color(0.95f, 0.92f, 0.85f); // Açık krem

                                    btnTxt.fontStyle = FontStyle.Bold;

                                    AddSkillThemeTextShadow(btnTxt);

                                }

                            }

                            txt.color = new Color(0.9f, 0.85f, 0.75f, 1f);

                            AddSkillThemeTextShadow(txt);

                            txt.fontSize = 11;

                            txt.alignment = TextAnchor.MiddleCenter;

                            return;

                        }

                        panel = panel.parent;

                    }

                }

            }

        }

        /// <summary>

        /// Inventory panelindeki tüm arka plan ve dekoratif görsellerin raycastTarget özelliğini kapatır.

        /// Böylece giyili eşya slotları (EqSlot) raycast engeline takılmadan tıklanabilir.

        /// </summary>

        private void CleanupInventoryRaycastTargets(Transform root)

        {

/* Loop Removed */

/* Loop Removed */

            var texts = root.GetComponentsInChildren<Text>(true);

