        /// <summary>

        /// Inventory UIF'inin içinde gömülü child MsgBox panellerini gizler.

        /// C++ birebir: UIInventory.cpp — m_pUIINV_MsgBox (co_MsgBoxOkCancel child Base)

        /// Bu child'lar "text_msg" text'i ve "btn_ok" + "btn_cancel" butonları içerir.

        /// Varsayılan gizli olmalı — sadece item destroy onayında ShowYesNo() ile açılır.

        /// </summary>

        private void HideEmbeddedMsgBoxChildren(Transform root)

        {

            // Tüm descendant'ları tara — gömülü MsgBox herhangi bir derinlikte olabilir

            var allTexts = root.GetComponentsInChildren<Text>(true);

            foreach (var txt in allTexts)

            {

                // "Would you like to destroy" veya "text_msg" ID'li text'i bul

                if (txt.gameObject.name == "text_msg" ||

                    (txt.text != null && txt.text.Contains("destroy")))

                {

                    // Bu text'in ait olduğu en yakın "Base" parent'ını bul

                    // (inventory root'un kendisi olmasın)

                    Transform panel = txt.transform.parent;

                    while (panel != null && panel != root)

                    {

                        // Bu panel'in altında btn_ok veya btn_cancel varsa → MsgBox paneli

                        bool hasOk = false, hasCancel = false;

                        foreach (Transform ch in panel)

                        {

                            string n = ch.gameObject.name.ToLowerInvariant();

                            if (n.Contains("btn_ok") || n == "ok") hasOk = true;

                            if (n.Contains("btn_cancel") || n.Contains("cancel")) hasCancel = true;

                        }

                        if (hasOk || hasCancel)

                        {

                            if (panel.name == "area_samma")

                            {

                                // area_samma'nın kendisini kapatma! Sadece içindeki kullanılmayan onay kutusu elemanlarını kapat.

                                foreach (Transform ch in panel)

                                {

                                    ch.gameObject.SetActive(false);

                                }

                            }

                            else

                            {

                                panel.gameObject.SetActive(false);

                            }

                            return; // Bulduk, çık

                        }

                        panel = panel.parent;

                    }

                    // Parent bulunamadıysa text'in kendi parent'ını gizle

                    if (txt.transform.parent != null && txt.transform.parent != root)

                    {

                        txt.transform.parent.gameObject.SetActive(false);

                        return;

                    }

                }

            }

        }

        /// <summary>

        /// UIVarious (karakter bilgi paneli) text referanslarını bağlar.

        /// C++ referans: UIVarious.cpp Load() satır 119-167

        /// </summary>

        private void BindVariousElements(Transform root)

        {

            bool isModern = IsModernPrefab(root);

            // 1. Karakter info panelinin arka planını, kapatma butonunu ve başlıklarını temala (Skilltree ile aynı tasarım)

            ApplyVariousUITheme(root);

            // 2. Kalan sekmeleri simetrik hizala ve Quest sekmesini kaldır

            var btnState = KOUIRenderer.FindChildButton(root, "btn_state");

            var btnQuest = KOUIRenderer.FindChildButton(root, "btn_quest");

            var btnClan = KOUIRenderer.FindChildButton(root, "btn_clan");

            var btnFriends = KOUIRenderer.FindChildButton(root, "btn_friends");

            if (btnQuest != null && !isModern) btnQuest.gameObject.SetActive(false);

            if (btnState != null && btnClan != null && btnFriends != null && !isModern)

            {

                btnState.transform.SetParent(root, false);

                btnClan.transform.SetParent(root, false);

                btnFriends.transform.SetParent(root, false);

                var rtState = btnState.GetComponent<RectTransform>();

                var rtClan = btnClan.GetComponent<RectTransform>();

                var rtFriends = btnFriends.GetComponent<RectTransform>();

                if (rtState != null && rtClan != null && rtFriends != null)

                {

                    float height = 30f; // Yükseklik 30px yapıldı

                    float width = 95f;  // Genişlik 95px yapıldı (3 * 95 + 2 * 1 = 287px)

                    float margin = 3f;  // Sol boşluk 3px

                    float marginTop = 2f; // Üst boşluk 2px yapıldı

                    float gap = 1f;     // Sekmeler arası 1px boşluk

                    rtState.anchorMin = new Vector2(0f, 1f);

                    rtState.anchorMax = new Vector2(0f, 1f);

                    rtState.pivot = new Vector2(0f, 1f);

                    rtState.sizeDelta = new Vector2(width, height);

                    rtState.anchoredPosition = new Vector2(margin, -marginTop);

                    rtClan.anchorMin = new Vector2(0f, 1f);

                    rtClan.anchorMax = new Vector2(0f, 1f);

                    rtClan.pivot = new Vector2(0f, 1f);

                    rtClan.sizeDelta = new Vector2(width, height);

                    rtClan.anchoredPosition = new Vector2(margin + width + gap, -marginTop);

                    rtFriends.anchorMin = new Vector2(0f, 1f);

                    rtFriends.anchorMax = new Vector2(0f, 1f);

                    rtFriends.pivot = new Vector2(0f, 1f);

                    rtFriends.sizeDelta = new Vector2(width, height);

                    rtFriends.anchoredPosition = new Vector2(margin + (width + gap) * 2f, -marginTop);

                }

            }

            // 3. Paneldeki statik yazıları (etiketleri) gold yap, değerleri krem renge boya

            ModernizeVariousTexts(root);

            // ================================================

            // C++ birebir: UIVarious.cpp:1463-1506 — Load()

            // _uiVarious (el_various_all_us.uif) root'undan child page'leri ve butonları bul

            // ================================================

            // C++ birebir: m_pPageState = page_state Base child

            var pageStateTr = KOUIRenderer.FindChildByID(root, "page_state");

            if (pageStateTr != null)

            {

                _uiPageState = pageStateTr.gameObject;

            }

            // C++ UIVarious.cpp satır 124-126 — page_state altındaki text'ler

            _textID = KOUIRenderer.FindChildText(root, "text_Id");

            _textLevel = KOUIRenderer.FindChildText(root, "Text_Level");

            _textRealmPoint = KOUIRenderer.FindChildText(root, "Text_RealmPoint");

            // C++ UIVarious.cpp satır 128-130

            _textClass = KOUIRenderer.FindChildText(root, "Text_Class");

            _textRace = KOUIRenderer.FindChildText(root, "Text_Race");

            _textNation = KOUIRenderer.FindChildText(root, "Text_Nation");

            // C++ UIVarious.cpp satır 132-137 — Various paneldeki HP/MP/Exp/AP/GP/Weight

            _textVarHP = KOUIRenderer.FindChildText(root, "Text_HP");

            _textVarMP = KOUIRenderer.FindChildText(root, "Text_MP");

            _textVarExp = KOUIRenderer.FindChildText(root, "Text_Exp");

            _textAP = KOUIRenderer.FindChildText(root, "Text_AP");

            _textGP = KOUIRenderer.FindChildText(root, "Text_GP");

            // C++ UIVarious.cpp satır 139

            _textBonusPoint = KOUIRenderer.FindChildText(root, "Text_BonusPoint");

            // C++ UIVarious.cpp satır 147-151

            _textStrength = KOUIRenderer.FindChildText(root, "Text_Strength");

            _textStamina = KOUIRenderer.FindChildText(root, "Text_Stamina");

            _textDexterity = KOUIRenderer.FindChildText(root, "Text_Dexterity");

            _textMagicAttack = KOUIRenderer.FindChildText(root, "Text_MagicAttack");

            _textIntelligence = KOUIRenderer.FindChildText(root, "Text_Intelligence");

            // C++ UIVarious.cpp satır 153-158: Resist text'leri

            _textRegistFire = KOUIRenderer.FindChildText(root, "Text_RegistFire");

            _textRegistMagic = KOUIRenderer.FindChildText(root, "Text_RegistMagic");

            _textRegistIce = KOUIRenderer.FindChildText(root, "Text_RegistIce");

            _textRegistCurse = KOUIRenderer.FindChildText(root, "Text_RegistCurse");

            _textRegistLight = KOUIRenderer.FindChildText(root, "Text_RegistLightR");

            _textRegistPoison = KOUIRenderer.FindChildText(root, "Text_RegistPoison");

            int bound = 0;

            if (_textID != null) bound++;

            if (_textLevel != null) bound++;

            if (_textStrength != null) bound++;

            if (_textStamina != null) bound++;

            if (_textDexterity != null) bound++;

            if (_textIntelligence != null) bound++;

            if (_textMagicAttack != null) bound++;

            // C++ UIVarious.cpp satır 483-492 birebir: STR=0x01, STA=0x02, DEX=0x03, INT=0x04, CHA=0x05

            _btnStatStr = BindStatButton(root, "btn_strength", 0x01, "STR");

            _btnStatSta = BindStatButton(root, "btn_stamina", 0x02, "STA");

            _btnStatDex = BindStatButton(root, "btn_Dexterity", 0x03, "DEX");

            _btnStatInt = BindStatButton(root, "btn_Intelligence", 0x04, "INT");

            _btnStatCha = BindStatButton(root, "btn_MagicAttack", 0x05, "CHA");

            if (_btnStatStr != null) _btnStatStr.SetActive(false);

            if (_btnStatSta != null) _btnStatSta.SetActive(false);

            if (_btnStatDex != null) _btnStatDex.SetActive(false);

            if (_btnStatInt != null) _btnStatInt.SetActive(false);

            if (_btnStatCha != null) _btnStatCha.SetActive(false);

            CreateStatDistributionPanel(root);

            // ================================================

            // C++ birebir: UIVarious.cpp:1468-1472 — Tab butonları

            // btn_state, btn_quest, btn_clan (knights), btn_friends, btn_close

            // ================================================

            BindVariousTabButton(root, "btn_state",   "page_state");

            BindVariousTabButton(root, "btn_clan",    "page_knights");

            BindVariousTabButton(root, "btn_friends", "page_friend");

            // C++ birebir: btn_close → Close()

            var btnClose = KOUIRenderer.FindChildButton(root, "btn_close");

            if (btnClose != null)

            {

                btnClose.onClick.AddListener(() => { ToggleCharacterInfo(); });

            }

            // C++ birebir: UIVarious.cpp:1506 — UpdatePageButtons(m_pBtn_State)

            // İlk açılışta sadece page_state göster, diğerleri gizli

            UpdateVariousPage(root, "page_state");

        }

        public void ApplyVariousUITheme(Transform root)

        {

            var rootRT = root.GetComponent<RectTransform>();

            if (rootRT == null) return;

            bool isModern = IsModernPrefab(root);

            if (!isModern)

            {

                // 1. Çakışan arka plan ve çerçeve resimlerini devre dışı bırak

                CleanupLegacyUIGraphics(root);

                // 2. Orijinal arka plan resmini (Image veya RawImage) gizle veya saydam yap

                ClearGraphicComponent(root);

                // Sayfaların kendi arka planlarını da temizle

                var pageState = root.Find("page_state");

                if (pageState != null) ClearGraphicComponent(pageState);

                var pageKnights = root.Find("page_knights");

                if (pageKnights != null) ClearGraphicComponent(pageKnights);

                var pageFriend = root.Find("page_friend");

                if (pageFriend != null) ClearGraphicComponent(pageFriend);

                // 1.1 frame altındaki tüm gereksiz nesneleri (kopya butonlar, eski arka planlar, yazılar) tamamen kapat

                var frameTr = root.Find("frame");

                if (frameTr != null)

                {

                    foreach (Transform child in frameTr)

                    {

                        if (child.name != "btn_state" && child.name != "btn_clan" && child.name != "btn_friends" && child.name != "btn_close")

                        {

                            child.gameObject.SetActive(false);

                        }

                    }

                }

            }

            // 2. Koyu bronz zemin ve altın sarısı çerçeve için özel arka plan oluştur/bul

            var customBg = root.Find("VariousCustomBg")?.gameObject;

            Image bgImg = null;

            if (customBg == null)

            {

                customBg = new GameObject("VariousCustomBg");

                customBg.transform.SetParent(root, false);

                customBg.transform.SetAsFirstSibling(); // En arkada durması için

                bgImg = customBg.AddComponent<Image>();

                var rt = customBg.GetComponent<RectTransform>();

                if (rt != null && !isModern)

                {

                    rt.anchorMin = Vector2.zero;

                    rt.anchorMax = Vector2.one;

                    rt.offsetMin = Vector2.zero;

                    rt.offsetMax = Vector2.zero;

                }

            }

            else

            {

                bgImg = customBg.GetComponent<Image>();

            }

            if (bgImg != null)

            {

                // Skill Book ile aynı şık bronz-altın gradyan arka planı giydir

                bgImg.sprite = GetSkillThemePanelBgSprite("various_bg", (int)rootRT.rect.width, (int)rootRT.rect.height, 0,

                    new Color(0.12f, 0.10f, 0.08f, 0.98f),

                    new Color(0.04f, 0.04f, 0.04f, 0.98f),

                    new Color(0.6f, 0.48f, 0.22f, 0.9f),

                    2);

            }

            // 3. Kapatma butonunu stilize et ve sağ üst köşeye al

            var btnClose = KOUIRenderer.FindChildButton(root, "btn_close");

            if (btnClose != null)

            {

                if (!isModern)

                {

                    btnClose.transform.SetParent(root, false);

                }

                SetButtonThemeSprite(btnClose, GetSkillThemeRoundedRectSprite("various_close_btn", 30, 30, 0,

                    new Color(0.18f, 0.18f, 0.18f, 1f),

                    new Color(0.45f, 0.35f, 0.15f, 1f),

                    1));

                var rtClose = btnClose.GetComponent<RectTransform>();

                if (rtClose != null && !isModern)

                {

                    rtClose.anchorMin = new Vector2(1f, 1f);

                    rtClose.anchorMax = new Vector2(1f, 1f);

                    rtClose.pivot = new Vector2(1f, 1f);

                    rtClose.anchoredPosition = new Vector2(-2f, -2f); // Sağ ve üst boşluk 2px

                    rtClose.sizeDelta = new Vector2(30f, 30f);

                }

                var btnTxt = btnClose.GetComponentInChildren<Text>();

                if (btnTxt == null)

                {

                    var txtObj = new GameObject("Text");

                    txtObj.transform.SetParent(btnClose.transform, false);

                    btnTxt = txtObj.AddComponent<Text>();

                    btnTxt.text = "X";

                    btnTxt.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");

                    btnTxt.alignment = TextAnchor.MiddleCenter;

                    var txtRT = txtObj.GetComponent<RectTransform>();

                    txtRT.anchorMin = Vector2.zero;

                    txtRT.anchorMax = Vector2.one;

                    txtRT.offsetMin = Vector2.zero;

                    txtRT.offsetMax = Vector2.zero;

                }

                if (btnTxt != null)

                {

                    btnTxt.color = new Color(0.9f, 0.75f, 0.25f, 1f);

                    btnTxt.fontStyle = FontStyle.Bold;

                    btnTxt.fontSize = 14;

                    AddSkillThemeTextShadow(btnTxt);

                }

            }

            // 4. Panel altındaki tüm diğer alt butonları ve sayfa oklarını stilize et

            ModernizePanelButtons(root);

        }

        private void CleanupLegacyUIGraphics(Transform parent)

        {

            foreach (Transform child in parent)

            {

                if (child.name == "VariousCustomBg") continue;

                // ui_String_ hariç tüm otomatik üretilmiş legacy görsel/alan nesnelerini kapat

                if ((child.name.StartsWith("ui_") && !child.name.StartsWith("ui_String_")) ||

                    child.name.ToLower().Contains("background") || child.name.ToLower().Contains("border"))

                {

                    child.gameObject.SetActive(false);

                }

                else

                {

                    CleanupLegacyUIGraphics(child);

                }

            }

        }

        private void ClearGraphicComponent(Transform t)

        {

            if (t == null) return;

            var img = t.GetComponent<Image>();

            if (img != null)

            {

                img.color = Color.clear;

                img.sprite = null;

            }

            var raw = t.GetComponent<RawImage>();

            if (raw != null)

            {

                raw.color = Color.clear;

                raw.texture = null;

            }

        }

        private void ModernizePanelButtons(Transform parent)

        {

            var buttons = parent.GetComponentsInChildren<Button>(true);

            var btnBgSprite = GetSkillThemeRoundedRectSprite("various_sub_btn_bg", 64, 20, 0,

                new Color(0.18f, 0.14f, 0.10f, 1f),

                new Color(0.5f, 0.4f, 0.18f, 1f),

                1);

            var arrowBgSprite = GetSkillThemeRoundedRectSprite("various_sub_arrow_bg", 20, 20, 0,

                new Color(0.18f, 0.14f, 0.10f, 1f),

                new Color(0.5f, 0.4f, 0.18f, 1f),

                1);

            foreach (var btn in buttons)

            {

                // Skip buttons in our custom distribution panels

                if (btn.transform.parent != null &&

                    (btn.transform.parent.name.StartsWith("Row_") || btn.transform.parent.name.StartsWith("StatRow_") ||

                     btn.transform.parent.parent?.name == "StatDistributionPanel" ||

                     btn.transform.parent.parent?.name == "SkillDistributionPanel"))

                {

                    continue;

                }

                // Zaten elle stilize ettiğimiz ana sekme butonları veya kapatma butonunu es geç

                if (btn.gameObject.name == "btn_state" || btn.gameObject.name == "btn_clan" ||

                    btn.gameObject.name == "btn_friends" || btn.gameObject.name == "btn_close")

                {

                    continue;

                }

                // Stat dağıtma butonları ("P" butonları) ise bunları "+" butonu olarak ayarla

                if (btn.gameObject.name.StartsWith("btn_", System.StringComparison.OrdinalIgnoreCase) &&

                    (btn.gameObject.name.Contains("strength") || btn.gameObject.name.Contains("stamina") ||

                     btn.gameObject.name.Contains("Dexterity") || btn.gameObject.name.Contains("Intelligence") ||

                     btn.gameObject.name.Contains("MagicAttack")))

                {

                    SetButtonThemeSprite(btn, GetSkillThemeRoundedRectSprite("btn_plus", 14, 14, 0, new Color(0.25f, 0.2f, 0.05f, 1), Color.clear, 0));

                    var txt = btn.GetComponentInChildren<Text>();

                    if (txt != null)

                    {

                        txt.text = "+";

                        txt.color = new Color(0.95f, 0.85f, 0.35f, 1);

                        txt.fontStyle = FontStyle.Bold;

                        txt.fontSize = 10;

                    }

                    continue;

                }

                // Ok/Sayfa geçiş butonları ise dairesel/ufak kare buton yap

                if (btn.gameObject.name.ToLower().Contains("noclan"))
                {
                    continue; // Özel no-clan buton tasarımlarımızı ezme
                }

                if (btn.gameObject.name.Contains("page") || btn.gameObject.name == "btn_clan_up" || btn.gameObject.name == "btn_clan_down" || btn.gameObject.name.StartsWith("btn_page"))

                {

                    SetButtonThemeSprite(btn, arrowBgSprite);

                    var txt = btn.GetComponentInChildren<Text>();

                    if (txt != null)

                    {

                        txt.color = new Color(0.9f, 0.75f, 0.25f);

                        txt.fontStyle = FontStyle.Bold;

                        txt.fontSize = 10;

                    }

                }

                else

                {

                    // Genel alt işlem butonları (Refresh, Invite, Join, Ban, Whisper, Delete vb.)

                    SetButtonThemeSprite(btn, btnBgSprite);

                    var txt = btn.GetComponentInChildren<Text>();

                    if (txt != null)

                    {

                        txt.color = new Color(0.9f, 0.75f, 0.25f);

                        txt.fontStyle = FontStyle.Bold;

                        txt.fontSize = 9;

                        AddSkillThemeTextShadow(txt);

                    }

                }

            }

        }

        private void CleanupClanLinesAndBorders(Transform root)

        {

            var pages = new string[] { "page_knights", "page_Clan", "page_clan" };

            foreach (var pageId in pages)

            {

                var page = EntropyOnline.Import.KOUIRenderer.FindChildByID(root, pageId);

                if (page == null) continue;

                // Deactivate legacy background images containing lines, borders and button shapes

                var imgKnight = page.Find("img_knight");

                if (imgKnight != null) imgKnight.gameObject.SetActive(false);

                var imgGrade0 = page.Find("image_grade00");

                if (imgGrade0 != null) imgGrade0.gameObject.SetActive(false);

                var imgGrade1 = page.Find("image_grade01");

                if (imgGrade1 != null) imgGrade1.gameObject.SetActive(false);

                var imgGrade2 = page.Find("image_grade02");

                if (imgGrade2 != null) imgGrade2.gameObject.SetActive(false);

                var imgGrade3 = page.Find("image_grade03");

                if (imgGrade3 != null) imgGrade3.gameObject.SetActive(false);

                // Style button text labels to match modernized theme (gold and bold)

                var textsToStyle = new string[] { "text_clan_admit_a", "text_clan_appoint_a", "text_clan_remove_a" };

                foreach (var txtId in textsToStyle)

                {

                    var txtObj = EntropyOnline.Import.KOUIRenderer.FindChildByID(page, txtId);

                    if (txtObj != null)

                    {

                        var txtComp = txtObj.GetComponent<Text>();

                        if (txtComp != null)

                        {

                            txtComp.color = new Color(0.85f, 0.72f, 0.44f, 1f); // Gold

                            txtComp.fontStyle = FontStyle.Bold;

                        }

                    }

                }

            }

        }

        private void UpdateVariousTabStyles(Transform root, string activePageId)

        {

            var btnState = KOUIRenderer.FindChildButton(root, "btn_state");

            var btnClan = KOUIRenderer.FindChildButton(root, "btn_clan");

            var btnFriends = KOUIRenderer.FindChildButton(root, "btn_friends");

            if (btnState == null || btnClan == null || btnFriends == null) return;

            float height = 30f;

            float width = 95f;      // Genişlik 95px yapıldı (3 * 95 + 2 * 1 = 287px)

            float margin = 3f;      // Sol boşluk 3px

            float marginTop = 2f;   // Üst boşluk 2px yapıldı

            float gap = 1f;         // Sekmeler arası 1px boşluk

            var activeSprite = GetSkillThemeRoundedRectSprite("various_tab_active", (int)width, (int)height, 0, new Color(0.28f, 0.22f, 0.08f, 1), Color.clear, 0);

            var inactiveSprite = GetSkillThemeRoundedRectSprite("various_tab_inactive", (int)width, (int)height, 0, new Color(0.08f, 0.08f, 0.08f, 0.9f), Color.clear, 0);

            UpdateSingleTabStyle(btnState, activePageId == "page_state", activeSprite, inactiveSprite, "CHARACTER");

            UpdateSingleTabStyle(btnClan, activePageId == "page_knights" || activePageId == "page_Clan" || activePageId == "page_clan", activeSprite, inactiveSprite, "CLAN");

            UpdateSingleTabStyle(btnFriends, activePageId == "page_friend", activeSprite, inactiveSprite, "FRIENDS");

            // Sekmeler: sol boşluk 3px, üst boşluk 2px, sekmeler 95px, araları 1px, yükseklik 30px.

            var rtState = btnState.GetComponent<RectTransform>();

            var rtClan = btnClan.GetComponent<RectTransform>();

            var rtFriends = btnFriends.GetComponent<RectTransform>();

            if (rtState != null && rtClan != null && rtFriends != null)

            {

                rtState.anchorMin = new Vector2(0f, 1f);

                rtState.anchorMax = new Vector2(0f, 1f);

                rtState.pivot = new Vector2(0f, 1f);

                rtState.sizeDelta = new Vector2(width, height);

                rtState.anchoredPosition = new Vector2(margin, -marginTop);

                rtClan.anchorMin = new Vector2(0f, 1f);

                rtClan.anchorMax = new Vector2(0f, 1f);

                rtClan.pivot = new Vector2(0f, 1f);

                rtClan.sizeDelta = new Vector2(width, height);

                rtClan.anchoredPosition = new Vector2(margin + width + gap, -marginTop);

                rtFriends.anchorMin = new Vector2(0f, 1f);

                rtFriends.anchorMax = new Vector2(0f, 1f);

                rtFriends.pivot = new Vector2(0f, 1f);

                rtFriends.sizeDelta = new Vector2(width, height);

                rtFriends.anchoredPosition = new Vector2(margin + (width + gap) * 2f, -marginTop);

            }

        }

        private void UpdateSingleTabStyle(Button btn, bool isActive, Sprite activeSprite, Sprite inactiveSprite, string tabText)

        {

            SetButtonThemeSprite(btn, isActive ? activeSprite : inactiveSprite);

            var txt = btn.GetComponentInChildren<Text>();

            if (txt == null)

            {

                var txtObj = new GameObject("Text");

                txtObj.transform.SetParent(btn.transform, false);

                txt = txtObj.AddComponent<Text>();

                txt.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");

                txt.alignment = TextAnchor.MiddleCenter;

                var txtRT = txtObj.GetComponent<RectTransform>();

                txtRT.anchorMin = Vector2.zero;

                txtRT.anchorMax = Vector2.one;

                txtRT.offsetMin = Vector2.zero;

                txtRT.offsetMax = Vector2.zero;

            }

            if (txt != null)

            {

                txt.text = tabText;

                txt.color = isActive ? new Color(0.95f, 0.85f, 0.35f, 1) : new Color(0.6f, 0.6f, 0.6f, 1);

                txt.fontStyle = isActive ? FontStyle.Bold : FontStyle.Normal;

                txt.fontSize = 10;

                AddSkillThemeTextShadow(txt);

            }

        }

        public void ModernizeVariousTexts(Transform root)

        {

            var texts = root.GetComponentsInChildren<Text>(true);

            foreach (var txt in texts)

            {

                // Skip texts in our custom distribution panels

                if (txt.transform.parent != null &&

                    (txt.transform.parent.name.StartsWith("Row_") || txt.transform.parent.name.StartsWith("StatRow_") ||

                     txt.transform.parent.parent?.name == "StatDistributionPanel" ||

                     txt.transform.parent.parent?.name == "SkillDistributionPanel" ||

                     txt.transform.parent.parent?.parent?.name == "StatDistributionPanel" ||

                     txt.transform.parent.parent?.parent?.name == "SkillDistributionPanel"))

                {

                    continue;

                }

                // Kapatma butonunun (btn_close) yazısını es geç, rengi ve boyutu ezilmesin

                if (txt.transform.parent != null && txt.transform.parent.name == "btn_close")

                {

                    continue;

                }

                // Eğer statik etiket, başlık veya liste başlıkları/açıklamaları ise gold yap

                if (txt.gameObject.name.StartsWith("string_") || txt.gameObject.name.StartsWith("Label") ||

                    txt.text.EndsWith(":") || txt.gameObject.name.Contains("Title") || txt.gameObject.name.Contains("header") ||

                    txt.text.Contains("Rank") || txt.text.Contains("Level") || txt.text.Contains("Job") ||

                    txt.text.Contains("Character ID") || txt.text.Contains("Members") ||

                    txt.text.Contains("Green") || txt.text.Contains("Red") || txt.text.Contains("Grey") || txt.text.Contains("Online"))

                {

                    txt.color = new Color(0.9f, 0.75f, 0.25f);

                    txt.fontStyle = FontStyle.Bold;

                }

                else

                {

                    // Değerler ise beyaz/krem yap

                    txt.color = new Color(0.95f, 0.95f, 0.9f);

                }

                txt.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");

                AddSkillThemeTextShadow(txt);

            }

        }

        /// <summary>

        /// C++ birebir: UIVarious.cpp:1530-1561 — UpdatePageButtons

        /// Tüm alt sayfaları gizle, sadece activePageId'yi göster.

        /// page_state, page_quest, page_knights, page_friend, page_clan,

        /// page_knights_union_main, page_knights_union_sub

        /// </summary>

        private static readonly string[] _variousPageIds = {

            "page_state", "page_quest", "page_knights", "page_friend",

            "page_clan", "page_Clan", "page_knights_union_main", "page_knights_union_sub"

        };

        private void UpdateVariousPage(Transform root, string activePageId)

        {

            _activeVariousPageId = activePageId;

            foreach (var pageId in _variousPageIds)

            {

                var pageTr = KOUIRenderer.FindChildByID(root, pageId);

                if (pageTr != null)

                    pageTr.gameObject.SetActive(pageId == activePageId);

            }

            // Seçili tab butonuna göre görselleri güncelle (Altın/bronz teması)

            UpdateVariousTabStyles(root, activePageId);

            // Tüm alt butonları ve sayfa oklarını tekrar modernize et (sayfalar aktifken çalışması için)

            ModernizePanelButtons(root);

            // Clan sayfalarındaki eski çerçeve ve sütun ayraç çizgilerini temizle

            CleanupClanLinesAndBorders(root);

            UpdateStatDistributionPanelVisibility();

        }

        /// <summary>

        /// Bir tab butonunu belirli bir sayfaya bağlar.

        /// C++ birebir: UIVarious.cpp ReceiveMessage satır 1511-1525

        /// </summary>

        private void BindVariousTabButton(Transform root, string buttonId, string pageId)

        {

            var btn = KOUIRenderer.FindChildButton(root, buttonId);

            if (btn != null)

            {

                // C++ birebir: tab buton referansını sakla (UIVarious.h:240-243)

                _variousTabButtons[pageId] = btn;

                Transform capturedRoot = root;

                btn.onClick.AddListener(() =>

                {

                    UpdateVariousPage(capturedRoot, pageId);

                    if (pageId == "page_state") RefreshPageState();

                    if (pageId == "page_knights") RefreshPageKnights(capturedRoot);

                    // C++ birebir: UIVarious.cpp:1559-1560 — Friend tab açılınca MsgSend_MemberInfo

                    if (pageId == "page_friend") RefreshPageFriend(capturedRoot);

                });

            }

        }

        /// <summary>

        /// Tek bir stat butonunu C2S_DISTRIBUTE_STAT paketine bağlar.

        /// C++ referans: UIVarious.cpp MsgSendAbilityPointChange() satır 487-512

        /// </summary>

        private GameObject BindStatButton(Transform root, string buttonId, byte statType, string statName)

        {

            var btnTr = FindChildByIDIgnoreCase(root, buttonId);

            var btn = btnTr != null ? btnTr.GetComponent<Button>() : null;

            if (btn != null)

            {

                // Stat dağıtma butonlarını şık altın/bronz temasıyla özgünleştir (P yerine + yapıyoruz)

                SetButtonThemeSprite(btn, GetSkillThemeRoundedRectSprite("btn_plus", 14, 14, 0, new Color(0.25f, 0.2f, 0.05f, 1), Color.clear, 0));

                var btnTxt = btn.GetComponentInChildren<Text>();

                if (btnTxt != null)

                {

                    btnTxt.text = "+";

                    btnTxt.color = new Color(0.95f, 0.85f, 0.35f, 1);

                    btnTxt.fontStyle = FontStyle.Bold;

                    btnTxt.fontSize = 10;

                }

                btn.onClick.AddListener(() =>

                {

                    // C++ UIVarious.cpp satır 487-512: MsgSendAbilityPointChange

                    // Bonus point kontrolü GameManager'dan yapılır

                    var gm = EntropyOnline.Core.GameManager.Instance;

                    if (gm != null && gm.StatPoints <= 0)

                    {

                        Debug.LogWarning($"[KOUIMGR] {statName} artırılamaz — bonus puan yok!");

                        return;

                    }

                    using var packet = new KOPacketWriter(WizOpcode.WIZ_POINT_CHANGE);

                    packet.WriteByte(statType);

                    // C++ MsgSendAblityPointChange satır 503-504: [type: byte] [value: short]

                    packet.WriteInt16(1); // siValueDelta = +1

                    KONetworkManager.Instance?.SendPacket(packet);

                });

                return btn.gameObject;

            }

            return null;

        }

        /// <summary>

        /// StateBar butonlarını bağlar.

        /// C++ referans: UIStateBar.cpp Load() satır 198-203, ReceiveMessage() satır 609-634

        /// </summary>

        private void BindStateBarButtons(Transform root)

        {

            // C++ UIStateBar.cpp satır 198: m_pBtn_ZoomIn = GetChildByID<CN3UIButton>("Btn_ZoomIn")

            // Minimap Group içinde — root'tan recursive aranır

            var btnZoomIn = KOUIRenderer.FindChildButton(root, "Btn_ZoomIn");

            if (btnZoomIn != null)

            {

                btnZoomIn.onClick.AddListener(() =>

                {

                    // C++ UIStateBar.cpp satır 613-616: ZoomSet(m_fZoom * 1.1f)

                    _miniMapZoom = Mathf.Clamp(_miniMapZoom * 1.1f, 1.0f, 6.0f);

                    UpdateMiniMapUV();

                });

            }

            // C++ UIStateBar.cpp satır 199: m_pBtn_ZoomOut = GetChildByID<CN3UIButton>("Btn_ZoomOut")

            var btnZoomOut = KOUIRenderer.FindChildButton(root, "Btn_ZoomOut");

            if (btnZoomOut != null)

            {

                btnZoomOut.onClick.AddListener(() =>

                {

                    // C++ UIStateBar.cpp satır 618-621: ZoomSet(m_fZoom * 0.9f)

                    _miniMapZoom = Mathf.Clamp(_miniMapZoom * 0.9f, 1.0f, 6.0f);

                    UpdateMiniMapUV();

                });

            }

            // Q button (btn_quest) is completely deactivated as Level Guide is removed

            var btnQuest = KOUIRenderer.FindChildButton(root, "btn_quest");

            Vector2 origQuestPos = Vector2.zero;

            bool hasQuestBtn = false;

            if (btnQuest != null)

            {

                var btnQuestRt = btnQuest.GetComponent<RectTransform>();

                if (btnQuestRt != null)

                {

                    origQuestPos = btnQuestRt.anchoredPosition;

                    hasQuestBtn = true;

                }

                btnQuest.gameObject.SetActive(false);

            }

            // C++ UIStateBar.cpp satır 203: m_pBtn_Power = GetChildByID<CN3UIButton>("btn_power")

            var btnPower = KOUIRenderer.FindChildButton(root, "btn_power");

            if (btnPower != null)

            {

                btnPower.onClick.AddListener(() =>

                {

                    // WIZ_SHOPPING_MALL + STORE_OPEN paketini gönder

                    using var pkt = new KOPacketWriter(WizOpcode.WIZ_SHOPPING_MALL);

                    pkt.WriteByte((byte)ShoppingMallOpcodes.STORE_OPEN);

                    KONetworkManager.Instance.SendPacket(pkt);

                });

                // Shift btnPower to the left to occupy btnQuest's old position and make it diamond-shaped

                var btnPowerRt = btnPower.GetComponent<RectTransform>();

                if (btnPowerRt != null)

                {

                    float spacing = 42f; // Increased spacing for diamond buttons

                    if (hasQuestBtn)

                    {

                        btnPowerRt.anchoredPosition = origQuestPos; // Shift to the left

                    }

                    btnPowerRt.sizeDelta = new Vector2(34, 34); // Resize to match reference style

                    // Replace RawImage with procedural Diamond Image

                    var oldRaw = btnPower.GetComponent<RawImage>();

                    if (oldRaw != null)

                    {

                        DestroyImmediate(oldRaw);

                    }

                    var imgPower = btnPower.GetComponent<Image>();

                    if (imgPower == null)

                    {

                        imgPower = btnPower.gameObject.AddComponent<Image>();

                    }

                    imgPower.sprite = GetDiamondSprite("btn_store_diamond_bg", 34, 34, new Color(0.24f, 0.08f, 0.20f, 1f), new Color(0.75f, 0.63f, 0.38f, 1f), 2);

                    imgPower.color = Color.white;

                    btnPower.targetGraphic = imgPower;

                    btnPower.transition = Selectable.Transition.ColorTint;

                    var colorsPower = btnPower.colors;

                    colorsPower.normalColor = Color.white;

                    colorsPower.highlightedColor = new Color(1.2f, 1.2f, 1.2f, 1f);

                    colorsPower.pressedColor = new Color(0.8f, 0.8f, 0.8f, 1f);

                    colorsPower.selectedColor = Color.white;

                    btnPower.colors = colorsPower;

                    // Add text overlay "P" inside btnPower

                    Transform txtPowerTrans = btnPower.transform.Find("Text");

                    GameObject txtPowerObj = txtPowerTrans != null ? txtPowerTrans.gameObject : null;

                    if (txtPowerObj == null)

                    {

                        txtPowerObj = new GameObject("Text", typeof(RectTransform));

                        txtPowerObj.transform.SetParent(btnPower.transform, false);

                        txtPowerObj.layer = btnPower.gameObject.layer;

                        var txtRt = txtPowerObj.GetComponent<RectTransform>();

                        txtRt.anchorMin = Vector2.zero;

                        txtRt.anchorMax = Vector2.one;

                        txtRt.sizeDelta = Vector2.zero;

                        txtRt.anchoredPosition = Vector2.zero;

                    }

                    var txtPowerComp = txtPowerObj.GetComponent<Text>();

                    if (txtPowerComp == null) txtPowerComp = txtPowerObj.AddComponent<Text>();

                    txtPowerComp.font = GetSafeFont(9);

                    txtPowerComp.text = "P";

                    txtPowerComp.alignment = TextAnchor.MiddleCenter;

                    txtPowerComp.color = new Color(0.95f, 0.82f, 0.55f, 1f);

                    txtPowerComp.fontSize = 12;

                    txtPowerComp.fontStyle = FontStyle.Bold;

                    var shPower = txtPowerObj.GetComponent<Shadow>();

                    if (shPower == null) shPower = txtPowerObj.AddComponent<Shadow>();

                    shPower.effectColor = Color.black;

                    shPower.effectDistance = new Vector2(1f, -1f);

                    // Add label "STORE" below btnPower

                    Transform lblPowerTrans = btnPower.transform.Find("Label");

                    GameObject lblPowerObj = lblPowerTrans != null ? lblPowerTrans.gameObject : null;

                    if (lblPowerObj == null)

                    {

                        lblPowerObj = new GameObject("Label", typeof(RectTransform));

                        lblPowerObj.transform.SetParent(btnPower.transform, false);

                        lblPowerObj.layer = btnPower.gameObject.layer;

                        var lblRt = lblPowerObj.GetComponent<RectTransform>();

                        lblRt.anchorMin = new Vector2(0.5f, 0.5f);

                        lblRt.anchorMax = new Vector2(0.5f, 0.5f);

                        lblRt.pivot = new Vector2(0.5f, 1f);

                        lblRt.sizeDelta = new Vector2(80, 20);

                        lblRt.anchoredPosition = new Vector2(0, -22); // Placed centered below

                    }

                    var lblPowerComp = lblPowerObj.GetComponent<Text>();

                    if (lblPowerComp == null) lblPowerComp = lblPowerObj.AddComponent<Text>();

                    lblPowerComp.font = GetSafeFont(9);

                    lblPowerComp.text = "STORE";

                    lblPowerComp.alignment = TextAnchor.UpperCenter;

                    lblPowerComp.color = new Color(0.95f, 0.82f, 0.55f, 1f);

                    lblPowerComp.fontSize = 8;

                    lblPowerComp.fontStyle = FontStyle.Bold;

                    var shPowerLbl = lblPowerObj.GetComponent<Shadow>();

                    if (shPowerLbl == null) shPowerLbl = lblPowerObj.AddComponent<Shadow>();

                    shPowerLbl.effectColor = Color.black;

                    shPowerLbl.effectDistance = new Vector2(1f, -1f);

                    Transform parentTrans = btnPower.transform.parent;

                    string btnAhName = "btn_ah";

                    Transform existingAh = parentTrans.Find(btnAhName);

                    if (existingAh != null)

                    {

                        Destroy(existingAh.gameObject);

                        existingAh = null;

                    }

                    if (existingAh == null)

                    {

                        GameObject btnAhObj = new GameObject(btnAhName, typeof(RectTransform));

                        btnAhObj.transform.SetParent(parentTrans, false);

                        btnAhObj.layer = parentTrans.gameObject.layer; // Ensure it is on the UI layer (5)

                        var btnAhRt = btnAhObj.GetComponent<RectTransform>();

                        btnAhRt.anchorMin = btnPowerRt.anchorMin;

                        btnAhRt.anchorMax = btnPowerRt.anchorMax;

                        btnAhRt.pivot = btnPowerRt.pivot;

                        btnAhRt.sizeDelta = btnPowerRt.sizeDelta;

                        btnAhRt.anchoredPosition = new Vector2(btnPowerRt.anchoredPosition.x + spacing, btnPowerRt.anchoredPosition.y);

                        // Create custom visual representation (rounded gold-bordered button)

                        var img = btnAhObj.AddComponent<Image>();

                        img.sprite = GetDiamondSprite("btn_ah_diamond_bg", 34, 34, new Color(0.18f, 0.12f, 0.10f, 1f), new Color(0.75f, 0.63f, 0.38f, 1f), 2);

                        img.color = Color.white;

                        // Add Button component and click listener

                        var btnAh = btnAhObj.AddComponent<Button>();

                        btnAh.targetGraphic = img;

                        btnAh.transition = Selectable.Transition.ColorTint;

                        var colors = btnAh.colors;

                        colors.normalColor = Color.white;

                        colors.highlightedColor = new Color(1.2f, 1.2f, 1.2f, 1f);

                        colors.pressedColor = new Color(0.8f, 0.8f, 0.8f, 1f);

                        colors.selectedColor = Color.white;

                        btnAh.colors = colors;

                        btnAh.onClick.AddListener(() => ToggleAuctionHouseUI());

                        // Add text overlay "AH"

                        GameObject textObj = new GameObject("Text", typeof(RectTransform));

                        textObj.transform.SetParent(btnAhObj.transform, false);

                        textObj.layer = parentTrans.gameObject.layer; // Ensure it is on the UI layer (5)

                        var txtRt = textObj.GetComponent<RectTransform>();

                        txtRt.anchorMin = Vector2.zero;

                        txtRt.anchorMax = Vector2.one;

                        txtRt.sizeDelta = Vector2.zero;

                        txtRt.anchoredPosition = Vector2.zero;

                        var txtComp = textObj.AddComponent<Text>();

                        txtComp.font = GetSafeFont(9);

                        txtComp.text = "AH";

                        txtComp.alignment = TextAnchor.MiddleCenter;

                        txtComp.color = new Color(0.95f, 0.82f, 0.55f, 1f); // Bronze/Gold color matching P and Q theme

                        txtComp.fontSize = 11;

                        txtComp.fontStyle = FontStyle.Bold;

                        var shadow = textObj.AddComponent<Shadow>();

                        shadow.effectColor = Color.black;

                        shadow.effectDistance = new Vector2(1f, -1f);

                        // Add label "AUCTION HOUSE" below btnAh

                        GameObject lblAhObj = new GameObject("Label", typeof(RectTransform));

                        lblAhObj.transform.SetParent(btnAhObj.transform, false);

                        lblAhObj.layer = parentTrans.gameObject.layer;

                        var lblAhRt = lblAhObj.GetComponent<RectTransform>();

                        lblAhRt.anchorMin = new Vector2(0.5f, 0.5f);

                        lblAhRt.anchorMax = new Vector2(0.5f, 0.5f);

                        lblAhRt.pivot = new Vector2(0.5f, 1f);

                        lblAhRt.sizeDelta = new Vector2(80, 30);

                        lblAhRt.anchoredPosition = new Vector2(0, -22); // Placed centered below

                        var lblAhComp = lblAhObj.AddComponent<Text>();

                        lblAhComp.font = GetSafeFont(9);

                        lblAhComp.text = "AUCTION\nHOUSE";

                        lblAhComp.alignment = TextAnchor.UpperCenter;

                        lblAhComp.color = new Color(0.95f, 0.82f, 0.55f, 1f);

                        lblAhComp.fontSize = 7;

                        lblAhComp.fontStyle = FontStyle.Bold;

                        lblAhComp.lineSpacing = 0.9f;

                        var shadowLblAh = lblAhObj.AddComponent<Shadow>();

                        shadowLblAh.effectColor = Color.black;

                        shadowLblAh.effectDistance = new Vector2(1f, -1f);

                        // Create btn_drops (Drops Search Button) next to btn_ah

                        string btnDropsName = "btn_drops";

                        Transform existingDrops = parentTrans.Find(btnDropsName);

                        if (existingDrops != null)

                        {

                            Destroy(existingDrops.gameObject);

                            existingDrops = null;

                        }

                        if (existingDrops == null)

                        {

                            GameObject btnDropsObj = new GameObject(btnDropsName, typeof(RectTransform));

                            btnDropsObj.transform.SetParent(parentTrans, false);

                            btnDropsObj.layer = parentTrans.gameObject.layer;

                            var btnDropsRt = btnDropsObj.GetComponent<RectTransform>();

                            btnDropsRt.anchorMin = btnPowerRt.anchorMin;

                            btnDropsRt.anchorMax = btnPowerRt.anchorMax;

                            btnDropsRt.pivot = btnPowerRt.pivot;

                            btnDropsRt.sizeDelta = btnPowerRt.sizeDelta;

                            // Placed spaced from btnAh

                            btnDropsRt.anchoredPosition = new Vector2(btnPowerRt.anchoredPosition.x + (spacing * 2), btnPowerRt.anchoredPosition.y);

                            // Create custom visual representation (rounded gold-bordered button)

                            var imgDrops = btnDropsObj.AddComponent<Image>();

                            imgDrops.sprite = GetDiamondSprite("btn_drops_diamond_bg", 34, 34, new Color(0.10f, 0.15f, 0.20f, 1f), new Color(0.75f, 0.63f, 0.38f, 1f), 2);

                            imgDrops.color = Color.white;

                            // Add Button component and click listener

                            var btnDrops = btnDropsObj.AddComponent<Button>();

                            btnDrops.targetGraphic = imgDrops;

                            btnDrops.transition = Selectable.Transition.ColorTint;

                            var colorsDrops = btnDrops.colors;

                            colorsDrops.normalColor = Color.white;

                            colorsDrops.highlightedColor = new Color(1.2f, 1.2f, 1.2f, 1f);

                            colorsDrops.pressedColor = new Color(0.8f, 0.8f, 0.8f, 1f);

                            colorsDrops.selectedColor = Color.white;

                            btnDrops.colors = colorsDrops;

                            btnDrops.onClick.AddListener(() => ToggleDropSearchUI());

                            // Add text overlay "D"

                            GameObject textObjD = new GameObject("Text", typeof(RectTransform));

                            textObjD.transform.SetParent(btnDropsObj.transform, false);

                            textObjD.layer = parentTrans.gameObject.layer;

                            var txtRtD = textObjD.GetComponent<RectTransform>();

                            txtRtD.anchorMin = Vector2.zero;

                            txtRtD.anchorMax = Vector2.one;

                            txtRtD.sizeDelta = Vector2.zero;

                            txtRtD.anchoredPosition = Vector2.zero;

                            var txtCompD = textObjD.AddComponent<Text>();

                            txtCompD.font = GetSafeFont(9);

                            txtCompD.text = "D";

                            txtCompD.alignment = TextAnchor.MiddleCenter;

                            txtCompD.color = new Color(0.95f, 0.82f, 0.55f, 1f);

                            txtCompD.fontSize = 12;

                            txtCompD.fontStyle = FontStyle.Bold;

                            var shadowD = textObjD.AddComponent<Shadow>();

                            shadowD.effectColor = Color.black;

                            shadowD.effectDistance = new Vector2(1f, -1f);

                            // Add label "DROPS" below btnDrops

                            GameObject lblDropsObj = new GameObject("Label", typeof(RectTransform));

                            lblDropsObj.transform.SetParent(btnDropsObj.transform, false);

                            lblDropsObj.layer = parentTrans.gameObject.layer;

                            var lblDropsRt = lblDropsObj.GetComponent<RectTransform>();

                            lblDropsRt.anchorMin = new Vector2(0.5f, 0.5f);

                            lblDropsRt.anchorMax = new Vector2(0.5f, 0.5f);

                            lblDropsRt.pivot = new Vector2(0.5f, 1f);

                            lblDropsRt.sizeDelta = new Vector2(80, 20);

                            lblDropsRt.anchoredPosition = new Vector2(0, -22);

                            var lblDropsComp = lblDropsObj.AddComponent<Text>();

                            lblDropsComp.font = GetSafeFont(9);

                            lblDropsComp.text = "DROPS";

                            lblDropsComp.alignment = TextAnchor.UpperCenter;

                            lblDropsComp.color = new Color(0.95f, 0.82f, 0.55f, 1f);

                            lblDropsComp.fontSize = 8;

                            lblDropsComp.fontStyle = FontStyle.Bold;

                            var shadowLblDrops = lblDropsObj.AddComponent<Shadow>();

                            shadowLblDrops.effectColor = Color.black;

                            shadowLblDrops.effectDistance = new Vector2(1f, -1f);

                        }

                    }

                }

            }

        }

        public void UpdateHP(float ratio)

        {

            ratio = Mathf.Clamp01(ratio);

            if (_hpFill != null) _hpFill.FillAmount = ratio;

            if (_customHpFillImage != null) _customHpFillImage.rectTransform.anchorMax = new Vector2(ratio, 1f);

        }

        public void UpdateMP(float ratio)

        {

            ratio = Mathf.Clamp01(ratio);

            if (_mpFill != null) _mpFill.FillAmount = ratio;

            if (_customMpFillImage != null) _customMpFillImage.rectTransform.anchorMax = new Vector2(ratio, 1f);

        }

        public void UpdateEXP(float ratio)

        {

            ratio = Mathf.Clamp01(ratio);

            if (_expFill != null) _expFill.FillAmount = ratio;

            if (_customExpFillImage != null) _customExpFillImage.rectTransform.anchorMax = new Vector2(ratio, 1f);

        }

        // ================================================

        // Text Güncelleme API — C++ SetString() birebir portları

        // ================================================

        /// <summary>

        /// StateBar HP text güncelleme.

        /// C++ referans: UIStateBar.cpp UpdateHP() satır 287-307

        /// Format: "{current} / {max}"

        /// </summary>

        public void UpdateHPText(int current, int max)

        {

            if (_textHP != null)

                _textHP.text = $"{current} / {max}";

            if (_customHpTextVal != null)

                _customHpTextVal.text = $"{current}/{max}";

        }

        /// <summary>

        /// StateBar MP text güncelleme.

        /// C++ referans: UIStateBar.cpp UpdateMSP() satır 262-285

        /// Format: "{current} / {max}"

        /// </summary>

        public void UpdateMPText(int current, int max)

        {

            if (_textMP != null)

                _textMP.text = $"{current} / {max}";

            if (_customMpTextVal != null)

                _customMpTextVal.text = $"{current}/{max}";

        }

        /// <summary>

        /// StateBar EXP text güncelleme.

        /// C++ referans: UIStateBar.cpp UpdateExp() satır 219-260

        /// Format: "{percentage:.2f} %"

        /// </summary>

        public void UpdateExpText(long exp, long expNext)

        {

            if (_textExp != null && expNext > 0)

            {

                double percentage = 100.0 * ((double)exp / (double)expNext);

                _textExp.text = $"{percentage:F2} %";

                if (_customExpTextVal != null)

                    _customExpTextVal.text = $"Exp. %{percentage:F2}";

            }

        }

        /// <summary>

        /// StateBar pozisyon text güncelleme.

        /// C++ referans: UIStateBar.cpp UpdatePosition() satır 309-320

        /// Format: "{x:.1f}, {z:.1f}"

        /// </summary>

        public void UpdatePositionText(float x, float z)

        {

            if (_textPosition != null)

                _textPosition.text = $"{(int)x}, {(int)z}";

            if (_customCoordsTextVal != null)

                _customCoordsTextVal.text = $"{(int)x},{(int)z}";

        }

        /// <summary>

        /// StateBar FPS text güncelleme.

        /// </summary>

        public void UpdateFPSText(float fps)

        {

            if (_textFPS != null)

                _textFPS.text = fps.ToString("F1");

            if (_customSystemFpsTextVal != null)

                _customSystemFpsTextVal.text = $"FPS: {(int)fps}";

            UpdateCustomSystemIndicators();

        }

        // ================================================

        // Redesigned Mobile Player Status Bar Builder & Helpers

        // ================================================

        private void RebuildMobileStateBar(Transform root)

        {

            if (root == null) return;

            // 1. Hide original C++ GUI elements (borders, old texts, old bars), but preserve buttons (Q, P, AH, etc.)

            /* Loop Removed */

            /* Loop Removed */

            foreach (var txt in root.GetComponentsInChildren<Text>(true))

            {

                if (txt.GetComponentInParent<Button>() != null || txt.GetComponentInChildren<Button>() != null) continue;

                txt.enabled = false;

            }

            // 2. Create the custom redesigned container (Compact width)

            var containerObj = new GameObject("MobileStateBarContainer", typeof(RectTransform));

            containerObj.transform.SetParent(root, false);

            _customStateBarContainer = containerObj.GetComponent<RectTransform>();

            _customStateBarContainer.anchorMin = new Vector2(0, 1);

            _customStateBarContainer.anchorMax = new Vector2(0, 1);

            _customStateBarContainer.pivot = new Vector2(0, 1);

            _customStateBarContainer.anchoredPosition = new Vector2(3f, -10f); // 3px offset from top-left to pull everything closer to the left edge

            _customStateBarContainer.sizeDelta = new Vector2(260f, 110f);

            var gm = GameManager.Instance;

            byte charClass = gm != null ? gm.CharClass : (byte)1;

            string charName = gm != null ? gm.CharacterName : "Player";

            short level = gm != null ? gm.Level : (short)1;

            // Get the builtin font

            var font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");

            if (font == null) font = Resources.GetBuiltinResource<Font>("Arial.ttf");

            // 6. Coordinates (Row 1 Right, positioned above character name, no shadow)

            var coordsObj = new GameObject("CoordsVal", typeof(RectTransform));

            coordsObj.transform.SetParent(_customStateBarContainer, false);

            var cRt = coordsObj.GetComponent<RectTransform>();

            cRt.anchorMin = new Vector2(0, 1);

            cRt.anchorMax = new Vector2(0, 1);

            cRt.pivot = new Vector2(0, 0); // Bottom-left pivot so anchoredPosition.y represents the bottom edge

            cRt.anchoredPosition = new Vector2(62f, -7f); // Bottom of the box is exactly 2px above the shadow (which starts at -9f)

            cRt.sizeDelta = new Vector2(120f, 10f);

            _customCoordsTextVal = coordsObj.AddComponent<Text>();

            _customCoordsTextVal.font = font;

            _customCoordsTextVal.fontSize = 10;

            _customCoordsTextVal.fontStyle = FontStyle.Bold; // Make coordinates bold

            _customCoordsTextVal.alignment = TextAnchor.LowerLeft;

            _customCoordsTextVal.horizontalOverflow = HorizontalWrapMode.Overflow;

            _customCoordsTextVal.verticalOverflow = VerticalWrapMode.Overflow;

            _customCoordsTextVal.color = Color.white; // Pure white for perfect contrast

            _customCoordsTextVal.text = "0,0";

            // 7. Character Name (Row 1 Left, positioned below coordinates)

            var nameObj = new GameObject("NameVal", typeof(RectTransform));

            nameObj.transform.SetParent(_customStateBarContainer, false);

            var nRt = nameObj.GetComponent<RectTransform>();

            nRt.anchorMin = new Vector2(0, 1);

            nRt.anchorMax = new Vector2(0, 1);

            nRt.pivot = new Vector2(0, 1);

            nRt.anchoredPosition = new Vector2(76f, -12f); // Shifted up to avoid HP bar overlap

            nRt.sizeDelta = new Vector2(110f, 12f);

            _customNameTextVal = nameObj.AddComponent<Text>();

            _customNameTextVal.font = font;

            _customNameTextVal.fontSize = 11;

            _customNameTextVal.fontStyle = FontStyle.Bold;

            _customNameTextVal.alignment = TextAnchor.MiddleLeft;

            _customNameTextVal.horizontalOverflow = HorizontalWrapMode.Overflow;

            _customNameTextVal.verticalOverflow = VerticalWrapMode.Overflow;

            _customNameTextVal.color = new Color(0.95f, 0.8f, 0.3f, 1f);

            _customNameTextVal.text = charName;

            AddTextShadow(nameObj);

            // 7.1 Character Name Background (Flat, straight bar starting behind circle/flama, 60% opacity, fading in the last 10%)

            var nameBgObj = new GameObject("NameBg", typeof(RectTransform));

            nameBgObj.transform.SetParent(_customStateBarContainer, false);

            _customNameBgRt = nameBgObj.GetComponent<RectTransform>();

            _customNameBgRt.anchorMin = new Vector2(0, 1);

            _customNameBgRt.anchorMax = new Vector2(0, 1);

            _customNameBgRt.pivot = new Vector2(0, 1);

            _customNameBgRt.anchoredPosition = new Vector2(35f, -9f); // Starts slightly above character name (ends at -25f)

            _customNameBgRt.sizeDelta = new Vector2(167f, 16f); // Ends exactly at the new battery center (35 + 167 = 202)

            var nbImg = nameBgObj.AddComponent<Image>();

            nbImg.sprite = GetLast10PercentFadeoutSprite("name_bg_grad_last10", 167, 16, 0.6f);

            nameBgObj.transform.SetAsFirstSibling(); // Render in the background (behind coordinates and name)

            // 8. HP Bar Background (Sibling, no Mask, drawn behind)

            var hpBgObj = new GameObject("HPBg", typeof(RectTransform));

            hpBgObj.transform.SetParent(_customStateBarContainer, false);

            var hpBgRt = hpBgObj.GetComponent<RectTransform>();

            hpBgRt.anchorMin = new Vector2(0, 1);

            hpBgRt.anchorMax = new Vector2(0, 1);

            hpBgRt.pivot = new Vector2(0, 1);

            hpBgRt.anchoredPosition = new Vector2(66f, -24.5f);

            hpBgRt.sizeDelta = new Vector2(160f, 16f);

            var hpBgImg = hpBgObj.AddComponent<Image>();

            hpBgImg.sprite = GetSlantedSprite("hp_bar_bg_no_border", 160, 16, -7, new Color(0.12f, 0.02f, 0.02f, 0.85f), Color.clear, 0);

            hpBgObj.transform.SetAsFirstSibling(); // Render in the background (behind fills and texts)

            // 8.1 HP Bar Mask Parent (No visible graphic, masks the red fill)

            var hpBarObj = new GameObject("HPBar", typeof(RectTransform));

            hpBarObj.transform.SetParent(_customStateBarContainer, false);

            var hpRt = hpBarObj.GetComponent<RectTransform>();

            hpRt.anchorMin = new Vector2(0, 1);

            hpRt.anchorMax = new Vector2(0, 1);

            hpRt.pivot = new Vector2(0, 1);

            hpRt.anchoredPosition = new Vector2(66f, -24.5f); // Centered relative to 75x75 circle

            hpRt.sizeDelta = new Vector2(160f, 16f);

            var hpBarImg = hpBarObj.AddComponent<Image>();

            hpBarImg.sprite = GetSlantedSprite("hp_bar_bg_mask_shape", 160, 16, -7, Color.white, Color.clear, 0); // Solid white for mask shape

            hpBarObj.AddComponent<Mask>().showMaskGraphic = false; // Hide mask graphic so children show through

