        private Sprite GetLast10PercentFadeoutSprite(string key, int w, int h, float maxAlpha)

        {

            string cacheKey = $"{key}_{w}_{h}_{maxAlpha}";

            if (_slantedSpriteCache.TryGetValue(cacheKey, out Sprite cached))

            {

                if (cached != null) return cached;

            }

            Texture2D tex = new Texture2D(w, h, TextureFormat.RGBA32, false);

            tex.filterMode = FilterMode.Bilinear;

            tex.wrapMode = TextureWrapMode.Clamp;

            for (int y = 0; y < h; y++)

            {

                for (int x = 0; x < w; x++)

                {

                    float t = (float)x / (w - 1);

                    float alpha = maxAlpha;

                    if (t > 0.9f)

                    {

                        alpha = maxAlpha * (1f - (t - 0.9f) / 0.1f);

                    }

                    tex.SetPixel(x, y, new Color(0f, 0f, 0f, alpha));

                }

            }

            tex.Apply();

            Sprite sprite = Sprite.Create(tex, new Rect(0, 0, w, h), new Vector2(0.5f, 0.5f));

            _slantedSpriteCache[cacheKey] = sprite;

            return sprite;

        }

        private Sprite GetWifiIconSprite()

        {

            string cacheKey = "wifi_icon_procedural_highres";

            if (_slantedSpriteCache.TryGetValue(cacheKey, out Sprite cached))

            {

                if (cached != null) return cached;

            }

            Texture2D tex = new Texture2D(24, 24, TextureFormat.RGBA32, false);

            tex.filterMode = FilterMode.Bilinear;

            tex.wrapMode = TextureWrapMode.Clamp;

            // Generate clean, high-resolution arcs for a 24x24 wifi icon

            for (int y = 0; y < 24; y++)

            {

                for (int x = 0; x < 24; x++)

                {

                    // Center pivot at bottom-left corner (0,0)

                    float dist = Mathf.Sqrt(x * x + y * y);

                    bool draw = false;

                    // Central dot: dist up to 4

                    if (dist < 4.0f)

                    {

                        draw = true;

                    }

                    // Middle arc: dist 10 to 13

                    else if (dist >= 10.0f && dist <= 13.0f)

                    {

                        draw = true;

                    }

                    // Outer arc: dist 19 to 22

                    else if (dist >= 19.0f && dist <= 22.0f)

                    {

                        draw = true;

                    }

                    tex.SetPixel(x, y, draw ? Color.white : Color.clear);

                }

            }

            tex.Apply();

            Sprite sprite = Sprite.Create(tex, new Rect(0, 0, 24, 24), new Vector2(0.5f, 0.5f));

            _slantedSpriteCache[cacheKey] = sprite;

            return sprite;

        }

        private Sprite GetClockIconSprite()

        {

            string cacheKey = "clock_icon_procedural";

            if (_slantedSpriteCache.TryGetValue(cacheKey, out Sprite cached))

            {

                if (cached != null) return cached;

            }

            int size = 12;

            Texture2D tex = new Texture2D(size, size, TextureFormat.RGBA32, false);

            tex.filterMode = FilterMode.Bilinear;

            tex.wrapMode = TextureWrapMode.Clamp;

            float radius = 5.0f;

            float cx = 5.5f;

            float cy = 5.5f;

            for (int y = 0; y < size; y++)

            {

                for (int x = 0; x < size; x++)

                {

                    float dx = x - cx;

                    float dy = y - cy;

                    float dist = Mathf.Sqrt(dx * dx + dy * dy);

                    bool draw = false;

                    // Outer circle border

                    if (dist >= radius - 1.2f && dist <= radius + 0.2f)

                    {

                        draw = true;

                    }

                    // Hour hand: vertical line from center going up

                    else if (Mathf.Abs(dx) < 0.8f && dy >= 0f && dy < 3.5f)

                    {

                        draw = true;

                    }

                    // Minute hand: line going right-up

                    else if (Mathf.Abs(dy - dx * 0.5f) < 0.8f && dx >= 0f && dx < 3.5f)

                    {

                        draw = true;

                    }

                    // Center dot

                    else if (dist < 1.2f)

                    {

                        draw = true;

                    }

                    tex.SetPixel(x, y, draw ? Color.white : Color.clear);

                }

            }

            tex.Apply();

            Sprite sprite = Sprite.Create(tex, new Rect(0, 0, size, size), new Vector2(0.5f, 0.5f));

            _slantedSpriteCache[cacheKey] = sprite;

            return sprite;

        }

        private Sprite GetDiamondSprite(string key, int w, int h, Color fillColor, Color borderColor, int borderWidth)

        {

            string cacheKey = $"{key}_{w}_{h}_{fillColor}_{borderColor}_{borderWidth}";

            if (_slantedSpriteCache.TryGetValue(cacheKey, out Sprite sp))

                return sp;

            Texture2D tex = new Texture2D(w, h, TextureFormat.RGBA32, false);

            tex.filterMode = FilterMode.Bilinear;

            tex.wrapMode = TextureWrapMode.Clamp;

            float cx = w / 2f;

            float cy = h / 2f;

            // Border margin in distance metric: borderWidth / half_size

            float borderMargin = (float)borderWidth / cx;

            for (int x = 0; x < w; x++)

            {

                for (int y = 0; y < h; y++)

                {

                    float dx = Mathf.Abs(x - cx + 0.5f) / cx;

                    float dy = Mathf.Abs(y - cy + 0.5f) / cy;

                    float dist = dx + dy;

                    if (dist <= 1.0f)

                    {

                        if (dist > 1.0f - borderMargin)

                        {

                            tex.SetPixel(x, y, borderColor);

                        }

                        else

                        {

                            tex.SetPixel(x, y, fillColor);

                        }

                    }

                    else

                    {

                        tex.SetPixel(x, y, Color.clear);

                    }

                }

            }

            tex.Apply();

            Sprite newSp = Sprite.Create(tex, new Rect(0, 0, w, h), new Vector2(0.5f, 0.5f));

            _slantedSpriteCache[cacheKey] = newSp;

            return newSp;

        }

        private Sprite GetRoundedRectSprite(string key, int w, int h, int radius, Color fillColor, Color borderColor, int borderWidth)

        {

            string cacheKey = $"{key}_{w}_{h}_{radius}_{fillColor}_{borderColor}_{borderWidth}";

            if (_slantedSpriteCache.TryGetValue(cacheKey, out Sprite sp))

                return sp;

            Texture2D tex = new Texture2D(w, h, TextureFormat.RGBA32, false);

            tex.filterMode = FilterMode.Bilinear;

            tex.wrapMode = TextureWrapMode.Clamp;

            for (int x = 0; x < w; x++)

            {

                for (int y = 0; y < h; y++)

                {

                    if (radius <= 0)

                    {

                        bool isBorder = (x < borderWidth || x >= w - borderWidth || y < borderWidth || y >= h - borderWidth);

                        tex.SetPixel(x, y, isBorder ? borderColor : fillColor);

                        continue;

                    }

                    // Distance field calculation to nearest inside-core point

                    float cx = Mathf.Clamp(x, radius, w - 1 - radius);

                    float cy = Mathf.Clamp(y, radius, h - 1 - radius);

                    float dx = x - cx;

                    float dy = y - cy;

                    float dist = Mathf.Sqrt(dx * dx + dy * dy);

                    if (dist > radius + 1f)

                    {

                        tex.SetPixel(x, y, Color.clear);

                    }

                    else

                    {

                        // Border check: either near the corner radius edge, or near straight outer bounds

                        bool isBorder = (dist >= radius - borderWidth) ||

                                        (dist <= radius && (

                                            (cx == radius && x < borderWidth) ||

                                            (cx == w - 1 - radius && x >= w - borderWidth) ||

                                            (cy == radius && y < borderWidth) ||

                                            (cy == h - 1 - radius && y >= h - borderWidth)

                                         ));

                        float alpha = 1f;

                        if (dist > radius - 1f)

                        {

                            alpha = Mathf.Clamp01((radius + 1f - dist) / 2f);

                        }

                        Color c = isBorder ? borderColor : fillColor;

                        c.a *= alpha;

                        tex.SetPixel(x, y, c);

                    }

                }

            }

            tex.Apply();

            Sprite sprite = Sprite.Create(tex, new Rect(0, 0, w, h), new Vector2(0.5f, 0.5f));

            _slantedSpriteCache[cacheKey] = sprite;

            return sprite;

        }

        private Sprite GetSlantedSprite(string key, int w, int h, int slant, Color fillColor, Color borderColor, int borderWidth, bool horizontalGradient = false)

        {

            string cacheKey = $"{key}_{w}_{h}_{slant}_{fillColor}_{borderColor}_{borderWidth}_{horizontalGradient}";

            if (_slantedSpriteCache.TryGetValue(cacheKey, out Sprite cached))

            {

                if (cached != null) return cached;

            }

            Texture2D tex = new Texture2D(w, h, TextureFormat.RGBA32, false);

            tex.filterMode = FilterMode.Bilinear;

            tex.wrapMode = TextureWrapMode.Clamp;

            int absSlant = Mathf.Abs(slant);

            for (int y = 0; y < h; y++)

            {

                float t = (float)y / (h - 1);

                float startX = 0f;

                float endX = 0f;

                if (slant >= 0)

                {

                    startX = t * absSlant;

                    endX = w - (absSlant - t * absSlant);

                }

                else

                {

                    startX = (1 - t) * absSlant;

                    endX = w - t * absSlant;

                }

                for (int x = 0; x < w; x++)

                {

                    Color pixelColor = Color.clear;

                    if (x >= startX && x <= endX)

                    {

                        if (x < startX + borderWidth || x > endX - borderWidth || y < borderWidth || y >= h - borderWidth)

                        {

                            pixelColor = borderColor;

                        }

                        else

                        {

                            if (horizontalGradient)

                            {

                                float horizontalT = (float)x / (w - 1);

                                Color leftColor = new Color(fillColor.r * 0.5f, fillColor.g * 0.5f, fillColor.b * 0.5f, fillColor.a);

                                pixelColor = Color.Lerp(leftColor, fillColor, horizontalT);

                            }

                            else

                            {

                                pixelColor = fillColor;

                            }

                        }

                    }

                    tex.SetPixel(x, y, pixelColor);

                }

            }

            tex.Apply();

            Sprite sprite = Sprite.Create(tex, new Rect(0, 0, w, h), new Vector2(0.5f, 0.5f));

            _slantedSpriteCache[cacheKey] = sprite;

            return sprite;

        }

        private Sprite GetArrowSprite(string key, int w, int h, int leftSlant, int rightArrowSlant, Color fillColor, Color borderColor, int borderWidth, bool horizontalGradient = false)

        {

            if (_slantedSpriteCache == null)

            {

                _slantedSpriteCache = new Dictionary<string, Sprite>();

            }

            string cacheKey = $"{key}_{w}_{h}_{leftSlant}_{rightArrowSlant}_{fillColor}_{borderColor}_{borderWidth}_{horizontalGradient}";

            if (_slantedSpriteCache.TryGetValue(cacheKey, out Sprite cached))

            {

                if (cached != null) return cached;

            }

            Texture2D tex = new Texture2D(w, h, TextureFormat.RGBA32, false);

            tex.filterMode = FilterMode.Bilinear;

            tex.wrapMode = TextureWrapMode.Clamp;

            int absLeftSlant = Mathf.Abs(leftSlant);

            for (int y = 0; y < h; y++)

            {

                float t = (float)y / (h - 1);

                float startX = (leftSlant >= 0) ? (t * absLeftSlant) : ((1 - t) * absLeftSlant);

                float endX = w - 2f * Mathf.Abs(t - 0.5f) * rightArrowSlant;

                for (int x = 0; x < w; x++)

                {

                    Color pixelColor = Color.clear;

                    if (x >= startX && x <= endX)

                    {

                        bool isBorder = false;

                        if (x < startX + borderWidth || y < borderWidth || y >= h - borderWidth)

                        {

                            isBorder = true;

                        }

                        else

                        {

                            float rightBorderLimit = endX - borderWidth;

                            if (x > rightBorderLimit)

                            {

                                isBorder = true;

                            }

                        }

                        if (isBorder && borderWidth > 0)

                        {

                            pixelColor = borderColor;

                        }

                        else

                        {

                            if (horizontalGradient)

                            {

                                float horizontalT = (float)x / (w - 1);

                                if (key.Contains("name_bg"))

                                {

                                    float alpha = fillColor.a;

                                    if (horizontalT > 0.7f)

                                    {

                                        float fadeT = (horizontalT - 0.7f) / 0.3f;

                                        alpha = Mathf.Lerp(fillColor.a, 0f, fadeT);

                                    }

                                    pixelColor = new Color(fillColor.r, fillColor.g, fillColor.b, alpha);

                                }

                                else if (key.Contains("header_bg"))

                                {

                                    float centerDist = Mathf.Abs(horizontalT - 0.5f);

                                    float alpha = fillColor.a;

                                    if (centerDist > 0.35f)

                                    {

                                        float fadeT = (centerDist - 0.35f) / 0.15f;

                                        alpha = Mathf.Lerp(fillColor.a, 0f, fadeT);

                                    }

                                    pixelColor = new Color(fillColor.r, fillColor.g, fillColor.b, alpha);

                                }

                                else

                                {

                                    Color leftColor = new Color(fillColor.r * 0.5f, fillColor.g * 0.5f, fillColor.b * 0.5f, fillColor.a);

                                    pixelColor = Color.Lerp(leftColor, fillColor, horizontalT);

                                }

                            }

                            else

                            {

                                pixelColor = fillColor;

                            }

                        }

                    }

                    tex.SetPixel(x, y, pixelColor);

                }

            }

            tex.Apply();

            Sprite sprite = Sprite.Create(tex, new Rect(0, 0, w, h), new Vector2(0.5f, 0.5f));

            _slantedSpriteCache[cacheKey] = sprite;

            return sprite;

        }

        private Sprite GetLevelShieldSprite(string key, int w, int h, Color fillColor, Color borderColor, int borderWidth)

        {

            string cacheKey = $"{key}_{w}_{h}_{fillColor}_{borderColor}_{borderWidth}";

            if (_slantedSpriteCache.TryGetValue(cacheKey, out Sprite cached))

            {

                if (cached != null) return cached;

            }

            Texture2D tex = new Texture2D(w, h, TextureFormat.RGBA32, false);

            tex.filterMode = FilterMode.Bilinear;

            tex.wrapMode = TextureWrapMode.Clamp;

            float cutH = 5f; // height of bottom slanted cuts

            float cutW = 8f; // width of bottom slanted cuts

            for (int y = 0; y < h; y++)

            {

                for (int x = 0; x < w; x++)

                {

                    bool inside = false;

                    if (y >= cutH)

                    {

                        inside = true;

                    }

                    else

                    {

                        float leftLim = cutW * (1f - y / cutH);

                        float rightLim = w - 1f - cutW * (1f - y / cutH);

                        if (x >= leftLim && x <= rightLim)

                        {

                            inside = true;

                        }

                    }

                    Color pixelColor = Color.clear;

                    if (inside)

                    {

                        // Distance field to border line

                        float distToBorder;

                        if (y >= cutH)

                        {

                            distToBorder = Mathf.Min(x, w - 1 - x, h - 1 - y);

                        }

                        else

                        {

                            float dLeftSlant = Mathf.Abs(cutH * x + cutW * y - (cutH * cutW)) / Mathf.Sqrt(cutH * cutH + cutW * cutW);

                            float dRightSlant = Mathf.Abs(cutH * (w - 1 - x) + cutW * y - (cutH * cutW)) / Mathf.Sqrt(cutH * cutH + cutW * cutW);

                            distToBorder = Mathf.Min(y, dLeftSlant, dRightSlant);

                        }

                        if (distToBorder < borderWidth)

                        {

                            pixelColor = borderColor;

                        }

                        else

                        {

                            pixelColor = fillColor;

                        }

                        // Anti-aliased outer edge blending

                        if (distToBorder < 1f && distToBorder >= 0f)

                        {

                            pixelColor.a *= distToBorder;

                        }

                    }

                    tex.SetPixel(x, y, pixelColor);

                }

            }

            tex.Apply();

            Sprite sprite = Sprite.Create(tex, new Rect(0, 0, w, h), new Vector2(0.5f, 0.5f));

            _slantedSpriteCache[cacheKey] = sprite;

            return sprite;

        }

        private Sprite Get3DFillSprite(string key, int w, int h, Color baseColor)

        {

            string cacheKey = $"{key}_{w}_{h}_{baseColor}";

            if (_slantedSpriteCache.TryGetValue(cacheKey, out Sprite cached))

            {

                if (cached != null) return cached;

            }

            Texture2D tex = new Texture2D(w, h, TextureFormat.RGBA32, false);

            tex.filterMode = FilterMode.Bilinear;

            tex.wrapMode = TextureWrapMode.Clamp;

            for (int y = 0; y < h; y++)

            {

                float t = (float)y / (h - 1);

                Color c = baseColor;

                // Volumetric cylindrical liquid shading:

                // Dark bottom shadow refraction, bright midtone peak, sharp glossy specular line, and top highlight

                float shade = Mathf.Clamp01(0.35f + 0.65f * Mathf.Sin(t * Mathf.PI));

                c = Color.Lerp(baseColor * 0.25f, baseColor * 1.15f, shade);

                // Sharp glossy reflection band on the upper half (cylindrical highlight)

                if (t > 0.65f && t < 0.85f)

                {

                    float dist = Mathf.Abs(t - 0.75f) / 0.1f;

                    float gloss = Mathf.Clamp01(1f - dist);

                    c = Color.Lerp(c, Color.white, gloss * 0.45f); // Blend with 45% white gloss

                }

                // Very top refraction reflection highlight

                if (t > 0.9f)

                {

                    float factor = (t - 0.9f) / 0.1f;

                    c = Color.Lerp(c, Color.white, factor * 0.25f);

                }

                for (int x = 0; x < w; x++)

                {

                    tex.SetPixel(x, y, c);

                }

            }

            tex.Apply();

            Sprite sprite = Sprite.Create(tex, new Rect(0, 0, w, h), new Vector2(0.5f, 0.5f));

            _slantedSpriteCache[cacheKey] = sprite;

            return sprite;

        }

        private Sprite GetNameBgGradientSprite(string key, int w, int h)

        {

            string cacheKey = $"{key}_{w}_{h}";

            if (_slantedSpriteCache.TryGetValue(cacheKey, out Sprite cached))

            {

                if (cached != null) return cached;

            }

            Texture2D tex = new Texture2D(w, h, TextureFormat.RGBA32, false);

            tex.filterMode = FilterMode.Bilinear;

            tex.wrapMode = TextureWrapMode.Clamp;

            for (int y = 0; y < h; y++)

            {

                for (int x = 0; x < w; x++)

                {

                    float t = (float)x / (w - 1);

                    float alpha = 0.5f * (1f - t); // Starts at 50% opacity, fades to 0% at the right

                    tex.SetPixel(x, y, new Color(0f, 0f, 0f, alpha));

                }

            }

            tex.Apply();

            Sprite sprite = Sprite.Create(tex, new Rect(0, 0, w, h), new Vector2(0.5f, 0.5f));

            _slantedSpriteCache[cacheKey] = sprite;

            return sprite;

        }

        private Sprite GetSlantedBannerSprite(string key, int w, int h, int slant, Color fillColor, Color borderColor, int borderWidth)

        {

            string cacheKey = $"{key}_{w}_{h}_{slant}_{fillColor}_{borderColor}_{borderWidth}";

            if (_slantedSpriteCache.TryGetValue(cacheKey, out Sprite cached))

            {

                if (cached != null) return cached;

            }

            Texture2D tex = new Texture2D(w, h, TextureFormat.RGBA32, false);

            tex.filterMode = FilterMode.Bilinear;

            tex.wrapMode = TextureWrapMode.Clamp;

            for (int y = 0; y < h; y++)

            {

                float t = (float)y / (h - 1);

                float rightBoundary = w - (slant - t * slant);

                for (int x = 0; x < w; x++)

                {

                    Color pixelColor = Color.clear;

                    if (x >= 0 && x <= rightBoundary)

                    {

                        if (y < borderWidth || y >= h - borderWidth || x > rightBoundary - borderWidth)

                        {

                            pixelColor = borderColor;

                        }

                        else

                        {

                            pixelColor = fillColor;

                        }

                    }

                    tex.SetPixel(x, y, pixelColor);

                }

            }

            tex.Apply();

            Sprite sprite = Sprite.Create(tex, new Rect(0, 0, w, h), new Vector2(0.5f, 0.5f));

            _slantedSpriteCache[cacheKey] = sprite;

            return sprite;

        }

        private Sprite GetClassPortraitSprite(byte charClass)

        {

            string key = $"class_portrait_{charClass}";

            if (_slantedSpriteCache.TryGetValue(key, out Sprite cached))

            {

                if (cached != null) return cached;

            }

            int size = 96;

            Texture2D tex = new Texture2D(size, size, TextureFormat.RGBA32, false);

            tex.filterMode = FilterMode.Bilinear;

            tex.wrapMode = TextureWrapMode.Clamp;

            Color centerColor = Color.gray;

            Color outerColor = Color.black;

            int baseClass = charClass % 10;

            if (charClass == 1 || baseClass == 1) // Warrior

            {

                centerColor = new Color(0.35f, 0.08f, 0.08f, 1f); // Deep Ruby Red

            }

            else if (charClass == 2 || baseClass == 2) // Rogue

            {

                centerColor = new Color(0.08f, 0.32f, 0.15f, 1f); // Deep Emerald Green

            }

            else if (charClass == 3 || baseClass == 3) // Mage

            {

                centerColor = new Color(0.2f, 0.08f, 0.35f, 1f); // Deep Amethyst Purple

            }

            else if (charClass == 4 || baseClass == 4) // Priest

            {

                centerColor = new Color(0.35f, 0.28f, 0.08f, 1f); // Deep Gold/Amber

            }

            float radius = size * 0.5f;

            for (int y = 0; y < size; y++)

            {

                for (int x = 0; x < size; x++)

                {

                    float dx = x - radius;

                    float dy = y - radius;

                    float dist = Mathf.Sqrt(dx * dx + dy * dy);

                    if (dist <= radius)

                    {

                        float t = dist / radius;

                        Color pixelColor = Color.Lerp(centerColor, outerColor, t * 0.8f);

                        if (dist > radius - 1.5f)

                        {

                            pixelColor.a = 1f - (dist - (radius - 1.5f)) / 1.5f;

                        }

                        tex.SetPixel(x, y, pixelColor);

                    }

                    else

                    {

                        tex.SetPixel(x, y, Color.clear);

                    }

                }

            }

            tex.Apply();

            Sprite sprite = Sprite.Create(tex, new Rect(0, 0, size, size), new Vector2(0.5f, 0.5f));

            _slantedSpriteCache[key] = sprite;

            return sprite;

        }

        private string GetClassMonogram(byte charClass)

        {

            int baseClass = charClass % 10;

            return baseClass switch

            {

                1 => "W",

                2 => "R",

                3 => "M",

                4 => "P",

                _ => "P"

            };

        }

        private string GetClassShortName(byte charClass)

        {

            int baseClass = charClass % 10;

            return baseClass switch

            {

                1 => "WR",

                2 => "RG",

                3 => "MG",

                4 => "PR",

                _ => "PR"

            };

        }

        private void UpdateCustomSystemIndicators()

        {

            var gm = GameManager.Instance;

            if (gm != null)

            {

                if (_customLevelTextVal != null)

                    _customLevelTextVal.text = gm.Level.ToString();

                if (_customNameTextVal != null && _customNameTextVal.text != gm.CharacterName)

                    _customNameTextVal.text = gm.CharacterName;

                if (_customPortraitImageComponent != null && _customPortraitImageComponent.sprite == null)

                    _customPortraitImageComponent.sprite = GetClassPortraitSprite(gm.CharClass);

                if (_customPortraitMonogramText != null && string.IsNullOrEmpty(_customPortraitMonogramText.text))

                    _customPortraitMonogramText.text = GetClassMonogram(gm.CharClass);

            }

            if (_customSystemTimeTextVal != null)

            {

                _customSystemTimeTextVal.text = System.DateTime.Now.ToString("HH:mm");

            }

            if (_customSystemPingTextVal != null)

            {

                if (Time.time - _lastSystemBarUpdateTime > 1f)

                {

                    _lastSystemBarUpdateTime = Time.time;

                    _currentMockPing = Mathf.Clamp(UnityEngine.Random.Range(18, 26), 10, 99);

                }

                _customSystemPingTextVal.text = "MS: " + _currentMockPing;

            }

            if (_customSystemBatteryFillImage != null)

            {

                float battery = SystemInfo.batteryLevel;

                if (battery < 0f) battery = 1f; // Fallback

                _customSystemBatteryFillImage.fillAmount = battery;

                if (battery < 0.2f)

                    _customSystemBatteryFillImage.color = new Color(0.85f, 0.15f, 0.15f);

                else

                    _customSystemBatteryFillImage.color = new Color(0.15f, 0.85f, 0.15f);

            }

        }

        private void AddTextShadow(GameObject obj)

        {

            var shadow = obj.GetComponent<Shadow>();

            if (shadow == null) shadow = obj.AddComponent<Shadow>();

            shadow.effectColor = Color.black;

            shadow.effectDistance = new Vector2(1, -1);

        }

        /// <summary>

        /// TargetBar hedef bilgisi güncelleme.

        /// C++ referans: UITargetBar.cpp SetIDString() satır 53-58

        /// </summary>

        public void SetTargetInfo(string name, uint color = 0xFFFFFFFF)
        {
            if (_textTargetName != null)
            {
                _textTargetName.text = name;

                // D3DCOLOR (ARGB) → Unity Color32

                byte a = (byte)((color >> 24) & 0xFF);

                byte r = (byte)((color >> 16) & 0xFF);

                byte g = (byte)((color >> 8) & 0xFF);

                byte b = (byte)(color & 0xFF);

                _textTargetName.color = new Color32(r, g, b, a == 0 ? (byte)255 : a);

            }

        }

