        /// <summary>

        /// Item move sonrası inventory UI'ı yeniden doldur.

        /// Open-KO: InitIconUpdate() çağrısının birebir karşılığı.

        ///

        /// C++ referans: UIInventory.cpp InitIconUpdate() satır 394-443

        /// C++ akış: ReceiveResultFromServer → CommitPendingMove sonrasında

        ///           m_pMySlot[] ve m_pMyInvWnd[] güncellenmiş olur,

        ///           InitIconUpdate() bu model verisinden ikon oluşturur.

        ///

        /// Bizde: KOInventory.CommitPendingMove sonrası m_pMySlot/m_pMyInvWnd

        ///        güncellenmiş durumda. Bu fonksiyon model'den InventoryItemData[]

        ///        reconstruct edip PopulateInventory'e gönderiyor.

        /// </summary>

        public void RefreshInventoryUI()

        {

            // KOInventory modelinden InventoryItemData[] reconstruct et

            // Open-KO birebir: InitIconUpdate() m_pMySlot/m_pMyInvWnd'den okur

            var inv = KOInventory.Instance;

            if (inv == null) return;

            var itemList = new System.Collections.Generic.List<InventoryItemData>();

            // Equipment slot'ları — C++ satır 398-419: m_pMySlot[ITEM_SLOT_COUNT]

            for (int i = 0; i < KOInventory.ITEM_SLOT_COUNT; i++)

            {

                var slot = inv.m_pMySlot[i];

                if (slot == null || slot.IsEmpty) continue;

                // serverData mevcutsa direkt kullan (en doğru veri kaynağı)

                if (slot.serverData != null)

                {

                    // Slot bilgilerini güncelle (CommitPendingMove sonrası değişmiş olabilir)

                    slot.serverData.SlotType = 1; // EQUIPPED

                    slot.serverData.SlotIndex = (byte)i;

                    itemList.Add(slot.serverData);

                }

                else

                {

                    // Fallback: model verisinden InventoryItemData oluştur

                    itemList.Add(new InventoryItemData

                    {

                        InstanceId = slot.instanceId,

                        ItemDefId = slot.itemId,

                        Name = slot.iconFN ?? slot.itemId.ToString(),

                        Type = (byte)slot.itemClass,

                        AttachPoint = (byte)slot.attachPoint,

                        SlotType = 1, // EQUIPPED

                        SlotIndex = (byte)i,

                        StackCount = (short)slot.count,

                        Durability = (short)slot.durability,

                        IconId = slot.iconFN ?? ""

                    });

                }

            }

            // Bag slot'ları — C++ satır 421-443: m_pMyInvWnd[MAX_ITEM_INVENTORY]

            for (int i = 0; i < KOInventory.MAX_ITEM_INVENTORY; i++)

            {

                var slot = inv.m_pMyInvWnd[i];

                if (slot == null || slot.IsEmpty) continue;

                if (slot.serverData != null)

                {

                    slot.serverData.SlotType = 0; // INVENTORY

                    slot.serverData.SlotIndex = (byte)i;

                    itemList.Add(slot.serverData);

                }

                else

                {

                    itemList.Add(new InventoryItemData

                    {

                        InstanceId = slot.instanceId,

                        ItemDefId = slot.itemId,

                        Name = slot.iconFN ?? slot.itemId.ToString(),

                        Type = (byte)slot.itemClass,

                        AttachPoint = (byte)slot.attachPoint,

                        SlotType = 0, // INVENTORY

                        SlotIndex = (byte)i,

                        StackCount = (short)slot.count,

                        Durability = (short)slot.durability,

                        IconId = slot.iconFN ?? ""

                    });

                }

            }

            var reconstructed = itemList.ToArray();

            _currentInventoryItems = reconstructed;

            // UI populate sadece panel açıksa yapılır

            if (_uiInventory != null && _uiInventory.activeSelf)

                PopulateInventory(reconstructed);

            // GameManager cache'i de güncelle

            var gm = EntropyOnline.Core.GameManager.Instance;

            if (gm != null)

                gm.Inventory = reconstructed;

            if (_uiPersonalTrade != null && _uiPersonalTrade.activeSelf)

            {

                PopulateTradeInventory();

                var goldText = KOUIRenderer.FindChildText(_uiPersonalTrade.transform, "string_money_inv");

                if (goldText != null && gm != null)

                {

                    goldText.text = gm.Gold.ToString("N0");

                }

            }

        }

        /// <summary>

        /// UIVarious karakter bilgi paneli güncelleme.

        /// C++ referans: UIVarious.cpp UpdateAllStates() satır 1657-1776 birebir.

        /// Tüm stat, resist, AP/GP, Class/Race/Nation alanlarını günceller.

        /// </summary>

        public void RefreshCharacterInfo()

        {

            var gm = EntropyOnline.Core.GameManager.Instance;

            if (gm == null) return;

            long expMax = EntropyOnline.Shared.LevelExpTable.GetExpForLevel(gm.Level);

            UpdateCharacterInfo(

                gm.CharacterName, gm.Level, gm.StatStr, gm.StatSta,

                gm.StatDex, gm.StatInt, gm.StatCha, gm.StatPoints,

                gm.CurrentHp, gm.MaxHp, gm.CurrentMp, gm.MaxMp,

                gm.Experience, expMax, gm.SkillPoints, gm.Loyalty, gm.LoyaltyMonthly

            );

        }

        public void UpdateCharacterInfo(string name, short level, short str, short sta,

            short dex, short intel, short cha, short statPoints, int currentHp, int maxHp,

            int currentMp, int maxMp, long exp, long expMax, short skillPoints, int loyalty, int loyaltyMonthly)

        {

            // C++ UIVarious.cpp satır 192-196: UpdateID

            if (_textID != null) _textID.text = name;

            // C++ UIVarious.cpp satır 198-201: UpdateLevel

            if (_textLevel != null) _textLevel.text = level.ToString();

            var trCulture = new System.Globalization.CultureInfo("tr-TR");

            // C++ UIVarious.cpp satır 204-211: UpdateRealmPoint — "{loyalty} / {loyaltyMonthly}"

            if (_textRealmPoint != null) _textRealmPoint.text = $"{loyalty.ToString("N0", trCulture)} / {loyaltyMonthly.ToString("N0", trCulture)}";

            // C++ UIVarious.cpp satır 213-221: UpdateHP — "{current} / {max}"

            if (_textVarHP != null) _textVarHP.text = $"{currentHp.ToString("N0", trCulture)} / {maxHp.ToString("N0", trCulture)}";

            // C++ UIVarious.cpp satır 223-231: UpdateMSP — "{current} / {max}"

            if (_textVarMP != null) _textVarMP.text = $"{currentMp.ToString("N0", trCulture)} / {maxMp.ToString("N0", trCulture)}";

            // C++ UIVarious.cpp satır 233-241: UpdateExp(iVal, iValMax)

            if (_textVarExp != null && expMax > 0)

                _textVarExp.text = $"{exp.ToString("N0", trCulture)} / {expMax.ToString("N0", trCulture)}";

            var gm = EntropyOnline.Core.GameManager.Instance;

            // C++ UpdateAllStates satır 1664-1668: Class text

            if (_textClass != null && gm != null)

                _textClass.text = GetTextByClass(gm.CharClass);

            // C++ UpdateAllStates satır 1671-1675: Race text

            if (_textRace != null && gm != null)

                _textRace.text = GetRaceName(gm.Race);

            // C++ UpdateAllStates satır 1678-1682: Nation text

            if (_textNation != null && gm != null)

                _textNation.text = GetNationName(gm.Nation);

            // C++ UpdateAllStates satır 1690-1691: UpdateAttackPoint/UpdateGuardPoint

            // Delta'ları GameManager'dan al (sunucu CombatStats ile gönderir)

            if (_textAP != null && gm != null)

                _textAP.text = gm.TotalHit.ToString("N0", trCulture);

            if (_textGP != null && gm != null)

                _textGP.text = gm.TotalAc.ToString("N0", trCulture);

            // C++ UpdateAllStates satır 1694-1698: Stat'lar delta ile

            if (_textStrength != null && gm != null)

                _textStrength.text = FormatWithDelta(str, gm.StrDelta);

            else if (_textStrength != null)

                _textStrength.text = str.ToString();

            if (_textStamina != null && gm != null)

                _textStamina.text = FormatWithDelta(sta, gm.StaDelta);

            else if (_textStamina != null)

                _textStamina.text = sta.ToString();

            if (_textDexterity != null && gm != null)

                _textDexterity.text = FormatWithDelta(dex, gm.DexDelta);

            else if (_textDexterity != null)

                _textDexterity.text = dex.ToString();

            if (_textIntelligence != null && gm != null)

                _textIntelligence.text = FormatWithDelta(intel, gm.IntDelta);

            else if (_textIntelligence != null)

                _textIntelligence.text = intel.ToString();

            if (_textMagicAttack != null && gm != null)

                _textMagicAttack.text = FormatWithDelta(cha, gm.ChaDelta);

            else if (_textMagicAttack != null)

                _textMagicAttack.text = cha.ToString();

            // C++ UpdateAllStates satır 1700-1705: Resist değerleri

            if (gm != null)

            {

                if (_textRegistFire != null) _textRegistFire.text = (gm.FireR + gm.FireRDelta).ToString();

                if (_textRegistIce != null) _textRegistIce.text = (gm.ColdR + gm.ColdRDelta).ToString();

                if (_textRegistLight != null) _textRegistLight.text = (gm.LightningR + gm.LightningRDelta).ToString();

                if (_textRegistMagic != null) _textRegistMagic.text = (gm.MagicR + gm.MagicRDelta).ToString();

                if (_textRegistCurse != null) _textRegistCurse.text = (gm.DiseaseR + gm.DiseaseRDelta).ToString();

                if (_textRegistPoison != null) _textRegistPoison.text = (gm.PoisonR + gm.PoisonRDelta).ToString();

            }

            // C++ UIVarious.cpp satır 169-189: UpdateBonusPointAndButtons birebir

            // iBonusPointRemain > 0 → butonlar görünür, değilse gizli

            if (_textBonusPoint != null) _textBonusPoint.text = statPoints.ToString();

            if (_btnStatStr != null) _btnStatStr.SetActive(false);

            if (_btnStatSta != null) _btnStatSta.SetActive(false);

            if (_btnStatDex != null) _btnStatDex.SetActive(false);

            if (_btnStatInt != null) _btnStatInt.SetActive(false);

            if (_btnStatCha != null) _btnStatCha.SetActive(false);

            // C++ UIVarious.cpp UpdateAllStates satır 1711-1775 birebir:

            // Sınıfa göre stat highlight image visibility

            // m_pImg_Str, m_pImg_Sta, m_pImg_Dex, m_pImg_Int, m_pImg_MAP

            if (gm != null)

            {

                var variousRoot = _uiVarious?.transform;

                if (variousRoot != null)

                {

                    // C++ satır 1712-1725: önce hepsini gizle

                    SetChildVisible(variousRoot, "img_str", false);

                    SetChildVisible(variousRoot, "img_sta", false);

                    SetChildVisible(variousRoot, "img_dex", false);

                    SetChildVisible(variousRoot, "img_int", false);

                    SetChildVisible(variousRoot, "img_map", false);

                    // C++ satır 1727-1775: sınıfa göre göster

                    byte cc = gm.CharClass;

                    switch (cc)

                    {

                        // Warrior(KA=101,Berserker=105,EL=201,Blade=205) → STR+STA

                        case 101: case 105: case 201: case 205:

                            SetChildVisible(variousRoot, "img_str", true);

                            SetChildVisible(variousRoot, "img_sta", true);

                            break;

                        // Rogue(KA=102,Hunter=107,EL=202,Ranger=207) → STA+DEX

                        case 102: case 107: case 202: case 207:

                            SetChildVisible(variousRoot, "img_sta", true);

                            SetChildVisible(variousRoot, "img_dex", true);

                            break;

                        // Wizard(KA=103,Sorcerer=109,EL=203,Mage=209) → INT+MAP

                        case 103: case 109: case 203: case 209:

                            SetChildVisible(variousRoot, "img_int", true);

                            SetChildVisible(variousRoot, "img_map", true);

                            break;

                        // Priest(KA=104,Shaman=111,EL=204,Cleric=211) → STR+INT

                        case 104: case 111: case 204: case 211:

                            SetChildVisible(variousRoot, "img_str", true);

                            SetChildVisible(variousRoot, "img_int", true);

                            break;

                    }

                }

            }

        }

        /// <summary>

        /// C++ UIVarious.cpp FormatWithDelta() satır 471-477 birebir.

        /// iDelta > 0 → "val(+delta)", iDelta < 0 → "val(delta)", iDelta == 0 → "val"

        /// </summary>

        private static string FormatWithDelta(int iVal, int iDelta)

        {

            if (iDelta >= 0) return $"{iVal}(+{iDelta})";

            return $"{iVal}({iDelta})";

        }

        // SetChildVisible — 3710 satırındaki tek versiyona taşındı

        /// <summary>

        /// C++ GameBase.cpp GetTextByRace() satır 447-480 birebir.

        /// String'ler text_resources.h satır 246-254'ten.

