        private void BindNewExitMenuButtons(Transform root)
        {
            if (root == null) return;

            // 1. btn_select_server (Select Server) -> Disconnect & Load LoginScene
            var btnSelectServer = KOUIRenderer.FindChildButton(root, "btn_select_server");
            if (btnSelectServer != null)
            {
                btnSelectServer.onClick.RemoveAllListeners();
                btnSelectServer.onClick.AddListener(() =>
                {
                    ShowExitMenu(false);
                    if (KONetworkManager.Instance != null)
                        KONetworkManager.Instance.Disconnect();
                    UnityEngine.SceneManagement.SceneManager.LoadScene("LoginScene");
                });
            }

            // 2. btn_option (Option) -> Open Options Menu
            var btnOption = KOUIRenderer.FindChildButton(root, "btn_option");
            if (btnOption != null)
            {
                btnOption.onClick.RemoveAllListeners();
                btnOption.onClick.AddListener(() =>
                {
                    ShowExitMenu(false);
                    OpenGameOptions();
                });
            }

            // 3. btn_exit (Exit) -> Close Game Client
            var btnExit = KOUIRenderer.FindChildButton(root, "btn_exit");
            if (btnExit != null)
            {
                btnExit.onClick.RemoveAllListeners();
                btnExit.onClick.AddListener(() =>
                {
                    #if UNITY_EDITOR
                    UnityEditor.EditorApplication.isPlaying = false;
                    #else
                    Application.Quit();
                    #endif
                });
            }

            // 4. btn_cancel (Cancel) -> Close Exit Menu
            var btnCancel = KOUIRenderer.FindChildButton(root, "btn_cancel");
            if (btnCancel != null)
            {
                btnCancel.onClick.RemoveAllListeners();
                btnCancel.onClick.AddListener(() =>
                {
                    ShowExitMenu(false);
                });
            }
        }

        private void ModernizeExitMenuPanel(Transform root)
        {
            if (root == null) return;

            // 1. Style root background panel
            var bgImg = root.GetComponent<UnityEngine.UI.Image>();
            if (bgImg == null) bgImg = root.gameObject.AddComponent<UnityEngine.UI.Image>();
            
            // Set dynamic bronze/gold bordered vector background using custom theme (Opacity reduced to 85% for semi-transparency)
            bgImg.sprite = GetSkillThemePanelBgSprite("exit_menu_custom_bg_v2", 200, 183, 0,
                new Color(0.12f, 0.10f, 0.08f, 0.85f),
                new Color(0.04f, 0.04f, 0.04f, 0.85f),
                new Color(0.6f, 0.48f, 0.22f, 0.85f),
                2);
            bgImg.color = Color.white;

            var bgRt = root.GetComponent<RectTransform>();
            if (bgRt != null)
            {
                bgRt.sizeDelta = new Vector2(200f, 183f);
            }

            // 2. Style buttons dynamically
            // Colors:
            // Blue Button (Select Server, Option)
            Color blueBg = new Color(0.12f, 0.18f, 0.28f, 0.95f);      // Modern Blue
            Color blueBorder = new Color(0.25f, 0.40f, 0.60f, 0.95f);  // Light Blue Border
            
            // Red Button (Exit)
            Color redBg = new Color(0.45f, 0.05f, 0.08f, 0.95f);       // Warn Red
            Color redBorder = new Color(0.75f, 0.15f, 0.15f, 0.95f);   // Bright Red Border
            
            // Grey Button (Cancel)
            Color greyBg = new Color(0.20f, 0.18f, 0.16f, 0.95f);      // Grey/Bronze
            Color greyBorder = new Color(0.40f, 0.36f, 0.32f, 0.95f);  // Border

            StyleExitMenuButton(root, "btn_select_server", blueBg, blueBorder, "SELECT SERVER");
            StyleExitMenuButton(root, "btn_option", blueBg, blueBorder, "OPTION");
            StyleExitMenuButton(root, "btn_exit", redBg, redBorder, "EXIT");
            StyleExitMenuButton(root, "btn_cancel", greyBg, greyBorder, "CANCEL");
        }

        private void StyleExitMenuButton(Transform root, string btnName, Color normalColor, Color borderColor, string buttonText)
        {
            var btnTrans = root.Find("ButtonContainer/" + btnName);
            if (btnTrans == null) btnTrans = root.Find(btnName); // fallback
            if (btnTrans == null) return;

            var img = btnTrans.GetComponent<UnityEngine.UI.Image>();
            if (img == null) img = btnTrans.gameObject.AddComponent<UnityEngine.UI.Image>();

            // Generate button background texture procedurally at runtime in memory (180x37 size)
            int width = 180;
            int height = 37;
            Texture2D btnTex = new Texture2D(width, height, TextureFormat.RGBA32, false);
            for (int y = 0; y < height; y++)
            {
                for (int x = 0; x < width; x++)
                {
                    if (x < 1 || x >= width - 1 || y < 1 || y >= height - 1)
                        btnTex.SetPixel(x, y, borderColor);
                    else
                        btnTex.SetPixel(x, y, normalColor);
                }
            }
            btnTex.Apply();

            img.sprite = Sprite.Create(btnTex, new Rect(0, 0, width, height), new Vector2(0.5f, 0.5f));
            img.color = Color.white;

            // Setup Text properties dynamically
            var txtComp = btnTrans.GetComponentInChildren<UnityEngine.UI.Text>();
            if (txtComp != null)
            {
                txtComp.text = buttonText;
                txtComp.color = Color.white; // Changed to white color
                txtComp.font = GetSafeFont(12);
                txtComp.fontSize = 12;
                txtComp.alignment = TextAnchor.MiddleCenter;
            }

            // Setup transition visual state
            var btn = btnTrans.GetComponent<UnityEngine.UI.Button>();
            if (btn != null)
            {
                btn.transition = UnityEngine.UI.Selectable.Transition.ColorTint;
                btn.targetGraphic = img;
                var colors = btn.colors;
                colors.normalColor = Color.white;
                colors.highlightedColor = new Color(0.9f, 0.9f, 0.9f, 1f);
                colors.pressedColor = new Color(0.7f, 0.7f, 0.7f, 1f);
                btn.colors = colors;
            }
        }

