        public void ToggleInventory()

        {

            if (_uiInventory == null) return;

            // ================================================

            // C++ birebir: GameProcMain.cpp:4795-4841 — CommandToggleUIInventory

            // ================================================

            // C++ satır 4811-4816: Warehouse açıkken inventory toggle → inventory'yi kapat, yeni açma

            if (_uiWarehouse != null && _uiWarehouse.activeSelf)

            {

                if (_uiInventory.activeSelf)

                    ShowInventory(false);

                return; // C++ birebir: return bNeedOpen (false)

            }

            // C++ satır 4818-4823: Transaction açıkken inventory toggle → inventory'yi kapat, yeni açma

            if (_uiTransaction != null && _uiTransaction.activeSelf)

            {

                if (_uiInventory.activeSelf)

                    ShowInventory(false);

                return;

            }

            // C++ satır 4825-4838: Normal toggle

            if (_uiInventory.activeSelf)

            {

                ShowInventory(false);  // C++ satır 4827: Close(true)

            }

            else

            {

                // C++ satır 4833-4834: SkillTree açıksa kapat

                if (_uiSkillTree != null && _uiSkillTree.activeSelf)

                    ShowSkillTree(false);

                ShowInventory(true);   // C++ satır 4837: Open()

            }

        }

        /// <summary>

        /// Inventory panelini göster/gizle.

        /// C++ referans: UIInventory.cpp Open() satır 135-153, Close() satır 168-202

        /// Open: GoldUpdate + SetVisible

        /// Close: state temizle + dinamik item'ları yok et

        /// </summary>

                /// <summary>

        /// Enforces mutual exclusion rules when a panel is opened.

        /// </summary>

        private void OnPanelOpened(GameObject openedPanel)

        {

            if (openedPanel == null) return;

            // Close inspect panel when any other panel is opened

            if (KOInspectManager.Instance != null && KOInspectManager.Instance.IsInspectActive)

            {

                KOInspectManager.Instance.CloseInspectWindows();

            }

            // 1. Mutlak Tekil (Absolute Exclusive) Paneller - NPC, Upgrade, Pazar, Işınlanma, Mağaza vb.

            bool isAbsoluteExclusive = 

                openedPanel == _uiGemChestExchange ||

                openedPanel == _uiItemUpgrade || 

                openedPanel == _uiRingUpgrade || 

                openedPanel == _uiFastUpgrade || 

                openedPanel == _uiUpgradeSelect || 

                openedPanel == _uiStallView || 

                openedPanel == _uiMerchantSetup || 

                openedPanel == _uiWarp || 

                openedPanel == _uiWarehouse ||

                openedPanel == _uiTransaction ||

                openedPanel == _uiQuestTalk ||

                openedPanel == _uiQuestMenu;

            if (isAbsoluteExclusive)

            {

                // Kapatılabilecek tüm diğer panelleri kapat

                if (_uiInventory != null && _uiInventory != openedPanel && _uiInventory.activeSelf) ShowInventory(false);

                if (_uiSkillTree != null && _uiSkillTree != openedPanel && _uiSkillTree.activeSelf) ShowSkillTree(false);

                if (_uiCmdList != null && _uiCmdList != openedPanel && _uiCmdList.activeSelf) _uiCmdList.GetComponent<CmdListUI>()?.Close();

                if (_uiGameOptions != null && _uiGameOptions != openedPanel && _uiGameOptions.activeSelf) CloseGameOptions();

                if (_uiVarious != null && _uiVarious != openedPanel && _uiVarious.activeSelf)

                {

                    _uiVarious.SetActive(false);

                    UpdateStatDistributionPanelVisibility();

                }

                if (_uiWarehouse != null && _uiWarehouse != openedPanel && _uiWarehouse.activeSelf) ShowWarehouse(false);

                if (_uiWarp != null && _uiWarp != openedPanel && _uiWarp.activeSelf) ShowWarp(false);

                if (_uiStallView != null && _uiStallView != openedPanel && _uiStallView.activeSelf) ShowStallView(false);

                if (_uiMerchantSetup != null && _uiMerchantSetup != openedPanel && _uiMerchantSetup.activeSelf) ShowMerchantSetup(false);

                if (_uiItemUpgrade != null && _uiItemUpgrade != openedPanel && _uiItemUpgrade.activeSelf) ShowItemUpgrade(false);

                if (_uiRingUpgrade != null && _uiRingUpgrade != openedPanel && _uiRingUpgrade.activeSelf) ShowRingUpgrade(false);

                if (_uiGemChestExchange != null && _uiGemChestExchange != openedPanel && _uiGemChestExchange.activeSelf) ShowGemChestExchange(false);

                if (_uiFastUpgrade != null && _uiFastUpgrade != openedPanel && _uiFastUpgrade.activeSelf) ShowFastUpgrade(false);

                if (_uiUpgradeSelect != null && _uiUpgradeSelect != openedPanel && _uiUpgradeSelect.activeSelf) ShowUpgradeSelect(false);

                if (_uiTransaction != null && _uiTransaction != openedPanel && _uiTransaction.activeSelf) ShowTransaction(false);

                if (_uiQuestTalk != null && _uiQuestTalk != openedPanel && _uiQuestTalk.activeSelf) _uiQuestTalk.SetActive(false);

                if (_uiQuestMenu != null && _uiQuestMenu != openedPanel && _uiQuestMenu.activeSelf) _uiQuestMenu.SetActive(false);

            }

            else

            {

                // 2. Sağ Bölge Kişisel Menüleri (Envanter, SkillTree, CmdList, GameOptions) - Kendi aralarında tekil, Various'u kapatmaz!

                bool isRightPersonalMenu = 

                    openedPanel == _uiInventory || 

                    openedPanel == _uiSkillTree ||

                    openedPanel == _uiCmdList ||

                    openedPanel == _uiGameOptions;

                if (isRightPersonalMenu)

                {

                    if (_uiInventory != null && _uiInventory != openedPanel && _uiInventory.activeSelf) ShowInventory(false);

                    if (_uiSkillTree != null && _uiSkillTree != openedPanel && _uiSkillTree.activeSelf) ShowSkillTree(false);

                    if (_uiCmdList != null && _uiCmdList != openedPanel && _uiCmdList.activeSelf) _uiCmdList.GetComponent<CmdListUI>()?.Close();

                    if (_uiGameOptions != null && _uiGameOptions != openedPanel && _uiGameOptions.activeSelf) CloseGameOptions();

                    // Mutlak tekil panelleri kapat

                    if (_uiItemUpgrade != null && _uiItemUpgrade.activeSelf) ShowItemUpgrade(false);

                    if (_uiRingUpgrade != null && _uiRingUpgrade.activeSelf) ShowRingUpgrade(false);

                    if (_uiGemChestExchange != null && _uiGemChestExchange.activeSelf) ShowGemChestExchange(false);

                    if (_uiFastUpgrade != null && _uiFastUpgrade.activeSelf) ShowFastUpgrade(false);

                    if (_uiUpgradeSelect != null && _uiUpgradeSelect.activeSelf) ShowUpgradeSelect(false);

                    if (_uiStallView != null && _uiStallView.activeSelf) ShowStallView(false);

                    if (_uiMerchantSetup != null && _uiMerchantSetup.activeSelf) ShowMerchantSetup(false);

                    if (_uiWarp != null && _uiWarp.activeSelf) ShowWarp(false);

                    if (_uiWarehouse != null && _uiWarehouse.activeSelf) ShowWarehouse(false);

                    if (_uiTransaction != null && _uiTransaction.activeSelf) ShowTransaction(false);

                    if (_uiQuestTalk != null && _uiQuestTalk.activeSelf) _uiQuestTalk.SetActive(false);

                    if (_uiQuestMenu != null && _uiQuestMenu.activeSelf) _uiQuestMenu.SetActive(false);

                }

                else if (openedPanel == _uiVarious)

                {

                    // Sol bölge kişisel menüsü (Karakter Detay) - Envanter/SkillTree'ye dokunmaz, mutlak tekil panelleri kapatır!

                    if (_uiItemUpgrade != null && _uiItemUpgrade.activeSelf) ShowItemUpgrade(false);

                    if (_uiRingUpgrade != null && _uiRingUpgrade.activeSelf) ShowRingUpgrade(false);

                    if (_uiGemChestExchange != null && _uiGemChestExchange.activeSelf) ShowGemChestExchange(false);

                    if (_uiFastUpgrade != null && _uiFastUpgrade.activeSelf) ShowFastUpgrade(false);

                    if (_uiUpgradeSelect != null && _uiUpgradeSelect.activeSelf) ShowUpgradeSelect(false);

                    if (_uiStallView != null && _uiStallView.activeSelf) ShowStallView(false);

                    if (_uiMerchantSetup != null && _uiMerchantSetup.activeSelf) ShowMerchantSetup(false);

                    if (_uiWarp != null && _uiWarp.activeSelf) ShowWarp(false);

                    if (_uiWarehouse != null && _uiWarehouse.activeSelf) ShowWarehouse(false);

                    if (_uiTransaction != null && _uiTransaction.activeSelf) ShowTransaction(false);

                    if (_uiQuestTalk != null && _uiQuestTalk.activeSelf) _uiQuestTalk.SetActive(false);

                    if (_uiQuestMenu != null && _uiQuestMenu.activeSelf) _uiQuestMenu.SetActive(false);

                    if (_uiCmdList != null && _uiCmdList.activeSelf) _uiCmdList.GetComponent<CmdListUI>()?.Close();

                }

            }

        }

        public void CloseAllActivePanelsForInspect()

        {

            if (_uiInventory != null && _uiInventory.activeSelf) ShowInventory(false);

            if (_uiSkillTree != null && _uiSkillTree.activeSelf) ShowSkillTree(false);

            if (_uiCmdList != null && _uiCmdList.activeSelf) _uiCmdList.GetComponent<CmdListUI>()?.Close();

            if (_uiGameOptions != null && _uiGameOptions.activeSelf) CloseGameOptions();

            if (_uiWarehouse != null && _uiWarehouse.activeSelf) ShowWarehouse(false);

            if (_uiWarp != null && _uiWarp.activeSelf) ShowWarp(false);

            if (_uiTransaction != null && _uiTransaction.activeSelf) ShowTransaction(false);

            if (_uiUpgradeSelect != null && _uiUpgradeSelect.activeSelf) ShowUpgradeSelect(false);

            if (_uiItemUpgrade != null && _uiItemUpgrade.activeSelf) ShowItemUpgrade(false);

            if (_uiRingUpgrade != null && _uiRingUpgrade.activeSelf) ShowRingUpgrade(false);

            if (_uiGemChestExchange != null && _uiGemChestExchange.activeSelf) ShowGemChestExchange(false);

            if (_uiFastUpgrade != null && _uiFastUpgrade.activeSelf) ShowFastUpgrade(false);

            if (_uiStallView != null && _uiStallView.activeSelf) ShowStallView(false);

            if (_uiMerchantSetup != null && _uiMerchantSetup.activeSelf) ShowMerchantSetup(false);

            if (_uiVarious != null && _uiVarious.activeSelf)

            {

                _uiVarious.SetActive(false);

                UpdateStatDistributionPanelVisibility();

            }

        }

public void ShowInventory(bool show)

        {

            if (_uiInventory == null) return;

            if (show)

            {

                var sw = System.Diagnostics.Stopwatch.StartNew();

                OnPanelOpened(_uiInventory);

                long t1 = sw.ElapsedMilliseconds;

                _uiInventory.SetActive(true);

                long t2 = sw.ElapsedMilliseconds;

                _uiInventory.transform.SetAsLastSibling(); // Bring to front of canvas

                // C++ UIInventory.cpp satır 143: GoldUpdate()

                var gm = EntropyOnline.Core.GameManager.Instance;

                if (gm != null)

                    UpdateGold(gm.Gold);

                long t3 = sw.ElapsedMilliseconds;

                // Open-KO birebir: UIInventory::Open() → InitIconUpdate()

                // Panel açılınca KOInventory modelinden güncel veriyi reconstruct et

                RefreshInventoryUI();

                long t4 = sw.ElapsedMilliseconds;

                if (KOInventory.Instance != null)

                {

                    // Character preview disabled

                }

                // Mobil adaptasyon: Sağ panel değişikliği — skill bar'ı güncelle

                RepositionSkillBarForPanel();

                long t5 = sw.ElapsedMilliseconds;

                // Debug.LogWarning($"[INV-PROFILE] Open Inventory Profile:\n" +

                //                  $"  - OnPanelOpened: {t1}ms\n" +

                //                  $"  - SetActive(true): {t2 - t1}ms\n" +

                //                  $"  - UpdateGold: {t3 - t2}ms\n" +

                //                  $"  - RefreshInventoryUI: {t4 - t3}ms\n" +

                //                  $"  - RepositionSkillBar: {t5 - t4}ms\n" +

                //                  $"  - Total: {t5}ms");

            }

            else

            {

                // Kapatırken seçimi temizle

                _selectedInventoryIndex = -1;

                var slide = _uiInventory.GetComponent<KOUIPanelSlideIn>();

                if (slide != null)

                {

                    slide.SlideOut(() => {

                        _uiInventory.SetActive(false);

                        if (KOInventory.Instance != null)

                        {

                            KOInventory.Instance.CleanupCharacterPreview();

                        }

                        RepositionSkillBarForPanel();

                    });

                    RepositionSkillBarForPanel();

                }

                else

                {

                    _uiInventory.SetActive(false);

                    if (KOInventory.Instance != null)

                    {

                        KOInventory.Instance.CleanupCharacterPreview();

                    }

                    RepositionSkillBarForPanel();

                }

            }

        }

        /// <summary>

        /// C++ birebir: UIManager.cpp:538-558 — UserMoveHideUIs()

        /// Karakter hareket ettiğinde UISTYLE_USER_MOVE_HIDE flag'li panelleri kapatır.

        /// GameProcMain.cpp:4146 — Warehouse: UISTYLE_USER_MOVE_HIDE | UISTYLE_POS_RIGHT

        /// GameProcMain.cpp:4061 — Transaction: UISTYLE_POS_RIGHT | UISTYLE_USER_MOVE_HIDE

