        public void UserMoveHideUIs()

        {

            // C++ birebir: UIManager.cpp:549-553

            // if (pUI->IsVisible() && (pUI->GetStyle() & UISTYLE_USER_MOVE_HIDE))

            //     pUI->SetVisibleWithNoSound(false, true);

            bool bHide = false;

            // Warehouse — C++ GameProcMain.cpp:4146

            if (_uiWarehouse != null && _uiWarehouse.activeSelf)

            {

                ShowWarehouse(false);

                KOWarehouseManager.Instance?.LeaveWareHouseState();

                bHide = true;

            }

            // Transaction (shop) — C++ GameProcMain.cpp:4061

            // C++ birebir: SetVisibleWithNoSound(false, true) → ItemMoveFromThisToInv() (satır 1716)

            if (_uiTransaction != null && _uiTransaction.activeSelf)

            {

                ShowTransaction(false);

                bHide = true;

            }

            // Warp — C++ GameProcMain.cpp:4027

            if (_uiWarp != null && _uiWarp.activeSelf)

            {

                ShowWarp(false, true);

                bHide = true;

            }

            // DroppedItem — C++ GameProcMain.cpp:4051

            if (_uiDroppedItem != null && _uiDroppedItem.activeSelf)

            {

                _uiDroppedItem.SetActive(false);

                bHide = true;

            }

            // CountableItemEdit

            if (_uiCountableEdit != null && _uiCountableEdit.activeSelf)

            {

                HideCountableEdit();

                bHide = true;

            }

            // StallView (Pazar İzleme)

            if (_uiStallView != null && _uiStallView.activeSelf)

            {

                EntropyOnline.Trade.KOMerchantManager.Instance?.SendMerchantTradeCancel();

                ShowStallView(false);

                bHide = true;

            }

            if (bHide)

            {

            }

        }

        private float GetPanelTargetX(GameObject panel, RectTransform rt)
        {
            if (panel == null || rt == null) return 0f;
            var slide = panel.GetComponent<KOUIPanelSlideIn>();
            if (slide != null) return slide.TargetX;
            return rt.anchoredPosition.x;
        }

        public void RepositionSkillBarForPanel(bool instant = false)
        {
            var skillBar = MobileSkillBar.Instance;
            if (skillBar == null) return;

            var skillBarCanvas = skillBar.GetComponentInChildren<Canvas>();

            // Slide skillbar right offscreen when Warp/Teleport UI or Trade UI is open
            bool isWarpVisible = _uiWarp != null && _uiWarp.activeSelf;
            var warpSlide = _uiWarp?.GetComponent<KOUIPanelSlideIn>();
            if (warpSlide != null && warpSlide.IsSlidingOut)
            {
                isWarpVisible = false;
            }

            bool isTradeVisible = _uiPersonalTrade != null && _uiPersonalTrade.activeSelf;
            var tradeSlide = _uiPersonalTrade?.GetComponent<KOUIPanelSlideIn>();
            if (tradeSlide != null && tradeSlide.IsSlidingOut)
            {
                isTradeVisible = false;
            }

            // Check if game options panel is visible.
            bool isGameOptionsVisible = _uiGameOptions != null && _uiGameOptions.activeSelf;
            var gameOptionsSlide = _uiGameOptions?.GetComponent<KOUIPanelSlideIn>();
            if (gameOptionsSlide != null && gameOptionsSlide.IsSlidingOut) isGameOptionsVisible = false;

            if (isGameOptionsVisible)
            {
                instant = true;
            }

            float maxPanelPixels = 0f;
            bool isWarpOrTradeVisible = isWarpVisible || isTradeVisible;
            if (!isWarpOrTradeVisible)
            {
                float mainScale = _canvas != null ? _canvas.scaleFactor : 1f;

                // Helper to get screen pixel width of standard right panels
                // Using rt.rect.width instead of sizeDelta.x to correctly handle layout/stretch panels
                System.Func<GameObject, RectTransform, float> getVisualWidth = (panel, rt) =>
                {
                    if (panel == null || rt == null) return 0f;
                    float visualScale = panel.transform.localScale.x * mainScale;
                    float targetX = GetPanelTargetX(panel, rt);
                    return rt.rect.width * visualScale - targetX * mainScale;
                };

                // Check Inspect Player UI
                if (KOInspectManager.Instance != null && KOInspectManager.Instance.IsInspectActive)
                {
                    var rt = KOInspectManager.Instance.InspectInventoryPanel?.GetComponent<RectTransform>();
                    if (rt != null)
                    {
                        float inspectWidthCanvas = 272f + rt.rect.width - 26f - 10f;
                        maxPanelPixels = Mathf.Max(maxPanelPixels, inspectWidthCanvas * mainScale);
                    }
                }

                // Check Gem Chest Exchange
                bool isGemVisible = _uiGemChestExchange != null && _uiGemChestExchange.activeSelf;
                var gemSlide = _uiGemChestExchange?.GetComponent<KOUIPanelSlideIn>();
                if (gemSlide != null && gemSlide.IsSlidingOut) isGemVisible = false;
                if (isGemVisible)
                {
                    var rt = _uiGemChestExchange.GetComponent<RectTransform>();
                    if (rt != null)
                    {
                        float targetX = (gemSlide != null) ? gemSlide.TargetX : -50f;
                        float visualScale = _uiGemChestExchange.transform.localScale.x * mainScale;
                        maxPanelPixels = Mathf.Max(maxPanelPixels, rt.rect.width * visualScale - targetX * mainScale);
                    }
                }

                // Check Inventory
                bool isInventoryVisible = _uiInventory != null && _uiInventory.activeSelf;
                var invSlide = _uiInventory?.GetComponent<KOUIPanelSlideIn>();
                if (invSlide != null && invSlide.IsSlidingOut) isInventoryVisible = false;
                if (isInventoryVisible)
                {
                    var rt = _uiInventory.GetComponent<RectTransform>();
                    maxPanelPixels = Mathf.Max(maxPanelPixels, getVisualWidth(_uiInventory, rt));
                }

                // Check Merchant Control
                bool isMerchantControlVisible = _uiMerchantControl != null && _uiMerchantControl.activeSelf;
                var merchantControlSlide = _uiMerchantControl?.GetComponent<KOUIPanelSlideIn>();
                if (merchantControlSlide != null && merchantControlSlide.IsSlidingOut) isMerchantControlVisible = false;
                if (isMerchantControlVisible)
                {
                    var rt = _uiMerchantControl.GetComponent<RectTransform>();
                    maxPanelPixels = Mathf.Max(maxPanelPixels, getVisualWidth(_uiMerchantControl, rt));
                }

                // Check Inn Hostess Panel
                if (InnUI.Instance != null && InnUI.Instance.IsVisible && InnUI.Instance.Panel != null && InnUI.Instance.Panel.activeSelf)
                {
                    var rt = InnUI.Instance.Panel.GetComponent<RectTransform>();
                    if (rt != null)
                    {
                        float visualScale = InnUI.Instance.Panel.transform.localScale.x * mainScale;
                        maxPanelPixels = Mathf.Max(maxPanelPixels, rt.rect.width * visualScale);
                    }
                }

                // Check Magic Anvil (Upgrade Select)
                if (_uiUpgradeSelect != null && _uiUpgradeSelect.activeSelf)
                {
                    var rt = _uiUpgradeSelect.GetComponent<RectTransform>();
                    if (rt != null)
                    {
                        float visualScale = _uiUpgradeSelect.transform.localScale.x * mainScale;
                        maxPanelPixels = Mathf.Max(maxPanelPixels, rt.rect.width * visualScale);
                    }
                }

                // Check Skill Tree
                bool isSkillTreeVisible = _uiSkillTree != null && _uiSkillTree.activeSelf;
                var skillTreeSlide = _uiSkillTree?.GetComponent<KOUIPanelSlideIn>();
                if (skillTreeSlide != null && skillTreeSlide.IsSlidingOut) isSkillTreeVisible = false;
                if (isSkillTreeVisible)
                {
                    var rt = _uiSkillTree.GetComponent<RectTransform>();
                    maxPanelPixels = Mathf.Max(maxPanelPixels, getVisualWidth(_uiSkillTree, rt));
                }

                // Check Warehouse
                if (_uiWarehouse != null && _uiWarehouse.activeSelf)
                {
                    var rt = _uiWarehouse.GetComponent<RectTransform>();
                    maxPanelPixels = Mathf.Max(maxPanelPixels, getVisualWidth(_uiWarehouse, rt));
                }

                // Check Transaction
                if (_uiTransaction != null && _uiTransaction.activeSelf)
                {
                    var rt = _uiTransaction.GetComponent<RectTransform>();
                    maxPanelPixels = Mathf.Max(maxPanelPixels, getVisualWidth(_uiTransaction, rt));
                }

                // Check Item Upgrade
                if (_uiItemUpgrade != null && _uiItemUpgrade.activeSelf)
                {
                    var rt = _uiItemUpgrade.GetComponent<RectTransform>();
                    maxPanelPixels = Mathf.Max(maxPanelPixels, getVisualWidth(_uiItemUpgrade, rt));
                }

                // Check Fast Upgrade
                if (_uiFastUpgrade != null && _uiFastUpgrade.activeSelf)
                {
                    var rt = _uiFastUpgrade.GetComponent<RectTransform>();
                    maxPanelPixels = Mathf.Max(maxPanelPixels, getVisualWidth(_uiFastUpgrade, rt));
                }

                // Check Ring Upgrade
                if (_uiRingUpgrade != null && _uiRingUpgrade.activeSelf)
                {
                    var rt = _uiRingUpgrade.GetComponent<RectTransform>();
                    maxPanelPixels = Mathf.Max(maxPanelPixels, getVisualWidth(_uiRingUpgrade, rt));
                }

                // Check Command List
                bool isCmdListVisible = _uiCmdList != null && _uiCmdList.activeSelf;
                var cmdList = _uiCmdList?.GetComponent<CmdListUI>();
                if (cmdList != null && cmdList.IsClosing) isCmdListVisible = false;
                if (isCmdListVisible)
                {
                    var rt = _uiCmdList.GetComponent<RectTransform>();
                    maxPanelPixels = Mathf.Max(maxPanelPixels, getVisualWidth(_uiCmdList, rt));
                }
            } // End of if (!isWarpOrTradeVisible)

            float targetOffset = 0f;
            if (isWarpOrTradeVisible)
            {
                targetOffset = 400f;
            }
            else
            {
                float mainScale = _canvas != null ? _canvas.scaleFactor : 1f;
                float sbScale = 1f;
                if (skillBarCanvas != null)
                {
                    var skillBarScaler = skillBarCanvas.GetComponent<CanvasScaler>();
                    sbScale = skillBarScaler != null ? skillBarScaler.scaleFactor : skillBarCanvas.scaleFactor;
                }
                if (sbScale <= 0f) sbScale = 1f;

                if (isGameOptionsVisible)
                {
                    float uiScaleMultiplier = Mathf.Lerp(0.7f, 1.3f, GameOptionsManager.Instance.Graphic3_UIScale);
                    targetOffset = (-360f * uiScaleMultiplier - 115f * mainScale) / sbScale;
                }
                else if (maxPanelPixels > 0f)
                {
                    targetOffset = (-maxPanelPixels - 65f * mainScale) / sbScale;
                }
            }

            if (instant || Mathf.Abs(targetOffset - _lastSkillBarRepositionOffset) > 0.5f)
            {
                _lastSkillBarRepositionOffset = targetOffset;
                if (instant)
                    skillBar.SetHorizontalOffsetInstant(targetOffset);
                else
                    skillBar.SetHorizontalOffset(targetOffset);
            }

            if (isWarpOrTradeVisible || isGameOptionsVisible || maxPanelPixels > 0f)
            {
                if (_mobileTopRightCanvas != null)
                {
                    _mobileTopRightCanvas.sortingOrder = 95;
                }
                if (skillBarCanvas != null)
                {
                    skillBarCanvas.sortingOrder = 95;
                }
            }
            else
            {
                if (_mobileTopRightCanvas != null)
                {
                    _mobileTopRightCanvas.sortingOrder = 105;
                }
                if (skillBarCanvas != null)
                {
                    skillBarCanvas.sortingOrder = 110;
                }
            }
        }

        /// <summary>

        /// Open-KO birebir: UIInventory.cpp InitIconUpdate() satır 394-443

        /// + CheckIconDropIfSuccessSendToServer() satır 710-737 area bazlı drop hedef belirleme.

        ///

        /// C++ mekanizma:

        ///   - UIF'de 14 equip area (UI_AREA_TYPE_SLOT=1) + 28 bag area (UI_AREA_TYPE_INV=2) SABİT

        ///   - InitIconUpdate: m_pMySlot[i] != null ise area'ya icon koy

        ///   - CheckIconDropIfSuccessSendToServer: GetChildAreaByiOrder ile TÜM area'ları test et

        ///     → pArea->IsIn(ptCur.x, ptCur.y) → iDestiOrder = i

        ///   - Boş area'lar da drop hedefi olabilir

        ///

        /// Bizde: Tüm 14 equip + 28 bag slot'a SABİT KOItemDragHandler konteyneri koyuyoruz.

        /// İçinde item varsa ikon oluşuyor, yoksa saydam boş slot (drop hedefi olarak kalıyor).

        /// </summary>

        public void PopulateInventory(InventoryItemData[] items)

        {

            _currentInventoryItems = items;

            _selectedInventoryIndex = -1;

            // Eski dinamik item'ları temizle

            foreach (var obj in _inventorySlotItems)

                if (obj != null) Destroy(obj);

            _inventorySlotItems.Clear();

            foreach (var obj in _inventoryBagItems)

                if (obj != null) Destroy(obj);

            _inventoryBagItems.Clear();

            if (_uiInventory == null) return;

            Transform invRoot = _uiInventory.transform;

            // ================================================

            // DEBUG: TÜM area type'larını logla (type=1 equip var mı?)

            // ================================================

            var allKOAreas = invRoot.GetComponentsInChildren<KOUIArea>(true);

            var typeCounts = new System.Collections.Generic.Dictionary<int, int>();

            foreach (var area in allKOAreas)

            {

                if (!typeCounts.ContainsKey(area.AreaType)) typeCounts[area.AreaType] = 0;

                typeCounts[area.AreaType]++;

            }

            string typeReport = "";

            foreach (var kvp in typeCounts)

                typeReport += $"type={kvp.Key}:{kvp.Value} ";

            // Tasarım özgünleştirme: persistent slot soket arka planları ekle

            foreach (var area in allKOAreas)

            {

                if (area.AreaType == 1 || area.AreaType == 2)

                {

                    var areaImg = area.GetComponent<Image>() ?? area.gameObject.AddComponent<Image>();

                    areaImg.sprite = GetSkillThemeGlassSlotSprite("slot_socket_glass_v5", 45);

                    areaImg.color = Color.white;

                    areaImg.raycastTarget = false;

                }

            }

            // Equip area'ları topla (type=1) — C++ birebir: UI_AREA_TYPE_SLOT=1

            var equipAreaRTs = new System.Collections.Generic.List<RectTransform>();

            // Bag area'ları topla (type=2) — C++ birebir: UI_AREA_TYPE_INV=2

            var bagAreaRTs = new System.Collections.Generic.List<RectTransform>();

            foreach (var area in allKOAreas)

            {

                var rt = area.GetComponent<RectTransform>();

                if (area.AreaType == 1)

                    equipAreaRTs.Add(rt);

                else if (area.AreaType == 2)

                    bagAreaRTs.Add(rt);

            }

            // Bag area'ları sırala: sol-üstten sağ-alta

            bagAreaRTs.Sort((a, b) =>

            {

                int yCompare = b.anchorMin.y.CompareTo(a.anchorMin.y);

                return yCompare != 0 ? yCompare : a.anchorMin.x.CompareTo(b.anchorMin.x);

            });

            // ================================================

            // EQUIP SLOT'LAR

            // ================================================

            for (int i = 0; i < KOInventory.ITEM_SLOT_COUNT; i++)

            {

                var slotObj = new GameObject($"EqSlot_{i}");

                slotObj.transform.SetParent(invRoot, false);

                var slotRT = slotObj.AddComponent<RectTransform>();

                // C++ birebir: GetChildAreaByiOrder(UI_AREA_TYPE_SLOT=1, i)

                if (i < equipAreaRTs.Count)

                {

                    var areaRT = equipAreaRTs[i];

                    slotRT.anchorMin = areaRT.anchorMin;

                    slotRT.anchorMax = areaRT.anchorMax;

                    slotRT.offsetMin = areaRT.offsetMin;

                    slotRT.offsetMax = areaRT.offsetMax;

                }

                else

                {

                    // Type=1 area yok — slot'u gizle (debug loglardan type dağılımını kontrol et)

                    slotRT.anchorMin = new Vector2(0, 1);

                    slotRT.anchorMax = new Vector2(0, 1);

                    slotRT.pivot = new Vector2(0, 1);

                    slotRT.sizeDelta = new Vector2(32, 32);

                    slotRT.anchoredPosition = new Vector2(-100, -100);

                }

                // KOInventory modelinden slot verisini oku — C++ m_pMySlot[i]

                KOInventory.ItemSlot slotData = null;

                if (KOInventory.Instance != null)

                    slotData = KOInventory.Instance.m_pMySlot[i];

                if (slotData != null && !slotData.IsEmpty)

                {

                    int iconId = ResolveIconId(slotData.itemId);

                    var icon = KOItemIconLoader.LoadItemIcon(iconId);

                    if (icon != null)

                    {

                        var img = slotObj.AddComponent<Image>();

                        img.sprite = icon;

                        img.raycastTarget = true;

                    }

                    else

                    {

                        // İkon yüklenemedi — sadece renkli kutu, TEXT YOK (dikey yazı sorunu)

                        var img = slotObj.AddComponent<Image>();

                        img.color = new Color(0.2f, 0.3f, 0.5f, 0.5f);

                        img.raycastTarget = true;

                    }

                    // Mobil adaptasyon: single-tap=tooltip, double-tap=unequip

                    // C++ birebir: Render() → GetHighlightIconItem() → DisplayTooltipsEnable(spItem)

                    // spItem->pItemBasic->dwID ile tooltip gösterir

                    var slotHandler = slotObj.AddComponent<KOItemSlotHandler>();

                    slotHandler.slotType = KOItemSlotHandler.SlotType.EquipSlot;

                    slotHandler.slotIndex = i;

                    slotHandler.itemData = slotData.serverData;

                    // serverData null ise (KO paket yolu) → itemId ile fallback

                    if (slotData.serverData == null)

                        slotHandler.tooltipItemDefId = slotData.itemId;

                }

                else

                {

                    // Boş slot — saydam arka plan, drop hedefi olarak kalır (arka plan KOUIArea üzerinde)

                    var img = slotObj.AddComponent<Image>();

                    img.color = Color.clear;

                    img.raycastTarget = true;

                }

                // Open-KO birebir: HER slot'a KOItemDragHandler — boş da olsa drop hedefi

                var dragHandler = slotObj.AddComponent<KOItemDragHandler>();

                dragHandler.district = KOItemDragHandler.SlotDistrict.EquipSlot;

                dragHandler.slotIndex = i;

                _inventorySlotItems.Add(slotObj);

            }

            // ================================================

            // BAG SLOT'LAR — bagAreaRTs listesinden (anchorMin.y <= 0.40)

            // ================================================

            // Bag area'ları sırala: sol-üstten sağ-alta

            bagAreaRTs.Sort((a, b) =>

            {

                int yCompare = b.anchorMin.y.CompareTo(a.anchorMin.y);

                return yCompare != 0 ? yCompare : a.anchorMin.x.CompareTo(b.anchorMin.x);

            });

            for (int i = 0; i < KOInventory.MAX_ITEM_INVENTORY; i++)

            {

                var slotObj = new GameObject($"BagSlot_{i}");

                slotObj.transform.SetParent(invRoot, false);

                var slotRT = slotObj.AddComponent<RectTransform>();

                if (i < bagAreaRTs.Count)

                {

                    var areaRT = bagAreaRTs[i];

                    slotRT.anchorMin = areaRT.anchorMin;

                    slotRT.anchorMax = areaRT.anchorMax;

                    slotRT.offsetMin = areaRT.offsetMin;

                    slotRT.offsetMax = areaRT.offsetMax;

                }

                else

                {

                    // Fallback grid

                    slotRT.anchorMin = new Vector2(0, 1);

                    slotRT.anchorMax = new Vector2(0, 1);

                    slotRT.pivot = new Vector2(0, 1);

                    float iconSize = 45f;

                    int col = i % 7;

                    int row = i / 7;

                    slotRT.anchoredPosition = new Vector2(5f + col * 48f, -5f - row * 48f);

                    slotRT.sizeDelta = new Vector2(iconSize, iconSize);

                }

                // KOInventory modelinden bag verisini oku — C++ m_pMyInvWnd[i]

                KOInventory.ItemSlot bagData = null;

                if (KOInventory.Instance != null)

                    bagData = KOInventory.Instance.m_pMyInvWnd[i];

                if (bagData != null && !bagData.IsEmpty)

                {

                    bool isOnStall = false;

                    // C++ satır 426-441: m_pMyInvWnd[i]->pUIIcon SetTex(szIconFN)

                    // Open-KO birebir: dwIDIcon lookup — itemId ≠ icon ID

                    int iconId = ResolveIconId(bagData.itemId);

                    var icon = KOItemIconLoader.LoadItemIcon(iconId);

                    if (icon != null)

                    {

                        var img = slotObj.AddComponent<Image>();

                        img.sprite = icon;

                        img.raycastTarget = true;

                        if (isOnStall)

                        {

                            img.color = new Color(0.6f, 0.6f, 0.6f, 0.8f);

                        }

                    }

                    else

                    {

                        // İkon yüklenemedi — sadece renkli kutu, TEXT YOK (dikey yazı sorunu)

                        var img = slotObj.AddComponent<Image>();

                        img.color = isOnStall ? new Color(0.3f, 0.3f, 0.3f, 0.8f) : new Color(0.3f, 0.3f, 0.3f, 0.5f);

                        img.raycastTarget = true;

                    }

                    // C++ Render() count overlay

                    int displayCount = bagData.count;

                    bool showCount = false;

                    var basic = bagData.pItemBasic;

                    if (basic == null && KOInventory.s_pTbl_Items_Basic != null)

                    {

                        KOInventory.s_pTbl_Items_Basic.TryGetValue((uint)(bagData.itemId / 1000 * 1000), out basic);

                    }

                    if (basic != null)

                    {

                        if (basic.byContable == 1 || basic.byContable == 2)

                        {

                            if (bagData.count > 1)

                            {

                                showCount = true;

                            }

                        }

                        else if (basic.byAttachPoint == 15 && bagData.durability > 1)

                        {

                            displayCount = bagData.durability;

                            showCount = true;

                        }

                    }

                    if (showCount)

                    {

                        var countObj = new GameObject("CountText");

                        countObj.transform.SetParent(slotObj.transform, false);

                        var countRT = countObj.AddComponent<RectTransform>();

                        countRT.anchorMin = new Vector2(1, 0);

                        countRT.anchorMax = new Vector2(1, 0);

                        countRT.pivot = new Vector2(1, 0);

                        countRT.anchoredPosition = new Vector2(-2, 2);

                        countRT.sizeDelta = new Vector2(30, 12);

                        var countText = countObj.AddComponent<Text>();

                        countText.text = displayCount.ToString();

                        countText.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");

                        countText.fontSize = 9;

                        countText.color = Color.white;

                        countText.alignment = TextAnchor.LowerRight;

                        countText.raycastTarget = false;

                    }

                    // Mobil adaptasyon: single-tap=tooltip, double-tap=equip/use

                    // C++ birebir: Render() → GetHighlightIconItem() → DisplayTooltipsEnable(spItem)

                    var bagSlotHandler = slotObj.AddComponent<KOItemSlotHandler>();

                    bagSlotHandler.slotIndex = i;

                    bagSlotHandler.itemData = bagData.serverData;

                    // serverData null ise (KO paket yolu) → itemId ile fallback

                    if (bagData.serverData == null)

                        bagSlotHandler.tooltipItemDefId = bagData.itemId;

                    // C++ birebir: shop (UITransactionDlg) açıkken envanter item'ları

                    // UIWND_DISTRICT_TRADE_MY area'sında → NPC'ye satılabilir

                    if (_uiTransaction != null && _uiTransaction.activeSelf)

                    {

                        bagSlotHandler.slotType = KOItemSlotHandler.SlotType.ShopInvSlot;

                        bagSlotHandler.shopNpcId = _shopNpcId;

                        bagSlotHandler.shopTradeId = _shopTradeId;

                        bagSlotHandler.shopItemCount = bagData.count > 0 ? bagData.count : 1;

                        // byContable lookup from item table

                        var basicEntry = KOImport.ItemDataManager.GetItemBasic(bagData.itemId);

                        bagSlotHandler.shopByContable = basicEntry != null ? basicEntry.ByContable : (byte)0;

                    }

                    else

                    {

                        bagSlotHandler.slotType = KOItemSlotHandler.SlotType.BagSlot;

                    }

                }

                else

                {

                    // Boş bag slot — drop hedefi olarak kalır (arka plan KOUIArea üzerinde)

                    var img = slotObj.AddComponent<Image>();

                    img.color = Color.clear;

                    img.raycastTarget = true;

                    // Boş slot'a da KOItemSlotHandler ekle — drag-drop hedefi olsun

                    var emptyHandler = slotObj.AddComponent<KOItemSlotHandler>();

                    emptyHandler.slotIndex = i;

                    if (_uiTransaction != null && _uiTransaction.activeSelf)

                    {

                        emptyHandler.slotType = KOItemSlotHandler.SlotType.ShopInvSlot;

                        emptyHandler.shopNpcId = _shopNpcId;

                        emptyHandler.shopTradeId = _shopTradeId;

                    }

                    else

                    {

                        emptyHandler.slotType = KOItemSlotHandler.SlotType.BagSlot;

                    }

                }

                // Open-KO birebir: HER bag slot'a KOItemDragHandler — boş da olsa drop hedefi

                var bagDragHandler = slotObj.AddComponent<KOItemDragHandler>();

                bagDragHandler.district = KOItemDragHandler.SlotDistrict.BagSlot;

                bagDragHandler.slotIndex = i; // Direkt KOInventory.m_pMyInvWnd indeksi

                _inventoryBagItems.Add(slotObj);

            }

            int eqCount = 0, bagCount = 0;

            if (KOInventory.Instance != null)

            {

                for (int i = 0; i < KOInventory.ITEM_SLOT_COUNT; i++)

                    if (KOInventory.Instance.m_pMySlot[i] != null) eqCount++;

                for (int i = 0; i < KOInventory.MAX_ITEM_INVENTORY; i++)

                    if (KOInventory.Instance.m_pMyInvWnd[i] != null) bagCount++;

            }

            var sortBtn = invRoot.Find("btn_SortInventory");

            if (sortBtn != null)

            {

                sortBtn.SetAsLastSibling();

            }

        }

        /// <summary>

        /// Open-KO birebir: itemId → dwIDIcon lookup.

        /// C++ GameBase.cpp satır 617-621:

        ///   pItem = s_pTbl_Items_Basic.Find(iItemID / 1000 * 1000)

        ///   szIconFN = MakeIconFileName(pItem->dwIDIcon)

        /// dwIDIcon, itemId'den FARKLI bir değerdir — tabloda ayrı sütun.

        /// </summary>

        public static int ResolveIconId(int itemId)

        {

            if (itemId / 1000 * 1000 == 199101000 || itemId / 1000 * 1000 == 199111000)
            {
                return 19910100;
            }

            if (itemId / 1000 * 1000 == 149101000)
            {
                return 14910100;
            }

            if (itemId / 1000 * 1000 == 159301000 || itemId / 1000 * 1000 == 159311000)
            {
                return 15930100;
            }

            if (itemId / 1000 * 1000 == 135750000 || itemId / 1000 * 1000 == 135760000)
            {
                return 13621000;
            }

            if (itemId == 800085000) return 800078000;

            if (itemId <= 0) return 0;

            if (KOInventory.s_pTbl_Items_Basic == null) return itemId; // fallback

            var pItem = KOTableReader.FindItemBasic(KOInventory.s_pTbl_Items_Basic, itemId);

            if (pItem == null) return itemId; // tabloda bulunamazsa raw id dene

            // Query ItemDataManager to check the extension table for upgraded/unique icons

            var ext = KOImport.ItemDataManager.GetItemExt(itemId);

            if (ext != null && ext.DwIDIcon != 0)

            {

                return ext.DwIDIcon;

            }

            return (int)pItem.dwIDIcon;

        }

        /// <summary>

        /// Envanter listesinde bir item seçer.

        /// Seçili item'ı vurgular (sarı text + mavi arka plan).

        /// C++ referans: UIInventory.cpp GetHighlightIconItem() satır 445-458

        /// Mobil adaptasyon: PC'de highlight → mobilde tıklama ile seçim.

        /// </summary>

        private void SelectInventoryItem(int globalIndex)

        {

            if (_currentInventoryItems == null || globalIndex < 0 || globalIndex >= _currentInventoryItems.Length)

                return;

            _selectedInventoryIndex = globalIndex;

            var selectedItem = _currentInventoryItems[globalIndex];

            // Tüm equipped slot'ların vurgulamasını güncelle

            // C++ UISTYLE_ICON_HIGHLIGHT karşılığı — ikon Image rengini ayarla

            for (int i = 0; i < _inventorySlotItems.Count; i++)

            {

                var obj = _inventorySlotItems[i];

                if (obj == null) continue;

                // Bu slot'un global index'ini bul

                int slotGlobalIndex = -1;

                if (_currentInventoryItems != null)

                {

                    int eqCount = 0;

                    for (int j = 0; j < _currentInventoryItems.Length; j++)

                    {

                        if (_currentInventoryItems[j].IsEquipped)

                        {

                            if (eqCount == i) { slotGlobalIndex = j; break; }

                            eqCount++;

                        }

                    }

                }

                bool isSelected = (slotGlobalIndex == globalIndex);

                var img = obj.GetComponent<UnityEngine.UI.Image>();

                if (img != null)

                    img.color = isSelected ? new Color(0.7f, 0.9f, 1f, 1f) : Color.white;

            }

            // Tüm bag slot'ların vurgulamasını güncelle

            for (int i = 0; i < _inventoryBagItems.Count; i++)

            {

                var obj = _inventoryBagItems[i];

                if (obj == null) continue;

                int bagGlobalIndex = -1;

                if (_currentInventoryItems != null)

                {

                    int bagCount = 0;

                    for (int j = 0; j < _currentInventoryItems.Length; j++)

                    {

                        if (!_currentInventoryItems[j].IsEquipped)

                        {

                            if (bagCount == i) { bagGlobalIndex = j; break; }

                            bagCount++;

                        }

                    }

                }

                bool isSelected = (bagGlobalIndex == globalIndex);

                var img = obj.GetComponent<UnityEngine.UI.Image>();

                if (img != null)

                    img.color = isSelected ? new Color(0.7f, 0.9f, 1f, 1f) : Color.white;

            }

            // C++ UIInventory.cpp satır 1541-1570: sağ tıklama → InvOpsSomething

            // → CheckIconDropIfSuccessSendToServer → SendInvMsg

            // Mobilde: tıklama → KOInventory.EquipItem / UnequipItem / UseItem

            if (selectedItem.IsEquipped)

            {

                // C++ InvOpsSomething → Arm→Inv: SendInvMsg(0x02, itemID, slotIndex, invDestIndex)

                // Open-KO birebir: UIInventory.cpp satır 861-916

                if (KOInventory.Instance != null)

                {

                    KOInventory.Instance.UnequipItem(selectedItem.SlotIndex);

                }

            }

            else if (selectedItem.IsConsumable)

            {

                // C++ tüketilebilir item sağ tıklama → kullan

                if (InventoryUI.Instance != null)

                {

                    InventoryUI.Instance.SendUseItem(selectedItem.InstanceId);

                }

            }

            else

            {

                // C++ InvOpsSomething → Inv→Arm: SendInvMsg(0x01, itemID, invIndex, armDestIndex)

                // Open-KO birebir: UIInventory.cpp satır 917-982

                // GetArmDestinationIndex(byAttachPoint) ile doğru slot belirlenir

                if (KOInventory.Instance != null)

                {

                    // Bag'deki index'i bul (KOInventory modelindeki pozisyon)

                    int bagIdx = -1;

                    for (int bi = 0; bi < KOInventory.MAX_ITEM_INVENTORY; bi++)

                    {

                        var bagSlot = KOInventory.Instance.m_pMyInvWnd[bi];

                        if (bagSlot != null && bagSlot.instanceId == selectedItem.InstanceId)

                        {

                            bagIdx = bi;

                            break;

                        }

                    }

                    if (bagIdx >= 0)

                    {

                        KOInventory.Instance.EquipItem(bagIdx);

                    }

                    else

                    {

                        // Fallback: legacy yöntem

                        InventoryUI.Instance?.SendEquipItem(selectedItem.InstanceId, selectedItem.SlotIndex);

                        Debug.LogWarning($"[KOUIMGR] Inventory: KOInventory bag'da bulunamadı, fallback equip → {selectedItem.InstanceId}");

                    }

                }

            }

        }

        /// <summary>

        /// Envanter ağırlık text güncelleme.

        /// C++ referans: UIInventory.cpp UpdateWeight() satır 388-392

        /// </summary>

        public void UpdateWeight(string weight)

        {

            if (_textWeight != null)

            {

                _textWeight.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");

                _textWeight.material = null;

                _textWeight.text = weight;

                _textWeight.color = new Color(0.9f, 0.8f, 0.6f, 1);

            }

        }

        public void ToggleCharacterInfo()

        {

            // C++ birebir: btn_character → m_pUIVar->Open() / m_pUIVar->Close()

            // _uiVarious = el_various_all_us.uif — frame + tüm alt sayfalar tek panel

            if (_uiVarious == null) return;

            bool willShow = !_uiVarious.activeSelf;

            if (willShow)

            {

                if (KODropSearchUI.Instance != null && KODropSearchUI.Instance.gameObject.activeSelf)

                {

                    KODropSearchUI.Instance.Close();

                }

                OnPanelOpened(_uiVarious);

                _uiVarious.SetActive(true);

                _uiVarious.transform.SetAsLastSibling();

                RefreshPageState();

                UpdateStatDistributionPanelVisibility();

            }

            else

            {

                var slide = _uiVarious.GetComponent<KOUIPanelSlideIn>();

                if (slide != null)

                {

                    slide.SlideOut(() => {

                        _uiVarious.SetActive(false);

                        UpdateStatDistributionPanelVisibility();

                    });

                }

                else

                {

                    _uiVarious.SetActive(false);

                    UpdateStatDistributionPanelVisibility();

                }

            }

        }

        /// <summary>

        /// Open-KO birebir: UIPageState::Refresh — tüm string field'ları GameManager'dan günceller.

        /// UIF string ID'leri: string_name, string_level, string_class, string_str, string_sta,

        /// string_dex, string_int, string_cha, string_hp, string_mp, string_hit, string_ac,

        /// string_exp, string_point, string_gold

        /// </summary>

        private void RefreshPageState()

        {

            // C++ birebir: page_state, _uiVarious altındaki child

            if (_uiPageState == null && _uiVarious != null)

            {

                var ps = KOUIRenderer.FindChildByID(_uiVarious.transform, "page_state");

                if (ps != null) _uiPageState = ps.gameObject;

            }

            if (_uiPageState == null) return;

            var gm = GameManager.Instance;

            if (gm == null) return;

            var root = _uiPageState.transform;

            // Translate static labels to match target layout

            var labelMap = new Dictionary<string, string>(System.StringComparer.OrdinalIgnoreCase)

            {

                { "Level", "Level" },

                { "Level:", "Level" },

                { "Class", "Job" },

                { "Class:", "Job" },

                { "Hit Point", "HP Point" },

                { "Hit Point:", "HP Point" },

                { "Mana Point", "MP Point" },

                { "Mana Point:", "MP Point" },

                { "Experience Points", "Exp Points" },

                { "Experience Points:", "Exp Points" },

                { "National Point", "War Points" },

                { "National Point:", "War Points" },

                { "Attack", "Attack" },

                { "Attack:", "Attack" },

                { "Defense", "Defence" },

                { "Defense:", "Defence" },

                { "Flame Attack", "Flame Resist" },

                { "Flame Attack:", "Flame Resist" },

                { "Glacier Attack", "Glacier Resist" },

                { "Glacier Attack:", "Glacier Resist" },

                { "Lightning Attack", "Lightning Resist" },

                { "Lightning Attack:", "Lightning Resist" },

                { "Magic Attack", "Magic Resist" },

                { "Magic Attack:", "Magic Resist" },

                { "Curse Attack", "Curse Resist" },

                { "Curse Attack:", "Curse Resist" },

                { "Poison Attacks", "Poison Resist" },

                { "Poison Attacks:", "Poison Resist" }

            };

            var allTexts = root.GetComponentsInChildren<Text>(true);

            foreach (var txt in allTexts)

            {

                string tClean = txt.text.Trim();

                if (labelMap.TryGetValue(tClean, out string newLabel))

                {

                    txt.text = newLabel;

                }

                else if (tClean.EndsWith(":") && labelMap.TryGetValue(tClean.Substring(0, tClean.Length - 1).Trim(), out string newLabelColon))

                {

                    txt.text = newLabelColon;

                }

            }

            // Hide Manner & Weight elements

            var txtWeightVal = EntropyOnline.Import.KOUIRenderer.FindChildByID(root, "Text_Weight");

            if (txtWeightVal != null) txtWeightVal.gameObject.SetActive(false);

            var txtMannerVal = EntropyOnline.Import.KOUIRenderer.FindChildByID(root, "Text_Manner");

            if (txtMannerVal != null) txtMannerVal.gameObject.SetActive(false);

            foreach (var txt in allTexts)

            {

                if (txt.text == "Weight" || txt.text == "Manner")

                {

                    txt.gameObject.SetActive(false);

                }

            }

            // Perform programmatic layout rearrangement

            RearrangePageStateLayout(root);

            // Set formatted values

            var trCulture = new System.Globalization.CultureInfo("tr-TR");

            long expMax = EntropyOnline.Shared.LevelExpTable.GetExpForLevel(gm.Level);

            var textIdTr = FindChildByIDIgnoreCase(root, "text_Id");

            if (textIdTr != null)

            {

                var txt = textIdTr.GetComponent<Text>();

                if (txt != null) txt.text = gm.CharacterName ?? "";

            }

            SetText(root, "Text_Level", gm.Level.ToString());

            SetText(root, "Text_Class", GetBaseClassText(gm.CharClass));

            SetText(root, "Text_Race", EntropyOnline.Core.KOTextHelper.GetTextByRace(gm.Race));

            SetText(root, "Text_Nation", EntropyOnline.Core.KOTextHelper.GetTextByNation(gm.Nation));

            SetText(root, "Text_HP", $"{gm.CurrentHp.ToString("N0", trCulture)} / {gm.MaxHp.ToString("N0", trCulture)}");

            SetText(root, "Text_MP", $"{gm.CurrentMp.ToString("N0", trCulture)} / {gm.MaxMp.ToString("N0", trCulture)}");

            SetText(root, "Text_Exp", $"{gm.Experience.ToString("N0", trCulture)} / {expMax.ToString("N0", trCulture)}");

            SetText(root, "Text_AP", (gm.TotalHit + gm.AttackDelta).ToString("N0", trCulture));

            SetText(root, "Text_GP", (gm.TotalAc + gm.GuardDelta).ToString("N0", trCulture));

            SetText(root, "Text_Strength", FormatWithDelta(gm.StatStr, gm.StrDelta));

            SetText(root, "Text_Stamina", FormatWithDelta(gm.StatSta, gm.StaDelta));

            SetText(root, "Text_Dexterity", FormatWithDelta(gm.StatDex, gm.DexDelta));

            SetText(root, "Text_Intelligence", FormatWithDelta(gm.StatInt, gm.IntDelta));

            SetText(root, "Text_MagicAttack", FormatWithDelta(gm.StatCha, gm.ChaDelta));

            SetText(root, "Text_BonusPoint", gm.StatPoints.ToString());

            SetText(root, "Text_RealmPoint", $"{gm.Loyalty.ToString("N0", trCulture)} / {gm.LoyaltyMonthly.ToString("N0", trCulture)}");

            if (_btnStatStr != null) _btnStatStr.SetActive(false);

            if (_btnStatSta != null) _btnStatSta.SetActive(false);

            if (_btnStatDex != null) _btnStatDex.SetActive(false);

            if (_btnStatInt != null) _btnStatInt.SetActive(false);

            if (_btnStatCha != null) _btnStatCha.SetActive(false);

            UpdateStatDistributionPanelVisibility();

        }

        private string GetBaseClassText(byte charClass)

        {

            int baseClass = charClass % 100;

            if (baseClass == 1 || baseClass == 5 || baseClass == 6) return "Warrior";

            if (baseClass == 2 || baseClass == 7 || baseClass == 8) return "Rogue";

            if (baseClass == 3 || baseClass == 9 || baseClass == 10) return "Magician";

            if (baseClass == 4 || baseClass == 11 || baseClass == 12) return "Priest";

            return "Unknown Class";

        }

        private Transform FindChildByText(Transform root, string text)

        {

            if (root == null) return null;

            var txts = root.GetComponentsInChildren<Text>(true);

            foreach (var txt in txts)

            {

                if (txt.text.Trim() == text) return txt.transform;

            }

            return null;

        }

        private Sprite GetFadeHorizontalLineSprite()

        {

            int w = 64;

            int h = 1;

            Texture2D tex = new Texture2D(w, h, TextureFormat.RGBA32, false);

            tex.filterMode = FilterMode.Bilinear;

            Color gold = new Color(0.45f, 0.35f, 0.15f, 0.5f);

            for (int x = 0; x < w; x++)

            {

                float alphaFactor = 0f;

                float halfW = w / 2f;

                if (x < halfW)

                {

                    alphaFactor = x / halfW;

                }

                else

                {

                    alphaFactor = (w - x) / halfW;

                }

                alphaFactor = Mathf.Sin(alphaFactor * Mathf.PI / 2f);

                tex.SetPixel(x, 0, new Color(gold.r, gold.g, gold.b, gold.a * alphaFactor));

            }

            tex.Apply();

            return Sprite.Create(tex, new Rect(0, 0, w, h), new Vector2(0.5f, 0.5f));

        }

        private void DrawHorizontalLine(Transform parent, float x, float y, float width)

        {

            var lineObj = new GameObject("HorizontalSeparator");

            lineObj.transform.SetParent(parent, false);

            var img = lineObj.AddComponent<Image>();

            img.sprite = GetFadeHorizontalLineSprite();

            img.type = Image.Type.Simple;

            var rt = lineObj.GetComponent<RectTransform>();

            rt.anchorMin = new Vector2(0, 1);

            rt.anchorMax = new Vector2(0, 1);

            rt.pivot = new Vector2(0, 1);

            rt.anchoredPosition = new Vector2(x, y);

            rt.sizeDelta = new Vector2(width, 1f);

        }

        private void DrawVerticalLine(Transform parent, float x, float y, float height)

        {

            var lineObj = new GameObject("VerticalSeparator");

            lineObj.transform.SetParent(parent, false);

            var img = lineObj.AddComponent<Image>();

            img.color = new Color(0.45f, 0.35f, 0.15f, 0.3f);

            var rt = lineObj.GetComponent<RectTransform>();

            rt.anchorMin = new Vector2(0, 1);

            rt.anchorMax = new Vector2(0, 1);

            rt.pivot = new Vector2(0, 1);

            rt.anchoredPosition = new Vector2(x, y);

            rt.sizeDelta = new Vector2(1f, height);

        }

        private Sprite GetRoundedRectSprite(int radius, Color? fillColor = null, Color? borderColor = null)

        {

            int size = radius * 2 + 4;

            Texture2D tex = new Texture2D(size, size, TextureFormat.RGBA32, false);

            tex.filterMode = FilterMode.Bilinear;

            for (int y = 0; y < size; y++)

            {

                for (int x = 0; x < size; x++)

                {

                    tex.SetPixel(x, y, Color.clear);

                }

            }

            Color fill = fillColor ?? new Color(0.18f, 0.14f, 0.08f, 0.9f);

            Color border = borderColor ?? new Color(0.45f, 0.35f, 0.15f, 0.9f);

            for (int y = 0; y < size; y++)

            {

                for (int x = 0; x < size; x++)

                {

                    float dx = 0;

                    if (x < radius) dx = radius - x;

                    else if (x >= size - radius) dx = x - (size - radius - 1);

                    float dy = 0;

                    if (y < radius) dy = radius - y;

                    else if (y >= size - radius) dy = y - (size - radius - 1);

                    float dist = Mathf.Sqrt(dx * dx + dy * dy);

                    if (dx > 0 && dy > 0)

                    {

                        if (dist < radius - 1f)

                        {

                            tex.SetPixel(x, y, fill);

                        }

                        else if (dist < radius)

                        {

                            float t = radius - dist;

                            tex.SetPixel(x, y, Color.Lerp(border, fill, t));

                        }

                        else if (dist < radius + 1f)

                        {

                            float t = radius + 1f - dist;

                            tex.SetPixel(x, y, new Color(border.r, border.g, border.b, border.a * t));

                        }

                    }

                    else

                    {

                        if (x == 0 || x == size - 1 || y == 0 || y == size - 1)

                        {

                            tex.SetPixel(x, y, border);

                        }

                        else if (x == 1 || x == size - 2 || y == 1 || y == size - 2)

                        {

                            tex.SetPixel(x, y, border);

                        }

                        else

                        {

                            tex.SetPixel(x, y, fill);

                        }

                    }

                }

            }

            tex.Apply();

            return Sprite.Create(tex, new Rect(0, 0, size, size), new Vector2(0.5f, 0.5f), 100f, 0, SpriteMeshType.FullRect, new Vector4(radius, radius, radius, radius));

        }

        private void DrawCapsuleBackground(Transform parent, float x, float y, float width, float height)

        {

            var capObj = new GameObject("CapsuleBackground");

            capObj.transform.SetParent(parent, false);

            var img = capObj.AddComponent<Image>();

            img.sprite = GetRoundedRectSprite(10);

            img.type = Image.Type.Sliced;

            var rt = capObj.GetComponent<RectTransform>();

            rt.anchorMin = new Vector2(0, 1);

            rt.anchorMax = new Vector2(0, 1);

            rt.pivot = new Vector2(0, 1);

            rt.anchoredPosition = new Vector2(x, y);

            rt.sizeDelta = new Vector2(width, height);

            capObj.transform.SetAsFirstSibling();

        }

        private void DrawBoxBackground(Transform parent, float x, float y, float width, float height, Color color)

        {

            var bgObj = new GameObject("BoxBackground");

            bgObj.transform.SetParent(parent, false);

            var img = bgObj.AddComponent<Image>();

            img.color = color;

            var rt = bgObj.GetComponent<RectTransform>();

            rt.anchorMin = new Vector2(0, 1);

            rt.anchorMax = new Vector2(0, 1);

            rt.pivot = new Vector2(0, 1);

            rt.anchoredPosition = new Vector2(x, y);

            rt.sizeDelta = new Vector2(width, height);

            bgObj.transform.SetAsFirstSibling();

        }

        private void DrawButton(Transform parent, float x, float y, float w, float h, string text)
        {
            string name = "Button_" + text.Replace(" ", "");
            Transform existing = parent.Find(name);
            GameObject go;
            UnityEngine.UI.Image img;
            if (existing != null)
            {
                go = existing.gameObject;
                img = go.GetComponent<UnityEngine.UI.Image>();
            }
            else
            {
                go = new GameObject(name);
                go.transform.SetParent(parent, false);
                go.AddComponent<RectTransform>();
                go.AddComponent<CanvasRenderer>();
                img = go.AddComponent<UnityEngine.UI.Image>();
                go.AddComponent<Button>();
                var textGo = new GameObject("Text");
                textGo.transform.SetParent(go.transform, false);
                textGo.AddComponent<RectTransform>();
                var txt = textGo.AddComponent<Text>();
                txt.font = UnityEngine.Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");
                txt.fontSize = 11;
                txt.fontStyle = FontStyle.Bold;
                txt.alignment = TextAnchor.MiddleCenter;
            }

            if (img != null)
            {
                img.sprite = GetRoundedRectSprite(10, new Color(0.25f, 0.04f, 0.04f, 0.75f), new Color(0.45f, 0.35f, 0.15f, 0.9f));
                img.type = UnityEngine.UI.Image.Type.Sliced;
            }

            var rt = go.GetComponent<RectTransform>();

            rt.anchorMin = new Vector2(0f, 1f);

            rt.anchorMax = new Vector2(0f, 1f);

            rt.pivot = new Vector2(0f, 1f);

            rt.anchoredPosition = new Vector2(x, y);

            rt.sizeDelta = new Vector2(w, h);

            var imgComp = go.GetComponent<Image>();

            if (imgComp != null)

            {

                imgComp.color = Color.white; // Keep the exact custom baked fill and border colors

            }

            var btnComp = go.GetComponent<Button>();

            if (btnComp != null)

            {

                btnComp.onClick.RemoveAllListeners();

                btnComp.onClick.AddListener(() => {

                    if (text == "Stat Reset")

                    {

                        var netMgr = KONetworkManager.Instance;

                        if (netMgr != null && netMgr.IsConnected)

                        {

                            using var pkt = new KOPacketWriter(WizOpcode.WIZ_CLASS_CHANGE);

                            pkt.WriteByte(0x03); // CLASS_RESET_STAT_REQ

                            netMgr.SendPacket(pkt);

                        }

                    }

                    else

                    {

                    }

                });

            }

            var txtComp = go.GetComponentInChildren<Text>();

            if (txtComp != null)

            {

                txtComp.text = text;

                txtComp.color = new Color(0.95f, 0.85f, 0.35f, 1f); // Gold text

                var textRt = txtComp.GetComponent<RectTransform>();

                textRt.anchorMin = Vector2.zero;

                textRt.anchorMax = Vector2.one;

                textRt.offsetMin = Vector2.zero;

                textRt.offsetMax = Vector2.zero;

            }

        }

        public void RearrangePageStateLayout(Transform root)

        {

            var labelMap = new Dictionary<string, string>(System.StringComparer.OrdinalIgnoreCase)

            {

                { "Level", "Level" },

                { "Class", "Job" },

                { "Hit Point", "HP Point" },

                { "Mana Point", "MP Point" },

                { "Experience Points", "Exp Points" },

                { "National Point", "War Points" },

                { "Attack", "Attack" },

                { "Defense", "Defence" },

                { "Flame Attack", "Flame Resist" },

                { "Glacier Attack", "Glacier Resist" },

                { "Lightning Attack", "Lightning Resist" },

                { "Magic Attack", "Magic Resist" },

                { "Curse Attack", "Curse Resist" },

                { "Poison Attacks", "Poison Resist" }

            };

            // Widen and lengthen the various panel and page_state to match Skill Tree vertical height (510f)

            var rtPage = root.GetComponent<RectTransform>();

            if (rtPage != null)

            {

                rtPage.sizeDelta = new Vector2(319f, 505f);

            }

            if (root.parent != null)

            {

                var rtVarious = root.parent.GetComponent<RectTransform>();

                if (rtVarious != null)

                {

                    rtVarious.sizeDelta = new Vector2(322f, 510f);

                }

            }

            // Draw horizontal and vertical separators and backgrounds dynamically only once

            bool needsCreate = true;

            for (int i = 0; i < root.childCount; i++)

            {

                string cName = root.GetChild(i).name;

                if (cName == "VerticalSeparator" || cName == "HorizontalSeparator" ||

                    cName == "CapsuleBackground" || cName == "BoxBackground")

                {

                    needsCreate = false;

                    break;

                }

            }

            if (needsCreate)

            {

                // Draw horizontal separators (fading from left/right, centered exactly between rows)

                DrawHorizontalLine(root, 15f, -153f, 290f); // between Job bottom (-147f) and Exp top (-158f)

                DrawHorizontalLine(root, 15f, -215f, 290f); // between War bottom (-210f) and Attack top (-220f)

                DrawHorizontalLine(root, 15f, -251f, 290f); // between Defence bottom (-244f) and Stat Point capsule top (-258f)

                DrawHorizontalLine(root, 15f, -375f, 290f); // between INT bottom (-370f) and Resistance capsule top (-380f)

                // Draw capsules backgrounds (only one capsule for Stat Point to prevent Z-fighting)

                DrawCapsuleBackground(root, 15f, -258f, 120f, 20f); // Shortened Stat Point capsule (W=120f)

                DrawCapsuleBackground(root, 15f, -380f, 95f, 20f);  // Resistance capsule

                // Draw stat box backgrounds (Left Column: STR, DEX, INT)

                DrawBoxBackground(root, 15f, -290f, 135f, 24f, new Color(0.1f, 0.1f, 0.1f, 0.8f));

                DrawBoxBackground(root, 15f, -318f, 135f, 24f, new Color(0.1f, 0.1f, 0.1f, 0.8f));

                DrawBoxBackground(root, 15f, -346f, 135f, 24f, new Color(0.1f, 0.1f, 0.1f, 0.8f));

                // Draw stat box backgrounds (Right Column: HP, MP)

                DrawBoxBackground(root, 170f, -290f, 135f, 24f, new Color(0.1f, 0.1f, 0.1f, 0.8f));

                DrawBoxBackground(root, 170f, -318f, 135f, 24f, new Color(0.1f, 0.1f, 0.1f, 0.8f));

                // Draw vertical separators inside stat boxes

                DrawVerticalLine(root, 55f, -290f, 24f);

                DrawVerticalLine(root, 210f, -290f, 24f);

                DrawVerticalLine(root, 55f, -318f, 24f);

                DrawVerticalLine(root, 210f, -318f, 24f);

                DrawVerticalLine(root, 55f, -346f, 24f);

                // Draw resistance box backgrounds (Left Column, toned down colors)

                DrawBoxBackground(root, 15f, -410f, 135f, 24f, new Color(0.2f, 0.03f, 0.03f, 0.75f)); // Flame

                DrawBoxBackground(root, 15f, -438f, 135f, 24f, new Color(0.04f, 0.04f, 0.16f, 0.75f));  // Glacier

                DrawBoxBackground(root, 15f, -466f, 135f, 24f, new Color(0.15f, 0.03f, 0.15f, 0.75f));   // Lightning

                // Draw resistance box backgrounds (Right Column, toned down colors)

                DrawBoxBackground(root, 170f, -410f, 135f, 24f, new Color(0.2f, 0.1f, 0f, 0.75f));     // Magic

                DrawBoxBackground(root, 170f, -438f, 135f, 24f, new Color(0.06f, 0.06f, 0.06f, 0.75f)); // Curse

                DrawBoxBackground(root, 170f, -466f, 135f, 24f, new Color(0.03f, 0.13f, 0.03f, 0.75f));  // Poison

                // Draw vertical separators inside resistance boxes

                DrawVerticalLine(root, 110f, -410f, 24f);

                DrawVerticalLine(root, 265f, -410f, 24f);

                DrawVerticalLine(root, 110f, -438f, 24f);

                DrawVerticalLine(root, 265f, -438f, 24f);

                DrawVerticalLine(root, 110f, -466f, 24f);

                DrawVerticalLine(root, 265f, -466f, 24f);

            }

            // Draw interactive buttons dynamically

            DrawButton(root, 185f, -258f, 120f, 20f, "Stat Preset");

            DrawButton(root, 185f, -346f, 120f, 20f, "Stat Reset");

            // Ensure backgrounds render at the back in correct order

            for (int i = 0; i < root.childCount; i++)

            {

                var child = root.GetChild(i);

                if (child.name == "BoxBackground")

                {

                    child.SetAsFirstSibling();

                }

            }

            for (int i = 0; i < root.childCount; i++)

            {

                var child = root.GetChild(i);

                if (child.name == "CapsuleBackground")

                {

                    child.SetAsFirstSibling();

                }

            }

            // Position character info elements relative to the top-left of page_state

            PositionElement(FindChildByIDIgnoreCase(root, "text_Id"), 15f, -58f, 180f, 25f, TextAnchor.MiddleLeft);

            PositionElement(FindChildByIDIgnoreCase(root, "Text_Nation"), 205f, -60f, 100f, 20f, TextAnchor.MiddleRight);

            var txtRaceVal = FindChildByIDIgnoreCase(root, "Text_Race");

            if (txtRaceVal != null) txtRaceVal.gameObject.SetActive(false);

            // Row 1: Level (Left) & HP Point (Right)

            PositionElement(FindChildByIDIgnoreCase(root, "Text_Level"), 65f, -95f, 70f, 24f, TextAnchor.MiddleCenter);

            PositionElement(FindChildByIDIgnoreCase(root, "Text_HP"), 205f, -95f, 100f, 24f, TextAnchor.MiddleCenter);

            // Row 2: Job (Left) & MP Point (Right)

            PositionElement(FindChildByIDIgnoreCase(root, "Text_Class"), 65f, -123f, 70f, 24f, TextAnchor.MiddleCenter);

            PositionElement(FindChildByIDIgnoreCase(root, "Text_MP"), 205f, -123f, 100f, 24f, TextAnchor.MiddleCenter);

            // Row 3: Exp Points (Full Width)

            PositionElement(FindChildByIDIgnoreCase(root, "Text_Exp"), 100f, -158f, 205f, 24f, TextAnchor.MiddleCenter);

            // Row 4: War Points (Full Width)

            PositionElement(FindChildByIDIgnoreCase(root, "Text_RealmPoint"), 100f, -186f, 205f, 24f, TextAnchor.MiddleCenter);

            // Row 5: Attack (Left) & Defence (Right)

            PositionElement(FindChildByIDIgnoreCase(root, "Text_AP"), 75f, -220f, 70f, 24f, TextAnchor.MiddleCenter);

            PositionElement(FindChildByIDIgnoreCase(root, "Text_GP"), 235f, -220f, 70f, 24f, TextAnchor.MiddleCenter);

            // Stat Points Capsule Label & Value (Shortened capsule container W=120f)

            var lblStatPoint = FindChildByText(root, "Stat Point");

            if (lblStatPoint != null)

            {

                PositionElement(lblStatPoint, 15f, -258f, 90f, 20f, TextAnchor.MiddleCenter);

                var txt = lblStatPoint.GetComponent<Text>();

                if (txt != null)

                {

                    txt.color = new Color(0.95f, 0.85f, 0.35f, 1);

                    txt.fontStyle = FontStyle.Bold;

                }

            }

            PositionElement(FindChildByIDIgnoreCase(root, "Text_BonusPoint"), 105f, -258f, 30f, 20f, TextAnchor.MiddleCenter);

            // Stats Left Column (STR, DEX, INT) - centered values

            PositionElement(FindChildByIDIgnoreCase(root, "Text_Strength"), 55f, -290f, 95f, 24f, TextAnchor.MiddleCenter);

            PositionElement(FindChildByIDIgnoreCase(root, "Text_Dexterity"), 55f, -318f, 95f, 24f, TextAnchor.MiddleCenter);

            PositionElement(FindChildByIDIgnoreCase(root, "Text_Intelligence"), 55f, -346f, 95f, 24f, TextAnchor.MiddleCenter);

            // Stats Right Column (HP/Stamina, MP/MagicAttack) - centered values

            PositionElement(FindChildByIDIgnoreCase(root, "Text_Stamina"), 210f, -290f, 95f, 24f, TextAnchor.MiddleCenter);

            PositionElement(FindChildByIDIgnoreCase(root, "Text_MagicAttack"), 210f, -318f, 95f, 24f, TextAnchor.MiddleCenter);

            // Plus buttons are completely deactivated as stat distribution will happen on Stat Preset panel

            var btnStr = FindChildByIDIgnoreCase(root, "btn_strength");

            if (btnStr != null) btnStr.gameObject.SetActive(false);

            var btnDex = FindChildByIDIgnoreCase(root, "btn_Dexterity");

            if (btnDex != null) btnDex.gameObject.SetActive(false);

            var btnInt = FindChildByIDIgnoreCase(root, "btn_Intelligence");

            if (btnInt != null) btnInt.gameObject.SetActive(false);

            var btnSta = FindChildByIDIgnoreCase(root, "btn_stamina");

            if (btnSta != null) btnSta.gameObject.SetActive(false);

            var btnCha = FindChildByIDIgnoreCase(root, "btn_MagicAttack");

            if (btnCha != null) btnCha.gameObject.SetActive(false);

            // Resistances Header Capsule Label

            var lblResistance = FindChildByText(root, "Resistance");

            if (lblResistance != null)

            {

                PositionElement(lblResistance, 15f, -380f, 95f, 20f, TextAnchor.MiddleCenter);

                var txt = lblResistance.GetComponent<Text>();

                if (txt != null)

                {

                    txt.color = new Color(0.95f, 0.85f, 0.35f, 1);

                    txt.fontStyle = FontStyle.Bold;

                }

            }

            // Resistances 3x2 Grid values

            PositionElement(FindChildByIDIgnoreCase(root, "Text_RegistFire"), 110f, -410f, 40f, 24f, TextAnchor.MiddleCenter);

            PositionElement(FindChildByIDIgnoreCase(root, "Text_RegistMagic"), 265f, -410f, 40f, 24f, TextAnchor.MiddleCenter);

            PositionElement(FindChildByIDIgnoreCase(root, "Text_RegistIce"), 110f, -438f, 40f, 24f, TextAnchor.MiddleCenter);

            PositionElement(FindChildByIDIgnoreCase(root, "Text_RegistCurse"), 265f, -438f, 40f, 24f, TextAnchor.MiddleCenter);

            PositionElement(FindChildByIDIgnoreCase(root, "Text_RegistLightR"), 110f, -466f, 40f, 24f, TextAnchor.MiddleCenter);

            PositionElement(FindChildByIDIgnoreCase(root, "Text_RegistPoison"), 265f, -466f, 40f, 24f, TextAnchor.MiddleCenter);

            // Set background colors for HP/MP and elements that do not have custom box backgrounds (toned down values)

            SetFieldBackground(FindChildByIDIgnoreCase(root, "Text_Level"), new Color(0.1f, 0.1f, 0.1f, 0.8f));

            SetFieldBackground(FindChildByIDIgnoreCase(root, "Text_Class"), new Color(0.1f, 0.1f, 0.1f, 0.8f));

            SetFieldBackground(FindChildByIDIgnoreCase(root, "Text_AP"), new Color(0.1f, 0.1f, 0.1f, 0.8f));

            SetFieldBackground(FindChildByIDIgnoreCase(root, "Text_GP"), new Color(0.1f, 0.1f, 0.1f, 0.8f));

            SetFieldBackground(FindChildByIDIgnoreCase(root, "Text_HP"), new Color(0.25f, 0.04f, 0.04f, 0.75f)); // Toned down Dark Red

            SetFieldBackground(FindChildByIDIgnoreCase(root, "Text_MP"), new Color(0.05f, 0.05f, 0.18f, 0.75f)); // Toned down Dark Blue

            SetFieldBackground(FindChildByIDIgnoreCase(root, "Text_Exp"), new Color(0.1f, 0.08f, 0.05f, 0.75f));   // Toned down Dark Brown

            SetFieldBackground(FindChildByIDIgnoreCase(root, "Text_RealmPoint"), new Color(0.1f, 0.08f, 0.05f, 0.75f)); // Toned down Dark Brown

            // Deactivate legacy background images/lines

            var legacyImgNames = new string[] { "img_dex", "img_sta", "img_str", "img_int", "ui_Image_3950EC00", "img_map" };

            foreach (var imgName in legacyImgNames)

            {

                var tr = FindChildByIDIgnoreCase(root, imgName);

                if (tr != null) tr.gameObject.SetActive(false);

            }

            var allTexts = root.GetComponentsInChildren<Text>(true);

            // Deactivate legacy/unused label texts

            foreach (var txt in allTexts)

            {

                string name = txt.gameObject.name;

                // If it is one of our value fields, keep active

                if (string.Equals(name, "text_Id", System.StringComparison.OrdinalIgnoreCase) || name == "Text_Level" || name == "Text_Class" || name == "Text_Race" || name == "Text_Nation" ||

                    name.StartsWith("Text_HP") || name.StartsWith("Text_MP") || name == "Text_Exp" || name == "Text_RealmPoint" ||

                    name == "Text_AP" || name == "Text_GP" || name == "Text_BonusPoint" || name.StartsWith("Text_Strength") ||

                    name.StartsWith("Text_Stamina") || name.StartsWith("Text_Dexterity") || name.StartsWith("Text_Intelligence") ||

                    name.StartsWith("Text_MagicAttack") || name.StartsWith("Text_Regist"))

                {

                    continue;

                }

                // If it is one of our mapped labels, keep active

                string tClean = txt.text.Trim();

                if (tClean.EndsWith(":")) tClean = tClean.Substring(0, tClean.Length - 1).Trim();

                if (labelMap.ContainsKey(tClean) ||

                    labelMap.ContainsValue(tClean) ||

                    tClean == "STR" ||

                    tClean == "HP" ||

                    tClean == "DEX" ||

                    tClean == "MP" ||

                    tClean == "INT" ||

                    tClean == "Resistance" ||

                    tClean == "Stat Point" ||

                    tClean == "Stat Preset" ||

                    tClean == "Stat Reset")

                {

                    continue;

                }

                // Otherwise, deactivate legacy/unused label

                txt.gameObject.SetActive(false);

            }

            // List of labels we want to position

            foreach (Transform child in root)

            {

                var txt = child.GetComponent<Text>();

                if (txt == null) continue;

                string t = txt.text.Trim();

                if (t.EndsWith(":")) t = t.Substring(0, t.Length - 1).Trim();

                if (System.StringComparer.OrdinalIgnoreCase.Equals(t, "Level"))

                    PositionElement(child, 15f, -95f, 50f, 24f, TextAnchor.MiddleLeft);

                else if (System.StringComparer.OrdinalIgnoreCase.Equals(t, "Job"))

                    PositionElement(child, 15f, -123f, 50f, 24f, TextAnchor.MiddleLeft);

                else if (System.StringComparer.OrdinalIgnoreCase.Equals(t, "Nation"))

                    child.gameObject.SetActive(false);

                else if (System.StringComparer.OrdinalIgnoreCase.Equals(t, "Race"))

                    child.gameObject.SetActive(false);

                else if (System.StringComparer.OrdinalIgnoreCase.Equals(t, "HP Point"))

                    PositionElement(child, 145f, -95f, 60f, 24f, TextAnchor.MiddleLeft);

                else if (System.StringComparer.OrdinalIgnoreCase.Equals(t, "MP Point"))

                    PositionElement(child, 145f, -123f, 60f, 24f, TextAnchor.MiddleLeft);

                else if (System.StringComparer.OrdinalIgnoreCase.Equals(t, "Exp Points"))

                    PositionElement(child, 15f, -158f, 80f, 24f, TextAnchor.MiddleLeft);

                else if (System.StringComparer.OrdinalIgnoreCase.Equals(t, "War Points"))

                    PositionElement(child, 15f, -186f, 80f, 24f, TextAnchor.MiddleLeft);

                else if (System.StringComparer.OrdinalIgnoreCase.Equals(t, "Attack"))

                    PositionElement(child, 15f, -220f, 60f, 24f, TextAnchor.MiddleLeft);

                else if (System.StringComparer.OrdinalIgnoreCase.Equals(t, "Defence"))

                    PositionElement(child, 165f, -220f, 65f, 24f, TextAnchor.MiddleLeft);

                else if (System.StringComparer.OrdinalIgnoreCase.Equals(t, "STR"))

                    PositionElement(child, 20f, -290f, 35f, 24f, TextAnchor.MiddleLeft);

                else if (System.StringComparer.OrdinalIgnoreCase.Equals(t, "HP"))

                    PositionElement(child, 175f, -290f, 35f, 24f, TextAnchor.MiddleLeft);

                else if (System.StringComparer.OrdinalIgnoreCase.Equals(t, "DEX"))

                    PositionElement(child, 20f, -318f, 35f, 24f, TextAnchor.MiddleLeft);

                else if (System.StringComparer.OrdinalIgnoreCase.Equals(t, "MP"))

                    PositionElement(child, 175f, -318f, 35f, 24f, TextAnchor.MiddleLeft);

                else if (System.StringComparer.OrdinalIgnoreCase.Equals(t, "INT"))

                    PositionElement(child, 20f, -346f, 35f, 24f, TextAnchor.MiddleLeft);

                else if (System.StringComparer.OrdinalIgnoreCase.Equals(t, "Flame Resist"))

                    PositionElement(child, 20f, -410f, 85f, 24f, TextAnchor.MiddleLeft);

                else if (System.StringComparer.OrdinalIgnoreCase.Equals(t, "Magic Resist"))

                    PositionElement(child, 175f, -410f, 85f, 24f, TextAnchor.MiddleLeft);

                else if (System.StringComparer.OrdinalIgnoreCase.Equals(t, "Glacier Resist"))

                    PositionElement(child, 20f, -438f, 85f, 24f, TextAnchor.MiddleLeft);

                else if (System.StringComparer.OrdinalIgnoreCase.Equals(t, "Curse Resist"))

                    PositionElement(child, 175f, -438f, 85f, 24f, TextAnchor.MiddleLeft);

                else if (System.StringComparer.OrdinalIgnoreCase.Equals(t, "Lightning Resist"))

                    PositionElement(child, 20f, -466f, 85f, 24f, TextAnchor.MiddleLeft);

                else if (System.StringComparer.OrdinalIgnoreCase.Equals(t, "Poison Resist"))

                    PositionElement(child, 175f, -466f, 85f, 24f, TextAnchor.MiddleLeft);

            }

        }

        private void PositionElement(Transform element, float x, float y, float w, float h, TextAnchor alignment = TextAnchor.MiddleCenter)

        {

            if (element == null) return;

            var rt = element.GetComponent<RectTransform>();

            if (rt == null) return;

            rt.anchorMin = new Vector2(0f, 1f);

            rt.anchorMax = new Vector2(0f, 1f);

            rt.pivot = new Vector2(0f, 1f);

            rt.anchoredPosition = new Vector2(x, y);

            rt.sizeDelta = new Vector2(w, h);

            var txt = element.GetComponent<Text>();

            if (txt != null)

            {

                txt.alignment = alignment;

            }

        }

        private Transform FindChildByIDIgnoreCase(Transform root, string id)

        {

            if (root == null) return null;

            var t = root.Find(id);

            if (t != null) return t;

            Transform[] children = root.GetComponentsInChildren<Transform>(true);

            foreach (var child in children)

            {

                if (string.Equals(child.name, id, System.StringComparison.OrdinalIgnoreCase))

                {

                    return child;

                }

            }

            return null;

        }

        private void SetFieldBackground(Transform field, Color color)

        {

            if (field == null) return;

            string bgName = field.name + "_Bg";

            Transform bgTr = field.parent.Find(bgName);

            if (bgTr == null)

            {

                var go = new GameObject(bgName, typeof(RectTransform), typeof(UnityEngine.UI.Image));

                bgTr = go.transform;

                bgTr.SetParent(field.parent, false);

            }

            // Render behind field

            int fieldIndex = field.GetSiblingIndex();

            bgTr.SetSiblingIndex(fieldIndex > 0 ? fieldIndex - 1 : 0);

            var rt = bgTr.GetComponent<RectTransform>();

            var fieldRt = field.GetComponent<RectTransform>();

            if (rt != null && fieldRt != null)

            {

                rt.anchorMin = fieldRt.anchorMin;

                rt.anchorMax = fieldRt.anchorMax;

                rt.pivot = fieldRt.pivot;

                rt.anchoredPosition = fieldRt.anchoredPosition;

                rt.sizeDelta = fieldRt.sizeDelta;

            }

            var img = bgTr.GetComponent<UnityEngine.UI.Image>();

            if (img != null && fieldRt != null)

            {

                int w = (int)fieldRt.sizeDelta.x;

                int h = (int)fieldRt.sizeDelta.y;

                if (w <= 0) w = 50;

                if (h <= 0) h = 20;

                // Gold border with 50% opacity

                Color borderColor = new Color(0.45f, 0.35f, 0.15f, 0.5f);

                string key = $"field_bg_{field.name}_{w}_{h}_{color.r:F3}_{color.g:F3}_{color.b:F3}";

                img.sprite = GetSkillThemeRoundedRectSprite(key, w, h, 0, color, borderColor, 1);

                img.color = Color.white;

            }

        }

        /// <summary>UIF text ID ile Text component'ini bulup değerini set eder.</summary>

        private void SetText(Transform root, string id, string value)

        {

            var tr = EntropyOnline.Import.KOUIRenderer.FindChildByID(root, id);

            if (tr != null)

            {

                var txt = tr.GetComponent<Text>();

                if (txt != null) txt.text = value;

            }

        }

        /// <summary>Debug logging version of SetText — logs whether element/Text was found</summary>

        private void SetTextWithLog(Transform root, string id, string value)

        {

            var tr = EntropyOnline.Import.KOUIRenderer.FindChildByID(root, id);

            if (tr == null)

            {

                Debug.LogWarning($"[KOUIMGR] SetText FAILED: '{id}' not found in hierarchy");

                return;

            }

            var txt = tr.GetComponent<Text>();

            if (txt == null)

            {

                Debug.LogWarning($"[KOUIMGR] SetText FAILED: '{id}' found but no Text component");

                return;

            }

            txt.text = value;

        }

