        private void RefreshPageKnights(Transform variousRoot)

        {

            // Root referansını sakla — async refresh için

            _variousRoot = variousRoot;

            // C++ birebir: SetVisible(true) → RefreshButtonHandler(true) → MsgSend_MemberInfoAll()

            // (UIVarious.cpp:585-594)

            var km = KOKnightsManager.Instance;

            if (km != null && km.IsInClan)

