            // KOKnightsManager event'ine abone ol — sunucu cevabı gelince panelı güncelle

            if (!_knightsEventSubscribed && km != null)

            {

                km.OnKnightsInfoChanged += OnKnightsDataChanged;

                km.OnMemberListUpdated += OnKnightsMemberListUpdated;

