        private void BindKnightsButtons(Transform knightsPage)

        {

            var km = KOKnightsManager.Instance;

            // btn_clan_refresh — C++ birebir: UIVarious.cpp:664-665 → RefreshButtonHandler()

            var btnRefresh = FindKnightsButton(knightsPage, "btn_clan_refresh");

            if (btnRefresh != null)

