                btnRefresh.onClick.AddListener(() =>

                {

                    // C++ birebir: UIVarious.cpp:702-713 — 5 saniye cooldown

                    if (_fTimeLimit_Refresh < 5.0f)

                    {

                        return;

                    }

                    _fTimeLimit_Refresh = 0f;

                    _knightsPageCur = 1;

                    km?.MsgSend_MemberInfoAll();

                });

            }

            // btn_clan_up — C++ birebir: UIVarious.cpp:660-661 → PreviousPageButtonHandler()

            var btnUp = FindKnightsButton(knightsPage, "btn_clan_up");

            if (btnUp != null)

            {

                btnUp.onClick.AddListener(() =>

                {

                    // C++ birebir: UIVarious.cpp:682-689

                    _knightsPageCur--;

                    if (_knightsPageCur < 1) _knightsPageCur = 1;

                    if (_variousRoot != null) PopulateKnightsPanel(_variousRoot);

                });

            }

            // btn_clan_down — C++ birebir: UIVarious.cpp:662-663 → NextPageButtonHandler()

            var btnDown = FindKnightsButton(knightsPage, "btn_clan_down");

            if (btnDown != null)

            {

                btnDown.onClick.AddListener(() =>

                {

                    // C++ birebir: UIVarious.cpp:691-700

                    _knightsPageCur++;

                    int memberCount = km?.Members?.Count ?? 0;

                    int maxPage = memberCount / 10 + 1;

                    if (_knightsPageCur > maxPage) _knightsPageCur = maxPage;

                    if (_variousRoot != null) PopulateKnightsPanel(_variousRoot);

                });

            }

            // btn_Invite (Invite Party)
            var btnInvite = FindKnightsButton(knightsPage, "btn_Invite") ?? FindKnightsButton(knightsPage, "ui_String_690EC924");
            if (btnInvite != null)
            {
                btnInvite.onClick.RemoveAllListeners();
                btnInvite.onClick.AddListener(() =>
                {
                    string selectedName = GetSelectedMemberName(knightsPage);
                    if (!string.IsNullOrEmpty(selectedName))
                    {
                        if (PartyUI.Instance != null)
                        {
                            PartyUI.Instance.SendPartyInvite(selectedName);
                        }
                    }
                    else
                    {
                    }
                });
            }

            // btn_clan_whisper — C++ birebir: UIVarious.cpp:668-669 → WhisperButtonHandler()

            var btnWhisper = FindKnightsButton(knightsPage, "btn_clan_whisper");

            if (btnWhisper != null)

            {

                btnWhisper.onClick.AddListener(() =>

                {

                    // C++ birebir: UIVarious.cpp:742-748

                    string selectedName = GetSelectedMemberName(knightsPage);

                    if (!string.IsNullOrEmpty(selectedName))

                    {

                        km?.MsgSend_ChatSelectTarget(selectedName);

                    }

                    else

                    {

                    }

                });

            }

            // btn_clan_admit — C++ birebir: UIVarious.cpp:670-671 → AdmitButtonHandler()

            var btnAdmit = FindKnightsButton(knightsPage, "btn_clan_admit");

            if (btnAdmit != null)

            {

                btnAdmit.onClick.AddListener(() =>

                {

                    // C++ birebir: UIVarious.cpp:750-758 — 3 saniye cooldown

                    if (_fTimeLimit_Admit < 3.0f)

                    {

                        return;

                    }

                    _fTimeLimit_Admit = 0f;

                    // Target ID çözümleme — GameManager, TargetInfoUI veya KOTargetSelector'dan al
                    int targetID = -1;
                    var gm = EntropyOnline.Core.GameManager.Instance;
                    if (gm != null && gm.TargetId >= 0)
                        targetID = (int)gm.TargetId;
                    else if (EntropyOnline.UI.TargetInfoUI.Instance != null && EntropyOnline.UI.TargetInfoUI.Instance.CurrentTargetId >= 0)
                        targetID = (int)EntropyOnline.UI.TargetInfoUI.Instance.CurrentTargetId;
                    else if (EntropyOnline.World.KOTargetSelector.Instance != null && EntropyOnline.World.KOTargetSelector.Instance.CurrentTarget != null)
                        targetID = (int)EntropyOnline.World.KOTargetSelector.Instance.CurrentTarget.ServerInstanceId;

                    if (targetID >= 0)

                    {

                        km?.MsgSend_KnightsAdmit(targetID);

                        AddMsgOutput("Invitation sent to player.", D3DColorToUnity(0xffffff00));

                    }

                    else

                    {

                        Debug.LogWarning("[KOUIMGR] ⚠️ btn_clan_admit — hedef oyuncu yok!");

                        AddMsgOutput("Please select a target player first.", D3DColorToUnity(0xffffff00));

                    }

                });

            }

            // Btn_clan_Appoint — C++ birebir: UIVarious.cpp:674-675 → AppointButtonHandler()

            var btnAppoint = FindKnightsButton(knightsPage, "Btn_clan_Appoint");

            if (btnAppoint != null)

            {

                btnAppoint.onClick.AddListener(() =>

                {

                    // C++ birebir: UIVarious.cpp:774-785 — 3 saniye cooldown

                    if (_fTimeLimit_Appoint < 3.0f)

                    {

                        return;

                    }

                    _fTimeLimit_Appoint = 0f;

                    // C++ birebir: listeden seçili üye ismi

                    string selectedName = GetSelectedMemberName(knightsPage);

                    if (!string.IsNullOrEmpty(selectedName))

                    {

                        km?.MsgSend_KnightsAppointViceChief(selectedName);

                    }

                    else

                    {

                    }

                });

            }

            // Btn_clan_Remove — C++ birebir: UIVarious.cpp:672-673 → RemoveButtonHandler()
            var btnRemove = FindKnightsButton(knightsPage, "Btn_clan_Remove");
            if (btnRemove != null)
            {
                btnRemove.onClick.RemoveAllListeners();
                btnRemove.onClick.AddListener(() =>
                {
                    if (_fTimeLimit_Remove < 3.0f)
                    {
                        return;
                    }
                    _fTimeLimit_Remove = 0f;

                    byte localDuty = km?.Duty ?? 0;
                    if (localDuty == 1) // Leader
                    {
                        string selectedName = GetSelectedMemberName(knightsPage);
                        if (!string.IsNullOrEmpty(selectedName))
                        {
                            string msg = $"Are you sure you want to kick {selectedName} from the clan?";
                            KOMessageBox.Instance.ShowYesNo(msg, "Kick Clan Member", MsgBoxBehavior.BEHAVIOR_NOTHING, onYes: () =>
                            {
                                km?.MsgSend_KnightsLeave(selectedName);
                            });
                        }
                        else
                        {
                        }
                    }
                    else // Member/Assistant leaving the clan
                    {
                        string msg = "Are you sure you want to leave the clan?";
                        KOMessageBox.Instance.ShowYesNo(msg, "Leave Clan", MsgBoxBehavior.BEHAVIOR_NOTHING, onYes: () =>
                        {
                            if (KONetworkManager.Instance != null)
                            {
                                using var packet = new KOPacketWriter(WizOpcode.WIZ_KNIGHTS_PROCESS);
                                packet.WriteByte(0x03); // N3_SP_KNIGHTS_WITHDRAW
                                KONetworkManager.Instance.SendPacket(packet);
                            }
                        });
                    }
                });
            }

        }

        /// <summary>

        /// C++ birebir: CUIKnights::ChangeUIByDuty (UIVarious.cpp:1006-1026)

        /// Chief → Admit/Appoint/Remove görünür

        /// ViceChief → Admit görünür, Appoint/Remove gizli

        /// Diğer → Admit/Appoint/Remove gizli

        /// </summary>

        private void ChangeKnightsUIByDuty(Transform variousRoot)
        {
            var pages = new string[] { "page_knights", "page_Clan", "page_clan" };
            var km = KOKnightsManager.Instance;
            string clanName = km?.ClanName ?? GameManager.Instance?.ClanName ?? "";
            bool hasClan = !string.IsNullOrEmpty(clanName) && clanName != "---";
            if (!hasClan)
            {
                foreach (var pageId in pages)
                {
                    var page = FindKnightsChild(variousRoot, pageId);
                    if (page == null) continue;
                    var btnAdmit   = FindKnightsChild(page, "btn_clan_admit") ?? FindKnightsChild(page, "text_clan_admit_a");
                    var btnAppoint = FindKnightsChild(page, "Btn_clan_Appoint") ?? FindKnightsChild(page, "text_clan_appoint_a");
                    var btnRemove  = FindKnightsChild(page, "Btn_clan_Remove") ?? FindKnightsChild(page, "text_clan_remove_a");
                    if (btnAdmit != null)   btnAdmit.gameObject.SetActive(false);
                    if (btnAppoint != null) btnAppoint.gameObject.SetActive(false);
                    if (btnRemove != null)  btnRemove.gameObject.SetActive(false);
                }
                return;
            }

            byte duty = km?.Duty ?? 0;

            foreach (var pageId in pages)

            {

                var page = FindKnightsChild(variousRoot, pageId);

                if (page == null) continue;

                var btnAdmit   = FindKnightsChild(page, "btn_clan_admit") ?? FindKnightsChild(page, "text_clan_admit_a");

                var btnAppoint = FindKnightsChild(page, "Btn_clan_Appoint") ?? FindKnightsChild(page, "text_clan_appoint_a");

                var btnRemove  = FindKnightsChild(page, "Btn_clan_Remove") ?? FindKnightsChild(page, "text_clan_remove_a");

                if (duty == KOKnightsManager.KNIGHTS_DUTY_CHIEF)

                {

                    if (btnAdmit != null)   btnAdmit.gameObject.SetActive(true);

                    if (btnAppoint != null) btnAppoint.gameObject.SetActive(true);

                    if (btnRemove != null)  btnRemove.gameObject.SetActive(true);

                }

                else if (duty == KOKnightsManager.KNIGHTS_DUTY_VICECHIEF)
                {
                    if (btnAdmit != null)   btnAdmit.gameObject.SetActive(true);
                    if (btnAppoint != null) btnAppoint.gameObject.SetActive(false);
                    if (btnRemove != null)  btnRemove.gameObject.SetActive(true);
                }
                else
                {
                    if (btnAdmit != null)   btnAdmit.gameObject.SetActive(false);
                    if (btnAppoint != null) btnAppoint.gameObject.SetActive(false);
                    if (btnRemove != null)  btnRemove.gameObject.SetActive(true);
                }

            }

            UpdateHandoverButtonState();
        }

        /// <summary>

        /// C++ birebir: List_clan_ChrID listesinden seçili üye ismini döndürür.

        /// UIVarious.cpp:769-770 — m_pList_CharIDs->GetCurSel() + GetString()

        /// Şimdilik ilk üyeyi döndürür (list selection henüz implemente edilmedi).

        /// </summary>

        private string GetSelectedMemberName(Transform knightsPage)

        {

            var km = KOKnightsManager.Instance;

            if (km?.Members == null || km.Members.Count == 0) return null;

            if (_knightsSelectedIndex >= 0 && _knightsSelectedIndex < km.Members.Count)

            {

                return km.Members[_knightsSelectedIndex].Name;

            }

            return null;

        }

