            // Btn_Page_Down — C++ birebir: UIVarious.cpp:1148-1184
            var btnPageDown = EntropyOnline.Import.KOUIRenderer.FindChildButton(friendPage, "btn_page_down") ?? EntropyOnline.Import.KOUIRenderer.FindChildButton(friendPage, "Btn_Page_Down");
            if (btnPageDown != null)
