            }

            // Btn_Add — C++ birebir: UIVarious.cpp:1190-1200
            var btnAdd = EntropyOnline.Import.KOUIRenderer.FindChildButton(friendPage, "btn_add") ?? EntropyOnline.Import.KOUIRenderer.FindChildButton(friendPage, "Btn_Add");
            if (btnAdd != null)
            {
                btnAdd.onClick.RemoveAllListeners();
                btnAdd.onClick.AddListener(() =>
                {
                    // C++ birebir: pUPC = s_pOPMgr->UPCGetByID(s_pPlayer->m_iIDTarget)
                    // → MemberAdd(pUPC->IDString(), ...)
                    var gm = EntropyOnline.Core.GameManager.Instance;
                    if (gm != null && gm.TargetId >= 0 && gm.TargetIsPlayer)
                    {
                        var rp = EntropyOnline.World.EntityManager.Instance.GetRemotePlayer(gm.TargetId);
                        if (rp != null)
                        {
                            string targetName = rp.Name;
                            if (!string.IsNullOrEmpty(targetName))
                            {
                                fm?.MsgSend_FriendAdd(targetName);
                            }
                        }
                        else
                        {
                        }
                    }
                    else
                    {
                    }
                });
            }

            // Btn_Delete — C++ birebir: UIVarious.cpp:1202-1213
            var btnDelete = EntropyOnline.Import.KOUIRenderer.FindChildButton(friendPage, "btn_delete") ?? EntropyOnline.Import.KOUIRenderer.FindChildButton(friendPage, "Btn_Delete");
            if (btnDelete != null)
            {
                btnDelete.onClick.RemoveAllListeners();
                btnDelete.onClick.AddListener(() =>
                {
                    // C++ birebir: iSel = m_pList_Friends->GetCurSel() → GetString → MemberDelete
                    string selectedName = GetSelectedFriendName(friendPage);
                    if (!string.IsNullOrEmpty(selectedName))
                    {
                        fm?.MsgSend_FriendRemove(selectedName);
                    }
                    else
                    {
                    }
                });
            }

            // Btn_Whisper — C++ birebir: UIVarious.cpp:1214-1222 (aynı zamanda "Private" butonu)
            var btnWhisper = EntropyOnline.Import.KOUIRenderer.FindChildButton(friendPage, "btn_whisper") ?? EntropyOnline.Import.KOUIRenderer.FindChildButton(friendPage, "Btn_Whisper");
            if (btnWhisper != null)
            {
                btnWhisper.onClick.RemoveAllListeners();
                btnWhisper.onClick.AddListener(() =>
                {
                    string selectedName = GetSelectedFriendName(friendPage);
                    if (!string.IsNullOrEmpty(selectedName))
                    {
                        // C++ birebir: MsgSend_ChatSelectTarget(szID)
                        var km = KOKnightsManager.Instance;
                        km?.MsgSend_ChatSelectTarget(selectedName);
                    }
                    else
                    {
                    }
                });
            }

            // Btn_Party — C++ birebir: UIVarious.cpp:1224-1239
            var btnParty = EntropyOnline.Import.KOUIRenderer.FindChildButton(friendPage, "btn_party") ?? EntropyOnline.Import.KOUIRenderer.FindChildButton(friendPage, "Btn_Party");
            if (btnParty != null)
            {
                btnParty.onClick.RemoveAllListeners();
                btnParty.onClick.AddListener(() =>
                {
                    string selectedName = GetSelectedFriendName(friendPage);
                    if (!string.IsNullOrEmpty(selectedName))
                    {
                        // C++ birebir: MsgSend_PartyOrForceCreate(szID)
                        if (PartyUI.Instance != null)
                        {
                            PartyUI.Instance.SendPartyInvite(selectedName);
                        }
                    }
                    else
                    {
                    }
                });
            }

        }

        private void PopulateFriendList(Transform variousRoot)

        {

            if (variousRoot == null) return;

            var friendPage = EntropyOnline.Import.KOUIRenderer.FindChildByID(variousRoot, "page_friend");

            if (friendPage == null) return;

            var listFriends = EntropyOnline.Import.KOUIRenderer.FindChildByID(friendPage, "List_Friends");

            if (listFriends != null)

            {

                var txt = listFriends.GetComponent<UnityEngine.UI.Text>();

                if (txt != null)

                {

                    txt.text = "";

                    txt.enabled = false;

                }

            }

            // Orijinal UIF sayfalama öğelerini gizle
            var btnPageUp = EntropyOnline.Import.KOUIRenderer.FindChildByID(friendPage, "btn_page_up") ?? EntropyOnline.Import.KOUIRenderer.FindChildByID(friendPage, "Btn_Page_Up");
            if (btnPageUp != null) btnPageUp.gameObject.SetActive(false);

            var btnPageDown = EntropyOnline.Import.KOUIRenderer.FindChildByID(friendPage, "btn_page_down") ?? EntropyOnline.Import.KOUIRenderer.FindChildByID(friendPage, "Btn_Page_Down");
            if (btnPageDown != null) btnPageDown.gameObject.SetActive(false);

            var strPage = EntropyOnline.Import.KOUIRenderer.FindChildByID(friendPage, "string_page") ?? EntropyOnline.Import.KOUIRenderer.FindChildByID(friendPage, "String_Page");
            if (strPage != null) strPage.gameObject.SetActive(false);

            var textFriend = EntropyOnline.Import.KOUIRenderer.FindChildByID(friendPage, "text_friend") ?? EntropyOnline.Import.KOUIRenderer.FindChildByID(friendPage, "Text_Friend");
            if (textFriend != null) textFriend.gameObject.SetActive(false);

            var fm = KOFriendManager.Instance;
            var defaultFont = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");

            // Butonları ve durum etiketlerini stilize et
            StyleFriendButtons(friendPage);
            CreateOrUpdateFriendLegends(friendPage, defaultFont);

            // Viewport & Content ScrollRect oluştur/konumlandır
            float b0 = 14f;
            float totalTableWidth = 293f;
            CreateFriendHeaders(friendPage, b0, totalTableWidth, defaultFont);

            Transform scrollContent = null;
            var scrollViewport = friendPage.Find("FriendsListViewport");

            if (scrollViewport == null)
            {
                var vpGo = new GameObject("FriendsListViewport", typeof(RectTransform), typeof(CanvasRenderer), typeof(UnityEngine.UI.Image), typeof(UnityEngine.UI.ScrollRect), typeof(UnityEngine.UI.Mask));
                vpGo.transform.SetParent(friendPage, false);
                scrollViewport = vpGo.transform;
                
                var rtVp = vpGo.GetComponent<RectTransform>();
                rtVp.anchorMin = new Vector2(0f, 1f);
                rtVp.anchorMax = new Vector2(0f, 1f);
                rtVp.pivot = new Vector2(0f, 1f);
                // Shifted down by 10px: -118f -> -128f
                rtVp.anchoredPosition = new Vector2(b0, -128f);
                rtVp.sizeDelta = new Vector2(totalTableWidth, 230f); // Display exactly 10 rows (10 * 23f = 230f)
                
                var vpImg = vpGo.GetComponent<UnityEngine.UI.Image>();
                vpImg.sprite = GetSkillThemeRoundedRectSprite("friends_vp_mask_230", 293, 230, 0, new Color(0.04f, 0.04f, 0.04f, 0.8f), Color.clear, 0);
                vpImg.type = UnityEngine.UI.Image.Type.Simple;
                
                var contentGo = new GameObject("FriendsListContent", typeof(RectTransform));
                contentGo.transform.SetParent(scrollViewport, false);
                
                var rtContent = contentGo.GetComponent<RectTransform>();
                rtContent.anchorMin = new Vector2(0f, 1f);
                rtContent.anchorMax = new Vector2(1f, 1f);
                rtContent.pivot = new Vector2(0.5f, 1f);
                rtContent.anchoredPosition = Vector2.zero;
                rtContent.sizeDelta = new Vector2(0f, 230f);

                var scrollRect = vpGo.GetComponent<UnityEngine.UI.ScrollRect>();
                scrollRect.content = rtContent;
                scrollRect.horizontal = false;
                scrollRect.vertical = true;
                scrollRect.movementType = UnityEngine.UI.ScrollRect.MovementType.Elastic;
                scrollRect.scrollSensitivity = 25f;

                scrollContent = contentGo.transform;
            }
            else
            {
                scrollViewport.gameObject.SetActive(true);
                scrollContent = scrollViewport.Find("FriendsListContent");
                var rtVp = scrollViewport.GetComponent<RectTransform>();
                if (rtVp != null)
                {
                    // Shifted down by 10px: -118f -> -128f
                    rtVp.anchoredPosition = new Vector2(b0, -128f);
                    rtVp.sizeDelta = new Vector2(totalTableWidth, 230f);
                }
            }

            var friends = (fm != null) ? fm.GetFriends() : new System.Collections.Generic.Dictionary<string, KOFriendManager.FriendInfo>();
            int friendCount = friends.Count;
            float targetHeight = Mathf.Max(230f, friendCount * 23f);

            var rtContentContainer = scrollContent.GetComponent<RectTransform>();
            if (rtContentContainer != null)
            {
                rtContentContainer.sizeDelta = new Vector2(rtContentContainer.sizeDelta.x, targetHeight);
            }

            // Eski hücre ve tıklama alanlarını temizle
            var toDestroy = new System.Collections.Generic.List<GameObject>();
            foreach (Transform child in scrollContent)
            {
                if (child.name.StartsWith("FriendRow_") || child.name.StartsWith("RowClickTrigger_") || child.name == "FriendGridLinesOverlay")
                {
                    toDestroy.Add(child.gameObject);
                }
            }
            foreach (var go in toDestroy)
            {
                UnityEngine.Object.Destroy(go);
            }

            // Grid çizgilerini çiz (Tek sütun)
            AddFriendGridLines(scrollContent, totalTableWidth, 0f, -targetHeight, targetHeight);

            // Arkadaşlar listesini doldur
            int idx = 0;
            foreach (var kvp in friends)
            {
                var fi = kvp.Value;
                int actualIndex = idx;

                bool isSelected = (actualIndex == _friendSelectedIndex);
                
                // Status colors based on dot colors in legend
                Color textColor;
                if (fi.OnLine)
                {
                    textColor = fi.IsParty ? new Color(1f, 0.6f, 0.1f, 1f) : new Color(0f, 1f, 0f, 1f);
                }
                else
                {
                    textColor = new Color(1f, 0.1f, 0.1f, 1f);
                }
                
                string colorHex = string.Format("#{0:X2}{1:X2}{2:X2}", (byte)(textColor.r * 255f), (byte)(textColor.g * 255f), (byte)(textColor.b * 255f));

                // Tek bir FriendRow container'ı
                var rowGo = new GameObject($"FriendRow_{actualIndex}", typeof(RectTransform));
                rowGo.transform.SetParent(scrollContent, false);
                var rtRow = rowGo.GetComponent<RectTransform>();
                rtRow.anchorMin = new Vector2(0f, 1f);
                rtRow.anchorMax = new Vector2(1f, 1f);
                rtRow.pivot = new Vector2(0.5f, 1f);
                rtRow.anchoredPosition = new Vector2(0f, -actualIndex * 23f);
                rtRow.sizeDelta = new Vector2(0f, 23f);
                rtRow.localScale = Vector3.one;

                // If selected, draw a subtle gold highlight background
                if (isSelected)
                {
                    var bgGo = new GameObject("SelectedBg", typeof(RectTransform), typeof(CanvasRenderer), typeof(UnityEngine.UI.Image));
                    bgGo.transform.SetParent(rowGo.transform, false);
                    var rtBg = bgGo.GetComponent<RectTransform>();
                    rtBg.anchorMin = Vector2.zero;
                    rtBg.anchorMax = Vector2.one;
                    rtBg.pivot = new Vector2(0.5f, 0.5f);
                    rtBg.anchoredPosition = Vector2.zero;
                    rtBg.sizeDelta = Vector2.zero;
                    var bgImg = bgGo.GetComponent<UnityEngine.UI.Image>();
                    
                    int bgWidth = Mathf.RoundToInt(totalTableWidth);
                    bgImg.sprite = GetFadeGradientSprite("friend_selection_fade_bg_" + bgWidth, bgWidth, 23, Color.white, Color.clear, 0);
                    bgImg.type = UnityEngine.UI.Image.Type.Simple;
                    bgImg.color = new Color(0.6f, 0.48f, 0.22f, 0.35f); // Soft gold fade gradient
                    bgImg.raycastTarget = false;
                }

                // 1. Name Text (No dot on the left!)
                var textGo = new GameObject("NameText", typeof(RectTransform), typeof(CanvasRenderer), typeof(UnityEngine.UI.Text));
                textGo.transform.SetParent(rowGo.transform, false);
                var rtTxt = textGo.GetComponent<RectTransform>();
                rtTxt.anchorMin = new Vector2(0f, 0.5f);
                rtTxt.anchorMax = new Vector2(1f, 0.5f);
                rtTxt.pivot = new Vector2(0f, 0.5f);
                rtTxt.anchoredPosition = new Vector2(10f, 0f);
                rtTxt.sizeDelta = new Vector2(-20f, 20f);

                var cellTxt = textGo.GetComponent<UnityEngine.UI.Text>();
                cellTxt.font = defaultFont;
                if (cellTxt.font == null) cellTxt.font = Font.CreateDynamicFontFromOSFont("Arial", 11);
                cellTxt.fontSize = 11;
                cellTxt.alignment = TextAnchor.MiddleLeft;
                cellTxt.supportRichText = true;
                cellTxt.raycastTarget = false;
                cellTxt.text = $"<color={colorHex}>{fi.Name}</color>";

                // Invisible click trigger for row selection
                var clickGo = new GameObject($"RowClickTrigger_{actualIndex}", typeof(RectTransform), typeof(CanvasRenderer), typeof(UnityEngine.UI.Image), typeof(UnityEngine.UI.Button));
                clickGo.transform.SetParent(scrollContent, false);
                var rtClick = clickGo.GetComponent<RectTransform>();
                rtClick.anchorMin = new Vector2(0f, 1f);
                rtClick.anchorMax = new Vector2(1f, 1f);
                rtClick.pivot = new Vector2(0.5f, 1f);
                rtClick.anchoredPosition = new Vector2(0f, -actualIndex * 23f);
                rtClick.sizeDelta = new Vector2(0f, 23f);
                rtClick.localScale = Vector3.one;

                var clickImg = clickGo.GetComponent<UnityEngine.UI.Image>();
                clickImg.color = Color.clear;
                clickImg.raycastTarget = true;

                int indexToSelect = actualIndex;
                var clickBtn = clickGo.GetComponent<UnityEngine.UI.Button>();
                clickBtn.transition = UnityEngine.UI.Selectable.Transition.None;
                clickBtn.onClick.AddListener(() => {
                    _friendSelectedIndex = indexToSelect;
                    PopulateFriendList(variousRoot);
                });

                idx++;
            }

            // Seçim vurgusu arka planını oluştur veya konumlandır
            var selectionBgTr = scrollContent.Find("FriendRowSelectionBg");
            UnityEngine.UI.Image selectionBgImg = null;
            if (selectionBgTr == null)
            {
                var bgGo = new GameObject("FriendRowSelectionBg", typeof(RectTransform), typeof(CanvasRenderer), typeof(UnityEngine.UI.Image));
                bgGo.transform.SetParent(scrollContent, false);
                selectionBgTr = bgGo.transform;
            }
            selectionBgTr.SetSiblingIndex(1);
            selectionBgImg = selectionBgTr.GetComponent<UnityEngine.UI.Image>();
            if (selectionBgImg != null)
            {
                int bgWidth = Mathf.RoundToInt(totalTableWidth) + 20;
                selectionBgImg.sprite = GetFadeGradientSprite("friends_selection_fade_bg_" + bgWidth, bgWidth, 23, Color.white, Color.clear, 0);
                selectionBgImg.type = UnityEngine.UI.Image.Type.Simple;
                selectionBgImg.color = new Color(0.6f, 0.48f, 0.22f, 0.35f);
                selectionBgImg.raycastTarget = false;

                var bgRT = selectionBgTr.GetComponent<RectTransform>();
                bgRT.anchorMin = new Vector2(0f, 1f);
                bgRT.anchorMax = new Vector2(0f, 1f);
                bgRT.pivot = new Vector2(0f, 1f);
                
                if (_friendSelectedIndex >= 0 && _friendSelectedIndex < friends.Count)
                {
                    bgRT.gameObject.SetActive(true);
                    bgRT.anchoredPosition = new Vector2(-10f, -_friendSelectedIndex * 23f);
                    bgRT.sizeDelta = new Vector2(bgWidth, 23f);
                }
                else
                {
                    bgRT.gameObject.SetActive(false);
                }
                bgRT.localScale = Vector3.one;
            }

        }

        private void AddFriendGridLines(Transform parentContent, float totalTableWidth, float topY, float bottomY, float height)
        {
            if (parentContent == null) return;

            var gridContainer = parentContent.Find("FriendGridLinesOverlay");
            if (gridContainer != null)
            {
                Destroy(gridContainer.gameObject);
            }

            var containerGo = new GameObject("FriendGridLinesOverlay", typeof(RectTransform), typeof(UnityEngine.UI.LayoutElement));
            containerGo.transform.SetParent(parentContent, false);
            containerGo.transform.SetAsFirstSibling();

            var le = containerGo.GetComponent<UnityEngine.UI.LayoutElement>();
            if (le != null)
            {
                le.ignoreLayout = true;
            }

            var containerRT = containerGo.GetComponent<RectTransform>();
            if (containerRT != null)
            {
                containerRT.anchorMin = Vector2.zero;
                containerRT.anchorMax = Vector2.one;
                containerRT.offsetMin = Vector2.zero;
                containerRT.offsetMax = Vector2.zero;
            }

            Color lineColor = new Color(0.3f, 0.25f, 0.2f, 0.35f);

            // Sınır dikey çizgileri
            float[] xCoords = { 0f, totalTableWidth };
            for (int i = 0; i < xCoords.Length; i++)
            {
                var vLine = new GameObject($"VLine_{i}", typeof(RectTransform), typeof(UnityEngine.UI.Image));
                vLine.transform.SetParent(containerGo.transform, false);
                var rt = vLine.GetComponent<RectTransform>();
                rt.anchorMin = new Vector2(0f, 1f);
                rt.anchorMax = new Vector2(0f, 1f);
                rt.pivot = new Vector2(0.5f, 0.5f);
                
                float posX = xCoords[i];
                if (i == 0) posX += 1f;
                if (i == xCoords.Length - 1) posX -= 1f;

                rt.anchoredPosition = new Vector2(posX, (topY + bottomY) / 2f);
                rt.sizeDelta = new Vector2(1f, height);
                vLine.GetComponent<UnityEngine.UI.Image>().color = lineColor;
            }

            // Yatay çizgiler
            int rowCount = Mathf.RoundToInt(height / 23f);
            if (rowCount < 1) rowCount = 1;
            float rowHeight = height / rowCount;
            for (int i = 0; i <= rowCount; i++)
            {
                var hLine = new GameObject($"HLine_{i}", typeof(RectTransform), typeof(UnityEngine.UI.Image));
                hLine.transform.SetParent(containerGo.transform, false);
                var rt = hLine.GetComponent<RectTransform>();
                rt.anchorMin = new Vector2(0f, 1f);
                rt.anchorMax = new Vector2(0f, 1f);
                rt.pivot = new Vector2(0.5f, 0.5f);
                
                float posY = topY - i * rowHeight;
                if (i == 0) posY -= 1f;
                if (i == rowCount) posY += 1f;

                rt.anchoredPosition = new Vector2(totalTableWidth / 2f, posY);
                rt.sizeDelta = new Vector2(totalTableWidth, 1f);
                hLine.GetComponent<UnityEngine.UI.Image>().color = lineColor;
            }
        }

        private void CreateOrUpdateFriendLegends(Transform friendPage, Font defaultFont)
        {
            var legendContainer = friendPage.Find("FriendLegendContainer");
            if (legendContainer == null)
            {
                var go = new GameObject("FriendLegendContainer", typeof(RectTransform));
                go.transform.SetParent(friendPage, false);
                legendContainer = go.transform;

                var rt = go.GetComponent<RectTransform>();
                rt.anchorMin = new Vector2(0f, 1f);
                rt.anchorMax = new Vector2(0f, 1f);
                rt.pivot = new Vector2(0f, 0.5f);
                rt.anchoredPosition = new Vector2(0f, -405f);
                rt.sizeDelta = new Vector2(321f, 20f);

                // Online
                CreateLegendItem(legendContainer, "Online", "Online", new Color(0f, 1f, 0f, 1f), 32f, defaultFont);

                // In Party (Shifted 10px right: 105f -> 115f)
                CreateLegendItem(legendContainer, "InParty", "In Party", new Color(1f, 0.6f, 0.1f, 1f), 115f, defaultFont);

                // Not Connected (Shifted 10px right: 188f -> 198f)
                CreateLegendItem(legendContainer, "NotConnected", "Not Connected", new Color(1f, 0.1f, 0.1f, 1f), 198f, defaultFont);
            }
            else
            {
                legendContainer.gameObject.SetActive(true);
                var onlineTr = legendContainer.Find("Online");
                if (onlineTr != null) onlineTr.GetComponent<RectTransform>().anchoredPosition = new Vector2(32f, 0f);
                var inPartyTr = legendContainer.Find("InParty");
                if (inPartyTr != null) inPartyTr.GetComponent<RectTransform>().anchoredPosition = new Vector2(115f, 0f);
                var notConnectedTr = legendContainer.Find("NotConnected");
                if (notConnectedTr != null) notConnectedTr.GetComponent<RectTransform>().anchoredPosition = new Vector2(198f, 0f);
            }

            var btnAdd = EntropyOnline.Import.KOUIRenderer.FindChildButton(friendPage, "btn_add") ?? EntropyOnline.Import.KOUIRenderer.FindChildButton(friendPage, "Btn_Add");
            var btnDelete = EntropyOnline.Import.KOUIRenderer.FindChildButton(friendPage, "btn_delete") ?? EntropyOnline.Import.KOUIRenderer.FindChildButton(friendPage, "Btn_Delete");
            var btnWhisper = EntropyOnline.Import.KOUIRenderer.FindChildButton(friendPage, "btn_whisper") ?? EntropyOnline.Import.KOUIRenderer.FindChildButton(friendPage, "Btn_Whisper");
            var btnParty = EntropyOnline.Import.KOUIRenderer.FindChildButton(friendPage, "btn_party") ?? EntropyOnline.Import.KOUIRenderer.FindChildButton(friendPage, "Btn_Party");
            var btnRefresh = EntropyOnline.Import.KOUIRenderer.FindChildButton(friendPage, "btn_refresh") ?? EntropyOnline.Import.KOUIRenderer.FindChildButton(friendPage, "Btn_Refresh");

            // Orijinal sarı ve gri renkli etiketleri ve eski başıboş duran buton metinlerini gizle (rekürsif)
            var allTexts = friendPage.GetComponentsInChildren<UnityEngine.UI.Text>(true);
            foreach (var txt in allTexts)
            {
                if (txt == null) continue;

                // Korunacaklar:
                // 1. Yeni legend container içindekiler
                if (txt.transform == legendContainer || txt.transform.parent == legendContainer || txt.transform.IsChildOf(legendContainer))
                    continue;

                // 2. Butonların kendi içindeki metinler (bizim atadığımız büyük harfli REGISTER, DELETE vb.)
                if (btnAdd != null && txt.transform.IsChildOf(btnAdd.transform)) continue;
                if (btnDelete != null && txt.transform.IsChildOf(btnDelete.transform)) continue;
                if (btnWhisper != null && txt.transform.IsChildOf(btnWhisper.transform)) continue;
                if (btnParty != null && txt.transform.IsChildOf(btnParty.transform)) continue;
                if (btnRefresh != null && txt.transform.IsChildOf(btnRefresh.transform)) continue;

                // 3. Tablo başlığı ("Friend" veya "Name" vb. ve yeni oluşturulan grid/satır yazıları)
                string tName = txt.name.ToLower();
                string tVal = txt.text.Trim();
                if (tName.Contains("header") || tVal.Equals("friend", System.StringComparison.OrdinalIgnoreCase))
                    continue;

                // 4. Row hücrelerindeki yazılar (FriendRow_... veya benzeri satır elemanları)
                if (txt.transform.parent != null && (txt.transform.parent.name.StartsWith("FriendRow_") || txt.transform.parent.name == "FriendsListContent"))
                    continue;

                // Diğer tüm eski/bağımsız legacy metin nesnelerini gizle
                txt.gameObject.SetActive(false);
            }
        }

        private void CreateFriendHeaders(Transform friendPage, float b0, float totalTableWidth, Font defaultFont)
        {
            if (friendPage == null) return;

            // Headers background with fadeout
            var bgTr = EntropyOnline.Import.KOUIRenderer.FindChildByID(friendPage, "FriendHeadersBackground");
            UnityEngine.UI.Image bgImg = null;
            if (bgTr == null)
            {
                var bgGo = new GameObject("FriendHeadersBackground", typeof(RectTransform), typeof(CanvasRenderer), typeof(UnityEngine.UI.Image));
                bgGo.transform.SetParent(friendPage, false);
                bgTr = bgGo.transform;
            }
            bgTr.SetSiblingIndex(1);
            bgImg = bgTr.GetComponent<UnityEngine.UI.Image>();
            if (bgImg != null)
            {
                // Yatay olarak 20px kısaltıldı: totalTableWidth + 20 -> totalTableWidth
                int bgWidth = Mathf.RoundToInt(totalTableWidth);
                bgImg.sprite = GetFadeGradientSprite("friend_header_fade_bg_" + bgWidth, bgWidth, 40, Color.white, Color.clear, 0);
                bgImg.type = UnityEngine.UI.Image.Type.Simple;
                bgImg.color = new Color(0.6f, 0.48f, 0.22f, 0.35f); // Soft gold
                bgImg.raycastTarget = false;

                var bgRT = bgTr.GetComponent<RectTransform>();
                bgRT.anchorMin = new Vector2(0f, 1f);
                bgRT.anchorMax = new Vector2(0f, 1f);
                bgRT.pivot = new Vector2(0f, 0f);
                // Konum b0 - 10f -> b0 olarak güncellendi ve başlıkla birlikte 10px yukarı kaydırıldı (y = -108f)
                bgRT.anchoredPosition = new Vector2(b0, -108f); // Bottom at -108f, top at -68f (height 40)
                bgRT.sizeDelta = new Vector2(bgWidth, 40f);
                bgRT.localScale = Vector3.one;
            }

            // Header Text label: "FRIENDS", size 24, Bold, White, Centered, positioned at y = -88f (10px up from -98f)
            var headerTextTr = EntropyOnline.Import.KOUIRenderer.FindChildByID(friendPage, "Text_Header_FriendName");
            if (headerTextTr == null)
            {
                var go = new GameObject("Text_Header_FriendName", typeof(RectTransform), typeof(CanvasRenderer), typeof(UnityEngine.UI.Text));
                go.transform.SetParent(friendPage, false);
                headerTextTr = go.transform;
            }
            
            headerTextTr.gameObject.SetActive(true);
            var rt = headerTextTr.GetComponent<RectTransform>();
            rt.anchorMin = new Vector2(0f, 1f);
            rt.anchorMax = new Vector2(0f, 1f);
            rt.pivot = new Vector2(0.5f, 0.5f);
            rt.anchoredPosition = new Vector2(b0 + totalTableWidth / 2f, -88f); // Centered horizontally & vertically, shifted 10px up
            rt.sizeDelta = new Vector2(totalTableWidth, 30f);

            var txt = headerTextTr.GetComponent<UnityEngine.UI.Text>();
            txt.font = defaultFont;
            if (txt.font == null) txt.font = Font.CreateDynamicFontFromOSFont("Arial", 12);
            txt.fontSize = 24; // Same size as clan name
            txt.fontStyle = FontStyle.Bold;
