        }

        private void CreateLegendItem(Transform parent, string name, string label, Color dotColor, float dotX, Font font)
        {
            var itemGo = new GameObject(name, typeof(RectTransform));
            itemGo.transform.SetParent(parent, false);
            var rtItem = itemGo.GetComponent<RectTransform>();
            rtItem.anchorMin = new Vector2(0f, 0.5f);
            rtItem.anchorMax = new Vector2(0f, 0.5f);
            rtItem.pivot = new Vector2(0f, 0.5f);
            rtItem.anchoredPosition = new Vector2(dotX, 0f);
            rtItem.sizeDelta = new Vector2(90f, 20f);

            // Dot
            var dotGo = new GameObject("Dot", typeof(RectTransform), typeof(CanvasRenderer), typeof(UnityEngine.UI.Image));
            dotGo.transform.SetParent(itemGo.transform, false);
            var rtDot = dotGo.GetComponent<RectTransform>();
            rtDot.anchorMin = new Vector2(0f, 0.5f);
            rtDot.anchorMax = new Vector2(0f, 0.5f);
            rtDot.pivot = new Vector2(0f, 0.5f);
            rtDot.anchoredPosition = new Vector2(0f, 0f);
            rtDot.sizeDelta = new Vector2(10f, 10f);

            var dotImg = dotGo.GetComponent<UnityEngine.UI.Image>();
            dotImg.sprite = GetSkillThemeRoundedRectSprite("circle_dot_" + name, 10, 10, 5, Color.white, Color.clear, 0);
            dotImg.color = dotColor;

            // Text
            var textGo = new GameObject("Text", typeof(RectTransform), typeof(CanvasRenderer), typeof(UnityEngine.UI.Text));
            textGo.transform.SetParent(itemGo.transform, false);
            var rtText = textGo.GetComponent<RectTransform>();
            rtText.anchorMin = new Vector2(0f, 0.5f);
            rtText.anchorMax = new Vector2(1f, 0.5f);
            rtText.pivot = new Vector2(0f, 0.5f);
            rtText.anchoredPosition = new Vector2(15f, 0f);
            rtText.sizeDelta = new Vector2(-15f, 20f);

            var txt = textGo.GetComponent<UnityEngine.UI.Text>();
            txt.font = font;
            txt.text = label;
            txt.fontSize = 11;
            txt.color = Color.white;
            txt.alignment = TextAnchor.MiddleLeft;
        }

        private void StyleFriendButtons(Transform friendPage)
        {
            if (friendPage == null) return;

            var btnAdd = EntropyOnline.Import.KOUIRenderer.FindChildButton(friendPage, "btn_add") ?? EntropyOnline.Import.KOUIRenderer.FindChildButton(friendPage, "Btn_Add");
            var btnDelete = EntropyOnline.Import.KOUIRenderer.FindChildButton(friendPage, "btn_delete") ?? EntropyOnline.Import.KOUIRenderer.FindChildButton(friendPage, "Btn_Delete");
            var btnWhisper = EntropyOnline.Import.KOUIRenderer.FindChildButton(friendPage, "btn_whisper") ?? EntropyOnline.Import.KOUIRenderer.FindChildButton(friendPage, "Btn_Whisper");
            var btnParty = EntropyOnline.Import.KOUIRenderer.FindChildButton(friendPage, "btn_party") ?? EntropyOnline.Import.KOUIRenderer.FindChildButton(friendPage, "Btn_Party");
            var btnRefresh = EntropyOnline.Import.KOUIRenderer.FindChildButton(friendPage, "btn_refresh") ?? EntropyOnline.Import.KOUIRenderer.FindChildButton(friendPage, "Btn_Refresh");

            var buttons = new UnityEngine.UI.Button[] { btnAdd, btnDelete, btnWhisper, btnParty, btnRefresh };
            var labels = new string[] { "REGISTER", "DELETE", "PRIVATE", "PARTY", "REFRESH" };

            float[] posX = new float[] { 120.5f, 200.5f, 80.5f, 160.5f, 240.5f };
            float[] posY = new float[] { -438f, -438f, -474f, -474f, -474f };

            float btnWidth = 70f;
            float btnHeight = 25f;

            var defaultFont = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");

            for (int i = 0; i < buttons.Length; i++)
            {
                var btn = buttons[i];
                if (btn == null) continue;

                btn.gameObject.SetActive(true);

                var rt = btn.GetComponent<RectTransform>();
                if (rt != null)
                {
                    rt.anchorMin = new Vector2(0f, 1f);
                    rt.anchorMax = new Vector2(0f, 1f);
                    rt.pivot = new Vector2(0.5f, 1f);
                    rt.anchoredPosition = new Vector2(posX[i], posY[i]);
                    rt.sizeDelta = new Vector2(btnWidth, btnHeight);
                    rt.localScale = Vector3.one;
                }

                var raw = btn.GetComponent<UnityEngine.UI.RawImage>();
                if (raw != null) UnityEngine.Object.DestroyImmediate(raw);

                var img = btn.gameObject.GetComponent<UnityEngine.UI.Image>() ?? btn.gameObject.AddComponent<UnityEngine.UI.Image>();
                img.type = UnityEngine.UI.Image.Type.Simple;
                img.color = Color.white;

                Color topCol = Color.black;
                Color botCol = Color.black;
                Color borderCol = Color.black;
                string spriteKey = "";

                if (i == 1) // DELETE -> Red
                {
                    spriteKey = "friends_btn_red";
                    topCol = new Color(0.45f, 0.05f, 0.08f, 0.95f);
                    botCol = new Color(0.45f, 0.05f, 0.08f, 0.95f);
                    borderCol = new Color(0.75f, 0.15f, 0.15f, 0.95f);
                }
                else // REGISTER, PRIVATE, PARTY, REFRESH -> Green
                {
                    spriteKey = "friends_btn_green";
                    topCol = new Color(0.12f, 0.28f, 0.12f, 0.95f);
                    botCol = new Color(0.12f, 0.28f, 0.12f, 0.95f);
                    borderCol = new Color(0.25f, 0.55f, 0.25f, 0.95f);
                }

                int wInt = Mathf.RoundToInt(btnWidth);
                int hInt = Mathf.RoundToInt(btnHeight);
                img.sprite = GetSkillThemePanelBgSprite(spriteKey + "_" + wInt + "_" + hInt, wInt, hInt, 0, topCol, botCol, borderCol, 1);

                btn.transition = UnityEngine.UI.Selectable.Transition.ColorTint;
                btn.targetGraphic = img;

                var cb = btn.colors;
                cb.normalColor = Color.white;
                cb.highlightedColor = new Color(0.9f, 0.9f, 0.9f, 1f);
                cb.pressedColor = new Color(0.7f, 0.7f, 0.7f, 1f);
                cb.selectedColor = Color.white;
                btn.colors = cb;

                var txt = btn.GetComponentInChildren<UnityEngine.UI.Text>(true);
                if (txt == null)
                {
                    var txtObj = new GameObject("Text", typeof(RectTransform), typeof(UnityEngine.UI.Text));
                    txtObj.transform.SetParent(btn.transform, false);
                    txt = txtObj.GetComponent<UnityEngine.UI.Text>();
                }

                txt.gameObject.SetActive(true);

                var txtRT = txt.rectTransform;
                if (txtRT != null)
                {
                    txtRT.anchorMin = Vector2.zero;
                    txtRT.anchorMax = Vector2.one;
                    txtRT.sizeDelta = Vector2.zero;
                    txtRT.anchoredPosition = Vector2.zero;
                    txtRT.pivot = new Vector2(0.5f, 0.5f);
                    txtRT.localScale = Vector3.one;
                }

                txt.text = labels[i];
                if (defaultFont != null) txt.font = defaultFont;
                txt.fontSize = 10;
                txt.color = Color.white;
                txt.alignment = TextAnchor.MiddleCenter;
                txt.horizontalOverflow = HorizontalWrapMode.Wrap;
                txt.verticalOverflow = VerticalWrapMode.Overflow;
            }
        }

        private static Transform FindKnightsChild(Transform parent, string childName)

        {

            if (parent == null || string.IsNullOrEmpty(childName)) return null;

            if (parent.name.Equals(childName, System.StringComparison.OrdinalIgnoreCase)) return parent;

            foreach (Transform child in parent)

            {

                var found = FindKnightsChild(child, childName);

                if (found != null) return found;

            }

            return null;

        }

        private static UnityEngine.UI.Button FindKnightsButton(Transform parent, string buttonName)

        {

            var t = FindKnightsChild(parent, buttonName);

            return t != null ? t.GetComponent<UnityEngine.UI.Button>() : null;

        }

        private static float GetRTLeft(RectTransform rt)

        {

            if (rt == null) return 0f;

            return rt.anchoredPosition.x - rt.pivot.x * rt.sizeDelta.x;

        }

        private static float GetRTRight(RectTransform rt)

        {

            if (rt == null) return 0f;

            return rt.anchoredPosition.x + (1f - rt.pivot.x) * rt.sizeDelta.x;

        }

        private static void SetRTEdges(RectTransform rt, float left, float right)

        {

            if (rt == null) return;

            float width = right - left;

            float posX = left + rt.pivot.x * width;

            rt.anchoredPosition = new Vector2(posX, rt.anchoredPosition.y);

            rt.sizeDelta = new Vector2(width, rt.sizeDelta.y);

        }

        private static float GetLocalLeft(RectTransform rt)

        {

            if (rt == null) return 0f;

            return rt.localPosition.x + rt.rect.xMin;

        }

        private static float GetLocalRight(RectTransform rt)

        {

            if (rt == null) return 0f;

            return rt.localPosition.x + rt.rect.xMax;

        }

        private static void SetLocalEdges(RectTransform rt, float left, float right)

        {

            if (rt == null) return;

            float width = right - left;

            rt.sizeDelta = new Vector2(width, rt.sizeDelta.y);

            float localX = left + rt.pivot.x * width;

            rt.localPosition = new Vector3(localX, rt.localPosition.y, rt.localPosition.z);

        }

        /// <summary>

        /// Open-KO CUIKnights panel içeriğini doldurur.

        /// </summary>

        /// <summary>

        /// C++ birebir: List_Friends'den seçili arkadaş ismini döndürür.

        /// UIVarious.cpp:1206-1208 — m_pList_Friends->GetCurSel() + GetString()

        /// </summary>

        private string GetSelectedFriendName(Transform friendPage)

        {

            var fm = KOFriendManager.Instance;

            if (fm == null || fm.Count == 0) return null;

            var friends = fm.GetFriends();

            if (_friendSelectedIndex >= 0 && _friendSelectedIndex < friends.Count)

            {

                int idx = 0;

                foreach (var kvp in friends)

                {

                    if (idx == _friendSelectedIndex) return kvp.Value.Name;

                    idx++;

                }

            }

            return null;

        }

        private Sprite CreateGreenHexagonButtonSprite(int w, int h)
        {
            Texture2D tex = new Texture2D(w, h, TextureFormat.RGBA32, false);
            tex.filterMode = FilterMode.Bilinear;
            tex.wrapMode = TextureWrapMode.Clamp;

            Color centerColor = new Color(0.08f, 0.45f, 0.15f, 0.95f);      // forest green
            Color edgeColor = new Color(0.03f, 0.22f, 0.08f, 0.95f);        // deep dark green
            Color horizontalColor = new Color(0.18f, 0.55f, 0.22f, 0.95f);  // bright green metal edge
            Color brightHighlightColor = new Color(0.45f, 0.85f, 0.5f, 0.95f); // lime green inner highlight line

            float cy = h / 2f;
            float indent = h * 0.4f; 
            float cosTheta = 0.78f; 

            float resScale = h / 36f;
            float borderOuter = 1.5f * resScale;
            float borderInner = 3.0f * resScale;
            float shadowGap = 4.0f * resScale;

            for (int y = 0; y < h; y++)
            {
                for (int x = 0; x < w; x++)
                {
                    float leftBound = Mathf.Abs(y - cy) * (indent / cy);
                    float rightBound = w - leftBound;

                    float distToLeft = (x - leftBound) * cosTheta;
                    float distToRight = (rightBound - x) * cosTheta;
                    float distToTop = (h - 1) - y;
                    float distToBottom = y;
                    float minDist = Mathf.Min(Mathf.Min(distToLeft, distToRight), Mathf.Min(distToTop, distToBottom));

                    if (minDist < 0f)
                    {
                        float edgeFade = Mathf.Clamp01(1f + minDist);
                        if (edgeFade > 0.01f)
                        {
                            Color edgeC = horizontalColor;
                            edgeC.a *= edgeFade;
                            tex.SetPixel(x, y, edgeC);
                        }
                        else
                        {
                            tex.SetPixel(x, y, Color.clear);
                        }
                    }
                    else if (minDist < borderOuter)
                    {
                        tex.SetPixel(x, y, horizontalColor);
                    }
                    else if (minDist < borderInner)
                    {
                        tex.SetPixel(x, y, brightHighlightColor);
                    }
                    else if (minDist < shadowGap)
                    {
                        tex.SetPixel(x, y, new Color(0.01f, 0.12f, 0.03f, 0.95f));
                    }
                    else
                    {
                        float fade = Mathf.Abs(y - cy) / cy;
                        Color fillColor = Color.Lerp(centerColor, edgeColor, fade);

                        float hx = w * 0.35f;
                        float hy = h * 0.65f;
                        float hdx = (x - hx) * ((float)h / w);
                        float hdy = y - hy;
                        float distToHighlight = Mathf.Sqrt(hdx * hdx + hdy * hdy);
                        float highlightRadius = h * 0.35f;

                        if (distToHighlight < highlightRadius)
                        {
                            float factor = 1f - (distToHighlight / highlightRadius);
                            factor = factor * factor * (3f - 2f * factor);
                            float gloss = factor * 0.06f; 
                            fillColor.r = Mathf.Clamp01(fillColor.r + gloss * 0.5f);
                            fillColor.g = Mathf.Clamp01(fillColor.g + gloss * 0.8f);
                            fillColor.b = Mathf.Clamp01(fillColor.b + gloss);
                            fillColor.a = Mathf.Clamp01(fillColor.a + gloss * 0.5f);
                        }

                        tex.SetPixel(x, y, fillColor);
                    }
                }
            }
            tex.Apply();
            return Sprite.Create(tex, new Rect(0f, 0f, w, h), new Vector2(0.5f, 0.5f));
        }

        /// <summary>
        /// Open-KO CUIKnights panel içeriğini doldurur.
        /// </summary>
        private void PopulateKnightsPanel(Transform variousRoot)
        {
            var knightsPage = FindKnightsChild(variousRoot, "page_knights") ?? variousRoot;
            // Orta kısımdaki çakışan butonları oyundan tamamen silip yok ediyoruz (Kökten silme)
            var middleBtns = new string[] { 
                "btn_refresh", "btn_knights", "btn_clan_Invite", 
                "btn_pageup", "btn_pagedown", "btn_page_up", "btn_page_down" 
            };
            foreach (var btnName in middleBtns)
            {
                var trBtn = FindKnightsChild(knightsPage, btnName);
                if (trBtn != null)
                {
                    Destroy(trBtn.gameObject);
                }
            }
            if (knightsPage == null)
            {
                Debug.LogWarning("[KOUIMGR] PopulateKnightsPanel: page_knights not found");
                return;
            }

            float b0 = 14f;
            float rightLimit = 321f - b0;
            float totalTableWidth = rightLimit - b0;
            Transform scrollContent = null;

            var km = KOKnightsManager.Instance;
            string clanName = km?.ClanName ?? GameManager.Instance?.ClanName ?? "";
            byte duty = km?.Duty ?? 0;
            byte grade = km?.Grade ?? 0;

            bool hasClan = !string.IsNullOrEmpty(clanName) && clanName != "---";
            
            // Donated butonunu da gizle/göster
            var trDonated = FindKnightsChild(knightsPage, "btn_clan_donated");
            if (trDonated != null) trDonated.gameObject.SetActive(hasClan);

            var noClanTr = FindKnightsChild(knightsPage, "NoClanContainer");
            if (!hasClan)
            {
                // Normal UI öğelerini gizle
                var trClansNameNoClan = FindKnightsChild(knightsPage, "Text_clansName");
                if (trClansNameNoClan != null) trClansNameNoClan.gameObject.SetActive(false);

                var trDuty = FindKnightsChild(knightsPage, "Text_clan_Duty");
                if (trDuty != null) trDuty.gameObject.SetActive(false);

                var trMemberCount = FindKnightsChild(knightsPage, "Text_clan_MemberCount");
                if (trMemberCount != null) trMemberCount.gameObject.SetActive(false);

                var logoBoxTr = FindKnightsChild(knightsPage, "ClanLogoBox");
                if (logoBoxTr != null) logoBoxTr.gameObject.SetActive(false);

                var fadeBgTr = FindKnightsChild(knightsPage, "ClanTextFadeBg");
                if (fadeBgTr != null) fadeBgTr.gameObject.SetActive(false);

                var scrollViewport = FindKnightsChild(knightsPage, "KnightsListViewport");
                if (scrollViewport != null) scrollViewport.gameObject.SetActive(false);

                var headerBgTr = FindKnightsChild(knightsPage, "ClanHeadersBackground");
                if (headerBgTr != null) headerBgTr.gameObject.SetActive(false);

                // Grid başlık nesnelerini de gizleyelim (Text_Header_ ön ekiyle)
                var headersToHide = new string[] { "Text_Header_Rank", "Text_Header_Name", "Text_Header_Level", "Text_Header_Job" };
                foreach (var hName in headersToHide)
                {
                    var hTr = FindKnightsChild(knightsPage, hName);
                    if (hTr != null) hTr.gameObject.SetActive(false);
                }

                // Grid çizgileri, sütunlar ve tıklama alanlarını gizle
                var gridItemsToHide = new string[] { 
                    "ClanGridLinesOverlay", "List_clan_Grade", "List_clan_ChrID", "List_clan_Level", "List_clan_Job"
                };
                foreach (var itemName in gridItemsToHide)
                {
                    var itemTr = FindKnightsChild(knightsPage, itemName);
                    if (itemTr != null) itemTr.gameObject.SetActive(false);
                }

                for (int r = 0; r < 50; r++)
                {
                    var clickTr = FindKnightsChild(knightsPage, $"RowClickTrigger_{r}");
                    if (clickTr != null) clickTr.gameObject.SetActive(false);
