                    rtLinkTxt.anchorMax = Vector2.one;
                    rtLinkTxt.offsetMin = Vector2.zero;
                    rtLinkTxt.offsetMax = Vector2.zero;

                    var linkTxt = linkTextGo.GetComponent<UnityEngine.UI.Text>();
                    linkTxt.font = defaultFontNoClan;
                    linkTxt.text = "Click Here for All the Details.";
                    linkTxt.fontSize = 11;
                    linkTxt.fontStyle = FontStyle.Bold;
                    linkTxt.color = new Color(0.9f, 0.7f, 0.2f);
                    linkTxt.alignment = TextAnchor.MiddleLeft;

                    var linkBtn = infoLinkGo.GetComponent<UnityEngine.UI.Button>();
                    linkBtn.targetGraphic = linkTxt;
                    linkBtn.onClick.AddListener(() =>
                    {
                        AddMsgOutput("To create a clan, you need to be level 35 or higher and have 10,000,000 coins.", D3DColorToUnity(0xffffff00));
                        AddMsgOutput("Talk to the Clan Merchant in Moradon Castle for further promotions.", D3DColorToUnity(0xffffff00));
                    });
                }
                noClanTr.gameObject.SetActive(true);

                // StyleKnightsButtons çağrısı da butonları gizleyecek
                StyleKnightsButtons(knightsPage);
                return;
            }
            else
            {
                // Normal UI öğelerini geri göster
                var trClansNameRestored = FindKnightsChild(knightsPage, "Text_clansName");
                if (trClansNameRestored != null) trClansNameRestored.gameObject.SetActive(true);

                var trDutyRestored = FindKnightsChild(knightsPage, "Text_clan_Duty");
                if (trDutyRestored != null) trDutyRestored.gameObject.SetActive(true);

                var trMemberCountRestored = FindKnightsChild(knightsPage, "Text_clan_MemberCount");
                if (trMemberCountRestored != null) trMemberCountRestored.gameObject.SetActive(true);

                var logoBoxTrRestored = FindKnightsChild(knightsPage, "ClanLogoBox");
                if (logoBoxTrRestored != null) logoBoxTrRestored.gameObject.SetActive(true);

                var fadeBgTrRestored = FindKnightsChild(knightsPage, "ClanTextFadeBg");
                if (fadeBgTrRestored != null) fadeBgTrRestored.gameObject.SetActive(true);

                var scrollViewportRestored = FindKnightsChild(knightsPage, "KnightsListViewport");
                if (scrollViewportRestored != null) scrollViewportRestored.gameObject.SetActive(true);

                var headerBgTrRestored = FindKnightsChild(knightsPage, "ClanHeadersBackground");
                if (headerBgTrRestored != null) headerBgTrRestored.gameObject.SetActive(true);

                // Grid başlık nesnelerini geri göster
                var headersToShow = new string[] { "Text_Header_Rank", "Text_Header_Name", "Text_Header_Level", "Text_Header_Job" };
                foreach (var hName in headersToShow)
                {
                    var hTr = FindKnightsChild(knightsPage, hName);
                    if (hTr != null) hTr.gameObject.SetActive(true);
                }

                // Grid çizgileri ve listeleri geri göster
                var gridItemsToShow = new string[] { 
                    "ClanGridLinesOverlay", "List_clan_Grade", "List_clan_ChrID", "List_clan_Level", "List_clan_Job"
                };
                foreach (var itemName in gridItemsToShow)
                {
                    var itemTr = FindKnightsChild(knightsPage, itemName);
                    if (itemTr != null) itemTr.gameObject.SetActive(true);
                }

                for (int r = 0; r < 50; r++)
                {
                    var clickTr = FindKnightsChild(knightsPage, $"RowClickTrigger_{r}");
                    if (clickTr != null) clickTr.gameObject.SetActive(true);
                    else break;
                }

                if (noClanTr != null) noClanTr.gameObject.SetActive(false);
            }

            SetTextWithLog(knightsPage, "Text_clansName",
                string.IsNullOrEmpty(clanName) ? "---" : clanName);

            string gradeText = $"Grade: {(grade > 0 ? grade : 5)}";
            SetTextWithLog(knightsPage, "Text_clan_Duty", gradeText);
            // Clan adı ve derece (Duty) metinlerini dikey ortada, sola dayalı olarak baş harflerinden hizala
            var trClansName = FindKnightsChild(knightsPage, "Text_clansName");
            if (trClansName != null)
            {
                var rtName = trClansName.GetComponent<RectTransform>();
                if (rtName != null)
                {
                    rtName.anchorMin = new Vector2(0f, 1f);
                    rtName.anchorMax = new Vector2(0f, 1f);
                    rtName.pivot = new Vector2(0f, 0.5f);
                    rtName.anchoredPosition = new Vector2(94f, -75f); // Sola hizalandı, 5px aşağı kaydırıldı ve 10px yukarıda kalacak şekilde ayarlandı

                    // Kare logo kutusu oluştur veya konumlandır (HP/MP barının solundaki yuvarlak stilinde) - 1.5 Kat Büyütüldü (68x68) - En soldaki dikey çizgiyle (b0) hizalandı
                    var logoBoxTr = FindKnightsChild(knightsPage, "ClanLogoBox");
                    UnityEngine.UI.Image logoBoxImg = null;
                    if (logoBoxTr == null)
                    {
                        var go = new GameObject("ClanLogoBox", typeof(RectTransform), typeof(CanvasRenderer), typeof(UnityEngine.UI.Image));
                        go.transform.SetParent(knightsPage, false);
                        logoBoxTr = go.transform;
                    }
                    logoBoxTr.SetSiblingIndex(2); // Arkadaki BoxBackground (0) ve ClanHeadersBackground'un (1) önünde, yazıların arkasında
                    logoBoxImg = logoBoxTr.GetComponent<UnityEngine.UI.Image>();
                    if (logoBoxImg != null)
                    {
                        Color boxFill = new Color(0.08f, 0.08f, 0.08f, 0.95f); // Karakter avatar çemberiyle aynı dolgu
                        Color boxBorder = new Color(0.6f, 0.48f, 0.22f, 0.9f); // Karakter avatar çemberiyle aynı gold sınır
                        logoBoxImg.sprite = GetSkillThemeRoundedRectSprite("clan_logo_box_r10", 68, 68, 10, boxFill, boxBorder, 2);
                        logoBoxImg.type = UnityEngine.UI.Image.Type.Simple;
                        logoBoxImg.color = Color.white;
                        logoBoxImg.raycastTarget = false;

                        var rtBox = logoBoxTr.GetComponent<RectTransform>();
                        rtBox.anchorMin = new Vector2(0f, 1f);
                        rtBox.anchorMax = new Vector2(0f, 1f);
                        rtBox.pivot = new Vector2(0f, 0.5f); // Sola dayalı, dikeyde ortalı
                        rtBox.anchoredPosition = new Vector2(b0, -85f); // b0 dikey çizgisiyle hizalandı
                        rtBox.sizeDelta = new Vector2(68f, 68f);
                        rtBox.localScale = Vector3.one;
                    }

                    // Tek bir sağa sönümlemeli (one-sided fade-out) arka plan bandı ekle (Klan adı ve Derece arkasına)
                    var textBgTr = FindKnightsChild(knightsPage, "ClanTextFadeBg");
                    UnityEngine.UI.Image textBgImg = null;
                    if (textBgTr == null)
                    {
                        var go = new GameObject("ClanTextFadeBg", typeof(RectTransform), typeof(CanvasRenderer), typeof(UnityEngine.UI.Image));
                        go.transform.SetParent(knightsPage, false);
                        textBgTr = go.transform;
                    }
                    textBgTr.SetSiblingIndex(1); // Yazıların arkasında
                    textBgImg = textBgTr.GetComponent<UnityEngine.UI.Image>();
                    if (textBgImg != null)
                    {
                        float bgWidth = rightLimit - 80f; // Sağ sınıra kadar uzanır
                        int wInt = Mathf.RoundToInt(bgWidth);
                        Color fillCol = new Color(0.6f, 0.48f, 0.22f, 0.35f); // Soft gold dolgu
                        Color borderCol = new Color(0.6f, 0.48f, 0.22f, 0.5f); // İnce gold üst-alt çizgiler
                        textBgImg.sprite = GetOneSidedFadeGradientSprite("clan_text_fade_bg_" + wInt, wInt, 50, fillCol, borderCol, 1);
                        textBgImg.type = UnityEngine.UI.Image.Type.Simple;
                        textBgImg.color = Color.white;
                        textBgImg.raycastTarget = false;

                        var rtTextBg = textBgTr.GetComponent<RectTransform>();
                        rtTextBg.anchorMin = new Vector2(0f, 1f);
                        rtTextBg.anchorMax = new Vector2(0f, 1f);
                        rtTextBg.pivot = new Vector2(0f, 0.5f); // Sol-orta pivot
                        rtTextBg.anchoredPosition = new Vector2(80f, -85f); // Simgenin 2px arkasından başlar (14 + 68 - 2 = 80f)
                        rtTextBg.sizeDelta = new Vector2(bgWidth, 50f); // 50px yükseklik (dikeyde ortalı)
                        rtTextBg.localScale = Vector3.one;
                    }

                    // Klan sembolü nesnesini (img_symbol veya img_knight) bu kutunun içine yerleştir
                    var trSymbol = FindKnightsChild(knightsPage, "img_symbol") ?? FindKnightsChild(knightsPage, "img_knight");
                    if (trSymbol != null)
                    {
                        trSymbol.SetParent(logoBoxTr, false);
                        var rtSym = trSymbol.GetComponent<RectTransform>();
                        if (rtSym != null)
                        {
                            rtSym.anchorMin = Vector2.zero;
                            rtSym.anchorMax = Vector2.one;
                            rtSym.pivot = new Vector2(0.5f, 0.5f);
                            rtSym.anchoredPosition = Vector2.zero;
                            rtSym.sizeDelta = new Vector2(-4f, -4f); // Kenarlardan 2px içeride kalacak şekilde
                            rtSym.localScale = Vector3.one;
                        }
                    }

                    var txtName = trClansName.GetComponent<UnityEngine.UI.Text>();
                    if (txtName != null)
                    {
                        txtName.fontSize = 24;
                        txtName.alignment = TextAnchor.MiddleLeft;
                        txtName.fontStyle = FontStyle.Bold;
                    }
                }
            }

            var trClanDuty = FindKnightsChild(knightsPage, "Text_clan_Duty");
            if (trClanDuty != null)
            {
                var rtDuty = trClanDuty.GetComponent<RectTransform>();
                if (rtDuty != null)
                {
                    rtDuty.anchorMin = new Vector2(0f, 1f);
                    rtDuty.anchorMax = new Vector2(0f, 1f);
                    rtDuty.pivot = new Vector2(0f, 0.5f);
                    rtDuty.anchoredPosition = new Vector2(94f, -100f); // Sola hizalandı, dikeyde ortalandı ve 15px yukarı taşındı

                    var txtDuty = trClanDuty.GetComponent<UnityEngine.UI.Text>();
                    if (txtDuty != null)
                    {
                        txtDuty.fontSize = 11;
                        txtDuty.alignment = TextAnchor.MiddleLeft;
                    }
                }
            }

            int onlineCount = km?.OnlineCount ?? 0;
            int totalCount = km?.MemberCount ?? 0;

            var realMembers = km?.Members;
            var members = new List<ClanMemberEntry>();
            if (realMembers != null)
            {
                members.AddRange(realMembers);
            }



            var listGrade = FindKnightsChild(knightsPage, "List_clan_Grade");
            var listName  = FindKnightsChild(knightsPage, "List_clan_ChrID");
            var listLevel = FindKnightsChild(knightsPage, "List_clan_Level");
            var listJob   = FindKnightsChild(knightsPage, "List_clan_Job");

            float b1 = 0f, b2 = 0f, b3 = 0f, b4 = 0f;
            
            float topY = 0f, bottomY = 0f, height = 0f;

            if (listGrade != null && listName != null && listLevel != null && listJob != null)
            {
                var rtGrade = listGrade.GetComponent<RectTransform>();
                var rtName = listName.GetComponent<RectTransform>();
                var rtLevel = listLevel.GetComponent<RectTransform>();
                var rtJob = listJob.GetComponent<RectTransform>();

                if (rtGrade != null && rtName != null && rtLevel != null && rtJob != null)
                {
                    b0 = 14f;
                    float pageWidth = 321f;
                    rightLimit = pageWidth - b0;
                    totalTableWidth = rightLimit - b0;

                    b1 = b0 + (75f / 318f) * totalTableWidth;
                    b2 = b0 + (192f / 318f) * totalTableWidth;
                    b3 = b0 + (255f / 318f) * totalTableWidth;
                    b4 = rightLimit;

                    var scrollViewport = FindKnightsChild(knightsPage, "KnightsListViewport");
                    
                    if (scrollViewport == null)
                    {
                        var vpGo = new GameObject("KnightsListViewport", typeof(RectTransform), typeof(UnityEngine.UI.RectMask2D), typeof(UnityEngine.UI.ScrollRect));
                        vpGo.transform.SetParent(knightsPage, false);

                        var rtVp = vpGo.GetComponent<RectTransform>();
                        rtVp.anchorMin = new Vector2(0f, 1f);
                        rtVp.anchorMax = new Vector2(0f, 1f);
                        rtVp.pivot = new Vector2(0f, 1f);
                        rtVp.anchoredPosition = new Vector2(b0, -160f);
                        rtVp.sizeDelta = new Vector2(totalTableWidth, 230f);

                        var contentGo = new GameObject("KnightsListContent", typeof(RectTransform));
                        contentGo.transform.SetParent(vpGo.transform, false);

                        var rtContent = contentGo.GetComponent<RectTransform>();
                        rtContent.anchorMin = new Vector2(0f, 1f);
                        rtContent.anchorMax = new Vector2(1f, 1f);
                        rtContent.pivot = new Vector2(0.5f, 1f);
                        rtContent.anchoredPosition = Vector2.zero;
                        rtContent.sizeDelta = new Vector2(0f, 230f);

                        var scrollRect = vpGo.GetComponent<UnityEngine.UI.ScrollRect>();
                        scrollRect.content = rtContent;
                        scrollRect.horizontal = false;
                        scrollRect.vertical = true;
                        scrollRect.movementType = UnityEngine.UI.ScrollRect.MovementType.Elastic;
                        scrollRect.scrollSensitivity = 25f;

                        scrollContent = contentGo.transform;

                        listGrade.SetParent(scrollContent, false);
                        listName.SetParent(scrollContent, false);
                        listLevel.SetParent(scrollContent, false);
                        listJob.SetParent(scrollContent, false);
                    }
                    else
                    {
                        scrollContent = scrollViewport.Find("KnightsListContent");
                        var rtVp = scrollViewport.GetComponent<RectTransform>();
                        if (rtVp != null)
                        {
                            rtVp.anchoredPosition = new Vector2(b0, -160f);
                            rtVp.sizeDelta = new Vector2(totalTableWidth, 230f);
                        }
                    }

                    int memberCount = members != null ? members.Count : 0;
                    float targetHeight = Mathf.Max(230f, memberCount * 23f);

                    var rtContentContainer = scrollContent.GetComponent<RectTransform>();
                    if (rtContentContainer != null)
                    {
                        rtContentContainer.sizeDelta = new Vector2(rtContentContainer.sizeDelta.x, targetHeight);
                    }

                    SetRTEdges(rtGrade, 0f, b1 - b0);
                    SetRTEdges(rtName, b1 - b0, b2 - b0);
                    SetRTEdges(rtLevel, b2 - b0, b3 - b0);
                    SetRTEdges(rtJob, b3 - b0, b4 - b0);

                    rtGrade.anchoredPosition = new Vector2(rtGrade.anchoredPosition.x, 0f);
                    rtName.anchoredPosition = new Vector2(rtName.anchoredPosition.x, 0f);
                    rtLevel.anchoredPosition = new Vector2(rtLevel.anchoredPosition.x, 0f);
                    rtJob.anchoredPosition = new Vector2(rtJob.anchoredPosition.x, 0f);

                    rtGrade.sizeDelta = new Vector2(rtGrade.sizeDelta.x, targetHeight);
                    rtName.sizeDelta = new Vector2(rtName.sizeDelta.x, targetHeight);
                    rtLevel.sizeDelta = new Vector2(rtLevel.sizeDelta.x, targetHeight);
                    rtJob.sizeDelta = new Vector2(rtJob.sizeDelta.x, targetHeight);

                    topY = 0f;
                    bottomY = -targetHeight;
                    height = targetHeight;

                    AddClanGridLines(scrollContent, knightsPage, 0f, b1 - b0, b2 - b0, b3 - b0, b4 - b0, topY, bottomY, height);
                }
            }

            float rowHeight = 23f; // Her satır sabit 23 piksel
            if (rowHeight < 1f) rowHeight = 19f;
            float targetLineSpacing = rowHeight / 11f;
            foreach (var listTr in new Transform[] { listGrade, listName, listLevel, listJob })
            {
                var txt = EnsureListText(listTr);
                if (txt != null)
                {
                    txt.alignment = TextAnchor.UpperCenter;
                    txt.lineSpacing = targetLineSpacing;
                }
            }

            ClearListText(listGrade);
            ClearListText(listName);
            ClearListText(listLevel);
            ClearListText(listJob);

            StyleKnightsButtons(knightsPage);

            var trMemberCountPop = FindKnightsChild(knightsPage, "Text_clan_MemberCount");
            if (trMemberCountPop != null)
            {
                var trValues = trMemberCountPop.Find("Values");
                if (trValues != null)
                {
                    var txtValues = trValues.GetComponent<UnityEngine.UI.Text>();
                    if (txtValues != null)
                    {
                        txtValues.text = $"{onlineCount}\n{totalCount}/50";
                    }
                }
            }

            // 1. Her kolon şeridindeki eski dinamik üye metinlerini temizle
            foreach (var listTr in new Transform[] { listGrade, listName, listLevel, listJob })
            {
                if (listTr == null) continue;
                var toDestroy = new System.Collections.Generic.List<GameObject>();
                foreach (Transform child in listTr)
                {
                    if (child.name.StartsWith("MemberText_"))
                    {
                        toDestroy.Add(child.gameObject);
                    }
                }
                foreach (var go in toDestroy)
                {
                    UnityEngine.Object.Destroy(go);
                }
                var txt = listTr.GetComponent<Text>();
                if (txt != null)
                {
                    txt.text = "";
                    txt.enabled = false;
                }
            }

            // Ayrıca scrollContent içindeki eski RowClickTrigger nesnelerini temizle
            if (scrollContent != null)
            {
                var toDestroyTriggers = new System.Collections.Generic.List<GameObject>();
                foreach (Transform child in scrollContent)
                {
                    if (child.name.StartsWith("RowClickTrigger_"))
                    {
                        toDestroyTriggers.Add(child.gameObject);
                    }
                }
                foreach (var go in toDestroyTriggers)
                {
                    UnityEngine.Object.Destroy(go);
                }
            }

            if (members == null || members.Count == 0)
            {
                return;
            }

            var defaultFont = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");

            // 2. Her üye için kolonlarda ayrı hücreler oluşturalım
            for (int i = 0; i < members.Count; i++)
            {
                var member = members[i];
                string colorHex = member.IsOnline ? "#00FF00" : "#808080";
                
                string gradeStr = member.IsOnline ? GetDutyNameEN((byte)member.Rank) : "....";
                string nameStr = member.Name;
                string levelStr = member.IsOnline ? member.Level.ToString() : "....";
                string jobStr = member.IsOnline ? GetClassName(member.CharClass) : "....";

                string[] texts = new string[] { gradeStr, nameStr, levelStr, jobStr };
                Transform[] lists = new Transform[] { listGrade, listName, listLevel, listJob };

                for (int col = 0; col < 4; col++)
                {
                    var parentCol = lists[col];
                    if (parentCol == null) continue;

                    var cellGo = new GameObject($"MemberText_{i}", typeof(RectTransform), typeof(CanvasRenderer), typeof(UnityEngine.UI.Text));
                    cellGo.transform.SetParent(parentCol, false);

                    var rt = cellGo.GetComponent<RectTransform>();
                    rt.anchorMin = new Vector2(0f, 1f);
                    rt.anchorMax = new Vector2(1f, 1f);
                    rt.pivot = new Vector2(0.5f, 1f);
                    rt.anchoredPosition = new Vector2(0f, -i * 23f);
                    rt.sizeDelta = new Vector2(0f, 23f);
                    rt.localScale = Vector3.one;

                    var cellTxt = cellGo.GetComponent<UnityEngine.UI.Text>();
                    cellTxt.font = defaultFont;
                    if (cellTxt.font == null) cellTxt.font = Font.CreateDynamicFontFromOSFont("Arial", 11);
                    cellTxt.fontSize = 11;
                    cellTxt.alignment = TextAnchor.MiddleCenter;
                    cellTxt.supportRichText = true;
                    cellTxt.raycastTarget = false; // Tıklama tetikleyicisini engellememesi için
                    cellTxt.text = $"<color={colorHex}>{texts[col]}</color>";
                }

                // Her satır için görünmez pazar satırı gibi tıklama tetikleyicisi ekle
                if (scrollContent != null)
                {
                    var clickGo = new GameObject($"RowClickTrigger_{i}", typeof(RectTransform), typeof(CanvasRenderer), typeof(UnityEngine.UI.Image), typeof(UnityEngine.UI.Button));
                    clickGo.transform.SetParent(scrollContent, false);

                    var rtClick = clickGo.GetComponent<RectTransform>();
                    rtClick.anchorMin = new Vector2(0f, 1f);
                    rtClick.anchorMax = new Vector2(1f, 1f);
                    rtClick.pivot = new Vector2(0.5f, 1f);
                    rtClick.anchoredPosition = new Vector2(0f, -i * 23f);
                    rtClick.sizeDelta = new Vector2(0f, 23f);
                    rtClick.localScale = Vector3.one;

                    var clickImg = clickGo.GetComponent<UnityEngine.UI.Image>();
                    clickImg.color = Color.clear; // Görünmez
                    clickImg.raycastTarget = true;

                    int index = i;
                    var clickBtn = clickGo.GetComponent<UnityEngine.UI.Button>();
                    clickBtn.transition = UnityEngine.UI.Selectable.Transition.None;
                    clickBtn.onClick.AddListener(() => {
                        SelectKnightsRow(index, scrollContent, totalTableWidth);
                    });
                }
            }

            // Seçim vurgusu arka planını oluştur veya konumlandır
            if (scrollContent != null)
            {
                var selectionBgTr = scrollContent.Find("KnightsRowSelectionBg");
                UnityEngine.UI.Image selectionBgImg = null;
                if (selectionBgTr == null)
                {
                    var bgGo = new GameObject("KnightsRowSelectionBg", typeof(RectTransform), typeof(CanvasRenderer), typeof(UnityEngine.UI.Image));
                    bgGo.transform.SetParent(scrollContent, false);
                    selectionBgTr = bgGo.transform;
                }
                selectionBgTr.SetSiblingIndex(1); // GridLines (0) ve Hücrelerin arasında
                selectionBgImg = selectionBgTr.GetComponent<UnityEngine.UI.Image>();
                if (selectionBgImg != null)
                {
                    int bgWidth = Mathf.RoundToInt(totalTableWidth) + 20; // Sola-sağa +10px taşma payı
                    selectionBgImg.sprite = GetFadeGradientSprite("knights_selection_fade_bg_" + bgWidth, bgWidth, 23, Color.white, Color.clear, 0);
                    selectionBgImg.type = UnityEngine.UI.Image.Type.Simple;
                    selectionBgImg.color = new Color(0.6f, 0.48f, 0.22f, 0.35f); // Soft gold
                    selectionBgImg.raycastTarget = false;

                    var bgRT = selectionBgTr.GetComponent<RectTransform>();
                    bgRT.anchorMin = new Vector2(0f, 1f);
                    bgRT.anchorMax = new Vector2(0f, 1f);
                    bgRT.pivot = new Vector2(0f, 1f);
                    
                    if (_knightsSelectedIndex >= 0 && _knightsSelectedIndex < members.Count)
                    {
                        bgRT.gameObject.SetActive(true);
                        bgRT.anchoredPosition = new Vector2(-10f, -_knightsSelectedIndex * 23f);
                        bgRT.sizeDelta = new Vector2(bgWidth, 23f);
                    }
                    else
                    {
                        bgRT.gameObject.SetActive(false);
                    }
                    bgRT.localScale = Vector3.one;
                }
            }

            CreateClanHeaders(knightsPage, b0, b1, b2, b3, b4);

            // Klan üye derecesine göre buton görünürlüklerini uygula
            ChangeKnightsUIByDuty(variousRoot);
        }
        
        private void StyleKnightsButtons(Transform knightsPage)
        {
            var km = KOKnightsManager.Instance;
            string clanNameStyle = km?.ClanName ?? GameManager.Instance?.ClanName ?? "";
            bool hasClanStyle = !string.IsNullOrEmpty(clanNameStyle) && clanNameStyle != "---";
            if (knightsPage == null) {
                return;
            }

            // Orijinal/Eski sarı buton ve metin nesnelerini tamamen yok et (Çakışmaları önlemek için)
            var originalsToDestroy = new string[] {
                "text_clan_appoint_a", "text_clan_admit_a", "text_clan_remove_a",
                "ui_String_540E43A8", "ui_String_690EC924", "ui_String_21B9CCCC",
                "ui_String_C5644AF8", "ui_String_F7B8C1D4", "btn_",
                "btn_union", "btn_clan_up", "btn_clan_down"
            };
            foreach (var name in originalsToDestroy)
            {
                var tr = FindKnightsChild(knightsPage, name);
                if (tr != null)
                {
                    UnityEngine.Object.Destroy(tr.gameObject);
                }
            }

            // 1. Orijinal UIF'deki başıboş duran bağımsız metin, buton, kutu ve alan nesnelerini gizle
            foreach (Transform child in knightsPage)
            {
                string cName = child.name.ToLower();

                // Korunması gereken özel ana bileşenler
                if (cName == "text_clansname" || cName == "text_clan_duty" || cName == "text_clan_membercount" || cName == "knightsgridlines" || cName.StartsWith("text_header_"))
                {
                    continue;
                }

                // Bizim 6 aksiyon butonumuz ve Donated korunmalı
                if (cName == "btn_clan_admit" || cName == "btn_clan_appoint" || cName == "btn_clan_remove" || 
                    cName == "btn_clan_whisper" || cName == "btn_clan_private" || 
                    cName == "btn_invite" || cName == "btn_clan_refresh" ||
                    cName == "text_clan_admit_a" || cName == "text_clan_appoint_a" || cName == "text_clan_remove_a" ||
                    cName == "ui_string_540e43a8" || cName == "ui_string_690ec924" || cName == "ui_string_21b9cccc" ||
                    cName == "btn_clan_donated" || cName == "btn_")
                {
                    continue;
                }

                // Gizlenecek olan gereksiz veya boş kutu/sayfa elemanları
                if (cName.Contains("group_page") || cName.Contains("edit_page") || cName.Contains("group_clan_page") ||
                    cName.Contains("edit0") || cName.Contains("edit1") || cName.Contains("edit2") ||
                    cName.Contains("string_page") || cName.Contains("text_clan_page") ||
                    cName.Contains("btn_clan_up") || cName.Contains("btn_clan_down") ||
                    cName.Contains("btn_union") || cName.Contains("btn_clan_party") ||
                    cName.Contains("area") || cName.StartsWith("ui_area_") ||
                    cName.StartsWith("string_") || cName.StartsWith("ui_string_") || cName.StartsWith("text_clan_"))
                {
                    child.gameObject.SetActive(false);
                    continue;
                }

                // Kullanıcının belirttiği sarı/beyaz renkli legacy etiketleri de içeriğe göre gizle
                var txt = child.GetComponent<UnityEngine.UI.Text>();
                if (txt != null)
                {
                    string txtVal = txt.text.Trim();
                    if (string.Equals(txtVal, "join", System.StringComparison.OrdinalIgnoreCase) ||
                        string.Equals(txtVal, "appoint", System.StringComparison.OrdinalIgnoreCase) ||
                        string.Equals(txtVal, "ban", System.StringComparison.OrdinalIgnoreCase) ||
                        string.Equals(txtVal, "invite", System.StringComparison.OrdinalIgnoreCase) ||
                        string.Equals(txtVal, "refresh", System.StringComparison.OrdinalIgnoreCase) ||
                        string.Equals(txtVal, "private", System.StringComparison.OrdinalIgnoreCase) ||
                        string.Equals(txtVal, "confederacy", System.StringComparison.OrdinalIgnoreCase) ||
                        txtVal.StartsWith("Total Members", System.StringComparison.OrdinalIgnoreCase))
                    {
                        child.gameObject.SetActive(false);
                    }
                }
            }

            // 2. Aksiyon Butonları (Kusursuz Simetrik Sabit Koordinatlı Yerleşim)
            var btnAdmit   = FindKnightsButton(knightsPage, "btn_clan_admit") ?? FindKnightsButton(knightsPage, "text_clan_admit_a");
            var btnAppoint = FindKnightsButton(knightsPage, "Btn_clan_Appoint") ?? FindKnightsButton(knightsPage, "text_clan_appoint_a");
            var btnRemove  = FindKnightsButton(knightsPage, "Btn_clan_Remove") ?? FindKnightsButton(knightsPage, "text_clan_remove_a");
            var btnWhisper = FindKnightsButton(knightsPage, "btn_clan_whisper") ?? FindKnightsButton(knightsPage, "btn_clan_private") ?? FindKnightsButton(knightsPage, "ui_String_540E43A8");
            var btnInvite  = FindKnightsButton(knightsPage, "btn_Invite") ?? FindKnightsButton(knightsPage, "ui_String_690EC924");
            var btnRefresh = FindKnightsButton(knightsPage, "btn_clan_refresh") ?? FindKnightsButton(knightsPage, "ui_String_21B9CCCC");

            var buttons = new UnityEngine.UI.Button[] { btnAdmit, btnAppoint, btnRemove, btnWhisper, btnInvite, btnRefresh };
            byte localDutyForLabel = km?.Duty ?? 0;
            string removeBtnLabel = (localDutyForLabel == 1) ? "Kick" : "Leave";
            var labels  = new string[] { "Join Clan", "Appoint", removeBtnLabel, "PM", "Invite Party", "Refresh" };

            // Buton koordinatları (Dikey Stack: Private -> Invite -> Refresh)
            float[] posX = new float[] { 
                273f,  // Join (Sağ sütun ortası)
                121f,  // Appoint
                197f,  // Kick
                273f,  // Private (Sağ sütun en alt)
                45f,   // Invite (Sol sütun en alt)
                273f   // Refresh (Sağ sütun en üst)
            };
            float[] posY = new float[] {
                -438f, // Join (Sağ sütun ortası)
                -474f, // Appoint
                -474f, // Kick
                -474f, // Private (Sağ sütun en alt)
                -474f, // Invite (Sol sütun en alt)
                -402f  // Refresh (Sağ sütun en üst)
            };

            float btnWidth = 70f;
            float btnHeight = 25f;

            var defaultFont = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");

            for (int i = 0; i < buttons.Length; i++)
            {
                var btn = buttons[i];
                if (btn == null) {
                    continue;
                }

                btn.gameObject.SetActive(hasClanStyle);

                var rt = btn.GetComponent<RectTransform>();
                if (rt != null)
                {
                    rt.anchorMin = new Vector2(0f, 1f);
                    rt.anchorMax = new Vector2(0f, 1f);
                    rt.pivot = new Vector2(0.5f, 1f);

                    rt.anchoredPosition = new Vector2(posX[i], posY[i]);
                    rt.sizeDelta = new Vector2(btnWidth, btnHeight);
                    rt.localScale = Vector3.one;
                }

                // --- STYLING START ---
                var raw = btn.GetComponent<UnityEngine.UI.RawImage>();
                if (raw != null) UnityEngine.Object.DestroyImmediate(raw);

                var img = btn.gameObject.GetComponent<UnityEngine.UI.Image>() ?? btn.gameObject.AddComponent<UnityEngine.UI.Image>();
                img.type = UnityEngine.UI.Image.Type.Simple;
                img.color = Color.white;

                Color topCol = Color.black;
                Color botCol = Color.black;
                Color borderCol = Color.black;
                string spriteKey = "";

                if (i == 0 || i == 4 || i == 5) // Join Clan (0), Invite Party (4), Refresh (5) -> OK Green
                {
                    spriteKey = "knights_btn_green";
                    topCol = new Color(0.12f, 0.28f, 0.12f, 0.95f);
                    botCol = new Color(0.12f, 0.28f, 0.12f, 0.95f);
                    borderCol = new Color(0.25f, 0.55f, 0.25f, 0.95f);
                }
                else if (i == 1) // Appoint -> My Merchant Bronze/Gold
                {
                    spriteKey = "knights_btn_bronze";
                    topCol = new Color(0.38f, 0.26f, 0.08f, 1f);
                    botCol = new Color(0.16f, 0.08f, 0.02f, 1f);
                    borderCol = new Color(0.88f, 0.68f, 0.22f, 1f);
                }
                else if (i == 2) // Kick -> CANCEL Red
                {
                    spriteKey = "knights_btn_red";
                    topCol = new Color(0.45f, 0.05f, 0.08f, 0.95f);
                    botCol = new Color(0.45f, 0.05f, 0.08f, 0.95f);
                    borderCol = new Color(0.75f, 0.15f, 0.15f, 0.95f);
                }
                else if (i == 3) // Private -> History Blue
                {
                    spriteKey = "knights_btn_blue";
                    topCol = new Color(0.1f, 0.22f, 0.42f, 1f);
                    botCol = new Color(0.03f, 0.08f, 0.18f, 1f);
                    borderCol = new Color(0.3f, 0.55f, 0.9f, 1f);
                }

                int wInt = Mathf.RoundToInt(btnWidth);
                int hInt = Mathf.RoundToInt(btnHeight);
                img.sprite = GetSkillThemePanelBgSprite(spriteKey + "_" + wInt + "_" + hInt, wInt, hInt, 0, topCol, botCol, borderCol, 1);

                btn.transition = UnityEngine.UI.Selectable.Transition.ColorTint;
                btn.targetGraphic = img;

                var cb = btn.colors;
                cb.normalColor = Color.white;
                cb.highlightedColor = new Color(0.9f, 0.9f, 0.9f, 1f);
                cb.pressedColor = new Color(0.7f, 0.7f, 0.7f, 1f);
                cb.selectedColor = Color.white;
                btn.colors = cb;
                // --- STYLING END ---

                // Butonun tam ortasına yazısını yerleştir
                var txt = btn.GetComponentInChildren<UnityEngine.UI.Text>(true);
                if (txt == null)
                {
                    var txtObj = new GameObject("Text", typeof(RectTransform), typeof(UnityEngine.UI.Text));
                    txtObj.transform.SetParent(btn.transform, false);
                    txt = txtObj.GetComponent<UnityEngine.UI.Text>();
                }

                txt.gameObject.SetActive(true);

                var txtRT = txt.rectTransform;
                if (txtRT != null)
                {
                    txtRT.anchorMin = Vector2.zero;
                    txtRT.anchorMax = Vector2.one;
                    txtRT.sizeDelta = Vector2.zero;
                    txtRT.anchoredPosition = Vector2.zero;
                    txtRT.pivot = new Vector2(0.5f, 0.5f);
                    txtRT.localScale = Vector3.one;
                }

                txt.text = labels[i];
                if (defaultFont != null) txt.font = defaultFont;
                txt.fontSize = 10;
                txt.color = Color.white;
                txt.alignment = TextAnchor.MiddleCenter;
                txt.horizontalOverflow = HorizontalWrapMode.Wrap;
                txt.verticalOverflow = VerticalWrapMode.Overflow;
            }

            // 3. Üye Sayısı Yazısının Sola Hizalanması ve Konumlandırılması (3 Sütunlu Tablo Yapısı)
            var trMemberCount = FindKnightsChild(knightsPage, "Text_clan_MemberCount");
            if (trMemberCount != null)
            {
                // Ana text component'ini gizle ki çift yazmasın
                var parentTxt = trMemberCount.GetComponent<UnityEngine.UI.Text>();
                if (parentTxt != null) parentTxt.enabled = false;

                // 1. Sütun: Etiketler (Total Online Members / Number of Members)
                var trLabels = trMemberCount.Find("Labels");
                if (trLabels == null)
                {
                    var go = new GameObject("Labels", typeof(RectTransform), typeof(UnityEngine.UI.Text));
                    go.transform.SetParent(trMemberCount, false);
                    trLabels = go.transform;
                }
                var txtLabels = trLabels.GetComponent<UnityEngine.UI.Text>();
                txtLabels.alignment = TextAnchor.UpperLeft;
                txtLabels.color = Color.white;
                txtLabels.fontSize = 11;
                if (defaultFont != null) txtLabels.font = defaultFont;
                txtLabels.text = "Total Online Members\nNumber of Members";
                
                var rtLabels = trLabels.GetComponent<RectTransform>();
                rtLabels.anchorMin = new Vector2(0f, 0f);
                rtLabels.anchorMax = new Vector2(1f, 1f);
                rtLabels.pivot = new Vector2(0f, 1f);
                rtLabels.offsetMin = Vector2.zero;
                rtLabels.offsetMax = new Vector2(-85f, 0f); // 200px - 115px = 85px (Genişliği 115px yapar)

                // 2. Sütun: İki Noktalar (:)
                var trColons = trMemberCount.Find("Colons");
                if (trColons == null)
                {
                    var go = new GameObject("Colons", typeof(RectTransform), typeof(UnityEngine.UI.Text));
                    go.transform.SetParent(trMemberCount, false);
                    trColons = go.transform;
                }
                var txtColons = trColons.GetComponent<UnityEngine.UI.Text>();
                txtColons.alignment = TextAnchor.UpperLeft;
                txtColons.color = Color.white;
                txtColons.fontSize = 11;
                if (defaultFont != null) txtColons.font = defaultFont;
                txtColons.text = ":\n:";
                
                var rtColons = trColons.GetComponent<RectTransform>();
                rtColons.anchorMin = new Vector2(0f, 0f);
                rtColons.anchorMax = new Vector2(1f, 1f);
                rtColons.pivot = new Vector2(0f, 1f);
                rtColons.offsetMin = new Vector2(115f, 0f); // X = 115px'ten başlar
                rtColons.offsetMax = new Vector2(-80f, 0f); // Genişliği tam 5px yapar (200px - 115px - 5px = 80px)

                // 3. Sütun: Değerler
                var trValues = trMemberCount.Find("Values");
                if (trValues == null)
                {
                    var go = new GameObject("Values", typeof(RectTransform), typeof(UnityEngine.UI.Text));
                    go.transform.SetParent(trMemberCount, false);
                    trValues = go.transform;
                }
                var txtValues = trValues.GetComponent<UnityEngine.UI.Text>();
                txtValues.alignment = TextAnchor.UpperLeft;
                txtValues.color = Color.white;
                txtValues.fontSize = 11;
                if (defaultFont != null) txtValues.font = defaultFont;
                
                var rtValues = trValues.GetComponent<RectTransform>();
                rtValues.anchorMin = new Vector2(0f, 0f);
                rtValues.anchorMax = new Vector2(1f, 1f);
                rtValues.pivot = new Vector2(0f, 1f);
                rtValues.offsetMin = new Vector2(120f, 0f); // X = 120px'ten başlar (115px + 5px)
                rtValues.offsetMax = Vector2.zero;

                var rt = trMemberCount.GetComponent<RectTransform>();
                if (rt != null)
                {
                    rt.anchorMin = new Vector2(0f, 1f);
                    rt.anchorMax = new Vector2(0f, 1f);
                    rt.pivot = new Vector2(0f, 1f);
                    rt.anchoredPosition = new Vector2(11f, -438f); // Y = -438f ve H = 26f yapıldı. Alt sınır -464f olur, -474f'teki Join butonuyla tam 10px boşluk kalır.
                    rt.sizeDelta = new Vector2(200f, 26f);
                    rt.localScale = Vector3.one;
                }
            }

            // 4. Donated Butonunu Dinamik Ekle (Total Online Members yazısının yukarısına)
            var btnDonatedTr = FindKnightsChild(knightsPage, "btn_clan_donated");
            UnityEngine.UI.Button btnDonated = null;
            if (btnDonatedTr == null)
            {
                if (btnAdmit != null)
                {
                    var donatedObj = UnityEngine.Object.Instantiate(btnAdmit.gameObject, knightsPage, false);
                    donatedObj.name = "btn_clan_donated";
                    btnDonatedTr = donatedObj.transform;
                    btnDonated = donatedObj.GetComponent<UnityEngine.UI.Button>();
                    btnDonated.onClick.RemoveAllListeners();
                }
                else
                {
                    var donatedObj = new GameObject("btn_clan_donated", typeof(RectTransform), typeof(UnityEngine.UI.Image), typeof(UnityEngine.UI.Button));
                    donatedObj.transform.SetParent(knightsPage, false);
                    btnDonatedTr = donatedObj.transform;
                    btnDonated = donatedObj.GetComponent<UnityEngine.UI.Button>();
                }
            }
            else
            {
                btnDonated = btnDonatedTr.GetComponent<UnityEngine.UI.Button>();
            }

            if (btnDonated != null)
            {
                btnDonated.gameObject.SetActive(hasClanStyle);
                var rt = btnDonated.GetComponent<RectTransform>();
                if (rt != null)
                {
                    rt.anchorMin = new Vector2(0f, 1f);
                    rt.anchorMax = new Vector2(0f, 1f);
                    rt.pivot = new Vector2(0.5f, 1f);
                    rt.anchoredPosition = new Vector2(45f, -402f); // Donated Y = -402f (Refresh ile aynı hizada)
                    rt.sizeDelta = new Vector2(btnWidth, btnHeight);
                    rt.localScale = Vector3.one;
                }

                // --- DONATED STYLING START ---
                var rawDonated = btnDonated.GetComponent<UnityEngine.UI.RawImage>();
                if (rawDonated != null) UnityEngine.Object.DestroyImmediate(rawDonated);

                var imgDonated = btnDonated.gameObject.GetComponent<UnityEngine.UI.Image>() ?? btnDonated.gameObject.AddComponent<UnityEngine.UI.Image>();
                imgDonated.type = UnityEngine.UI.Image.Type.Simple;
                imgDonated.color = Color.white;

                int wIntDonated = Mathf.RoundToInt(btnWidth);
                int hIntDonated = Mathf.RoundToInt(btnHeight);
                Color topColDonated = new Color(0.12f, 0.28f, 0.12f, 0.95f);
                Color botColDonated = new Color(0.12f, 0.28f, 0.12f, 0.95f);
                Color borderColDonated = new Color(0.25f, 0.55f, 0.25f, 0.95f);
                imgDonated.sprite = GetSkillThemePanelBgSprite("knights_btn_green_" + wIntDonated + "_" + hIntDonated, wIntDonated, hIntDonated, 0, topColDonated, botColDonated, borderColDonated, 1);

                btnDonated.transition = UnityEngine.UI.Selectable.Transition.ColorTint;
                btnDonated.targetGraphic = imgDonated;

                var cbDonated = btnDonated.colors;
                cbDonated.normalColor = Color.white;
                cbDonated.highlightedColor = new Color(0.9f, 0.9f, 0.9f, 1f);
                cbDonated.pressedColor = new Color(0.7f, 0.7f, 0.7f, 1f);
                cbDonated.selectedColor = Color.white;
                btnDonated.colors = cbDonated;
                // --- DONATED STYLING END ---

                var txt = btnDonated.GetComponentInChildren<UnityEngine.UI.Text>(true);
                if (txt == null)
                {
                    var txtObj = new GameObject("Text", typeof(RectTransform), typeof(UnityEngine.UI.Text));
                    txtObj.transform.SetParent(btnDonated.transform, false);
                    txt = txtObj.GetComponent<UnityEngine.UI.Text>();
                }
                txt.gameObject.SetActive(true);

                var txtRT = txt.rectTransform;
                if (txtRT != null)
                {
                    txtRT.anchorMin = Vector2.zero;
                    txtRT.anchorMax = Vector2.one;
                    txtRT.sizeDelta = Vector2.zero;
                    txtRT.anchoredPosition = Vector2.zero;
                    txtRT.pivot = new Vector2(0.5f, 0.5f);
                    txtRT.localScale = Vector3.one;
                }

                txt.text = "Donated";
                if (defaultFont != null) txt.font = defaultFont;
                txt.fontSize = 10;
                txt.color = Color.white;
                txt.alignment = TextAnchor.MiddleCenter;
            }

            // 5b. Handover Butonunu Dinamik Ekle (Solunda: Donated X=45f, Sağında: Disband X=197f -> Ortada: X=121f, Y = -402f)
            var btnHandoverTr = FindKnightsChild(knightsPage, "btn_clan_handover");
            UnityEngine.UI.Button btnHandover = null;
            if (btnHandoverTr == null)
            {
                if (btnAdmit != null)
                {
                    var handoverObj = UnityEngine.Object.Instantiate(btnAdmit.gameObject, knightsPage, false);
                    handoverObj.name = "btn_clan_handover";
                    btnHandoverTr = handoverObj.transform;
                    btnHandover = handoverObj.GetComponent<UnityEngine.UI.Button>();
                    btnHandover.onClick.RemoveAllListeners();
                }
                else
                {
                    var handoverObj = new GameObject("btn_clan_handover", typeof(RectTransform), typeof(UnityEngine.UI.Image), typeof(UnityEngine.UI.Button));
                    handoverObj.transform.SetParent(knightsPage, false);
                    btnHandoverTr = handoverObj.transform;
                    btnHandover = handoverObj.GetComponent<UnityEngine.UI.Button>();
                }
            }
            else
            {
                btnHandover = btnHandoverTr.GetComponent<UnityEngine.UI.Button>();
            }

            if (btnHandover != null)
            {
                btnHandover.gameObject.SetActive(false); // Default is inactive, selection updates it
                var rt = btnHandover.GetComponent<RectTransform>();
                if (rt != null)
                {
                    rt.anchorMin = new Vector2(0f, 1f);
                    rt.anchorMax = new Vector2(0f, 1f);
                    rt.pivot = new Vector2(0.5f, 1f);
                    rt.anchoredPosition = new Vector2(121f, -402f); // Appoint ile dikeyde tam hizalı
                    rt.sizeDelta = new Vector2(btnWidth, btnHeight);
                    rt.localScale = Vector3.one;
                }

                // --- HANDOVER STYLING START ---
                var rawHandover = btnHandover.GetComponent<UnityEngine.UI.RawImage>();
                if (rawHandover != null) UnityEngine.Object.DestroyImmediate(rawHandover);

                var imgHandover = btnHandover.gameObject.GetComponent<UnityEngine.UI.Image>() ?? btnHandover.gameObject.AddComponent<UnityEngine.UI.Image>();
                imgHandover.type = UnityEngine.UI.Image.Type.Simple;
                imgHandover.color = Color.white;

                int wIntHandover = Mathf.RoundToInt(btnWidth);
                int hIntHandover = Mathf.RoundToInt(btnHeight);
                Color topColHandover = new Color(0.38f, 0.26f, 0.08f, 1f); // Appoint Bronze
                Color botColHandover = new Color(0.16f, 0.08f, 0.02f, 1f);
                Color borderColHandover = new Color(0.88f, 0.68f, 0.22f, 1f);
                imgHandover.sprite = GetSkillThemePanelBgSprite("knights_btn_bronze_" + wIntHandover + "_" + hIntHandover, wIntHandover, hIntHandover, 0, topColHandover, botColHandover, borderColHandover, 1);

                btnHandover.transition = UnityEngine.UI.Selectable.Transition.ColorTint;
                btnHandover.targetGraphic = imgHandover;

                var cbHandover = btnHandover.colors;
                cbHandover.normalColor = Color.white;
                cbHandover.highlightedColor = new Color(0.9f, 0.9f, 0.9f, 1f);
                cbHandover.pressedColor = new Color(0.7f, 0.7f, 0.7f, 1f);
                cbHandover.selectedColor = Color.white;
                btnHandover.colors = cbHandover;
                // --- HANDOVER STYLING END ---

                var txtHandover = btnHandover.GetComponentInChildren<UnityEngine.UI.Text>(true);
                if (txtHandover == null)
                {
                    var txtObj = new GameObject("Text", typeof(RectTransform), typeof(UnityEngine.UI.Text));
                    txtObj.transform.SetParent(btnHandover.transform, false);
                    txtHandover = txtObj.GetComponent<UnityEngine.UI.Text>();
                }

                txtHandover.gameObject.SetActive(true);
                var txtRT = txtHandover.rectTransform;
                if (txtRT != null)
                {
                    txtRT.anchorMin = Vector2.zero;
                    txtRT.anchorMax = Vector2.one;
                    txtRT.sizeDelta = Vector2.zero;
                    txtRT.anchoredPosition = Vector2.zero;
                    txtRT.pivot = new Vector2(0.5f, 0.5f);
                    txtRT.localScale = Vector3.one;
                }

                txtHandover.text = "Handover";
                if (defaultFont != null) txtHandover.font = defaultFont;
                txtHandover.fontSize = 10;
                txtHandover.color = Color.white;
                txtHandover.alignment = TextAnchor.MiddleCenter;
                txtHandover.horizontalOverflow = HorizontalWrapMode.Overflow;
                txtHandover.verticalOverflow = VerticalWrapMode.Overflow;

                btnHandover.onClick.RemoveAllListeners();
                btnHandover.onClick.AddListener(() =>
                {
                    string targetName = GetSelectedMemberName(knightsPage);
                    if (string.IsNullOrEmpty(targetName)) return;

                    if (KOMessageBox.Instance != null)
                    {
                        KOMessageBox.Instance.Show(
                            $"Are you sure you want to handover the Clan leadership to {targetName}?",
                            "Handover Clan Leadership",
                            MsgBoxStyle.MB_YESNO,
                            MsgBoxBehavior.BEHAVIOR_NOTHING,
                            onYes: () =>
                            {
                                KOKnightsManager.Instance?.MsgSend_KnightsAppointChief(targetName);
                            },
                            countdownDuration: 5,
                            forceFixedCenter: true
                        );
                    }
                });
            }

            // 5. Disband Butonunu Dinamik Ekle (Alternatif 1: X = 197f, Y = -402f)
            var btnDisbandTr = FindKnightsChild(knightsPage, "btn_clan_disband");
            UnityEngine.UI.Button btnDisband = null;
            if (btnDisbandTr == null)
            {
                if (btnAdmit != null)
                {
                    var disbandObj = UnityEngine.Object.Instantiate(btnAdmit.gameObject, knightsPage, false);
                    disbandObj.name = "btn_clan_disband";
                    btnDisbandTr = disbandObj.transform;
                    btnDisband = disbandObj.GetComponent<UnityEngine.UI.Button>();
                    btnDisband.onClick.RemoveAllListeners();
                }
                else
                {
                    var disbandObj = new GameObject("btn_clan_disband", typeof(RectTransform), typeof(UnityEngine.UI.Image), typeof(UnityEngine.UI.Button));
                    disbandObj.transform.SetParent(knightsPage, false);
                    btnDisbandTr = disbandObj.transform;
                    btnDisband = disbandObj.GetComponent<UnityEngine.UI.Button>();
                }
            }
            else
            {
                btnDisband = btnDisbandTr.GetComponent<UnityEngine.UI.Button>();
            }

            if (btnDisband != null)
            {
                // Sadece klan başkanı (Chief = localDutyForLabel == 1) ise görünsün
                btnDisband.gameObject.SetActive(hasClanStyle && localDutyForLabel == 1);
                var rt = btnDisband.GetComponent<RectTransform>();
                if (rt != null)
                {
                    rt.anchorMin = new Vector2(0f, 1f);
                    rt.anchorMax = new Vector2(0f, 1f);
                    rt.pivot = new Vector2(0.5f, 1f);
                    rt.anchoredPosition = new Vector2(197f, -402f); // 1. satır, 3. sütun
                    rt.sizeDelta = new Vector2(btnWidth, btnHeight);
                    rt.localScale = Vector3.one;
                }

                // --- DISBAND STYLING START ---
                var rawDisband = btnDisband.GetComponent<UnityEngine.UI.RawImage>();
                if (rawDisband != null) UnityEngine.Object.DestroyImmediate(rawDisband);

                var imgDisband = btnDisband.gameObject.GetComponent<UnityEngine.UI.Image>() ?? btnDisband.gameObject.AddComponent<UnityEngine.UI.Image>();
                imgDisband.type = UnityEngine.UI.Image.Type.Simple;
                imgDisband.color = Color.white;

                int wIntDisband = Mathf.RoundToInt(btnWidth);
                int hIntDisband = Mathf.RoundToInt(btnHeight);
                Color topColDisband = new Color(0.45f, 0.05f, 0.08f, 0.95f);
                Color botColDisband = new Color(0.45f, 0.05f, 0.08f, 0.95f);
                Color borderColDisband = new Color(0.75f, 0.15f, 0.15f, 0.95f);
                imgDisband.sprite = GetSkillThemePanelBgSprite("knights_btn_red_" + wIntDisband + "_" + hIntDisband, wIntDisband, hIntDisband, 0, topColDisband, botColDisband, borderColDisband, 1);

                btnDisband.transition = UnityEngine.UI.Selectable.Transition.ColorTint;
                btnDisband.targetGraphic = imgDisband;

                var cbDisband = btnDisband.colors;
                cbDisband.normalColor = Color.white;
                cbDisband.highlightedColor = new Color(0.9f, 0.9f, 0.9f, 1f);
                cbDisband.pressedColor = new Color(0.7f, 0.7f, 0.7f, 1f);
                cbDisband.selectedColor = Color.white;
                btnDisband.colors = cbDisband;
                // --- DISBAND STYLING END ---

                var txt = btnDisband.GetComponentInChildren<UnityEngine.UI.Text>(true);
                if (txt == null)
                {
                    var txtObj = new GameObject("Text", typeof(RectTransform), typeof(UnityEngine.UI.Text));
                    txtObj.transform.SetParent(btnDisband.transform, false);
                    txt = txtObj.GetComponent<UnityEngine.UI.Text>();
                }

                txt.gameObject.SetActive(true);
                var txtRT = txt.rectTransform;
                if (txtRT != null)
                {
                    txtRT.anchorMin = Vector2.zero;
                    txtRT.anchorMax = Vector2.one;
                    txtRT.sizeDelta = Vector2.zero;
                    txtRT.anchoredPosition = Vector2.zero;
                    txtRT.pivot = new Vector2(0.5f, 0.5f);
                    txtRT.localScale = Vector3.one;
                }

                txt.text = "Disband Clan";
                if (defaultFont != null) txt.font = defaultFont;
                txt.fontSize = 10;
                txt.color = Color.white;
                txt.alignment = TextAnchor.MiddleCenter;
                txt.horizontalOverflow = HorizontalWrapMode.Overflow;
                txt.verticalOverflow = VerticalWrapMode.Overflow;

                // Tıklama olayı: OnBtnDestroy() onay kutusunu tetikler
                btnDisband.onClick.RemoveAllListeners();
                btnDisband.onClick.AddListener(() =>
                {
                    if (KOMessageBox.Instance != null)
                    {
                        KOMessageBox.Instance.Show(
                            "Are you sure you want to disband the Clan?",
                            "Disband Clan",
                            MsgBoxStyle.MB_YESNO,
                            MsgBoxBehavior.BEHAVIOR_KNIGHTS_DESTROY,
                            onYes: () =>
                            {
                                KOKnightsManager.Instance?.MsgSend_KnightsDestroy();
                            },
                            countdownDuration: 5,
                            forceFixedCenter: true
                        );
                    }
                });
            }

            UpdateHandoverButtonState();
        }

        private void UpdateHandoverButtonState()
        {
            var variousRoot = _variousRoot ?? _uiVarious?.transform;
            if (variousRoot == null) return;

            var pages = new string[] { "page_knights", "page_Clan", "page_clan" };
            var km = KOKnightsManager.Instance;
            bool isChief = km != null && km.Duty == 1;

            foreach (var pageId in pages)
            {
                var page = FindKnightsChild(variousRoot, pageId);
                if (page == null) continue;

                var btnHandover = FindKnightsChild(page, "btn_clan_handover");
                if (btnHandover == null) continue;

                bool showHandover = false;
                if (isChief && _knightsSelectedIndex >= 0 && km.Members != null && _knightsSelectedIndex < km.Members.Count)
                {
                    var member = km.Members[_knightsSelectedIndex];
                    if (member.Rank == 2 && member.IsOnline) // Rank 2 is KNIGHTS_DUTY_VICECHIEF
                    {
                        showHandover = true;
                    }
                }

                btnHandover.gameObject.SetActive(showHandover);
            }
        }

        private static void PrintHierarchy(Transform tr, int depth)
        {
            if (tr == null) return;
            foreach (Transform child in tr)
            {
                PrintHierarchy(child, depth + 1);
            }
        }

        private void AddClanGridLines(Transform parentContent, Transform knightsPage, float b0, float b1, float b2, float b3, float b4, float topY, float bottomY, float height)

        {

            if (parentContent == null) return;

            if (knightsPage != null)

            {

                var legacyGrid = knightsPage.Find("knightsgridlines");

                if (legacyGrid != null)

                {

                    legacyGrid.gameObject.SetActive(false);

                }

            }

            var gridContainer = parentContent.Find("ClanGridLinesOverlay");

            if (gridContainer != null)

            {

                Destroy(gridContainer.gameObject);

            }

            // LayoutElement ekleyerek VerticalLayoutGroup tarafından hizalanmasını engelliyoruz

            var containerGo = new GameObject("ClanGridLinesOverlay", typeof(RectTransform), typeof(UnityEngine.UI.LayoutElement));

            containerGo.transform.SetParent(parentContent, false);

            containerGo.transform.SetAsFirstSibling(); // En arkada çizilmesi için

            var le = containerGo.GetComponent<UnityEngine.UI.LayoutElement>();

            if (le != null)

            {

                le.ignoreLayout = true; // Dikey düzenleyici (LayoutGroup) bunu yok saysın

            }

            var containerRT = containerGo.GetComponent<RectTransform>();

            if (containerRT != null)

            {

                containerRT.anchorMin = new Vector2(0f, 0f);

                containerRT.anchorMax = new Vector2(1f, 1f);

                containerRT.offsetMin = Vector2.zero;

                containerRT.offsetMax = Vector2.zero;

            }

            Color lineColor = new Color(0.3f, 0.25f, 0.2f, 0.35f);

            // Draw vertical lines

            float[] xCoords = { b0, b1, b2, b3, b4 };

            for (int i = 0; i < xCoords.Length; i++)

            {

                var vLine = new GameObject($"VLine_{i}", typeof(RectTransform), typeof(UnityEngine.UI.Image));

                vLine.transform.SetParent(containerGo.transform, false);

                var rt = vLine.GetComponent<RectTransform>();

                rt.anchorMin = new Vector2(0f, 1f);

                rt.anchorMax = new Vector2(0f, 1f);

                rt.pivot = new Vector2(0.5f, 0.5f);

                float posX = xCoords[i];

                if (i == 0) posX += 1f;

                if (i == xCoords.Length - 1) posX -= 1f;

                rt.anchoredPosition = new Vector2(posX, (topY + bottomY) / 2f);

                rt.sizeDelta = new Vector2(1f, height);

                vLine.GetComponent<UnityEngine.UI.Image>().color = lineColor;

            }

            // Draw horizontal lines

            int rowCount = Mathf.RoundToInt(height / 23f);

            if (rowCount < 1) rowCount = 1;

            float rowHeight = height / rowCount;

            for (int i = 0; i <= rowCount; i++)

            {

                var hLine = new GameObject($"HLine_{i}", typeof(RectTransform), typeof(UnityEngine.UI.Image));

                hLine.transform.SetParent(containerGo.transform, false);

                var rt = hLine.GetComponent<RectTransform>();

                rt.anchorMin = new Vector2(0f, 1f);

                rt.anchorMax = new Vector2(0f, 1f);

                rt.pivot = new Vector2(0.5f, 0.5f);

                float posY = topY - i * rowHeight;

                if (i == 0) posY -= 1f;

                if (i == rowCount) posY += 1f;

                rt.anchoredPosition = new Vector2((b0 + b4) / 2f, posY);

                rt.sizeDelta = new Vector2(b4 - b0, 1f);

                hLine.GetComponent<UnityEngine.UI.Image>().color = lineColor;

            }

        }

        private void SelectKnightsRow(int index, Transform scrollContent, float totalTableWidth)
        {
            _knightsSelectedIndex = index;

            if (scrollContent != null)
            {
                var selectionBgTr = scrollContent.Find("KnightsRowSelectionBg");
                if (selectionBgTr != null)
                {
                    selectionBgTr.gameObject.SetActive(true);
                    var bgRT = selectionBgTr.GetComponent<RectTransform>();
                    if (bgRT != null)
                    {
                        int bgWidth = Mathf.RoundToInt(totalTableWidth) + 20;
                        bgRT.anchoredPosition = new Vector2(-10f, -index * 23f);
                        bgRT.sizeDelta = new Vector2(bgWidth, 23f);
                    }
                }
            }
            UpdateHandoverButtonState();
        }

        private void CreateClanHeaders(Transform knightsPage, float b0, float b1, float b2, float b3, float b4)
        {
            if (knightsPage == null) return;

            // Headers background with fadeout
            var bgTr = FindKnightsChild(knightsPage, "ClanHeadersBackground");
            UnityEngine.UI.Image bgImg = null;
            if (bgTr == null)
            {
                var bgGo = new GameObject("ClanHeadersBackground", typeof(RectTransform), typeof(CanvasRenderer), typeof(UnityEngine.UI.Image));
                bgGo.transform.SetParent(knightsPage, false);
                bgTr = bgGo.transform;
            }
            bgTr.SetSiblingIndex(1); // Behind headers, in front of BoxBackground (BoxBackground will be at index 0)
            bgImg = bgTr.GetComponent<UnityEngine.UI.Image>();
            if (bgImg != null)
            {
                int bgWidth = Mathf.RoundToInt(b4 - b0) + 20; // Yatayda 20 piksel daha geniş (her iki yana +10px)
                bgImg.sprite = GetFadeGradientSprite("clan_header_fade_bg_" + bgWidth, bgWidth, 23, Color.white, Color.clear, 0); // Yükseklik 23px yapıldı
                bgImg.type = UnityEngine.UI.Image.Type.Simple;
                bgImg.color = new Color(0.6f, 0.48f, 0.22f, 0.35f); // Same soft gold color with 35% opacity
                bgImg.raycastTarget = false;

                var bgRT = bgTr.GetComponent<RectTransform>();
                bgRT.anchorMin = new Vector2(0f, 1f);
                bgRT.anchorMax = new Vector2(0f, 1f);
                bgRT.pivot = new Vector2(0f, 0f); // Bottom-left pivot
                bgRT.anchoredPosition = new Vector2(b0 - 10f, -157f); // Sola doğru 10px kaydırıldı
                bgRT.sizeDelta = new Vector2(bgWidth, 23f); // Yükseklik 23px yapıldı
                bgRT.localScale = Vector3.one;
            }

            var headers = new string[] { "RANK", "CLAN MEMBERS", "LEVEL", "JOB" };

            var boundsLeft = new float[] { b0, b1, b2, b3 };

            var boundsRight = new float[] { b1, b2, b3, b4 };

            var names = new string[] { "Text_Header_Rank", "Text_Header_Name", "Text_Header_Level", "Text_Header_Job" };

            var defaultFont = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");

            Color goldColor = new Color(0.9f, 0.75f, 0.25f); // Yumuşak altın sarısı (#E5C040)

            for (int i = 0; i < headers.Length; i++)

            {

                var headerTr = FindKnightsChild(knightsPage, names[i]);

                UnityEngine.UI.Text txt = null;

                if (headerTr == null)

                {

                    var go = new GameObject(names[i], typeof(RectTransform), typeof(UnityEngine.UI.Text));

                    go.transform.SetParent(knightsPage, false);

                    headerTr = go.transform;

                }

                txt = headerTr.GetComponent<UnityEngine.UI.Text>();

                txt.text = headers[i];

                txt.color = goldColor;

                txt.fontSize = 11;

                txt.fontStyle = FontStyle.Bold;

                if (defaultFont != null) txt.font = defaultFont;

                txt.alignment = TextAnchor.MiddleCenter;

                var rt = headerTr.GetComponent<RectTransform>();

                if (rt != null)

                {

                    rt.anchorMin = new Vector2(0f, 1f);

                    rt.anchorMax = new Vector2(0f, 1f);

                    float left = boundsLeft[i];

                    float right = boundsRight[i];

                    float width = right - left;

                    rt.pivot = new Vector2(0.5f, 0f); // Alt kenardan hizalama

                    rt.anchoredPosition = new Vector2(left + width / 2f, -153f); // Y konumu sabit -167f (yazı yüksekliği ile eşleşir)

                    rt.sizeDelta = new Vector2(width, 15f);

                    rt.localScale = Vector3.one;

                }

            }

        }

