        /// <summary>

        /// C++ birebir: List transform'üzerinde Text component yoksa oluşturur.

        /// UIF'deki CN3UIList için KOUIRenderer özel rendering yapmaz,

        /// bu yüzden Text component runtime'da eklenir.

        /// </summary>

        private Text EnsureListText(Transform listTr)

        {

            if (listTr == null) return null;

            var txt = listTr.GetComponent<Text>();

            if (txt == null)

            {

                // List transform'unda Text yok — oluştur

                txt = listTr.gameObject.AddComponent<Text>();

                txt.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");

                if (txt.font == null)

                    txt.font = Font.CreateDynamicFontFromOSFont("Arial", 11);

                txt.fontSize = 11;

                txt.color = Color.white;

                txt.supportRichText = true;

                txt.alignment = TextAnchor.UpperLeft;

                txt.horizontalOverflow = HorizontalWrapMode.Overflow;

                txt.verticalOverflow = VerticalWrapMode.Overflow;

                txt.raycastTarget = false;

            }

            return txt;

        }

        private void ClearListText(Transform listTr)

        {

            var txt = EnsureListText(listTr);

            if (txt != null) { txt.text = ""; txt.supportRichText = true; }

        }

        private void BindListSelection(Transform listTr, System.Action<int> onSelect)

        {

            var txt = EnsureListText(listTr);

            if (txt != null)

            {

                txt.raycastTarget = true;

                var handler = txt.gameObject.GetComponent<KOListSelectionHandler>();

                if (handler == null) handler = txt.gameObject.AddComponent<KOListSelectionHandler>();

                handler.OnLineSelected = onSelect;

            }

        }

        /// <summary>Liste text'ini set et</summary>

        private void SetListText(Transform listTr, string content)

        {

            var txt = EnsureListText(listTr);

            if (txt != null) { txt.text = content; txt.supportRichText = true; }

        }

