        public void OpenGameOptions()

        {

            if (_uiGameOptions == null)

            {

                var prefab = Resources.Load<GameObject>("ModernUI/GameOptionsPanel");

                if (prefab == null)

                {

                    prefab = Resources.Load<GameObject>("KOPrefabs/UI/GameOptionsPanel");

                }

                if (prefab != null)

                {

                    _uiGameOptions = Instantiate(prefab, _hudContainer != null ? _hudContainer.transform : _canvas.transform);
                    _uiGameOptions.name = prefab.name;
                }
                else
                {
                    _uiGameOptions = new GameObject("GameOptionsPanel");
                    _uiGameOptions.transform.SetParent(_hudContainer != null ? _hudContainer.transform : _canvas.transform, false);
                    _uiGameOptions.AddComponent<GameOptionsUI>();
                }

                if (_uiGameOptions.GetComponent<KOUIScaleIndependent>() == null)

                {

                    _uiGameOptions.AddComponent<KOUIScaleIndependent>();

                }

                var slide = _uiGameOptions.GetComponent<KOUIPanelSlideIn>();

                if (slide == null)

                {

                    slide = _uiGameOptions.AddComponent<KOUIPanelSlideIn>();

                    slide.TargetX = -50f;

                    slide.StartX = 450f;

                }

            }

            OnPanelOpened(_uiGameOptions);

            // Set scale and initial offscreen position immediately before enabling to prevent 1-frame flicker

            if (_canvas != null && _canvas.scaleFactor > 0f)

            {

                float s = _canvas.scaleFactor;

                _uiGameOptions.transform.localScale = new Vector3(1f / s, 1f / s, 1f / s);

            }

            var rtPos = _uiGameOptions.GetComponent<RectTransform>();

            var slideComp = _uiGameOptions.GetComponent<KOUIPanelSlideIn>();

            if (rtPos != null && slideComp != null)

            {

                var pos = rtPos.anchoredPosition;

                pos.x = slideComp.StartX;

                rtPos.anchoredPosition = pos;

            }

            _uiGameOptions.SetActive(true);

            RepositionSkillBarForPanel();

        }

        public void CloseGameOptions()
        {
            if (_uiGameOptions != null)
            {
                var slide = _uiGameOptions.GetComponent<KOUIPanelSlideIn>();
                if (slide != null)
                {
                    slide.SlideOut(() => {
                        _uiGameOptions.SetActive(false);
                        RepositionSkillBarForPanel();
                    });
                }
                else
                {
                    _uiGameOptions.SetActive(false);
                    RepositionSkillBarForPanel();
                }
            }

        }

