                }

                // Add slide-in animation component

                var slide = _uiMerchantControl.AddComponent<KOUIPanelSlideIn>();

                slide.IsLeft = false;

                slide.TargetX = -50f;

                slide.StartX = 450f;

                slide.Duration = 0.2f;

