            if (_uiGameOptions != null && _uiGameOptions.activeSelf) CloseGameOptions();

            // Set scale and initial offscreen position immediately before enabling to prevent 1-frame flicker

            if (_canvas != null && _canvas.scaleFactor > 0f)

            {

                float s = _canvas.scaleFactor;

                _uiMerchantControl.transform.localScale = new Vector3(1f / s, 1f / s, 1f / s);

            }

            var rtPos = _uiMerchantControl.GetComponent<RectTransform>();

            var slideComp = _uiMerchantControl.GetComponent<KOUIPanelSlideIn>();

            if (rtPos != null && slideComp != null)

            {

                var pos = rtPos.anchoredPosition;

                pos.x = slideComp.StartX;

                rtPos.anchoredPosition = pos;

            }

            _uiMerchantControl.SetActive(true);

            _merchantControl?.RefreshUI();

            RepositionSkillBarForPanel();

        }

