                    ShowInventory(false);

                // C++ satır 4855-4856: Transaction açıksa kapat

                // C++ birebir: SetVisibleWithNoSound(false, true) → ItemMoveFromThisToInv()

                if (_uiTransaction != null && _uiTransaction.activeSelf)

                    ShowTransaction(false);

