        public void ShowSkillTree(bool show)

        {

            if (_uiSkillTree == null) return;

            if (show)

            {

                MobileSkillBar.Instance?.SetSkillDragEnabled(true);

                var sw = System.Diagnostics.Stopwatch.StartNew();

                OnPanelOpened(_uiSkillTree);

                long t1 = sw.ElapsedMilliseconds;

                _uiSkillTree.SetActive(true);

                long t2 = sw.ElapsedMilliseconds;

                _uiSkillTree.transform.SetAsLastSibling(); // Bring to front of canvas

                // Tab/sayfa state sıfırla

                _stCurrentKindOf = 0;

                _stCurrentSkillPage = 0;

                ApplySetPageInCharRegion(_uiSkillTree.transform);

                ApplyButtonVisibleStateSet(_uiSkillTree.transform);

                long t3 = sw.ElapsedMilliseconds;

                // C++ birebir: InitIconUpdate() → SkillTree'den öğrenilmiş skill ID'lerini çek

                var skillIds = GetLearnedSkillIdsFromManager();

                if (skillIds != null && skillIds.Length > 0)

                    PopulateSkillTree(skillIds);

                else if (_learnedSkillIds != null)

                    PopulateSkillTree(_learnedSkillIds);

                long t4 = sw.ElapsedMilliseconds;

                // Skill point ve branch değerlerini güncelle

                RefreshSkillTreeUI();

                long t5 = sw.ElapsedMilliseconds;

                // C++ birebir: Render() satır 780 — TooltipRenderDisable()

                // Açılışta tooltip temiz başlasın

                SkillTreeTooltipDisable();

                _selectedSkillId = -1;

                if (!_isSkillTreeThemed)

                {

                    ApplySkillBookUITheme(_uiSkillTree.transform);

                    FixSkillTreePrefabHierarchy(_uiSkillTree.transform);

                    _isSkillTreeThemed = true;

                }

                UpdateTabButtonStyles(_uiSkillTree.transform, _stCurrentKindOf);

                long t6 = sw.ElapsedMilliseconds;

                // Debug.LogWarning($"[SKILL-PROFILE] Open SkillTree Profile:\n" +

                //                  $"  - OnPanelOpened: {t1}ms\n" +

                //                  $"  - SetActive(true): {t2 - t1}ms\n" +

                //                  $"  - Layout & Visible Set: {t3 - t2}ms\n" +

                //                  $"  - PopulateSkillTree: {t4 - t3}ms\n" +

                //                  $"  - RefreshSkillTreeUI: {t5 - t4}ms\n" +

                //                  $"  - Styling & Tabs: {t6 - t5}ms\n" +

                //                  $"  - Total: {t6}ms");

            }

            else

            {

                MobileSkillBar.Instance?.SetSkillDragEnabled(false);

                // Kapatılırken de tooltip temizle

                SkillTreeTooltipDisable();

                _selectedSkillId = -1;

                var slide = _uiSkillTree.GetComponent<KOUIPanelSlideIn>();

                if (slide != null)

                {

                    slide.SlideOut(() => {

                        _uiSkillTree.SetActive(false);

                        RepositionSkillBarForPanel();

                    });

                    // SlideOut başladıktan hemen sonra skillbar animasyonunu 0 hedefine başlatıyoruz

                    RepositionSkillBarForPanel();

                }

                else

                {

                    _uiSkillTree.SetActive(false);

                    RepositionSkillBarForPanel();

                }

            }

            RepositionSkillBarForPanel();

            UpdateSkillDistributionPanelVisibility();

        }

        /// <summary>

        /// C++ birebir: CN3UIBase::AllClearImageByName(szName, bVisible)

        /// UIF child'lardaki id'si szContains içeren öğeleri visible/invisible yapar.

        /// cpp:1929-2047 — SetPageInCharRegion'da kullanılır.

        /// </summary>

        private void AllClearByName(Transform root, string szContains, bool bVisible)

        {

            foreach (Transform child in root)

            {

                // Recursive — child'ların child'ları da tara

                AllClearByName(child, szContains, bVisible);

                string cName = child.gameObject.name;

                // C++ AllClearImageByName: id/name'inde szContains geçen tüm öğeler

                if (cName.IndexOf(szContains, System.StringComparison.OrdinalIgnoreCase) >= 0)

                {

                    child.gameObject.SetActive(bVisible);

                }

            }

        }

        /// <summary>

        /// C++ birebir: UISkillTreeDlg::SetPageInCharRegion() — cpp:1927-2069

        /// Tüm class header image/string'lerini gizle, sadece aktif sınıfa ait olanı göster.

        /// </summary>

        private void ApplySetPageInCharRegion(Transform root)

        {

            var gm = EntropyOnline.Core.GameManager.Instance;

            if (gm == null) return;

            string[] allHeaders = {

                "img_public", "img_blade", "img_Blade Master", "img_ranger", "img_kasar hood",

                "img_mage", "img_Arc Mage", "img_cleric", "img_Paladin",

                "img_berserker", "img_Berserker Hero", "img_hunter", "img_Shadow Bane",

                "img_sorcerer", "img_Elemental Lord", "img_shaman", "img_Shadow Knight"

            };

            foreach (var hName in allHeaders)

            {

                AllClearByName(root, hName, false);

            }

            // cpp:1929: public header gizle

            AllClearByName(root, "img_public", false);

            if (gm.Nation == 2) // NATION_ELMORAD

            {

                // cpp:1990-1997: Tüm Elmorad class header'larını gizle

                AllClearByName(root, "img_blade", false);

                AllClearByName(root, "img_Blade Master", false);

                AllClearByName(root, "img_ranger", false);

                AllClearByName(root, "img_kasar hood", false);

                AllClearByName(root, "img_mage", false);

                AllClearByName(root, "img_Arc Mage", false);

                AllClearByName(root, "img_cleric", false);

                AllClearByName(root, "img_Paladin", false);

                // cpp:1999-2042: Aktif sınıfa ait olanı göster

                switch (gm.CharClass)

                {

                    case GameConstants.CLASS_EL_WARRIOR:

                        AllClearByName(root, "img_public", true);

                        AllClearByName(root, "img_blade", true);

                        break;

                    case GameConstants.CLASS_EL_ROGUE:

                        AllClearByName(root, "img_public", true);

                        AllClearByName(root, "img_ranger", true);

                        break;

                    case GameConstants.CLASS_EL_WIZARD:

                        AllClearByName(root, "img_public", true);

                        AllClearByName(root, "img_mage", true);

                        break;

                    case GameConstants.CLASS_EL_PRIEST:

                        AllClearByName(root, "img_public", true);

                        AllClearByName(root, "img_cleric", true);

                        break;

                    case GameConstants.CLASS_EL_BLADE:

                        AllClearByName(root, "img_blade", true); break;

                    case GameConstants.CLASS_EL_RANGER:

                        AllClearByName(root, "img_ranger", true); break;

                    case GameConstants.CLASS_EL_MAGE:

                        AllClearByName(root, "img_mage", true); break;

                    case GameConstants.CLASS_EL_CLERIC:

                        AllClearByName(root, "img_cleric", true); break;

                    case GameConstants.CLASS_EL_PROTECTOR:

                        AllClearByName(root, "img_Blade Master", true);

                        AllClearByName(root, "img_blade", true);

                        SetChildActiveExact(root, "img_blade", false); break;

                    case GameConstants.CLASS_EL_ASSASSIN:

                        AllClearByName(root, "img_kasar hood", true);

                        AllClearByName(root, "img_ranger", true);

                        SetChildActiveExact(root, "img_ranger", false); break;

                    case GameConstants.CLASS_EL_ENCHANTER:

                        AllClearByName(root, "img_Arc Mage", true);

                        AllClearByName(root, "img_mage", true);

                        SetChildActiveExact(root, "img_mage", false); break;

                    case GameConstants.CLASS_EL_DRUID:

                        AllClearByName(root, "img_Paladin", true);

                        AllClearByName(root, "img_cleric", true);

                        SetChildActiveExact(root, "img_cleric", false); break;

                }

            }

            else // NATION_KARUS

            {

                // cpp:1934-1941: Tüm Karus class header'larını gizle

                AllClearByName(root, "img_berserker", false);

                AllClearByName(root, "img_Berserker Hero", false);

                AllClearByName(root, "img_hunter", false);

                AllClearByName(root, "img_Shadow Bane", false);

                AllClearByName(root, "img_sorcerer", false);

                AllClearByName(root, "img_Elemental Lord", false);

                AllClearByName(root, "img_shaman", false);

                AllClearByName(root, "img_Shadow Knight", false);

                switch (gm.CharClass)

                {

                    case GameConstants.CLASS_KA_WARRIOR:

                        AllClearByName(root, "img_public", true);

                        AllClearByName(root, "img_berserker", true);

                        break;

                    case GameConstants.CLASS_KA_ROGUE:

                        AllClearByName(root, "img_public", true);

                        AllClearByName(root, "img_hunter", true);

                        break;

                    case GameConstants.CLASS_KA_WIZARD:

                        AllClearByName(root, "img_public", true);

                        AllClearByName(root, "img_sorcerer", true);

                        break;

                    case GameConstants.CLASS_KA_PRIEST:

                        AllClearByName(root, "img_public", true);

                        AllClearByName(root, "img_shaman", true);

                        break;

                    case GameConstants.CLASS_KA_BERSERKER:

                        AllClearByName(root, "img_berserker", true); break;

                    case GameConstants.CLASS_KA_HUNTER:

                        AllClearByName(root, "img_hunter", true); break;

                    case GameConstants.CLASS_KA_SORCERER:

                        AllClearByName(root, "img_sorcerer", true); break;

                    case GameConstants.CLASS_KA_SHAMAN:

                        AllClearByName(root, "img_shaman", true); break;

                    case GameConstants.CLASS_KA_GUARDIAN:

                        AllClearByName(root, "img_Berserker Hero", true);

                        AllClearByName(root, "img_berserker", true);

                        SetChildActiveExact(root, "img_berserker", false); break;

                    case GameConstants.CLASS_KA_PENETRATOR:

                        AllClearByName(root, "img_Shadow Bane", true);

                        AllClearByName(root, "img_hunter", true);

                        SetChildActiveExact(root, "img_hunter", false); break;

                    case GameConstants.CLASS_KA_NECROMANCER:

                        AllClearByName(root, "img_Elemental Lord", true);

                        AllClearByName(root, "img_sorcerer", true);

                        SetChildActiveExact(root, "img_sorcerer", false); break;

                    case GameConstants.CLASS_KA_DARKPRIEST:

                        AllClearByName(root, "img_Shadow Knight", true);

                        AllClearByName(root, "img_shaman", true);

                        SetChildActiveExact(root, "img_shaman", false); break;

                }

            }

            // cpp:2049-2068: img_master sadece 2nd job sınıflarında visible

            bool hasMaster = gm.CharClass == GameConstants.CLASS_KA_GUARDIAN ||

                             gm.CharClass == GameConstants.CLASS_KA_PENETRATOR ||

                             gm.CharClass == GameConstants.CLASS_KA_NECROMANCER ||

                             gm.CharClass == GameConstants.CLASS_KA_DARKPRIEST ||

                             gm.CharClass == GameConstants.CLASS_EL_PROTECTOR ||

                             gm.CharClass == GameConstants.CLASS_EL_ASSASSIN ||

                             gm.CharClass == GameConstants.CLASS_EL_ENCHANTER ||

                             gm.CharClass == GameConstants.CLASS_EL_DRUID;

            AllClearByName(root, "img_master", hasMaster);

        }

        /// <summary>

        /// C++ birebir: UISkillTreeDlg::ButtonVisibleStateSet() — cpp:1352-1649

        /// Tüm class-specific tab butonlarını gizle, sadece aktif sınıfa ait olanları göster.

        /// </summary>

        private void ApplyButtonVisibleStateSet(Transform root)

        {

            var gm = GameManager.Instance;

            if (gm == null) return;

            // Elmorad butonları  cpp:1406-1437

            string[] elButtons = { "btn_ranger0", "btn_ranger1", "btn_ranger2",

                                  "btn_blade0", "btn_blade1", "btn_blade2",

                                  "btn_mage0", "btn_mage1", "btn_mage2",

                                  "btn_cleric0", "btn_cleric1", "btn_cleric2" };

            // Karus butonlar  cpp:1438-1471

            string[] kaButtons = { "btn_hunter0", "btn_hunter1", "btn_hunter2",

                                  "btn_berserker0", "btn_berserker1", "btn_berserker2",

                                  "btn_sorcerer0", "btn_sorcerer1", "btn_sorcerer2",

                                  "btn_shaman0", "btn_shaman1", "btn_shaman2" };

            // cpp:1401-1404: master balangta gizli

            SetChildVisible(root, "btn_master", false);

            SetChildInteractable(root, "btn_master", true);

            // Tm butonlar gizle ve varsaylan olarak aktif/tklanabilir yap

            foreach (var name in elButtons)

            {

                SetChildVisible(root, name, false);

                SetChildInteractable(root, name, true);

            }

            foreach (var name in kaButtons)

            {

                SetChildVisible(root, name, false);

                SetChildInteractable(root, name, true);

            }

            // cpp:1484-1648: Aktif snfa ait butonlar gster

            switch (gm.CharClass)

            {

                // Elmorad

                case GameConstants.CLASS_EL_BLADE:

                case GameConstants.CLASS_EL_PROTECTOR:

                    SetChildVisible(root, "btn_blade0", true);

                    SetChildVisible(root, "btn_blade1", true);

                    SetChildVisible(root, "btn_blade2", true);

                    if (gm.CharClass == GameConstants.CLASS_EL_PROTECTOR)

                        SetChildVisible(root, "btn_master", true);

                    break;

                case GameConstants.CLASS_EL_RANGER:

                case GameConstants.CLASS_EL_ASSASSIN:

                    SetChildVisible(root, "btn_ranger0", true);

                    SetChildVisible(root, "btn_ranger1", true);

                    SetChildVisible(root, "btn_ranger2", true);

                    if (gm.CharClass == GameConstants.CLASS_EL_ASSASSIN)

                        SetChildVisible(root, "btn_master", true);

                    break;

                case GameConstants.CLASS_EL_MAGE:

                case GameConstants.CLASS_EL_ENCHANTER:

                    SetChildVisible(root, "btn_mage0", true);

                    SetChildVisible(root, "btn_mage1", true);

                    SetChildVisible(root, "btn_mage2", true);

                    if (gm.CharClass == GameConstants.CLASS_EL_ENCHANTER)

                        SetChildVisible(root, "btn_master", true);

                    break;

                case GameConstants.CLASS_EL_CLERIC:

                case GameConstants.CLASS_EL_DRUID:

                    SetChildVisible(root, "btn_cleric0", true);

                    SetChildVisible(root, "btn_cleric1", true);

                    SetChildVisible(root, "btn_cleric2", true);

                    if (gm.CharClass == GameConstants.CLASS_EL_DRUID)

                        SetChildVisible(root, "btn_master", true);

                    break;

                // Karus

                case GameConstants.CLASS_KA_BERSERKER:

                case GameConstants.CLASS_KA_GUARDIAN:

                    SetChildVisible(root, "btn_berserker0", true);

                    SetChildVisible(root, "btn_berserker1", true);

                    SetChildVisible(root, "btn_berserker2", true);

                    if (gm.CharClass == GameConstants.CLASS_KA_GUARDIAN)

                        SetChildVisible(root, "btn_master", true);

                    break;

                case GameConstants.CLASS_KA_HUNTER:

                case GameConstants.CLASS_KA_PENETRATOR:

                    SetChildVisible(root, "btn_hunter0", true);

                    SetChildVisible(root, "btn_hunter1", true);

                    SetChildVisible(root, "btn_hunter2", true);

                    if (gm.CharClass == GameConstants.CLASS_KA_PENETRATOR)

                        SetChildVisible(root, "btn_master", true);

                    break;

                case GameConstants.CLASS_KA_SORCERER:

                case GameConstants.CLASS_KA_NECROMANCER:

                    SetChildVisible(root, "btn_sorcerer0", true);

                    SetChildVisible(root, "btn_sorcerer1", true);

                    SetChildVisible(root, "btn_sorcerer2", true);

                    if (gm.CharClass == GameConstants.CLASS_KA_NECROMANCER)

                        SetChildVisible(root, "btn_master", true);

                    break;

                case GameConstants.CLASS_KA_SHAMAN:

                case GameConstants.CLASS_KA_DARKPRIEST:

                    SetChildVisible(root, "btn_shaman0", true);

                    SetChildVisible(root, "btn_shaman1", true);

                    SetChildVisible(root, "btn_shaman2", true);

                    if (gm.CharClass == GameConstants.CLASS_KA_DARKPRIEST)

                        SetChildVisible(root, "btn_master", true);

                    break;

                // Elmorad Base Classes (Sekmeleri gster ama kilitleme)

                case GameConstants.CLASS_EL_WARRIOR:

                    SetChildVisible(root, "btn_blade0", true);

                    SetChildVisible(root, "btn_blade1", true);

                    SetChildVisible(root, "btn_blade2", true);

                    break;

                case GameConstants.CLASS_EL_ROGUE:

                    SetChildVisible(root, "btn_ranger0", true);

                    SetChildVisible(root, "btn_ranger1", true);

                    SetChildVisible(root, "btn_ranger2", true);

                    break;

                case GameConstants.CLASS_EL_WIZARD:

                    SetChildVisible(root, "btn_mage0", true);

                    SetChildVisible(root, "btn_mage1", true);

                    SetChildVisible(root, "btn_mage2", true);

                    break;

                case GameConstants.CLASS_EL_PRIEST:

                    SetChildVisible(root, "btn_cleric0", true);

                    SetChildVisible(root, "btn_cleric1", true);

                    SetChildVisible(root, "btn_cleric2", true);

                    break;

                // Karus Base Classes (Sekmeleri gster ama kilitleme)

                case GameConstants.CLASS_KA_WARRIOR:

                    SetChildVisible(root, "btn_berserker0", true);

                    SetChildVisible(root, "btn_berserker1", true);

                    SetChildVisible(root, "btn_berserker2", true);

                    break;

                case GameConstants.CLASS_KA_ROGUE:

                    SetChildVisible(root, "btn_hunter0", true);

                    SetChildVisible(root, "btn_hunter1", true);

                    SetChildVisible(root, "btn_hunter2", true);

                    break;

                case GameConstants.CLASS_KA_WIZARD:

                    SetChildVisible(root, "btn_sorcerer0", true);

                    SetChildVisible(root, "btn_sorcerer1", true);

                    SetChildVisible(root, "btn_sorcerer2", true);

                    break;

                case GameConstants.CLASS_KA_PRIEST:

                    SetChildVisible(root, "btn_shaman0", true);

                    SetChildVisible(root, "btn_shaman1", true);

                    SetChildVisible(root, "btn_shaman2", true);

                    break;

            }

        }

        private static void SetChildVisible(Transform root, string childName, bool visible)

        {

            var child = KOUIRenderer.FindChildByID(root, childName);

            if (child != null) child.gameObject.SetActive(visible);

        }

        private static void SetChildInteractable(Transform root, string childName, bool interactable)

        {

            var btn = KOUIRenderer.FindChildButton(root, childName);

            if (btn != null) btn.interactable = interactable;

        }

        /// <summary>

        /// C++ birebir: UISkillTreeDlg::InitIconUpdate() sonrası öğrenilmiş skill ID'lerini çek.

        /// KOSkillTreeManager.SkillTree[kindOf][page][slot] → HasLevel==true olanları topla.

        /// </summary>

        private int[] GetLearnedSkillIdsFromManager()

        {

            var mgr = KOSkillTreeManager.Instance;

            if (mgr == null) return null;

            // Tablo yüklü ise InitIconUpdate çağır — güncel skill listesi oluştur

            if (KOImport.SkillTableParser.IsLoaded)

                mgr.InitIconUpdate();

            // HasLevel==true olan tüm skill ID'leri topla

            var list = new System.Collections.Generic.List<int>();

            for (int i = 0; i < KOSkillTreeManager.MAX_SKILL_KIND_OF; i++)

                for (int j = 0; j < KOSkillTreeManager.MAX_SKILL_PAGE_NUM; j++)

                    for (int k = 0; k < KOSkillTreeManager.MAX_SKILL_IN_PAGE; k++)

                    {

                        var entry = mgr.SkillTree[i, j, k];

                        if (entry != null && entry.HasLevel)

                            list.Add(entry.SkillId);

                    }

            return list.Count > 0 ? list.ToArray() : null;

        }

        /// <summary>

        /// SkillTree text referanslarını ve butonlarını bağlar.

        /// C++ referans: UISkillTreeDlg.cpp InitIconWnd() satır 1183-1193, ReceiveMessage() satır 236-277

        /// </summary>

        private void BindSkillTreeElements(Transform root)

        {

            // C++ UISkillTreeDlg.cpp satır 1187: m_pStr_info = GetChildByID<CN3UIString>("string_info")

            _textSkillInfo = KOUIRenderer.FindChildText(root, "string_info");

            // C++ UISkillTreeDlg.cpp satır 1189: m_pStr_skill_point = GetChildByID<CN3UIString>("string_skillpoint")

            _textSkillPoint = KOUIRenderer.FindChildText(root, "string_skillpoint");

            // C++ birebir: UISkillTreeDlg.cpp InitIconWnd() satır 1188-1192

            // Tooltip text elementleri — skill hover/tıklama bilgisi

            _textSkillMp = KOUIRenderer.FindChildText(root, "string_skill_mp");

            _textSkillPointReq = KOUIRenderer.FindChildText(root, "string_skill_point");

            _textSkillItem0 = KOUIRenderer.FindChildText(root, "string_skill_item0");

            _textSkillItem1 = KOUIRenderer.FindChildText(root, "string_skill_item1");

            _textSkillItem2 = KOUIRenderer.FindChildText(root, "string_skill_item2");



            // cpp:1317-1347: string_0..string_7 — branch puanları

            for (int i = 0; i < 8; i++)

            {

                _stBranchTexts[i] = KOUIRenderer.FindChildText(root, $"string_{i}");

            }

            // cpp:1897-1899: string_page — sayfa numarası

            _stPageText = KOUIRenderer.FindChildText(root, "string_page");

            // C++ birebir: UISkillTreeDlg.cpp:1881 — string_list_0..5 (skill adları)

            for (int i = 0; i < 6; i++)

            {

                _stSkillNameTexts[i] = KOUIRenderer.FindChildText(root, $"string_list_{i}");

            }

            int stNameCount = 0;

            for (int i2 = 0; i2 < 6; i2++) { if (_stSkillNameTexts[i2] != null) stNameCount++; }

            // C++ UISkillTreeDlg.cpp satır 236: btn_close → Close()

            var btnClose = KOUIRenderer.FindChildButton(root, "btn_close");

            if (btnClose != null)

            {

                btnClose.onClick.AddListener(() => ShowSkillTree(false));

            }

            // cpp:239-242: btn_left / btn_right — sayfa navigasyonu

            var btnLeft = KOUIRenderer.FindChildButton(root, "btn_left");

            if (btnLeft != null)

                btnLeft.onClick.AddListener(() => SkillTreePageChange(_stCurrentKindOf, _stCurrentSkillPage - 1));

            var btnRight = KOUIRenderer.FindChildButton(root, "btn_right");

            if (btnRight != null)

                btnRight.onClick.AddListener(() => SkillTreePageChange(_stCurrentKindOf, _stCurrentSkillPage + 1));

            // cpp:261: btn_public → SetPageInIconRegion(0, 0)

            var btnPublic = KOUIRenderer.FindChildButton(root, "btn_public");

            if (btnPublic != null)

                btnPublic.onClick.AddListener(() => SkillTreePageChange(0, 0));

            // cpp:263-276: sınıf bazlı tab butonları → SetPageInIconRegion(1/2/3/4, 0)

            // Elmorad tab butonları

            string[] elTabNames = { "btn_ranger", "btn_blade", "btn_mage", "btn_cleric" };

            // Karus tab butonları

            string[] kaTabNames = { "btn_hunter", "btn_berserker", "btn_sorcerer", "btn_shaman" };

            foreach (var tabBase in elTabNames)

            {

                for (int t = 0; t < 3; t++)

                {

                    int kindOf = t + 1; // 1, 2, 3

                    var btn = KOUIRenderer.FindChildButton(root, $"{tabBase}{t}");

                    if (btn != null)

                        btn.onClick.AddListener(() => SkillTreePageChange(kindOf, 0));

                }

            }

            foreach (var tabBase in kaTabNames)

            {

                for (int t = 0; t < 3; t++)

                {

                    int kindOf = t + 1;

                    var btn = KOUIRenderer.FindChildButton(root, $"{tabBase}{t}");

                    if (btn != null)

                        btn.onClick.AddListener(() => SkillTreePageChange(kindOf, 0));

                }

            }

            // cpp:275-276: btn_master → SetPageInIconRegion(4, 0)

            var btnMaster = KOUIRenderer.FindChildButton(root, "btn_master");

            if (btnMaster != null)

                btnMaster.onClick.AddListener(() => SkillTreePageChange(4, 0));

            // btn_0..7 click listeners are completely removed since point distribution is handled by the new custom panel

        }

        /// <summary>

        /// C++ birebir: SetPageInIconRegion(kindOf, page) — tab/sayfa değiştirme

        /// Sadece aktif kindOf + page'deki skill ikonlarını göster.

        /// </summary>

        private void SkillTreePageChange(int kindOf, int page)

        {

            if (kindOf < 0 || kindOf >= ST_MAX_KIND) return;

            if (page < 0 || page >= ST_MAX_PAGE) return;

            _stCurrentKindOf = kindOf;

            _stCurrentSkillPage = page;

            // Sayfa değişince tooltip temizle — C++ birebir: Render() her frame TooltipRenderDisable

            SkillTreeTooltipDisable();

            _selectedSkillId = -1;

            // KOSkillTreeManager'ı da güncelle

            var mgr = KOSkillTreeManager.Instance;

            if (mgr != null)

            {

                mgr.CurKindOf = kindOf;

                mgr.CurSkillPage = page;

            }

            // Visibility güncelle

            if (_stSkillObjs != null)

            {

                for (int k = 0; k < ST_MAX_KIND; k++)

                    for (int p = 0; p < ST_MAX_PAGE; p++)

                        for (int s = 0; s < ST_MAX_SLOT; s++)

                        {

                            if (_stSkillObjs[k, p, s] != null)

                                _stSkillObjs[k, p, s].SetActive(k == kindOf && p == page);

                        }

            }

            // Sayfa numarası güncelle

            if (_stPageText != null)

                _stPageText.text = (page + 1).ToString();

            // C++ birebir: UISkillTreeDlg.cpp:1877-1892

            // string_list_0..5 → aktif sayfadaki skill adları

            UpdateSkillNameTexts(kindOf, page);

            if (_uiSkillTree != null)

            {

                UpdateTabButtonStyles(_uiSkillTree.transform, _stCurrentKindOf);

            }

        }

        /// <summary>

        /// C++ birebir: UISkillTreeDlg.cpp:1877-1892

        /// Aktif sayfadaki her slot için string_list_k → pSkill->szName yaz.

        /// Slot boşsa text'i gizle.

        /// </summary>

        private void UpdateSkillNameTexts(int kindOf, int page)

        {

            var skillMgr = KOSkillTreeManager.Instance;

            for (int k = 0; k < 6; k++)

            {

                if (_stSkillNameTexts[k] == null) continue;

                // C++ birebir: cpp:1879-1884

                SkillIconEntry entry = null;

                if (skillMgr != null

                    && kindOf >= 0 && kindOf < KOSkillTreeManager.MAX_SKILL_KIND_OF

                    && page >= 0 && page < KOSkillTreeManager.MAX_SKILL_PAGE_NUM)

                {

                    entry = skillMgr.SkillTree[kindOf, page, k];

                }

                if (entry != null && entry.Skill != null && !string.IsNullOrEmpty(entry.Skill.Name))

                {

                    // C++ birebir: cpp:1883 — pStrName->SetString(pSkill->szName)

                    _stSkillNameTexts[k].text = entry.Skill.Name;

                    _stSkillNameTexts[k].gameObject.SetActive(true);

                }

                else

                {

                    // C++ birebir: cpp:1890 — pStrName->SetVisible(false)

                    _stSkillNameTexts[k].gameObject.SetActive(false);

                }

            }

        }

        /// <summary>Skill point ve branch değerlerini UI'a yaz</summary>

        public void RefreshSkillTreeUI()

        {

            var mgr = KOSkillTreeManager.Instance;

            if (mgr == null) return;

            // cpp:1313-1315: string_skillpoint = m_iSkillInfo[0]

            if (_textSkillPoint != null)

                _textSkillPoint.text = mgr.SkillInfo[0].ToString();

            // cpp:1317-1347: string_0..string_7 = m_iSkillInfo[1..8]

            for (int i = 0; i < 8; i++)

            {

                if (_stBranchTexts[i] != null)

                    _stBranchTexts[i].text = mgr.SkillInfo[i + 1].ToString();

            }

            if (_uiSkillTree != null)

            {

                UpdateTabButtonStyles(_uiSkillTree.transform, _stCurrentKindOf);

            }

            // Yerinde güncelleme yöntemiyle ikonları anlık yenile (Open-KO uyumlu)

            RefreshSkillTreeIcons();

            UpdateSkillDistributionPanelVisibility();

        }

        private void RefreshSkillTreeIcons()

        {

            var skillMgr = KOSkillTreeManager.Instance;

            if (skillMgr == null) return;

            // Hafızadaki entry kilit durumlarını son SkillInfo durumuna göre güncelle

            skillMgr.InitIconUpdate();

            for (int k = 0; k < ST_MAX_KIND; k++)

            {

                for (int p = 0; p < ST_MAX_PAGE; p++)

                {

                    for (int s = 0; s < ST_MAX_SLOT; s++)

                    {

                        var itemObj = _stSkillObjs[k, p, s];

                        if (itemObj == null) continue;

                        var entry = skillMgr.SkillTree[k, p, s];

                        if (entry == null) continue;

                        var img = itemObj.GetComponent<UnityEngine.UI.Image>();

                        if (img == null) continue;

                        int skillId = entry.SkillId;

                        _stSkillIds[k, p, s] = skillId;

                        // GameObject adını duruma göre güncelle

                        itemObj.name = $"Skill_{skillId}_{(entry.HasLevel ? "open" : "locked")}";

                        img.raycastTarget = true;

                        if (entry.HasLevel)

                        {

                            Sprite icon = KOItemIconLoader.LoadSkillIcon(skillId);

                            if (icon != null)

                            {

                                img.sprite = icon;

                                img.color = Color.white;

                            }

                            else

                            {

                                img.color = new Color(0.2f, 0.4f, 0.2f, 0.5f);

                            }

                            // Sürükle-bırak (Drag Drop) özelliğini aktif et veya güncelle

                            var dragDrop = itemObj.GetComponent<KOSkillDragDrop>();

                            if (dragDrop == null) dragDrop = itemObj.AddComponent<KOSkillDragDrop>();

                            dragDrop.SetSkillData(skillId, icon, true);

                            // Tıklama olayını (Button) ekle

                            var btn = itemObj.GetComponent<Button>();

                            if (btn == null)

                            {

                                btn = itemObj.AddComponent<Button>();

                                btn.transition = Selectable.Transition.None;

                                int capturedId = skillId;

                                btn.onClick.AddListener(() => OnSkillIconClicked(capturedId));

                            }

                        }

                        else

                        {

                            Sprite enigmaIcon = KOItemIconLoader.LoadEnigmaIcon();

                            if (enigmaIcon != null)

                            {

                                img.sprite = enigmaIcon;

                                img.color = Color.white;

                            }

                            else

                            {

                                img.color = new Color(0.3f, 0.3f, 0.3f, 0.6f);

                            }

                            // Kilitli beceriler taşınamaz (dragDrop kaldır) ama tıklanabilir (Button koru/ekle)

                            var dragDrop = itemObj.GetComponent<KOSkillDragDrop>();

                            if (dragDrop != null) Destroy(dragDrop);

                            var btn = itemObj.GetComponent<Button>();

                            if (btn == null)

                            {

                                btn = itemObj.AddComponent<Button>();

                                btn.transition = Selectable.Transition.None;

                                int capturedId = skillId;

                                btn.onClick.AddListener(() => OnSkillIconClicked(capturedId));

                            }

                        }

                        // Kenarlık (Border Frame) görselini güncelle

                        var borderTransform = itemObj.transform.Find("BorderFrame");

                        if (borderTransform != null)

                        {

                            var borderImg = borderTransform.GetComponent<UnityEngine.UI.Image>();

                            if (borderImg != null)

                            {

                                borderImg.sprite = GetSkillThemeRoundedRectSprite(

                                    entry.HasLevel ? "slot_border_premium" : "slot_border_locked",

                                    36, 36, 0, Color.clear,

                                    entry.HasLevel ? new Color(0.55f, 0.45f, 0.20f, 0.9f) : new Color(0.35f, 0.35f, 0.35f, 0.7f),

                                    1

                                );

                            }

                        }

                    }

                }

            }

        }

        // ================================================================

        // SkillTree Tooltip — C++ birebir: UISkillTreeDlg.cpp:774-1181

        // Mobil adaptasyon: C++ hover → tıklama

        // ================================================================

        /// <summary>

        /// Mobil adaptasyon: Skill ikonuna tıklanınca çağrılır.

        /// C++ karşılığı: Render() satır 789-792 → UISTYLE_ICON_HIGHLIGHT tetiklemesi.

        /// Aynı skill'e tekrar tıklanırsa tooltip kapatılır (toggle).

        /// </summary>

        private void OnSkillIconClicked(int skillId)

        {

            // Debug.LogWarning($"[SKILL-CLICK] OnSkillIconClicked called for skillId: {skillId}");

            // Toggle: aynı skill'e tekrar tıkla → kapat

            if (_selectedSkillId == skillId)

            {

                SkillTreeTooltipDisable();

                _selectedSkillId = -1;

                return;

            }

            _selectedSkillId = skillId;

            // C++ birebir: spSkill = GetHighlightIconItem(pChild)

            var pSkill = KOImport.SkillTableParser.Find(skillId);

            if (pSkill == null)

            {

                SkillTreeTooltipDisable();

                return;

            }

            SkillTreeTooltipEnable(pSkill);

        }

        /// <summary>

        /// C++ birebir: UISkillTreeDlg::TooltipRenderEnable(__IconItemSkill* spSkill)

        /// UISkillTreeDlg.cpp satır 997-1171

        ///

        /// 6 text alanını doldurur:

        ///   1. string_info      → pSkill->szDesc (description)

        ///   2. string_skill_mp  → MP consumed / Doesn't use MP

        ///   3. string_skill_point → Required Level / Required Skill Point

        ///   4. string_skill_item0 → Required weapon type

        ///   5. string_skill_item1 → Required item

        ///   6. string_skill_item2 → Consumed item

        /// </summary>

        private void SkillTreeTooltipEnable(KOImport.SkillEntry pSkill)

        {

            if (pSkill == null) return;

            // ---- 1. Description ---- cpp:1004-1008

            if (_textSkillInfo != null)

            {

                _textSkillInfo.gameObject.SetActive(true);

                _textSkillInfo.text = pSkill.Desc;

            }

            // ---- 2. MP consumed ---- cpp:1010-1019

            if (_textSkillMp != null)

            {

                _textSkillMp.gameObject.SetActive(true);

                // C++ birebir: cpp:1014-1017

                if (pSkill.ExhaustMSP == 0)

                    _textSkillMp.text = "Doesn't use MP";                         // IDS_SKILL_TOOLTIP_NO_MANA (4320)

                else

                    _textSkillMp.text = $"MP consumed : {pSkill.ExhaustMSP}";     // IDS_SKILL_TOOLTIP_USE_MANA (4323)

            }

            // ---- 3. Required level/skill point ---- cpp:1022-1033

            if (_textSkillPointReq != null)

            {

                _textSkillPointReq.gameObject.SetActive(true);

                // C++ birebir: cpp:1027-1031

                // Basic skills: iNeedSkill % 10 == 0 → "Required Level"

                // 2nd job / master: → "Required Skill Point"

                if ((pSkill.NeedSkill % 10) == 0)

                    _textSkillPointReq.text = $"Required Level : {pSkill.NeedLevel}";      // IDS_SKILL_TOOLTIP_NEED_LEVEL (4324)

                else

                    _textSkillPointReq.text = $"Required Skill Point : {pSkill.NeedLevel}"; // IDS_SKILL_TOOLTIP_NEED_SKILL_PT (4325)

            }

            // ---- 4. Required weapon type ---- cpp:1036-1098

            if (_textSkillItem0 != null)

            {

                _textSkillItem0.gameObject.SetActive(true);

                _textSkillItem0.text = GetNeedItemString(pSkill.NeedItem);

            }

            // ---- 5. Required item (e.g. scroll, arrows) ---- cpp:1101-1118

            if (_textSkillItem1 != null)

            {

                _textSkillItem1.gameObject.SetActive(true);

                // C++ birebir: cpp:1105-1115

                if (pSkill.ExhaustItem != 0)

                {

                    // C++ birebir: s_pTbl_Items_Basic.Find(dwExhaustItem)->szName

                    // Unity: ItemDataManager.GetItemBasic() → SzName

                    var itemBasic = KOImport.ItemDataManager.GetItemBasic((int)pSkill.ExhaustItem);

                    if (itemBasic != null && !string.IsNullOrEmpty(itemBasic.SzName))

                        _textSkillItem1.text = $"Required item : {itemBasic.SzName}"; // IDS_SKILL_TOOLTIP_ITEM_NEED (4329)

                    else

                        _textSkillItem1.text = "No required item";           // fallback

                }

                else

                {

                    _textSkillItem1.text = "No required item";               // IDS_SKILL_TOOLTIP_ITEM_NO (4330)

                }

            }

            // ---- 6. Consumed item ---- cpp:1121-1162

            if (_textSkillItem2 != null)

            {

                _textSkillItem2.gameObject.SetActive(true);

                // C++ birebir: cpp:1127-1147 — master scroll → stone dönüşümü

                // Çoğu skill için consumed item yok

                // Master scroll ID'leri sabit: 379006000-379009000 aralığı

                // Basitlik: ExhaustItem == 0 → "No item consumed"

                _textSkillItem2.text = "No item consumed";                   // IDS_SKILL_TOOLTIP_USE_ITEM_NO (4322)

            }

            Text[] tooltipTexts = { _textSkillInfo, _textSkillMp, _textSkillPointReq, _textSkillItem0, _textSkillItem1, _textSkillItem2 };

            foreach (var txt in tooltipTexts)

            {

                if (txt != null)

                {

                    txt.color = new Color(0.9f, 0.9f, 0.9f, 1);

                    txt.fontSize = 12;

                    AddSkillThemeTextShadow(txt);

                }

            }

        }

        /// <summary>

        /// C++ birebir: UISkillTreeDlg::TooltipRenderDisable()

        /// UISkillTreeDlg.cpp satır 1173-1181

        /// Tüm tooltip text'lerini gizler.

        /// </summary>

        private void SkillTreeTooltipDisable()

        {

            // C++ birebir: cpp:1175-1180

            if (_textSkillInfo != null) _textSkillInfo.gameObject.SetActive(false);

            if (_textSkillMp != null) _textSkillMp.gameObject.SetActive(false);

            if (_textSkillPointReq != null) _textSkillPointReq.gameObject.SetActive(false);

            if (_textSkillItem0 != null) _textSkillItem0.gameObject.SetActive(false);

            if (_textSkillItem1 != null) _textSkillItem1.gameObject.SetActive(false);

            if (_textSkillItem2 != null) _textSkillItem2.gameObject.SetActive(false);

        }

        /// <summary>

        /// C++ birebir: UISkillTreeDlg.cpp:1040-1096 — dwNeedItem → silah tipi string mapping

        /// text_resources.h satır 274-299 — IDS_SKILL_TOOLTIP_NEED_ITEM_ID1..17 + NEED_ITEM_NO

        /// </summary>

        private static string GetNeedItemString(uint dwNeedItem)

        {

            return dwNeedItem switch

            {

                0  => "Required Item : All Weapons",       // IDS_SKILL_TOOLTIP_NEED_ITEM_ID1 (4303)

                1  => "Required Item : Dagger",            // IDS_SKILL_TOOLTIP_NEED_ITEM_ID2 (4312)

                2  => "Required Item : Sword",             // IDS_SKILL_TOOLTIP_NEED_ITEM_ID3 (4313)

                3  => "Required Item : Ax",                // IDS_SKILL_TOOLTIP_NEED_ITEM_ID4 (4314)

                4  => "Required Item : Striking Weapon",   // IDS_SKILL_TOOLTIP_NEED_ITEM_ID5 (4315)

                5  => "Required Item : Spear",             // IDS_SKILL_TOOLTIP_NEED_ITEM_ID6 (4316)

                6  => "Required Item : Shield",            // IDS_SKILL_TOOLTIP_NEED_ITEM_ID7 (4317)

                7  => "Required Item : Bow",               // IDS_SKILL_TOOLTIP_NEED_ITEM_ID8 (4318)

                8  => "Required Item : Longbow",           // IDS_SKILL_TOOLTIP_NEED_ITEM_ID9 (4319)

                10 => "Required Item : Launcher",          // IDS_SKILL_TOOLTIP_NEED_ITEM_ID10 (4304)

                11 => "Required Item : Staff",             // IDS_SKILL_TOOLTIP_NEED_ITEM_ID11 (4305)

                12 => "Required Item : Arrow",             // IDS_SKILL_TOOLTIP_NEED_ITEM_ID12 (4306)

                13 => "Required Item : Javelin",           // IDS_SKILL_TOOLTIP_NEED_ITEM_ID13 (4307)

                21 => "Required Item : Warrior Armor",     // IDS_SKILL_TOOLTIP_NEED_ITEM_ID14 (4308)

                22 => "Required Item : Rogue Armor",       // IDS_SKILL_TOOLTIP_NEED_ITEM_ID15 (4309)

                23 => "Required Item : Magician Armor",    // IDS_SKILL_TOOLTIP_NEED_ITEM_ID16 (4310)

                24 => "Required Item : Priest Armor",      // IDS_SKILL_TOOLTIP_NEED_ITEM_ID17 (4311)

                _  => "No basic item"                      // IDS_SKILL_TOOLTIP_NEED_ITEM_NO (4328)

            };

        }

        /// <summary>

        /// C++ birebir: UISkillTreeDlg::InitIconUpdate (UISkillTreeDlg.cpp:1195-1304)

        /// + AddSkillToPage (1676-1710) + SetPageInIconRegion (1828-1870)

        ///

        /// Sabitler (GameDef.h:1257-1259):

        ///   MAX_SKILL_KIND_OF  = 5  (0=basic, 1-4=specialized tabs)

        ///   MAX_SKILL_PAGE_NUM = 7  (her tab'da 7 sayfa)

        ///   MAX_SKILL_IN_PAGE  = 6  (her sayfada 6 skill)

        ///

        /// Akış:

        ///   1. Tüm skill'leri class bazlı filtrele

        ///   2. iNeedSkill % 10 ile kategori belirle (0=basic, 5-8=tabs)

        ///   3. Her kategori için sayfa/slot'a yerleştir

        ///   4. Sadece aktif tab ve sayfadaki skill'leri göster

        ///   5. Her skill GetChildAreaByiOrder(UI_AREA_TYPE_SKILL_TREE, slotIndex) ile pozisyonlanır

        /// </summary>

        public void PopulateSkillTree(int[] skillIds)

        {

            _learnedSkillIds = skillIds;

            if (_uiSkillTree == null) return;

            Transform stRoot = _uiSkillTree.transform;

            var skillMgr = KOSkillTreeManager.Instance;

            if (skillMgr == null)

            {

                // Eski dinamik item'ları temizle

                foreach (var obj in _skillTreeListItems)

                    if (obj != null) Destroy(obj);

                _skillTreeListItems.Clear();

                PopulateSkillTreeFallback(skillIds, stRoot);

                return;

            }

            // KOSkillTreeManager henüz init edilmediyse, önce init et

            if (skillIds != null && skillIds.Length > 0)

                skillMgr.InitIconUpdate();

            // Eğer objeler zaten oluşturulmuşsa, sıfırdan GameObject oluşturma ve yerleştirme adımlarını tamamen atla!

            // Sadece aktif sayfanın nesnelerini SetActive(true) diğerlerini SetActive(false) yap.

            bool alreadyCreated = (_stSkillObjs != null && _stSkillObjs[0, 0, 0] != null);

            if (!alreadyCreated)

            {

                // Eski dinamik nesneleri temizle

                foreach (var obj in _skillTreeListItems)

                    if (obj != null) Destroy(obj);

                _skillTreeListItems.Clear();

                _stSkillObjs = new GameObject[ST_MAX_KIND, ST_MAX_PAGE, ST_MAX_SLOT];

                _stSkillIds = new int[ST_MAX_KIND, ST_MAX_PAGE, ST_MAX_SLOT];

                for (int a = 0; a < ST_MAX_KIND; a++)

                    for (int b = 0; b < ST_MAX_PAGE; b++)

                        for (int c = 0; c < ST_MAX_SLOT; c++)

                            _stSkillIds[a, b, c] = -1;

                // 480 kez hiyerarşide arama yapmamak için alanları 1 kez önbelleğe al!

                RectTransform[] cachedAreas = new RectTransform[ST_MAX_SLOT];

                for (int slot = 0; slot < ST_MAX_SLOT; slot++)

                {

                    cachedAreas[slot] = KOUIRenderer.FindChildAreaByiOrder(stRoot, 7, slot);

                }

                int totalCount = 0;

                for (int kindOf = 0; kindOf < ST_MAX_KIND; kindOf++)

                {

                    for (int page = 0; page < ST_MAX_PAGE; page++)

                    {

                        for (int slot = 0; slot < ST_MAX_SLOT; slot++)

                        {

                            var entry = skillMgr.SkillTree[kindOf, page, slot];

                            if (entry == null) continue;

                            int skillId = entry.SkillId;

                            _stSkillIds[kindOf, page, slot] = skillId;

                            var areaRT = cachedAreas[slot];

                            var itemObj = new GameObject($"Skill_{skillId}_{(entry.HasLevel ? "open" : "locked")}");

                            itemObj.transform.SetParent(stRoot, false);

                            var itemRT = itemObj.AddComponent<RectTransform>();

                            if (areaRT != null)

                            {

                                itemRT.anchorMin = areaRT.anchorMin;

                                itemRT.anchorMax = areaRT.anchorMax;

                                itemRT.offsetMin = areaRT.offsetMin;

                                itemRT.offsetMax = areaRT.offsetMax;

                            }

                            else

                            {

                                itemRT.anchorMin = new Vector2(0, 1);

                                itemRT.anchorMax = new Vector2(0, 1);

                                itemRT.pivot = new Vector2(0, 1);

                                float iconSize = 32f;

                                float gapX = 3f;

                                int col = slot % 6;

                                int row = slot / 6;

                                itemRT.anchoredPosition = new Vector2(8f + col * (iconSize + gapX), -200f - row * (iconSize + gapX));

                                itemRT.sizeDelta = new Vector2(iconSize, iconSize);

                            }

                            var img = itemObj.AddComponent<UnityEngine.UI.Image>();

                            if (entry.HasLevel)

                            {

                                Sprite icon = KOItemIconLoader.LoadSkillIcon(skillId);

                                if (icon != null)

                                {

                                    img.sprite = icon;

                                    img.raycastTarget = true;

                                }

                                else

                                {

                                    img.color = new Color(0.2f, 0.4f, 0.2f, 0.5f);

                                    img.raycastTarget = true;

                                }

                                Sprite dragIcon = KOItemIconLoader.LoadSkillIcon(skillId);

                                var dragDrop = itemObj.AddComponent<KOSkillDragDrop>();

                                dragDrop.SetSkillData(skillId, dragIcon, true);

                                int capturedId = skillId;

                                var btn = itemObj.AddComponent<Button>();

                                btn.transition = Selectable.Transition.None;

                                btn.onClick.AddListener(() => OnSkillIconClicked(capturedId));

                            }

                            else

                            {

                                Sprite enigmaIcon = KOItemIconLoader.LoadEnigmaIcon();

                                if (enigmaIcon != null)

                                {

                                    img.sprite = enigmaIcon;

                                    img.raycastTarget = true;

                                }

                                else

                                {

                                    img.color = new Color(0.3f, 0.3f, 0.3f, 0.6f);

                                    img.raycastTarget = true;

                                }

                                int capturedId = skillId;

                                var btn = itemObj.AddComponent<Button>();

                                btn.transition = Selectable.Transition.None;

                                btn.onClick.AddListener(() => OnSkillIconClicked(capturedId));

                            }

                            var borderObj = new GameObject("BorderFrame");

                            borderObj.transform.SetParent(itemObj.transform, false);

                            var borderImg = borderObj.AddComponent<UnityEngine.UI.Image>();

                            borderImg.sprite = GetSkillThemeRoundedRectSprite(entry.HasLevel ? "slot_border_premium" : "slot_border_locked", 36, 36, 0, Color.clear, entry.HasLevel ? new Color(0.55f, 0.45f, 0.20f, 0.9f) : new Color(0.35f, 0.35f, 0.35f, 0.7f), 1);

                            borderImg.raycastTarget = false;

                            var borderRT = borderObj.GetComponent<RectTransform>();

                            borderRT.anchorMin = Vector2.zero;

                            borderRT.anchorMax = Vector2.one;

                            borderRT.offsetMin = Vector2.zero;

                            borderRT.offsetMax = Vector2.zero;

                            _stSkillObjs[kindOf, page, slot] = itemObj;

                            _skillTreeListItems.Add(itemObj);

                            totalCount++;

                        }

                    }

                }

            }

            // C++ birebir: SetPageInIconRegion(_stCurrentKindOf, _stCurrentSkillPage)

            for (int k = 0; k < ST_MAX_KIND; k++)

                for (int p = 0; p < ST_MAX_PAGE; p++)

                    for (int s = 0; s < ST_MAX_SLOT; s++)

                    {

                        if (_stSkillObjs[k, p, s] != null)

                            _stSkillObjs[k, p, s].SetActive(k == _stCurrentKindOf && p == _stCurrentSkillPage);

                    }

            // Sayfa numarası

            if (_stPageText != null)

                _stPageText.text = (_stCurrentSkillPage + 1).ToString();

            // C++ birebir: UISkillTreeDlg.cpp:1877-1892 — skill adlarını güncelle

            UpdateSkillNameTexts(_stCurrentKindOf, _stCurrentSkillPage);

        }

        /// <summary>

        /// Fallback: KOSkillTreeManager yoksa sadece öğrenilmiş skill'leri göster.

        /// </summary>

        private void PopulateSkillTreeFallback(int[] skillIds, Transform stRoot)

        {

            if (skillIds == null || skillIds.Length == 0) return;

            int[] slotCounter = new int[ST_MAX_KIND];

            for (int i = 0; i < skillIds.Length; i++)

            {

                int skillId = skillIds[i];

                int kindOf = 0;

                var skillData = KOImport.SkillTableParser.Find(skillId);

                if (skillData != null)

                {

                    int iModulo = skillData.NeedSkill % 10;

                    switch (iModulo)

                    {

                        case 0: kindOf = 0; break;

                        case 5: kindOf = 1; break;

                        case 6: kindOf = 2; break;

                        case 7: kindOf = 3; break;

                        case 8: kindOf = 4; break;

                    }

                }

                int totalInKind = slotCounter[kindOf];

                int page = totalInKind / ST_MAX_SLOT;

                int slot = totalInKind % ST_MAX_SLOT;

                if (page >= ST_MAX_PAGE) continue;

                _stSkillIds[kindOf, page, slot] = skillId;

                slotCounter[kindOf]++;

                var areaRT = KOUIRenderer.FindChildAreaByiOrder(stRoot, 7, slot);

                var itemObj = new GameObject($"Skill_{skillId}");

                itemObj.transform.SetParent(stRoot, false);

                var itemRT = itemObj.AddComponent<RectTransform>();

                if (areaRT != null)

                {

                    itemRT.anchorMin = areaRT.anchorMin;

                    itemRT.anchorMax = areaRT.anchorMax;

                    itemRT.offsetMin = areaRT.offsetMin;

                    itemRT.offsetMax = areaRT.offsetMax;

                }

                else

                {

                    itemRT.anchorMin = new Vector2(0, 1);

                    itemRT.anchorMax = new Vector2(0, 1);

                    itemRT.pivot = new Vector2(0, 1);

                    float iconSize = 32f;

                    float gapX = 3f;

                    int col = slot % 6;

                    int row = slot / 6;

                    itemRT.anchoredPosition = new Vector2(

                        8f + col * (iconSize + gapX),

                        -200f - row * (iconSize + gapX));

                    itemRT.sizeDelta = new Vector2(iconSize, iconSize);

                }

                Sprite icon = KOItemIconLoader.LoadSkillIcon(skillId);

                var img = itemObj.AddComponent<UnityEngine.UI.Image>();

                if (icon != null)

                {

                    img.sprite = icon;

                    img.raycastTarget = true;

                }

                else

                {

                    img.color = new Color(0.2f, 0.4f, 0.2f, 0.5f);

                    img.raycastTarget = true;

                }

                var dragDrop = itemObj.AddComponent<KOSkillDragDrop>();

                dragDrop.SetSkillData(skillId, icon, true);

                        var borderObj = new GameObject("BorderFrame");

                        borderObj.transform.SetParent(itemObj.transform, false);

                        var borderImg = borderObj.AddComponent<UnityEngine.UI.Image>();

                        borderImg.sprite = GetSkillThemeRoundedRectSprite("slot_border_premium", 36, 36, 0, Color.clear, new Color(0.55f, 0.45f, 0.20f, 0.9f), 1);

                        borderImg.raycastTarget = false;

                        var borderRT = borderObj.GetComponent<RectTransform>();

                        borderRT.anchorMin = Vector2.zero;

                        borderRT.anchorMax = Vector2.one;

                        borderRT.offsetMin = Vector2.zero;

                        borderRT.offsetMax = Vector2.zero;

                        _stSkillObjs[kindOf, page, slot] = itemObj;

                        _skillTreeListItems.Add(itemObj);

            }

            for (int k = 0; k < ST_MAX_KIND; k++)

                for (int p = 0; p < ST_MAX_PAGE; p++)

                    for (int s = 0; s < ST_MAX_SLOT; s++)

                    {

                        if (_stSkillObjs[k, p, s] != null)

                            _stSkillObjs[k, p, s].SetActive(

                                k == _stCurrentKindOf && p == _stCurrentSkillPage);

                    }

            if (_stPageText != null)

                _stPageText.text = (_stCurrentSkillPage + 1).ToString();

        }

