        /// <summary>

        /// Open-KO birebir: CUINPCEvent::Open (UINPCEvent.cpp:97-129)

        /// e_NpcEvent: 0 = NPC_EVENT_ITEM_TRADE, 1 = NPC_EVENT_TRADE_REPAIR

        /// </summary>

        public void ShowNpcEvent(int tradeId, byte eventType)

        {

            int npcTemplateId = EntropyOnline.World.KONpcEventHandler.LastInteractedNpcTemplateId;

            long npcInstanceId = EntropyOnline.World.KONpcEventHandler.LastInteractedNpcInstanceId;

            int npcType = 0;

            var em = EntropyOnline.World.EntityManager.Instance;

            if (em != null)

            {

                var entity = em.GetEntityByInstanceId(npcInstanceId);

                if (entity != null)

                {

                    npcType = entity.ActType;

                }

            }

            if (npcType == 0 && npcTemplateId > 0 && EntropyOnline.World.WorldBuilder.Instance != null)

            {

                npcType = EntropyOnline.World.WorldBuilder.Instance.GetNpcType(npcTemplateId);

            }

            // Alım-satım NPC'lerinde (Type 21/22) diyalog panelini tamamen bypass edip dükkanı açıyoruz.

            if (npcType == 21 || npcType == 22)

            {

                DoCommercialTransaction(tradeId);

                return;

            }

            // UINPCEvent.cpp:99-101 birebir

            _npcEventTradeId = tradeId;

            if (_uiNpcEvent == null)

                CreateNpcEventPanel();

            if (_uiNpcEvent == null) return; // UIF yüklenemedi

            // UINPCEvent.cpp:99 — SetVisible(true)

            _uiNpcEvent.SetActive(true);

            // UINPCEvent.cpp:49-51 — GetChildByID kontrollerini bul

            var titleText = KOUIRenderer.FindChildText(_uiNpcEvent.transform, "Text_Title");

            var btnRepairTr = KOUIRenderer.FindChildByID(_uiNpcEvent.transform, "Btn_Repair");

            var textRepairTr = KOUIRenderer.FindChildByID(_uiNpcEvent.transform, "Text_Repair");

            // UINPCEvent.cpp:104-128 — switch(eNpcEvent)

            switch (eventType)

            {

                case 0: // NPC_EVENT_ITEM_TRADE — UINPCEvent.cpp:106-113

                    if (titleText != null) titleText.text = "Trade";

                    // UINPCEvent.cpp:111 — m_pBtn_Repair->SetVisible(false)

                    if (btnRepairTr != null) btnRepairTr.gameObject.SetActive(false);

                    // UINPCEvent.cpp:112 — m_pText_Repair->SetVisible(false)

                    if (textRepairTr != null) textRepairTr.gameObject.SetActive(false);

                    break;

                case 1: // NPC_EVENT_TRADE_REPAIR — UINPCEvent.cpp:116-123

                    if (titleText != null) titleText.text = "Exchange / Repair";

                    // UINPCEvent.cpp:121 — m_pBtn_Repair->SetVisible(true)

                    if (btnRepairTr != null) btnRepairTr.gameObject.SetActive(true);

                    // UINPCEvent.cpp:122 — m_pText_Repair->SetVisible(true)

                    if (textRepairTr != null) textRepairTr.gameObject.SetActive(true);

                    break;

            }

        }

