        private void HandleClassChange_KO(byte[] rawData)

        {

            var r = new KOPacketReader(rawData);

            byte subOpcode = r.ReadByte();

            switch (subOpcode)

            {

                case 0x01: // CLASS_CHANGE_STATUS_REQ

                    ShowNpcChange();

                    break;

                case 0x03: // CLASS_RESET_STAT_REQ

                    MsgRecv_AllPointInit(r);

                    break;

                case 0x04: // CLASS_RESET_SKILL_REQ

                    MsgRecv_SkillPointInit(r);

                    break;

                case 0x05: // CLASS_RESET_COST_REQ

                    {

                        int iGold = r.ReadInt32();

                        bool bAllPoint = false;

                        if (_uiNpcChange != null && _uiNpcChange.activeSelf)

                        {

                            var npcChangeScript = _uiNpcChange.GetComponent<KONpcChangeEvent>();

                            if (npcChangeScript != null)

                            {

                                bAllPoint = npcChangeScript.GetSendedAllPoint();

                            }

                        }

                        ShowPointInit(bAllPoint, iGold);

                    }

                    break;

                case 0x06: // CLASS_PROMOTION_REQ

                    {

                        short newClass = r.ReadInt16();

                        short socketId = r.ReadInt16();

                        var gm = GameManager.Instance;

                        if (gm != null && socketId == gm.CharacterId)

                        {

                            gm.CharClass = (byte)newClass;

                            RefreshSkillTreeUI();

                        }

                    }

                    break;

                default:

                    break;

            }

        }

        private void MsgRecv_AllPointInit(KOPacketReader r)

        {

            byte bType = r.ReadByte();

            int dwGold = r.ReadInt32();

            string szMsg;

            switch (bType)

            {

                case 0x00: // Yetersiz noah

                    szMsg = Services.StringTableService.Get(6086).Replace("%d", dwGold.ToString("N0"));

                    AddMsgOutput(szMsg, D3DColorToUnity(0xffff3b3b));

                    break;

                case 0x01: // Başarılı

                    var gm = GameManager.Instance;

                    if (gm != null)

                    {

                        gm.StatStr = r.ReadInt16();

                        gm.StatSta = r.ReadInt16();

                        gm.StatDex = r.ReadInt16();

                        gm.StatInt = r.ReadInt16();

                        gm.StatCha = r.ReadInt16();

                        gm.MaxHP = r.ReadInt16();

                        gm.MaxMP = r.ReadInt16();

                        gm.TotalHit = r.ReadInt16();

                        gm.MaxWeight = (short)r.ReadUInt16();

                        gm.StatPoints = r.ReadInt16();

                        gm.Gold = dwGold;

                        long expMax = EntropyOnline.Shared.LevelExpTable.GetExpForLevel(gm.Level);

                        UpdateCharacterInfo(

                            gm.CharacterName, gm.Level, gm.StatStr, gm.StatSta, gm.StatDex, gm.StatInt, gm.StatCha,

                            gm.StatPoints, gm.CurrentHp, gm.MaxHp, gm.CurrentMp, gm.MaxMp,

                            gm.Experience, expMax, gm.SkillPoints, gm.Loyalty, gm.LoyaltyMonthly

                        );

                        UpdateGold(dwGold);

                    }

                    break;

                case 0x02: // Sıfırlanacak puan yok

                    szMsg = Services.StringTableService.Get(6087);

                    AddMsgOutput(szMsg, D3DColorToUnity(0xffff3b3b));

                    break;

                default:

                    break;

            }

        }

        private void MsgRecv_SkillPointInit(KOPacketReader r)

        {

            byte bType = r.ReadByte();

            int dwGold = r.ReadInt32();

            string szMsg;

            switch (bType)

            {

                case 0x00: // Yetersiz noah

                    szMsg = Services.StringTableService.Get(6086).Replace("%d", dwGold.ToString("N0"));

                    AddMsgOutput(szMsg, D3DColorToUnity(0xffff3b3b));

                    break;

                case 0x01: // Başarılı

                    var gm = GameManager.Instance;

                    if (gm != null)

                    {

                        gm.Gold = dwGold;

                        int serbestPuan = r.ReadByte();

                        int[] skillInfo = new int[9];

                        skillInfo[0] = serbestPuan;

                        for (int i = 1; i < 9; i++)

                            skillInfo[i] = 0;

                        if (KOSkillTreeManager.Instance != null)

                        {

                            KOSkillTreeManager.Instance.SetSkillInfo(skillInfo);

                        }

                        // GameManager'daki öğrenilmiş skill listesini güncelle (sadece basic/kilit açma skilleri kalacak)

                        var learnedSkills = GetLearnedSkillIdsFromManager();

                        if (learnedSkills == null) learnedSkills = new int[0];

                        gm.LearnedSkills = learnedSkills;

                        // MobileSkillBar slotlarını güncelle/temizle (tüm sayfaları tamamen boşalt)
                        if (MobileSkillBar.Instance != null)
                        {
                            MobileSkillBar.Instance.ClearAllSkills();
                        }

                        long expMax = EntropyOnline.Shared.LevelExpTable.GetExpForLevel(gm.Level);

                        UpdateCharacterInfo(

                            gm.CharacterName, gm.Level, gm.StatStr, gm.StatSta, gm.StatDex, gm.StatInt, gm.StatCha,

                            gm.StatPoints, gm.CurrentHp, gm.MaxHp, gm.CurrentMp, gm.MaxMp,

                            gm.Experience, expMax, gm.SkillPoints, gm.Loyalty, gm.LoyaltyMonthly

                        );

                        UpdateGold(dwGold);

                        // Anlık olarak SkillTree paneline yansımasını sağla (Kapatıp açmaya gerek kalmaz)

                        RefreshSkillTreeUI();

                    }

                    break;

                case 0x02: // Sıfırlanacak puan yok

                    szMsg = Services.StringTableService.Get(6087);

                    AddMsgOutput(szMsg, D3DColorToUnity(0xffff3b3b));

                    break;

                default:

                    break;

            }

        }

