        ///   m_pText_Repair = GetChildByID("Text_Repair")

        ///   m_pText_Title  = GetChildByID("Text_Title")

        /// UINPCEvent.cpp:56-94 — ReceiveMessage:

        ///   Btn_Sale → Close() + DoCommercialTransaction(m_iTradeID)

        ///   Btn_Repair → Close() + m_pUIInventory->Open(INV_STATE_REPAIR)

        ///   btn_close → Close()

        /// </summary>

        private void CreateNpcEventPanel()

        {

            // GameProcMain.cpp:4011-4012 birebir:

            // m_pUINpcEvent->LoadFromFile(pTbl->szNpcEvent);

            _uiNpcEvent = LoadUIPanel("UI_US", "co_smith_us.uif");

            if (_uiNpcEvent == null)

            {

                Debug.LogError("[KOUIMGR] co_smith_us.uif yüklenemedi!");

                return;

            }

            // GameProcMain.cpp:4013 birebir:

            // m_pUINpcEvent->SetVisibleWithNoSound(false);

            _uiNpcEvent.SetActive(false);

            // GameProcMain.cpp:4014-4018: pozisyon ayarı — ekran ortası

            SetPanelPosCenter(_uiNpcEvent);

            // UINPCEvent.cpp:60-72 birebir — Btn_Sale click handler

            var btnSale = KOUIRenderer.FindChildButton(_uiNpcEvent.transform, "Btn_Sale");

            if (btnSale != null)

            {

                btnSale.onClick.AddListener(() =>

                {

                    // UINPCEvent.cpp:62-63 — personal trade kontrolü

                    // C++ birebir: if(s_pPlayer->m_bPerTrade) return;

                    var tradeMgr = EntropyOnline.Trade.KOTradeManager.Instance;

                    if (tradeMgr != null && tradeMgr.IsInTrade)

                    {

                        return;

                    }

                    // UINPCEvent.cpp:65 — Close()

                    int tid = _npcEventTradeId;

                    CloseNpcEvent();

                    // UINPCEvent.cpp:72 — DoCommercialTransaction(m_iTradeID)

                    // C++ birebir: GameProcMain.cpp:4367-4384

                    // Sunucuya paket GÖNDERILMEZ — trade paneli lokal olarak açılır!

                    DoCommercialTransaction(tid);

                });

            }

            // UINPCEvent.cpp:75-88 birebir — Btn_Repair click handler

            var btnRepair = KOUIRenderer.FindChildButton(_uiNpcEvent.transform, "Btn_Repair");

            if (btnRepair != null)

            {

                btnRepair.onClick.AddListener(() =>

                {

                    // UINPCEvent.cpp:80 — Close()

                    CloseNpcEvent();

                    // UINPCEvent.cpp:87 — m_pUIInventory->Open(INV_STATE_REPAIR)

                    // TODO: INV_STATE_REPAIR — envanter tamir modu

                });

            }

            // UINPCEvent.cpp:90-91 birebir — btn_close click handler

            var btnClose = KOUIRenderer.FindChildButton(_uiNpcEvent.transform, "btn_close");

            if (btnClose != null)

            {

                btnClose.onClick.AddListener(CloseNpcEvent);

            }

        }

