        /// <summary>

        /// Open-KO birebir: CUIQuestTalk::Open (UIQuestTalk.cpp:36-66)

        /// Packet: [eventIdUp: int] [eventIdOk: int] [msg0..msg7: int]

        /// msgId → s_pTbl_QuestTalk.Find(msgId) → szTalk

        /// </summary>

        public void ShowQuestTalk(int eventIdUp, int eventIdOk, int[] messageIds)

        {

            if (_uiQuestTalk == null)

                CreateQuestTalkPanel();

            OnPanelOpened(_uiQuestTalk);

            // UIQuestTalk.cpp:38-39

            _questTalkNumPages = 0;

            _questTalkCurPage = 0;

            _questTalkPages = new string[10];

            // UIQuestTalk.cpp:45-57 — msgId → talk text lookup

            for (int i = 0; i < messageIds.Length && i < 10; i++)

            {

                if (messageIds[i] <= 0) continue;

                string talk = KOImport.QuestTableParser.FindTalk(messageIds[i]);

                if (!string.IsNullOrEmpty(talk))

                {

                    // UIQuestTalk.cpp:54 — ConvertPipesToNewlines

                    _questTalkPages[_questTalkNumPages] = talk.Replace('|', '\n');

                    _questTalkNumPages++;

                }

            }

            if (_questTalkNumPages == 0)

            {

                Debug.LogWarning("[QUEST] ShowQuestTalk: hiç metin bulunamadı");

                return;

            }

            // UIQuestTalk.cpp:59

            _questTalkText.text = _questTalkPages[0];

            _uiQuestTalk.SetActive(true);

            // C++ birebir: GameProcMain.cpp:4179-4182

            // iX = (iW - (rc.right - rc.left)) / 2; iY = (iH - (rc.bottom - rc.top)) / 2;

            SetPanelPosCenter(_uiQuestTalk);

        }

        /// <summary>

        /// co_QuestTalk_us.uif'i yükle ve bind et.

        /// C++ UIQuestTalk::Load (UIQuestTalk.cpp:103-131):

        ///   Text_Talk, btn_Ok_center, btn_close, btn_Next, btn_Pre, scroll

        /// C++ UIQuestTalk::ReceiveMessage (UIQuestTalk.cpp:68-100):

        ///   btn_Ok_center → next page / close

        ///   btn_close → close

        /// </summary>

        private void CreateQuestTalkPanel()

        {

            _uiQuestTalk = LoadUIPanel("UI_US", "co_QuestTalk_us.uif");

            if (_uiQuestTalk == null)

            {

                Debug.LogError("[KOUIMGR] co_QuestTalk_us.uif yüklenemedi!");

                return;

            }

            Transform root = _uiQuestTalk.transform;

            // C++ UIQuestTalk.cpp:108 — m_pTextTalk = GetChildByID<CN3UIString>("Text_Talk")

            _questTalkText = KOUIRenderer.FindChildText(root, "Text_Talk");

            if (_questTalkText != null)

            {

                // C++ birebir: CN3UIString region sınırlarına clip — word-wrap + dikey kırpma

                _questTalkText.horizontalOverflow = HorizontalWrapMode.Wrap;

                _questTalkText.verticalOverflow = VerticalWrapMode.Truncate;

            }

            // C++ UIQuestTalk.cpp:109 — btn_Ok_center → next page veya close

            var btnOk = KOUIRenderer.FindChildButton(root, "btn_Ok_center");

            if (btnOk != null)

            {

                btnOk.onClick.AddListener(() =>

                {

                    // C++ UIQuestTalk.cpp:74-84 birebir

                    _questTalkCurPage++;

                    if (_questTalkCurPage >= _questTalkNumPages)

                    {

                        _questTalkCurPage = 0;

                        _uiQuestTalk.SetActive(false);

                    }

                    else

                    {

                        if (_questTalkText != null)

                            _questTalkText.text = _questTalkPages[_questTalkCurPage];

                    }

                });

            }

            // C++ UIQuestTalk.cpp:112 — btn_close → close

            var btnClose = KOUIRenderer.FindChildButton(root, "btn_close");

            if (btnClose != null)

            {

                btnClose.onClick.AddListener(() => _uiQuestTalk.SetActive(false));

            }

            // C++ UIQuestTalk.cpp:113-129 — btn_UpperEvent, btn_Next, btn_Pre → görünmez başlat

            var btnUpperEvent = KOUIRenderer.FindChildButton(root, "btn_UpperEvent");

            if (btnUpperEvent != null) btnUpperEvent.gameObject.SetActive(false);

            var btnNext = KOUIRenderer.FindChildButton(root, "btn_Next");

            if (btnNext != null) btnNext.gameObject.SetActive(false);

            var btnOkRight = KOUIRenderer.FindChildButton(root, "btn_Ok_right");

            if (btnOkRight != null) btnOkRight.gameObject.SetActive(false);

            var btnPre = KOUIRenderer.FindChildButton(root, "btn_Pre");

            if (btnPre != null) btnPre.gameObject.SetActive(false);

            _uiQuestTalk.SetActive(false);

        }

