        /// <summary>

        /// Open-KO birebir: CUIQuestMenu::Open (UIQuestMenu.cpp:149-254)

        /// Packet: [npcId: short] [talkId: int] [menuId0..menuId9: int]

        /// talkId → s_pTbl_QuestTalk.Find(talkId) → szTitle

        /// menuId → s_pTbl_QuestMenu.Find(menuId) → szMenu (buton metni)

        /// </summary>

        public void ShowQuestMenu(short npcId, int talkId, int[] menuTextIds)

        {

            int npcTemplateId = EntropyOnline.World.KONpcEventHandler.LastInteractedNpcTemplateId;

            long npcInstanceId = EntropyOnline.World.KONpcEventHandler.LastInteractedNpcInstanceId;

            int npcType = 0;

            var em = EntropyOnline.World.EntityManager.Instance;

            if (em != null)

            {

                var entity = em.GetEntityByInstanceId(npcInstanceId);

                if (entity != null)

                {

                    npcType = entity.ActType;

                }

            }

            if (npcType == 0 && npcTemplateId > 0 && EntropyOnline.World.WorldBuilder.Instance != null)

            {

                npcType = EntropyOnline.World.WorldBuilder.Instance.GetNpcType(npcTemplateId);

            }

            // Alım-satım NPC'lerinde (Type 21/22) Quest Seçim Menüsü çıkarsa, 

            // 0. seçeneği (Alışveriş / I want to trade) otomatik seçip sunucuya gönderiyoruz.

            if (npcType == 21 || npcType == 22)

            {

                SendSelectMenu(0);

                return;

            }

            // Miraselth / Proconsul ya da Gem/Chest Kirdirma secenekleri iceren Quest Menusu cikarsa,

            // Ozel kutu/gem kirdirma panelini (ShowGemChestExchange) aciyoruz.

            // Dynamic template check using current npcId from EntityManager

            var currentNpcEntity = EntropyOnline.World.EntityManager.Instance?.GetEntityByInstanceId(npcId);

            int resolvedNpcTemplateId = currentNpcEntity != null ? currentNpcEntity.NpcId : 0;

            if (resolvedNpcTemplateId == 2050 || npcTemplateId == 2050)

            {

                ShowGemChestExchange(true, npcId, talkId, menuTextIds);

                return;

            }

            // Magic Anvil (Type 24) Quest Seçim Menüsü çıkarsa,

            // Özel arayüz seçim panelini (ShowUpgradeSelect) açıyoruz.

            if (npcType == 24)

            {

                _anvilOpenedFromQuestMenu = true;

                ShowUpgradeSelect(true, npcId);

                return;

            }

            if (_uiQuestMenu == null)

                CreateQuestMenuPanel();

            if (_uiQuestMenu == null) return;

            OnPanelOpened(_uiQuestMenu);

            // UIQuestMenu.cpp:151 — InitBase()

            // C++ birebir satır 54: SetPos(0, 0) — pozisyon sıfırlanır

            // C++ birebir satır 56-71: eski klonlar silinir

            foreach (var btn in _questMenuButtons)

                if (btn != null) Destroy(btn);

            _questMenuButtons.Clear();

            // UIQuestMenu.cpp:153-154 — template null kontrolü

            if (_questMenuTextSample == null || _questMenuImgBtnSample == null ||

                _questMenuImgMenuSample == null || _questMenuBtnSample == null)

            {

                Debug.LogError("[QUEST] ShowQuestMenu: template node'lar bulunamadı!");

                return;

            }

            // UIQuestMenu.cpp:160-166 — NPC name

            // TODO: NPC adı lookup (şimdilik boş)

            // UIQuestMenu.cpp:169-177 — title lookup

            string title = KOImport.QuestTableParser.FindTalk(talkId);

            if (string.IsNullOrEmpty(title))

            {

                Debug.LogWarning($"[QUEST] ShowQuestMenu: talkId={talkId} bulunamadı");

                return;

            }

            // UIQuestMenu.cpp:176 — ConvertPipesToNewlines

            if (_questMenuTitle != null)

                _questMenuTitle.text = title.Replace('|', '\n');

            // UIQuestMenu.cpp:179-192 — menü metinlerini topla

            int menuCount = 0;

            string[] menuTexts = new string[10];

            for (int j = 0; j < menuTextIds.Length && j < 10; j++)

            {

                if (menuTextIds[j] <= 0) continue;

                string menuText = KOImport.QuestTableParser.FindMenu(menuTextIds[j]);

                if (!string.IsNullOrEmpty(menuText))

                    menuTexts[j] = menuText;

                menuCount++;

            }

            if (menuCount == 0)

            {

                Debug.LogWarning("[QUEST] ShowQuestMenu: menü butonları bulunamadı");

                return;

            }

            // C++ birebir: InitBase — panel boyutunu ve img_Bottom'u orijinale geri yükle

            var panelRTRestore = _uiQuestMenu.GetComponent<RectTransform>();

            if (panelRTRestore != null && _questMenuOrigPanelHeight > 0)

                panelRTRestore.sizeDelta = new Vector2(panelRTRestore.sizeDelta.x, _questMenuOrigPanelHeight);

            if (_questMenuImgBottom != null)

            {

                var bottomRTRestore = _questMenuImgBottom.GetComponent<RectTransform>();

                if (bottomRTRestore != null)

                    bottomRTRestore.anchoredPosition = _questMenuImgBottomOrigPos;

            }

            // UIQuestMenu.cpp:201 — SetVisible(true)

            _uiQuestMenu.SetActive(true);

            // UIQuestMenu.cpp:203-207 — iIH = m_pImageMenu->GetRegion().Height()

            // Kaydedilen template pixel yüksekliğini kullan (ConvertAllChildrenToFixed sonrası)

            float iIH = _tmplImgMenuSize.y > 0.5f ? _tmplImgMenuSize.y : 24f;

            // C++ birebir satır 209-238: Her menü item'ı için şablonları klonla

            int cloneIndex = 0;

            for (int i = 0; i < menuCount && i < 10; i++)

            {

                if (string.IsNullOrEmpty(menuTexts[i])) continue;

                int menuIndex = i;

                float moveDown = cloneIndex * iIH;

                // *(m_pTextMenuImgBk[i]) = *m_pImageMenu; + MoveOffset(0, i*iIH)

                var imgBk = Instantiate(_questMenuImgMenuSample, _uiQuestMenu.transform);

                imgBk.name = $"img_menu_{i}";

                imgBk.SetActive(true);

                SetClonePosition(imgBk, _tmplImgMenuPos, _tmplImgMenuSize, moveDown);

                _questMenuButtons.Add(imgBk);

                // *(m_pTextMenuImg[i]) = *m_pImageBtn; + MoveOffset(0, i*iIH)

                var imgBtn = Instantiate(_questMenuImgBtnSample, _uiQuestMenu.transform);

                imgBtn.name = $"img_button_menu_{i}";

                imgBtn.SetActive(true);

                SetClonePosition(imgBtn, _tmplImgBtnPos, _tmplImgBtnSize, moveDown);

                _questMenuButtons.Add(imgBtn);

                // *(m_pTextMenuBtn[i]) = *m_pBtnMenu; + MoveOffset(0, i*iIH)

                var btnClone = Instantiate(_questMenuBtnSample, _uiQuestMenu.transform);

                btnClone.name = $"btn_menu_{i}";

                btnClone.SetActive(true);

                SetClonePosition(btnClone, _tmplBtnMenuPos, _tmplBtnMenuSize, moveDown);

                var btn = btnClone.GetComponent<Button>();

                if (btn == null) btn = btnClone.AddComponent<Button>();

                btn.onClick.RemoveAllListeners();

                btn.onClick.AddListener(() =>

                {

                    SendSelectMenu((byte)menuIndex);

                    _uiQuestMenu.SetActive(false);

                });

                _questMenuButtons.Add(btnClone);

                // *(m_pTextMenu[i]) = *m_pTextSample; + MoveOffset(0, i*iIH)

                var txtClone = Instantiate(_questMenuTextSample, _uiQuestMenu.transform);

                txtClone.name = $"Text_Menu_{i}";

                txtClone.SetActive(true);

                SetClonePosition(txtClone, _tmplTextMenuPos, _tmplTextMenuSize, moveDown);

                var txtComp = txtClone.GetComponentInChildren<Text>();

                if (txtComp != null) txtComp.text = menuTexts[i];

                _questMenuButtons.Add(txtClone);

                cloneIndex++;

            }

            // UIQuestMenu.cpp:240-241 — img_Bottom pozisyonunu güncelle

            // C++ birebir: m_pImageBottom->SetPos(0, m_pTextMenuImgBk[m_iMenuCnt-1]->GetRegion().bottom)

            // Son item'ın bottom'u = template_bottom + (numItems-1) * iIH

            // img_Bottom offset from original = (numItems-1) * iIH

            if (_questMenuImgBottom != null && cloneIndex > 0)

            {

                var bottomRT = _questMenuImgBottom.GetComponent<RectTransform>();

                if (bottomRT != null)

                {

                    float imgBottomOffset = (cloneIndex - 1) * iIH;

                    bottomRT.anchoredPosition = new Vector2(

                        _questMenuImgBottomOrigPos.x,

                        _questMenuImgBottomOrigPos.y - imgBottomOffset);

                }

            }

            // UIQuestMenu.cpp:247-249 — C++ birebir: panel bottom = img_Bottom bottom

            // rcText = GetRegion(); rcText.bottom = m_pImageBottom->GetRegion().bottom; SetRegion(rcText);

            var panelRT = _uiQuestMenu.GetComponent<RectTransform>();

            if (panelRT != null && _questMenuImgBottom != null)

            {

                var bottomRT = _questMenuImgBottom.GetComponent<RectTransform>();

                if (bottomRT != null)

                {

                    // img_Bottom: anchor(0,1) pivot(0,1), anchoredPosition = (x, -topFromTop)

                    // bottom edge (from panel top) = -anchoredPosition.y + height

                    float imgBottomEdge = -bottomRT.anchoredPosition.y + bottomRT.sizeDelta.y;

                    panelRT.sizeDelta = new Vector2(panelRT.sizeDelta.x, imgBottomEdge);

                }

            }

            // UIQuestMenu.cpp:251-253 — ekran ortasına konumlandır

            // C++ birebir: SetPos((iWidth - w) / 2, (iHeight - h) / 2)

            SetPanelPosCenter(_uiQuestMenu);

        }

        /// <summary>

        /// Open-KO birebir: CUIQuestMenu::MsgSend_SelectMenu (UIQuestMenu.cpp:139-147)

        /// WIZ_SELECT_MSG + byte(index) → sunucuya seçim bildir

        /// </summary>

        private void SendSelectMenu(byte index)

        {

            var netMgr = KONetworkManager.Instance;

            if (netMgr != null)

            {

                using var pkt = new KOPacketWriter(WizOpcode.WIZ_SELECT_MSG);

                pkt.WriteByte(index);

                netMgr.SendPacket(pkt);

            }

        }

        /// <summary>

        /// co_QuestMenu_us.uif'i yükle ve bind et.

        /// C++ UIQuestMenu::Load (UIQuestMenu.cpp:74-102) birebir:

        ///   Text_Title, Text_Npcname, btn_close, scroll

        ///   Text_Menu, btn_menu, img_button_menu, img_menu → RemoveChild → template

        /// </summary>

        private void CreateQuestMenuPanel()

        {

            _uiQuestMenu = LoadUIPanel("UI_US", "co_QuestMenu_us.uif");

            if (_uiQuestMenu == null)

            {

                Debug.LogError("[KOUIMGR] co_QuestMenu_us.uif yüklenemedi!");

                return;

            }

            Transform root = _uiQuestMenu.transform;

            // Prefab'dan yüklendiyse zaten fixed anchor (0,1) — ConvertAllChildrenToFixed gereksiz.

            // Runtime fallback (UIF parse) durumunda stretch anchor olur — o zaman çevir.

            bool isPrefab = Resources.Load<GameObject>(

                $"KOPrefabs/UI/{Path.GetFileNameWithoutExtension("co_QuestMenu_us.uif")}") != null;

            if (!isPrefab)

                ConvertAllChildrenToFixed(_uiQuestMenu);

            // Orijinal panel yüksekliğini sakla (fixed dönüşümden sonra değişmez)

            {

                var prt = _uiQuestMenu.GetComponent<RectTransform>();

                if (prt != null) _questMenuOrigPanelHeight = prt.sizeDelta.y;

            }

            // C++ UIQuestMenu.cpp:80 — m_pTextTitle

            _questMenuTitle = KOUIRenderer.FindChildText(root, "Text_Title");

            // C++ UIQuestMenu.cpp:83 — m_pStrNpcName

            _questMenuNpcName = KOUIRenderer.FindChildText(root, "Text_Npcname");

            // C++ UIQuestMenu.cpp:82 — btn_close

            var btnClose = KOUIRenderer.FindChildButton(root, "btn_close");

            if (btnClose != null)

                btnClose.onClick.AddListener(() => _uiQuestMenu.SetActive(false));

            // C++ UIQuestMenu.cpp:91 — m_pImageBottom (statik, çıkarılmaz)

            _questMenuImgBottom = KOUIRenderer.FindChildByID(root, "img_Bottom")?.gameObject;

            if (_questMenuImgBottom != null)

            {

                var bottomRT = _questMenuImgBottom.GetComponent<RectTransform>();

                if (bottomRT != null)

                    _questMenuImgBottomOrigPos = bottomRT.anchoredPosition;

            }

            // === Template'ları çıkar (C++ RemoveChild birebir) ===

            // Her template'ın FIXED ANCHOR pozisyonunu kaydet, sonra çıkar.

            // SetParent(null) anchoredPosition'ı bozar ama biz kaydettik.

            // C++ satır 79,97: Text_Menu → template

            _questMenuTextSample = KOUIRenderer.FindChildByID(root, "Text_Menu")?.gameObject;

            if (_questMenuTextSample != null)

            {

                var rt = _questMenuTextSample.GetComponent<RectTransform>();

                _tmplTextMenuPos = rt.anchoredPosition;

                _tmplTextMenuSize = rt.sizeDelta;

                _questMenuTextSample.SetActive(false);

            }

            // C++ satır 85,98: btn_menu → template

            _questMenuBtnSample = KOUIRenderer.FindChildByID(root, "btn_menu")?.gameObject;

            if (_questMenuBtnSample != null)

            {

                var rt = _questMenuBtnSample.GetComponent<RectTransform>();

                _tmplBtnMenuPos = rt.anchoredPosition;

                _tmplBtnMenuSize = rt.sizeDelta;

                _questMenuBtnSample.SetActive(false);

            }

            // C++ satır 88,99: img_button_menu → template

            _questMenuImgBtnSample = KOUIRenderer.FindChildByID(root, "img_button_menu")?.gameObject;

            if (_questMenuImgBtnSample != null)

            {

                var rt = _questMenuImgBtnSample.GetComponent<RectTransform>();

                _tmplImgBtnPos = rt.anchoredPosition;

                _tmplImgBtnSize = rt.sizeDelta;

                _questMenuImgBtnSample.SetActive(false);

            }

            // C++ satır 94,100: img_menu → template

            _questMenuImgMenuSample = KOUIRenderer.FindChildByID(root, "img_menu")?.gameObject;

            if (_questMenuImgMenuSample != null)

            {

                var rt = _questMenuImgMenuSample.GetComponent<RectTransform>();

                _tmplImgMenuPos = rt.anchoredPosition;

                _tmplImgMenuSize = rt.sizeDelta;

                _questMenuImgMenuSample.SetActive(false);

            }

            _uiQuestMenu.SetActive(false);

            // Debug: Template boyutlarını logla

            var panelRT_dbg = _uiQuestMenu.GetComponent<RectTransform>();

            // img_menu template'ın RawImage'ı var mı?

            if (_questMenuImgMenuSample != null)

            {

                var ri = _questMenuImgMenuSample.GetComponent<RawImage>();

            }

        }

        /// <summary>

        /// Open-KO birebir: GameProcMain.cpp:4367-4384 — DoCommercialTransaction

        /// Trade panelini lokal olarak açar. Sunucuya paket GÖNDERİLMEZ.

        /// C++ birebir: UITransactionDlg::EnterTransactionState (satır 305-369)

        /// Item_Org_us.tbl'den bySellGroup filtreleme ile item listesi çekilir.

        /// </summary>

        private void DoCommercialTransaction(int tradeId)

        {

            // C++ birebir: if (m_pUITransactionDlg->IsVisible()) return;

            if (_uiTransaction != null && _uiTransaction.activeSelf)

                return;

            // C++ birebir: m_pUITransactionDlg->m_iTradeID = iTradeID;

            // C++ birebir: m_pUITransactionDlg->SetVisible(true);

            ShowTransaction(true);

            // C++ birebir: GameProcMain.cpp:4377-4381

            // if (m_pUIInventory->IsVisible()) CommandToggleUIInventory();

            // if (m_pUISkillTreeDlg->IsVisible()) m_pUISkillTreeDlg->Close();

            if (_uiInventory != null && _uiInventory.activeSelf)

                ShowInventory(false);

            if (_uiSkillTree != null && _uiSkillTree.activeSelf)

                _uiSkillTree.SetActive(false);

            // C++ birebir: m_pUITransactionDlg->EnterTransactionState();

            // → Item_Org_us.tbl'den bySellGroup == tradeId/1000 filtrele

            var shopItems = KOImport.ItemDataManager.GetShopItemsBySellGroup(tradeId);

            if (shopItems != null && shopItems.Length > 0)

            {

                int npcId = 0;

                if (ShopUI.Instance != null)

                    npcId = ShopUI.Instance.GetNpcId();

                if (npcId == 0)

                {

                    var gm = EntropyOnline.Core.GameManager.Instance;

                    npcId = gm != null ? (int)gm.TargetId : 0;

                    if (ShopUI.Instance != null)

                        ShopUI.Instance.SetNpcId(npcId);

                }

                PopulateShopList(npcId, tradeId, shopItems);

            }

            else

            {

                Debug.LogWarning($"[TRADE] DoCommercialTransaction: tradeId={tradeId} — item listesi boş (sellGroup={tradeId / 1000})");

            }

        }

        public void ShowTransaction(bool show)

        {

            if (_uiTransaction != null)

            {

                if (show)

                {

                    OnPanelOpened(_uiTransaction);

                }

                _uiTransaction.SetActive(show);

            }

            if (show)

            {

                // C++ birebir: UISTYLE_POS_RIGHT — her gösterimde sağ kenar pozisyonu güncelle

                // GameProcMain.cpp:4056: SetPos(iW - panelW, 10)

                SetPanelPosRightCenter(_uiTransaction);

                // C++ birebir: UITransactionDlg::GoldUpdate() (satır 422-428)

                // m_pStrMyGold->SetString(FormatNumber(s_pPlayer->m_InfoExt.iGold))

                UpdateTransactionGold();

            }

            else

            {

                // C++ birebir: UITransactionDlg.cpp LeaveTransactionState satır 490

                // ItemMoveFromThisToInv() — m_pMyTradeInv'den m_pMyInvWnd'ye geri taşı

                ItemMoveFromThisToInv();

                _selectedShopItemIndex = -1;

                _currentShopItems = null;

                _shopNpcId = 0;

                foreach (var item in _shopListItems)

                    if (item != null) Destroy(item);

                _shopListItems.Clear();

                foreach (var obj in _shopInvItems)

                    if (obj != null) Destroy(obj);

                _shopInvItems.Clear();

            }

            // Mobil adaptasyon: Sağ panel değişikliği — skill bar'ı güncelle

            RepositionSkillBarForPanel();

        }

        /// <summary>

        /// C++ birebir: UITransactionDlg::GoldUpdate() (satır 422-428)

        /// string_item_name elementine oyuncunun altın miktarını yazdırır.

        /// </summary>

        private void UpdateTransactionGold()

        {

            if (_uiTransaction == null) return;

            var goldTr = KOUIRenderer.FindChildByID(_uiTransaction.transform, "string_item_name");

            if (goldTr != null)

            {

                var goldText = goldTr.GetComponent<Text>();

                if (goldText != null)

                {

                    var gm = EntropyOnline.Core.GameManager.Instance;

                    goldText.text = gm != null ? gm.Gold.ToString("N0") : "0";

                }

            }

            var labelObj = _uiTransaction.transform.Find("StoreAmountLabel")?.gameObject;

            if (labelObj != null)

            {

                labelObj.SetActive(IsMultipleSellingActive);

                if (IsMultipleSellingActive)

                {

                    var txt = labelObj.GetComponent<Text>();

                    if (txt != null)

                    {

                        txt.text = "Total Amount :" + _totalSelectedSellAmount.ToString("N0");

                    }

                }

            }

        }

