        /// </summary>

        public void ShowWarehouse(bool show)

        {

            if (_uiWarehouse == null) return;

            _uiWarehouse.SetActive(show);

            if (show)

            {

                OnPanelOpened(_uiWarehouse);

                // C++ birebir: UISTYLE_POS_RIGHT — GameProcMain.cpp:4141

                SetPanelPosRightCenter(_uiWarehouse);

                // C++ EnterWareHouseStateEnd satır 589-593: m_pStrMyGold->SetString(FormatNumber(iGold))

                var gm = EntropyOnline.Core.GameManager.Instance;

                if (gm != null && _textMyGold != null)

                    _textMyGold.text = gm.Gold.ToString("N0");

                // C++ birebir: EnterWareHouseStateEnd satır 587 — ItemMoveFromInvToThis

                ItemMoveFromInvToThis_Ware();

                // Mevcut depo verisi varsa populate et

                if (_currentWarehouseItems != null)

                    PopulateWarehouse(_warehouseGold, _currentWarehouseItems);

                PrintRuntimeHierarchy(_uiWarehouse.transform);

            }

            else

            {

                // C++ birebir: UIWareHouseDlg.cpp LeaveWareHouseState satır 501

                ItemMoveFromThisToInv_Ware();

                // C++ birebir: LeaveWareHouseState sonrası inventory gold + UI güncelle

                var gm = EntropyOnline.Core.GameManager.Instance;

                if (gm != null)

                    UpdateGold(gm.Gold);

