                // Inventory UI'ı yenile (itemlar m_pMyInvWnd'ye geri taşındı)

                RefreshInventoryUI();

            }

            // Mobil adaptasyon: Sağ panel değişikliği — skill bar'ı güncelle

            RepositionSkillBarForPanel();

        }

        private void PrintRuntimeHierarchy(Transform parent, int indent = 0)

        {

            var space = new string(' ', indent * 2);

            var rect = parent.GetComponent<RectTransform>();

            var active = parent.gameObject.activeSelf;

            var activeInHierarchy = parent.gameObject.activeInHierarchy;

            var canvasGroup = parent.GetComponent<CanvasGroup>();

            var graphic = parent.GetComponent<UnityEngine.UI.Graphic>();

            var btn = parent.GetComponent<UnityEngine.UI.Button>();

            for (int i = 0; i < parent.childCount; i++)

            {

                PrintRuntimeHierarchy(parent.GetChild(i), indent + 1);

            }

        }

        private T GetComponentInParentInactive<T>(Transform trans) where T : Component

        {

            Transform current = trans;

            while (current != null)

            {

                T comp = current.GetComponent<T>();

                if (comp != null) return comp;

                current = current.parent;

            }

            return null;

        }

        /// <summary>

        /// C++ birebir: UIWareHouseDlg.cpp ItemMoveFromInvToThis() satır 1727-1753

        /// Warehouse açılırken m_pMyInvWnd → m_pMyWareInv MOVE.

        /// </summary>

        private void ItemMoveFromInvToThis_Ware()

        {

            var inv = KOInventory.Instance;

            if (inv == null) return;

            for (int i = 0; i < KOInventory.MAX_ITEM_INVENTORY; i++)

            {

                m_pMyWareInv[i] = null;

                if (inv.m_pMyInvWnd[i] == null) continue;

                m_pMyWareInv[i] = inv.m_pMyInvWnd[i];

                inv.m_pMyInvWnd[i] = null;

            }

        }

        /// <summary>

        /// C++ birebir: UIWareHouseDlg.cpp ItemMoveFromThisToInv() satır 1755-1779

        /// Warehouse kapanırken m_pMyWareInv → m_pMyInvWnd GERİ TAŞI.

        /// </summary>

        private void ItemMoveFromThisToInv_Ware()

        {

            var inv = KOInventory.Instance;

            if (inv == null) return;

            for (int i = 0; i < KOInventory.MAX_ITEM_INVENTORY; i++)

            {

                if (m_pMyWareInv[i] != null)

                {

                    inv.m_pMyInvWnd[i] = m_pMyWareInv[i];

                    m_pMyWareInv[i] = null;

                }

            }

        }

        public void HandleWareDeposit(int srcInvSlot, int dstWareSlot)

        {

            var slot = m_pMyWareInv[srcInvSlot];

            if (slot == null) { Debug.LogWarning($"[WARE_DEPOSIT] m_pMyWareInv[{srcInvSlot}] NULL!"); return; }

            var mgr = KOWarehouseManager.Instance;

            if (mgr == null) return;

            byte byContableCheck = 0;

            if (KOInventory.s_pTbl_Items_Basic != null &&

                KOInventory.s_pTbl_Items_Basic.TryGetValue((uint)(slot.itemId / 1000 * 1000), out var basic))

            {

                byContableCheck = basic.byContable;

            }

            if ((byContableCheck == 1 || byContableCheck == 2) && slot.count > 1)

            {

                _countableEditMode = CountableEditMode.WarehouseItemDeposit;

                _warePendingSrcSlot = srcInvSlot;

                _warePendingDstSlot = dstWareSlot;

                _warePendingItemId = slot.itemId;

                _itemCountMax = slot.count;

                ShowCountableEdit(false);

            }

            else

            {

                ExecuteWareDeposit(srcInvSlot, dstWareSlot, slot.count);

            }

        }

        public void ExecuteWareDeposit(int srcInvSlot, int dstWareSlot, int count)

        {

            var slot = m_pMyWareInv[srcInvSlot];

            if (slot == null) return;

            var mgr = KOWarehouseManager.Instance;

            if (mgr == null) return;

            int page = mgr.CurPage;

            int resolvedDst = dstWareSlot;

            byte realContable = 0;

            if (KOInventory.s_pTbl_Items_Basic != null &&

                KOInventory.s_pTbl_Items_Basic.TryGetValue((uint)(slot.itemId / 1000 * 1000), out var basic))

            {

                realContable = basic.byContable;

            }

            if (realContable == 1 || realContable == 2 || resolvedDst < 0)

            {

                var (destPage, destSlot) = GetWareDestinationIndex(slot.itemId, realContable, page);

                if (destSlot >= 0)

                {

                    resolvedDst = destSlot;

                    page = destPage;

                }

                else

                {

                    Debug.LogWarning("[KOUIMGR] ExecuteWareDeposit: Warehouse dolu!");

                    return;

                }

            }

            int globalDst = page * KOWarehouseManager.MAX_ITEM_TRADE + resolvedDst;

            int itemId = slot.itemId;

            mgr.SendToServerToWareMsg(itemId, (byte)page, (byte)srcInvSlot, (byte)resolvedDst, count);

            if (_currentWarehouseItems != null)

            {

                var newList = new System.Collections.Generic.List<WarehouseSlot>(_currentWarehouseItems);

                var existing = newList.Find(w => w.Slot == resolvedDst && w.ItemId == itemId);

                if (existing != null)

                {

                    existing.Count += (short)count;

                }

                else

                {

                    newList.Add(new WarehouseSlot

                    {

                        Slot = (byte)resolvedDst,

                        ItemId = itemId,

                        Count = (short)count,

                        Durability = (short)slot.durability

                    });

                }

                _currentWarehouseItems = newList.ToArray();

            }

            if (slot.count <= count)

            {

                m_pMyWareInv[srcInvSlot] = null;

            }

            else

            {

                slot.count -= count;

                if (slot.serverData != null) slot.serverData.StackCount = (short)slot.count;

            }

            mgr.SetSlot(page, resolvedDst, itemId, slot.durability, count);

            RefreshWarehouseUI();

        }

        public void HandleWareWithdraw(int srcWareSlot, int dstInvSlot)

        {

            if (_currentWarehouseItems == null) return;

            var mgr = KOWarehouseManager.Instance;

            if (mgr == null) return;

            int page = mgr.CurPage;

            WarehouseSlot wareSlot = null;

            foreach (var w in _currentWarehouseItems)

            {

                if (w.Slot == srcWareSlot && w.ItemId != 0) { wareSlot = w; break; }

            }

            if (wareSlot == null) return;

            byte byContableCheck = 0;

            if (KOInventory.s_pTbl_Items_Basic != null &&

                KOInventory.s_pTbl_Items_Basic.TryGetValue((uint)(wareSlot.ItemId / 1000 * 1000), out var basic))

            {

                byContableCheck = basic.byContable;

            }

            if ((byContableCheck == 1 || byContableCheck == 2) && wareSlot.Count > 1)

            {

                _countableEditMode = CountableEditMode.WarehouseItemWithdraw;

                _warePendingSrcSlot = srcWareSlot;

                _warePendingDstSlot = dstInvSlot;

                _warePendingItemId = wareSlot.ItemId;

                _itemCountMax = wareSlot.Count;

                ShowCountableEdit(false);

            }

            else

            {

                ExecuteWareWithdraw(srcWareSlot, dstInvSlot, wareSlot.Count);

            }

        }

        public void ExecuteWareWithdraw(int srcWareSlot, int dstInvSlot, int count)

        {

            WarehouseSlot wareSlot = null;

            if (_currentWarehouseItems != null)

            {

                foreach (var w in _currentWarehouseItems)

                {

                    if (w.Slot == srcWareSlot && w.ItemId != 0) { wareSlot = w; break; }

                }

            }

            if (wareSlot == null) return;

            var mgr = KOWarehouseManager.Instance;

            if (mgr == null) return;

            int page = mgr.CurPage;

            int resolvedDst = dstInvSlot;

            byte realContable = 0;

            if (KOInventory.s_pTbl_Items_Basic != null &&

                KOInventory.s_pTbl_Items_Basic.TryGetValue((uint)(wareSlot.ItemId / 1000 * 1000), out var basic))

            {

                realContable = basic.byContable;

            }

            if (realContable == 1 || realContable == 2 || resolvedDst < 0)

            {

                int destSlot = GetWareInvDestinationIndex(wareSlot.ItemId, realContable);

                if (destSlot >= 0)

                {

                    resolvedDst = destSlot;

                }

                else

                {

                    Debug.LogWarning("[KOUIMGR] ExecuteWareWithdraw: Envanter dolu!");

                    return;

                }

            }

            int globalSrc = page * KOWarehouseManager.MAX_ITEM_TRADE + srcWareSlot;

            mgr.SendToServerFromWareMsg(wareSlot.ItemId, (byte)page, (byte)srcWareSlot, (byte)resolvedDst, count);

            var existingInv = m_pMyWareInv[resolvedDst];

            if (existingInv != null && existingInv.itemId == wareSlot.ItemId)

            {

                existingInv.count += count;

                if (existingInv.serverData != null) existingInv.serverData.StackCount = (short)existingInv.count;

            }

            else

            {

                var pItem = KOTableReader.FindItemBasic(KOInventory.s_pTbl_Items_Basic, wareSlot.ItemId);

                m_pMyWareInv[resolvedDst] = new KOInventory.ItemSlot

                {

                    itemId      = wareSlot.ItemId,

                    count       = count,

                    durability  = wareSlot.Durability > 0 ? wareSlot.Durability :

                                  (pItem != null ? (int)pItem.siMaxDurability : 1000),

                    attachPoint = (pItem != null) ? pItem.byAttachPoint : 0,

                    itemClass   = (pItem != null) ? pItem.byClass : 0,

                    iconFN      = (pItem != null) ? pItem.dwIDIcon.ToString() : ""

                };

            }

            if (_currentWarehouseItems != null)

            {

                var newList = new System.Collections.Generic.List<WarehouseSlot>(_currentWarehouseItems);

                var existing = newList.Find(w => w.Slot == srcWareSlot && w.ItemId == wareSlot.ItemId);

                if (existing != null)

                {

                    if (existing.Count <= count)

                    {

                        newList.Remove(existing);

                    }

                    else

                    {

                        existing.Count -= (short)count;

                    }

                }

                _currentWarehouseItems = newList.ToArray();

            }

            int remainingCount = wareSlot.Count - count;

            if (remainingCount <= 0)

            {

                mgr.ClearSlot(page, srcWareSlot);

            }

            else

            {

                mgr.SetSlot(page, srcWareSlot, wareSlot.ItemId, wareSlot.Durability, remainingCount);

            }

            RefreshWarehouseUI();

        }

        public void HandleWareToWareMove(int srcWareSlot, int dstWareSlot)

        {

            var mgr = KOWarehouseManager.Instance;

            if (mgr == null || _currentWarehouseItems == null) return;

            int page = mgr.CurPage;

            int globalSrc = page * KOWarehouseManager.MAX_ITEM_TRADE + srcWareSlot;

            int globalDst = page * KOWarehouseManager.MAX_ITEM_TRADE + dstWareSlot;

            WarehouseSlot srcItem = null;

            WarehouseSlot dstItem = null;

            foreach (var item in _currentWarehouseItems)

            {

                if (item.Slot == srcWareSlot) srcItem = item;

                if (item.Slot == dstWareSlot) dstItem = item;

            }

            if (srcItem == null || srcItem.ItemId == 0) return;

            // Send packet via WarehouseUI

            WarehouseUI.Instance?.SendWareToWare(srcItem.ItemId, (byte)page, (byte)srcWareSlot, (byte)dstWareSlot);

            // Update local _currentWarehouseItems list

            var newList = new System.Collections.Generic.List<WarehouseSlot>();

            foreach (var item in _currentWarehouseItems)

            {

                if (item.Slot == srcWareSlot)

                {

                    if (dstItem != null)

                    {

                        newList.Add(new WarehouseSlot { Slot = (byte)srcWareSlot, ItemId = dstItem.ItemId, Count = dstItem.Count, Durability = dstItem.Durability });

                    }

                }

                else if (item.Slot == dstWareSlot)

                {

                    newList.Add(new WarehouseSlot { Slot = (byte)dstWareSlot, ItemId = srcItem.ItemId, Count = srcItem.Count, Durability = srcItem.Durability });

                }

                else

                {

                    newList.Add(item);

                }

            }

            if (dstItem == null)

            {

                newList.Add(new WarehouseSlot { Slot = (byte)dstWareSlot, ItemId = srcItem.ItemId, Count = srcItem.Count, Durability = srcItem.Durability });

            }

            _currentWarehouseItems = newList.ToArray();

            // Update mgr internal slots

            mgr.SetSlot(page, dstWareSlot, srcItem.ItemId, srcItem.Durability, srcItem.Count);

            if (dstItem != null)

                mgr.SetSlot(page, srcWareSlot, dstItem.ItemId, dstItem.Durability, dstItem.Count);

            else

                mgr.SetSlot(page, srcWareSlot, 0, 0, 0);

            RefreshWarehouseUI();

        }

        public void HandleWareInvToInvMove(int srcInvSlot, int dstInvSlot)

        {

            var srcItem = m_pMyWareInv[srcInvSlot];

            if (srcItem == null || srcItem.itemId == 0) return;

            var dstItem = m_pMyWareInv[dstInvSlot];

            if (KOInventory.Instance != null)

            {

                KOInventory.Instance.SendInvMsg(

                    KOInventory.ITEM_MOVE_INV_TO_INV,

                    srcItem.itemId,

                    srcInvSlot,

                    dstInvSlot);

            }

            // Swap locally

            m_pMyWareInv[srcInvSlot] = dstItem;

            m_pMyWareInv[dstInvSlot] = srcItem;

            RefreshWarehouseUI();

        }

        /// <summary>

        /// Warehouse UI'ı yenile (PopulateWarehouse ile aynı veriyi tekrar render et).

        /// </summary>

        public void RefreshWarehouseUI()

        {

            if (_uiWarehouse == null || !_uiWarehouse.activeSelf)

            {

                Debug.LogWarning($"[WARE_REFRESH] ATLANMADI: _uiWarehouse={_uiWarehouse != null}, active={_uiWarehouse?.activeSelf}");

                return;

            }

            if (_currentWarehouseItems != null)

            {

                if (KOWarehouseManager.Instance != null)
                {
                    _warehouseGold = KOWarehouseManager.Instance.WareGold;
                }

                PopulateWarehouse(_warehouseGold, _currentWarehouseItems);

            }

            else

            {

                Debug.LogWarning("[WARE_REFRESH] _currentWarehouseItems NULL!");

            }

        }

        /// <summary>

        /// Warehouse text referanslarını ve butonlarını bağlar.

        /// C++ referans: UIWareHouseDlg.cpp InitIconWnd() satır 194-200, ReceiveMessage() satır 336-337

        /// </summary>

        private void BindWarehouseElements(Transform root)

        {

            // C++ UIWareHouseDlg.cpp satır 194: m_pStrWareGold = GetChildByID<CN3UIString>("string_wareitem_name")

            _textWareGold = KOUIRenderer.FindChildText(root, "string_wareitem_name");

            // C++ UIWareHouseDlg.cpp satır 198: m_pStrMyGold = GetChildByID<CN3UIString>("string_item_name")

            _textMyGold = KOUIRenderer.FindChildText(root, "string_item_name");

            // C++ UIWareHouseDlg.cpp satır 336-337: m_pBtnClose -> LeaveWareHouseState()

            var btnClose = KOUIRenderer.FindChildButton(root, "btn_close");

            if (btnClose != null)

            {

                btnClose.onClick.AddListener(() =>

                {

                    KOWarehouseManager.Instance?.LeaveWareHouseState();

                    ShowWarehouse(false);

                });

            }

            // C++ UIWareHouseDlg.cpp satır 2082: m_pBtnPageUp = GetChildByID<CN3UIButton>("btn_page_up")

            var btnPageUp = KOUIRenderer.FindChildButton(root, "btn_page_up");

            if (btnPageUp != null)

            {

                btnPageUp.onClick.AddListener(() =>

                {

                    if (WarehouseUI.Instance != null) WarehouseUI.Instance.OnBtnPageUp();

                    else Debug.LogWarning("[KOUIMGR-CLICK] btn_page_up: WarehouseUI.Instance is null!");

                });

            }

            // C++ UIWareHouseDlg.cpp satır 2083: m_pBtnPageDown = GetChildByID<CN3UIButton>("btn_page_down")

            var btnPageDown = KOUIRenderer.FindChildButton(root, "btn_page_down");

            if (btnPageDown != null)

            {

                btnPageDown.onClick.AddListener(() =>

                {

                    if (WarehouseUI.Instance != null) WarehouseUI.Instance.OnBtnPageDown();

                    else Debug.LogWarning("[KOUIMGR-CLICK] btn_page_down: WarehouseUI.Instance is null!");

                });

            }

            // C++ UIWareHouseDlg.cpp satır 322-326: btn_gold -> gold deposit (envanter -> depo)

            var btnGold = KOUIRenderer.FindChildButton(root, "btn_gold");

            if (btnGold != null)

            {

                btnGold.onClick.AddListener(() =>

                {

                    _countableEditMode = CountableEditMode.WarehouseDeposit;

                    ShowCountableEdit(true);

                });

            }

            // C++ UIWareHouseDlg.cpp satır 329-333: btn_gold_warehouse -> gold withdraw (depo -> envanter)

            var btnGoldWare = KOUIRenderer.FindChildButton(root, "btn_gold_warehouse");

            if (btnGoldWare != null)

            {

                btnGoldWare.onClick.AddListener(() =>

                {

                    _countableEditMode = CountableEditMode.WarehouseWithdraw;

                    ShowCountableEdit(true);

                });

            }

            // Modernize the Warehouse Panel look

            ModernizeWarehousePanel(root);

        }

