        public void ToggleMultipleSellSelection(int slotIndex, int itemId, int count)

        {

            if (_selectedSellSlots.Contains(slotIndex))

            {

                _selectedSellSlots.Remove(slotIndex);

            }

            else

            {

                _selectedSellSlots.Add(slotIndex);

            }

            RecalculateMultipleSellAmount();

            RefreshShopInventory();

        }

        private void RecalculateMultipleSellAmount()

        {

            _totalSelectedSellAmount = 0;

            if (m_pMyTradeInv == null) return;

            foreach (int slotIdx in _selectedSellSlots)

            {

                var slot = m_pMyTradeInv[slotIdx];

                if (slot != null && !m_pMyTradeInvHidden[slotIdx])

                {

                    _totalSelectedSellAmount += GetItemSellPrice(slot.itemId, slot.count);

                }

            }

            UpdateTransactionGold();

        }

        public int GetItemSellPrice(int itemId, int count)

        {

            if (KOInventory.s_pTbl_Items_Basic == null) return count;

            var basic = KOTableReader.FindItemBasic(KOInventory.s_pTbl_Items_Basic, itemId);

            if (basic == null) return count;

            var ext = ItemDataManager.GetItemExt(itemId);

            int multiply = ext != null && ext.SiPriceMultiply > 0 ? ext.SiPriceMultiply : 1;

            int singlePrice = basic.iPrice * multiply;

            if (basic.iSaleType != 1)

                singlePrice /= 6;

            if (singlePrice < 1) singlePrice = 1;

            return singlePrice * count;

        }

        public void ExecuteMultipleSell()

        {

            if (_selectedSellSlots.Count == 0) return;

            var shopUI = ShopUI.Instance;

            if (shopUI == null) return;

            // Karakterin parasına satılacak eşyaların toplam bedelini ekle

            var gm = EntropyOnline.Core.GameManager.Instance;

            if (gm != null)

            {

                gm.Gold += _totalSelectedSellAmount;

            }

            var slotsToSell = new System.Collections.Generic.List<int>(_selectedSellSlots);

            foreach (int slotIdx in slotsToSell)

            {

                var slot = m_pMyTradeInv[slotIdx];

                if (slot != null && !m_pMyTradeInvHidden[slotIdx])

                {

                    shopUI.SellItem(_shopTradeId, (byte)slotIdx, (uint)slot.itemId, (short)slot.count);

                    // Lokalde envanterden hemen kaldır

                    m_pMyTradeInv[slotIdx] = null;

                    m_pMyTradeInvHidden[slotIdx] = false;

                }

            }

            _selectedSellSlots.Clear();

            _totalSelectedSellAmount = 0;

            UpdateTransactionGold();

            RefreshShopInventory();

        }

