                    stringPage.color = new Color(0.95f, 0.85f, 0.35f, 1);

                    stringPage.fontStyle = FontStyle.Bold;

                    stringPage.alignment = TextAnchor.MiddleCenter;

                    AddSkillThemeTextShadow(stringPage);

                }

                var textWeight = KOUIRenderer.FindChildText(root, "text_weight");

                if (textWeight != null)

                {

                    textWeight.color = new Color(0.9f, 0.8f, 0.6f, 1);

                    textWeight.fontStyle = FontStyle.Bold;

                    AddSkillThemeTextShadow(textWeight);

                }

                // 6. Modernize Slot list containers

                var topBgTr = root.Find("ui_Image_69D6EBA8") ?? KOUIRenderer.FindChildByID(root, "ui_Image_69D6EBA8");

                if (topBgTr != null)

                {

                    if (!isModern)

                    {

                        var rawImg = topBgTr.GetComponent<RawImage>();

                        if (rawImg != null) rawImg.enabled = false;

                        var imgComp = topBgTr.GetComponent<Image>();

                        if (imgComp != null) imgComp.enabled = false;

                    }

                    var bgObj = topBgTr.Find("TopCustomBg")?.gameObject;

                    if (bgObj == null)

                    {

                        bgObj = new GameObject("TopCustomBg", typeof(RectTransform));

                        bgObj.transform.SetParent(topBgTr, false);

                        bgObj.transform.SetAsFirstSibling();

                        var bgRT = bgObj.GetComponent<RectTransform>();

                        if (bgRT != null && !isModern)

                        {

                            bgRT.anchorMin = Vector2.zero;

                            bgRT.anchorMax = Vector2.one;

                            bgRT.offsetMin = Vector2.zero;

                            bgRT.offsetMax = Vector2.zero;

                        }

                    }

                    var bgImgComponent = bgObj.GetComponent<Image>() ?? bgObj.AddComponent<Image>();

                    bgImgComponent.sprite = GetSkillThemeRoundedRectSprite("warehouse_top_slots_bg", 362, 134, 4,

                        new Color(0.08f, 0.08f, 0.08f, 0.7f),

                        new Color(0.45f, 0.35f, 0.15f, 0.6f),

                        1);

                    bgImgComponent.color = Color.white;

                }

                var bottomBgTr = root.Find("ui_Image_C62C6D7C") ?? KOUIRenderer.FindChildByID(root, "ui_Image_C62C6D7C");

                if (bottomBgTr != null)

                {

                    if (!isModern)

                    {

                        var rawImg = bottomBgTr.GetComponent<RawImage>();

                        if (rawImg != null) rawImg.enabled = false;

                        var imgComp = bottomBgTr.GetComponent<Image>();

                        if (imgComp != null) imgComp.enabled = false;

                    }

                    var bgObj = bottomBgTr.Find("BottomCustomBg")?.gameObject;

                    if (bgObj == null)

                    {

                        bgObj = new GameObject("BottomCustomBg", typeof(RectTransform));

                        bgObj.transform.SetParent(bottomBgTr, false);

                        bgObj.transform.SetAsFirstSibling();

                        var bgRT = bgObj.GetComponent<RectTransform>();

                        if (bgRT != null && !isModern)

                        {

                            bgRT.anchorMin = Vector2.zero;

                            bgRT.anchorMax = Vector2.one;

                            bgRT.offsetMin = Vector2.zero;

                            bgRT.offsetMax = Vector2.zero;

                        }

                    }

                    var bgImgComponent = bgObj.GetComponent<Image>() ?? bgObj.AddComponent<Image>();

                    bgImgComponent.sprite = GetSkillThemeRoundedRectSprite("warehouse_bottom_slots_bg", 362, 313, 4,

                        new Color(0.08f, 0.08f, 0.08f, 0.7f),

                        new Color(0.45f, 0.35f, 0.15f, 0.6f),

                        1);

                    bgImgComponent.color = Color.white;

                }

                // 7. Sibling sorting will be done at the very end to ensure it covers dynamically created elements

                // 8. Cleanup Raycast Targets to prevent blocking clicks

                if (!isModern)

                {

                    CleanupWarehouseRaycastTargets(root);

                }

                // 9. Center Top Warehouse Slots (AreaType = 3) horizontally

                if (!isModern)

                {

                    var slot0 = KOUIRenderer.FindChildAreaByiOrder(root, 3, 0);

                    if (slot0 != null && slot0.anchoredPosition.x < 30f)

                    {

                        for (int i = 0; i < 24; i++)

                        {

                            var areaRT = KOUIRenderer.FindChildAreaByiOrder(root, 3, i);

                            if (areaRT != null)

                            {

                                var pos = areaRT.anchoredPosition;

                                pos.x += 13f;

                                areaRT.anchoredPosition = pos;

                            }

                        }

                    }

                }

                // 10. Add horizontal gold divider line with fade-out edges at y = -302f

                var separatorObj = root.Find("WarehouseSeparator")?.gameObject;

                if (separatorObj == null)

                {

                    separatorObj = new GameObject("WarehouseSeparator", typeof(RectTransform));

                    separatorObj.transform.SetParent(root, false);

                    var existingBg = root.Find("WarehouseCustomBg");

                    if (existingBg != null)

                    {

                        separatorObj.transform.SetSiblingIndex(existingBg.GetSiblingIndex() + 1);

                    }

                    var rt = separatorObj.GetComponent<RectTransform>();

                    if (rt != null && !isModern)

                    {

                        rt.anchorMin = new Vector2(0f, 1f);

                        rt.anchorMax = new Vector2(1f, 1f); // Stretch horizontally

                        rt.pivot = new Vector2(0.5f, 0.5f);

                        rt.anchoredPosition = new Vector2(0f, -312f);

                        rt.sizeDelta = new Vector2(0f, 2f); // 2px height for better visual crispness

                    }

                }

                else

                {

                    separatorObj.SetActive(true);

                }

                var sepImg = separatorObj.GetComponent<Image>() ?? separatorObj.AddComponent<Image>();

                sepImg.sprite = GetSkillThemeHorizontalFadeLineSprite("warehouse_fade_line", 364, 2, new Color(0.6f, 0.48f, 0.22f, 1f));

                sepImg.color = Color.white;

                sepImg.raycastTarget = false;

                // 11. Add WAREHOUSE title text at the top center of the panel

                var titleObj = root.Find("WarehouseTitle")?.gameObject;

                if (titleObj == null)

                {

                    titleObj = new GameObject("WarehouseTitle", typeof(RectTransform));

                    titleObj.transform.SetParent(root, false);

                    var existingBg = root.Find("WarehouseCustomBg");

                    if (existingBg != null)

                    {

                        titleObj.transform.SetSiblingIndex(existingBg.GetSiblingIndex() + 1);

                    }

                    var rt = titleObj.GetComponent<RectTransform>();

                    if (rt != null && !isModern)

                    {

                        rt.anchorMin = new Vector2(0.5f, 1f);

                        rt.anchorMax = new Vector2(0.5f, 1f);

                        rt.pivot = new Vector2(0.5f, 0.5f);

                        rt.anchoredPosition = new Vector2(0f, -41f);

                        rt.sizeDelta = new Vector2(200f, 24f);

                    }

                }

                var titleTxt = titleObj.GetComponent<Text>() ?? titleObj.AddComponent<Text>();

                titleTxt.text = "WAREHOUSE";

                titleTxt.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");

                titleTxt.alignment = TextAnchor.MiddleCenter;

                titleTxt.color = new Color(0.95f, 0.85f, 0.35f, 1f);

                titleTxt.fontStyle = FontStyle.Bold;

                titleTxt.fontSize = 14;

                AddSkillThemeTextShadow(titleTxt);

                // Set title on top of backgrounds/panels

                titleObj.transform.SetAsLastSibling();

                // Position gold buttons (btn_gold and btn_gold_warehouse) to fit the capsule (x=235, size=26x26)

                var btnGold = KOUIRenderer.FindChildButton(root, "btn_gold");

                if (btnGold != null)

                {

                    var rt = btnGold.GetComponent<RectTransform>();

                    if (rt != null)

                    {

                        rt.anchoredPosition = new Vector2(233f, -324f);

                        rt.sizeDelta = new Vector2(30f, 30f);

                    }

                }

                var btnGoldWare = KOUIRenderer.FindChildButton(root, "btn_gold_warehouse");

                if (btnGoldWare != null)

                {

                    var rt = btnGoldWare.GetComponent<RectTransform>();

                    if (rt != null)

                    {

                        rt.anchoredPosition = new Vector2(233f, -283f);

                        rt.sizeDelta = new Vector2(30f, 30f);

                    }

                }

                // Force buttons and close button on top of everything to prevent overlap or blocking

                if (!isModern)

                {

                    var pUp = KOUIRenderer.FindChildButton(root, "btn_page_up");

                    if (pUp != null) pUp.transform.SetAsLastSibling();

                    var pDown = KOUIRenderer.FindChildButton(root, "btn_page_down");

                    if (pDown != null) pDown.transform.SetAsLastSibling();

                    var gDep = KOUIRenderer.FindChildButton(root, "btn_gold");

                    if (gDep != null) gDep.transform.SetAsLastSibling();

                    var gWith = KOUIRenderer.FindChildButton(root, "btn_gold_warehouse");

                    if (gWith != null) gWith.transform.SetAsLastSibling();

                    var bCls = KOUIRenderer.FindChildButton(root, "btn_close");

                    if (bCls != null) bCls.transform.SetAsLastSibling();

                }

            }

            catch (System.Exception ex)

            {

                Debug.LogError($"[KOUIMGR] Error in ModernizeWarehousePanel: {ex.Message}");

            }

        }

        private void CreateGoldCapsuleForText(Text goldText)

        {

            if (goldText == null) return;

            goldText.alignment = TextAnchor.MiddleRight;

            goldText.horizontalOverflow = HorizontalWrapMode.Overflow;

            var textRT = goldText.GetComponent<RectTransform>();

            if (textRT != null)

            {

                // Force anchors and pivot to Left-Top (0, 1) to ensure identical positioning across panels

                textRT.anchorMin = new Vector2(0f, 1f);

                textRT.anchorMax = new Vector2(0f, 1f);

                textRT.pivot = new Vector2(0f, 1f);

                textRT.anchoredPosition = new Vector2(258f, textRT.anchoredPosition.y);

                textRT.sizeDelta = new Vector2(85f, 20f);

            }

            var parent = goldText.transform.parent;

            var capsuleObj = parent.Find(goldText.gameObject.name + "_Capsule")?.gameObject;

            if (capsuleObj == null)

            {

                capsuleObj = new GameObject(goldText.gameObject.name + "_Capsule", typeof(RectTransform));

                capsuleObj.transform.SetParent(parent, false);

            }

            capsuleObj.transform.SetSiblingIndex(goldText.transform.GetSiblingIndex()); // draw behind

            var capsuleImg = capsuleObj.GetComponent<Image>() ?? capsuleObj.AddComponent<Image>();

            capsuleImg.sprite = GetSkillThemeRoundedRectSprite(goldText.gameObject.name + "_gold_capsule", 150, 22, 4,

                new Color(0.08f, 0.08f, 0.08f, 0.6f),

                new Color(0.45f, 0.35f, 0.15f, 0.8f),

                1);

            capsuleImg.color = Color.white;

            capsuleImg.raycastTarget = false;

            var capsuleRT = capsuleObj.GetComponent<RectTransform>();

            if (capsuleRT != null && textRT != null)

            {

                // Force anchors and pivot to Left-Top (0, 1)

                capsuleRT.anchorMin = new Vector2(0f, 1f);

                capsuleRT.anchorMax = new Vector2(0f, 1f);

                capsuleRT.pivot = new Vector2(0f, 1f);

                capsuleRT.sizeDelta = new Vector2(120f, 22f);

                capsuleRT.anchoredPosition = new Vector2(233f, textRT.anchoredPosition.y + 1f);

            }

        }

        private void CleanupWarehouseRaycastTargets(Transform root)

        {

/* Loop Removed */

/* Loop Removed */

            var texts = root.GetComponentsInChildren<UnityEngine.UI.Text>(true);

            foreach (var txt in texts)

            {

                if (GetComponentInParentInactive<UnityEngine.UI.Button>(txt.transform) == null)

                {

                    txt.raycastTarget = false;

                }

            }

        }

        /// <summary>

        /// Sunucudan gelen depo verisini panele doldurur.

        /// C++ birebir: UIWareHouseDlg.cpp InitIconUpdate() satır 203-228

        ///   → GetChildAreaByiOrder(UI_AREA_TYPE_TRADE_NPC, i) ile ware slotları

        ///   → GetChildAreaByiOrder(UI_AREA_TYPE_TRADE_MY, i) ile inv slotları

        /// </summary>

        public void PopulateWarehouse(long wareGold, WarehouseSlot[] items)

        {

            _warehouseGold = wareGold;

            _currentWarehouseItems = items;

            // Eski dinamik item'ları temizle

            foreach (var obj in _warehouseListItems)

                if (obj != null) Destroy(obj);

            _warehouseListItems.Clear();

            if (_uiWarehouse == null) return;

            Transform wareRoot = _uiWarehouse.transform;

            // Tasarım özgünleştirme: persistent slot soket arka planları ekle

            var allKOAreas = wareRoot.GetComponentsInChildren<KOUIArea>(true);

            foreach (var area in allKOAreas)

            {

                if (area.AreaType == 3 || area.AreaType == 11)

                {

                    var areaImg = area.GetComponent<Image>() ?? area.gameObject.AddComponent<Image>();

                    areaImg.sprite = GetSkillThemeGlassSlotSprite("slot_socket_glass_v5", 45);

                    areaImg.color = Color.white;

                    areaImg.raycastTarget = false;

                }

            }

            // C++ EnterWareHouseStateStart satır 549-550: m_pStrWareGold->SetString(FormatNumber(iWareGold))

            if (_textWareGold != null)

                _textWareGold.text = wareGold.ToString("N0");

            // C++ EnterWareHouseStateEnd satır 589-593: m_pStrMyGold->SetString(FormatNumber(iGold))

            var gm = EntropyOnline.Core.GameManager.Instance;

            if (gm != null && _textMyGold != null)

                _textMyGold.text = gm.Gold.ToString("N0");

            // C++ birebir: string_page güncelle

            var textPage = KOUIRenderer.FindChildText(wareRoot, "string_page");

            if (textPage != null)

            {

                var mgr = KOWarehouseManager.Instance;

                textPage.text = $"{(mgr != null ? mgr.CurPage + 1 : 1)}/8";

            }

            // ============================================

            // Warehouse slotları — UI_AREA_TYPE_TRADE_NPC (3)

            // C++ birebir: InitIconUpdate() satır 220:

            //   CN3UIArea* pArea = GetChildAreaByiOrder(UI_AREA_TYPE_TRADE_NPC, i);

            //   m_pMyWare[j][i]->pUIIcon->SetRegion(pArea->GetRegion());

            // ============================================

            const int UI_AREA_TYPE_TRADE_NPC = 3;  // N3UIArea.h:16

            const int UI_AREA_TYPE_TRADE_MY  = 11; // N3UIArea.h:24

            // Mevcut sayfadaki dolu slot'ları global index ile hashle

            var wareOccupied = new System.Collections.Generic.Dictionary<int, WarehouseSlot>();

            if (items != null)

            {

                foreach (var slot in items)

                {

                    if (slot.ItemId != 0)

                        wareOccupied[slot.Slot] = slot;

                }

            }

            var wareMgr = KOWarehouseManager.Instance;

            int curPage = wareMgr != null ? wareMgr.CurPage : 0;

            for (int i = 0; i < KOWarehouseManager.MAX_ITEM_TRADE; i++)

            {

                var areaRT = KOUIRenderer.FindChildAreaByiOrder(wareRoot, UI_AREA_TYPE_TRADE_NPC, i);

                if (wareOccupied.TryGetValue(i, out var slot))

                {

                    // Dolu slot — ikon oluştur

                    if (areaRT == null) continue;

                    var itemObj = CreateWarehouseIconInArea(areaRT, $"WareSlot_{i}",

                        slot.ItemId, slot.Count,

                        KOItemSlotHandler.SlotType.WarehouseSlot, i, slot.Durability);

                    if (itemObj.GetComponent<KOItemDragDrop>() == null)

                        itemObj.AddComponent<KOItemDragDrop>();

                    _warehouseListItems.Add(itemObj);

                }

                else

                {

                    // Boş slot — şeffaf drop target

                    if (areaRT == null) continue;

                    var emptyObj = new GameObject($"WareSlot_{i}");

                    emptyObj.transform.SetParent(wareRoot, false);

                    var emptyRT = emptyObj.AddComponent<RectTransform>();

                    emptyRT.anchorMin = areaRT.anchorMin;

                    emptyRT.anchorMax = areaRT.anchorMax;

                    emptyRT.pivot = areaRT.pivot;

                    emptyRT.anchoredPosition = areaRT.anchoredPosition;

                    emptyRT.sizeDelta = areaRT.sizeDelta;

                    var emptyImg = emptyObj.AddComponent<Image>();

                    emptyImg.color = new Color(0, 0, 0, 0);

                    emptyImg.raycastTarget = true;

                    var handler = emptyObj.AddComponent<KOItemSlotHandler>();

                    handler.slotType = KOItemSlotHandler.SlotType.WarehouseSlot;

                    handler.slotIndex = i;

                    handler.tooltipItemDefId = 0;

                    if (emptyObj.GetComponent<KOItemDragDrop>() == null)

                        emptyObj.AddComponent<KOItemDragDrop>();

                    _warehouseListItems.Add(emptyObj);

                }

            }

            // ============================================

            // Inventory slotları — UI_AREA_TYPE_TRADE_MY (11)

            // C++ birebir: m_pMyWareInv'den oku (m_pMyInvWnd yerine)

            //   pArea = GetChildAreaByiOrder(UI_AREA_TYPE_TRADE_MY, i);

            //   spItem->pUIIcon->SetRegion(pArea->GetRegion());

            // ============================================

            bool hasTradeMyAreas = KOUIRenderer.FindChildAreaByiOrder(wareRoot, UI_AREA_TYPE_TRADE_MY, 0) != null;

            for (int i = 0; i < KOInventory.MAX_ITEM_INVENTORY; i++)

            {

                // C++ birebir: m_pMyWareInv'den oku

                var invItem = m_pMyWareInv[i];

                bool hasItem = invItem != null && invItem.itemId != 0;

                RectTransform areaRT = hasTradeMyAreas

                    ? KOUIRenderer.FindChildAreaByiOrder(wareRoot, UI_AREA_TYPE_TRADE_MY, i)

                    : null;

                if (areaRT != null)

                {

                    if (hasItem)

                    {

                        var itemObj = CreateWarehouseIconInArea(areaRT, $"WareInvSlot_{i}",

                            invItem.itemId, invItem.count > 0 ? invItem.count : 1,

                            KOItemSlotHandler.SlotType.WarehouseInvSlot, i, (short)invItem.durability);

                        // Drag-drop ekle

                        if (itemObj.GetComponent<KOItemDragDrop>() == null)

                            itemObj.AddComponent<KOItemDragDrop>();

                        _warehouseListItems.Add(itemObj);

                    }

                    else

                    {

                        // Boş slot — drop target

                        var emptyObj = new GameObject($"WareInvSlot_{i}");

                        emptyObj.transform.SetParent(wareRoot, false);

                        var emptyRT = emptyObj.AddComponent<RectTransform>();

                        emptyRT.anchorMin = areaRT.anchorMin;

                        emptyRT.anchorMax = areaRT.anchorMax;

                        emptyRT.pivot = areaRT.pivot;

                        emptyRT.anchoredPosition = areaRT.anchoredPosition;

                        emptyRT.sizeDelta = areaRT.sizeDelta;

                        var emptyImg = emptyObj.AddComponent<Image>();

                        emptyImg.color = new Color(0, 0, 0, 0);

                        emptyImg.raycastTarget = true;

                        var handler = emptyObj.AddComponent<KOItemSlotHandler>();

                        handler.slotType = KOItemSlotHandler.SlotType.WarehouseInvSlot;

                        handler.slotIndex = i;

                        handler.tooltipItemDefId = 0;

                        if (emptyObj.GetComponent<KOItemDragDrop>() == null)

                            emptyObj.AddComponent<KOItemDragDrop>();

                        _warehouseListItems.Add(emptyObj);

                    }

                }

                else

                {

                    // Fallback: UIF'de type=11 area yok — grid layout

                    var itemObj = new GameObject($"WareInvSlot_{i}");

                    itemObj.transform.SetParent(wareRoot, false);

                    var itemRT = itemObj.AddComponent<RectTransform>();

                    float iconSize = 32f;

                    float spacing = 36f;

                    float startX = 8f;

                    float startY = 8f + (3 - (i / 7)) * spacing;

                    int col = i % 7;

                    itemRT.anchorMin = new Vector2(0, 0);

                    itemRT.anchorMax = new Vector2(0, 0);

                    itemRT.pivot = new Vector2(0, 0);

                    itemRT.anchoredPosition = new Vector2(startX + col * spacing, startY);

                    itemRT.sizeDelta = new Vector2(iconSize, iconSize);

                    if (hasItem)

                    {

                        int iconId = ResolveIconId(invItem.itemId);

                        var icon = KOItemIconLoader.LoadItemIcon(iconId);

                        var img = itemObj.AddComponent<Image>();

                        if (icon != null)

                        {

                            img.sprite = icon;

                            img.preserveAspect = true;

                        }

                        else

                        {

                            img.color = new Color(0.3f, 0.3f, 0.3f, 0.5f);

                        }

                        img.raycastTarget = true;

                        // Count overlay

                        int displayCount = invItem.count;

                        bool showCount = false;

                        var basic = invItem.pItemBasic;

                        if (basic == null && KOInventory.s_pTbl_Items_Basic != null)

                        {

                            KOInventory.s_pTbl_Items_Basic.TryGetValue((uint)(invItem.itemId / 1000 * 1000), out basic);

                        }

                        if (basic != null)

                        {

                            if (basic.byContable == 1 || basic.byContable == 2)

                            {

                                if (invItem.count > 1)

                                {

                                    showCount = true;

                                }

                            }

                            else if (basic.byAttachPoint == 15 && invItem.durability > 1)

                            {

                                displayCount = invItem.durability;

                                showCount = true;

                            }

                        }

                        if (showCount)

                        {

                            var cObj = new GameObject("Count");

                            cObj.transform.SetParent(itemObj.transform, false);

                            var cRT = cObj.AddComponent<RectTransform>();

                            cRT.anchorMin = new Vector2(1, 0);

                            cRT.anchorMax = new Vector2(1, 0);

                            cRT.pivot = new Vector2(1, 0);

                            cRT.anchoredPosition = new Vector2(-1, 1);

                            cRT.sizeDelta = new Vector2(20, 10);

                            var cText = cObj.AddComponent<Text>();

                            cText.text = displayCount.ToString();

                            cText.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");

                            cText.fontSize = 8;

                            cText.color = Color.white;

                            cText.alignment = TextAnchor.LowerRight;

                            cText.raycastTarget = false;

                        }

                        var h = itemObj.AddComponent<KOItemSlotHandler>();

                        h.slotType = KOItemSlotHandler.SlotType.WarehouseInvSlot;

                        h.slotIndex = i;

                        h.tooltipItemDefId = invItem.itemId;

                        h.warehouseItemCount = invItem.count > 0 ? invItem.count : 1;

                    }

                    else

                    {

                        // Boş slot — drop target

                        var img = itemObj.AddComponent<Image>();

                        img.color = new Color(0, 0, 0, 0);

                        img.raycastTarget = true;

                        var h = itemObj.AddComponent<KOItemSlotHandler>();

                        h.slotType = KOItemSlotHandler.SlotType.WarehouseInvSlot;

                        h.slotIndex = i;

                        h.tooltipItemDefId = 0;

                    }

                    // Drag-drop ekle

                    if (itemObj.GetComponent<KOItemDragDrop>() == null)

                        itemObj.AddComponent<KOItemDragDrop>();

                    _warehouseListItems.Add(itemObj);

                }

            }

            int invCount = 0;

            for (int ii = 0; ii < KOInventory.MAX_ITEM_INVENTORY; ii++)

                if (m_pMyWareInv[ii] != null && m_pMyWareInv[ii].itemId != 0) invCount++;

        }

        /// <summary>

        /// C++ birebir: UIWareHouseDlg gold text refresh

        /// m_pStrWareGold->SetString(FormatNumber(iWareGold))

        /// m_pStrMyGold->SetString(FormatNumber(iGold))

        /// Gold deposit/withdraw sonrası anlık UI güncellemesi.

        /// </summary>

        private void RefreshWarehouseGoldDisplay()

        {

            var wareMgr = KOWarehouseManager.Instance;

            var gm = EntropyOnline.Core.GameManager.Instance;

            if (_textWareGold != null && wareMgr != null)
            {
                _textWareGold.text = wareMgr.WareGold.ToString("N0");
                _warehouseGold = wareMgr.WareGold;
            }

            if (_textMyGold != null && gm != null)

                _textMyGold.text = gm.Gold.ToString("N0");

        }

        /// <summary>

        /// UIF area region'una item ikonu yerleştirir.

        /// C++ birebir: InitIconUpdate() — CN3UIIcon::SetRegion(pArea->GetRegion())

        /// İkon, area'nın tam boyutunda oluşturulur ve area'nın parent'ına child olarak eklenir.

        /// </summary>

                private GameObject CreateWarehouseIconInArea(RectTransform areaRT, string name,

            int itemId, int count,

            KOItemSlotHandler.SlotType slotType, int slotIndex, short durability = 0)

        {

            var itemObj = new GameObject(name);

            // Area'nın parent'ına ekle (aynı seviyede, area'nın pozisyonunu kopyala)

            itemObj.transform.SetParent(areaRT.parent, false);

            var itemRT = itemObj.AddComponent<RectTransform>();

            // Area ile aynı anchor/pozisyon/boyut

            itemRT.anchorMin = areaRT.anchorMin;

            itemRT.anchorMax = areaRT.anchorMax;

            itemRT.offsetMin = areaRT.offsetMin;

            itemRT.offsetMax = areaRT.offsetMax;

            itemRT.pivot = areaRT.pivot;

            itemRT.anchoredPosition = areaRT.anchoredPosition;

            itemRT.sizeDelta = areaRT.sizeDelta;

            itemObj.transform.localScale = areaRT.localScale;

            // C++ InitIconUpdate() satır 215: SetTex(szIconFN)

            // itemId → dwIDIcon lookup (C++ birebir: s_pTbl_Items_Basic->dwIDIcon)

            int iconId = ResolveIconId(itemId);

            var icon = KOItemIconLoader.LoadItemIcon(iconId);

            // Create a child object for the icon to add padding/margins

            var iconObj = new GameObject("Icon");

            iconObj.transform.SetParent(itemObj.transform, false);

            var iconRT = iconObj.AddComponent<RectTransform>();

            iconRT.anchorMin = Vector2.zero;

            iconRT.anchorMax = Vector2.one;

            iconRT.offsetMin = Vector2.zero;

            iconRT.offsetMax = Vector2.zero;

            if (icon != null)

            {

                var img = iconObj.AddComponent<UnityEngine.UI.Image>();

                img.sprite = icon;

                img.preserveAspect = true;

                img.raycastTarget = false;

            }

            else

            {

                var img = iconObj.AddComponent<UnityEngine.UI.Image>();

                img.color = new Color(0.3f, 0.3f, 0.3f, 0.5f);

                img.raycastTarget = false;

            }

            // Ensure the main itemObj has a transparent image to intercept raycasts

            var mainImg = itemObj.AddComponent<UnityEngine.UI.Image>();

            mainImg.color = Color.clear;

            mainImg.raycastTarget = true;

            // C++ Render() satır 112-134: Countable item count overlay

            byte byContableCheck = 0;

            byte byAttachPointCheck = 0;

            if (KOInventory.s_pTbl_Items_Basic != null &&

                KOInventory.s_pTbl_Items_Basic.TryGetValue((uint)(itemId / 1000 * 1000), out var basicCount))

            {

                byContableCheck = basicCount.byContable;

                byAttachPointCheck = basicCount.byAttachPoint;

            }

            int displayCount = count;

            bool showCount = false;

            if (byContableCheck == 1 || byContableCheck == 2)

            {

                if (count > 1)

                {

                    showCount = true;

                }

            }

            else if (byAttachPointCheck == 15 && durability > 1)

            {

                displayCount = durability;

                showCount = true;

            }

            if (showCount)

            {

                var countObj = new GameObject("CountText");

                countObj.transform.SetParent(itemObj.transform, false);

                var countRT = countObj.AddComponent<RectTransform>();

                countRT.anchorMin = new Vector2(1, 0);

                countRT.anchorMax = new Vector2(1, 0);

                countRT.pivot = new Vector2(1, 0);

                countRT.anchoredPosition = new Vector2(-1, 1);

                countRT.sizeDelta = new Vector2(30, 12);

                var countText = countObj.AddComponent<Text>();

                countText.text = displayCount.ToString();

                countText.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");

                countText.fontSize = 9;

                countText.color = Color.white;

                countText.alignment = TextAnchor.LowerRight;

                countText.raycastTarget = false;

                var shadow = countObj.AddComponent<Shadow>();

                shadow.effectColor = new Color(0, 0, 0, 0.9f);

                shadow.effectDistance = new Vector2(1, -1);

            }

            // Mobil adaptasyon: single-tap=tooltip

            var handler = itemObj.AddComponent<KOItemSlotHandler>();

            handler.slotType = slotType;

            handler.slotIndex = slotIndex;

            handler.tooltipItemDefId = itemId;

            handler.shopByContable = byContableCheck;

            // Drag-drop ekle

            if (itemObj.GetComponent<KOItemDragDrop>() == null)

                itemObj.AddComponent<KOItemDragDrop>();

            return itemObj;

        }

        public void ShowWarp(bool show, bool instant = false)

        {

            if (_uiWarp != null)

            {

                if (show)

                {

                OnPanelOpened(_uiWarp);

                    if (_uiWarp.activeSelf) return;

                    _uiWarp.SetActive(true);

                    _uiWarp.transform.SetAsLastSibling();

                }

                else

                {

                    if (!_uiWarp.activeSelf) return;

                    var slide = _uiWarp.GetComponent<KOUIPanelSlideIn>();

                    if (slide != null && !instant && _uiWarp.activeInHierarchy)

                    {

                        slide.SlideOut(() =>

                        {

                            _uiWarp.SetActive(false);

                            RepositionSkillBarForPanel();

                        });

                    }

                    else

                    {

                        _uiWarp.SetActive(false);

                        RepositionSkillBarForPanel();

                    }

                }

            }

            // C++ UIWarp.cpp:126-133: SetVisible

            // Kapatırken warp state'i temizle — C++ Reset() karşılığı

            if (!show)

            {

                _selectedWarpId = -1;

                _selectedWarpIndex = -1;

                _currentWarpEntries = null;

                if (_textAgreement != null) _textAgreement.text = "";

                foreach (var item in _warpListItems)

                {

                    if (item != null) Destroy(item);

                }

                _warpListItems.Clear();

            }

            RepositionSkillBarForPanel();

        }

        private void ClearPersonalTradeUI()

        {

            UpdateTradeGoldDisplay(true, 0);

            UpdateTradeGoldDisplay(false, 0);

            for (int i = 0; i < 12; i++)

            {

                ClearTradeSlot(true, i);

                ClearTradeSlot(false, i);

            }

        }

        public void ShowPersonalTrade(bool show)

        {

            if (_uiPersonalTrade == null) return;

            if (show)

            {

                _uiPersonalTrade.SetActive(true);

                _uiPersonalTrade.transform.SetAsLastSibling();

                if (_canvas != null && _canvas.scaleFactor > 0f)

                {

                    float s = _canvas.scaleFactor;

                    _uiPersonalTrade.transform.localScale = new Vector3(1f / s, 1f / s, 1f / s);

                }

                // C++ UIPerTradeDlg.cpp GoldUpdate() satır 346-349:

                // m_pStrMyGold->SetStringAsInt(s_pPlayer->m_InfoExt.iGold)

                var gm = EntropyOnline.Core.GameManager.Instance;

                var goldText = KOUIRenderer.FindChildText(_uiPersonalTrade.transform, "string_money_inv");

                if (goldText != null && gm != null)

                {

                    goldText.text = gm.Gold.ToString("N0");

                }

                // Set player name labels in trade window

                var myNameText = KOUIRenderer.FindChildText(_uiPersonalTrade.transform, "text_id_my");

                if (myNameText != null && gm != null)

                {

                    myNameText.text = gm.CharacterName;

                }

                var otherNameText = KOUIRenderer.FindChildText(_uiPersonalTrade.transform, "text_id_other");

                if (otherNameText != null)

                {

                    var otherId = EntropyOnline.Trade.KOTradeManager.Instance != null 

                        ? EntropyOnline.Trade.KOTradeManager.Instance.OtherId 

                        : -1;

                    string otherName = "";

                    if (otherId >= 0 && EntropyOnline.World.EntityManager.Instance != null)

                    {

                        otherName = EntropyOnline.World.EntityManager.Instance.GetEntityName((short)otherId);

                    }

                    if (string.IsNullOrEmpty(otherName))

                    {

                        otherName = otherId >= 0 ? $"Player_{otherId}" : "";

                    }

                    otherNameText.text = otherName;

                }

                // Onay butonlarını ve görünümlerini sıfırla

                SetTradeConfirmButtonState(true, true);

                SetTradeConfirmButtonState(false, true);

                // Clear previous slots and gold to ensure clean start

                ClearPersonalTradeUI();

                // Modernize first to shift slot coordinates correctly

                ModernizePersonalTradePanel(_uiPersonalTrade.transform);

                // Populate player's inventory items inside the trade panel

                PopulateTradeInventory();

                RepositionSkillBarForPanel();

            }

            else

            {

                // Clear trade inventory icons

                foreach (var obj in _tradeInvItems)

                {

                    if (obj != null) Destroy(obj);

                }

                _tradeInvItems.Clear();

                if (KOMessageBox.Instance != null && KOMessageBox.Instance.IsVisible)

                {

                    if (KOMessageBox.Instance.CallerPanel == _uiPersonalTrade ||

                        KOMessageBox.Instance.CurrentBehavior == MsgBoxBehavior.BEHAVIOR_PERSONAL_TRADE_PERMIT ||

                        KOMessageBox.Instance.CurrentBehavior == MsgBoxBehavior.BEHAVIOR_PERSONAL_TRADE_FMT_WAIT)

                    {

                        KOMessageBox.Instance.Hide();

                    }

                }

                var slide = _uiPersonalTrade.GetComponent<KOUIPanelSlideIn>();

                if (slide != null)

                {

                    slide.SlideOut(() => {

                        _uiPersonalTrade.SetActive(false);

                        ClearPersonalTradeUI();

                        RepositionSkillBarForPanel();

                    });

                    RepositionSkillBarForPanel();

                }

                else

                {

                    _uiPersonalTrade.SetActive(false);

                    ClearPersonalTradeUI();

                    RepositionSkillBarForPanel();

                }

            }

        }

        private Vector3 GetLocalPositionRelativeTo(Transform child, Transform targetParent)

        {

            return targetParent.InverseTransformPoint(child.position);

        }

        private Vector3 GetSafeLocalPositionRelativeTo(Transform child, Transform targetParent)

        {

            Vector3 localPos = child.localPosition;

            Transform curr = child.parent;

            while (curr != null && curr != targetParent)

            {

                localPos = new Vector3(localPos.x * curr.localScale.x, localPos.y * curr.localScale.y, localPos.z * curr.localScale.z) + curr.localPosition;

                curr = curr.parent;

            }

            return localPos;

        }

        private void ModernizePersonalTradePanel(Transform root)

        {

            try

            {

                // Force update UI layout by temporarily activating the panel if it is inactive

                bool wasActive = root.gameObject.activeSelf;

                if (!wasActive)

                {

                    root.gameObject.SetActive(true);

                }

                Canvas.ForceUpdateCanvases();

                LayoutRebuilder.ForceRebuildLayoutImmediate(root.GetComponent<RectTransform>());

                bool isModern = IsModernPrefab(root);

                // 1. Disable legacy background images starting with ui_Image_

/* Loop Removed */

/* Loop Removed */

                // 2. Create custom main background GameObject

                var mainRt = root.GetComponent<RectTransform>();

                var customBg = root.Find("PersonalTradeCustomBg")?.gameObject;

                if (customBg == null)

                {

                    customBg = new GameObject("PersonalTradeCustomBg", typeof(RectTransform));

                    customBg.transform.SetParent(root, false);

                    customBg.transform.SetAsFirstSibling(); // Draw behind everything

                    var bgImg = customBg.AddComponent<Image>();

                    var rt = customBg.GetComponent<RectTransform>();

                    if (rt != null && !isModern)

                    {

                        rt.anchorMin = Vector2.zero;

                        rt.anchorMax = Vector2.one;

                        rt.offsetMin = Vector2.zero;

                        rt.offsetMax = Vector2.zero;

                    }

                }

                float headerShiftY = 8f;

                // 3. Create/Style centered header title text matching Warp/Gate panel style

                var titleText = KOUIRenderer.FindChildText(root, "Text_Title") ?? root.Find("Text_Title")?.GetComponent<Text>();

                if (titleText == null)

                {

                    var titleObj = new GameObject("Text_Title", typeof(RectTransform));

                    titleObj.transform.SetParent(root, false);

                    titleText = titleObj.AddComponent<Text>();

                }

                if (titleText != null)

                {

                    titleText.gameObject.SetActive(true);

                    var rt = titleText.GetComponent<RectTransform>();

                    if (rt != null && !isModern)

                    {

                        rt.anchorMin = new Vector2(0.5f, 1f);

                        rt.anchorMax = new Vector2(0.5f, 1f);

                        rt.pivot = new Vector2(0.5f, 1f);

