                        rt.anchoredPosition = new Vector2(0f, -44f + headerShiftY);

                        rt.sizeDelta = new Vector2(330f, 1.5f);

                    }

                }

                // 4. Modernize close button (btn_close)

                var btnClose = KOUIRenderer.FindChildButton(root, "btn_close");

                if (btnClose != null)

                {

                    var closeRt = btnClose.GetComponent<RectTransform>();

                    if (closeRt != null && !isModern)

                    {

