                    AddSkillThemeTextShadow(btnTxt);

                }

                // 5. Hide legacy gold button (btn_gold) as gold click is bound directly to the trade gold capsule

                var btnGold = KOUIRenderer.FindChildButton(root, "btn_gold");

                if (btnGold != null)

                {

                    btnGold.gameObject.SetActive(false);

                }

                // 6. Modernize slot sockets (KOUIArea AreaType 4, 5, 12, 11, 2, 1) using glass theme

                var allAreas = root.GetComponentsInChildren<KOUIArea>(true);

                foreach (var area in allAreas)

                {

                    if (area.AreaType == 4 || area.AreaType == 5 || area.AreaType == 12 || area.AreaType == 11 || area.AreaType == 2 || area.AreaType == 1)

                    {

