                        areaImg.sprite = GetSkillThemeGlassSlotSprite("slot_socket_glass_v5", 45);

                        areaImg.color = Color.white;

                    }

                }

                float topShift = 10f + headerShiftY; // Amount to shift elements upwards to shorten the panel and reduce header gap

                // Shift player inventory slots (AreaType == 12) horizontally to the left by exactly 4.5 pixels and vertically upwards

                if (!isModern)

                {

                    foreach (var area in allAreas)

                    {

                        if (area.AreaType == 12)

                        {

                            var rt = area.GetComponent<RectTransform>();

                            if (rt != null)

                            {

                                var cache = rt.GetComponent<KOUIAreaOriginalPosition>();

                                if (cache == null)

                                {

                                    cache = rt.gameObject.AddComponent<KOUIAreaOriginalPosition>();

                                    cache.Position = rt.anchoredPosition;

                                }

                                var pos = cache.Position;

                                rt.anchoredPosition = new Vector2(pos.x - 4.5f, pos.y + topShift);

                            }

