                                            capsuleRT.anchorMax = new Vector2(btnRT.anchorMax.x, capsuleRT.anchorMax.y);

                                            capsuleRT.pivot = new Vector2(btnRT.pivot.x, btnRT.pivot.y);

                                            capsuleRT.anchoredPosition = new Vector2(btnRT.anchoredPosition.x, btnRT.anchoredPosition.y + 27f);

                                        }

                                    }

                                    if (coinTr != null)

                                    {

                                        coinTr.SetParent(capsuleTr, false);

                                        var coinRT = coinTr.GetComponent<RectTransform>();

                                        if (coinRT != null)

                                        {

                                            coinRT.anchorMin = new Vector2(0f, 0.5f);

                                            coinRT.anchorMax = new Vector2(0f, 0.5f);

                                            coinRT.pivot = new Vector2(0.5f, 0.5f);

                                            coinRT.localScale = Vector3.one;

                                            coinRT.anchoredPosition = new Vector2(12f, 0f);

                                            coinRT.sizeDelta = new Vector2(14f, 14f);

                                            coinTr.gameObject.SetActive(true);

                                        }

                                    }

                                    textRT.SetParent(capsuleTr, false);

                                    textRT.anchorMin = new Vector2(1f, 0.5f);

                                    textRT.anchorMax = new Vector2(1f, 0.5f);

                                    textRT.pivot = new Vector2(1f, 0.5f);

                                    textRT.anchoredPosition = new Vector2(-10f, 0f);

                                    otherTradeGoldText.alignment = TextAnchor.MiddleRight;

                                }

                            }

                            else

                            {

                                if (capsuleTr.parent != originalParent && !isModern)

                                {

                                    capsuleTr.SetParent(originalParent, false);

                                }

                                var capsuleRT = capsuleTr.GetComponent<RectTransform>();

                                var img = capsuleTr.GetComponent<Image>();

                                if (capsuleRT != null && img != null)

                                {

                                    capsuleRT.sizeDelta = new Vector2(tradeBtnWidth, 22f);

                                    img.sprite = GetSkillThemeRoundedRectSprite("string_money_other_gold_capsule_10", (int)tradeBtnWidth, 22, 10,

                                        new Color(0.08f, 0.08f, 0.08f, 0.6f),

                                        new Color(0.45f, 0.35f, 0.15f, 0.8f),

                                        1);

                                    // Align horizontally with btn_trade_other

                                    var localBtnTradeOther = KOUIRenderer.FindChildButton(root, "btn_trade_other");

                                    if (localBtnTradeOther != null && !isModern)

                                    {

                                        var btnRT = localBtnTradeOther.GetComponent<RectTransform>();

                                        if (btnRT != null)

                                        {

                                            capsuleRT.anchorMin = new Vector2(btnRT.anchorMin.x, capsuleRT.anchorMin.y);

                                            capsuleRT.anchorMax = new Vector2(btnRT.anchorMax.x, capsuleRT.anchorMax.y);

                                            capsuleRT.anchoredPosition = new Vector2(btnRT.anchoredPosition.x, capsuleRT.anchoredPosition.y);

                                        }

                                    }

                                }

                            }

                        }

                    }

                }

                if (invGoldText != null)

                {

                    invGoldText.color = Color.white;

                    invGoldText.fontStyle = FontStyle.Bold;

                    AddSkillThemeTextShadow(invGoldText);

                    var textRT = invGoldText.GetComponent<RectTransform>();

                    var coinTr = originalCoinInv;

                    if (textRT != null)

                    {

                        var originalParent = textRT.parent;

                        if (originalParent != null && originalParent.name == "string_money_inv_Capsule")

                        {

                            originalParent = originalParent.parent;

                        }

                        if (originalParent != null)

                        {

                            if (originalCoinInv == null && originalCoinMy != null)

                            {

                                var newCoin = Instantiate(originalCoinMy.gameObject, originalParent, false);

                                newCoin.name = "img_gold_inv";

                                originalCoinInv = newCoin.transform;

                                coinTr = originalCoinInv;

                            }

                            var capsuleTr = originalParent.Find("string_money_inv_Capsule");

                            if (capsuleTr == null)

                            {

                                var originalLocalPos = textRT.localPosition;

                                var originalAnchorMin = textRT.anchorMin;

                                var originalAnchorMax = textRT.anchorMax;

                                var originalPivot = textRT.pivot;

                                var capsuleObj = new GameObject("string_money_inv_Capsule", typeof(RectTransform));

                                capsuleObj.transform.SetParent(originalParent, false);

                                capsuleTr = capsuleObj.transform;

                                var img = capsuleTr.gameObject.AddComponent<Image>();

                                img.raycastTarget = true;

                                var capsuleRT = capsuleTr.GetComponent<RectTransform>();

                                if (capsuleRT != null)

                                {

                                    // Calculate right edge of the original 110px capsule

                                    float rightEdge = originalLocalPos.x + (110f * (1f - originalPivot.x));

                                    capsuleRT.anchorMin = originalAnchorMin;

                                    capsuleRT.anchorMax = originalAnchorMax;

                                    capsuleRT.pivot = new Vector2(1f, originalPivot.y); // Set pivot x to 1f (right edge)

                                    capsuleRT.sizeDelta = new Vector2(tradeBtnWidth, 22f);

                                    capsuleRT.localPosition = new Vector3(rightEdge, originalLocalPos.y, originalLocalPos.z);

                                    img.sprite = GetSkillThemeRoundedRectSprite("string_money_inv_gold_capsule_10", (int)tradeBtnWidth, 22, 10,

                                        new Color(0.08f, 0.08f, 0.08f, 0.6f),

                                        new Color(0.45f, 0.35f, 0.15f, 0.8f),

                                        1);

                                    if (coinTr != null)

                                    {

                                        coinTr.SetParent(capsuleTr, false);

                                        var coinRT = coinTr.GetComponent<RectTransform>();

                                        if (coinRT != null)

                                        {

                                            coinRT.anchorMin = new Vector2(0f, 0.5f);

                                            coinRT.anchorMax = new Vector2(0f, 0.5f);

                                            coinRT.pivot = new Vector2(0.5f, 0.5f);

                                            coinRT.localScale = Vector3.one;

                                            coinRT.anchoredPosition = new Vector2(12f, 0f);

                                            coinRT.sizeDelta = new Vector2(14f, 14f);

                                            coinTr.gameObject.SetActive(true);

                                        }

                                    }

                                    textRT.SetParent(capsuleTr, false);

                                    textRT.anchorMin = new Vector2(1f, 0.5f);

                                    textRT.anchorMax = new Vector2(1f, 0.5f);

                                    textRT.pivot = new Vector2(1f, 0.5f);

                                    textRT.anchoredPosition = new Vector2(-10f, 0f);

                                    invGoldText.alignment = TextAnchor.MiddleRight;

                                }

                            }

                            else

                            {

                                if (capsuleTr.parent != originalParent && !isModern)

                                {

                                    capsuleTr.SetParent(originalParent, false);

                                }

                                var capsuleRT = capsuleTr.GetComponent<RectTransform>();

                                var img = capsuleTr.GetComponent<Image>();

                                if (capsuleRT != null && img != null)

                                {

                                    img.raycastTarget = true;

                                    if (!isModern)

                                    {

                                        // Adjust pivot and position of existing capsule to align right edge

                                        var cache = capsuleRT.GetComponent<KOUIAreaOriginalPosition>();

                                        if (cache == null)

                                        {

                                            cache = capsuleRT.gameObject.AddComponent<KOUIAreaOriginalPosition>();

                                            cache.Position = capsuleRT.anchoredPosition;

                                        }

                                        var origPos = cache.Position;

                                        capsuleRT.pivot = new Vector2(1f, capsuleRT.pivot.y);

                                        capsuleRT.anchoredPosition = new Vector2(origPos.x + 55f, origPos.y);

                                    }

                                    capsuleRT.sizeDelta = new Vector2(tradeBtnWidth, 22f);

                                    img.sprite = GetSkillThemeRoundedRectSprite("string_money_inv_gold_capsule_10", (int)tradeBtnWidth, 22, 10,

                                        new Color(0.08f, 0.08f, 0.08f, 0.6f),

                                        new Color(0.45f, 0.35f, 0.15f, 0.8f),

                                        1);

                                }

                            }

                            // Remove button click on the capsule to prevent triggering gold input dialog

                            if (capsuleTr != null)

                            {

                                var btn = capsuleTr.gameObject.GetComponent<Button>();

                                if (btn != null)

                                {

                                    Destroy(btn);

                                }

                            }

                        }

                    }

                }

                // Parent the trade button texts (which are siblings in the original prefab) to their buttons

                var tBtnMy = KOUIRenderer.FindChildButton(root, "btn_trade_my");

                var tBtnOther = KOUIRenderer.FindChildButton(root, "btn_trade_other");

                var allTexts = root.GetComponentsInChildren<Text>(true);

                foreach (var txt in allTexts)

                {

                    string name = txt.gameObject.name;

                    // If it was already parented in a previous run, check if it's the shadow text

                    if (txt.transform.parent != null && (txt.transform.parent.name == "btn_trade_my" || txt.transform.parent.name == "btn_trade_other"))

                    {

                        if (txt.color.r < 0.15f && txt.color.g < 0.15f && txt.color.b < 0.15f)

                        {

                            txt.gameObject.SetActive(false);

                            continue;

                        }

                    }

                    // Check if this is the duplicate shadow text for the player name labels or gold labels (nearly black color)

                    if (name == "text_id_my" || name == "text_id_other" ||

                        name == "string_money_my" || name == "string_money_other" || name == "string_money_inv")

                    {

                        if (txt.color.r < 0.15f && txt.color.g < 0.15f && txt.color.b < 0.15f)

                        {

                            txt.gameObject.SetActive(false); // Hide the shadow text completely

                            continue;

                        }

                    }

                    if (!isModern)

                    {

                        float x = txt.rectTransform.anchoredPosition.x;

                        float y = txt.rectTransform.anchoredPosition.y;

                        // Original trade text labels are around y = -289

                        if (y >= -295f && y <= -280f)

                        {

                            // Check if this is the duplicate shadow text (nearly black color)

                            if (txt.color.r < 0.15f && txt.color.g < 0.15f && txt.color.b < 0.15f)

                            {

                                txt.gameObject.SetActive(false); // Hide the shadow text completely

                                continue;

                            }

                            if (x < 100f && tBtnMy != null)

                            {

                                txt.transform.SetParent(tBtnMy.transform, false);

                                var rt = txt.rectTransform;

                                rt.anchorMin = Vector2.zero;

                                rt.anchorMax = Vector2.one;

                                rt.offsetMin = Vector2.zero;

                                rt.offsetMax = Vector2.zero;

                                txt.alignment = TextAnchor.MiddleCenter;

                                txt.verticalOverflow = VerticalWrapMode.Overflow;

                            }

                            else if (x > 150f && tBtnOther != null)

                            {

                                txt.transform.SetParent(tBtnOther.transform, false);

                                var rt = txt.rectTransform;

                                rt.anchorMin = Vector2.zero;

                                rt.anchorMax = Vector2.one;

                                rt.offsetMin = Vector2.zero;

                                rt.offsetMax = Vector2.zero;

                                txt.alignment = TextAnchor.MiddleCenter;

                                txt.verticalOverflow = VerticalWrapMode.Overflow;

                            }

                        }

                    }

                }

                // Apply gold/bold styling to name labels, and white styling to gold amounts

                var texts = root.GetComponentsInChildren<Text>(true);

                foreach (var txt in texts)

                {

                    string name = txt.gameObject.name;

                    if (name.StartsWith("string_name_") || name == "text_id_my" || name == "text_id_other")

                    {

                        txt.color = new Color(0.95f, 0.85f, 0.35f, 1);

                        txt.fontStyle = FontStyle.Bold;

                        AddSkillThemeTextShadow(txt);

                    }

                    else if (name.StartsWith("string_money_") || name.StartsWith("string_gold_"))

                    {

                        txt.color = Color.white;

                        txt.fontStyle = FontStyle.Bold;

                        AddSkillThemeTextShadow(txt);

                    }

                }

                // 8. Modernize other buttons (like confirm buttons)

                var buttons = root.GetComponentsInChildren<UnityEngine.UI.Button>(true);

                foreach (var btn in buttons)

                {

                    string name = btn.gameObject.name;

                    if (name != "btn_close" && name != "btn_gold")

                    {

                        var rt = btn.GetComponent<RectTransform>();

                        if (rt != null)

                        {

                            rt.sizeDelta = new Vector2(rt.sizeDelta.x, 24f); // Set height to 24 to prevent bottom clipping

                        }

                        SetButtonThemeSprite(btn, GetSkillThemeRoundedRectSprite("trade_btn_" + name + "_10", (int)(rt != null ? rt.sizeDelta.x : 120), 24, 10,

                            new Color(0.2f, 0.18f, 0.15f, 1f),

                            new Color(0.6f, 0.48f, 0.22f, 1f),

                            1));

                        var txt = btn.GetComponentInChildren<Text>();

                        if (txt != null)

                        {

                            // Clear any existing legacy/modern outline or shadow components

                            var comps = txt.GetComponents<Component>();

                            foreach (var comp in comps)

                            {

                                if (comp == null) continue;

                                string typeName = comp.GetType().Name;

                                if (typeName.Contains("Shadow") || typeName.Contains("Outline") || typeName.Contains("Effect"))

                                {

                                    DestroyImmediate(comp);

                                }

                            }

                            txt.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");

                            txt.material = null; // Reset material to default to prevent any custom outline/blur shaders

                            txt.transform.localScale = Vector3.one;

                            txt.resizeTextForBestFit = false;

                            txt.color = new Color(0.95f, 0.85f, 0.35f, 1f); // Premium gold color

                            txt.fontStyle = FontStyle.Normal; // Normal style for crisp vectors at small size

                            txt.fontSize = 12;

                            txt.alignment = TextAnchor.MiddleCenter;

                            txt.verticalOverflow = VerticalWrapMode.Overflow;

                            txt.horizontalOverflow = HorizontalWrapMode.Overflow;

                        }

                    }

                }

                // Bind button click on the MY trade gold capsule to trigger gold input dialog

                if (myTradeGoldText != null)

                {

                    var myGoldCapsule = myTradeGoldText.transform.parent;

                    if (myGoldCapsule != null && myGoldCapsule.name == "string_money_my_Capsule")

                    {

                        var img = myGoldCapsule.GetComponent<Image>();

                        if (img != null)

                        {

                            img.raycastTarget = true;

                            img.color = Color.white; // Explicitly reset color to white to clear any previous grey tint

                        }

                        // Explicitly disable raycasting on child text and coin icon to prevent them from blocking/swallowing click events

                        myTradeGoldText.raycastTarget = false;

                        if (originalCoinMy != null)

                        {

                            var coinImg = originalCoinMy.GetComponent<Image>();

                            if (coinImg != null) coinImg.raycastTarget = false;

                            var coinRaw = originalCoinMy.GetComponent<RawImage>();

                            if (coinRaw != null) coinRaw.raycastTarget = false;

                        }

                        var btn = myGoldCapsule.gameObject.GetComponent<Button>() ?? myGoldCapsule.gameObject.AddComponent<Button>();

                        btn.interactable = true;

                        btn.transition = Selectable.Transition.None; // Prevent button component from changing/tinting the capsule color

                        btn.onClick.RemoveAllListeners();

                        btn.onClick.AddListener(() =>

                        {

                            var inst = EntropyOnline.Trade.KOTradeManager.Instance;

                            if (inst != null)

                            {

                                inst.RequestItemCountEdit();

                            }

                        });

                    }

                }

                // Debug toast removed as requested

                // --- CUSTOM CENTERING OF SLOTS AND UI ELEMENTS ---

                // Helper to shift any RectTransform relative to its original position without changing anchors/pivots

                void ShiftElement(RectTransform rt, float offsetX, float offsetY = 0f)

                {

                    if (rt == null) return;

                    var cache = rt.GetComponent<KOUIAreaOriginalPosition>();

                    if (cache == null)

                    {

                        cache = rt.gameObject.AddComponent<KOUIAreaOriginalPosition>();

                        cache.Position = rt.anchoredPosition;

                    }

                    var origPos = cache.Position;

                    rt.anchoredPosition = new Vector2(origPos.x + offsetX, origPos.y + offsetY);

                }

                // 1. Center all top slot grids (AreaType 4 and 5) and shift vertically

                if (!isModern)

                {

                    foreach (var area in allAreas)

                    {

                        if (area.AreaType == 4 || area.AreaType == 5)

                        {

                            ShiftElement(area.GetComponent<RectTransform>(), -9.0f, topShift);

                        }

                    }

                    // 2. Center top labels and buttons and shift vertically

                    var btnTradeMy = KOUIRenderer.FindChildButton(root, "btn_trade_my");

                    if (btnTradeMy != null) ShiftElement(btnTradeMy.GetComponent<RectTransform>(), -9.0f, topShift);

                    var btnTradeOther = KOUIRenderer.FindChildButton(root, "btn_trade_other");

                    if (btnTradeOther != null) ShiftElement(btnTradeOther.GetComponent<RectTransform>(), -9.0f, topShift);

                }

                // Center and style top player name labels (aligned with trade slot grids)

                var textIdMy = KOUIRenderer.FindChildText(root, "text_id_my");

                var textIdOther = KOUIRenderer.FindChildText(root, "text_id_other");

                // Calculate bounds for My slots (AreaType 4)

                float myGridLeft = 0f;

                float myGridRight = 0f;

                float myGridTopY = 0f;

                bool foundMyGrid = false;

                // Calculate bounds for Other slots (AreaType 5)

                float otherGridLeft = 0f;

                float otherGridRight = 0f;

                float otherGridTopY = 0f;

                bool foundOtherGrid = false;

                foreach (var area in allAreas)

                {

                    var rt = area.GetComponent<RectTransform>();

                    if (rt != null)

                    {

                        if (area.AreaType == 4)

                        {

                            float leftEdge = rt.anchoredPosition.x;

                            float rightEdge = rt.anchoredPosition.x + rt.rect.width;

                            float topEdge = rt.anchoredPosition.y;

                            if (!foundMyGrid)

                            {

                                myGridLeft = leftEdge;

                                myGridRight = rightEdge;

                                myGridTopY = topEdge;

                                foundMyGrid = true;

                            }

                            else

                            {

                                if (leftEdge < myGridLeft) myGridLeft = leftEdge;

                                if (rightEdge > myGridRight) myGridRight = rightEdge;

                                if (topEdge > myGridTopY) myGridTopY = topEdge;

                            }

                        }

                        else if (area.AreaType == 5)

                        {

                            float leftEdge = rt.anchoredPosition.x;

                            float rightEdge = rt.anchoredPosition.x + rt.rect.width;

                            float topEdge = rt.anchoredPosition.y;

                            if (!foundOtherGrid)

                            {

                                otherGridLeft = leftEdge;

                                otherGridRight = rightEdge;

                                otherGridTopY = topEdge;

                                foundOtherGrid = true;

                            }

                            else

                            {

                                if (leftEdge < otherGridLeft) otherGridLeft = leftEdge;

                                if (rightEdge > otherGridRight) otherGridRight = rightEdge;

                                if (topEdge > otherGridTopY) otherGridTopY = topEdge;

                            }

                        }

                    }

                }

                float myGridWidth = foundMyGrid ? (myGridRight - myGridLeft) : 135f;

                float myGridCenter = foundMyGrid ? (myGridLeft + myGridRight) / 2f : 78f;

                float myGridTop = foundMyGrid ? myGridTopY : -96f;

                float otherGridWidth = foundOtherGrid ? (otherGridRight - otherGridLeft) : 135f;

                float otherGridCenter = foundOtherGrid ? (otherGridLeft + otherGridRight) / 2f : 246f;

                float otherGridTop = foundOtherGrid ? otherGridTopY : -96f;

                // Position names slightly closer to slot grids: bottom edge of backing plate is 8px above slots.

                // Since backing plate height is 28px, center Y = gridTop + 8px + (28px / 2) = gridTop + 22px.

                float targetYMy = myGridTop + 22f;

                float targetYOther = otherGridTop + 22f;

                if (textIdMy != null)

                {

                    var rt = textIdMy.GetComponent<RectTransform>();

                    if (rt != null)

                    {

                        // Clean legacy shadow texts on this component if any

                        var comps = textIdMy.GetComponents<Component>();

                        foreach (var comp in comps)

                        {

                            if (comp == null) continue;

                            string typeName = comp.GetType().Name;

                            if (typeName.Contains("Shadow") || typeName.Contains("Outline") || typeName.Contains("Effect"))

                            {

                                DestroyImmediate(comp);

                            }

                        }

                        var originalParent = rt.parent;

                        if (originalParent != null && originalParent.name == "text_id_my_Bg")

                        {

                            originalParent = originalParent.parent;

                        }

                        if (originalParent != null)

                        {

                            var bgTr = originalParent.Find("text_id_my_Bg");

                            Image bgImg = null;

                            if (bgTr == null)

                            {

                                var bgObj = new GameObject("text_id_my_Bg", typeof(RectTransform));

                                bgObj.transform.SetParent(originalParent, false);

                                bgTr = bgObj.transform;

                                bgImg = bgObj.AddComponent<Image>();

                            }

                            else

                            {

                                bgImg = bgTr.GetComponent<Image>();

                            }

                            var bgRT = bgTr.GetComponent<RectTransform>();

                            if (bgRT != null && !isModern)

                            {

                                // Align horizontally centered over myGrid, pivot in center for precise gap calculations

                                bgRT.anchorMin = new Vector2(0f, 1f); // Anchor to top-left of parent

                                bgRT.anchorMax = new Vector2(0f, 1f); // Anchor to top-left of parent

                                bgRT.pivot = new Vector2(0.5f, 0.5f); // Center pivot

                                bgRT.sizeDelta = new Vector2(myGridWidth, 28f); // Increased height to 28px

                                bgRT.anchoredPosition = new Vector2(myGridCenter, targetYMy);

                            }

                            if (bgImg != null)

                            {

                                int wInt = Mathf.RoundToInt(myGridWidth);

                                bgImg.sprite = GetFadeGradientSprite($"trade_name_my_fade_bg_{wInt}_28", wInt, 28, Color.white, Color.clear, 0);

                                bgImg.color = new Color(0.6f, 0.48f, 0.22f, 0.25f);

                                bgImg.raycastTarget = false;

                            }

                            if (!isModern)

                            {

                                rt.SetParent(bgTr, false);

                                rt.anchorMin = Vector2.zero;

                                rt.anchorMax = Vector2.one;

                                rt.pivot = new Vector2(0.5f, 0.5f);

                                rt.offsetMin = Vector2.zero;

                                rt.offsetMax = Vector2.zero;

                            }

                        }

                        // Style name text

                        textIdMy.text = (GameManager.Instance != null) ? GameManager.Instance.CharacterName : "";

                        textIdMy.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");

                        textIdMy.material = null;

                        textIdMy.transform.localScale = Vector3.one;

                        textIdMy.resizeTextForBestFit = false;

                        textIdMy.color = Color.white; // Solid white

                        textIdMy.fontStyle = FontStyle.Bold; // Bold style

                        textIdMy.fontSize = 12; // Nickname tag size

                        textIdMy.alignment = TextAnchor.MiddleCenter;

                        textIdMy.verticalOverflow = VerticalWrapMode.Overflow;

                        textIdMy.horizontalOverflow = HorizontalWrapMode.Overflow;

                    }

                }

                if (textIdOther != null)

                {

                    var rt = textIdOther.GetComponent<RectTransform>();

                    if (rt != null)

                    {

                        // Clean legacy shadow texts on this component if any

                        var comps = textIdOther.GetComponents<Component>();

                        foreach (var comp in comps)

                        {

                            if (comp == null) continue;

                            string typeName = comp.GetType().Name;

                            if (typeName.Contains("Shadow") || typeName.Contains("Outline") || typeName.Contains("Effect"))

                            {

                                DestroyImmediate(comp);

                            }

                        }

                        var originalParent = rt.parent;

                        if (originalParent != null && originalParent.name == "text_id_other_Bg")

                        {

                            originalParent = originalParent.parent;

                        }

                        if (originalParent != null)

                        {

                            var bgTr = originalParent.Find("text_id_other_Bg");

                            Image bgImg = null;

                            if (bgTr == null)

                            {

                                var bgObj = new GameObject("text_id_other_Bg", typeof(RectTransform));

                                bgObj.transform.SetParent(originalParent, false);

                                bgTr = bgObj.transform;

                                bgImg = bgObj.AddComponent<Image>();

                            }

                            else

                            {

                                bgImg = bgTr.GetComponent<Image>();

                            }

                            var bgRT = bgTr.GetComponent<RectTransform>();

                            if (bgRT != null && !isModern)

                            {

                                // Align horizontally centered over otherGrid, pivot in center for precise gap calculations

                                bgRT.anchorMin = new Vector2(0f, 1f); // Anchor to top-left of parent

                                bgRT.anchorMax = new Vector2(0f, 1f); // Anchor to top-left of parent

                                bgRT.pivot = new Vector2(0.5f, 0.5f); // Center pivot

                                bgRT.sizeDelta = new Vector2(otherGridWidth, 28f); // Increased height to 28px

                                bgRT.anchoredPosition = new Vector2(otherGridCenter, targetYOther);

                            }

                            if (bgImg != null)

                            {

                                int wInt = Mathf.RoundToInt(otherGridWidth);

                                bgImg.sprite = GetFadeGradientSprite($"trade_name_other_fade_bg_{wInt}_28", wInt, 28, Color.white, Color.clear, 0);

                                bgImg.color = new Color(0.6f, 0.48f, 0.22f, 0.25f);

                                bgImg.raycastTarget = false;

                            }

                            if (!isModern)

                            {

                                rt.SetParent(bgTr, false);

                                rt.anchorMin = Vector2.zero;

                                rt.anchorMax = Vector2.one;

                                rt.pivot = new Vector2(0.5f, 0.5f);

                                rt.offsetMin = Vector2.zero;

                                rt.offsetMax = Vector2.zero;

                            }

                        }

                        // Style name text

                        textIdOther.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");

                        textIdOther.material = null;

                        textIdOther.transform.localScale = Vector3.one;

                        textIdOther.resizeTextForBestFit = false;

                        textIdOther.color = Color.white; // Solid white

                        textIdOther.fontStyle = FontStyle.Bold; // Bold style

                        textIdOther.fontSize = 12; // Nickname tag size

                        textIdOther.alignment = TextAnchor.MiddleCenter;

                        textIdOther.verticalOverflow = VerticalWrapMode.Overflow;

                        textIdOther.horizontalOverflow = HorizontalWrapMode.Overflow;

                    }

                }

                if (!isModern)

                {

                    var capsuleMy = root.Find("string_money_my_Capsule") ?? root.GetComponentInChildren<RectTransform>().Find("string_money_my_Capsule");

                    if (capsuleMy != null) ShiftElement(capsuleMy.GetComponent<RectTransform>(), -9.0f, topShift);

                    var capsuleOther = root.Find("string_money_other_Capsule") ?? root.GetComponentInChildren<RectTransform>().Find("string_money_other_Capsule");

                    if (capsuleOther != null) ShiftElement(capsuleOther.GetComponent<RectTransform>(), -9.0f, topShift);

                    // 3. Center bottom gold capsule

                    var capsuleInv = root.Find("string_money_inv_Capsule") ?? root.GetComponentInChildren<RectTransform>().Find("string_money_inv_Capsule");

                    if (capsuleInv != null) ShiftElement(capsuleInv.GetComponent<RectTransform>(), -4.5f, topShift);

                }

                // --- DYNAMIC HEIGHT CALIBRATION (To make bottom gap equal to side margin) ---

                if (mainRt != null)

                {

                    float newHeight = mainRt.sizeDelta.y;

                    if (!isModern)

                    {

                        float leftmostX = 15f;

                        float bottommostY = -550f;

                        bool foundX = false;

                        bool foundY = false;

                        foreach (var area in allAreas)

                        {

                            if (area.AreaType == 12)

                            {

                                var rt = area.GetComponent<RectTransform>();

                                if (rt != null)

                                {

                                    float leftEdge = rt.anchoredPosition.x;

                                    float bottomEdge = rt.anchoredPosition.y - rt.rect.height;

                                    if (!foundX)

                                    {

                                        leftmostX = leftEdge;

                                        foundX = true;

                                    }

                                    else

                                    {

                                        if (leftEdge < leftmostX) leftmostX = leftEdge;

                                    }

                                    if (!foundY || bottomEdge < bottommostY)

                                    {

                                        bottommostY = bottomEdge;

                                        foundY = true;

                                    }

                                }

                            }

                        }

                        float sideMargin = foundX ? leftmostX : 15f;

                        if (sideMargin < 0f) sideMargin = 15f;

                        // The new height is: sideMargin + |bottommostY|

                        newHeight = sideMargin - bottommostY;

                        // Clamp to make sure we don't go out of bounds

                        if (newHeight < 400f || newHeight > 650f)

                        {

                            newHeight = 560f;

                        }

                        mainRt.sizeDelta = new Vector2(364f, newHeight);

                    }

                    // Re-generate background sprite with correct height

                    var bgImg = customBg != null ? customBg.GetComponent<Image>() : null;

                    if (bgImg != null)

                    {

                        bgImg.sprite = GetSkillThemePanelBgSprite("personal_trade_custom_bg", 364, (int)newHeight, 0,

                            new Color(0.12f, 0.10f, 0.08f, 0.98f),

                            new Color(0.04f, 0.04f, 0.04f, 0.98f),

                            new Color(0.6f, 0.48f, 0.22f, 0.9f),

                            2);

                        bgImg.color = Color.white;

                    }

                }

                ForceEnableUIComponents(root);

                // Restore active state

                if (!wasActive)

                {

                    root.gameObject.SetActive(false);

                }

            }

            catch (System.Exception ex)

            {

                Debug.LogError($"[KOUIMGR] Error in ModernizePersonalTradePanel: {ex.Message}");

            }

        }

        private void ModernizeMerchantSetupPanel(Transform root)

        {

            try

            {

                // Force update UI layout

                bool wasActive = root.gameObject.activeSelf;

                if (!wasActive)

                {

                    root.gameObject.SetActive(true);

                }

                Canvas.ForceUpdateCanvases();

                LayoutRebuilder.ForceRebuildLayoutImmediate(root.GetComponent<RectTransform>());

                // Adjust root size delta to shorten the panel

                var rootRt = root.GetComponent<RectTransform>();

                if (rootRt != null)

                {

                    rootRt.sizeDelta = new Vector2(362f, 400f);

                }

                // 1. Orijinal otomatik oluşturulmuş arka plan görsellerini (ui_Image_*) kapat

/* Loop Removed */

/* Loop Removed */

                // 2. Koyu premium ana arka plan oluştur ve ata (362x400, keskin köşeler)

                var customBg = root.Find("MerchantSetupCustomBg")?.gameObject;

                if (customBg == null)

                {

                    customBg = new GameObject("MerchantSetupCustomBg", typeof(RectTransform));

                    customBg.transform.SetParent(root, false);

                    customBg.transform.SetAsFirstSibling(); // En arkaya yerleştir

                    customBg.AddComponent<Image>();

                    var rt = customBg.GetComponent<RectTransform>();

                    if (rt != null)

                    {

                        rt.anchorMin = Vector2.zero;

                        rt.anchorMax = Vector2.one;

                        rt.offsetMin = Vector2.zero;

                        rt.offsetMax = Vector2.zero;

                    }

                }

                var bgImg = customBg.GetComponent<Image>();

                if (bgImg != null)

                {

                    bgImg.sprite = GetSkillThemePanelBgSprite("merchant_setup_bg_v2", 362, 400, 0,

                        new Color(0.12f, 0.10f, 0.08f, 0.98f),

                        new Color(0.04f, 0.04f, 0.04f, 0.98f),

                        new Color(0.6f, 0.48f, 0.22f, 0.9f),

                        2);

                    bgImg.color = Color.white;

                }

                // Check if title already exists to avoid double modernization/shifting

                var titleText = root.Find("Text_Title")?.GetComponent<Text>();

                bool isFirstTime = (titleText == null);

                // Add header title text (Style matching SKILL PAGE)

                if (titleText == null)

                {

                    var titleObj = new GameObject("Text_Title", typeof(RectTransform));

                    titleObj.transform.SetParent(root, false);

                    titleText = titleObj.AddComponent<Text>();

                }

                if (titleText != null)

                {

                    titleText.gameObject.SetActive(true);

                    var rt = titleText.GetComponent<RectTransform>();

                    if (rt != null)

                    {

                        rt.anchorMin = new Vector2(0.5f, 1f);

                        rt.anchorMax = new Vector2(0.5f, 1f);

                        rt.pivot = new Vector2(0.5f, 1f);

                        rt.sizeDelta = new Vector2(250f, 30f);

                        rt.anchoredPosition = new Vector2(0f, -4f);

                    }

                    titleText.text = "Create a Merchant";

                    titleText.font = GetSafeFont(14);

                    titleText.color = new Color(0.95f, 0.85f, 0.35f, 1f);

                    titleText.fontStyle = FontStyle.Bold;

                    titleText.fontSize = 14;

                    titleText.alignment = TextAnchor.MiddleCenter;

                    AddSkillThemeTextShadow(titleText);

                }

                // Add title divider

                var dividerObj = root.Find("SkillTitleDivider")?.gameObject;

                if (dividerObj == null)

                {

                    dividerObj = new GameObject("SkillTitleDivider", typeof(RectTransform));

                    dividerObj.transform.SetParent(root, false);

                    var divRt = dividerObj.GetComponent<RectTransform>();

                    if (divRt != null)

                    {

                        divRt.anchorMin = new Vector2(0.5f, 1f);

                        divRt.anchorMax = new Vector2(0.5f, 1f);

                        divRt.pivot = new Vector2(0.5f, 1f);

                        divRt.sizeDelta = new Vector2(280f, 2f);

                        divRt.anchoredPosition = new Vector2(0f, -34f);

                    }

                }

                var dividerImg = dividerObj.GetComponent<Image>() ?? dividerObj.AddComponent<Image>();

                dividerImg.sprite = GetSkillThemeFadingDividerSprite("merchant_title_divider", 280, 2, new Color(0.9f, 0.75f, 0.25f, 0.8f));

                dividerImg.color = Color.white;

                // Add grid divider

                var gridDividerObj = root.Find("MerchantGridDivider")?.gameObject;

                if (gridDividerObj == null)

                {

                    gridDividerObj = new GameObject("MerchantGridDivider", typeof(RectTransform));

                    gridDividerObj.transform.SetParent(root, false);

                    var gridDivRt = gridDividerObj.GetComponent<RectTransform>();

                    if (gridDivRt != null)

                    {

                        gridDivRt.anchorMin = new Vector2(0.5f, 1f);

                        gridDivRt.anchorMax = new Vector2(0.5f, 1f);

                        gridDivRt.pivot = new Vector2(0.5f, 1f);

                        gridDivRt.sizeDelta = new Vector2(280f, 2f);

                        gridDivRt.anchoredPosition = new Vector2(0f, -159f);

                    }

                }

                var gridDividerImg = gridDividerObj.GetComponent<Image>() ?? gridDividerObj.AddComponent<Image>();

                gridDividerImg.sprite = GetSkillThemeFadingDividerSprite("merchant_grid_divider", 280, 2, new Color(0.9f, 0.75f, 0.25f, 0.8f));

                gridDividerImg.color = Color.white;

                // Shift all children except custom background, title and divider down by 25 units

                if (isFirstTime)

                {

                    int shiftAmount = 25;

                    for (int i = 0; i < root.childCount; i++)

                    {

                        var child = root.GetChild(i);

                        if (child.name != "MerchantSetupCustomBg" &&

                            child.name != "Text_Title" &&

                            child.name != "SkillTitleDivider" &&

                            child.name != "MerchantGridDivider")

                        {

                            var childRt = child.GetComponent<RectTransform>();

                            if (childRt != null)

                            {

                                var pos = childRt.anchoredPosition;

                                pos.y -= shiftAmount;

                                // Center slot grids horizontally inside the 362px wide panel

                                string name = child.name;

                                // 12-slot grid and their price/name texts (shift left by 9px)

                                if ((name.StartsWith("at") && name.Length > 2 && char.IsDigit(name[2])) ||

                                    (name.StartsWith("st") && name.Length > 2 && char.IsDigit(name[2])))

                                {

                                    pos.x -= 9f;

                                }

                                // 28-slot grid slots (shift left by 8px)

                                else if (name.StartsWith("a") && name.Length > 1 && char.IsDigit(name[1]))

                                {

                                    if (!name.StartsWith("at"))

                                    {

                                        pos.x -= 8f;

                                    }

                                }

                                // 28-slot grid count/amount text overlays (shift left by 8px)

                                else if (int.TryParse(name, out int numVal) && numVal >= 200 && numVal <= 227)

                                {

                                    pos.x -= 8f;

                                }

                                childRt.anchoredPosition = pos;

                            }

                        }

                    }

                }

                // 3. Slotların zeminlerini modernize et (cam tasarımı)

                var allAreas = root.GetComponentsInChildren<KOUIArea>(true);

                foreach (var area in allAreas)

                {

                    var areaImg = area.GetComponent<Image>() ?? area.gameObject.AddComponent<Image>();

                    areaImg.sprite = GetSkillThemeGlassSlotSprite("slot_socket_glass_v5", 45);

                    areaImg.color = Color.white;

                }

                // 4. InputField (edit_message) modernize et (pasif ve gizli)

                var editMsgObj = KOUIRenderer.FindChildByID(root, "edit_message");

                if (editMsgObj != null)

                {

                    editMsgObj.gameObject.SetActive(false);

                    var oldRaw = editMsgObj.GetComponent<RawImage>();

                    if (oldRaw != null) UnityEngine.Object.DestroyImmediate(oldRaw);

                    var inputBg = editMsgObj.GetComponent<Image>() ?? editMsgObj.gameObject.AddComponent<Image>();

                    inputBg.sprite = GetSkillThemeRoundedRectSprite("input_custom_bg", 320, 51, 0,

                        new Color(0.04f, 0.04f, 0.04f, 0.9f),

                        new Color(0.45f, 0.35f, 0.15f, 0.6f),

                        1);

                    inputBg.color = Color.white;

                    var placeholder = editMsgObj.transform.Find("Placeholder")?.GetComponent<Text>();

                    if (placeholder != null)

                    {

                        placeholder.color = new Color(0.6f, 0.6f, 0.6f, 1f);

                        placeholder.font = GetSafeFont(11);

                    }

                    var textComp = editMsgObj.transform.Find("Text")?.GetComponent<Text>();

                    if (textComp != null)

                    {

                        textComp.color = Color.white;

                        textComp.font = GetSafeFont(11);

                    }

                }

                // 5. Butonları (btn_ok, btn_cancel) modernize et ve yukarı taşı (Item Upgrade stili)

                string[] origTextNames = { "ui_String_6B95857C", "ui_String_F4003A8", "ui_String_56950000", "ui_String_B2EA81D4" };

                foreach (var tName in origTextNames)

                {

                    var tTr = root.Find(tName);

                    if (tTr != null) tTr.gameObject.SetActive(false);

                }

                Color greenBg = new Color(0.12f, 0.28f, 0.12f, 0.95f);

                Color greenBorder = new Color(0.25f, 0.55f, 0.25f, 0.95f);

                Color redBg = new Color(0.45f, 0.05f, 0.08f, 0.95f);

                Color redBorder = new Color(0.75f, 0.15f, 0.15f, 0.95f);

                var btnOk = KOUIRenderer.FindChildButton(root, "btn_ok");

                if (btnOk != null)

                {

                    var okRt = btnOk.GetComponent<RectTransform>();

                    if (okRt != null)

                    {

                        okRt.anchorMin = new Vector2(0f, 1f);

                        okRt.anchorMax = new Vector2(0f, 1f);

                        okRt.pivot = new Vector2(0.5f, 0.5f);

                        okRt.sizeDelta = new Vector2(104f, 26f);

                        okRt.anchoredPosition = new Vector2(121f, -378f);

                    }

                    var oldRaw = btnOk.GetComponent<RawImage>();

                    if (oldRaw != null) UnityEngine.Object.DestroyImmediate(oldRaw);

                    var img = btnOk.GetComponent<Image>();

                    if (img == null) img = btnOk.gameObject.AddComponent<Image>();

                    img.sprite = GetSkillThemeRoundedRectSprite("merchant_btn_ok_bg", 104, 26, 0, greenBg, greenBorder, 1);

                    img.color = Color.white;

                    var btn = btnOk.GetComponent<Button>();

                    if (btn != null)

                    {

                        btn.transition = Selectable.Transition.ColorTint;

                        btn.targetGraphic = img;

                        var colors = btn.colors;

                        colors.normalColor = Color.white;

                        colors.highlightedColor = new Color(0.9f, 0.9f, 0.9f, 1f);

                        colors.pressedColor = new Color(0.7f, 0.7f, 0.7f, 1f);

                        colors.selectedColor = new Color(0.9f, 0.9f, 0.9f, 1f);

                        colors.disabledColor = new Color(0.5f, 0.5f, 0.5f, 0.5f);

                        btn.colors = colors;

                    }

                    var txt = btnOk.GetComponentInChildren<Text>();

                    if (txt == null)

                    {

                        var txtGo = new GameObject("Text", typeof(RectTransform));

                        txtGo.transform.SetParent(btnOk.transform, false);

                        txt = txtGo.AddComponent<Text>();

                    }

                    var rtTxt = txt.GetComponent<RectTransform>();

                    if (rtTxt != null)

                    {

                        rtTxt.anchorMin = Vector2.zero;

                        rtTxt.anchorMax = Vector2.one;

                        rtTxt.pivot = new Vector2(0.5f, 0.5f);

                        rtTxt.offsetMin = Vector2.zero;

                        rtTxt.offsetMax = Vector2.zero;

                        rtTxt.anchoredPosition = Vector2.zero;

                    }

                    txt.text = "OK";

                    txt.alignment = TextAnchor.MiddleCenter;

                    txt.font = GetSafeFont(12);

                    txt.color = Color.white;

                    txt.fontSize = 12;

                    txt.fontStyle = FontStyle.Bold;

                }

                var btnCancel = KOUIRenderer.FindChildButton(root, "btn_cancel");

                if (btnCancel != null)

                {

                    var cancelRt = btnCancel.GetComponent<RectTransform>();

                    if (cancelRt != null)

                    {

                        cancelRt.anchorMin = new Vector2(0f, 1f);

                        cancelRt.anchorMax = new Vector2(0f, 1f);

                        cancelRt.pivot = new Vector2(0.5f, 0.5f);

                        cancelRt.sizeDelta = new Vector2(104f, 26f);

                        cancelRt.anchoredPosition = new Vector2(241f, -378f);

                    }

                    var oldRaw = btnCancel.GetComponent<RawImage>();

                    if (oldRaw != null) UnityEngine.Object.DestroyImmediate(oldRaw);

                    var img = btnCancel.GetComponent<Image>();

                    if (img == null) img = btnCancel.gameObject.AddComponent<Image>();

                    img.sprite = GetSkillThemeRoundedRectSprite("merchant_btn_cancel_bg", 104, 26, 0, redBg, redBorder, 1);

                    img.color = Color.white;

                    var btn = btnCancel.GetComponent<Button>();

                    if (btn != null)

                    {

                        btn.transition = Selectable.Transition.ColorTint;

                        btn.targetGraphic = img;

                        var colors = btn.colors;

                        colors.normalColor = Color.white;

                        colors.highlightedColor = new Color(0.9f, 0.9f, 0.9f, 1f);

                        colors.pressedColor = new Color(0.7f, 0.7f, 0.7f, 1f);

                        colors.selectedColor = new Color(0.9f, 0.9f, 0.9f, 1f);

                        colors.disabledColor = new Color(0.5f, 0.5f, 0.5f, 0.5f);

                        btn.colors = colors;

                    }

                    var txt = btnCancel.GetComponentInChildren<Text>();

                    if (txt == null)

                    {

                        var txtGo = new GameObject("Text", typeof(RectTransform));

                        txtGo.transform.SetParent(btnCancel.transform, false);

                        txt = txtGo.AddComponent<Text>();

                    }

                    var rtTxt = txt.GetComponent<RectTransform>();

                    if (rtTxt != null)

                    {

                        rtTxt.anchorMin = Vector2.zero;

                        rtTxt.anchorMax = Vector2.one;

                        rtTxt.pivot = new Vector2(0.5f, 0.5f);

                        rtTxt.offsetMin = Vector2.zero;

                        rtTxt.offsetMax = Vector2.zero;

                        rtTxt.anchoredPosition = Vector2.zero;

                    }

                    txt.text = "CANCEL";

                    txt.alignment = TextAnchor.MiddleCenter;

                    txt.font = GetSafeFont(11);

                    txt.color = Color.white;

                    txt.fontSize = 11;

                    txt.fontStyle = FontStyle.Bold;

                }

                ForceEnableUIComponents(root);

                if (!wasActive)

                {

                    root.gameObject.SetActive(false);

                }

            }

            catch (System.Exception ex)

            {

                Debug.LogError($"[KOUIMGR] Error in ModernizeMerchantSetupPanel: {ex}");

                // Fallback: restore active state in case of exception to prevent panel from staying open

                try

                {

                    if (root != null)

                    {

                        root.gameObject.SetActive(false);

                    }

                }

                catch {}

            }

        }

        private void ModernizeStallViewPanel(Transform root)

        {

            try

            {

                // Force update UI layout

                bool wasActive = root.gameObject.activeSelf;

                if (!wasActive)

                {

                    root.gameObject.SetActive(true);

                }

                Canvas.ForceUpdateCanvases();

                LayoutRebuilder.ForceRebuildLayoutImmediate(root.GetComponent<RectTransform>());

                // Check if already modernized (e.g. loaded from a ModernUI prefab)

                bool isAlreadyModernized = root.Find("StallViewCustomBg") != null;

                if (isAlreadyModernized)

                {

                    ForceEnableUIComponents(root);

                    if (!wasActive)

                    {

                        root.gameObject.SetActive(false);

                    }

                    return;

                }

                // 1. Orijinal otomatik oluşturulmuş arka plan görsellerini (ui_Image_*) kapat

/* Loop Removed */

/* Loop Removed */

                // Force size and center alignment of the root panel to 363x432 (centered on all screens)

                var rtRoot = root.GetComponent<RectTransform>();

                if (rtRoot != null)

                {

                    rtRoot.anchorMin = new Vector2(0.5f, 0.5f);

                    rtRoot.anchorMax = new Vector2(0.5f, 0.5f);

                    rtRoot.pivot = new Vector2(0.5f, 0.5f);

                    rtRoot.sizeDelta = new Vector2(363f, 432f);

                    rtRoot.anchoredPosition = Vector2.zero;

                    if (root.GetComponent<KOUIScaleIndependent>() == null)

                    {

                        root.gameObject.AddComponent<KOUIScaleIndependent>();

                    }

                }

                // 2. Koyu premium ana arka plan oluştur ve ata (363x432)

                var customBg = root.Find("StallViewCustomBg")?.gameObject;

                Image bgImg = null;

                if (customBg == null)

                {

                    customBg = new GameObject("StallViewCustomBg", typeof(RectTransform));

                    customBg.transform.SetParent(root, false);

                    customBg.transform.SetAsFirstSibling(); // En arkaya yerleştir

                    bgImg = customBg.AddComponent<Image>();

                    var rt = customBg.GetComponent<RectTransform>();

                    if (rt != null)

                    {

                        rt.anchorMin = Vector2.zero;

                        rt.anchorMax = Vector2.one;

                        rt.offsetMin = Vector2.zero;

                        rt.offsetMax = Vector2.zero;

                    }

                }

                else

                {

                    bgImg = customBg.GetComponent<Image>() ?? customBg.AddComponent<Image>();

                }

                bgImg.sprite = GetSkillThemePanelBgSprite("stall_view_bg", 363, 432, 0,

                    new Color(0.12f, 0.10f, 0.08f, 0.98f),

                    new Color(0.04f, 0.04f, 0.04f, 0.98f),

                    new Color(0.6f, 0.48f, 0.22f, 0.9f),

                    2);

                bgImg.color = Color.white;

                // 3. Slotların zeminlerini modernize et (cam tasarımı)

                var allAreas = root.GetComponentsInChildren<KOUIArea>(true);

                foreach (var area in allAreas)

                {

                    var areaImg = area.GetComponent<Image>() ?? area.gameObject.AddComponent<Image>();

                    areaImg.sprite = GetSkillThemeGlassSlotSprite("slot_socket_glass_v5", 45);

                    areaImg.color = Color.white;

                }

                // 4. Gold göstergesini modernize et (text_money)

                var goldText = KOUIRenderer.FindChildText(root, "text_money");

                if (goldText != null)

                {

                    goldText.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");

                    goldText.color = new Color(0.95f, 0.85f, 0.35f, 1f);

                    goldText.fontSize = 12;

                    goldText.fontStyle = FontStyle.Bold;

                    goldText.alignment = TextAnchor.MiddleCenter;

                    var rtText = goldText.GetComponent<RectTransform>();

                    if (rtText != null)

                    {

                        rtText.anchorMin = new Vector2(0f, 1f);

                        rtText.anchorMax = new Vector2(0f, 1f);

                        rtText.pivot = new Vector2(0f, 1f);

                        rtText.sizeDelta = new Vector2(133f, 21f); // 141 - 8 padding

                        rtText.anchoredPosition = new Vector2(212f, -157f); // Aligned to inventory slot right edge (345 - 133 = 212)

                    }

                    // Altındaki arka planı da güzelleştirelim (3 grid slotu genişliğinde: 141px)

                    var goldBgTr = root.Find("ui_Image_8FA174BC"); // Old gold background name we found

                    if (goldBgTr != null)

                    {

                        goldBgTr.gameObject.SetActive(true); // Keep it active but style it!

                        var oldRaw = goldBgTr.GetComponent<RawImage>();

                        if (oldRaw != null)

                        {

                            UnityEngine.Object.DestroyImmediate(oldRaw);

                        }

                        var goldBgImg = goldBgTr.GetComponent<Image>() ?? goldBgTr.gameObject.AddComponent<Image>();

                        goldBgImg.sprite = GetSkillThemeRoundedRectSprite("gold_display_bg", 141, 23, 4,

                            new Color(0.04f, 0.04f, 0.04f, 0.8f),

                            new Color(0.45f, 0.35f, 0.15f, 0.4f),

                            1);

                        goldBgImg.color = Color.white;

                        var rtGoldBg = goldBgTr.GetComponent<RectTransform>();

                        if (rtGoldBg != null)

                        {

                            rtGoldBg.anchorMin = new Vector2(0f, 1f);

                            rtGoldBg.anchorMax = new Vector2(0f, 1f);

                            rtGoldBg.pivot = new Vector2(0f, 1f);

                            rtGoldBg.sizeDelta = new Vector2(141f, 23f);

                            rtGoldBg.anchoredPosition = new Vector2(208f, -156f); // Aligned to inventory slot right edge (349 - 141 = 208)

                        }

                    }

                }

                // 5. Butonu (btn_ok) modernize et (Stall View için btn_ok kapatma butonudur)

                var btnOk = KOUIRenderer.FindChildButton(root, "btn_ok");

                if (btnOk != null)

                {

                    // Style button to be exactly like the MessageBox OK button: 104x26, sharp corners (radius 0), green colors

                    SetButtonThemeSprite(btnOk, GetSkillThemeRoundedRectSprite("btn_ok_green_stall", 104, 26, 0,

                        new Color(0.12f, 0.28f, 0.12f, 0.95f),

                        new Color(0.25f, 0.55f, 0.25f, 0.95f),

                        1));

                    var rtBtn = btnOk.GetComponent<RectTransform>();

                    if (rtBtn != null)

                    {

                        rtBtn.anchorMin = new Vector2(0.5f, 0f);

                        rtBtn.anchorMax = new Vector2(0.5f, 0f);

                        rtBtn.pivot = new Vector2(0.5f, 0f);

                        rtBtn.sizeDelta = new Vector2(104f, 26f);

                        rtBtn.anchoredPosition = new Vector2(0f, 12f);

                    }

                    // Find and reparent the first sibling text component, and deactivate duplicates

                    bool firstFound = false;

                    var allTexts = root.GetComponentsInChildren<Text>(true);

                    foreach (var tx in allTexts)

                    {

                        string trimmed = tx.text.Replace(" ", "").Replace("\n", "").Replace("\r", "").ToUpper().Trim();

                        if (trimmed == "OK" && (tx.transform.parent == root || tx.transform.parent == btnOk.transform))

                        {

                            if (!firstFound)

                            {

                                tx.transform.SetParent(btnOk.transform, false);

                                tx.rectTransform.anchorMin = Vector2.zero;

                                tx.rectTransform.anchorMax = Vector2.one;

                                tx.rectTransform.offsetMin = Vector2.zero;

                                tx.rectTransform.offsetMax = Vector2.zero;

                                tx.rectTransform.pivot = new Vector2(0.5f, 0.5f);

                                tx.text = "OK";

                                tx.alignment = TextAnchor.MiddleCenter;

                                tx.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");

                                tx.color = Color.white;

                                tx.fontSize = 11;

                                tx.fontStyle = FontStyle.Bold;

                                tx.gameObject.SetActive(true);

                                firstFound = true;

                            }

                            else

                            {

                                tx.gameObject.SetActive(false);

                            }

                        }

                    }

                    // Deactivate any duplicate TextMeshProUGUI components as well

                    bool firstTmpFound = false;

                    var tmps = root.GetComponentsInChildren<TMPro.TextMeshProUGUI>(true);

                    foreach (var tmp in tmps)

                    {

                        string trimmed = tmp.text.Replace(" ", "").Replace("\n", "").Replace("\r", "").ToUpper().Trim();

                        if (trimmed == "OK" && (tmp.transform.parent == root || tmp.transform.parent == btnOk.transform))

                        {

                            if (!firstTmpFound && !firstFound)

                            {

                                tmp.transform.SetParent(btnOk.transform, false);

                                tmp.rectTransform.anchorMin = Vector2.zero;

                                tmp.rectTransform.anchorMax = Vector2.one;

                                tmp.rectTransform.offsetMin = Vector2.zero;

                                tmp.rectTransform.offsetMax = Vector2.zero;

                                tmp.rectTransform.pivot = new Vector2(0.5f, 0.5f);

                                tmp.text = "OK";

                                tmp.color = Color.white;

                                tmp.fontSize = 11;

                                tmp.fontStyle = TMPro.FontStyles.Bold;

                                tmp.gameObject.SetActive(true);

                                firstTmpFound = true;

                            }

                            else

                            {

                                tmp.gameObject.SetActive(false);

                            }

                        }

                    }

                }

                // 6. SkillTree panelindeki branch ayiracinin aynisini ekle

                var divider = root.Find("StallViewDivider")?.gameObject;

                if (divider == null)

                {

                    divider = new GameObject("StallViewDivider", typeof(RectTransform));

                    divider.transform.SetParent(root, false);

                    // 12 slot grid'in arkasinda kalmasin, background'un hemen ustunde dursun

                    var customBgTr = root.Find("StallViewCustomBg");

                    if (customBgTr != null)

                    {

                        divider.transform.SetSiblingIndex(customBgTr.GetSiblingIndex() + 1);

                    }

                    var divImg = divider.AddComponent<Image>();

                    divImg.sprite = GetSkillThemeRoundedRectSprite("stall_view_divider", 336, 1, 0, new Color(0.6f, 0.48f, 0.22f, 0.4f), Color.clear, 0);

                    divImg.color = Color.white;

                    var rtDiv = divider.GetComponent<RectTransform>();

                    if (rtDiv != null)

                    {

                        rtDiv.anchorMin = new Vector2(0.5f, 1f);

                        rtDiv.anchorMax = new Vector2(0.5f, 1f);

                        rtDiv.pivot = new Vector2(0.5f, 0.5f);

                        rtDiv.sizeDelta = new Vector2(336f, 1f);

                        rtDiv.anchoredPosition = new Vector2(0f, -148f); // Shifted down to -148f to reduce gap with gold box

                    }

                }

                else

                {

                    // Var olan ayracı da güncel ayara çek (derinlik, boyut ve sprite güncelle)

                    var divImg = divider.GetComponent<Image>() ?? divider.AddComponent<Image>();

                    divImg.sprite = GetSkillThemeRoundedRectSprite("stall_view_divider", 336, 1, 0, new Color(0.6f, 0.48f, 0.22f, 0.4f), Color.clear, 0);

                    divImg.color = Color.white;

                    var rtDiv = divider.GetComponent<RectTransform>();

                    if (rtDiv != null)

                    {

                        rtDiv.sizeDelta = new Vector2(336f, 1f);

                        rtDiv.anchoredPosition = new Vector2(0f, -148f); // Shifted down to -148f to reduce gap with gold box

                    }

                }

                // 7. Yukarıdaki 12'li grid slotunu ve fiyat metinlerini ayracın üst kenarına 8px boşluk kalacak şekilde aşağı kaydır

                for (int i = 0; i < 12; i++)

                {

                    var slotTr = root.Find($"at{i}");

                    if (slotTr != null)

                    {

                        var rtSlot = slotTr.GetComponent<RectTransform>();

                        if (rtSlot != null)

                        {

                            float targetY = (i < 6) ? -42f : -95f;

                            rtSlot.anchoredPosition = new Vector2(rtSlot.anchoredPosition.x, targetY);

                        }

                    }

                    var priceTr = root.Find($"st{i}");

                    if (priceTr != null)

                    {

                        var rtPrice = priceTr.GetComponent<RectTransform>();

                        if (rtPrice != null)

                        {

                            float targetY = (i < 6) ? -69f : -122f;

                            rtPrice.anchoredPosition = new Vector2(rtPrice.anchoredPosition.x, targetY);

                        }

                    }

                }

                // 8. Add/Update title text at the top: "[PlayerName]'s Merchant" styled like SKILL PAGE

                int socketId = KOMerchantManager.Instance != null ? KOMerchantManager.Instance.TargetMerchantSocketId : -1;

                string sellerName = "Someone";

                if (socketId != -1)

                {

                    if (GameManager.Instance != null && (GameManager.Instance.CharacterId == socketId || (short)GameManager.Instance.CharacterId == (short)socketId))

                    {

                        sellerName = GameManager.Instance.CharacterName;

                    }

                    else

                    {

                        var rp = EntropyOnline.World.EntityManager.Instance?.GetRemotePlayer(socketId);

                        if (rp != null && !string.IsNullOrEmpty(rp.Name))

                        {

                            sellerName = rp.Name;

                        }

                    }

                }

                var titleObj = root.Find("StallViewTitle")?.gameObject;

                if (titleObj == null)

                {

                    titleObj = new GameObject("StallViewTitle", typeof(RectTransform));

                    titleObj.transform.SetParent(root, false);

                    var titleTxt = titleObj.AddComponent<Text>();

                    titleTxt.text = $"{sellerName}'s Merchant";

                    titleTxt.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");

                    titleTxt.alignment = TextAnchor.MiddleCenter;

                    titleTxt.color = new Color(0.95f, 0.85f, 0.35f, 1f);

                    titleTxt.fontStyle = FontStyle.Bold;

                    titleTxt.fontSize = 14;

                    AddSkillThemeTextShadow(titleTxt);

                    var rtTitle = titleObj.GetComponent<RectTransform>();

                    if (rtTitle != null)

                    {

                        rtTitle.anchorMin = new Vector2(0.5f, 1f);

                        rtTitle.anchorMax = new Vector2(0.5f, 1f);

                        rtTitle.pivot = new Vector2(0.5f, 0.5f);

                        rtTitle.sizeDelta = new Vector2(300f, 30f);

                        rtTitle.anchoredPosition = new Vector2(0f, -22f);

                    }

                }

                else

                {

                    var titleTxt = titleObj.GetComponent<Text>();

                    if (titleTxt != null)

                    {

                        titleTxt.text = $"{sellerName}'s Merchant";

                    }

                }

                ForceEnableUIComponents(root);

                if (!wasActive)

                {

                    root.gameObject.SetActive(false);

                }

            }

            catch (System.Exception ex)

            {

                Debug.LogError($"[KOUIMGR] Error in ModernizeStallViewPanel: {ex.Message}");

                // Fallback: restore active state in case of exception to prevent panel from staying open

                try

{

                    if (root != null)

                    {

                        root.gameObject.SetActive(false);

                    }

                }

                catch {}

            }

        }

        private void BindPersonalTradeElements(Transform root)

        {

            ModernizePersonalTradePanel(root);

            // C++ UIPerTradeDlg.cpp satır 816-820: btn_close → iptal

            var btnClose = KOUIRenderer.FindChildButton(root, "btn_close");

            if (btnClose != null)

            {

                btnClose.onClick.AddListener(() =>

                {

                    if (EntropyOnline.Trade.KOTradeManager.Instance != null)

                        EntropyOnline.Trade.KOTradeManager.Instance.SendExchangeCancel();

                    else

                        ShowPersonalTrade(false);

                });

            }

            // C++ UIPerTradeDlg.cpp InitIconWnd() satır 228: m_pStrMyGold = GetChildByID<CN3UIString>("string_money_inv")

            var goldText = KOUIRenderer.FindChildText(root, "string_money_inv");

            if (goldText != null)

            {

                goldText.text = "0";

            }

            // C++ birebir: GetChildAreaByiOrder(UI_AREA_TYPE_PER_TRADE_MY, i) — ReceiveIconDrop hit test alanları

            for (int i = 0; i < 12; i++)

            {

                var areaRT = KOUIRenderer.FindChildAreaByiOrder(root, 4, i);

                if (areaRT != null)

                {

                    var areaGO = areaRT.gameObject;

                    var img = areaGO.GetComponent<UnityEngine.UI.Image>();

                    if (img == null)

                    {

                        img = areaGO.AddComponent<UnityEngine.UI.Image>();

                        img.color = Color.clear;

                    }

                    img.raycastTarget = true;

                    var dropTarget = areaGO.GetComponent<KOTradeDropTarget>();

                    if (dropTarget == null)

                        dropTarget = areaGO.AddComponent<KOTradeDropTarget>();

                    dropTarget.tradeSlotIndex = i;

                }

            }

            // C++ UIPerTradeDlg.cpp satır 822-824: btn_trade_my → onay

            var btnTradeMy = KOUIRenderer.FindChildButton(root, "btn_trade_my");

            _btnTradeMy = btnTradeMy;

            var btnTradeOther = KOUIRenderer.FindChildButton(root, "btn_trade_other");

            _btnTradeOther = btnTradeOther;

            if (_btnTradeMy != null)

            {

                var txt = _btnTradeMy.GetComponentInChildren<Text>(true);

                _originalTradeMyText = txt != null ? txt.text : "Trade";

            }

            if (_btnTradeOther != null)

            {

                var txt = _btnTradeOther.GetComponentInChildren<Text>(true);

                _originalTradeOtherText = txt != null ? txt.text : "Trade";

                _btnTradeOther.interactable = false;

            }

            if (btnTradeMy != null)

            {

                btnTradeMy.onClick.AddListener(() =>

                {

                    var tradeMgr = EntropyOnline.Trade.KOTradeManager.Instance;

                    if (tradeMgr == null) return;

                    if (tradeMgr.State != EntropyOnline.Trade.KOTradeManager.PerTradeState.Normal)

                    {

                        Debug.LogWarning("[TRADE] Onaylanamaz - takas normal durumda değil.");

                        return;

                    }

                    if (KOMessageBox.Instance != null)

                    {

                        KOMessageBox.Instance.ShowYesNo(

                            "Do you want to finalize the trade?",

                            "Confirm Trade",

                            MsgBoxBehavior.BEHAVIOR_NOTHING,

                            onYes: () =>

                            {

                                tradeMgr.SendExchangeDecide();

                            },

                            countdownDuration: 5,

                            forceFixedCenter: true,

                            callerPanel: _uiPersonalTrade

                        );

                    }

                    else

                    {

                        tradeMgr.SendExchangeDecide();

                    }

                });

            }

            // C++ UIPerTradeDlg.cpp satır 828-832: btn_gold → RequestItemCountEdit

            var btnGold = KOUIRenderer.FindChildButton(root, "btn_gold");

            if (btnGold != null)

            {

                btnGold.onClick.AddListener(() =>

                {

                    if (EntropyOnline.Trade.KOTradeManager.Instance != null)

                        EntropyOnline.Trade.KOTradeManager.Instance.RequestItemCountEdit();

                });

            }

        }

        private void ModernizePartyBBS(GameObject panel)

        {

            if (panel == null) return;

            Transform root = panel.transform;

            if (root.Find("PartyBBSCustomBg") != null) return; // Already modernized

            try

            {

                // Force root centering and keep dimensions constant on screen size change

                var rtRoot = root.GetComponent<RectTransform>();

                if (rtRoot != null)

                {

                    rtRoot.anchorMin = new Vector2(0.5f, 0.5f);

                    rtRoot.anchorMax = new Vector2(0.5f, 0.5f);

                    rtRoot.pivot = new Vector2(0.5f, 0.5f);

                    rtRoot.anchoredPosition = Vector2.zero;

                    rtRoot.sizeDelta = new Vector2(338f, 558f);

                    float s = CanvasScaleFactor;

                    if (s > 0f)

                    {

                        rtRoot.localScale = new Vector3(1f / s, 1f / s, 1f / s);

                    }

                }

                // 1. Disable original backgrounds

/* Loop Removed */

/* Loop Removed */

                // 2. Custom Main Background (Size: 338x558, Anchored to Top-Center)

                var customBg = new GameObject("PartyBBSCustomBg", typeof(RectTransform));

                customBg.transform.SetParent(root, false);

                customBg.transform.SetAsFirstSibling();

                var bgImg = customBg.AddComponent<Image>();

                var rtBg = customBg.GetComponent<RectTransform>();

                rtBg.anchorMin = new Vector2(0.5f, 1f);

                rtBg.anchorMax = new Vector2(0.5f, 1f);

                rtBg.pivot = new Vector2(0.5f, 1f);

                rtBg.anchoredPosition = Vector2.zero;

                rtBg.sizeDelta = new Vector2(338f, 558f);

                bgImg.sprite = GetSkillThemePanelBgSprite("partybbs_custom_bg", 338, 558, 0,

                    new Color(0.12f, 0.10f, 0.08f, 0.98f),

                    new Color(0.04f, 0.04f, 0.04f, 0.98f),

                    new Color(0.6f, 0.48f, 0.22f, 0.9f),

                    2);

                bgImg.color = Color.white;

                bgImg.raycastTarget = true;

                // 3. Close Button (btn_exit) - align to Top-Right

                var btnClose = KOUIRenderer.FindChildButton(root, "btn_exit");

                if (btnClose != null)

                {

                    var rt = btnClose.GetComponent<RectTransform>();

                    rt.anchorMin = new Vector2(1f, 1f);

                    rt.anchorMax = new Vector2(1f, 1f);

                    rt.pivot = new Vector2(1f, 1f);

                    rt.anchoredPosition = new Vector2(-4f, -4f);

                    rt.sizeDelta = new Vector2(24f, 24f);

                    SetButtonThemeSprite(btnClose, GetSkillThemeRoundedRectSprite("partybbs_close_btn", 24, 24, 0,

                        new Color(0.18f, 0.18f, 0.18f, 1f),

                        new Color(0.45f, 0.35f, 0.15f, 1f),

                        1));

                    var btnTxt = btnClose.GetComponentInChildren<Text>();

                    if (btnTxt == null)

                    {

                        var txtObj = new GameObject("Text");

                        txtObj.transform.SetParent(btnClose.transform, false);

                        btnTxt = txtObj.AddComponent<Text>();

                        btnTxt.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");

                        btnTxt.alignment = TextAnchor.MiddleCenter;

                    }

                    btnTxt.enabled = true;

                    btnTxt.text = "X";

                    btnTxt.color = new Color(0.9f, 0.8f, 0.6f, 1f);

                    btnTxt.fontStyle = FontStyle.Bold;

                    btnTxt.fontSize = 12;

                    btnTxt.rectTransform.anchorMin = Vector2.zero;

                    btnTxt.rectTransform.anchorMax = Vector2.one;

                    btnTxt.rectTransform.offsetMin = Vector2.zero;

                    btnTxt.rectTransform.offsetMax = Vector2.zero;

                }

                // 4. Panel Title

                var titleText = KOUIRenderer.FindChildText(root, "string_title");

                if (titleText == null)

                {

                    var titleObj = new GameObject("string_title");

                    titleObj.transform.SetParent(root, false);

                    titleText = titleObj.AddComponent<Text>();

                    titleText.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");

                    titleText.alignment = TextAnchor.MiddleCenter;

                }

                titleText.enabled = true;

                titleText.text = "LOOKING PARTY";

                titleText.color = new Color(0.95f, 0.85f, 0.35f, 1f);

                titleText.fontStyle = FontStyle.Bold;

                titleText.fontSize = 16;

                var rtTitle = titleText.GetComponent<RectTransform>();

                rtTitle.anchorMin = new Vector2(0.5f, 1f);

                rtTitle.anchorMax = new Vector2(0.5f, 1f);

                rtTitle.pivot = new Vector2(0.5f, 1f);

                rtTitle.anchoredPosition = new Vector2(0f, -15f);

                rtTitle.sizeDelta = new Vector2(250f, 30f);

                AddSkillThemeTextShadow(titleText);

                // 5. Hide original vertical tabs

                var btnPersonalTab = root.Find("btn_personal")?.gameObject;

                var btnPartyTab = root.Find("btn_party")?.gameObject;

                if (btnPersonalTab != null) btnPersonalTab.SetActive(false);

                if (btnPartyTab != null) btnPartyTab.SetActive(false);

                // 6. Create Table Column Headers (NAME, CLASS, LEVEL)

                var headersContainer = new GameObject("TableHeaders", typeof(RectTransform));

                headersContainer.transform.SetParent(root, false);

                var rtHeaders = headersContainer.GetComponent<RectTransform>();

                rtHeaders.anchorMin = new Vector2(0.5f, 1f);

                rtHeaders.anchorMax = new Vector2(0.5f, 1f);

                rtHeaders.pivot = new Vector2(0.5f, 1f);

                rtHeaders.anchoredPosition = new Vector2(0f, -55f);

                rtHeaders.sizeDelta = new Vector2(318f, 25f);

                System.Action<string, string, float, float, Color> createHeaderCol = (id, label, startX, width, barColor) => {

                    var colObj = new GameObject(id, typeof(RectTransform));

                    colObj.transform.SetParent(headersContainer.transform, false);

                    var rtCol = colObj.GetComponent<RectTransform>();

                    rtCol.anchorMin = new Vector2(0f, 0.5f);

                    rtCol.anchorMax = new Vector2(0f, 0.5f);

                    rtCol.pivot = new Vector2(0f, 0.5f);

                    rtCol.anchoredPosition = new Vector2(startX, 0f);

                    rtCol.sizeDelta = new Vector2(width, 25f);

                    var bgObj = new GameObject("Bg", typeof(RectTransform));

                    bgObj.transform.SetParent(colObj.transform, false);

                    var rtBg = bgObj.GetComponent<RectTransform>();

                    rtBg.anchorMin = Vector2.zero;

                    rtBg.anchorMax = Vector2.one;

                    rtBg.offsetMin = Vector2.zero;

                    rtBg.offsetMax = Vector2.zero;

                    var bgImg = bgObj.AddComponent<Image>();

                    bgImg.sprite = GetArrowSprite(id + "_header_bg", (int)width, 25, 0, 0, barColor, Color.clear, 0, horizontalGradient: true);

                    var txt = colObj.AddComponent<Text>();

                    txt.text = label;

                    txt.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");

                    txt.alignment = TextAnchor.MiddleCenter;

                    txt.color = new Color(0.9f, 0.8f, 0.6f, 1f);

                    txt.fontStyle = FontStyle.Bold;

                    txt.fontSize = 11;

                    txt.enabled = true;

                    AddSkillThemeTextShadow(txt);

                };

                createHeaderCol("Header_Name", "NAME", 0f, 155f, new Color(0.2f, 0.6f, 0.2f, 0.3f));

                createHeaderCol("Header_Class", "CLASS", 155f, 80f, new Color(0.7f, 0.2f, 0.2f, 0.3f));

                createHeaderCol("Header_Level", "LEVEL", 235f, 83f, new Color(0.2f, 0.5f, 0.8f, 0.3f));

                // 7. Create Scrollable Viewport and Content Container

                var scrollObj = new GameObject("ListScrollRect", typeof(RectTransform));

                scrollObj.transform.SetParent(root, false);

                var rtScroll = scrollObj.GetComponent<RectTransform>();

                rtScroll.anchorMin = new Vector2(0.5f, 1f);

                rtScroll.anchorMax = new Vector2(0.5f, 1f);

                rtScroll.pivot = new Vector2(0.5f, 1f);

                rtScroll.anchoredPosition = new Vector2(0f, -80f);

                rtScroll.sizeDelta = new Vector2(318f, 336f);

                var scrollImg = scrollObj.AddComponent<Image>();

                scrollImg.sprite = GetSkillThemeRoundedRectSprite("bbs_scroll_frame", 318, 336, 0,

                    new Color(0.08f, 0.07f, 0.05f, 0.6f),

                    new Color(0.3f, 0.25f, 0.2f, 0.4f),

                    1);

                var viewportObj = new GameObject("Viewport", typeof(RectTransform));

                viewportObj.transform.SetParent(scrollObj.transform, false);

                var rtViewport = viewportObj.GetComponent<RectTransform>();

                rtViewport.anchorMin = Vector2.zero;

                rtViewport.anchorMax = Vector2.one;

                rtViewport.offsetMin = new Vector2(1f, 1f);

                rtViewport.offsetMax = new Vector2(-1f, -1f);

                var viewImg = viewportObj.AddComponent<Image>();

                viewImg.color = new Color(0f, 0f, 0f, 0.01f);

                var mask = viewportObj.AddComponent<Mask>();

                mask.showMaskGraphic = false;

                var contentObj = new GameObject("Content", typeof(RectTransform));

                contentObj.transform.SetParent(viewportObj.transform, false);

                var rtContent = contentObj.GetComponent<RectTransform>();

                rtContent.anchorMin = new Vector2(0.5f, 1f);

                rtContent.anchorMax = new Vector2(0.5f, 1f);

                rtContent.pivot = new Vector2(0.5f, 1f);

                rtContent.anchoredPosition = Vector2.zero;

                rtContent.sizeDelta = new Vector2(318f, 720f); // Spaced rows height

                var scrollRect = scrollObj.AddComponent<ScrollRect>();

                scrollRect.viewport = rtViewport;

                scrollRect.content = rtContent;

                scrollRect.horizontal = false;

                scrollRect.vertical = true;

                scrollRect.movementType = ScrollRect.MovementType.Elastic;

                // Disable page texts (string_page)

                var allTexts = root.GetComponentsInChildren<Text>(true);

                foreach (var txt in allTexts)

                {

                    if (txt.gameObject.name == "string_page")

                    {

                        txt.gameObject.SetActive(false);

                    }

                }

                // 8. Style buttons

                var personalGroup = root.Find("personal");

                var partyGroup = root.Find("party");

                if (personalGroup != null)

                {

                    var rt = personalGroup.GetComponent<RectTransform>();

                    if (rt != null)

                    {

                        rt.anchorMin = new Vector2(0.5f, 0.5f);

                        rt.anchorMax = new Vector2(0.5f, 0.5f);

                        rt.pivot = new Vector2(0.5f, 0.5f);

                        rt.anchoredPosition = Vector2.zero;

                        rt.sizeDelta = new Vector2(338f, 558f);

                    }

                    ModernizeBBSGroup(personalGroup, true, btnPersonalTab?.GetComponent<Button>(), btnPartyTab?.GetComponent<Button>());

                }

                if (partyGroup != null)

                {

                    var rt = partyGroup.GetComponent<RectTransform>();

                    if (rt != null)

                    {

                        rt.anchorMin = new Vector2(0.5f, 0.5f);

                        rt.anchorMax = new Vector2(0.5f, 0.5f);

                        rt.pivot = new Vector2(0.5f, 0.5f);

                        rt.anchoredPosition = Vector2.zero;

                        rt.sizeDelta = new Vector2(338f, 558f);

                    }

                    ModernizeBBSGroup(partyGroup, false, btnPersonalTab?.GetComponent<Button>(), btnPartyTab?.GetComponent<Button>());

                }

                // Initialize bottom button alignments & states

                RefreshPartyBBSButtons(panel);

            }

            catch (System.Exception ex)

            {

                Debug.LogError($"[KOUIMGR] Error in ModernizePartyBBS: {ex.Message}\n{ex.StackTrace}");

            }

        }

        public void RefreshPartyBBSButtons(GameObject panel)

        {

            if (panel == null) return;

            Transform root = panel.transform;

            var personalGroup = root.Find("personal");

            var partyGroup = root.Find("party");

            bool isRegistered = false;

            if (GameManager.Instance != null)

            {

                isRegistered = GameManager.Instance.RecruitParty;

            }

            var btnSprite = GetSkillThemeRoundedRectSprite("bbs_btn_bg", 64, 20, 0,

                new Color(0.18f, 0.14f, 0.10f, 1f),

                new Color(0.5f, 0.4f, 0.18f, 1f),

                1);

            var btnRedSprite = GetSkillThemeRoundedRectSprite("bbs_btn_red_bg", 64, 20, 0,

                new Color(0.35f, 0.12f, 0.12f, 1f),

                new Color(0.7f, 0.3f, 0.3f, 1f),

                1);

            System.Action<Transform, bool> updateGroupButtons = (group, isPersonal) => {

                var btnAdd = KOUIRenderer.FindChildButton(group, "btn_add");

                var btnDelete = KOUIRenderer.FindChildButton(group, "btn_delete");

                var btnRefresh = KOUIRenderer.FindChildButton(group, "btn_refresh");

                if (isRegistered)

                {

                    if (btnAdd != null) btnAdd.gameObject.SetActive(false);

                    if (btnDelete != null)

                    {

                        btnDelete.gameObject.SetActive(true);

                        StyleActionBtn(btnDelete, "🗑 REMOVE", new Vector2(-80f, -526f), new Vector2(135f, 32f), btnRedSprite);

                        var txt = btnDelete.GetComponentInChildren<Text>();

                        if (txt != null)

                        {

                            txt.color = Color.white;

                            txt.enabled = true;

                        }

                    }

                }

                else

                {

                    if (btnDelete != null) btnDelete.gameObject.SetActive(false);

                    if (btnAdd != null)

                    {

                        btnAdd.gameObject.SetActive(true);

                        StyleActionBtn(btnAdd, "📝 REGISTER", new Vector2(-80f, -526f), new Vector2(135f, 32f), btnSprite);

                    }

                }

                if (btnRefresh != null)

                {

                    StyleActionBtn(btnRefresh, "🔄 REFRESH", new Vector2(80f, -526f), new Vector2(135f, 32f), btnSprite);

                }

            };

            if (personalGroup != null) updateGroupButtons(personalGroup, true);

            if (partyGroup != null) updateGroupButtons(partyGroup, false);

        }

        private void ModernizeBBSGroup(Transform group, bool isPersonal, Button btnPersonalTab, Button btnPartyTab)

        {

            // First, disable ALL legacy Text components inside this group to prevent overlaps, except string_page

            var legacyTexts = group.GetComponentsInChildren<Text>(true);

