            }

            // Mid-Panel Tab Switcher Button

            var switcherObj = new GameObject("TabSwitcherButton", typeof(RectTransform));

            switcherObj.transform.SetParent(group, false);

            var rtSwitcher = switcherObj.GetComponent<RectTransform>();

