            // Disable original background images in sub-panel

/* Loop Removed */

/* Loop Removed */

            // Reparent texts if personal group

            if (isPersonal)

            {

                Transform contentTrans = group.parent.Find("ListScrollRect/Viewport/Content");

                Transform parentToUse = contentTrans != null ? contentTrans : group.parent;

                for (int i = 0; i < 66; i++)

                {

                    string textId = $"text_{i:D2}";

                    var textObj = group.Find(textId);

                    if (textObj != null)

                    {

                        textObj.SetParent(parentToUse, true);

                        var txt = textObj.GetComponent<Text>();

                        if (txt != null)

                        {

                            txt.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");

                            txt.fontSize = 11;

                            txt.fontStyle = FontStyle.Bold;

                            txt.enabled = true;

                            AddSkillThemeTextShadow(txt);

                            var rt = textObj.GetComponent<RectTransform>();

                            rt.anchorMin = new Vector2(0.5f, 1f);

                            rt.anchorMax = new Vector2(0.5f, 1f);

                            rt.pivot = new Vector2(0.5f, 0.5f);

                            int rowIdx = i % 22;

                            int colIdx = i / 22;

                            float yPos = -16f - (rowIdx * 32f); // Spaced nicely for mobile (32f instead of 16.5f)

                            float xPos = 0f;

                            float width = 100f;

                            if (colIdx == 0) // Name

                            {

                                xPos = -95f;

                                width = 140f;

                                txt.alignment = TextAnchor.MiddleLeft;

                                txt.color = Color.white;

                            }

                            else if (colIdx == 1) // Level

                            {

                                xPos = 135f;

                                width = 70f;

                                txt.alignment = TextAnchor.MiddleCenter;

                                txt.color = new Color(0.6f, 0.85f, 1f, 1f);

                            }

                            else // Class

                            {

                                xPos = 35f;

                                width = 100f;

                                txt.alignment = TextAnchor.MiddleCenter;

                                txt.color = new Color(0.9f, 0.75f, 0.55f, 1f);

                            }

                            rt.anchoredPosition = new Vector2(xPos, yPos);

                            rt.sizeDelta = new Vector2(width, 16f);

                        }

                    }

                }

            }

            else

            {

                for (int i = 0; i < 66; i++)

                {

                    string textId = $"text_{i:D2}";

                    var textObj = group.Find(textId);

                    if (textObj != null)

                    {

                        Destroy(textObj.gameObject);

                    }

                }

            }

        }

        private void StyleActionBtn(Button btn, string label, Vector2 pos, Vector2 size, Sprite sprite)

        {

            var rt = btn.GetComponent<RectTransform>();

            rt.anchorMin = new Vector2(0.5f, 1f);

            rt.anchorMax = new Vector2(0.5f, 1f);

            rt.pivot = new Vector2(0.5f, 0.5f);

            rt.anchoredPosition = pos;

            rt.sizeDelta = size;

            SetButtonThemeSprite(btn, sprite);

            var txt = btn.GetComponentInChildren<Text>();

            if (txt == null)

            {

                var txtObj = new GameObject("Text");

                txtObj.transform.SetParent(btn.transform, false);

                txt = txtObj.AddComponent<Text>();

                txt.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");

                txt.alignment = TextAnchor.MiddleCenter;

            }

            txt.text = label;

            txt.color = new Color(0.9f, 0.8f, 0.6f, 1f);

            txt.fontStyle = FontStyle.Bold;

            txt.fontSize = 11;

            txt.enabled = true; // Ensure active

            AddSkillThemeTextShadow(txt);

            txt.rectTransform.anchorMin = Vector2.zero;

            txt.rectTransform.anchorMax = Vector2.one;

            txt.rectTransform.offsetMin = Vector2.zero;

            txt.rectTransform.offsetMax = Vector2.zero;

        }

