        private void SetPartySlotActive(int i, bool active)

        {

            if (_uiParty == null) return;

            string[] subNames = new string[] {

                $"Area_{i}",

                $"progress_hp_{i}",

                $"progress_mp_{i}_curse",

                $"static_name_{i}",

                $"SlotNameBg_{i}"

            };

            foreach (var subName in subNames)

            {

                var child = _uiParty.transform.Find(subName);

                if (child != null)

                {

                    child.gameObject.SetActive(active);

                }

            }

            // Custom active/deactive controls

            if (_partyClassIcons[i] != null) _partyClassIcons[i].gameObject.SetActive(active);

            if (_partyIndexBgs[i] != null) _partyIndexBgs[i].transform.parent.gameObject.SetActive(active);

        }

