        /// <summary>

        /// Sunucudan gelen parti üye listesini panele doldurur.

        /// </summary>

        public void PopulatePartyList(long leaderId, PartyMemberData[] members)

        {

            if (_partyActionMenu != null)

            {

                _partyActionMenu.SetActive(false);

                _partyActionMenuTargetId = -1;

            }

            _currentPartyMembers = members;

            // Eski dinamik item'ları temizle

            foreach (var obj in _partyMemberItems)

                if (obj != null) Destroy(obj);

            _partyMemberItems.Clear();

            if (members == null || members.Length == 0)

            {

                ShowParty(false);

                return;

            }

            ShowParty(true);

            if (_uiParty == null) return;

            long myId = GameManager.Instance != null ? GameManager.Instance.CharacterId : 0;

            bool iAmLeader = (leaderId == myId);

            var closeBtn = _uiParty.transform.Find("HeaderBar/CloseBtn");

            if (closeBtn != null)

            {

                closeBtn.gameObject.SetActive(true);

            }

            for (int i = 0; i < 8; i++)

            {

                if (i < members.Length)

                {

                    SetPartySlotActive(i, true);

                    var member = members[i];

                    bool isLeader = (member.CharacterId == leaderId);

                    // İsim metnini güncelle

                    var nameObj = _uiParty.transform.Find($"static_name_{i}");

                    var nameText = nameObj?.GetComponent<Text>();

                    if (nameText == null) nameText = nameObj?.GetComponentInChildren<Text>();

                    if (nameText != null)

                    {

                        nameText.text = member.Name;

                        nameText.color = isLeader ? Color.yellow : Color.white;

                    }

                    // HP slanted fill güncelle

                    float hpRatio = member.MaxHp > 0 ? (float)member.CurrentHp / member.MaxHp : 0f;

                    if (_partyHpFills[i] != null)

                    {

                        _partyHpFills[i].anchorMax = new Vector2(hpRatio, 1f);

                    }

                    // MP slanted fill güncelle

                    float mpRatio = member.MaxMp > 0 ? (float)member.CurrentMp / member.MaxMp : 0f;

                    if (_partyMpFills[i] != null)

                    {

                        _partyMpFills[i].anchorMax = new Vector2(mpRatio, 1f);

                    }

                    // Class simgesi güncelle

                    if (_partyClassIcons[i] != null)

                    {

                        int classBase = member.Class % 100;

                        int mainClass = classBase switch

                        {

                            1 or 5 or 6 => 1,   // Warrior

                            2 or 7 or 8 => 2,   // Rogue

                            3 or 9 or 10 => 3,  // Mage

                            4 or 11 or 12 => 4, // Priest

                            _ => 1

                        };

                        Sprite iconSprite = Resources.Load<Sprite>($"UI/class_icon_{mainClass}");

                        _partyClassIcons[i].sprite = iconSprite;

                        _partyClassIcons[i].gameObject.SetActive(iconSprite != null);

                    }

                    // Seçim çerçevesini, ok butonunu ve baklava renklerini güncelle

                    bool isSelected = (i == KOPartyManager.Instance.IndexSelected);

                    if (_partySlotSelectedOutlines[i] != null)

                    {

                        _partySlotSelectedOutlines[i].SetActive(isSelected);

                    }

                    if (_partySlotArrowBtns[i] != null)

                    {

                        bool showArrow = isSelected && iAmLeader && (member.CharacterId != myId);

                        _partySlotArrowBtns[i].SetActive(showArrow);

                    }

                    if (_partyIndexBgs[i] != null)

                    {

                        _partyIndexBgs[i].color = isLeader 

                            ? new Color(0.796f, 0.004f, 0.035f, 0.95f) 

                            : new Color(0.5f, 0f, 0.5f, 0.95f);

                    }

                }

                else

                {

                    SetPartySlotActive(i, false);

                }

            }

            // Dynamically adjust panel height based on active members count to prevent blocking clicks on empty space below

            var panelRt = _uiParty.GetComponent<RectTransform>();

            if (panelRt != null)

            {

                float slotSpacing = 28f;

                float newHeight = 36f + members.Length * slotSpacing;

                panelRt.sizeDelta = new Vector2(180f, newHeight);

            }

        }

        private void CreatePartyActionMenu()

        {

            if (_partyActionMenu != null) return;

            // Ana menü objesi (şeffaf taşıyıcı)

            _partyActionMenu = new GameObject("PartyActionMenu");

            var rectTrans = _partyActionMenu.AddComponent<RectTransform>();

            rectTrans.sizeDelta = new Vector2(85f, 48f);

