            Color goldBorderColor = new Color(0.796f, 0.733f, 0.545f, 0.8f); // Exit button border

            Color exitBtnTextColor = new Color(0.886f, 0.768f, 0.549f, 1f);  // Exit button text color (warm yellow)

            // 1. Leader (Make Leader) Butonu

            var leaderBtnObj = new GameObject("LeaderBtn");

            leaderBtnObj.transform.SetParent(_partyActionMenu.transform, false);

            var leaderBtnImg = leaderBtnObj.AddComponent<Image>();

            leaderBtnImg.sprite = GetSkillThemeRoundedRectSprite("party_menu_leader_btn_v4", 340, 84, 40, btnBgColor, goldBorderColor, 4);

            leaderBtnImg.color = Color.white;

            var leaderBtn = leaderBtnObj.AddComponent<Button>();

            leaderBtn.targetGraphic = leaderBtnImg;

            var leaderBtnRt = leaderBtnObj.GetComponent<RectTransform>();

            leaderBtnRt.anchorMin = new Vector2(0.5f, 1f);

            leaderBtnRt.anchorMax = new Vector2(0.5f, 1f);

            leaderBtnRt.pivot = new Vector2(0.5f, 1f);

            leaderBtnRt.anchoredPosition = new Vector2(0f, 0f);

            leaderBtnRt.sizeDelta = new Vector2(85f, 21f);

            var leaderTextObj = new GameObject("Text");

            leaderTextObj.transform.SetParent(leaderBtnObj.transform, false);

            var leaderText = leaderTextObj.AddComponent<Text>();

            leaderText.font = customFont;

            leaderText.text = "Make Leader";

            leaderText.fontSize = 10;

            leaderText.alignment = TextAnchor.MiddleCenter;

            leaderText.color = exitBtnTextColor;

            var leaderTextRt = leaderTextObj.GetComponent<RectTransform>();

            leaderTextRt.anchorMin = Vector2.zero;

            leaderTextRt.anchorMax = Vector2.one;

            leaderTextRt.offsetMin = Vector2.zero;

            leaderTextRt.offsetMax = Vector2.zero;

            leaderBtn.onClick.AddListener(OnPartyActionMakeLeader);

            // 2. Kick (Kick out) Butonu

            var kickBtnObj = new GameObject("KickBtn");

            kickBtnObj.transform.SetParent(_partyActionMenu.transform, false);

            var kickBtnImg = kickBtnObj.AddComponent<Image>();

            kickBtnImg.sprite = GetSkillThemeRoundedRectSprite("party_menu_kick_btn_v4", 340, 84, 40, btnBgColor, goldBorderColor, 4);

            kickBtnImg.color = Color.white;

            var kickBtn = kickBtnObj.AddComponent<Button>();

            kickBtn.targetGraphic = kickBtnImg;

            var kickBtnRt = kickBtnObj.GetComponent<RectTransform>();

            kickBtnRt.anchorMin = new Vector2(0.5f, 0f);

            kickBtnRt.anchorMax = new Vector2(0.5f, 0f);

            kickBtnRt.pivot = new Vector2(0.5f, 0f);

            kickBtnRt.anchoredPosition = new Vector2(0f, 0f);

            kickBtnRt.sizeDelta = new Vector2(85f, 21f);

            var kickTextObj = new GameObject("Text");

            kickTextObj.transform.SetParent(kickBtnObj.transform, false);

            var kickText = kickTextObj.AddComponent<Text>();

            kickText.font = customFont;

            kickText.text = "Kick out";

            kickText.fontSize = 10;

            kickText.alignment = TextAnchor.MiddleCenter;

            kickText.color = exitBtnTextColor;

            var kickTextRt = kickTextObj.GetComponent<RectTransform>();

            kickTextRt.anchorMin = Vector2.zero;

            kickTextRt.anchorMax = Vector2.one;

            kickTextRt.offsetMin = Vector2.zero;

            kickTextRt.offsetMax = Vector2.zero;

            kickBtn.onClick.AddListener(OnPartyActionKick);

            // Hover / Tıklama efektleri için görsel geri bildirim (Color Block)

            var leaderColorBlock = leaderBtn.colors;

            leaderColorBlock.normalColor = Color.white;

            leaderColorBlock.highlightedColor = new Color(0.85f, 0.85f, 0.85f, 1f);

            leaderColorBlock.pressedColor = new Color(0.7f, 0.7f, 0.7f, 1f);

            leaderBtn.colors = leaderColorBlock;

            var kickColorBlock = kickBtn.colors;

            kickColorBlock.normalColor = Color.white;

            kickColorBlock.highlightedColor = new Color(0.85f, 0.85f, 0.85f, 1f);

            kickColorBlock.pressedColor = new Color(0.7f, 0.7f, 0.7f, 1f);

            kickBtn.colors = kickColorBlock;

            _partyActionMenu.SetActive(false);

        }

        private void OnPartyActionMakeLeader()

        {

            if (_partyActionMenuTargetId != -1 && PartyUI.Instance != null)

            {

                PartyUI.Instance.SendPartyPromote(_partyActionMenuTargetId);

            }

            if (_partyActionMenu != null)

            {

                _partyActionMenu.SetActive(false);

                _partyActionMenuTargetId = -1;

            }

        }

        private void OnPartyActionKick()

        {

            if (_partyActionMenuTargetId != -1 && PartyUI.Instance != null)

            {

                PartyUI.Instance.SendPartyKick(_partyActionMenuTargetId);

            }

            if (_partyActionMenu != null)

            {

                _partyActionMenu.SetActive(false);

                _partyActionMenuTargetId = -1;

            }

        }

        public void UpdatePartySelection()

        {

            if (KOPartyManager.Instance == null) return;

            int selectedIndex = KOPartyManager.Instance.IndexSelected;

            long leaderId = KOPartyManager.Instance.LeaderId;

            if (leaderId == -1 && _currentPartyMembers != null && _currentPartyMembers.Length > 0)

                leaderId = _currentPartyMembers[0].CharacterId;

            long myId = GameManager.Instance != null ? GameManager.Instance.CharacterId : 0;

            bool iAmLeader = (leaderId == myId);

            if (_partyActionMenu != null && _partyActionMenu.activeSelf)

            {

                if (selectedIndex == -1 || _currentPartyMembers == null || selectedIndex >= _currentPartyMembers.Length || _currentPartyMembers[selectedIndex].CharacterId != _partyActionMenuTargetId)

                {

                    _partyActionMenu.SetActive(false);

                    _partyActionMenuTargetId = -1;

                }

            }

            for (int i = 0; i < 8; i++)

            {

                bool isSelected = (i == selectedIndex);

                if (_partySlotSelectedOutlines[i] != null)

                {

                    _partySlotSelectedOutlines[i].SetActive(isSelected);

                }

                if (_partySlotArrowBtns[i] != null)

                {

                    bool showArrow = false;

                    if (isSelected && _currentPartyMembers != null && i < _currentPartyMembers.Length)

                    {

                        var member = _currentPartyMembers[i];

                        showArrow = iAmLeader && (member.CharacterId != myId);

                    }

                    _partySlotArrowBtns[i].SetActive(showArrow);

                }

                if (_currentPartyMembers != null && i < _currentPartyMembers.Length)

                {

                    bool isLeader = (_currentPartyMembers[i].CharacterId == leaderId);

                    if (_partyIndexBgs[i] != null)

                    {

                        _partyIndexBgs[i].color = isLeader 

                            ? new Color(0.796f, 0.004f, 0.035f, 0.95f) 

                            : new Color(0.5f, 0f, 0.5f, 0.95f);

                    }

                }

            }

        }

        public void UpdatePartyMemberHP(PartyHpData[] updates)

        {

            if (_uiParty == null || _currentPartyMembers == null || updates == null) return;

            foreach (var update in updates)

            {

                for (int i = 0; i < _currentPartyMembers.Length; i++)

                {

                    if (_currentPartyMembers[i].CharacterId == update.CharacterId)

                    {

                        _currentPartyMembers[i].CurrentHp = update.CurrentHp;

                        _currentPartyMembers[i].MaxHp = update.MaxHp;

                        _currentPartyMembers[i].CurrentMp = update.CurrentMp;

                        _currentPartyMembers[i].MaxMp = update.MaxMp;

                        if (_uiParty != null)

                        {

                            // HP slanted fill güncelle

                            float hpRatio = update.MaxHp > 0 ? (float)update.CurrentHp / update.MaxHp : 0f;

                            if (_partyHpFills[i] != null)

                            {

                                _partyHpFills[i].anchorMax = new Vector2(hpRatio, 1f);

                            }

                            // MP slanted fill güncelle

                            float mpRatio = update.MaxMp > 0 ? (float)update.CurrentMp / update.MaxMp : 0f;

                            if (_partyMpFills[i] != null)

                            {

                                _partyMpFills[i].anchorMax = new Vector2(mpRatio, 1f);

                            }

                        }

                        break;

                    }

                }

            }

        }

        private void ShowPartyDisbandConfirmation()

        {

            if (KOMessageBox.Instance != null)

            {

                KOMessageBox.Instance.ShowYesNo(

                    "Are you sure you want to disband the party?",

                    "Disband Party",

                    MsgBoxBehavior.BEHAVIOR_NOTHING,

                    onYes: () =>

                    {

                        if (PartyUI.Instance != null)

                            PartyUI.Instance.SendPartyLeave();

                    }

                );

            }

            else

            {

                if (PartyUI.Instance != null)

                    PartyUI.Instance.SendPartyLeave();

            }

        }

        private void ModernizePartyPanel(GameObject partyUI)

        {

            if (partyUI == null) return;

            // Early return if already modernized to prevent duplicate GameObject creation

            if (partyUI.transform.Find("HeaderBar") != null)

                return;

            var panelRt = partyUI.GetComponent<RectTransform>();

            if (panelRt != null)

            {

                panelRt.anchorMin = new Vector2(1f, 1f);

                panelRt.anchorMax = new Vector2(1f, 1f);

                panelRt.pivot = new Vector2(1f, 1f);

                panelRt.anchoredPosition = new Vector2(-160f, -110f);

                panelRt.sizeDelta = new Vector2(180f, 320f);

            }

            // Add transparent background to intercept clicks and prevent click-through to 3D world

            var panelImg = partyUI.GetComponent<Image>();

            if (panelImg == null) panelImg = partyUI.AddComponent<Image>();

            panelImg.color = new Color(0f, 0f, 0f, 0f);

            panelImg.raycastTarget = true;

            // Hide old backgrounds and clutter

            foreach (Transform child in partyUI.transform)

            {

                string name = child.name;

                bool isSlotComponent = false;

                for (int i = 0; i < 8; i++)

                {

                    if (name == $"Area_{i}" || name == $"static_name_{i}" || 

                        name == $"progress_hp_{i}" || name == $"progress_mp_{i}_curse")

                    {

                        isSlotComponent = true;

                        break;

                    }

                }

                if (!isSlotComponent)

                {

                    child.gameObject.SetActive(false);

                }

            }

            // Create modern Header Bar

            var headerObj = new GameObject("HeaderBar");

            headerObj.transform.SetParent(partyUI.transform, false);

            var headerRt = headerObj.AddComponent<RectTransform>();

            headerRt.anchorMin = new Vector2(0f, 1f);

            headerRt.anchorMax = new Vector2(0f, 1f);

            headerRt.pivot = new Vector2(0f, 1f);

            headerRt.anchoredPosition = new Vector2(7f, 0f);

            headerRt.sizeDelta = new Vector2(133f, 36f);

            var headerImg = headerObj.AddComponent<Image>();

            headerImg.sprite = GetArrowSprite("party_header_bg", 133, 36, 0, 0, new Color(0.1f, 0.1f, 0.1f, 0.7f), Color.clear, 0, horizontalGradient: true);

            // Add UIDragHandler to drag the whole panel via header

            var drag = headerObj.AddComponent<UIDragHandler>();

            drag.Initialize(panelRt);

            // "Kill:0" Text

            var killObj = new GameObject("KillText");

            killObj.transform.SetParent(headerObj.transform, false);

            var killText = killObj.AddComponent<Text>();

            killText.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");

            if (killText.font == null) killText.font = Resources.FindObjectsOfTypeAll<Font>()[0];

            killText.text = "💀 Kill:0";

            killText.fontSize = 9;

            killText.color = new Color(0.95f, 0.6f, 0.15f, 1f);

            killText.alignment = TextAnchor.MiddleLeft;

            var killRt = killObj.GetComponent<RectTransform>();

            killRt.anchorMin = new Vector2(0f, 0.5f);

            killRt.anchorMax = new Vector2(0f, 0.5f);

            killRt.pivot = new Vector2(0f, 0.5f);

            killRt.anchoredPosition = new Vector2(10f, 8f);

            killRt.sizeDelta = new Vector2(100f, 12f);

            // "PARTY" Title

            var titleObj = new GameObject("TitleText");

            titleObj.transform.SetParent(headerObj.transform, false);

            var titleText = titleObj.AddComponent<Text>();

            titleText.font = killText.font;

            titleText.text = "PARTY";

            titleText.fontSize = 15;

            titleText.fontStyle = FontStyle.Bold;

            titleText.color = new Color(0.9f, 0.75f, 0.3f, 1f); // Gold title

            titleText.alignment = TextAnchor.MiddleLeft;

            var titleRt = titleObj.GetComponent<RectTransform>();

            titleRt.anchorMin = new Vector2(0f, 0.5f);

            titleRt.anchorMax = new Vector2(0f, 0.5f);

            titleRt.pivot = new Vector2(0f, 0.5f);

            titleRt.anchoredPosition = new Vector2(10f, -8f);

            titleRt.sizeDelta = new Vector2(100f, 18f);

            // Helper to create buttons on top right

            System.Action<string, string, float, UnityEngine.Events.UnityAction> createHeaderBtn = (name, symbol, xPos, action) => {

                var btnObj = new GameObject(name);

                btnObj.transform.SetParent(headerObj.transform, false);

                var btnRt = btnObj.AddComponent<RectTransform>();

                btnRt.anchorMin = new Vector2(1f, 0.5f);

                btnRt.anchorMax = new Vector2(1f, 0.5f);

                btnRt.pivot = new Vector2(0.5f, 0.5f);

                btnRt.anchoredPosition = new Vector2(xPos, 0f);

                btnRt.sizeDelta = new Vector2(20f, 20f);

                var btnImg = btnObj.AddComponent<Image>();

                btnImg.color = new Color(0.25f, 0.25f, 0.25f, 0.9f); // Dark button frame

                var borderObj = new GameObject("Border");

                borderObj.transform.SetParent(btnObj.transform, false);

                var borderRt = borderObj.AddComponent<RectTransform>();

                borderRt.anchorMin = Vector2.zero;

                borderRt.anchorMax = Vector2.one;

                borderRt.offsetMin = Vector2.zero;

                borderRt.offsetMax = Vector2.zero;

                var borderImg = borderObj.AddComponent<Image>();

                borderImg.color = new Color(0.6f, 0.48f, 0.22f, 0.7f); // Gold button border

                var mask = borderObj.AddComponent<Mask>();

                mask.showMaskGraphic = true;

                var innerObj = new GameObject("Inner");

                innerObj.transform.SetParent(borderObj.transform, false);

                var innerRt = innerObj.AddComponent<RectTransform>();

                innerRt.anchorMin = Vector2.zero;

                innerRt.anchorMax = Vector2.one;

                innerRt.offsetMin = new Vector2(1f, 1f);

                innerRt.offsetMax = new Vector2(-1f, -1f);

                var innerImg = innerObj.AddComponent<Image>();

                innerImg.color = new Color(0.18f, 0.18f, 0.18f, 1f);

                var txtObj = new GameObject("Text");

                txtObj.transform.SetParent(innerObj.transform, false);

                var txt = txtObj.AddComponent<Text>();

                txt.font = killText.font;

                txt.text = symbol;

                txt.fontSize = 13;

                txt.alignment = TextAnchor.MiddleCenter;

                txt.color = new Color(0.9f, 0.75f, 0.3f, 1f);

                var txtRt = txtObj.GetComponent<RectTransform>();

                txtRt.anchorMin = Vector2.zero;

                txtRt.anchorMax = Vector2.one;

                txtRt.offsetMin = Vector2.zero;

                txtRt.offsetMax = Vector2.zero;

                var btnComp = btnObj.AddComponent<Button>();

                btnComp.onClick.AddListener(action);

            };

            // Create Star (Rank), Gear (Settings), X (Close) buttons

            createHeaderBtn("CloseBtn", "✕", -14f, () => ShowPartyDisbandConfirmation());

            createHeaderBtn("SettingsBtn", "⚙", -34f, () => {});

            // Modernize the 8 slots

            for (int i = 0; i < 8; i++)

            {

                var areaObj = partyUI.transform.Find($"Area_{i}");

                var nameObj = partyUI.transform.Find($"static_name_{i}");

                var progressHpObj = partyUI.transform.Find($"progress_hp_{i}");

                var progressMpObj = partyUI.transform.Find($"progress_mp_{i}_curse");

                if (areaObj == null || nameObj == null || progressHpObj == null || progressMpObj == null)

                    continue;

                float baseY = -50f - (i * 28f); // Dynamically space slots starting neatly below HeaderBar (Y = -36)

                var progressHpRt = progressHpObj.GetComponent<RectTransform>();

                // 1. Reshape Area button to cover the slot row

                var areaRt = areaObj.GetComponent<RectTransform>();

                areaRt.anchorMin = new Vector2(0f, 1f);

                areaRt.anchorMax = new Vector2(1f, 1f);

                areaRt.pivot = new Vector2(0f, 0.5f);

                areaRt.anchoredPosition = new Vector2(0f, baseY);

                areaRt.sizeDelta = new Vector2(148f, 24f);

                // Disable all pre-existing child game objects of Area_i to clean up old design artifacts

                foreach (Transform child in areaObj.transform)

                {

                    child.gameObject.SetActive(false);

                }

                // Enable transparent background image on Area_i itself for raycasting

                var areaImg = areaObj.GetComponent<UnityEngine.UI.Image>();

                if (areaImg == null) areaImg = areaObj.gameObject.AddComponent<UnityEngine.UI.Image>();

                areaImg.enabled = true;

                areaImg.color = Color.clear;

                areaImg.raycastTarget = true;

                var areaRaw = areaObj.GetComponent<UnityEngine.UI.RawImage>();

                if (areaRaw != null) areaRaw.enabled = false;

                // Add button handler to select slot member on click

                var btn = areaObj.GetComponent<Button>();

                if (btn == null) btn = areaObj.gameObject.AddComponent<Button>();

                int index = i;

                btn.onClick.RemoveAllListeners();

                btn.onClick.AddListener(() => {

                    if (KOPartyManager.Instance != null)

                        KOPartyManager.Instance.TargetByIndex(index);

                });

                // 2. Diamond slot index container

                var indexFrameObj = new GameObject($"SlotIndexFrame_{i}");

                indexFrameObj.transform.SetParent(partyUI.transform, false);

                var indexFrameImg = indexFrameObj.AddComponent<Image>();

                indexFrameImg.color = new Color(0.6f, 0.48f, 0.22f, 1f); // Gold border color

                indexFrameImg.raycastTarget = false;

                indexFrameObj.transform.localEulerAngles = new Vector3(0, 0, 45); // Rotate 45 deg

                var indexFrameRt = indexFrameObj.GetComponent<RectTransform>();

                indexFrameRt.anchorMin = new Vector2(0f, 1f);

                indexFrameRt.anchorMax = new Vector2(0f, 1f);

                indexFrameRt.pivot = new Vector2(0.5f, 0.5f);

                indexFrameRt.anchoredPosition = new Vector2(16f, baseY);

                indexFrameRt.sizeDelta = new Vector2(20f, 20f);

                var indexBgObj = new GameObject("IndexBG");

                indexBgObj.transform.SetParent(indexFrameObj.transform, false);

                _partyIndexBgs[i] = indexBgObj.AddComponent<Image>();

                _partyIndexBgs[i].color = (i == 0) ? new Color(0.796f, 0.004f, 0.035f, 0.95f) : new Color(0.5f, 0f, 0.5f, 0.95f); // Red for leader, Purple for others

                _partyIndexBgs[i].raycastTarget = false;

                var indexBgRt = indexBgObj.GetComponent<RectTransform>();

                indexBgRt.anchorMin = new Vector2(0.5f, 0.5f);

                indexBgRt.anchorMax = new Vector2(0.5f, 0.5f);

                indexBgRt.pivot = new Vector2(0.5f, 0.5f);

                indexBgRt.anchoredPosition = Vector2.zero;

                indexBgRt.sizeDelta = new Vector2(17f, 17f);

                var indexTextObj = new GameObject("IndexText");

                indexTextObj.transform.SetParent(indexBgObj.transform, false);

                indexTextObj.transform.localEulerAngles = new Vector3(0, 0, -45); // Counter rotate text

                var idxText = indexTextObj.AddComponent<Text>();

                idxText.font = killText.font;

                idxText.text = (i + 1).ToString();

                idxText.fontSize = 11;

                idxText.fontStyle = FontStyle.Bold;

                idxText.color = Color.white;

                idxText.alignment = TextAnchor.MiddleCenter;

                idxText.raycastTarget = false;

                _partyIndexTexts[i] = idxText;

                var indexTextRt = indexTextObj.GetComponent<RectTransform>();

                indexTextRt.anchorMin = Vector2.zero;

                indexTextRt.anchorMax = Vector2.one;

                indexTextRt.offsetMin = Vector2.zero;

                indexTextRt.offsetMax = Vector2.zero;

                // 3. Class/Job Icon image

                var classIconObj = new GameObject($"SlotClassIcon_{i}");

                classIconObj.transform.SetParent(partyUI.transform, false);

                _partyClassIcons[i] = classIconObj.AddComponent<Image>();

                _partyClassIcons[i].raycastTarget = false;

                var classIconRt = classIconObj.GetComponent<RectTransform>();

                classIconRt.anchorMin = new Vector2(0f, 1f);

                classIconRt.anchorMax = new Vector2(0f, 1f);

                classIconRt.pivot = new Vector2(0.5f, 0.5f);

                classIconRt.anchoredPosition = new Vector2(25f, baseY - 7f);

                classIconRt.sizeDelta = new Vector2(12f, 12f);

                // 4. Slanted HP bar

                progressHpRt.anchorMin = new Vector2(0f, 1f);

                progressHpRt.anchorMax = new Vector2(0f, 1f);

                progressHpRt.pivot = new Vector2(0f, 0.5f);

                progressHpRt.anchoredPosition = new Vector2(16f, baseY + 8f);

                progressHpRt.sizeDelta = new Vector2(123f, 12f);

                // Disable old children of progressHp

                foreach (Transform child in progressHpObj.transform)

                    child.gameObject.SetActive(false);

                var hpImg = progressHpObj.GetComponent<UnityEngine.UI.Image>();

                if (hpImg != null) hpImg.enabled = false;

                var hpRaw = progressHpObj.GetComponent<UnityEngine.UI.RawImage>();

                if (hpRaw != null) hpRaw.enabled = false;

                // Create HP slanted BG

                var hpBg = new GameObject("HPBarBG");

                hpBg.transform.SetParent(progressHpObj.transform, false);

                var hpBgImg = hpBg.AddComponent<Image>();

                hpBgImg.sprite = GetArrowSprite($"party_hp_bg_{i}", 123, 12, 0, 0, new Color(0.12f, 0.02f, 0.02f, 0.85f), Color.clear, 0);

                hpBgImg.raycastTarget = false;

                var hpBgRt = hpBg.GetComponent<RectTransform>();

                hpBgRt.anchorMin = Vector2.zero;

                hpBgRt.anchorMax = Vector2.one;

                hpBgRt.offsetMin = Vector2.zero;

                hpBgRt.offsetMax = Vector2.zero;

                // Create HP Mask

                var hpMask = new GameObject("HPBarMask");

                hpMask.transform.SetParent(progressHpObj.transform, false);

                var hpMaskImg = hpMask.AddComponent<Image>();

                hpMaskImg.sprite = GetArrowSprite($"party_hp_mask_{i}", 123, 12, 0, 0, Color.white, Color.clear, 0);

                hpMaskImg.raycastTarget = false;

                hpMask.AddComponent<Mask>().showMaskGraphic = false;

                var hpMaskRt = hpMask.GetComponent<RectTransform>();

                hpMaskRt.anchorMin = Vector2.zero;

                hpMaskRt.anchorMax = Vector2.one;

                hpMaskRt.offsetMin = Vector2.zero;

                hpMaskRt.offsetMax = Vector2.zero;

                // Create HP Fill (child of Mask)

                var hpFill = new GameObject("HPBarFG");

                hpFill.transform.SetParent(hpMask.transform, false);

                var hpFillImg = hpFill.AddComponent<Image>();

                hpFillImg.sprite = GetArrowSprite($"party_hp_fill_{i}", 123, 12, 0, 0, Color.white, Color.clear, 0, horizontalGradient: true);

                hpFillImg.color = new Color(0.796f, 0.004f, 0.035f, 0.95f); // Red fill

                hpFillImg.raycastTarget = false;

                _partyHpFills[i] = hpFill.GetComponent<RectTransform>();

                _partyHpFills[i].anchorMin = Vector2.zero;

                _partyHpFills[i].anchorMax = Vector2.one;

                _partyHpFills[i].pivot = new Vector2(0f, 0.5f);

                _partyHpFills[i].offsetMin = Vector2.zero;

                _partyHpFills[i].offsetMax = Vector2.zero;

                // Create HP Border

                var hpBorder = new GameObject("HPBarBorder");

                hpBorder.transform.SetParent(progressHpObj.transform, false);

                var hpBorderImg = hpBorder.AddComponent<Image>();

                hpBorderImg.sprite = GetArrowSprite($"party_hp_border_{i}", 123, 12, 0, 0, Color.clear, new Color(0.6f, 0.48f, 0.22f, 0.6f), 1);

                hpBorderImg.raycastTarget = false;

                var hpBorderRt = hpBorder.GetComponent<RectTransform>();

                hpBorderRt.anchorMin = Vector2.zero;

                hpBorderRt.anchorMax = Vector2.one;

                hpBorderRt.offsetMin = Vector2.zero;

                hpBorderRt.offsetMax = Vector2.zero;

                // Create Selection HP Gold Outline — no longer HP-bar only;

                // we keep this for backward compat but now it covers the FULL row

                // with a left-pointed arrow shape.

                var hpOutline = new GameObject("HPBarSelectedOutline");

                hpOutline.transform.SetParent(progressHpObj.transform, false);

                var hpOutlineImg = hpOutline.AddComponent<Image>();

                hpOutlineImg.sprite = GetArrowSprite($"party_hp_outline_{i}", 123, 12, 0, 0, Color.clear, Color.yellow, 2);

                hpOutlineImg.raycastTarget = false;

                hpOutlineImg.enabled = false; // Eski dar outline'ı gizle

                var hpOutlineRt = hpOutline.GetComponent<RectTransform>();

                hpOutlineRt.anchorMin = Vector2.zero;

                hpOutlineRt.anchorMax = Vector2.one;

                hpOutlineRt.offsetMin = Vector2.zero;

                hpOutlineRt.offsetMax = Vector2.zero;

                // --- Full-row arrow-shaped selection outline ---

                // Sol tarafı ok (baklava köşesi) şeklinde sivri, sağ/üst/alt düz kenar.

                // Tüm satırı (diamond index + HP bar + name + MP bar) kapsar ve HP barın bitişinde biter.

                var selOutline = new GameObject($"SlotSelectionOutline_{i}");

                selOutline.transform.SetParent(partyUI.transform, false);

                // Procedural diamond-wrapping outline:

                // Sol kenarı 45 derece eğimli baklava şekline uyar, içi şeffaftır, rengi bronz-altındır.

                int arrowW = 138, arrowH = 28;

                var arrowTex = new Texture2D(arrowW, arrowH, TextureFormat.RGBA32, false);

                arrowTex.filterMode = FilterMode.Bilinear;

                var pixels = new Color32[arrowW * arrowH];

                for (int p = 0; p < pixels.Length; p++) pixels[p] = new Color32(0, 0, 0, 0);

                int borderThickness = 2;

                Color32 gold = new Color32(255, 215, 0, 220); // Visible gold/yellow color

                for (int py = 0; py < arrowH; py++)

                {

                    // Baklavanın 45 derece dönüşüyle birebir uyumlu sol sınır (tipX)

                    int tipX = Mathf.Abs(py - 14);

                    for (int px = 0; px < arrowW; px++)

                    {

                        if (px < tipX) continue; // Dış kısım

                        // Sadece kenar çizgilerini çiz (içini doldurma)

                        bool isBorder = false;

                        // Sol eğik kenar

                        if (px >= tipX && px < tipX + borderThickness) isBorder = true;

                        // Sağ düz kenar

                        if (px >= arrowW - borderThickness) isBorder = true;

                        // Üst kenar

                        if (py >= arrowH - borderThickness && px >= tipX) isBorder = true;

                        // Alt kenar

                        if (py < borderThickness && px >= tipX) isBorder = true;

                        if (isBorder)

                        {

                            pixels[py * arrowW + px] = gold;

                        }

                    }

                }

                arrowTex.SetPixels32(pixels);

                arrowTex.Apply();

                var selOutlineImg = selOutline.AddComponent<Image>();

                selOutlineImg.sprite = Sprite.Create(arrowTex, new Rect(0, 0, arrowW, arrowH), new Vector2(0.5f, 0.5f), 100f);

                selOutlineImg.raycastTarget = false;

                var selOutlineRt = selOutline.GetComponent<RectTransform>();

                selOutlineRt.anchorMin = new Vector2(0f, 1f);

                selOutlineRt.anchorMax = new Vector2(0f, 1f);

                selOutlineRt.pivot = new Vector2(0f, 0.5f);

                selOutlineRt.anchoredPosition = new Vector2(1f, baseY);

                selOutlineRt.sizeDelta = new Vector2(138f, 28f);

                _partySlotSelectedOutlines[i] = selOutline;

                selOutline.SetActive(false);

                // --- Separate left arrow button (◄) ---

                var arrowBtn = new GameObject($"SlotArrowBtn_{i}");

                arrowBtn.transform.SetParent(partyUI.transform, false);

                // Ok butonu arka planı (resim ve altın kenarlık tek bir kavisli sprite içinde)

                var arrowBtnImg = arrowBtn.AddComponent<Image>();

                arrowBtnImg.sprite = GetSkillThemeRoundedRectSprite($"slot_arrow_btn_bg_v5_{i}", 72, 72, 12,

                    new Color(0.24f, 0.15f, 0.12f, 0.95f),

                    new Color(0.796f, 0.733f, 0.545f, 0.8f),

                    4);

                arrowBtnImg.color = Color.white;

                arrowBtnImg.raycastTarget = true;

                var arrowBtnRt = arrowBtn.GetComponent<RectTransform>();

                arrowBtnRt.anchorMin = new Vector2(0f, 1f);

                arrowBtnRt.anchorMax = new Vector2(0f, 1f);

                arrowBtnRt.pivot = new Vector2(1f, 0.5f);

                arrowBtnRt.anchoredPosition = new Vector2(-5f, baseY);

                arrowBtnRt.sizeDelta = new Vector2(18f, 18f);

                // Ok simgesi (◄)

                var arrowIconObj = new GameObject("ArrowIcon");

                arrowIconObj.transform.SetParent(arrowBtn.transform, false);

                var arrowIconText = arrowIconObj.AddComponent<Text>();

                arrowIconText.font = killText.font;

                arrowIconText.text = "◄";

                arrowIconText.fontSize = 12;

                arrowIconText.alignment = TextAnchor.MiddleCenter;

                arrowIconText.color = new Color(0.886f, 0.768f, 0.549f, 1f); // exit button text color

                arrowIconText.raycastTarget = false;

                var arrowIconRt = arrowIconObj.GetComponent<RectTransform>();

                arrowIconRt.anchorMin = Vector2.zero;

                arrowIconRt.anchorMax = Vector2.one;

                arrowIconRt.offsetMin = Vector2.zero;

                arrowIconRt.offsetMax = Vector2.zero;

                // Buton bileşeni ekle (işlev daha sonra atanacak)

                var arrowBtnComp = arrowBtn.AddComponent<Button>();

                arrowBtnComp.targetGraphic = arrowBtnImg;

                int arrowIndex = i;

                arrowBtnComp.onClick.AddListener(() => {

                    if (KOPartyManager.Instance == null) return;

                    long myId = GameManager.Instance != null ? GameManager.Instance.CharacterId : 0;

                    long leaderId = KOPartyManager.Instance.LeaderId;

                    if (leaderId == -1 && _currentPartyMembers != null && _currentPartyMembers.Length > 0)

                        leaderId = _currentPartyMembers[0].CharacterId;

                    bool iAmLeader = (leaderId == myId);

                    if (!iAmLeader) return;

                    if (_currentPartyMembers == null || arrowIndex >= _currentPartyMembers.Length) return;

                    var member = _currentPartyMembers[arrowIndex];

                    if (member.CharacterId == myId) return;

                    CreatePartyActionMenu();

                    if (_partyActionMenu.activeSelf && _partyActionMenuTargetId == member.CharacterId)

                    {

                        _partyActionMenu.SetActive(false);

                    }

                    else

                    {

                        _partyActionMenuTargetId = member.CharacterId;

                        _partyActionMenu.transform.SetParent(arrowBtn.transform, false);

                        var actionRt = _partyActionMenu.GetComponent<RectTransform>();

                        actionRt.anchorMin = new Vector2(0f, 0.5f);

                        actionRt.anchorMax = new Vector2(0f, 0.5f);

                        actionRt.pivot = new Vector2(1f, 0.5f);

                        actionRt.anchoredPosition = new Vector2(-6f, 0f);

                        _partyActionMenu.SetActive(true);

                    }

                });

                _partySlotArrowBtns[i] = arrowBtn;

                arrowBtn.SetActive(false);

                // 5. Slanted thin MP bar

                var progressMpRt = progressMpObj.GetComponent<RectTransform>();

                progressMpRt.anchorMin = new Vector2(0f, 1f);

                progressMpRt.anchorMax = new Vector2(0f, 1f);

                progressMpRt.pivot = new Vector2(0f, 0.5f);

                progressMpRt.anchoredPosition = new Vector2(16f, baseY + 1f);

                progressMpRt.sizeDelta = new Vector2(123f, 2f);

                // Disable old children of progressMp

                foreach (Transform child in progressMpObj.transform)

                    child.gameObject.SetActive(false);

                var mpImg = progressMpObj.GetComponent<UnityEngine.UI.Image>();

                if (mpImg != null) mpImg.enabled = false;

                var mpRaw = progressMpObj.GetComponent<UnityEngine.UI.RawImage>();

                if (mpRaw != null) mpRaw.enabled = false;

                // Create MP BG

                var mpBg = new GameObject("MPBarBG");

                mpBg.transform.SetParent(progressMpObj.transform, false);

                var mpBgImg = mpBg.AddComponent<Image>();

                mpBgImg.color = new Color(0.02f, 0.02f, 0.12f, 0.85f);

                mpBgImg.raycastTarget = false;

                var mpBgRt = mpBg.GetComponent<RectTransform>();

                mpBgRt.anchorMin = Vector2.zero;

                mpBgRt.anchorMax = Vector2.one;

                mpBgRt.offsetMin = Vector2.zero;

                mpBgRt.offsetMax = Vector2.zero;

                // Create MP Mask

                var mpMask = new GameObject("MPBarMask");

                mpMask.transform.SetParent(progressMpObj.transform, false);

                var mpMaskImg = mpMask.AddComponent<Image>();

                mpMaskImg.color = Color.white;

                mpMaskImg.raycastTarget = false;

                mpMask.AddComponent<Mask>().showMaskGraphic = false;

                var mpMaskRt = mpMask.GetComponent<RectTransform>();

                mpMaskRt.anchorMin = Vector2.zero;

                mpMaskRt.anchorMax = Vector2.one;

                mpMaskRt.offsetMin = Vector2.zero;

                mpMaskRt.offsetMax = Vector2.zero;

                // Create MP Fill

                var mpFill = new GameObject("MPBarFG");

                mpFill.transform.SetParent(mpMask.transform, false);

                var mpFillImg = mpFill.AddComponent<Image>();

                mpFillImg.color = new Color(0.216f, 0.337f, 0.988f, 0.95f); // Blue fill

                mpFillImg.raycastTarget = false;

                _partyMpFills[i] = mpFill.GetComponent<RectTransform>();

                _partyMpFills[i].anchorMin = Vector2.zero;

                _partyMpFills[i].anchorMax = Vector2.one;

                _partyMpFills[i].pivot = new Vector2(0f, 0.5f);

                _partyMpFills[i].offsetMin = Vector2.zero;

                _partyMpFills[i].offsetMax = Vector2.zero;

                // 6. Modern Name Text overlay

                var nameText = nameObj.GetComponent<Text>();

                if (nameText == null) nameText = nameObj.GetComponentInChildren<Text>();

                if (nameText != null)

                {

                    nameText.font = killText.font;

                    nameText.fontSize = 12;

                    nameText.alignment = TextAnchor.MiddleLeft;

                    nameText.color = Color.white;

                    nameText.supportRichText = false;

                    nameText.raycastTarget = false;

                }

                var nameRt = nameObj.GetComponent<RectTransform>();

                nameRt.anchorMin = new Vector2(0f, 1f);

                nameRt.anchorMax = new Vector2(0f, 1f);

                nameRt.pivot = new Vector2(0f, 0.5f);

                nameRt.anchoredPosition = new Vector2(40f, baseY - 7f);

                nameRt.sizeDelta = new Vector2(100f, 14f);

                // Create Name Background with left-to-right fadeout

                var nameBgObj = new GameObject($"SlotNameBg_{i}");

                nameBgObj.transform.SetParent(partyUI.transform, false);

                var nameBgImg = nameBgObj.AddComponent<Image>();

                nameBgImg.sprite = GetArrowSprite($"party_name_bg_{i}", 123, 14, 0, 0, new Color(0f, 0f, 0f, 0.5f), Color.clear, 0, horizontalGradient: true);

                nameBgImg.raycastTarget = false;

                var nameBgRt = nameBgObj.GetComponent<RectTransform>();

                nameBgRt.anchorMin = new Vector2(0f, 1f);

                nameBgRt.anchorMax = new Vector2(0f, 1f);

                nameBgRt.pivot = new Vector2(0f, 0.5f);

                nameBgRt.anchoredPosition = new Vector2(16f, baseY - 7f);

                nameBgRt.sizeDelta = new Vector2(123f, 14f);

                progressHpObj.transform.SetAsFirstSibling();

                progressMpObj.transform.SetAsFirstSibling();

                nameBgObj.transform.SetAsLastSibling();

                indexFrameObj.transform.SetAsLastSibling();

                classIconObj.transform.SetAsLastSibling();

                nameObj.transform.SetAsLastSibling();

                selOutline.transform.SetAsLastSibling();

                areaObj.transform.SetAsLastSibling(); // Tıklama alanı görsellerin üzerinde

                arrowBtn.transform.SetAsLastSibling(); // Sol ok butonu tıklama alanının da üzerinde

            }

        }

        /// <summary>

        /// Parti davet diyaloğunu gösterir.

        /// Open-KO birebir: GameProcMain.cpp:5165-5169

        /// std::string szMsg = fmt::format_text_resource(IDS_PARTY_PERMIT);

        /// MessageBoxPost(szID + szMsg, "", MB_YESNO, BEHAVIOR_PARTY_PERMIT);

        ///

        /// Mobil adaptasyon: Basit Evet/Hayır dialog.

        /// </summary>

        public void ShowPartyInviteDialog(long inviterId, string inviterName)

        {

            // Open-KO birebir: GameProcMain.cpp:5165-5169

            // std::string szMsg = fmt::format_text_resource(IDS_PARTY_PERMIT);

            // MessageBoxPost(szID + szMsg, "", MB_YESNO, BEHAVIOR_PARTY_PERMIT);

            string message = $"{inviterName} sent you a party request.";

            if (KOMessageBox.Instance != null)

            {

                // Open-KO birebir: UIMessageBox.cpp ReceiveMessage

                //   Yes → MsgSend_PartyOrForcePermit(true)   (cpp:125-127)

                //   No  → MsgSend_PartyOrForcePermit(false)  (cpp:189-191)

                KOMessageBox.Instance.ShowYesNo(

                    message, "Party Request",

                    MsgBoxBehavior.BEHAVIOR_PARTY_PERMIT,

                    onYes: () =>

                    {

                        if (PartyUI.Instance != null)

                            PartyUI.Instance.SendPartyResponse(inviterId, true);

                    },

                    onNo: () =>

                    {

                        if (PartyUI.Instance != null)

                            PartyUI.Instance.SendPartyResponse(inviterId, false);

                    },

                    countdownDuration: 30,

                    autoClickOnTimeout: true

                );

            }

            else

            {

                Debug.LogWarning("[KOUIMGR] KOMessageBox yüklenmemiş — party davet gösterilemedi");

            }

        }

        /// <summary>

        /// Item Upgrade panelini göster/gizle.

        /// C++ referans: UIItemUpgrade.cpp SetVisible() satır 563-578

        /// Open: CopyInventoryItems + GoldUpdate

        /// Close: ResetUpgradeInventory + AnimClose

        /// </summary>

                public void ShowGemChestExchange(bool show, short npcId = 0, int talkId = 0, int[] menuTextIds = null)

                        {

                            if (_uiGemChestExchange == null)

                            {

                                _uiGemChestExchange = LoadModernUIPanelDirect("co_GemChestExchange_us");

                                if (_uiGemChestExchange != null)

                                {

                                    _uiGemChestExchange.AddComponent<KOUIScaleIndependent>();

                                    // Position and push offscreen right BEFORE adding slide component to avoid initialization flicker

                                    SetPanelPosRightCenter(_uiGemChestExchange);

                                    var rt = _uiGemChestExchange.GetComponent<RectTransform>();

                                    if (rt != null)

                                    {

                                        var pos = rt.anchoredPosition;

                                        pos.x = 450f; // StartX

                                        rt.anchoredPosition = pos;

                                    }

                                    var slide = _uiGemChestExchange.GetComponent<KOUIPanelSlideIn>() ?? _uiGemChestExchange.AddComponent<KOUIPanelSlideIn>();

                                    slide.TargetX = -50f;

                                    slide.StartX = 450f;

                                    _uiGemChestExchange.SetActive(false);

                                    BindGemChestExchangeCloseButton(_uiGemChestExchange.transform);

                                }

                            }

                            else

                            {

                                // Ensure slide is present and configured

                                var slide = _uiGemChestExchange.GetComponent<KOUIPanelSlideIn>();

                                if (slide == null)

                                {

                                    slide = _uiGemChestExchange.AddComponent<KOUIPanelSlideIn>();

                                    slide.TargetX = -50f;

                                    slide.StartX = 450f;

                                }

                            }

                            if (_uiGemChestExchange == null)

                            {

                                Debug.LogError("[QUEST] co_GemChestExchange_us prefab could not be loaded dynamically!");

                                return;

                            }

                            if (show)

                            {

                                OnPanelOpened(_uiGemChestExchange);

                                // Position and push offscreen right BEFORE SetActive(true) to prevent flicker on left

                                SetPanelPosRightCenter(_uiGemChestExchange);

                                var rt = _uiGemChestExchange.GetComponent<RectTransform>();

                                if (rt != null)

                                {

                                    var pos = rt.anchoredPosition;

                                    pos.x = 450f; // StartX (offscreen right)

                                    rt.anchoredPosition = pos;

                                }

                                _uiGemChestExchange.SetActive(true);

                                _uiGemChestExchange.transform.SetAsLastSibling();

                                var exchangeMgr = _uiGemChestExchange.GetComponent<KOGemChestExchangeManager>();

                                if (exchangeMgr == null)

                                {

                                    exchangeMgr = _uiGemChestExchange.AddComponent<KOGemChestExchangeManager>();

                                }

                                if (menuTextIds != null)

                                {

                                    exchangeMgr.InitializeUI(_uiGemChestExchange.transform, npcId, talkId, menuTextIds);

                                }

                                var goldText = KOUIRenderer.FindChildText(_uiGemChestExchange.transform, "text_gold");

                                if (goldText != null && KOInventory.Instance != null)

                                {

                                    goldText.text = Core.GameManager.Instance.Gold.ToString("N0");

                                }

                                RepositionSkillBarForPanel();

                            }

                            else

                            {

                                var slide = _uiGemChestExchange.GetComponent<KOUIPanelSlideIn>();

                                if (slide != null && _uiGemChestExchange.activeSelf)

                                {

                                    slide.SlideOut(() => {

                                        _uiGemChestExchange.SetActive(false);

                                        RepositionSkillBarForPanel();

                                    });

                                    RepositionSkillBarForPanel();

                                }

                                else

                                {

                                    if (_uiGemChestExchange != null) _uiGemChestExchange.SetActive(false);

                                    RepositionSkillBarForPanel();

                                }

                            }

                        }

private void BindGemChestExchangeCloseButton(Transform root)

        {

            var btnClose = KOUIRenderer.FindChildButton(root.gameObject, "btn_close");

            if (btnClose != null)

            {

                btnClose.onClick.RemoveAllListeners();

                btnClose.onClick.AddListener(() => { ShowGemChestExchange(false); });

            }

        }

public void ShowItemUpgrade(bool show)

        {

            if (_uiItemUpgrade == null) return;

            _uiItemUpgrade.SetActive(show);

            if (show)

            {

                OnPanelOpened(_uiItemUpgrade);

                // Ensure covers are inactive and reset initially

                ResetCovers();

                _uiItemUpgrade.transform.SetAsLastSibling();

                SetPanelPosRightCenter(_uiItemUpgrade);

                // C++ SetVisible(true) satır 569-571: CancelIconDrop + CopyInventoryItems + GoldUpdate

                // Mobil: CopyInventoryItems → PopulateUpgradeInventory (slot ikonlarını render et)

                UpdateUpgradeGold();

                PopulateUpgradeInventory();

            }

            else

            {

                // Stop running animation coroutine

                if (_upgradeAnimationCoroutine != null)

                {

                    StopCoroutine(_upgradeAnimationCoroutine);

                    _upgradeAnimationCoroutine = null;

                }

                // Explicitly hide covers and restore cached positions

                ResetCovers();

                // C++ SetVisibleWithNoSound(false) satır 597-598: ResetUpgradeInventory + AnimClose

                var mgr = KOItemUpgradeManager.Instance;

                if (mgr != null)

                {

                    mgr.IsUpgradeInProgress = false;

                    mgr.ResetUpgradeInventory();

                }

                ClearUpgradeIcons();

            }

            RepositionSkillBarForPanel();

        }

        /// <summary>

        public void ShowUpgradeSelect(bool show, int npcId = 0)

        {

            if (_uiUpgradeSelect == null) return;

            if (show)

            {

                // Eğer herhangi bir upgrade işlemi devam ediyorsa yeni seçim panelini açma

                var mgr = KOItemUpgradeManager.Instance;

                var fastMgr = KOFastUpgradeManager.Instance;

                var ringMgr = KOAccessoryUpgradeManager.Instance;

                if ((mgr != null && mgr.IsUpgradeInProgress) || 

                    (fastMgr != null && fastMgr.IsUpgradeInProgress) || 

                    (ringMgr != null && ringMgr.IsUpgradeInProgress))

                {

                    Debug.LogWarning("[UPGRADE] Upgrade in progress – blocking ShowUpgradeSelect.");

                    return;

                }

                OnPanelOpened(_uiUpgradeSelect);

            }

            _uiUpgradeSelect.SetActive(show);

            if (show)

            {

                SetPanelPosRightCenter(_uiUpgradeSelect);

            }

            if (show && npcId != 0)

            {

                var btnUpgrade1 = KOUIRenderer.FindChildButton(_uiUpgradeSelect.transform, "btn_upgrade_item");

                var btnUpgrade2 = KOUIRenderer.FindChildButton(_uiUpgradeSelect.transform, "btn_accessory_upgrade");

                var btnFastUpgrade = KOUIRenderer.FindChildButton(_uiUpgradeSelect.transform, "btn_fast_upgrade");

                var btnClose = KOUIRenderer.FindChildButton(_uiUpgradeSelect.transform, "btn_close");

                if (btnUpgrade1 != null)

                {

                    btnUpgrade1.onClick.RemoveAllListeners();

                    btnUpgrade1.onClick.AddListener(() =>

                    {

                        ShowUpgradeSelect(false, 0);

                        if (_anvilOpenedFromQuestMenu)

                        {

                            _anvilOpenedFromQuestMenu = false;

                            SendSelectMenu(0);

                        }

                        if (UpgradeUI.Instance != null)

                        {

                            UpgradeUI.Instance.Open(npcId);

                        }

                    });

                }

                if (btnUpgrade2 != null)

                {

                    btnUpgrade2.onClick.RemoveAllListeners();

                    btnUpgrade2.onClick.AddListener(() =>

                    {

                        ShowUpgradeSelect(false, 0);

                        if (_anvilOpenedFromQuestMenu)

                        {

                            _anvilOpenedFromQuestMenu = false;

                            SendSelectMenu(1);

                        }

                        ShowRingUpgrade(true, npcId);

                    });

                }

                if (btnFastUpgrade != null)

                {

                    btnFastUpgrade.onClick.RemoveAllListeners();

                    btnFastUpgrade.onClick.AddListener(() =>

                    {

                        ShowUpgradeSelect(false, 0);

                        if (_anvilOpenedFromQuestMenu)

                        {

                            _anvilOpenedFromQuestMenu = false;

                            SendSelectMenu(0); // Server treats fast upgrade as item upgrade

                        }

                        ShowFastUpgrade(true, npcId);

                    });

                }

                if (btnClose != null)

                {

                    btnClose.onClick.RemoveAllListeners();

                    btnClose.onClick.AddListener(() =>

                    {

                        ShowUpgradeSelect(false, 0);

                        if (_anvilOpenedFromQuestMenu)

                        {

                            _anvilOpenedFromQuestMenu = false;

                            SendSelectMenu(2); // Walk away

                        }

                    });

                }

            }

            RepositionSkillBarForPanel();

        }

        public void ShowFastUpgrade(bool show, int npcId = 0)

        {

            if (_uiFastUpgrade == null) return;

            if (show)

            {

                OnPanelOpened(_uiFastUpgrade);

            }

            _uiFastUpgrade.SetActive(show);

            if (show)

            {

                ResetCovers();

                _uiFastUpgrade.transform.SetAsLastSibling();

                SetPanelPosRightCenter(_uiFastUpgrade);

                var mgr = KOFastUpgradeManager.Instance;

                if (mgr != null)

                {

                    mgr.SetNpcID(npcId);

                    mgr.ResetUpgradeInventory();

                }

                UpdateUpgradeGold();

                PopulateUpgradeInventory();

            }

            else

            {

                if (_upgradeAnimationCoroutine != null)

                {

                    StopCoroutine(_upgradeAnimationCoroutine);

                    _upgradeAnimationCoroutine = null;

                }

                ResetCovers();

                var mgr = KOFastUpgradeManager.Instance;

                if (mgr != null)

                {

                    mgr.IsUpgradeInProgress = false;

                    mgr.ResetUpgradeInventory();

                }

                ClearUpgradeIcons();

            }

            RepositionSkillBarForPanel();

        }

        private void CreateUpgradeSelectPanelDynamically()

        {

            if (_canvas == null)

            {

                Debug.LogError("[KOUIMGR] Canvas bulunamadı! UpgradeSelect oluşturulamadı.");

                return;

            }

            // Create panel container object

            _uiUpgradeSelect = new GameObject("UpgradeSelectUIPanel", typeof(RectTransform));

            _uiUpgradeSelect.transform.SetParent(_canvas.transform, false);

            // Scale-independent constant size

            _uiUpgradeSelect.AddComponent<KOUIScaleIndependent>();

            var rt = _uiUpgradeSelect.GetComponent<RectTransform>();

            rt.anchorMin = new Vector2(1f, 0.5f);

            rt.anchorMax = new Vector2(1f, 0.5f);

            rt.pivot = new Vector2(1f, 0.5f);

            rt.sizeDelta = new Vector2(200f, 178f); // Height 178 for 4 buttons (including Title and padding)

            rt.anchoredPosition = new Vector2(-50f, 0f);

            // Generate background texture (matching InnUI style: dark charcoal with thin bronze border)

            Texture2D bgTex = new Texture2D(200, 178, TextureFormat.RGBA32, false);

            Color bgColor = new Color(0.06f, 0.05f, 0.05f, 0.85f);

            Color borderColor = new Color(0.45f, 0.12f, 0.12f, 0.90f); // Dark red/bronze border

            for (int y = 0; y < 178; y++)

            {

                for (int x = 0; x < 200; x++)

                {

                    if (x < 2 || x >= 200 - 2 || y < 2 || y >= 178 - 2)

                        bgTex.SetPixel(x, y, borderColor);

                    else

                        bgTex.SetPixel(x, y, bgColor);

                }

            }

            bgTex.Apply();

            var bgImg = _uiUpgradeSelect.AddComponent<UnityEngine.UI.Image>();

            bgImg.sprite = Sprite.Create(bgTex, new Rect(0, 0, 200, 178), new Vector2(0.5f, 0.5f));

            // Create title label "Select Upgrade"

            GameObject titleGo = new GameObject("TitleText", typeof(RectTransform));

            titleGo.transform.SetParent(_uiUpgradeSelect.transform, false);

            var titleRt = titleGo.GetComponent<RectTransform>();

            titleRt.anchorMin = new Vector2(0.5f, 1f);

            titleRt.anchorMax = new Vector2(0.5f, 1f);

            titleRt.pivot = new Vector2(0.5f, 1f);

            titleRt.sizeDelta = new Vector2(180f, 24f);

            titleRt.anchoredPosition = new Vector2(0f, -8f);

            var titleTxt = titleGo.AddComponent<UnityEngine.UI.Text>();

            titleTxt.text = "Select Upgrade";

            titleTxt.alignment = TextAnchor.MiddleCenter;

            titleTxt.color = new Color(0.92f, 0.80f, 0.52f, 1f); // Gold

            titleTxt.fontSize = 13;

            titleTxt.fontStyle = FontStyle.Bold;

            titleTxt.font = GetSafeFont(13);

            // Stacked buttons layout:

            // 1. Item Upgrade

            // 2. Fast Upgrade (Placeholder / Inactive)

            // 3. Accessory Upgrade

            // 4. Close (Red)

            Color blueBtnColor = new Color(0.08f, 0.22f, 0.35f, 0.85f);

            Color redBtnColor = new Color(0.45f, 0.05f, 0.08f, 0.85f);

            Color textGold = new Color(0.92f, 0.80f, 0.52f, 1f);

            CreateUpgradeSelectButton(_uiUpgradeSelect.transform, "Item Upgrade", "btn_upgrade_item", blueBtnColor, textGold, 180f, 30f, -36f);

            CreateUpgradeSelectButton(_uiUpgradeSelect.transform, "Fast Upgrade", "btn_fast_upgrade", blueBtnColor, textGold, 180f, 30f, -70f, true);

            CreateUpgradeSelectButton(_uiUpgradeSelect.transform, "Accessory Upgrade", "btn_accessory_upgrade", blueBtnColor, textGold, 180f, 30f, -104f);

            CreateUpgradeSelectButton(_uiUpgradeSelect.transform, "Close", "btn_close", redBtnColor, textGold, 180f, 30f, -138f);

            _uiUpgradeSelect.SetActive(false);

        }

        private GameObject CreateUpgradeSelectButton(Transform parent, string labelText, string goName, Color normalColor, Color textColor, float width, float height, float yPos, bool interactable = true)

        {

            GameObject btnObj = new GameObject(goName, typeof(RectTransform));

            btnObj.transform.SetParent(parent, false);

            var rt = btnObj.GetComponent<RectTransform>();

            rt.anchorMin = new Vector2(0.5f, 1f);

            rt.anchorMax = new Vector2(0.5f, 1f);

            rt.pivot = new Vector2(0.5f, 1f);

            rt.sizeDelta = new Vector2(width, height);

            rt.anchoredPosition = new Vector2(0f, yPos);

            var img = btnObj.AddComponent<UnityEngine.UI.Image>();

            // Draw button background texture with thin border

            int w = Mathf.RoundToInt(width);

            int h = Mathf.RoundToInt(height);

            Texture2D btnTex = new Texture2D(w, h, TextureFormat.RGBA32, false);

            Color borderCol = new Color(0.45f, 0.35f, 0.18f, 0.90f);

            if (normalColor.r > 0.4f && normalColor.g < 0.2f) // Close button (red) border

            {

                borderCol = new Color(0.65f, 0.15f, 0.15f, 0.90f);

            }

            for (int y = 0; y < h; y++)

            {

                for (int x = 0; x < w; x++)

                {

                    if (x < 1 || x >= w - 1 || y < 1 || y >= h - 1)

                        btnTex.SetPixel(x, y, borderCol);

                    else

                        btnTex.SetPixel(x, y, normalColor);

                }

            }

            btnTex.Apply();

            img.sprite = Sprite.Create(btnTex, new Rect(0, 0, w, h), new Vector2(0.5f, 0.5f));

            var btn = btnObj.AddComponent<UnityEngine.UI.Button>();

            btn.interactable = interactable;

            GameObject txtObj = new GameObject("Text", typeof(RectTransform));

            txtObj.transform.SetParent(btnObj.transform, false);

            var txtRt = txtObj.GetComponent<RectTransform>();

            txtRt.anchorMin = Vector2.zero;

            txtRt.anchorMax = Vector2.one;

            txtRt.sizeDelta = Vector2.zero;

            var txt = txtObj.AddComponent<UnityEngine.UI.Text>();

            txt.text = labelText;

            txt.alignment = TextAnchor.MiddleCenter;

            txt.color = textColor;

            txt.fontSize = 12;

            txt.fontStyle = FontStyle.Bold;

            txt.font = GetSafeFont(12);

            return btnObj;

        }

        private Sprite GetGoldIconSprite()

        {

            if (_uiInventory != null)

            {

                var tr = _uiInventory.transform.Find("btn_gold") ?? KOUIRenderer.FindChildByID(_uiInventory.transform, "btn_gold");

                if (tr != null)

                {

                    var img = tr.GetComponent<UnityEngine.UI.Image>();

                    if (img != null && img.sprite != null) return img.sprite;

                }

            }

            return null;

        }

        public void ConfigureGoldIcon(UnityEngine.UI.RawImage destImg)

        {

            if (destImg == null) return;

            Transform sourceTr = null;

            if (_uiInventory != null)

                sourceTr = _uiInventory.transform.Find("btn_gold") ?? KOUIRenderer.FindChildByID(_uiInventory.transform, "btn_gold");

            if (sourceTr == null && _uiTransaction != null)

                sourceTr = _uiTransaction.transform.Find("btn_gold") ?? KOUIRenderer.FindChildByID(_uiTransaction.transform, "btn_gold");

            if (sourceTr != null)

            {

                var srcImage = sourceTr.GetComponent<UnityEngine.UI.Image>();

                if (srcImage != null && srcImage.sprite != null)

                {

                    destImg.texture = srcImage.sprite.texture;

                    destImg.uvRect = new Rect(

                        srcImage.sprite.rect.x / srcImage.sprite.texture.width,

                        srcImage.sprite.rect.y / srcImage.sprite.texture.height,

                        srcImage.sprite.rect.width / srcImage.sprite.texture.width,

                        srcImage.sprite.rect.height / srcImage.sprite.texture.height

                    );

                    destImg.color = Color.white;

                    return;

                }

                var srcRaw = sourceTr.GetComponent<UnityEngine.UI.RawImage>();

                if (srcRaw != null)

                {

                    destImg.texture = srcRaw.texture;

                    destImg.uvRect = srcRaw.uvRect;

                    destImg.color = Color.white;

                }

            }

        }

