            }

            var coinValBgRt = coinValBgGo.GetComponent<RectTransform>();

            coinValBgRt.anchorMin = new Vector2(0.5f, 1f);

            coinValBgRt.anchorMax = new Vector2(0.5f, 1f);

            coinValBgRt.pivot = new Vector2(0.5f, 1f);

            if (isFastUpgradePanel)

            {

                coinValBgRt.sizeDelta = new Vector2(94f, 21f); // Fits beautifully inside 104px container

            }

            else

            {

                coinValBgRt.sizeDelta = new Vector2(70f, 21f);

            }

            coinValBgRt.anchoredPosition = new Vector2(0f, -18f); // 3px gap below the 15px label

            var coinValBgImg = coinValBgGo.GetComponent<UnityEngine.UI.Image>();

            if (coinValBgImg == null) coinValBgImg = coinValBgGo.AddComponent<UnityEngine.UI.Image>();

            coinValBgImg.sprite = GetSkillThemeRoundedRectSprite("upgrade_rate_val_bg_v4", 560, 168, 64,

                new Color(0.05f, 0.05f, 0.05f, 0.9f),

                new Color(0.6f, 0.48f, 0.22f, 0.8f),

                8);

            coinValBgImg.color = Color.white;

            // 3. ValueText

            var coinValGo = coinValBgGo.transform.Find("ValueText")?.gameObject;

            if (coinValGo == null)

            {

                coinValGo = new GameObject("ValueText", typeof(RectTransform));

                coinValGo.transform.SetParent(coinValBgGo.transform, false);

            }

            var coinValRt = coinValGo.GetComponent<RectTransform>();

            coinValRt.anchorMin = Vector2.zero;

            coinValRt.anchorMax = Vector2.one;

            coinValRt.sizeDelta = Vector2.zero;

            coinValRt.anchoredPosition = Vector2.zero;

            var coinValTxt = coinValGo.GetComponent<UnityEngine.UI.Text>();

            if (coinValTxt == null) coinValTxt = coinValGo.AddComponent<UnityEngine.UI.Text>();

            coinValTxt.text = "0";

            coinValTxt.alignment = TextAnchor.MiddleCenter;

            coinValTxt.color = new Color(0.95f, 0.82f, 0.55f, 1f);

            coinValTxt.fontSize = 11;

            coinValTxt.fontStyle = FontStyle.Bold;

            coinValTxt.font = GetSafeFont(11);

            needCoinsContainerGo.SetActive(false);

            topBgImg.color = Color.white;

            // 3. Style slot grids with custom glass sprite matching inventory slot aesthetics

            Sprite slotSprite = GetSkillThemeGlassSlotSprite("slot_socket_glass_v5", 45);

            // Shift and style all a_m_X requirement slots (shifted up by 20px)

            for (int i = 0; i < 9; i++)

            {

                var slot = root.Find($"a_m_{i}");

                if (slot != null)

                {

                    var img = slot.GetComponent<UnityEngine.UI.Image>();

                    if (img == null) img = slot.gameObject.AddComponent<UnityEngine.UI.Image>();

                    img.sprite = slotSprite;

                    img.color = Color.white;

                    if (!alreadyInitialized && !isModern)

                    {

                        var rt = slot.GetComponent<RectTransform>();

                        if (rt != null)

                        {

                            rt.anchoredPosition = new Vector2(rt.anchoredPosition.x, rt.anchoredPosition.y + 20f);

                        }

                    }

                }

            }

            // Shift and style a_upgrade (main slot) and a_result (result slot) (shifted up by 20px)

            string[] mainSlots = new string[] { "a_upgrade", "a_result" };

            foreach (var slotName in mainSlots)

            {

                var slot = root.Find(slotName);

                if (slot != null)

                {

                    var img = slot.GetComponent<UnityEngine.UI.Image>();

                    if (img == null) img = slot.gameObject.AddComponent<UnityEngine.UI.Image>();

                    img.sprite = slotSprite;

                    img.color = Color.white;

                    if (!alreadyInitialized && !isModern)

                    {

                        var rt = slot.GetComponent<RectTransform>();

                        if (rt != null)

                        {

                            rt.anchoredPosition = new Vector2(rt.anchoredPosition.x, rt.anchoredPosition.y + 20f);

                        }

                    }

                }

            }

            // Style and position all a_slot_X inventory slots in a symmetric grid (shifted up by 20px, left margin=16px, right margin=16px)

            for (int i = 0; i < 28; i++)

            {

                var slot = root.Find($"a_slot_{i}");

                if (slot != null)

                {

                    var img = slot.GetComponent<UnityEngine.UI.Image>();

                    if (img == null) img = slot.gameObject.AddComponent<UnityEngine.UI.Image>();

                    img.sprite = slotSprite;

                    img.color = Color.white;

                    var slotRT = slot.GetComponent<RectTransform>();

                    if (slotRT != null)

                    {

                        slotRT.anchorMin = new Vector2(0f, 1f);

                        slotRT.anchorMax = new Vector2(0f, 1f);

                        slotRT.pivot = new Vector2(0f, 1f);

                        slotRT.sizeDelta = new Vector2(45f, 45f);

                        float slotX = 16f + (i % 7) * 48.5f;

                        float slotY = -330f - (i / 7) * 49.5f;

                        slotRT.anchoredPosition = new Vector2(slotX, slotY);

                    }

                }

                // Position and style count texts to bottom-right of slot

                var cnt = root.Find($"s_count_{i}");

                if (cnt != null)

                {

                    var txt = cnt.GetComponent<UnityEngine.UI.Text>();

                    if (txt != null)

                    {

                        txt.font = GetSafeFont(10);

                        txt.fontStyle = FontStyle.Bold;

                    }

                    var cntRT = cnt.GetComponent<RectTransform>();

                    if (cntRT != null)

                    {

                        cntRT.anchorMin = new Vector2(0f, 1f);

                        cntRT.anchorMax = new Vector2(0f, 1f);

                        cntRT.pivot = new Vector2(1f, 0f); // Bottom-right pivot

                        cntRT.sizeDelta = new Vector2(40f, 15f);

                        float slotX = 16f + (i % 7) * 48.5f;

                        float slotY = -330f - (i / 7) * 49.5f;

                        cntRT.anchoredPosition = new Vector2(slotX + 45f, slotY - 45f);

                    }

                }

            }

            // 4. Style buttons (btn_ok, btn_cancel, btn_conversation, btn_close)

            Color greenBg = new Color(0.12f, 0.28f, 0.12f, 0.95f);

            Color greenBorder = new Color(0.25f, 0.55f, 0.25f, 0.95f);

            Color redBg = new Color(0.45f, 0.05f, 0.08f, 0.95f);

            Color redBorder = new Color(0.75f, 0.15f, 0.15f, 0.95f);

            Color greyBg = new Color(0.20f, 0.18f, 0.16f, 0.95f);

            Color greyBorder = new Color(0.40f, 0.36f, 0.32f, 0.95f);

            StyleUpgradeButton(root, "btn_ok", "ui_String_E4049600", greenBg, greenBorder, Color.white, "UPGRADE", 104, 26, new Vector2(-112, -248)); // Shifted up by 20px

            StyleUpgradeButton(root, "btn_cancel", "ui_String_4BFD55E0", redBg, redBorder, Color.white, "CANCEL", 104, 26, new Vector2(0, -248)); // Shifted up by 20px

            StyleUpgradeButton(root, "btn_conversation", "ui_String_EFA7D40C", greyBg, greyBorder, Color.white, "PREVIEW", 104, 26, new Vector2(112, -248)); // Shifted up by 20px

            // Style close button (red square with X)

            var btnClose = root.Find("btn_close");

            if (btnClose != null)

            {

                var rtClose = btnClose.GetComponent<RectTransform>();

                rtClose.anchoredPosition = new Vector2(338, -8);

                rtClose.sizeDelta = new Vector2(22, 22);

                Texture2D closeTex = new Texture2D(22, 22, TextureFormat.RGBA32, false);

                Color redCol = new Color(0.45f, 0.05f, 0.08f, 0.85f);

                Color closeBorder = new Color(0.65f, 0.15f, 0.15f, 0.90f);

                for (int y = 0; y < 22; y++)

                {

                    for (int x = 0; x < 22; x++)

                    {

                        if (x < 1 || x >= 22 - 1 || y < 1 || y >= 22 - 1)

                            closeTex.SetPixel(x, y, closeBorder);

                        else

                            closeTex.SetPixel(x, y, redCol);

                    }

                }

                closeTex.Apply();

                var rawClose = btnClose.GetComponent<UnityEngine.UI.RawImage>();

                if (rawClose != null)

                {

                    rawClose.texture = closeTex;

                    rawClose.color = Color.white;

                }

                else

                {

                    var imgClose = btnClose.GetComponent<UnityEngine.UI.Image>();

                    if (imgClose == null) imgClose = btnClose.gameObject.AddComponent<UnityEngine.UI.Image>();

                    imgClose.sprite = Sprite.Create(closeTex, new Rect(0, 0, 22, 22), new Vector2(0.5f, 0.5f));

                    imgClose.color = Color.white;

                }

                // Add "X" label inside close button

                var xGo = new GameObject("XLabel", typeof(RectTransform));

                xGo.transform.SetParent(btnClose, false);

                var xRt = xGo.GetComponent<RectTransform>();

                xRt.anchorMin = Vector2.zero;

                xRt.anchorMax = Vector2.one;

                xRt.sizeDelta = Vector2.zero;

                var xTxt = xGo.AddComponent<UnityEngine.UI.Text>();

                xTxt.text = "X";

                xTxt.alignment = TextAnchor.MiddleCenter;

                xTxt.color = Color.white;

                xTxt.fontSize = 11;

                xTxt.fontStyle = FontStyle.Bold;

                xTxt.font = GetSafeFont(11);

            }

            // Style text_gold and align with grid slot 6

            var goldTxt = root.Find("text_gold") ?? KOUIRenderer.FindChildByID(root, "text_gold");

            if (goldTxt != null)

            {

                var txt = goldTxt.GetComponent<UnityEngine.UI.Text>();

                if (txt != null)

                {

                    txt.font = GetSafeFont(12);

                    txt.fontStyle = FontStyle.Bold;

                    txt.color = new Color(0.92f, 0.80f, 0.52f, 1f);

                    txt.alignment = TextAnchor.MiddleCenter;

                }

                // Align with slot 6 (top-right slot in the inventory area, which is at x = 307, y = -330)

                float slotX = 307f;

                float slotY = -330f;

                float capsuleX = slotX + 45f; // align right edge to slot 6's right edge

                float capsuleY = slotY + 20f; // position above slot 6

                // Add gold capsule background (modern bronze capsule frame)

                var capsuleObj = root.Find("GoldCapsule")?.gameObject;

                if (capsuleObj == null)

                {

                    capsuleObj = new GameObject("GoldCapsule", typeof(RectTransform));

                    capsuleObj.transform.SetParent(root, false);

                }

                capsuleObj.transform.SetSiblingIndex(goldTxt.GetSiblingIndex()); // draw behind text

                var capsuleImg = capsuleObj.GetComponent<UnityEngine.UI.Image>() ?? capsuleObj.AddComponent<UnityEngine.UI.Image>();

                capsuleImg.sprite = GetSkillThemeRoundedRectSprite("upgrade_gold_capsule_130", 130, 22, 4,

                    new Color(0.08f, 0.08f, 0.08f, 0.6f),

                    new Color(0.45f, 0.35f, 0.15f, 0.8f),

                    1);

                capsuleImg.color = Color.white;

                capsuleImg.raycastTarget = false;

                var capsuleRT = capsuleObj.GetComponent<RectTransform>();

                if (capsuleRT != null)

                {

                    capsuleRT.anchorMin = new Vector2(0f, 1f);

                    capsuleRT.anchorMax = new Vector2(0f, 1f);

                    capsuleRT.pivot = new Vector2(1f, 0.5f); // Right-middle pivot

                    capsuleRT.sizeDelta = new Vector2(130f, 22f);

                    capsuleRT.anchoredPosition = new Vector2(capsuleX, capsuleY);

                }

                // Add coin icon inside the capsule using RawImage to copy original sprite

                var iconObj = capsuleObj.transform.Find("GoldIcon")?.gameObject;

                if (iconObj == null)

                {

                    iconObj = new GameObject("GoldIcon", typeof(RectTransform));

                    iconObj.transform.SetParent(capsuleObj.transform, false);

                }

                var iconImg = iconObj.GetComponent<UnityEngine.UI.RawImage>() ?? iconObj.AddComponent<UnityEngine.UI.RawImage>();

                ConfigureGoldIcon(iconImg);

                iconImg.raycastTarget = false;

                var iconRT = iconObj.GetComponent<RectTransform>();

                if (iconRT != null)

                {

                    iconRT.anchorMin = new Vector2(0f, 0.5f);

                    iconRT.anchorMax = new Vector2(0f, 0.5f);

                    iconRT.pivot = new Vector2(0f, 0.5f);

                    iconRT.sizeDelta = new Vector2(14f, 14f);

                    iconRT.anchoredPosition = new Vector2(8f, 0f); // 8px left margin

                }

                // Reposition and parent the actual gold text inside the capsule for perfect vertical/horizontal centering

                goldTxt.SetParent(capsuleObj.transform, false);

                var textRT = goldTxt.GetComponent<RectTransform>();

                if (textRT != null)

                {

                    textRT.anchorMin = Vector2.zero;

                    textRT.anchorMax = Vector2.one;

                    textRT.pivot = new Vector2(0.5f, 0.5f);

                    textRT.offsetMin = new Vector2(24f, 0f); // leave space for icon on left

                    textRT.offsetMax = new Vector2(-8f, 0f);  // right padding

                    textRT.anchoredPosition = Vector2.zero;

                }

            }

        }

        private void StyleUpgradeButton(Transform root, string btnName, string textName, Color normalColor, Color borderColor, Color textColor, string buttonText, float w, float h, Vector2 pos)

        {

            var btnTrans = root.Find(btnName);

            if (btnTrans == null) return;

            // Find text object (since it gets reparented, check under btnTrans, root, or search recursively)

            var txtTrans = btnTrans.Find(textName) ?? root.Find(textName) ?? KOUIRenderer.FindChildByID(btnTrans, textName) ?? KOUIRenderer.FindChildByID(root, textName);

            var rtBtn = btnTrans.GetComponent<RectTransform>();

            if (rtBtn != null)

            {

                rtBtn.anchorMin = new Vector2(0.5f, 1f);

                rtBtn.anchorMax = new Vector2(0.5f, 1f);

                rtBtn.pivot = new Vector2(0.5f, 1f);

                rtBtn.sizeDelta = new Vector2(w, h);

                rtBtn.anchoredPosition = pos;

            }

            // Remove RawImage if exists to prevent DisallowMultipleComponent conflicts

            var raw = btnTrans.GetComponent<RawImage>();

            if (raw != null) DestroyImmediate(raw);

            var img = btnTrans.GetComponent<Image>();

            if (img == null) img = btnTrans.gameObject.AddComponent<Image>();

            // Generate button background texture

            int width = Mathf.RoundToInt(w);

            int height = Mathf.RoundToInt(h);

            Texture2D btnTex = new Texture2D(width, height, TextureFormat.RGBA32, false);

            for (int y = 0; y < height; y++)

            {

                for (int x = 0; x < width; x++)

                {

                    if (x < 1 || x >= width - 1 || y < 1 || y >= height - 1)

                        btnTex.SetPixel(x, y, borderColor);

                    else

                        btnTex.SetPixel(x, y, normalColor);

                }

            }

            btnTex.Apply();

            img.sprite = Sprite.Create(btnTex, new Rect(0, 0, width, height), new Vector2(0.5f, 0.5f));

            img.color = Color.white;

            // Setup press transition visual feedback

            var btn = btnTrans.GetComponent<Button>();

            if (btn != null)

            {

                btn.transition = Selectable.Transition.ColorTint;

                btn.targetGraphic = img;

                var colors = btn.colors;

                colors.normalColor = Color.white;

                colors.highlightedColor = new Color(0.9f, 0.9f, 0.9f, 1f);

                colors.pressedColor = new Color(0.7f, 0.7f, 0.7f, 1f);

                colors.selectedColor = new Color(0.9f, 0.9f, 0.9f, 1f);

                colors.disabledColor = new Color(0.5f, 0.5f, 0.5f, 0.5f);

                btn.colors = colors;

            }

            if (txtTrans != null)

            {

                txtTrans.SetParent(btnTrans, false);

                txtTrans.localScale = Vector3.one;

                // Clean shadows/outlines to match accessory upgrade button style

                var shadow = txtTrans.GetComponent<UnityEngine.UI.Shadow>();

                if (shadow != null) DestroyImmediate(shadow);

                var outline = txtTrans.GetComponent<UnityEngine.UI.Outline>();

                if (outline != null) DestroyImmediate(outline);

                var rtTxt = txtTrans.GetComponent<RectTransform>();

                if (rtTxt != null)

                {

                    rtTxt.anchorMin = Vector2.zero;

                    rtTxt.anchorMax = Vector2.one;

                    rtTxt.pivot = new Vector2(0.5f, 0.5f);

                    rtTxt.sizeDelta = Vector2.zero;

                    rtTxt.anchoredPosition = Vector2.zero;

                }

                var textComp = txtTrans.GetComponent<UnityEngine.UI.Text>();

                if (textComp != null)

                {

                    textComp.text = buttonText;

                    textComp.alignment = TextAnchor.MiddleCenter;

                    textComp.color = textColor;

                    textComp.font = GetSafeFont(11);

                    textComp.fontStyle = FontStyle.Bold;

                }

            }

        }

        /// <summary>

        /// Ring (Accessory) Upgrade panelini göster/gizle.

        /// </summary>

        public void ShowRingUpgrade(bool show, int npcId = 0)

        {

            if (_uiRingUpgrade == null) return;

            if (show)

            {

                OnPanelOpened(_uiRingUpgrade);

                _uiRingUpgrade.SetActive(true);

                _uiRingUpgrade.transform.SetAsLastSibling();

                SetPanelPosRightCenter(_uiRingUpgrade);

                var mgr = _uiRingUpgrade.GetComponent<KOAccessoryUpgradeManager>();

                if (mgr == null)

                {

                    mgr = _uiRingUpgrade.AddComponent<KOAccessoryUpgradeManager>();

                }

                mgr.Initialize(_uiRingUpgrade.transform, npcId);

                ReorderUpgradeLayers(_uiRingUpgrade.transform);

            }

            else

            {

                _uiRingUpgrade.SetActive(false);

                var mgr = KOAccessoryUpgradeManager.Instance;

                if (mgr != null)

                {

                    mgr.ResetSlots();

                }

            }

            RepositionSkillBarForPanel();

        }

        /// <summary>

        /// Upgrade paneli text/buton referanslarını bağlar.

        /// C++ referans: UIItemUpgrade.cpp Load() satır 618-625, ReceiveMessage() satır 465-478

        /// </summary>

        private void BindUpgradeElements(Transform root, bool isFast)

        {

            // Hide success/fail flipflop animation images (19 frames each) and shift them up by 20px

            bool alreadyInitialized = _initializedRootsForUpgrade.Contains(root);

            if (!alreadyInitialized)

            {

                _initializedRootsForUpgrade.Add(root);

            }

            for (int i = 0; i < 19; i++)

            {

                var imgSuccess = KOUIRenderer.FindChildByID(root, $"img_s_load_{i}");

                if (imgSuccess != null)

                {

                    imgSuccess.gameObject.SetActive(false);

                    if (!alreadyInitialized)

                    {

                        var rt = imgSuccess.GetComponent<RectTransform>();

                        if (rt != null) rt.anchoredPosition = new Vector2(rt.anchoredPosition.x, rt.anchoredPosition.y + 20f);

                    }

                }

                var imgFail = KOUIRenderer.FindChildByID(root, $"img_f_load_{i}");

                if (imgFail != null)

                {

                    imgFail.gameObject.SetActive(false);

                    if (!alreadyInitialized)

                    {

                        var rt = imgFail.GetComponent<RectTransform>();

                        if (rt != null) rt.anchoredPosition = new Vector2(rt.anchoredPosition.x, rt.anchoredPosition.y + 20f);

                    }

                }

            }

            var imgCover1 = KOUIRenderer.FindChildByID(root, "img_cover_01");

            var imgCover2 = KOUIRenderer.FindChildByID(root, "img_cover_02");

            if (imgCover1 != null && imgCover2 != null)

            {

                var rt1 = imgCover1.GetComponent<RectTransform>();

                var rt2 = imgCover2.GetComponent<RectTransform>();

                var rawImg1 = imgCover1.GetComponent<UnityEngine.UI.RawImage>();

                var rawImg2 = imgCover2.GetComponent<UnityEngine.UI.RawImage>();

                if (rt1 != null && rt2 != null && rawImg1 != null && rawImg2 != null)

                {

                    // Ensure anchors/pivots are top-left (0, 1)

                    rt1.anchorMin = new Vector2(0, 1);

                    rt1.anchorMax = new Vector2(0, 1);

                    rt1.pivot = new Vector2(0, 1);

                    rt2.anchorMin = new Vector2(0, 1);

                    rt2.anchorMax = new Vector2(0, 1);

                    rt2.pivot = new Vector2(0, 1);

                    // Set sizes and positions to perfectly align with 325x176 ModernTopSlotsBg at (22, -50)

                    rt1.sizeDelta = new Vector2(325f, 88f);

                    rt1.anchoredPosition = new Vector2(22f, -50f);

                    rt2.sizeDelta = new Vector2(325f, 88f);

                    rt2.anchoredPosition = new Vector2(22f, -138f);

                    _cover1OrigPos = rt1.anchoredPosition;

                    _cover1Height = 88f;

                    _cover1OrigUV = rawImg1.uvRect;

                    _cover2OrigPos = rt2.anchoredPosition;

                    _cover2Height = 88f;

                    _cover2OrigUV = rawImg2.uvRect;

                    _coversCached = true;

                }

            }

            if (imgCover1 != null) imgCover1.gameObject.SetActive(false);

            if (imgCover2 != null) imgCover2.gameObject.SetActive(false);

            if (root == (_uiRingUpgrade != null ? _uiRingUpgrade.transform : null))

            {

                ReorderUpgradeLayers(root);

                return;

            }

            // Reorder hierarchy layers will be performed after modernization

            // C++ UIItemUpgrade.cpp satır 618: m_pBtnClose = GetChildByID<CN3UIButton>("btn_close")

            var btnClose = KOUIRenderer.FindChildButton(root, "btn_close");

            if (btnClose != null)

            {

                // C++ UIItemUpgrade.cpp satır 337-341: Close()

                btnClose.onClick.RemoveAllListeners();

                btnClose.onClick.AddListener(() => { if (isFast) ShowFastUpgrade(false); else ShowItemUpgrade(false); });

            }

            // C++ UIItemUpgrade.cpp satır 620: m_pBtnCancel = GetChildByID<CN3UIButton>("btn_cancel")

            var btnCancel = KOUIRenderer.FindChildButton(root, "btn_cancel");

            if (btnCancel != null)

            {

                btnCancel.onClick.RemoveAllListeners();

                btnCancel.onClick.AddListener(() =>

                {

                    // C++ ReceiveMessage satır 471-472: if (!m_bUpgradeInProgress) ResetUpgradeInventory()

                    var mgr = isFast ? (IKOUpgradeManager)KOFastUpgradeManager.Instance : (IKOUpgradeManager)KOItemUpgradeManager.Instance;

                    if (mgr != null && !mgr.IsUpgradeInProgress)

                    {

                        mgr.ResetUpgradeInventory();

                        RefreshUpgradeSlots();

                        PopulateUpgradeInventory();

                    }

                });

            }

            // C++ UIItemUpgrade.cpp satır 619: m_pBtnOk = GetChildByID<CN3UIButton>("btn_ok")

            var btnOk = KOUIRenderer.FindChildButton(root, "btn_ok");

            if (btnOk != null)

            {

                btnOk.onClick.RemoveAllListeners();

                btnOk.onClick.AddListener(() =>

                {

                    var mgr = isFast ? (IKOUpgradeManager)KOFastUpgradeManager.Instance : (IKOUpgradeManager)KOItemUpgradeManager.Instance;

                    if (mgr == null || mgr.IsUpgradeInProgress) return;

                    if (KOMessageBox.Instance != null)

                    {

                        KOMessageBox.Instance.ShowYesNo(

                            "Do you Want this Item Upgrade?\nYou may lose your belongings\ncompletely.", 

                            "Item Upgrade", 

                            MsgBoxBehavior.BEHAVIOR_NOTHING,

                            onYes: () => {

                                if (mgr != null && !mgr.IsUpgradeInProgress)

                                    mgr.SendToServerUpgradeMsg();

                            },

                            onNo: null,

                            callerPanel: isFast ? _uiFastUpgrade : _uiItemUpgrade

                        );

                    }

                    else

                    {

                        mgr.SendToServerUpgradeMsg();

                    }

                });

            }

            var btnPreview = KOUIRenderer.FindChildButton(root, "btn_conversation");

            if (btnPreview != null)

            {

                btnPreview.onClick.RemoveAllListeners();

                btnPreview.onClick.AddListener(() =>

                {

                    OnPreviewButtonClicked();

                });

            }

            // C++ UIItemUpgrade.cpp satır 625: m_pStrMyGold = GetChildByID<CN3UIString>("text_gold")

            var textGold = KOUIRenderer.FindChildText(root, "text_gold");

            if (textGold != null)

            {

                textGold.text = "0";

            }

            // ====================================================================

            // Faz 4: Drop target binding — C++ UIItemUpgrade.cpp Load() satır 621-654

            // ====================================================================

            // C++ satır 621: m_pAreaUpgrade = GetChildByID<CN3UIArea>("a_upgrade")

            var aUpgrade = KOUIRenderer.FindChildByID(root, "a_upgrade");

            if (aUpgrade != null)

            {

                // Image component yoksa ekle (raycast için gerekli)

                var img = aUpgrade.gameObject.GetComponent<Image>();

                if (img == null)

                {

                    img = aUpgrade.gameObject.AddComponent<Image>();

                    img.color = Color.clear;

                }

                img.raycastTarget = true;

                // Drop target ekle — sürükle-bırak ile upgrade slot'a item yerleştirme

                var dropTarget = aUpgrade.gameObject.GetComponent<KOUpgradeDropTarget>();

                if (dropTarget == null)

                    dropTarget = aUpgrade.gameObject.AddComponent<KOUpgradeDropTarget>();

                dropTarget.targetType = KOUpgradeDropTarget.TargetType.UpgradeSlot;

                dropTarget.slotIndex = 0;

                // CanvasGroup gerekli (raycast engellemesi için)

                if (aUpgrade.gameObject.GetComponent<CanvasGroup>() == null)

                    aUpgrade.gameObject.AddComponent<CanvasGroup>();

            }

            // C++ satır 638-642: m_pSlotArea[i] = GetChildByID<CN3UIArea>(fmt::format("a_m_{}", i))

            for (int i = 0; i < KOItemUpgradeManager.ANVIL_REQ_MAX; i++)

            {

                var slotArea = KOUIRenderer.FindChildByID(root, $"a_m_{i}");

                if (slotArea != null)

                {

                    // Image component yoksa ekle (raycast için gerekli)

                    var img = slotArea.gameObject.GetComponent<Image>();

                    if (img == null)

                    {

                        img = slotArea.gameObject.AddComponent<Image>();

                        img.color = Color.clear;

                    }

                    img.raycastTarget = true;

                    var dropTarget = slotArea.gameObject.GetComponent<KOUpgradeDropTarget>();

                    if (dropTarget == null)

                        dropTarget = slotArea.gameObject.AddComponent<KOUpgradeDropTarget>();

                    dropTarget.targetType = KOUpgradeDropTarget.TargetType.RequirementSlot;

                    dropTarget.slotIndex = i;

                    if (slotArea.gameObject.GetComponent<CanvasGroup>() == null)

                        slotArea.gameObject.AddComponent<CanvasGroup>();

                }

            }

            ModernizeItemUpgradePanel(root, alreadyInitialized);

            if (isFast)

            {

                // Hide standard areas

                var fastAUpgrade = KOUIRenderer.FindChildByID(root, "a_upgrade");

                if (fastAUpgrade != null) fastAUpgrade.gameObject.SetActive(false);

                var aResult = KOUIRenderer.FindChildByID(root, "a_result");

                if (aResult != null) aResult.gameObject.SetActive(false);

                for (int i = 0; i < 9; i++)

                {

                    var aM = KOUIRenderer.FindChildByID(root, $"a_m_{i}");

                    if (aM != null) aM.gameObject.SetActive(false);

                }

                var imgUpgrade = KOUIRenderer.FindChildByID(root, "img_upgrade");

                if (imgUpgrade != null) imgUpgrade.gameObject.SetActive(false);

                var imgResult = KOUIRenderer.FindChildByID(root, "img_result");

                if (imgResult != null) imgResult.gameObject.SetActive(false);

                var fastBtnPreview = KOUIRenderer.FindChildButton(root, "btn_conversation");

                if (fastBtnPreview != null) fastBtnPreview.gameObject.SetActive(false);

                // Find and rename OK/Cancel texts under root

                foreach (var txt in root.GetComponentsInChildren<UnityEngine.UI.Text>(true))

                {

                    if (txt.text == "O K" || txt.text == "OK")

                    {

                        txt.text = "UPGRADE";

                    }

                    else if (txt.text == "Cancel")

                    {

                        txt.text = "CANCEL";

                    }

                }

                // Create 18 slots dynamically if not already created

                var slotsParent = root.Find("FastUpgradeSlotsParent");

                if (slotsParent == null)

                {

                    GameObject parentGo = new GameObject("FastUpgradeSlotsParent", typeof(RectTransform));

                    parentGo.transform.SetParent(root, false);

                    var parentRt = parentGo.GetComponent<RectTransform>();

                    parentRt.anchorMin = new Vector2(0, 1);

                    parentRt.anchorMax = new Vector2(0, 1);

                    parentRt.pivot = new Vector2(0, 1);

                    parentRt.sizeDelta = new Vector2(325f, 176f);

                    parentRt.anchoredPosition = new Vector2(22f, -50f);

                    slotsParent = parentGo.transform;

                    int index = 0;

                    for (int r = 0; r < 3; r++)

                    {

                        for (int c = 0; c < 6; c++)

                        {

                            GameObject slotGo = new GameObject($"a_fast_slot_{index}", typeof(RectTransform));

                            slotGo.transform.SetParent(slotsParent, false);

                            var slotRt = slotGo.GetComponent<RectTransform>();

                            slotRt.anchorMin = new Vector2(0, 1);

                            slotRt.anchorMax = new Vector2(0, 1);

                            slotRt.pivot = new Vector2(0, 1);

                            slotRt.sizeDelta = new Vector2(42f, 42f);

                            slotRt.anchoredPosition = new Vector2(16f + c * 50f, -17f - r * 50f);

                            Sprite slotSprite = GetSkillThemeGlassSlotSprite("slot_socket_glass_v5", 45);

                            var slotImg = slotGo.AddComponent<Image>();

                            slotImg.sprite = slotSprite;

                            slotImg.color = Color.white;

                            slotImg.raycastTarget = true;

                            var dropTarget = slotGo.AddComponent<KOUpgradeDropTarget>();

                            dropTarget.targetType = KOUpgradeDropTarget.TargetType.UpgradeSlot;

                            dropTarget.slotIndex = index;

                            slotGo.AddComponent<CanvasGroup>();

                            index++;

                        }

                    }

                }

            }

            ReorderUpgradeLayers(root);

        }

        /// <summary>

        /// Reorders the upgrade panel's children hierarchy to match Open-KO C++ depth layers.

        /// This achieves the classic "castle gate" cover sliding animation where covers slide

        /// behind the window frames and title bar without using any fake clipping masks.

        /// </summary>

        private void ReorderUpgradeLayers(Transform root)

        {

            if (root == null) return;

            var slotsBgList = new List<Transform>();

            var animFramesList = new List<Transform>();

            var slotsList = new List<Transform>();

            var coversList = new List<Transform>();

            var bordersBgList = new List<Transform>();

            var invSlotsList = new List<Transform>();

            var buttonsTextsList = new List<Transform>();

            var othersList = new List<Transform>();

            for (int i = 0; i < root.childCount; i++)

            {

                Transform child = root.GetChild(i);

                string name = child.name;

                if (name == "img_cover_01" || name == "img_cover_02")

                {

                    coversList.Add(child);

                }

                else if (name == "ModernTopSlotsBg" || name == "UpgradeRateContainer" || name == "NeedCoinsContainer")

                {

                    slotsBgList.Add(child);

                }

                else if (name == "img_inven01")

                {

                    bordersBgList.Add(child);

                }

                else if (name.StartsWith("img_s_load_") || name.StartsWith("img_f_load_"))

                {

                    animFramesList.Add(child);

                }

                else if (name.StartsWith("a_m_") || name == "a_upgrade" || name == "a_result" || name == "a_upgrade_0" || name == "a_upgrade_1" || name == "a_upgrade_2")

                {

                    slotsList.Add(child);

                }

                else if (name.StartsWith("a_slot_") || name.StartsWith("s_count_"))

                {

                    invSlotsList.Add(child);

                }

                else if (name.StartsWith("btn_") || name == "text_gold")

                {

                    buttonsTextsList.Add(child);

                }

                else

                {

                    var rawImg = child.GetComponent<UnityEngine.UI.RawImage>();

                    var unityImg = child.GetComponent<UnityEngine.UI.Image>();

                    var text = child.GetComponent<UnityEngine.UI.Text>();

                    if (rawImg != null)

                    {

                        var rt = child.GetComponent<RectTransform>();

                        float h = rt != null ? rt.rect.height : 0;

                        string texName = rawImg.texture != null ? rawImg.texture.name : "";

                        if (texName.Contains("ui_upgrade") || (h > 200 && h < 300))

                        {

                            slotsBgList.Add(child);

                        }

                        else

                        {

                            bordersBgList.Add(child);

                        }

                    }

                    else if (text != null)

                    {

                        buttonsTextsList.Add(child);

                    }

                    else if (unityImg != null)

                    {

                        bordersBgList.Add(child);

                    }

                    else

                    {

                        othersList.Add(child);

                    }

                }

            }

            int index = 0;

            foreach (var t in slotsBgList) t.SetSiblingIndex(index++);

            foreach (var t in slotsList) t.SetSiblingIndex(index++);

            foreach (var t in coversList) t.SetSiblingIndex(index++);

            foreach (var t in animFramesList) t.SetSiblingIndex(index++);

            foreach (var t in bordersBgList) t.SetSiblingIndex(index++);

            foreach (var t in invSlotsList) t.SetSiblingIndex(index++);

            foreach (var t in buttonsTextsList) t.SetSiblingIndex(index++);

            foreach (var t in othersList) t.SetSiblingIndex(index++);

        }

        /// <summary>

        /// Upgrade sonuç göstergesi.

        /// C++ referans: UIItemUpgrade.cpp MsgRecv_ItemUpgrade()

        /// C++ animasyon (FlipFlop) kullanır — mobilde sadece log.

        /// </summary>

        public void HandleUpgradeResult(bool success, short newLevel)

        {

            if (_uiItemUpgrade == null || !_uiItemUpgrade.activeSelf) return;

            // Sonuç sonrası slotları güncelle — başarı/başarısız farketmeksizin

            RefreshUpgradeSlots();

        }

        private void ResetCovers()

        {

            if (_uiItemUpgrade != null) ResetCoversForRoot(_uiItemUpgrade.transform);

            if (_uiRingUpgrade != null) ResetCoversForRoot(_uiRingUpgrade.transform);

            if (_uiFastUpgrade != null) ResetCoversForRoot(_uiFastUpgrade.transform);

            // Herhangi bir yarım kalmış animasyon karesini sıfır aramayla anında gizle

            if (_activeAnimFrame != null)

            {

                _activeAnimFrame.SetActive(false);

                _activeAnimFrame = null;

            }

        }

