        /// <summary>

        /// Open-KO 1:1: Play upgrade success/fail FlipFlop and Cover animation sequence.

        /// </summary>

        public void PlayUpgradeAnimation(bool success)

        {

            if ((_uiItemUpgrade == null || !_uiItemUpgrade.activeSelf) && (_uiRingUpgrade == null || !_uiRingUpgrade.activeSelf) && (_uiFastUpgrade == null || !_uiFastUpgrade.activeSelf))

            {

                var mgr = KOItemUpgradeManager.Instance;

                if (mgr != null) mgr.IsUpgradeInProgress = false;

                var fastMgr = KOFastUpgradeManager.Instance;

                if (fastMgr != null) fastMgr.IsUpgradeInProgress = false;

                var ringMgr = KOAccessoryUpgradeManager.Instance;

                if (ringMgr != null) ringMgr.IsUpgradeInProgress = false;

                return;

            }

            if (_upgradeAnimationCoroutine != null)

            {

                StopCoroutine(_upgradeAnimationCoroutine);

            }

            _upgradeAnimationCoroutine = StartCoroutine(PlayUpgradeAnimationCor(success));

        }

        private void ConvertToFixedTopLeft(RectTransform childRT, RectTransform parentRT)

        {

            if (childRT == null || parentRT == null) return;

            if (childRT.anchorMin == new Vector2(0, 1) && childRT.anchorMax == new Vector2(0, 1) && childRT.pivot == new Vector2(0, 1))

                return;

            float parentW = parentRT.rect.width;

            float parentH = parentRT.rect.height;

            float left = parentW * childRT.anchorMin.x + childRT.offsetMin.x;

            float right = parentW * childRT.anchorMax.x + childRT.offsetMax.x;

            float bottom = parentH * childRT.anchorMin.y + childRT.offsetMin.y;

            float top = parentH * childRT.anchorMax.y + childRT.offsetMax.y;

            float width = right - left;

            float height = top - bottom;

            childRT.anchorMin = new Vector2(0, 1);

            childRT.anchorMax = new Vector2(0, 1);

            childRT.pivot = new Vector2(0, 1);

            childRT.sizeDelta = new Vector2(width, height);

            childRT.anchoredPosition = new Vector2(left, -parentH + top);

        }

        private System.Collections.IEnumerator PlayUpgradeAnimationCor(bool success)

        {

            Transform root = null;

            if (_uiRingUpgrade != null && _uiRingUpgrade.activeSelf)

                root = _uiRingUpgrade.transform;

            else if (_uiFastUpgrade != null && _uiFastUpgrade.activeSelf)

                root = _uiFastUpgrade.transform;

            else

                root = _uiItemUpgrade.transform;

            if (!_coversCached || _cachedCoversRoot != root)

            {

                bool isFast = (root == (_uiFastUpgrade != null ? _uiFastUpgrade.transform : null));

                BindUpgradeElements(root, isFast);

                _cachedCoversRoot = root;

            }

            var imgCover1 = KOUIRenderer.FindChildByID(root, "img_cover_01");

            var imgCover2 = KOUIRenderer.FindChildByID(root, "img_cover_02");

            try

            {

                // Reset to closed state initially

                ResetCovers();

                // Initialize covers to open state (height = 0) before showing them, to ensure smooth closing start

                if (imgCover1 != null && _coversCached)

                {

                    var rt1 = imgCover1.GetComponent<RectTransform>();

                    if (rt1 != null) rt1.sizeDelta = new Vector2(rt1.sizeDelta.x, 0);

                }

                if (imgCover2 != null && _coversCached)

                {

                    var rt2 = imgCover2.GetComponent<RectTransform>();

                    if (rt2 != null) rt2.sizeDelta = new Vector2(rt2.sizeDelta.x, 0);

                }

                // Sliding closed phase (0.4s)

                float closeDuration = 0.4f;

                float elapsedClose = 0.0f;

                if (imgCover1 != null)

                {

                    imgCover1.gameObject.SetActive(true);

                    imgCover1.transform.SetAsLastSibling();

                }

                if (imgCover2 != null)

                {

                    imgCover2.gameObject.SetActive(true);

                    imgCover2.transform.SetAsLastSibling();

                }

                while (elapsedClose < closeDuration)

                {

                    float t = Mathf.Min(elapsedClose / closeDuration, 1.0f);

                    float ease = t * t; // ease-in quadratic

                    if (imgCover1 != null)

                    {

                        var rt1 = imgCover1.GetComponent<RectTransform>();

                        var rawImg1 = imgCover1.GetComponent<UnityEngine.UI.RawImage>();

                        if (rt1 != null && rawImg1 != null && _coversCached)

                        {

                            float hCurrent = _cover1Height * ease;

                            rt1.sizeDelta = new Vector2(rt1.sizeDelta.x, hCurrent);

                            rt1.anchoredPosition = _cover1OrigPos;

                            Rect uv = _cover1OrigUV;

                            uv.height = _cover1OrigUV.height * ease;

                            rawImg1.uvRect = uv;

                        }

                    }

                    if (imgCover2 != null)

                    {

                        var rt2 = imgCover2.GetComponent<RectTransform>();

                        var rawImg2 = imgCover2.GetComponent<UnityEngine.UI.RawImage>();

                        if (rt2 != null && rawImg2 != null && _coversCached)

                        {

                            float hCurrent = _cover2Height * ease;

                            rt2.sizeDelta = new Vector2(rt2.sizeDelta.x, hCurrent);

                            rt2.anchoredPosition = new Vector2(_cover2OrigPos.x, _cover2OrigPos.y - _cover2Height + hCurrent);

                            Rect uv = _cover2OrigUV;

                            uv.y = _cover2OrigUV.y + _cover2OrigUV.height * (1.0f - ease);

                            uv.height = _cover2OrigUV.height * ease;

                            rawImg2.uvRect = uv;

                        }

                    }

                    yield return null;

                    elapsedClose += Time.deltaTime;

                }

                // Ensure fully closed

                if (imgCover1 != null && _coversCached)

                {

                    var rt1 = imgCover1.GetComponent<RectTransform>();

                    var rawImg1 = imgCover1.GetComponent<UnityEngine.UI.RawImage>();

                    if (rt1 != null && rawImg1 != null)

                    {

                        rt1.sizeDelta = new Vector2(rt1.sizeDelta.x, _cover1Height);

                        rt1.anchoredPosition = _cover1OrigPos;

                        rawImg1.uvRect = _cover1OrigUV;

                    }

                }

                if (imgCover2 != null && _coversCached)

                {

                    var rt2 = imgCover2.GetComponent<RectTransform>();

                    var rawImg2 = imgCover2.GetComponent<UnityEngine.UI.RawImage>();

                    if (rt2 != null && rawImg2 != null)

                    {

                        rt2.sizeDelta = new Vector2(rt2.sizeDelta.x, _cover2Height);

                        rt2.anchoredPosition = _cover2OrigPos;

                        rawImg2.uvRect = _cover2OrigUV;

                    }

                }

                // FlipFlop Animation: 19 frames (0..18), 0.1s frame delay

                for (int i = 0; i < 19; i++)

                {

                    // Hide previous frame

                    if (_activeAnimFrame != null)

                    {

                        _activeAnimFrame.SetActive(false);

                        _activeAnimFrame = null;

                    }

                    // Show current frame

                    var curFrameName = success ? $"img_s_load_{i}" : $"img_f_load_{i}";

                    var curFrame = KOUIRenderer.FindChildByID(root, curFrameName);

                    if (curFrame != null)

                    {

                        var rt = curFrame.GetComponent<RectTransform>();

                        if (rt != null) rt.anchoredPosition = new Vector2(rt.anchoredPosition.x, -105f);

                        _activeAnimFrame = curFrame.gameObject;

                        _activeAnimFrame.SetActive(true);

                        _activeAnimFrame.transform.SetAsLastSibling();

                    }

                    yield return new WaitForSeconds(0.1f);

                }

                // Hide last frame (frame 18)

                if (_activeAnimFrame != null)

                {

                    _activeAnimFrame.SetActive(false);

                    _activeAnimFrame = null;

                }

                // Apply deferred inventory updates for fast upgrade before covers open

                if (KOFastUpgradeManager.Instance != null && IsFastUpgradeUIOpen)

                {

                    KOFastUpgradeManager.Instance.ApplyDeferredInventoryUpdates();

                }

                // Refresh slot positions behind covers

                if (_uiRingUpgrade != null && _uiRingUpgrade.activeSelf && KOAccessoryUpgradeManager.Instance != null)

                {

                    KOAccessoryUpgradeManager.Instance.RefreshUpgradeSlots();

                }

                else

                {

                    RefreshUpgradeSlots();

                }

                // Cover Opening Animation: 0.8s duration, ease-out quadratic

                float coverAnimDuration = 0.8f;

                float elapsed = 0.0f;

                while (elapsed < coverAnimDuration)

                {

                    elapsed += Time.deltaTime;

                    float t = Mathf.Min(elapsed / coverAnimDuration, 1.0f);

                    float ease = 1.0f - ((1.0f - t) * (1.0f - t));

                    if (imgCover1 != null)

                    {

                        var rt1 = imgCover1.GetComponent<RectTransform>();

                        var rawImg1 = imgCover1.GetComponent<UnityEngine.UI.RawImage>();

                        if (rt1 != null && rawImg1 != null && _coversCached)

                        {

                            float hCurrent = _cover1Height * (1.0f - ease);

                            rt1.sizeDelta = new Vector2(rt1.sizeDelta.x, hCurrent);

                            rt1.anchoredPosition = _cover1OrigPos;

                            Rect uv = _cover1OrigUV;

                            uv.height = _cover1OrigUV.height * (1.0f - ease);

                            rawImg1.uvRect = uv;

                        }

                    }

                    if (imgCover2 != null)

                    {

                        var rt2 = imgCover2.GetComponent<RectTransform>();

                        var rawImg2 = imgCover2.GetComponent<UnityEngine.UI.RawImage>();

                        if (rt2 != null && rawImg2 != null && _coversCached)

                        {

                            float hCurrent = _cover2Height * (1.0f - ease);

                            rt2.sizeDelta = new Vector2(rt2.sizeDelta.x, hCurrent);

                            rt2.anchoredPosition = new Vector2(_cover2OrigPos.x, _cover2OrigPos.y - _cover2Height + hCurrent);

                            Rect uv = _cover2OrigUV;

                            uv.y = _cover2OrigUV.y + _cover2OrigUV.height * ease;

                            uv.height = _cover2OrigUV.height * (1.0f - ease);

                            rawImg2.uvRect = uv;

                        }

                    }

                    yield return null;

                }

            }

            finally

            {

                // Reset covers and restore original states

                ResetCovers();

                // Mark upgrade as no longer in progress

                var upgradeMgr = KOItemUpgradeManager.Instance;

                if (upgradeMgr != null)

                {

                    upgradeMgr.IsUpgradeInProgress = false;

                }

                var ringMgr = KOAccessoryUpgradeManager.Instance;

                if (ringMgr != null)

                {

                    ringMgr.IsUpgradeInProgress = false;

                }

                var fastMgr = KOFastUpgradeManager.Instance;

                if (fastMgr != null)

                {

                    fastMgr.IsUpgradeInProgress = false;

                }

                _upgradeAnimationCoroutine = null;

            }

        }

        private Coroutine _previewAnimationCoroutine = null;

        public void PlayPreviewAnimation(int previewId)

        {

            if ((_uiItemUpgrade == null || !_uiItemUpgrade.activeSelf) && (_uiRingUpgrade == null || !_uiRingUpgrade.activeSelf) && (_uiFastUpgrade == null || !_uiFastUpgrade.activeSelf))

            {

                var mgr = KOItemUpgradeManager.Instance;

                if (mgr != null) mgr.IsUpgradeInProgress = false;

                var fastMgr = KOFastUpgradeManager.Instance;

                if (fastMgr != null) fastMgr.IsUpgradeInProgress = false;

                var ringMgr = KOAccessoryUpgradeManager.Instance;

                if (ringMgr != null) ringMgr.IsUpgradeInProgress = false;

                return;

            }

            if (_upgradeAnimationCoroutine != null)

            {

                StopCoroutine(_upgradeAnimationCoroutine);

                _upgradeAnimationCoroutine = null;

            }

            if (_previewAnimationCoroutine != null)

            {

                StopCoroutine(_previewAnimationCoroutine);

            }

            if (_uiRingUpgrade != null && _uiRingUpgrade.activeSelf)

            {

                var ringMgr = KOAccessoryUpgradeManager.Instance;

                if (ringMgr != null) ringMgr.IsUpgradeInProgress = true;

            }

            else

            {

                var m = KOItemUpgradeManager.Instance;

                if (m != null) m.IsUpgradeInProgress = true;

            }

            _previewAnimationCoroutine = StartCoroutine(PlayPreviewAnimationCor(previewId));

        }

        private System.Collections.IEnumerator PlayPreviewAnimationCor(int previewId)

        {

            Transform root = null;

            bool isRingUpgrade = false;

            if (_uiRingUpgrade != null && _uiRingUpgrade.activeSelf)

            {

                root = _uiRingUpgrade.transform;

                isRingUpgrade = true;

            }

            else if (_uiFastUpgrade != null && _uiFastUpgrade.activeSelf)

            {

                root = _uiFastUpgrade.transform;

            }

            else if (_uiItemUpgrade != null)

            {

                root = _uiItemUpgrade.transform;

            }

            if (root == null) yield break;

            if (!_coversCached || _cachedCoversRoot != root)

            {

                bool isFast = (root == (_uiFastUpgrade != null ? _uiFastUpgrade.transform : null));

                BindUpgradeElements(root, isFast);

                _cachedCoversRoot = root;

            }

            var imgCover1 = KOUIRenderer.FindChildByID(root, "img_cover_01");

            var imgCover2 = KOUIRenderer.FindChildByID(root, "img_cover_02");

            try

            {

                // Reset to closed state initially

                ResetCovers();

                // Initialize covers to open state (height = 0) before showing them, to ensure smooth closing start

                if (imgCover1 != null && _coversCached)

                {

                    var rt1 = imgCover1.GetComponent<RectTransform>();

                    if (rt1 != null) rt1.sizeDelta = new Vector2(rt1.sizeDelta.x, 0);

                }

                if (imgCover2 != null && _coversCached)

                {

                    var rt2 = imgCover2.GetComponent<RectTransform>();

                    if (rt2 != null) rt2.sizeDelta = new Vector2(rt2.sizeDelta.x, 0);

                }

                // 1. Sliding closed phase (0.4s)

                float closeDuration = 0.4f;

                float elapsedClose = 0.0f;

                if (imgCover1 != null) imgCover1.gameObject.SetActive(true);

                if (imgCover2 != null) imgCover2.gameObject.SetActive(true);

                while (elapsedClose < closeDuration)

                {

                    float t = Mathf.Min(elapsedClose / closeDuration, 1.0f);

                    float ease = t * t; // ease-in quadratic

                    if (imgCover1 != null)

                    {

                        var rt1 = imgCover1.GetComponent<RectTransform>();

                        var rawImg1 = imgCover1.GetComponent<UnityEngine.UI.RawImage>();

                        if (rt1 != null && rawImg1 != null && _coversCached)

                        {

                            float hCurrent = _cover1Height * ease;

                            rt1.sizeDelta = new Vector2(rt1.sizeDelta.x, hCurrent);

                            rt1.anchoredPosition = _cover1OrigPos;

                            Rect uv = _cover1OrigUV;

                            uv.height = _cover1OrigUV.height * ease;

                            rawImg1.uvRect = uv;

                        }

                    }

                    if (imgCover2 != null)

                    {

                        var rt2 = imgCover2.GetComponent<RectTransform>();

                        var rawImg2 = imgCover2.GetComponent<UnityEngine.UI.RawImage>();

                        if (rt2 != null && rawImg2 != null && _coversCached)

                        {

                            float hCurrent = _cover2Height * ease;

                            rt2.sizeDelta = new Vector2(rt2.sizeDelta.x, hCurrent);

                            rt2.anchoredPosition = new Vector2(_cover2OrigPos.x, _cover2OrigPos.y - _cover2Height + hCurrent);

                            Rect uv = _cover2OrigUV;

                            uv.y = _cover2OrigUV.y + _cover2OrigUV.height * (1.0f - ease);

                            uv.height = _cover2OrigUV.height * ease;

                            rawImg2.uvRect = uv;

                        }

                    }

                    yield return null;

                    elapsedClose += Time.deltaTime;

                }

                // Ensure fully closed

                if (imgCover1 != null && _coversCached)

                {

                    var rt1 = imgCover1.GetComponent<RectTransform>();

                    var rawImg1 = imgCover1.GetComponent<UnityEngine.UI.RawImage>();

                    if (rt1 != null && rawImg1 != null)

                    {

                        rt1.sizeDelta = new Vector2(rt1.sizeDelta.x, _cover1Height);

                        rt1.anchoredPosition = _cover1OrigPos;

                        rawImg1.uvRect = _cover1OrigUV;

                    }

                }

                if (imgCover2 != null && _coversCached)

                {

                    var rt2 = imgCover2.GetComponent<RectTransform>();

                    var rawImg2 = imgCover2.GetComponent<UnityEngine.UI.RawImage>();

                    if (rt2 != null && rawImg2 != null)

                    {

                        rt2.sizeDelta = new Vector2(rt2.sizeDelta.x, _cover2Height);

                        rt2.anchoredPosition = _cover2OrigPos;

                        rawImg2.uvRect = _cover2OrigUV;

                    }

                }

                // 2. Play success loading bar frames (0..18) for previewing

                for (int i = 0; i < 19; i++)

                {

                    if (i > 0)

                    {

                        var prevFrame = KOUIRenderer.FindChildByID(root, $"img_s_load_{i - 1}");

                        if (prevFrame != null) prevFrame.gameObject.SetActive(false);

                    }

                    var curFrame = KOUIRenderer.FindChildByID(root, $"img_s_load_{i}");

                    if (curFrame != null)

                    {

                        var rt = curFrame.GetComponent<RectTransform>();

                        if (rt != null) rt.anchoredPosition = new Vector2(rt.anchoredPosition.x, -105f);

                        curFrame.gameObject.SetActive(true);

                    }

                    yield return new WaitForSeconds(0.1f);

                }

                // Hide last frame (frame 18)

                {

                    var lastFrame = KOUIRenderer.FindChildByID(root, "img_s_load_18");

                    if (lastFrame != null) lastFrame.gameObject.SetActive(false);

                }

                // 3. Set preview state active right before opening

                if (isRingUpgrade)

                {

                    var ringMgr = KOAccessoryUpgradeManager.Instance;

                    if (ringMgr != null)

                    {

                        ringMgr.IsPreviewActive = true;

                        ringMgr.PreviewResultItemId = previewId;

                        ringMgr.RefreshUpgradeSlots();

                    }

                }

                else

                {

                    var mgr = KOItemUpgradeManager.Instance;

                    if (mgr != null)

                    {

                        mgr.IsPreviewActive = true;

                        mgr.PreviewResultItemId = previewId;

                    }

                    RefreshUpgradeSlots();

                }

                // 4. Cover Opening Animation: 0.8s duration

                float coverAnimDuration = 0.8f;

                float elapsed = 0.0f;

                while (elapsed < coverAnimDuration)

                {

                    elapsed += Time.deltaTime;

                    float t = Mathf.Min(elapsed / coverAnimDuration, 1.0f);

                    float ease = 1.0f - ((1.0f - t) * (1.0f - t));

                    if (imgCover1 != null)

                    {

                        var rt1 = imgCover1.GetComponent<RectTransform>();

                        var rawImg1 = imgCover1.GetComponent<UnityEngine.UI.RawImage>();

                        if (rt1 != null && rawImg1 != null && _coversCached)

                        {

                            float hCurrent = _cover1Height * (1.0f - ease);

                            rt1.sizeDelta = new Vector2(rt1.sizeDelta.x, hCurrent);

                            rt1.anchoredPosition = _cover1OrigPos;

                            Rect uv = _cover1OrigUV;

                            uv.height = _cover1OrigUV.height * (1.0f - ease);

                            rawImg1.uvRect = uv;

                        }

                    }

                    if (imgCover2 != null)

                    {

                        var rt2 = imgCover2.GetComponent<RectTransform>();

                        var rawImg2 = imgCover2.GetComponent<UnityEngine.UI.RawImage>();

                        if (rt2 != null && rawImg2 != null && _coversCached)

                        {

                            float hCurrent = _cover2Height * (1.0f - ease);

                            rt2.sizeDelta = new Vector2(rt2.sizeDelta.x, hCurrent);

                            rt2.anchoredPosition = new Vector2(_cover2OrigPos.x, _cover2OrigPos.y - _cover2Height + hCurrent);

                            Rect uv = _cover2OrigUV;

                            uv.y = _cover2OrigUV.y + _cover2OrigUV.height * ease;

                            uv.height = _cover2OrigUV.height * (1.0f - ease);

                            rawImg2.uvRect = uv;

                        }

                    }

                    yield return null;

                }

            }

            finally

            {

                ResetCovers();

                if (isRingUpgrade)

                {

                    var ringMgr = KOAccessoryUpgradeManager.Instance;

                    if (ringMgr != null)

                    {

                        ringMgr.IsUpgradeInProgress = false;

                    }

                }

                else

                {

                    var mgr = KOItemUpgradeManager.Instance;

                    if (mgr != null)

                    {

                        mgr.IsUpgradeInProgress = false;

                    }

                }

                _previewAnimationCoroutine = null;

            }

        }

