        // ====================================================================

        // Faz 4: Upgrade Envanter Rendering + Slot Yönetimi

        // C++ karşılığı: UIItemUpgrade.cpp CopyInventoryItems (299-335),

        //                Render (154-199), HandleInventoryIconRightClick (1236-1298)

        // ====================================================================

        /// <summary>

        /// Open-KO birebir: UIItemUpgrade.cpp:299-335 — CopyInventoryItems()

        ///

        /// Panel açıldığında envanter ikonlarını upgrade panelinin a_slot_0..27 alanlarına render eder.

        /// C++'da m_pMyUpgradeInv[28] envanter kopyasıdır — mobilde doğrudan GameManager.Inventory okuruz.

        /// Her slot'a double-tap handler eklenir (C++ HandleInventoryIconRightClick karşılığı).

        /// </summary>

        public void PopulateUpgradeInventory()

        {

            ClearUpgradeIcons();

            bool isFast = IsFastUpgradeUIOpen;

            bool isExchange = IsGemChestExchangeUIOpen;

            Transform root = null;

            if (isFast) root = _uiFastUpgrade != null ? _uiFastUpgrade.transform : null;

            else if (isExchange) root = _uiGemChestExchange != null ? _uiGemChestExchange.transform : null;

            else root = _uiItemUpgrade != null ? _uiItemUpgrade.transform : null;

            if (root == null) return;

            var mgr = isFast ? (IKOUpgradeManager)KOFastUpgradeManager.Instance : (IKOUpgradeManager)KOItemUpgradeManager.Instance;

            if (KOInventory.Instance == null) return;

            if (!isExchange && mgr == null) return;

            // C++ satır 310-334: for (int i = 0; i < MAX_ITEM_INVENTORY; i++)

            for (int i = 0; i < KOItemUpgradeManager.MAX_ITEM_INVENTORY; i++)

            {

                // C++ satır 325-330: m_pAreaInv[i] = GetChildByID<CN3UIArea>(fmt::format("a_slot_{}", i))

                var slotArea = KOUIRenderer.FindChildByID(root, $"a_slot_{i}");

                if (slotArea == null) continue;

                // Envanterdeki bu slot'taki eşyayı bul

                var slot = KOInventory.Instance.m_pMyInvWnd[i];

                if (slot == null || slot.itemId == 0) continue;

                // C++ check: Calculate how many items from this slot are currently placed in the anvil

                int placedCount = 0;

                if (isFast)

                {

                    placedCount = KOFastUpgradeManager.Instance.IsItemPlaced(i) ? 1 : 0;

                }

                else if (isExchange)

                {

                    placedCount = (KOGemChestExchangeManager.Instance != null && i == KOGemChestExchangeManager.Instance.SelectedInvPos) ? 1 : 0;

                }

                else

                {

                    if (i == mgr.UpgradeItemSlotInvPos)

                    {

                        placedCount++;

                    }

                    for (int req = 0; req < KOItemUpgradeManager.ANVIL_REQ_MAX; req++)

                    {

                        if (mgr.GetRequirementSlotPos(req) == i)

                        {

                            placedCount++;

                        }

                    }

                }

                int displayedCount = slot.count - placedCount;

                if (displayedCount <= 0)

                    continue;

                var item = slot.serverData;

                if (item == null)

                {

                    item = new InventoryItemData

                    {

                        ItemDefId = slot.itemId,

                        SlotType = 0,

                        SlotIndex = (byte)i,

                        StackCount = (short)slot.count,

                        Durability = (short)slot.durability,

                        AttachPoint = (byte)slot.attachPoint,

                        Type = (byte)slot.itemClass

                    };

                }

                // C++ satır 323-330: spItem->pUIIcon->SetRegion(pArea->GetRegion())

                var iconObj = new GameObject($"UpgradeInvSlot_{i}");

                iconObj.transform.SetParent(slotArea, false);

                var iconRT = iconObj.AddComponent<RectTransform>();

                iconRT.anchorMin = Vector2.zero;

                iconRT.anchorMax = Vector2.one;

                iconRT.sizeDelta = Vector2.zero;

                iconRT.offsetMin = Vector2.zero;

                iconRT.offsetMax = Vector2.zero;

                // Ikon yükle (C++ SetTex birebir)

                var icon = KOItemIconLoader.LoadItemIcon(ResolveIconId(item.ItemDefId));

                var img = iconObj.AddComponent<Image>();

                if (icon != null)

                {

                    img.sprite = icon;

                    img.preserveAspect = true;

                }

                else

                {

                    img.color = new Color(0.3f, 0.3f, 0.3f, 0.5f);

                }

                img.raycastTarget = true;

                                // C++ Render satır 182-195: Stack count overlay

                byte byContableCheck = 0;

                byte byAttachPointCheck = 0;

                if (KOInventory.s_pTbl_Items_Basic != null &&

                    KOInventory.s_pTbl_Items_Basic.TryGetValue((uint)(item.ItemDefId / 1000 * 1000), out var basicCount))

                {

                    byContableCheck = basicCount.byContable;

                    byAttachPointCheck = basicCount.byAttachPoint;

                }

                int displayCountVal = displayedCount;

                bool showCount = false;

                if (byContableCheck == 1 || byContableCheck == 2)

                {

                    if (displayedCount > 1)

                    {

                        showCount = true;

                    }

                }

                else if (byAttachPointCheck == 15 && item.Durability > 1)

                {

                    displayCountVal = item.Durability;

                    showCount = true;

                }

                if (showCount)

                {

                    var countObj = new GameObject("CountText");

                    countObj.transform.SetParent(iconObj.transform, false);

                    var countRT = countObj.AddComponent<RectTransform>();

                    countRT.anchorMin = new Vector2(1, 0);

                    countRT.anchorMax = new Vector2(1, 0);

                    countRT.pivot = new Vector2(1, 0);

                    countRT.anchoredPosition = new Vector2(-2, 2);

                    countRT.sizeDelta = new Vector2(30, 12);

                    var countText = countObj.AddComponent<Text>();

                    countText.text = displayCountVal.ToString();

                    countText.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");

                    countText.fontSize = 9;

                    countText.color = Color.white;

                    countText.alignment = TextAnchor.LowerRight;

                    countText.raycastTarget = false;

                }

                // ====================================================================

                // Double-tap handler — C++ HandleInventoryIconRightClick karşılığı

                // C++ UIItemUpgrade.cpp:1236-1298

                // Mobil: right-click yok → double-tap ile aynı davranış.

                // Ayrıca KOItemDragHandler eklenir → sürükle-bırak desteği.

                // ====================================================================

                int capturedSlotIndex = i;  // Closure capture

                // Mobil adaptasyon: single-tap=tooltip

                var upgradeHandler = iconObj.AddComponent<KOItemSlotHandler>();

                upgradeHandler.slotType = KOItemSlotHandler.SlotType.BagSlot;

                upgradeHandler.slotIndex = capturedSlotIndex;

                upgradeHandler.tooltipItemDefId = item.ItemDefId;

                upgradeHandler.tooltipShowPrice = false;

                var btn = iconObj.AddComponent<Button>();

                btn.transition = Selectable.Transition.None;

                btn.onClick.AddListener(() => OnUpgradeInventorySlotTap(capturedSlotIndex));

                // KOItemDragHandler ekle — envanter slot'undan upgrade/requirement area'ya sürükleme

                var dragHandler = iconObj.AddComponent<KOItemDragHandler>();

                dragHandler.district = KOItemDragHandler.SlotDistrict.BagSlot;

                dragHandler.slotIndex = capturedSlotIndex;

                _upgradeInvIcons.Add(iconObj);

            }

            // Upgrade ve requirement slot'larını da güncelle

            RefreshUpgradeSlots();

        }

        /// <summary>

        /// Upgrade slot (a_upgrade) ve requirement slot'larını (a_m_0..8) günceller.

        /// KOItemUpgradeManager state'inden okuyarak ikonları render eder.

        ///

        /// C++ karşılığı: UIItemUpgrade.cpp:349-361 (upgrade slot render),

        ///                UIItemUpgrade.cpp:1300-1314 (requirement slot render)

        /// </summary>

        public void RefreshUpgradeSlots()

        {

            bool isFast = IsFastUpgradeUIOpen;

            Transform root = isFast ? (_uiFastUpgrade != null ? _uiFastUpgrade.transform : null) : (_uiItemUpgrade != null ? _uiItemUpgrade.transform : null);

            if (root == null) return;

            var mgr = isFast ? (IKOUpgradeManager)KOFastUpgradeManager.Instance : (IKOUpgradeManager)KOItemUpgradeManager.Instance;

            var gm = EntropyOnline.Core.GameManager.Instance;

            if (mgr == null || gm == null) return;

            if (isFast)

            {

                // Clear dynamic slot icons for fast upgrade

                foreach (var obj in _fastUpgradeIcons)

                {

                    if (obj != null) Destroy(obj);

                }

                _fastUpgradeIcons.Clear();

                var fastMgr = KOFastUpgradeManager.Instance;

                if (fastMgr != null)

                {

                    var slotsParent = root.Find("FastUpgradeSlotsParent");

                    if (slotsParent != null)

                    {

                        for (int i = 0; i < KOFastUpgradeManager.FAST_ANVIL_SLOT_MAX; i++)

                        {

                            int reqInvPos = fastMgr.GetUpgradeItemSlotPos(i);

                            if (reqInvPos < 0) continue;

                            var slotArea = slotsParent.Find($"a_fast_slot_{i}");

                            if (slotArea == null) continue;

                            InventoryItemData upgradeItem = null;

                            if (KOInventory.Instance != null && reqInvPos < KOInventory.MAX_ITEM_INVENTORY)

                            {

                                var slot = KOInventory.Instance.m_pMyInvWnd[reqInvPos];

                                if (slot != null && slot.itemId != 0)

                                {

                                    upgradeItem = slot.serverData ?? new InventoryItemData

                                    {

                                        ItemDefId = slot.itemId,

                                        SlotType = 0,

                                        SlotIndex = (byte)reqInvPos,

                                        StackCount = (short)slot.count,

                                        Durability = (short)slot.durability,

                                        AttachPoint = (byte)slot.attachPoint,

                                        Type = (byte)slot.itemClass

                                    };

                                }

                            }

                            if (upgradeItem != null)

                            {

                                var iconObj = CreateSlotIcon(slotArea, upgradeItem, $"FastUpgradeSlot_{i}");

                                var btn = iconObj.AddComponent<Button>();

                                btn.transition = Selectable.Transition.None;

                                var img = iconObj.GetComponent<Image>();

                                if (img != null) img.raycastTarget = true;

                                int capturedIndex = i;

                                btn.onClick.AddListener(() =>

                                {

                                    if (fastMgr.IsUpgradeInProgress) return;

                                    fastMgr.RemoveUpgradeItem(capturedIndex);

                                    fastMgr.IsUpgradeSucceeded = false;

                                    PopulateUpgradeInventory();

                                });

                                var tooltipHandler = iconObj.AddComponent<KOItemSlotHandler>();

                                tooltipHandler.slotType = KOItemSlotHandler.SlotType.BagSlot;

                                tooltipHandler.slotIndex = reqInvPos;

                                tooltipHandler.tooltipItemDefId = upgradeItem.ItemDefId;

                                tooltipHandler.tooltipShowPrice = false;

                                _fastUpgradeIcons.Add(iconObj);

                            }

                        }

                    }

                }

                // Update Dynamic Upgrade Success Rate -> Hide

                var fastRateContainer = root.Find("UpgradeRateContainer");

                if (fastRateContainer != null) fastRateContainer.gameObject.SetActive(false);

                // Update Dynamic Upgrade Cost (Need Coins)

                var fastNeedCoinsContainer = root.Find("NeedCoinsContainer");

                if (fastNeedCoinsContainer != null)

                {

                    int cost = fastMgr != null ? fastMgr.CalculateUpgradeCost() : 0;

                    fastNeedCoinsContainer.gameObject.SetActive(true);

                    var valTxt = fastNeedCoinsContainer.Find("ValueBg/ValueText")?.GetComponent<UnityEngine.UI.Text>();

                    if (valTxt != null)

                    {

                        valTxt.text = cost.ToString("N0");

                    }

                }

                return;

            }

            // ---- Upgrade (main) slot ----

            if (_upgradeMainIcon != null)

            {

                Destroy(_upgradeMainIcon);

                _upgradeMainIcon = null;

            }

            if (_upgradeResultIcon != null)

            {

                Destroy(_upgradeResultIcon);

                _upgradeResultIcon = null;

            }

            if (mgr.UpgradeItemSlotInvPos >= 0)

            {

                var aUpgrade = KOUIRenderer.FindChildByID(root, "a_upgrade");

                var aResult = KOUIRenderer.FindChildByID(root, "a_result");

                InventoryItemData upgradeItem = null;

                if (KOInventory.Instance != null && mgr.UpgradeItemSlotInvPos < KOInventory.MAX_ITEM_INVENTORY)

                {

                    var slot = KOInventory.Instance.m_pMyInvWnd[mgr.UpgradeItemSlotInvPos];

                    if (slot != null && slot.itemId != 0)

                    {

                        upgradeItem = slot.serverData ?? new InventoryItemData

                        {

                            ItemDefId = slot.itemId,

                            SlotType = 0,

                            SlotIndex = (byte)mgr.UpgradeItemSlotInvPos,

                            StackCount = (short)slot.count,

                            Durability = (short)slot.durability,

                            AttachPoint = (byte)slot.attachPoint,

                            Type = (byte)slot.itemClass

                        };

                    }

                }

                if (upgradeItem != null)

                {

                    if (mgr.IsPreviewActive)

                    {

                        if (aUpgrade != null)

                        {

                            _upgradeMainIcon = CreateSlotIcon(aUpgrade, upgradeItem, "UpgradeMainSlot");

                            var btn = _upgradeMainIcon.AddComponent<Button>();

                            btn.transition = Selectable.Transition.None;

                            var img = _upgradeMainIcon.GetComponent<Image>();

                            if (img != null) img.raycastTarget = true;

                            btn.onClick.AddListener(() =>

                            {

                                if (mgr.IsUpgradeInProgress) return;

                                mgr.ResetUpgradeInventory();

                                PopulateUpgradeInventory();

                            });

                        }

                        if (aResult != null)

                        {

                            var previewItem = new InventoryItemData

                            {

                                ItemDefId = mgr.PreviewResultItemId,

                                SlotType = 0,

                                SlotIndex = 0,

                                StackCount = 1,

                                Durability = upgradeItem.Durability,

                                AttachPoint = upgradeItem.AttachPoint,

                                Type = upgradeItem.Type

                            };

                            _upgradeResultIcon = CreateSlotIcon(aResult, previewItem, "UpgradeResultSlot");

                            var previewHandler = _upgradeResultIcon.AddComponent<KOItemSlotHandler>();

                            previewHandler.slotType = KOItemSlotHandler.SlotType.BagSlot;

                            previewHandler.tooltipItemDefId = mgr.PreviewResultItemId;

                            previewHandler.itemData = previewItem;

                            var img = _upgradeResultIcon.GetComponent<Image>();

                            if (img != null) img.raycastTarget = true;

                        }

                    }

                    else if (mgr.IsUpgradeSucceeded)

                    {

                        if (aResult != null)

                        {

                            _upgradeResultIcon = CreateSlotIcon(aResult, upgradeItem, "UpgradeResultSlot");

                            var btn = _upgradeResultIcon.AddComponent<Button>();

                            btn.transition = Selectable.Transition.None;

                            var img = _upgradeResultIcon.GetComponent<Image>();

                            if (img != null) img.raycastTarget = true;

                            btn.onClick.AddListener(() =>

                            {

                                mgr.ResetUpgradeInventory();

                                PopulateUpgradeInventory();

                            });

                        }

                    }

                    else

                    {

                        if (aUpgrade != null)

                        {

                            _upgradeMainIcon = CreateSlotIcon(aUpgrade, upgradeItem, "UpgradeMainSlot");

                            var btn = _upgradeMainIcon.AddComponent<Button>();

                            btn.transition = Selectable.Transition.None;

                            var img = _upgradeMainIcon.GetComponent<Image>();

                            if (img != null) img.raycastTarget = true;

                            btn.onClick.AddListener(() =>

                            {

                                if (mgr.IsUpgradeInProgress) return;

                                mgr.ResetUpgradeInventory();

                                PopulateUpgradeInventory();

                            });

                        }

                    }

                }

            }

            // ---- Requirement slot'ları ----

            for (int i = 0; i < KOItemUpgradeManager.ANVIL_REQ_MAX; i++)

            {

                if (_upgradeReqIcons[i] != null)

                {

                    Destroy(_upgradeReqIcons[i]);

                    _upgradeReqIcons[i] = null;

                }

                int reqInvPos = mgr.GetRequirementSlotPos(i);

                if (reqInvPos < 0) continue;

                var slotArea = KOUIRenderer.FindChildByID(root, $"a_m_{i}");

                if (slotArea == null) continue;

                InventoryItemData reqItem = null;

                if (KOInventory.Instance != null && reqInvPos >= 0 && reqInvPos < KOInventory.MAX_ITEM_INVENTORY)

                {

                    var slot = KOInventory.Instance.m_pMyInvWnd[reqInvPos];

                    if (slot != null && slot.itemId != 0)

                    {

                        reqItem = slot.serverData ?? new InventoryItemData

                        {

                            ItemDefId = slot.itemId,

                            SlotType = 0,

                            SlotIndex = (byte)reqInvPos,

                            StackCount = (short)slot.count,

                            Durability = (short)slot.durability,

                            AttachPoint = (byte)slot.attachPoint,

                            Type = (byte)slot.itemClass

                        };

                    }

                }

                if (reqItem != null)

                {

                    _upgradeReqIcons[i] = CreateSlotIcon(slotArea, reqItem, $"UpgradeReqSlot_{i}");

                    var btn = _upgradeReqIcons[i].AddComponent<Button>();

                    btn.transition = Selectable.Transition.None;

                    var img = _upgradeReqIcons[i].GetComponent<Image>();

                    if (img != null) img.raycastTarget = true;

                    int capturedIndex = i;

                    btn.onClick.AddListener(() =>

                    {

                        if (mgr.IsUpgradeInProgress) return;

                        mgr.RemoveRequirementItem(capturedIndex);

                        PopulateUpgradeInventory();

                    });

                }

            }

            // Update Dynamic Upgrade Success Rate

            var rateContainer = root.Find("UpgradeRateContainer");

            if (rateContainer != null)

            {

                float rate = mgr.CalculateUpgradeRate();

                if (rate >= 0f)

                {

                    rateContainer.gameObject.SetActive(true);

                    var valTxt = rateContainer.Find("ValueBg/ValueText")?.GetComponent<UnityEngine.UI.Text>();

                    if (valTxt != null)

                    {

                        valTxt.text = $"%{rate:0}";

                    }

                }

                else

                {

                    rateContainer.gameObject.SetActive(false);

                }

            }

            // Update Dynamic Upgrade Cost (Need Coins)

            var needCoinsContainer = root.Find("NeedCoinsContainer");

            if (needCoinsContainer != null)

            {

                int cost = mgr.CalculateUpgradeCost();

                if (cost >= 0)

                {

                    needCoinsContainer.gameObject.SetActive(true);

                    var valTxt = needCoinsContainer.Find("ValueBg/ValueText")?.GetComponent<UnityEngine.UI.Text>();

                    if (valTxt != null)

                    {

                        valTxt.text = cost.ToString("N0"); // e.g. "240,000" or "500,000" or "0"

                    }

                }

                else

                {

                    needCoinsContainer.gameObject.SetActive(false);

                }

            }

        }

        public void OnPreviewButtonClicked()

        {

            bool isFast = IsFastUpgradeUIOpen;

            var mgr = isFast ? (IKOUpgradeManager)KOFastUpgradeManager.Instance : (IKOUpgradeManager)KOItemUpgradeManager.Instance;

            if (mgr == null) return;

            if (mgr.IsUpgradeInProgress) return;

            int previewId;

            if (mgr.RequestUpgradePreview(out previewId))

            {

                PlayPreviewAnimation(previewId);

            }

            else

            {

                AddMsgOutput("Cannot preview upgrade for this item.", D3DColorToUnity(0xffff00ff));

            }

        }

        /// <summary>

        /// Open-KO birebir: UIItemUpgrade.cpp:1236-1298 — HandleInventoryIconRightClick()

        ///

        /// Mobil adaptasyon: right-click yok → double-tap ile aynı davranış.

        /// İlk tap'ta slot seçilir, 0.4s içinde ikinci tap → item yerleştirilir.

        ///

        /// Kurallar (C++ birebir):

        ///   1. Upgrade slot boş + item silah/zırh ise → upgrade slot'a koy (cpp:1255-1264)

        ///   2. Aksi halde item consumable/scroll ise → boş requirement slot'a koy (cpp:1267-1288)

        /// </summary>

        private void OnUpgradeInventorySlotTap(int invPos)

        {

            float now = Time.unscaledTime;

            // Double-tap kontrolü

            if (_lastUpgradeSlotTapIndex == invPos && (now - _lastUpgradeSlotTapTime) < DOUBLE_TAP_THRESHOLD)

            {

                // Double-tap algılandı — C++ HandleInventoryIconRightClick birebir

                _lastUpgradeSlotTapIndex = -1;

                _lastUpgradeSlotTapTime = 0;

                bool isFast = IsFastUpgradeUIOpen;

                var mgr = isFast ? (IKOUpgradeManager)KOFastUpgradeManager.Instance : (IKOUpgradeManager)KOItemUpgradeManager.Instance;

                if (mgr == null) return;

                // C++ satır 1252-1253: if (m_bUpgradeSucceeded) ResetUpgradeInventory()

                if (mgr.IsUpgradeSucceeded)

                {

                    if (isFast)

                    {

                        KOFastUpgradeManager.Instance.IsUpgradeSucceeded = false;

                    }

                    else

                    {

                        mgr.ResetUpgradeInventory();

                    }

                    PopulateUpgradeInventory();

                }

                // C++ satır 1255-1264: upgrade slot boş + IsAllowedUpgradeItem

                if (mgr.SetUpgradeItem(invPos))

                {

                    PopulateUpgradeInventory();

                    return;

                }

                // C++ satır 1267-1288: IsValidRequirementItem → boş requirement slot'a koy

                if (mgr.SetRequirementItem(invPos))

                {

                    PopulateUpgradeInventory();

                    return;

                }



            }

            else

            {

                // İlk tap — kaydet

                _lastUpgradeSlotTapIndex = invPos;

                _lastUpgradeSlotTapTime = now;

            }

        }

        /// <summary>

        /// Upgrade panelindeki dinamik olarak oluşturulan tüm ikonları temizler.

        /// C++ karşılığı: CopyInventoryItems başında yapılan cleanup (cpp:312-318).

        /// </summary>

        private void ClearUpgradeIcons()

        {

            foreach (var obj in _upgradeInvIcons)

                if (obj != null) Destroy(obj);

            _upgradeInvIcons.Clear();

            foreach (var obj in _fastUpgradeIcons)

                if (obj != null) Destroy(obj);

            _fastUpgradeIcons.Clear();

            if (_upgradeMainIcon != null)

            {

                Destroy(_upgradeMainIcon);

                _upgradeMainIcon = null;

            }

            if (_upgradeResultIcon != null)

            {

                Destroy(_upgradeResultIcon);

                _upgradeResultIcon = null;

            }

            for (int i = 0; i < KOItemUpgradeManager.ANVIL_REQ_MAX; i++)

            {

                if (_upgradeReqIcons[i] != null)

                {

                    Destroy(_upgradeReqIcons[i]);

                    _upgradeReqIcons[i] = null;

                }

            }

            _lastUpgradeSlotTapIndex = -1;

            _lastUpgradeSlotTapTime = 0;

        }

        /// <summary>

        /// Yardımcı: Belirtilen parent area'ya bir item ikonu oluşturur.

        /// C++ karşılığı: spItem->pUIIcon->SetRegion(pArea->GetRegion())

        /// </summary>

        private GameObject CreateSlotIcon(Transform parent, InventoryItemData item, string name)

        {

            var iconObj = new GameObject(name);

            iconObj.transform.SetParent(parent, false);

            var iconRT = iconObj.AddComponent<RectTransform>();

            iconRT.anchorMin = Vector2.zero;

            iconRT.anchorMax = Vector2.one;

            iconRT.sizeDelta = Vector2.zero;

            iconRT.offsetMin = Vector2.zero;

            iconRT.offsetMax = Vector2.zero;

            var icon = KOItemIconLoader.LoadItemIcon(ResolveIconId(item.ItemDefId));

            var img = iconObj.AddComponent<Image>();

            if (icon != null)

            {

                img.sprite = icon;

                img.preserveAspect = true;

            }

            else

            {

                img.color = new Color(0.3f, 0.3f, 0.3f, 0.5f);

            }

            img.raycastTarget = false; // Slot area'nın tıklamasını engellemez

            return iconObj;

        }

