        /// <summary>

        /// Chat panelini bağla.

        /// C++ UIChat.cpp Load() satır 273-303 birebir:

        /// m_pChatOut = GetChildByID<CN3UIString>("text0");

        /// m_pEdit = GetChildByID<CN3UIEdit>("edit0");

        /// m_pBtn_Normal = GetChildByID("btn_normal");

        /// </summary>

        private void BindChatPanel(Transform root)

        {

            if (IsModernPrefab(root))

            {

                BindChatPanelPrefab(root);

                return;

            }

            _chatOutputText = KOUIRenderer.FindChildText(root, "text0");

            if (_chatOutputText != null)

            {

                SetupChatScrollRect(_chatOutputText);

            }

            // C++ satır 287-288: edit0 → input alanı

            // UIF'de CN3UIEdit yok — mobilde InputField component'i ekle

            var editTransform = KOUIRenderer.FindChildByID(root, "edit0");

            if (editTransform != null)

            {

                var editGO = editTransform.gameObject;

                _chatInputField = editGO.GetComponent<InputField>();

                if (_chatInputField == null)

                {

                    // InputField component'i oluştur

                    var editText = editGO.GetComponent<Text>();

                    if (editText == null)

                    {

                        editText = editGO.AddComponent<Text>();

                        editText.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");

                        editText.fontSize = 11;

                        editText.color = Color.white;

                        // Türkçe karakter desteği

                        if (editText.font != null)

                            editText.font.RequestCharactersInTexture("ğüşöçıİĞÜŞÖÇ", 11);

                    }

                    _chatInputField = editGO.AddComponent<InputField>();

                    _chatInputField.textComponent = editText;

                    // C++ birebir: UI SetMaxString(256) ama MsgSend_Chat 128'de kesiyor (cpp:1553)

                    // Efektif sınır: 128 karakter

                    _chatInputField.characterLimit = 128;

                }

                // C++ UIMSG_EDIT_RETURN → Enter tuşu ile gönderme

                _chatInputField.onEndEdit.AddListener(OnChatInputSubmit);

            }

            // C++ satır 291-298: buton binding

            // Mobilde chat mode butonlarını bağla

            BindChatModeButton(root, "btn_normal", 1);  // N3_CHAT_NORMAL=1

            BindChatModeButton(root, "btn_private", 2); // N3_CHAT_PRIVATE=2

            BindChatModeButton(root, "btn_party_force", 3); // N3_CHAT_PARTY=3

            BindChatModeButton(root, "btn_knights", 6);     // N3_CHAT_CLAN=6

            BindChatModeButton(root, "btn_shout", 5);       // N3_CHAT_SHOUT=5

            // C++ birebir: ChangeChattingMode() — default buton state'i ayarla

            UpdateChatModeButtonStates();

            // C++ UIChat.cpp satır 297: btn_check_normal → kanal dinleme toggle

            var btnCheck = KOUIRenderer.FindChildButton(root, "btn_check_normal");

            if (btnCheck != null)

            {

                btnCheck.onClick.AddListener(() => ChatListenEnable());

            }

            // Arayüzü yeniden yapılandır (boşlukları kapat, isimleri değiştir, notices ekle)

            RestructureChatPanel(root);

        }

        private void BindChatPanelPrefab(Transform root)

        {

            CleanLegacyPrefabImages(root);

            _chatOutputText = KOUIRenderer.FindChildText(root, "text0");

            var rt = root.GetComponent<RectTransform>();

            if (rt != null && rt.rect.width > 0 && rt.rect.height > 0)

            {

                _chatWidth = rt.rect.width;

                _chatHeight = rt.rect.height;

            }

            // Hide the unused tabs and checkboxes

            string[] inactiveElements = { "btn_private", "btn_union", "btn_clan", "btn_check_normal", "btn_check_shout", "btn_check_party_force", "btn_check_clan", "btn_check_union", "btn_check_private", "btn_check_notices" };

            foreach (var name in inactiveElements)

            {

                var t = root.Find(name);

                if (t != null) t.gameObject.SetActive(false);

            }

            var editTransform = KOUIRenderer.FindChildByID(root, "edit0");

            if (editTransform != null)

            {

                var rtEdit = editTransform.GetComponent<RectTransform>();

                if (rtEdit != null)

                {

                    rtEdit.anchorMin = new Vector2(0, 1); // top-left (hizalama için bu gerekli)

                    rtEdit.anchorMax = new Vector2(0, 1);

                    rtEdit.pivot = new Vector2(0, 1);

                }

                var editGO = editTransform.gameObject;

                _chatInputField = editGO.GetComponent<InputField>();

                if (_chatInputField == null)

                {

                    var editText = editGO.GetComponent<Text>();

                    if (editText == null)

                    {

                        editText = editGO.AddComponent<Text>();

                        editText.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");

                        editText.fontSize = 11;

                        editText.color = Color.white;

                        if (editText.font != null)

                            editText.font.RequestCharactersInTexture("ğüşöçıİĞÜŞÖÇ", 11);

                    }

                    _chatInputField = editGO.AddComponent<InputField>();

                    _chatInputField.textComponent = editText;

                    _chatInputField.characterLimit = 128;

                }

                _chatInputField.onEndEdit.RemoveAllListeners();

                _chatInputField.onEndEdit.AddListener(OnChatInputSubmit);

            }

            _chatScrollRect = root.GetComponentInChildren<ScrollRect>(true);

            if (_chatScrollRect == null && _chatOutputText != null)

            {

                SetupChatScrollRect(_chatOutputText);

            }

            // Bind buttons

            BindChatModeButton(root, "btn_normal", 1);  // N3_CHAT_NORMAL=1

            BindChatModeButton(root, "btn_private", 2); // N3_CHAT_PRIVATE=2

            BindChatModeButton(root, "btn_party_force", 3); // N3_CHAT_PARTY=3

            BindChatModeButton(root, "btn_knights", 6);     // N3_CHAT_CLAN=6

            BindChatModeButton(root, "btn_shout", 5);       // N3_CHAT_SHOUT=5

            // Bind Notices Button

            var btnNotices = KOUIRenderer.FindChildButton(root, "btn_notices");

            if (btnNotices != null)

            {

                btnNotices.onClick.RemoveAllListeners();

                btnNotices.onClick.AddListener(() =>

                {

                    _chatMode = 10; // Özel Notices chat modu

                    UpdateChatModeButtonStates();

                });

                _chatModeButtons[10] = btnNotices;

            }

            UpdateChatModeButtonStates();

            // Set tab icons

            var bNormal = KOUIRenderer.FindChildButton(root, "btn_normal");

            if (bNormal != null) AddIconToButton(bNormal.gameObject, GetChatTabIconSprite("chat"));

            var bShout = KOUIRenderer.FindChildButton(root, "btn_shout");

            if (bShout != null) AddIconToButton(bShout.gameObject, GetChatTabIconSprite("shout"));

            var bParty = KOUIRenderer.FindChildButton(root, "btn_party_force");

            if (bParty != null) AddIconToButton(bParty.gameObject, GetChatTabIconSprite("party"));

            var bClan = KOUIRenderer.FindChildButton(root, "btn_knights");

            if (bClan != null) AddIconToButton(bClan.gameObject, GetChatTabIconSprite("clan"));

            if (btnNotices != null) AddIconToButton(btnNotices.gameObject, GetChatTabIconSprite("notices"));

            var btnCheck = KOUIRenderer.FindChildButton(root, "btn_check_normal");

            if (btnCheck != null)

            {

                btnCheck.onClick.RemoveAllListeners();

                btnCheck.onClick.AddListener(() => ChatListenEnable());

            }

            var btnOff = KOUIRenderer.FindChildButton(root, "btn_off");

            if (btnOff != null)

            {

                btnOff.onClick.RemoveAllListeners();

                btnOff.onClick.AddListener(() => ToggleChatFoldState(root));

            }

            UpdateChatPanelLayout(root, _chatWidth, _chatHeight);

            // Add resize handle

            AddResizeHandle(root, new Vector2(280f, 100f), new Vector2(450f, 400f), (newWidth, newHeight) =>

            {

                _chatWidth = newWidth;

                _chatHeight = newHeight;

                UpdateChatPanelLayout(root, newWidth, newHeight);

                RearrangePanelsPosition();

            });

            RearrangePanelsPosition();

        }

        private void RestructureChatPanel(Transform root)

        {

            if (IsModernPrefab(root)) return;

            // 1. "Chat" statik metin etiketlerini gizle

            foreach (var txt in root.GetComponentsInChildren<Text>(true))

            {

                if (txt.text == "Chat")

                {

                    txt.gameObject.SetActive(false);

                }

            }

            // 2. Kapatma/katlama butonunu aktif tut, sol ok simgesi giydir ve en alta konumlandır (NOWA Online yerleşimi)

            SetChildVisible(root, "btn_off", true);

            var btnOff = KOUIRenderer.FindChildButton(root, "btn_off");

            if (btnOff != null)

            {

                btnOff.gameObject.SetActive(true);

                btnOff.transform.localScale = Vector3.one;

                btnOff.onClick.RemoveAllListeners();

                btnOff.onClick.AddListener(() =>

                {

                    ToggleChatFoldState(root);

                });

                var btnOffRT = btnOff.GetComponent<RectTransform>();

                if (btnOffRT != null)

                {

                    btnOffRT.anchorMin = new Vector2(0, 1);

                    btnOffRT.anchorMax = new Vector2(0, 1);

                    btnOffRT.pivot = new Vector2(0, 1);

                    btnOffRT.anchoredPosition = new Vector2(341f, -142f);

                    btnOffRT.sizeDelta = new Vector2(14f, 15f);

                }

                SetUIElementThemeSprite(btnOff.gameObject, GetSkillThemeArrowSprite("chat_btn_off_arrow", 14, 15,

                    new Color(0.18f, 0.14f, 0.10f, 1f), // Koyu bronz zemin

                    new Color(0.5f, 0.4f, 0.18f, 0.9f),   // Parlak altın çerçeve/ok

                    1,

                    true // Sola bakan ok (<)

                ));

            }

            // 3. Kullanılmayan sekmeleri ve tüm filtre checkbox'larını tamamen gizle

            SetChildVisible(root, "btn_private", false);

            SetChildVisible(root, "btn_union", false); // Ally butonu

            SetChildVisible(root, "btn_clan", false); // Mükerrer Clan butonunu tamamen gizle (btn_knights'ı kullanıyoruz)

            string[] checkBtns = { "btn_check_normal", "btn_check_shout", "btn_check_party_force", "btn_check_clan", "btn_check_union", "btn_check_private", "btn_check_notices" };

            foreach (var cName in checkBtns)

            {

                var c = KOUIRenderer.FindChildByID(root, cName);

                if (c != null)

                {

                    c.gameObject.SetActive(false);

                    c.transform.localScale = Vector3.zero; // C++ kodunun zorla aktif etmesini önlemek için ölçeği sıfırlıyoruz

                }

            }

            // 4. Orijinal kaba arka plan görsellerini ve dekorasyon şeritlerini yok et (Böylece oyun motoru bunları zorla görünür yapsa bile çizilmezler)

/* Loop Removed */

/* Loop Removed */

            // 4.5 Scrollbar üzerindeki eski yukarı/aşağı yön ok butonlarını tamamen yok et

            var scrollTransform = root.Find("scroll");

            if (scrollTransform != null)

            {

                var scrollBtns = scrollTransform.GetComponentsInChildren<Button>(true);

                foreach (var sb in scrollBtns)

                {

                    DestroyImmediate(sb.gameObject);

                }

            }

            // 5. Chat panelini yatay olarak daralt (Sekmelere göre ebatlandır: 313f)

            var panelRT = root.GetComponent<RectTransform>();

            if (panelRT != null)

            {

                panelRT.sizeDelta = new Vector2(313f, panelRT.sizeDelta.y);

            }

            // Chat çıkış yazısı (text0) genişliğini ayarla

            var text0 = root.Find("text0");

            if (text0 != null)

            {

                var rtText = text0.GetComponent<RectTransform>();

                if (rtText != null) rtText.sizeDelta = new Vector2(283f, rtText.sizeDelta.y);

            }

            // 6. Kök nesneyi şeffaf yapıyoruz (raycastTarget=true kalabilir ama arka plan çizmeyecek)

            var rootImg = root.GetComponent<Image>();

            if (rootImg == null) rootImg = root.gameObject.AddComponent<Image>();

            if (rootImg != null)

            {

                rootImg.color = Color.clear;

                rootImg.raycastTarget = true;

                rootImg.sprite = null;

            }

            // 7. Sekme isimlerini değiştir, boyutlarını eşitle (74x24) ve simgeleri yerleştir (Öneri A)

            var btnNormal = KOUIRenderer.FindChildButton(root, "btn_normal");

            if (btnNormal != null)

            {

                var rt = btnNormal.GetComponent<RectTransform>();

                if (rt != null) rt.sizeDelta = new Vector2(74f, 24f);

                var txtNormal = btnNormal.GetComponentInChildren<Text>(true);

                if (txtNormal != null) txtNormal.text = "All Chat";

                AddIconToButton(btnNormal.gameObject, GetChatTabIconSprite("chat"));

            }

            var btnShout = KOUIRenderer.FindChildButton(root, "btn_shout");

            if (btnShout != null)

            {

                var rt = btnShout.GetComponent<RectTransform>();

                if (rt != null) rt.sizeDelta = new Vector2(74f, 24f);

                AddIconToButton(btnShout.gameObject, GetChatTabIconSprite("shout"));

            }

            var btnPartyForce = KOUIRenderer.FindChildButton(root, "btn_party_force");

            if (btnPartyForce != null)

            {

                var rt = btnPartyForce.GetComponent<RectTransform>();

                if (rt != null) rt.sizeDelta = new Vector2(74f, 24f);

                AddIconToButton(btnPartyForce.gameObject, GetChatTabIconSprite("party"));

            }

            var btnKnights = KOUIRenderer.FindChildButton(root, "btn_knights");

            if (btnKnights != null)

            {

                var rt = btnKnights.GetComponent<RectTransform>();

                if (rt != null) rt.sizeDelta = new Vector2(74f, 24f);

                var txtKnights = btnKnights.GetComponentInChildren<Text>(true);

                if (txtKnights != null) txtKnights.text = "Clan";

                AddIconToButton(btnKnights.gameObject, GetChatTabIconSprite("clan"));

            }

            // 8. "Notices" sekmesini oluştur (Klonlama)

            GameObject noticesBtnObj = null;

            if (btnPartyForce != null)

            {

                var noticesBtnTransform = root.Find("btn_notices");

                if (noticesBtnTransform == null)

                {

                    noticesBtnObj = Instantiate(btnPartyForce.gameObject, root, false);

                    noticesBtnObj.name = "btn_notices";

                }

                else

                {

                    noticesBtnObj = noticesBtnTransform.gameObject;

                }

                if (noticesBtnObj != null)

                {

                    noticesBtnObj.SetActive(true);

                    var rt = noticesBtnObj.GetComponent<RectTransform>();

                    if (rt != null) rt.sizeDelta = new Vector2(74f, 24f);

                    var txtNotices = noticesBtnObj.GetComponentInChildren<Text>(true);

                    if (txtNotices != null) txtNotices.text = "Notices";

                    AddIconToButton(noticesBtnObj, GetChatTabIconSprite("notices"));

                    var btnNotices = noticesBtnObj.GetComponent<Button>();

                    if (btnNotices != null)

                    {

                        btnNotices.onClick.RemoveAllListeners();

                        btnNotices.onClick.AddListener(() =>

                        {

                            _chatMode = 10; // Özel Notices chat modu

                            UpdateChatModeButtonStates();

                        });

                        _chatModeButtons[10] = btnNotices;

                    }

                }

            }

            // 9. Sekmeleri sola hizalayarak yan yana sırala (NOWA Online - Öneri A: 74px genişlik, sıfır boşluk, Y = 0f)

            RepositionUIElement(root, "btn_normal", new Vector2(0f, 0f));

            RepositionUIElement(root, "btn_shout", new Vector2(74f, 0f));

            RepositionUIElement(root, "btn_party_force", new Vector2(148f, 0f));

            RepositionUIElement(root, "btn_knights", new Vector2(222f, 0f));

            if (noticesBtnObj != null)

            {

                var rtNotices = noticesBtnObj.GetComponent<RectTransform>();

                if (rtNotices != null)

                {

                    rtNotices.anchorMin = new Vector2(0, 1);

                    rtNotices.anchorMax = new Vector2(0, 1);

                    rtNotices.pivot = new Vector2(0, 1);

                    rtNotices.anchoredPosition = new Vector2(296f, 0f);

                    rtNotices.sizeDelta = new Vector2(74f, 24f);

                }

            }

            // 9.5 Mesaj yazma alanını (edit0) belirginleştir ve konumlandır (En altta Y = -142f, Genişlik 321f)

            var editObj = root.Find("edit0")?.gameObject;

            if (editObj != null)

            {

                var editImg = editObj.GetComponent<Image>();

                if (editImg == null) editImg = editObj.AddComponent<Image>();

                if (editImg != null)

                {

                    editImg.enabled = true;

                    editImg.color = Color.white;

                }

                var rtEdit = editObj.GetComponent<RectTransform>();

                if (rtEdit != null)

                {

                    rtEdit.anchorMin = new Vector2(0, 1);

                    rtEdit.anchorMax = new Vector2(0, 1);

                    rtEdit.pivot = new Vector2(0, 1);

                    // Konum, boyut ve sprite UpdateChatPanelLayout içinde dinamik yönetilecek

                }

            }

            // 11. Buton durumlarını ve spritelarını ilk yüklemede hemen zorla uygulayarak göster

            UpdateChatModeButtonStates();

            // 12. Katlama durumunu ve görsellerini ilk yüklemede hemen uygula

            ApplyChatFoldState(root);

            // 13. Çift eksenli boyutlandırma tutamacını ekle (Genişlik: 280-450, Yükseklik: 100-400)

            AddResizeHandle(root, new Vector2(280f, 100f), new Vector2(450f, 400f), (newWidth, newHeight) =>

            {

                _chatWidth = newWidth;

                _chatHeight = newHeight;

                UpdateChatPanelLayout(root, newWidth, newHeight);

                RearrangePanelsPosition();

            });

            PrintFullHierarchy(root, "CHAT", "");

        }

        private void RepositionUIElement(Transform root, string childName, Vector2 anchoredPos)

        {

            var t = root.Find(childName);

            if (t != null)

            {

                var rt = t.GetComponent<RectTransform>();

                if (rt != null)

                {

                    rt.anchorMin = new Vector2(0, 1);

                    rt.anchorMax = new Vector2(0, 1);

                    rt.pivot = new Vector2(0, 1);

                    rt.anchoredPosition = anchoredPos;

                }

            }

        }

        private void SetUIElementThemeSprite(GameObject obj, Sprite sprite)

        {

            if (obj == null || sprite == null) return;

            // Butonun çocuk nesnelerindeki tüm eski durum resimlerini (RawImage/Image) yok et (böylece oyun kodları bunları aktif etse bile çizilemezler)

            for (int i = 0; i < obj.transform.childCount; i++)

            {

                var child = obj.transform.GetChild(i);

                if (child.name == "TabIcon") continue; // Simgeyi yok etme!

                var childRaw = child.GetComponent<RawImage>();

                if (childRaw != null) DestroyImmediate(childRaw);

                var childImg = child.GetComponent<Image>();

                if (childImg != null) DestroyImmediate(childImg);

            }

            // Buton durum geçişlerini kapat (Böylece seçildiğinde veya fareyle üzerine gelindiğinde orijinal gri görsele dönmez)

            var btn = obj.GetComponent<Button>();

            if (btn != null)

            {

                btn.transition = Selectable.Transition.None;

            }

            // RawImage bileşeni varsa doğrudan dokusunu güncelleyelim (en güvenli yöntem)

            var raw = obj.GetComponent<RawImage>();

            if (raw != null)

            {

                raw.enabled = true;

                raw.texture = sprite.texture;

                raw.uvRect = new Rect(0f, 0f, 1f, 1f);

                raw.color = Color.white;

                return;

            }

            var img = obj.GetComponent<Image>();

            if (img == null)

            {

                img = obj.AddComponent<Image>();

            }

            img.enabled = true;

            img.sprite = sprite;

            img.color = Color.white;

        }

        /// <summary>

        /// C++ UIChat.cpp ChangeChattingMode() satır 732-791 birebir.

        /// Seçili kanal butonunu DOWN, diğerlerini NORMAL state'e çeker.

        /// Mobilde: sadece _chatMode set eder.

        /// </summary>

        private void BindChatModeButton(Transform root, string btnId, byte chatMode)

        {

            var btn = KOUIRenderer.FindChildButton(root, btnId);

            if (btn != null)

            {

                byte mode = chatMode;

                _chatModeButtons[mode] = btn;

                btn.onClick.AddListener(() =>

                {

                    // C++ ChangeChattingMode birebir — m_eChatMode set + buton state güncelle

                    _chatMode = mode;

                    UpdateChatModeButtonStates();

                });

            }

        }

        /// <summary>

        /// C++ UIChat.cpp ChangeChattingMode() satır 732-791 birebir:

        /// Seçili kanal butonunu UI_STATE_BUTTON_DOWN, diğerlerini UI_STATE_BUTTON_NORMAL yapar.

        /// Unity'de: UIF butonları sprite-based olduğundan ColorBlock çalışmaz.

        /// Doğrudan Image.color ile basılı/normal efekt veririz.

        /// </summary>

        private void UpdateChatModeButtonStates()

        {

            var activeSprite = GetSkillThemeRoundedRectSprite("chat_tab_active_sharp", 74, 24, 0, // Öneri A: 74x24 tam boy

                new Color(0.35f, 0.28f, 0.15f, 0.45f), // Şeffaflığı artırılmış gold/bronz aktif dolgu

                new Color(0f, 0f, 0f, 0f),             // Çerçevesiz (0 outline thickness)

                0

            );

            var inactiveSprite = GetSkillThemeRoundedRectSprite("chat_tab_inactive_sharp", 74, 24, 0,

                new Color(0f, 0f, 0f, 0f), // Tamamen şeffaf inaktif

                new Color(0f, 0f, 0f, 0f),    // Çerçevesiz

                0

            );

            foreach (var kvp in _chatModeButtons)

            {

                if (kvp.Value == null) continue;

                var sprite = (kvp.Key == _chatMode) ? activeSprite : inactiveSprite;

                SetUIElementThemeSprite(kvp.Value.gameObject, sprite);

                var txt = kvp.Value.GetComponentInChildren<Text>(true);

                if (txt != null)

                {

                    txt.color = (kvp.Key == _chatMode) ? new Color(1f, 0.82f, 0.42f) : new Color(0.8f, 0.76f, 0.72f);

                }

            }

            RebuildChatVisibleText();

        }

        /// <summary>

        /// C++ UIChat.cpp ChatListenEnable() satır 793-815 birebir.

        /// Mevcut mod'un filtreleme durumunu toggle eder.

        /// </summary>

        private void ChatListenEnable()

        {

            switch (_chatMode)

            {

                case 1: // N3_CHAT_NORMAL

                    _bChatNormal = !_bChatNormal;

                    break;

                case 2: // N3_CHAT_PRIVATE

                    _bChatPrivate = !_bChatPrivate;

                    break;

                case 3: // N3_CHAT_PARTY

                case 4: // N3_CHAT_FORCE

                    _bChatParty = !_bChatParty;

                    break;

                case 6: // N3_CHAT_CLAN

                    _bChatClan = !_bChatClan;

                    break;

                case 5: // N3_CHAT_SHOUT

                    _bChatShout = !_bChatShout;

                    break;

            }

        }

        /// <summary>

        /// C++ UIChat.cpp UIMSG_EDIT_RETURN satır 171-218 birebir:

        /// Enter tuşuna basıldığında çağrılır.

        /// '/' → komut, '@' → whisper, '#' → parti, '$' → klan, '!' → shout, else → normal

        /// </summary>

        private void OnChatInputSubmit(string text)

        {

            if (string.IsNullOrEmpty(text)) return;

            // Sadece Enter ile submit olduğunda işle (New Input System)

            var kb = UnityEngine.InputSystem.Keyboard.current;

            if (kb == null || (!kb.enterKey.wasPressedThisFrame && !kb.numpadEnterKey.wasPressedThisFrame))

                return;

            byte channel = _chatMode;

            string msg = text;

            // C++ satır 182-217: prefix parse

            if (text.Length > 1)

            {

                switch (text[0])

                {

                    case '/':

                        // C++ GameProcMain.cpp ParseChattingCommand birebir port

                        // Satır 5745-5873: '/' prefix sonrası komut string'ini parse eder

                        ParseChattingCommand(text);

                        _chatInputField.text = "";

                        return;

                                        case '@':

                        // C++ N3_CHAT_PRIVATE - whisper

                        channel = 2;

                        int spaceIdx = text.IndexOf(' ');

                        if (spaceIdx > 1)

                        {

                            string targetName = text.Substring(1, spaceIdx - 1);

                            msg = text.Substring(spaceIdx + 1).TrimStart();

                            // C++ MsgSend_ChatSelectTarget(szID)

                            KONetworkManager.Instance?.SendChatSelectTarget(targetName);

                        }

                        else if (text.Length > 1)

                        {

                            string targetName = text.Substring(1).Trim();

                            msg = "";

                            KONetworkManager.Instance?.SendChatSelectTarget(targetName);

                        }

                        break;

                    case '#':

                        channel = 3; // N3_CHAT_PARTY

                        msg = text.Substring(1);

                        break;

                    case '$':

                        channel = 6; // N3_CHAT_CLAN

                        msg = text.Substring(1);

                        break;

                    case '!':

                        channel = 5; // N3_CHAT_SHOUT

                        msg = text.Substring(1);

                        break;

                }

            }

            // C++ birebir: if (szChat.size() >= 128) return; (GameProcMain.cpp:1553)

            if (!string.IsNullOrEmpty(msg) && msg.Length < 128)

            {

                using var packet = new KOPacketWriter(WizOpcode.WIZ_CHAT);

                packet.WriteByte(channel);

                packet.WriteString(msg);

                KONetworkManager.Instance?.SendPacket(packet);

                // C++ birebir: GameProcMain.cpp satır 2311-2319

                // Balon SADECE Normal ve Shout kanallarında gösterilir:

                //   if (N3_CHAT_NORMAL == eCM || N3_CHAT_SHOUT == eCM)

                //       pBPC->BalloonStringSet(szChat, crChat);

                if (channel == 1 || channel == 5) // N3_CHAT_NORMAL=1 veya N3_CHAT_SHOUT=5

                {

                    var player = UnityEngine.GameObject.FindGameObjectWithTag("Player");

                    if (player == null) player = UnityEngine.GameObject.Find("Player");

                    if (player != null)

                    {

                        var fn = player.GetComponent<EntropyOnline.World.FloatingName>();

                        if (fn != null)

                        {

                            // C++ birebir: szChat = szName + " : " + szMsg (cpp:2217)

                            var gm = GameManager.Instance;

                            string balloonText = (gm != null && !string.IsNullOrEmpty(gm.CharacterName))

                                ? $"{gm.CharacterName} : {msg}"

                                : msg;

                            // C++ birebir: BalloonStringSet(szChat, crChat) — renk kanal bazlı

                            // Normal = 0xFFFFFFFF (beyaz), Shout = 0xFFF86605 (turuncu)

                            Color balloonColor = (channel == 5)

                                ? new Color(0.973f, 0.4f, 0.02f, 1f)  // Shout: #F86605

                                : Color.white;                          // Normal: #FFFFFF

                            fn.ShowChatBubble(balloonText, balloonColor);

                        }

                    }

                }

            }

            _chatInputField.text = "";

        }

        /// <summary>

        /// Sunucudan gelen chat mesajını UI'da göster.

        /// C++ UIChat.cpp AddChatMsg() satır 305-392 birebir:

        /// Channel filtrelemesi + m_ChatBuffer'a ekleme + line wrap + scroll.

        /// Mobilde: text0'a doğrudan string ekleme (basitleştirilmiş — scroll yok).

        /// </summary>

        /// C++ UIChat.cpp AddChatMsg(eCM, szChat, crChat) birebir:

        /// szChat zaten birleştirilmiş "name : msg" formatında gelir.

        /// </summary>

        public void AddChatMessage(byte channel, string szChat)

        {

            if (_chatOutputText == null) return;

            // C++ UIChat.cpp AddChatMsg satır 310-335: kanal filtreleme birebir

            switch (channel)

            {

                case 1: // N3_CHAT_NORMAL

                    if (!_bChatNormal) return;

                    break;

                case 2: // N3_CHAT_PRIVATE

                    if (!_bChatPrivate) return;

                    break;

                case 3: // N3_CHAT_PARTY

                case 4: // N3_CHAT_FORCE

                    if (!_bChatParty) return;

                    break;

                case 6: // N3_CHAT_CLAN

                    if (!_bChatClan) return;

                    break;

                case 5: // N3_CHAT_SHOUT

                    if (!_bChatShout) return;

                    break;

            }

            // C++ D3DCOLOR renk seçimi — GameProcMain.cpp:2233-2263 birebir

            // D3DCOLOR_ARGB → RGB hex dönüşümü

            string colorHex = channel switch

            {

                1 => "FFFFFF",  // N3_CHAT_NORMAL: D3DCOLOR_ARGB(255,255,255,255) — cpp:2236

                2 => "80FFFF",  // N3_CHAT_PRIVATE: D3DCOLOR_ARGB(255,128,255,255) — cpp:2240

                3 => "00C0C0",  // N3_CHAT_PARTY: D3DCOLOR_ARGB(255,0,192,192) — cpp:2245

                4 => "00C0C0",  // N3_CHAT_FORCE: D3DCOLOR_ARGB(255,0,192,192) — cpp:2244 (PARTY ile aynı)

                5 => "F86605",  // N3_CHAT_SHOUT: D3DCOLOR_ARGB(255,0xf8,0x66,0x05) — cpp:2251

                6 => "00FF00",  // N3_CHAT_CLAN: D3DCOLOR_ARGB(255,0,255,0) — cpp:2255

                7 => "FFFF00",  // N3_CHAT_PUBLIC: D3DCOLOR_ARGB(255,255,255,0) — cpp:2258

                8 => "FFFF00",  // N3_CHAT_WAR: D3DCOLOR_ARGB(255,255,255,0) — cpp:2259

                9 => "FFFF00",  // N3_CHAT_TITLE: D3DCOLOR_ARGB(255,255,255,0) — cpp:2260

                11 => "FFFF00", // N3_CHAT_CONTINUE: D3DCOLOR_ARGB(255,255,255,0) — cpp:2261

                _ => "FFFFFF"   // default: crChat = 0xffffffff — cpp:2232

            };

            string formatted = $"<color=#{colorHex}>{szChat}</color>";

            ChatLineEntry entry = new ChatLineEntry();

            entry.channel = channel;

            entry.formattedText = formatted;

            _chatLines.Add(entry);

            // C++ MAX_CHAT_LINES = 255 sınırı

            while (_chatLines.Count > MAX_CHAT_LINES)

                _chatLines.RemoveAt(0);

            RebuildChatVisibleText();

        }

        private void RebuildChatVisibleText()
        {
            _chatDirty = true;
        }

        private void RebuildChatVisibleTextImmediate()
        {
            if (_chatOutputText == null) return;

            var sb = new System.Text.StringBuilder();

            var filtered = new List<string>();

            for (int i = 0; i < _chatLines.Count; i++)

            {

                var entry = _chatLines[i];

                bool show = false;

                if (_chatMode == 1) // ALL

                {

                    show = true;

                }

                else if (_chatMode == 3) // PARTY

                {

                    show = (entry.channel == 3 || entry.channel == 4);

                }

                else if (_chatMode == 5) // SHOUT

                {

                    show = (entry.channel == 5);

                }

                else if (_chatMode == 6) // CLAN

                {

                    show = (entry.channel == 6);

                }

                else if (_chatMode == 10) // NOTICES

                {

                    show = (entry.channel == 9 || entry.channel == 11 || entry.channel == 8 || entry.channel == 7);

                }

                if (show)

                {

                    filtered.Add(entry.formattedText);

                }

            }

            int showCount = Mathf.Min(filtered.Count, 50);

            for (int i = filtered.Count - showCount; i < filtered.Count; i++)

            {

                sb.AppendLine(filtered[i]);

            }

            _chatOutputText.text = sb.ToString();

            _chatOutputText.supportRichText = true;

            if (_chatScrollRect != null)

            {

                // Canvas.ForceUpdateCanvases(); // REMOVED FOR PERFORMANCE (Fixes minor healing spam lag)

                _chatScrollRect.verticalNormalizedPosition = 0f;

            }

        }

