        /// <summary>

        /// C++ UIChat.cpp SetNoticeTitle(szChat, crChat) satır 403-425 birebir.

        /// N3_CHAT_TITLE(9) kanalı ile gelen sunucu bildirimini ekranın üstünde

        /// kalıcı olarak gösterir. N3_CHAT_TITLE_DELETE(10) ile temizlenir.

        /// Widget: KO_TitleNotice (CreateTitleNoticeWidget ile oluşturulur)

        /// </summary>

        public void SetTitleNotice(string notice)

        {

            if (string.IsNullOrEmpty(notice))

            {

                if (_uiNoticeBar != null && _uiNoticeBar.activeSelf)

                {

                    _noticeFadeDirection = -1f;

                }

                else

                {

                    if (_uiNoticeBarText != null) _uiNoticeBarText.text = "";

                    _isNoticeBarActive = false;

                }

                // Fallback for old widget

                if (_titleNoticeText != null)

                {

                    _titleNoticeText.text = "";

                    _titleNoticeText.transform.parent.gameObject.SetActive(false);

                }

                return;

            }

            // Fallback old widget (keep updated but hidden or passive)

            if (_titleNoticeText != null)

            {

                _titleNoticeText.text = notice;

            }

            // Setup new Notice Bar

            if (_uiNoticeBar != null && _uiNoticeBarText != null && _uiNoticeBarTextRT != null)

            {

                _uiNoticeBarText.text = notice;

                _uiNoticeBarText.alignment = TextAnchor.MiddleCenter;

                float containerWidth = _uiNoticeBar.GetComponent<RectTransform>().rect.width;

                _uiNoticeBarTextRT.sizeDelta = new Vector2(containerWidth, 24f);

                _uiNoticeBarTextRT.anchoredPosition = new Vector2(0f, 0f);

                _uiNoticeBar.SetActive(true);

                _isNoticeBarActive = true;

                _isNoticeScrolling = false;

                _noticeActiveTimer = 6f; // Show for 6 seconds

                _noticeFadeDirection = 1f; // Fade in

                if (_uiNoticeBarCG != null && _uiNoticeBarCG.alpha < 0.1f)

                {

                    _uiNoticeBarCG.alpha = 0f;

                }

            }

        }

        public void SetContinueNotice(string notice)

        {

            if (string.IsNullOrEmpty(notice))

            {

                if (_uiNoticeBar != null && _uiNoticeBar.activeSelf)

                {

                    _noticeFadeDirection = -1f;

                }

                else

                {

                    if (_uiNoticeBarText != null) _uiNoticeBarText.text = "";

                    _isNoticeBarActive = false;

                }

                // Fallback old widget

                _continueNoticeMsg = "";

                _continueScrollOffset = 0f;

                if (_continueNoticeText != null)

                {

                    _continueNoticeText.text = "";

                    _continueNoticeText.transform.parent.gameObject.SetActive(false);

                }

                return;

            }

            // Fallback old widget

            _continueNoticeMsg = notice;

            _continueScrollOffset = 0f;

            if (_continueNoticeText != null)

            {

                _continueNoticeText.text = notice;

            }

            // Setup new Notice Bar

            if (_uiNoticeBar != null && _uiNoticeBarText != null && _uiNoticeBarTextRT != null)

            {

                _uiNoticeBarText.text = notice;

                _uiNoticeBarText.alignment = TextAnchor.MiddleLeft;

                float textWidth = _uiNoticeBarText.preferredWidth;

                _uiNoticeBarTextRT.sizeDelta = new Vector2(textWidth, 24f);

                float containerWidth = _uiNoticeBar.GetComponent<RectTransform>().rect.width;

                _uiNoticeBarTextRT.anchoredPosition = new Vector2(containerWidth, 0f);

                _uiNoticeBar.SetActive(true);

                _isNoticeBarActive = true;

                _isNoticeScrolling = true;

                _noticeFadeDirection = 1f; // Fade in

                if (_uiNoticeBarCG != null && _uiNoticeBarCG.alpha < 0.1f)

                {

                    _uiNoticeBarCG.alpha = 0f;

                }

            }

        }

