        /// <summary>

        /// C++ UIStateBar.cpp Load() satır 191-200 birebir:

        /// m_pGroup_MiniMap = GetChildByID("Group_MiniMap");

        /// m_pImage_Map = m_pGroup_MiniMap->GetChildByID<CN3UIImage>("Img_MiniMap");

        /// m_pGroup_MiniMap->SetVisible(false);

        /// </summary>

        private void BindMiniMap(Transform root)

        {

            var groupTransform = KOUIRenderer.FindChildByID(root, "Group_MiniMap");

            if (groupTransform != null)

            {

                _miniMapGroup = groupTransform.gameObject;

                // Reparent to Canvas so we can anchor it to the top-right corner of the screen

                if (_canvas != null)

                {

                    _miniMapGroup.transform.SetParent(_hudContainer != null ? _hudContainer.transform : _canvas.transform, false);

                    var rt = _miniMapGroup.GetComponent<RectTransform>();

                    if (rt != null)

                    {

                        rt.anchorMin = new Vector2(1f, 1f); // top-right anchor

                        rt.anchorMax = new Vector2(1f, 1f);

                        rt.pivot = new Vector2(1f, 1f);     // top-right pivot

                        rt.anchoredPosition = Vector2.zero; // flush with top-right corner

                    }

                }

                // C++ satır 195: default hidden

                _miniMapGroup.SetActive(false);

                // C++ satır 197: Img_MiniMap

                var imgTransform = KOUIRenderer.FindChildByID(groupTransform, "Img_MiniMap");

                if (imgTransform != null)

                {

                    _miniMapImage = imgTransform.GetComponent<RawImage>();

                    if (_miniMapImage == null)

                    {

                        imgTransform.gameObject.AddComponent<CanvasRenderer>();

                        _miniMapImage = imgTransform.gameObject.AddComponent<RawImage>();

                    }

                    // Create player indicator in the center of minimap

                    var markerGO = new GameObject("MiniMapPlayerMarker", typeof(RectTransform));

                    markerGO.transform.SetParent(imgTransform, false);

                    _miniMapMarker = markerGO.GetComponent<RectTransform>();

                    _miniMapMarker.anchorMin = new Vector2(0.5f, 0.5f);

                    _miniMapMarker.anchorMax = new Vector2(0.5f, 0.5f);

                    _miniMapMarker.pivot = new Vector2(0.5f, 0.5f);

                    _miniMapMarker.anchoredPosition = Vector2.zero;

                    _miniMapMarker.sizeDelta = new Vector2(24f, 24f);

                    var markerTxt = markerGO.AddComponent<Text>();

                    markerTxt.font = GetSafeFont(18);

                    markerTxt.fontSize = 18;

                    markerTxt.fontStyle = FontStyle.Bold;

                    markerTxt.alignment = TextAnchor.MiddleCenter;

                    markerTxt.color = new Color(0.9f, 0.2f, 0.2f, 1.0f);

                    markerTxt.text = "▲";

                    var markerOutline = markerGO.AddComponent<Outline>();

                    markerOutline.effectColor = Color.black;

                    markerOutline.effectDistance = new Vector2(1f, 1f);

                }

            }

        }

