        public void ToggleZoneMap()

        {

            if (_zoneMapGroup != null)

            {

                bool active = !_zoneMapGroup.activeSelf;

                _zoneMapGroup.SetActive(active);

                if (active)

                {

                    UpdateZoneMap();

                    if (_zoneMapTitle != null)

                    {

                        var gm = EntropyOnline.Core.GameManager.Instance;

                        _zoneMapTitle.text = gm != null ? $"Bölge Haritası (Zone {gm.CurrentZoneId})" : "Bölge Haritası";

                    }

                }

            }

        }

        public void UpdateZoneMap()

        {

            if (_zoneMapGroup == null || !_zoneMapGroup.activeSelf) return;

            if (_miniMapImage == null || _miniMapImage.texture == null) return;

            if (_miniMapSizeX <= 0 || _miniMapSizeZ <= 0) return;

            var gm = EntropyOnline.Core.GameManager.Instance;

            if (gm == null) return;

            if (_zoneMapImage != null && _zoneMapImage.texture != _miniMapImage.texture)

            {

                _zoneMapImage.texture = _miniMapImage.texture;

            }

            float pctX = gm.PlayerPosX / _miniMapSizeX;

            float pctZ = gm.PlayerPosZ / _miniMapSizeZ;

            if (_zoneMapMarker != null)

            {

                var rect = _zoneMapImage.rectTransform.rect;

                float xOffset = (pctX - 0.5f) * rect.width;

                float yOffset = (pctZ - 0.5f) * rect.height;

                _zoneMapMarker.anchoredPosition = new Vector2(xOffset, yOffset);

                if (_playerTransform == null)

                {

                    var playerObj = GameObject.FindGameObjectWithTag("Player");

                    if (playerObj == null) playerObj = GameObject.Find("Player");

                    if (playerObj != null)

                    {

                        _playerTransform = playerObj.transform;

                    }

                }

                if (_playerTransform != null)

                {

                    float rotY = _playerTransform.eulerAngles.y;

                    _zoneMapMarker.localRotation = Quaternion.Euler(0f, 0f, -rotY);

                }

            }

        }

