                _msgOutputText.text = "";

                _msgOutputText.supportRichText = true;

                _msgOutputText.fontSize = 14;

                _msgOutputText.verticalOverflow = VerticalWrapMode.Overflow;

                _msgOutputText.horizontalOverflow = HorizontalWrapMode.Wrap;

                // C++ birebir: UIMessageWnd.cpp CreateLines() + m_pScrollbar

                // Hiyerarşi: parentRT(ScrollRect) → viewport(RectMask2D) → textRT(Content+CSF)

                SetupMsgOutputScrollRect(_msgOutputText);

            }

            // C++ UIMessageWnd.cpp satır 132: btn_off → toggle

            var btnFold = KOUIRenderer.FindChildButton(root, "btn_off");

            if (btnFold != null)

            {

                btnFold.onClick.RemoveAllListeners();

                btnFold.onClick.AddListener(() =>

                {

                    ToggleMsgOutputFoldState(root);

                });

            }

            // Bilgi panelini yeniden yapılandır ve özgün arka plan uygula

            RestructureMsgOutputPanel(root);

