            // ile set eder, N3_CHAT_CONTINUE_DELETE(12) ile temizler.

            // ================================================================

            CreateContinueNoticeWidget();

        }

        private void BindMsgOutputPrefab(Transform root)

        {

            CleanLegacyPrefabImages(root);

            _msgOutputText = KOUIRenderer.FindChildText(root, "text_message");

            var rt = root.GetComponent<RectTransform>();

            if (rt != null && rt.rect.width > 0 && rt.rect.height > 0)

            {

                _msgOutputWidth = rt.rect.width;

                _msgOutputHeight = rt.rect.height;

            }

            if (_msgOutputText != null)

            {

                _msgOutputText.text = "";

                _msgOutputText.supportRichText = true;

                _msgOutputText.fontSize = 14;

            }

            _msgOutputScrollRect = root.GetComponentInChildren<ScrollRect>(true);

            if (_msgOutputScrollRect == null && _msgOutputText != null)

            {

                SetupMsgOutputScrollRect(_msgOutputText);

            }

            var btnFold = KOUIRenderer.FindChildButton(root, "btn_off");

            if (btnFold != null)

            {

                btnFold.onClick.RemoveAllListeners();

                btnFold.onClick.AddListener(() => ToggleMsgOutputFoldState(root));

            }

            UpdateMsgOutputPanelLayout(root, _msgOutputWidth, _msgOutputHeight);

            // Add resize handle

            AddResizeHandle(root, new Vector2(130f, 100f), new Vector2(240f, 400f), (newWidth, newHeight) =>

            {

                _msgOutputWidth = newWidth;

                _msgOutputHeight = newHeight;

                UpdateMsgOutputPanelLayout(root, newWidth, newHeight);

                RearrangePanelsPosition();

            });

            RearrangePanelsPosition();

