        private void RestructureMsgOutputPanel(Transform root)

        {

            if (IsModernPrefab(root)) return;

            // Debug hierarchy print to console



            // 1. Orijinal kaba arka plan görsellerini ve dekorasyon şeritlerini en başta yok et (Böylece yeni oluşturulacak sekmeleri etkilemez)

/* Loop Removed */

/* Loop Removed */

            // 2. Orijinal "Information" statik metin başlıklarını temiz bir şekilde gizle

            foreach (Transform child in root)

            {

                if (child.name.StartsWith("ui_String_"))

                {

                    var textComp = child.GetComponent<Text>();

                    if (textComp != null && textComp.text == "Information")

                    {

                        child.gameObject.SetActive(false);

                    }

                }

            }

            // 2.5 Scrollbar üzerindeki eski yukarı/aşağı ok butonlarını tamamen yok et

            var scrollTransform = root.Find("scroll");

            if (scrollTransform != null)

            {

                var scrollBtns = scrollTransform.GetComponentsInChildren<Button>(true);

                foreach (var sb in scrollBtns)

                {

                    DestroyImmediate(sb.gameObject);

                }

            }

            // 3. Panel genişliğini ayarla (160f)

            var panelRT = root.GetComponent<RectTransform>();

            if (panelRT != null)

            {

                panelRT.sizeDelta = new Vector2(160f, panelRT.sizeDelta.y);

            }

            var rootImg = root.GetComponent<Image>();

            if (rootImg == null) rootImg = root.gameObject.AddComponent<Image>();

            if (rootImg != null)

            {

                rootImg.color = Color.white;

                rootImg.raycastTarget = true; // Dokunmaları yakala

            }

            // 4. İlk katlama durumunu ve görsellerini uygula

            ApplyMsgOutputFoldState(root);

            // 5. Çift eksenli boyutlandırma tutamacını ekle (Genişlik: 130-240, Yükseklik: 100-400)

            AddResizeHandle(root, new Vector2(130f, 100f), new Vector2(240f, 400f), (newWidth, newHeight) =>

            {

                _msgOutputWidth = newWidth;

                _msgOutputHeight = newHeight;

                UpdateMsgOutputPanelLayout(root, newWidth, newHeight);

                RearrangePanelsPosition();

            });

            PrintFullHierarchy(root, "MSGOUTPUT", "");

        }

        private void PrintFullHierarchy(Transform t, string panelName, string indent)

        {

            var txtComp = t.GetComponent<Text>();

            string txtVal = txtComp != null ? txtComp.text : "";

            RectTransform rt = t.GetComponent<RectTransform>();

            Vector2 anchoredPos = rt != null ? rt.anchoredPosition : Vector2.zero;

            Vector2 sizeDelta = rt != null ? rt.sizeDelta : Vector2.zero;

            foreach (Transform child in t)

            {

                PrintFullHierarchy(child, panelName, indent + "  ");

            }

        }

        private bool _chatFolded = false;

        private float _chatWidth = 370f;

        private float _chatHeight = 140f;

        private float _msgOutputWidth = 160f;

        private float _msgOutputHeight = 140f;

        private void ToggleChatFoldState(Transform root)

        {

            _chatFolded = !_chatFolded;

            ApplyChatFoldState(root);

        }

        private void ApplyChatFoldState(Transform root)

        {

            var panelRT = root.GetComponent<RectTransform>();

            var btnFold = KOUIRenderer.FindChildButton(root, "btn_off");

            if (_chatFolded)

            {

                // Hide all children except btn_off

                foreach (Transform child in root)

                {

                    if (child.name == "btn_off") continue;

                    child.gameObject.SetActive(false);

                }

                var rootImg = root.GetComponent<Image>();

                if (rootImg != null)

                {

                    rootImg.color = Color.clear;

                    rootImg.sprite = null;

                }

                var bgTransform = root.Find("Chat_Background");

                if (bgTransform != null) bgTransform.gameObject.SetActive(false);

                var headerTransform = root.Find("Chat_Header");

                if (headerTransform != null) headerTransform.gameObject.SetActive(false);

                var resizeHandle = root.Find("ResizeHandle");

                if (resizeHandle != null) resizeHandle.gameObject.SetActive(false);

            }

            else

            {

                // Show only the correct active tabs and inputs

                string[] activeElements = { "btn_normal", "btn_shout", "btn_party_force", "btn_knights", "btn_notices", "edit0", "Chat_ScrollContainer" };

                foreach (var name in activeElements)

                {

                    var t = root.Find(name);

                    if (t != null) t.gameObject.SetActive(true);

                }

                // Hide the unused tabs and checkboxes

                string[] inactiveElements = { "btn_private", "btn_union", "btn_clan", "btn_check_normal", "btn_check_shout", "btn_check_party_force", "btn_check_clan", "btn_check_union", "btn_check_private", "btn_check_notices" };

                foreach (var name in inactiveElements)

                {

                    var t = root.Find(name);

                    if (t != null) t.gameObject.SetActive(false);

                }

                var rootImg = root.GetComponent<Image>();

                if (rootImg != null)

                {

                    rootImg.color = Color.clear;

                    rootImg.sprite = null;

                }

                // 1. Üst koyu sekme şeridini (Chat_Header) oluştur/bul

                var headerTransform = root.Find("Chat_Header");

                GameObject headerGO;

                if (headerTransform == null)

                {

                    headerGO = new GameObject("Chat_Header");

                    headerGO.transform.SetParent(root, false);

                    headerGO.transform.SetAsFirstSibling();

                }

                else

                {

                    headerGO = headerTransform.gameObject;

                }

                headerGO.SetActive(true);

                var headerImg = headerGO.GetComponent<Image>();

                if (headerImg == null) headerImg = headerGO.AddComponent<Image>();

                headerImg.enabled = true;

                headerImg.sprite = GetSkillThemeRoundedRectSprite("chat_header_bg", 370, 24, 0,

                    new Color(0.08f, 0.06f, 0.05f, 0.95f), // Koyu bronz zemin

                    new Color(0.5f, 0.4f, 0.18f, 0.7f),    // Altın sarısı çerçeve

                    1

                );

                headerImg.color = Color.white;

                var headerRT = headerGO.GetComponent<RectTransform>();

                if (headerRT != null)

                {

                    headerRT.anchorMin = new Vector2(0, 1);

                    headerRT.anchorMax = new Vector2(0, 1);

                    headerRT.pivot = new Vector2(0, 1);

                    headerRT.anchoredPosition = Vector2.zero; // En üstte

                    headerRT.sizeDelta = new Vector2(370f, 24f); // 370px genişlik, 24px yükseklik

                }

                // 2. Şeffaf mesaj kutusunu (Chat_Background) oluştur/bul

                var bgTransform = root.Find("Chat_Background");

                GameObject bgGO;

                if (bgTransform == null)

                {

                    bgGO = new GameObject("Chat_Background");

                    bgGO.transform.SetParent(root, false);

                    bgGO.transform.SetSiblingIndex(1);

                }

                else

                {

                    bgGO = bgTransform.gameObject;

                }

                bgGO.SetActive(true);

                var bgImg = bgGO.GetComponent<Image>();

                if (bgImg == null) bgImg = bgGO.AddComponent<Image>();

                bgImg.enabled = true;

                bgImg.raycastTarget = true;

                bgImg.color = Color.white;

                var bgRT = bgGO.GetComponent<RectTransform>();

                if (bgRT != null)

                {

                    bgRT.anchorMin = new Vector2(0, 1);

                    bgRT.anchorMax = new Vector2(0, 1);

                    bgRT.pivot = new Vector2(0, 1);

                    bgRT.anchoredPosition = new Vector2(0f, -24f);

                }

                // ResizeHandle göster

                var resizeHandle = root.Find("ResizeHandle");

                if (resizeHandle != null) resizeHandle.gameObject.SetActive(true);

                UpdateChatPanelLayout(root, _chatWidth, _chatHeight);

            }

            // Yeniden yerleşimi tetikle

            RearrangePanelsPosition();

        }

        private void UpdateChatPanelLayout(Transform root, float width, float height)

        {

            var panelRT = root.GetComponent<RectTransform>();

            if (panelRT != null)

            {

                panelRT.sizeDelta = new Vector2(width, height);

            }

            var header = root.Find("Chat_Header");

            if (header != null)

            {

                var headerRT = header.GetComponent<RectTransform>();

                if (headerRT != null)

                {

                    headerRT.sizeDelta = new Vector2(width, 24f);

                }

                var headerImg = header.GetComponent<Image>();

                if (headerImg != null)

                {

                    headerImg.sprite = GetSkillThemeRoundedRectSprite("chat_header_bg_" + (int)width, (int)width, 24, 0,

                        new Color(0.08f, 0.06f, 0.05f, 0.95f), // Koyu bronz zemin

                        new Color(0.5f, 0.4f, 0.18f, 0.7f),    // Altın sarısı çerçeve

                        1

                    );

                }

            }

            var bg = root.Find("Chat_Background");

            if (bg != null)

            {

                var bgRT = bg.GetComponent<RectTransform>();

                if (bgRT != null)

                {

                    // Şeffaf bronz kutu sekmelerin bittiği yerden (-24f) başlar ve yazı çubuğunun 0px üzerinde (-height + 20f) biter.

                    // Toplam yükseklik = height - 24f - 20f = height - 44f

                    bgRT.sizeDelta = new Vector2(width, height - 44f);

                }

                var bgImg = bg.GetComponent<Image>();

                if (bgImg != null)

                {

                    bgImg.sprite = GetSkillThemeRoundedRectSprite("chat_panel_bg_" + (int)width + "_" + (int)(height - 44f) + "_0", (int)width, (int)(height - 44f), 0,

                        new Color(0.12f, 0.09f, 0.07f, 0.60f), // Şeffaflığı dengelenmiş koyu bronz

                        new Color(0.5f, 0.4f, 0.18f, 0.8f),    // Altın sarısı çerçeve

                        1

                    );

                }

            }

            var scroll = root.Find("Chat_ScrollContainer");

            if (scroll != null)

            {

                var scrollRT = scroll.GetComponent<RectTransform>();

                if (scrollRT != null)

                {

                    // Mesaj kaydırma alanı bronz kutunun içine sığar (alt sınırı tam olarak yazı çubuğunun 0px üzerindedir).

                    // Toplam yükseklik = height - 34f (üst başlangıç) - 20f (alt bitiş farkı) = height - 54f

                    scrollRT.sizeDelta = new Vector2(width - 30f, height - 54f);

                }

            }

            var editObj = root.Find("edit0")?.gameObject;

            if (editObj != null)

            {

                var rtEdit = editObj.GetComponent<RectTransform>();

                if (rtEdit != null)

                {

                    // Yazı çubuğu dikey yüksekliği 20f, genişliği width - 20f yapıldı ve sola hizalandı (X = 0f) - en alt çizgiyle sıfırlandı (-height + 20f)

                    rtEdit.anchoredPosition = new Vector2(0f, -height + 20f);

                    rtEdit.sizeDelta = new Vector2(width - 20f, 20f);

                }

                var editImg = editObj.GetComponent<Image>();

                if (editImg != null)

                {

                    editImg.sprite = GetSkillThemeRoundedRectSprite("chat_input_bg_" + (int)(width - 20f) + "_20_0", (int)(width - 20f), 20, 0,

                        new Color(0.04f, 0.03f, 0.02f, 0.95f), // Çok koyu bronz/siyah

                        new Color(0.5f, 0.4f, 0.18f, 0.6f),    // Mat altın çerçeve

                        1

                    );

                    editImg.color = Color.white;

                }

            }

            var btnFold = KOUIRenderer.FindChildButton(root, "btn_off");

            if (btnFold != null)

            {

                var btnRT = btnFold.GetComponent<RectTransform>();

                if (btnRT != null)

                {

                    // Katlama butonu yazı çubuğuyla dikeyde hizalanır (-height + 20f) ve Notices sağ kenarına yaslanır (X = width - 20f)

                    btnRT.anchoredPosition = new Vector2(width - 20f, -height + 20f);

                    btnRT.sizeDelta = new Vector2(20f, 20f); // Tam kare olarak 20x20 yapıldı

                }

                SetUIElementThemeSprite(btnFold.gameObject, GetSkillThemeArrowSprite("chat_btn_off_arrow_20_20", 20, 20,

                    new Color(0.18f, 0.14f, 0.10f, 1f),

                    new Color(0.5f, 0.4f, 0.18f, 0.9f),

                    1,

                    true // Left ok (<)

                ));

            }

            // 5 adet sekme butonunu panel genişliğine tam sığacak şekilde otomatik konumlandır ve boyutlandır

            float tabWidth = width / 5f;

            string[] tabNames = { "btn_normal", "btn_shout", "btn_party_force", "btn_knights", "btn_notices" };

            for (int i = 0; i < tabNames.Length; i++)

            {

                var tab = root.Find(tabNames[i]);

                if (tab != null)

                {

                    var tabRT = tab.GetComponent<RectTransform>();

                    if (tabRT != null)

                    {

                        tabRT.anchorMin = new Vector2(0, 1);

                        tabRT.anchorMax = new Vector2(0, 1);

                        tabRT.pivot = new Vector2(0, 1);

                        tabRT.sizeDelta = new Vector2(tabWidth, 24f);

                        tabRT.anchoredPosition = new Vector2(i * tabWidth, 0f);

                    }

                }

            }

            // 6. Integrated Notice Bar creation and styling

            if (_uiNoticeBar == null)

            {

                _uiNoticeBar = new GameObject("KO_NoticeBar");

                _uiNoticeBar.transform.SetParent(root, false);

                _uiNoticeBar.AddComponent<Image>();

                _uiNoticeBar.AddComponent<RectMask2D>();

                var textGo = new GameObject("Text");

                textGo.transform.SetParent(_uiNoticeBar.transform, false);

                _uiNoticeBarText = textGo.AddComponent<Text>();

                _uiNoticeBarText.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");

                _uiNoticeBarText.fontSize = 11;

                _uiNoticeBarText.alignment = TextAnchor.MiddleLeft;

                _uiNoticeBarText.color = new Color(1f, 0.85f, 0.3f); // Golden yellow

                _uiNoticeBarText.horizontalOverflow = HorizontalWrapMode.Overflow;

                _uiNoticeBarTextRT = textGo.GetComponent<RectTransform>();

                _uiNoticeBarTextRT.anchorMin = new Vector2(0, 0);

                _uiNoticeBarTextRT.anchorMax = new Vector2(0, 1);

                _uiNoticeBarTextRT.pivot = new Vector2(0, 0.5f);

                _uiNoticeBarCG = _uiNoticeBar.AddComponent<CanvasGroup>();

                _uiNoticeBarCG.alpha = 0f;

                _uiNoticeBar.SetActive(false);

            }

            else

            {

                _uiNoticeBarCG = _uiNoticeBar.GetComponent<CanvasGroup>();

                if (_uiNoticeBarCG == null)

                {

                    _uiNoticeBarCG = _uiNoticeBar.AddComponent<CanvasGroup>();

                }

            }

            var nbRT = _uiNoticeBar.GetComponent<RectTransform>();

            if (nbRT != null)

            {

                nbRT.anchorMin = new Vector2(0, 1); // Anchored to top-left of parent (tabs are at Y = 0)

                nbRT.anchorMax = new Vector2(0, 1);

                nbRT.pivot = new Vector2(0, 0);     // Pivot at bottom-left of the bar

                nbRT.sizeDelta = new Vector2(width, 24f); // Stretch to same width, height 24px (matching tabs)

                nbRT.anchoredPosition = new Vector2(0f, 0f); // Sit exactly on top edge of parent tabs

            }

            var nbImg = _uiNoticeBar.GetComponent<Image>();

            if (nbImg != null)

            {

                nbImg.sprite = GetSkillThemeRoundedRectSprite("notice_bar_bg_" + (int)width, (int)width, 24, 0,

                    new Color(0.08f, 0.06f, 0.05f, 0.95f), // Koyu bronz zemin (matches header)

                    new Color(0.5f, 0.4f, 0.18f, 0.7f),    // Altın sarısı çerçeve

                    1

                );

                nbImg.color = Color.white;

            }

        }

        private Sprite GetChatTabIconSprite(string iconName)

        {

            int w = 12;

            int h = 12;

            Texture2D tex = new Texture2D(w, h, TextureFormat.RGBA32, false);

            tex.filterMode = FilterMode.Point;

            Color[] clearColors = new Color[w * h];

            for (int i = 0; i < clearColors.Length; i++) clearColors[i] = Color.clear;

            tex.SetPixels(clearColors);

            Color gold = new Color(0.75f, 0.62f, 0.35f, 1f);

            if (iconName == "chat")

            {

                for (int x = 2; x <= 9; x++) { tex.SetPixel(x, 9, gold); tex.SetPixel(x, 3, gold); }

                for (int y = 4; y <= 8; y++) { tex.SetPixel(1, y, gold); tex.SetPixel(10, y, gold); }

                tex.SetPixel(2, 8, gold); tex.SetPixel(9, 8, gold);

                tex.SetPixel(2, 4, gold); tex.SetPixel(9, 4, gold);

                tex.SetPixel(2, 2, gold); tex.SetPixel(3, 2, gold); tex.SetPixel(3, 3, gold);

            }

            else if (iconName == "shout")

            {

                for (int x = 2; x <= 4; x++) for (int y = 4; y <= 7; y++) tex.SetPixel(x, y, gold);

                for (int x = 5; x <= 9; x++)

                {

                    int minY = 5 - (x - 5) / 2;

                    int maxY = 6 + (x - 5) / 2;

                    for (int y = minY; y <= maxY; y++) tex.SetPixel(x, y, gold);

                }

                tex.SetPixel(3, 3, gold); tex.SetPixel(4, 3, gold);

            }

            else if (iconName == "party")

            {

                tex.SetPixel(3, 8, gold); tex.SetPixel(4, 8, gold);

                tex.SetPixel(3, 7, gold); tex.SetPixel(4, 7, gold);

                for (int x = 1; x <= 6; x++) tex.SetPixel(x, 4, gold);

                for (int x = 2; x <= 5; x++) tex.SetPixel(x, 5, gold);

                tex.SetPixel(7, 9, gold); tex.SetPixel(8, 9, gold);

                tex.SetPixel(7, 8, gold); tex.SetPixel(8, 8, gold);

                for (int x = 5; x <= 10; x++) tex.SetPixel(x, 5, gold);

                for (int x = 6; x <= 9; x++) tex.SetPixel(x, 6, gold);

            }

            else if (iconName == "clan")

            {

                for (int x = 2; x <= 9; x++) tex.SetPixel(x, 9, gold);

                for (int y = 4; y <= 8; y++) { tex.SetPixel(1, y, gold); tex.SetPixel(10, y, gold); }

                tex.SetPixel(2, 3, gold); tex.SetPixel(9, 3, gold);

                tex.SetPixel(3, 2, gold); tex.SetPixel(8, 2, gold);

                tex.SetPixel(4, 1, gold); tex.SetPixel(7, 1, gold);

                tex.SetPixel(5, 0, gold); tex.SetPixel(6, 0, gold);

            }

            else if (iconName == "notices")

            {

                for (int y = 1; y <= 10; y++) { tex.SetPixel(2, y, gold); tex.SetPixel(9, y, gold); }

                for (int x = 3; x <= 8; x++) { tex.SetPixel(x, 1, gold); tex.SetPixel(x, 10, gold); }

                tex.SetPixel(5, 11, gold); tex.SetPixel(6, 11, gold);

                tex.SetPixel(4, 7, gold); tex.SetPixel(5, 7, gold); tex.SetPixel(6, 7, gold); tex.SetPixel(7, 7, gold);

                tex.SetPixel(4, 4, gold); tex.SetPixel(5, 4, gold); tex.SetPixel(6, 4, gold); tex.SetPixel(7, 4, gold);

            }

            tex.Apply();

            return Sprite.Create(tex, new Rect(0, 0, w, h), new Vector2(0.5f, 0.5f));

        }

        private void AddIconToButton(GameObject btnObj, Sprite iconSprite)

        {

            if (btnObj == null || iconSprite == null) return;

            // 1. Butona yatay otomatik hizalama bileşeni (HorizontalLayoutGroup) ekle veya yapılandır

            var layout = btnObj.GetComponent<HorizontalLayoutGroup>();

            if (layout == null) layout = btnObj.AddComponent<HorizontalLayoutGroup>();

            layout.childAlignment = TextAnchor.MiddleCenter;

            layout.spacing = 4f;

            // Layout grubunun hem yatay hem dikey hizalamayı tam yönetmesini sağlıyoruz

            layout.childControlWidth = true;

            layout.childControlHeight = true;

            layout.childForceExpandWidth = false;

            layout.childForceExpandHeight = false;

            layout.padding = new RectOffset(0, 0, 0, 0);

            var iconTransform = btnObj.transform.Find("TabIcon");

            GameObject iconGO;

            if (iconTransform == null)

            {

                iconGO = new GameObject("TabIcon");

                iconGO.transform.SetParent(btnObj.transform, false);

            }

            else

            {

                iconGO = iconTransform.gameObject;

            }

            iconGO.layer = btnObj.layer;

            var img = iconGO.GetComponent<Image>();

            if (img == null) img = iconGO.AddComponent<Image>();

            img.enabled = true;

            img.sprite = iconSprite;

            img.color = Color.white;

            img.raycastTarget = false;

            // Layout element ekleyerek simgenin boyutunu 12x12 olarak layout grubuna bildiriyoruz

            var layoutElement = iconGO.GetComponent<LayoutElement>();

            if (layoutElement == null) layoutElement = iconGO.AddComponent<LayoutElement>();

            layoutElement.minWidth = 12f;

            layoutElement.minHeight = 12f;

            layoutElement.preferredWidth = 12f;

            layoutElement.preferredHeight = 12f;

            var iconRT = iconGO.GetComponent<RectTransform>();

            if (iconRT != null)

            {

                iconRT.sizeDelta = new Vector2(12f, 12f);

            }

            var txt = btnObj.GetComponentInChildren<Text>(true);

            if (txt != null)

            {

                var txtRT = txt.GetComponent<RectTransform>();

                if (txtRT != null)

                {

                    float prefWidth = txt.preferredWidth;

                    if (prefWidth <= 0)

                    {

                        prefWidth = txt.text.Length * 6f; // Fallback

                    }

                    // Layout element ekleyerek yazının boyutunu layout grubuna bildiriyoruz

                    var txtLayout = txt.gameObject.GetComponent<LayoutElement>();

                    if (txtLayout == null) txtLayout = txt.gameObject.AddComponent<LayoutElement>();

                    txtLayout.minWidth = prefWidth;

                    txtLayout.minHeight = 24f;

                    txtLayout.preferredWidth = prefWidth;

                    txtLayout.preferredHeight = 24f;

                    txtRT.sizeDelta = new Vector2(prefWidth, 24f);

                    txt.alignment = TextAnchor.MiddleCenter;

                }

                iconGO.transform.SetSiblingIndex(0);

                txt.transform.SetSiblingIndex(1);

            }

        }

        private bool _msgOutputFolded = false;

        private void ToggleMsgOutputFoldState(Transform root)

        {

            _msgOutputFolded = !_msgOutputFolded;

            ApplyMsgOutputFoldState(root);

        }

        private void ApplyMsgOutputFoldState(Transform root)

        {

            var panelRT = root.GetComponent<RectTransform>();

            var scroll = root.Find("scroll")?.gameObject;

            var container = root.Find("MsgOutput_ScrollContainer")?.gameObject;

            var btnFold = KOUIRenderer.FindChildButton(root, "btn_off");

            if (_msgOutputFolded)

            {

                if (scroll != null) scroll.SetActive(false);

                if (container != null) container.SetActive(false);

                var rootImg = root.GetComponent<Image>();

                if (rootImg != null)

                {

                    rootImg.color = Color.clear;

                }

                var resizeHandle = root.Find("ResizeHandle");

                if (resizeHandle != null) resizeHandle.gameObject.SetActive(false);

            }

            else

            {

                // Açık (Expanded) durum - Orijinal boyut ve içerik

                if (scroll != null) scroll.SetActive(true);

                if (container != null) container.SetActive(true);

                var rootImg = root.GetComponent<Image>();

                if (rootImg != null)

                {

                    rootImg.color = Color.white;

                }

                var resizeHandle = root.Find("ResizeHandle");

                if (resizeHandle != null) resizeHandle.gameObject.SetActive(true);

                UpdateMsgOutputPanelLayout(root, _msgOutputWidth, _msgOutputHeight);

            }

            // Yeniden yerleşimi tetikle

            RearrangePanelsPosition();

        }

        private void SetFoldButtonLabel(Button button, string text)

        {

            if (button == null) return;

            var textTransform = button.transform.Find("Label");

            Text textComp = null;

            if (textTransform == null)

            {

                var textGO = new GameObject("Label");

                textGO.transform.SetParent(button.transform, false);

                textComp = textGO.AddComponent<Text>();

                textComp.font = GetSafeFont(11);

                textComp.fontSize = 11;

                textComp.alignment = TextAnchor.MiddleCenter;

                textComp.color = new Color(0.9f, 0.8f, 0.6f, 0.95f); // Bronz/altın etiket yazısı

                textComp.supportRichText = true;

                var textRT = textGO.GetComponent<RectTransform>();

                if (textRT != null)

                {

                    textRT.anchorMin = Vector2.zero;

                    textRT.anchorMax = Vector2.one;

                    textRT.offsetMin = new Vector2(4, 0);

                    textRT.offsetMax = new Vector2(-4, 0);

                }

            }

            else

            {

                textComp = textTransform.GetComponent<Text>();

                textTransform.gameObject.SetActive(true);

            }

            if (textComp != null)

            {

                textComp.text = text;

            }

        }

        private void RemoveFoldButtonLabel(Button button)

        {

            if (button == null) return;

            var textTransform = button.transform.Find("Label");

            if (textTransform != null)

            {

                textTransform.gameObject.SetActive(false);

            }

        }

        private void RearrangePanelsPosition()

        {

            if (_uiChatDlg == null || _uiMsgOutput == null || _uiCmdBar == null) return;

            float bottomY = 48f;

            var chatRT = _uiChatDlg.GetComponent<RectTransform>();

            var msgRT = _uiMsgOutput.GetComponent<RectTransform>();

            if (chatRT == null || msgRT == null) return;

            // Kanvas ölçek çarpanını alıp panellere uygula (Sabit piksel boyutu için)

            float s = (_canvas != null) ? _canvas.scaleFactor : 1f;

            if (s <= 0f) s = 1f;

            chatRT.localScale = new Vector3(UIScaleMultiplier / s, UIScaleMultiplier / s, UIScaleMultiplier / s);
            msgRT.localScale = new Vector3(UIScaleMultiplier / s, UIScaleMultiplier / s, UIScaleMultiplier / s);

            var chatBtn = KOUIRenderer.FindChildButton(_uiChatDlg.transform, "btn_off");

            var msgBtn = KOUIRenderer.FindChildButton(_uiMsgOutput.transform, "btn_off");

            if (_chatFolded && _msgOutputFolded)

            {

                // SENARYO 1: İki panel de kapalı (Sol alt köşede üst üste stack)

                // Chat paneli (Üstte)

                chatRT.sizeDelta = new Vector2(60f, 20f);

                chatRT.anchoredPosition = new Vector2(2f / s, (bottomY + 22f) / s); // 20px + 2px boşluk

                if (chatBtn != null)

                {

                    var btnRT = chatBtn.GetComponent<RectTransform>();

                    if (btnRT != null)

                    {

                        btnRT.anchorMin = new Vector2(0, 1);

                        btnRT.anchorMax = new Vector2(0, 1);

                        btnRT.pivot = new Vector2(0, 1);

                        btnRT.anchoredPosition = Vector2.zero;

                        btnRT.sizeDelta = new Vector2(60f, 20f);

                    }

                    SetFoldButtonLabel(chatBtn, "Chat");

                    SetUIElementThemeSprite(chatBtn.gameObject, GetSkillThemeRoundedRectSprite("chat_btn_collapsed_60_20", 60, 20, 0,

                        new Color(0.04f, 0.03f, 0.02f, 0.95f),

                        new Color(0.5f, 0.4f, 0.18f, 0.8f),

                        1

                    ));

                }

                // Savaş Günlüğü (Altta)

                msgRT.sizeDelta = new Vector2(60f, 20f);

                msgRT.anchoredPosition = new Vector2(2f / s, bottomY / s);

                if (msgBtn != null)

                {

                    var btnRT = msgBtn.GetComponent<RectTransform>();

                    if (btnRT != null)

                    {

                        btnRT.anchorMin = new Vector2(0, 1);

                        btnRT.anchorMax = new Vector2(0, 1);

                        btnRT.pivot = new Vector2(0, 1);

                        btnRT.anchoredPosition = Vector2.zero;

                        btnRT.sizeDelta = new Vector2(60f, 20f);

                    }

                    SetFoldButtonLabel(msgBtn, "Info");

                    SetUIElementThemeSprite(msgBtn.gameObject, GetSkillThemeRoundedRectSprite("chat_btn_collapsed_60_20", 60, 20, 0,

                        new Color(0.04f, 0.03f, 0.02f, 0.95f),

                        new Color(0.5f, 0.4f, 0.18f, 0.8f),

                        1

                    ));

                }

            }

            else if (_chatFolded && !_msgOutputFolded)

            {

                // SENARYO 2: Sadece Chat kapalı, Savaş Günlüğü açık (Savaş Günlüğü solda, Chat butonu sağında)

                // Savaş Günlüğü (Solda - X = 2f)

                msgRT.sizeDelta = new Vector2(_msgOutputWidth, _msgOutputHeight);

                msgRT.anchoredPosition = new Vector2(2f / s, bottomY / s);

                if (msgBtn != null)

                {

                    var btnRT = msgBtn.GetComponent<RectTransform>();

                    if (btnRT != null)

                    {

                        btnRT.anchorMin = new Vector2(0, 1);

                        btnRT.anchorMax = new Vector2(0, 1);

                        btnRT.pivot = new Vector2(0, 1);

                        btnRT.anchoredPosition = new Vector2(_msgOutputWidth - 20f, -_msgOutputHeight + 20f);

                        btnRT.sizeDelta = new Vector2(20f, 20f);

                    }

                    RemoveFoldButtonLabel(msgBtn);

                    SetUIElementThemeSprite(msgBtn.gameObject, GetSkillThemeArrowSprite("msg_btn_off_arrow_20_20", 20, 20,

                        new Color(0.18f, 0.14f, 0.10f, 1f),

                        new Color(0.5f, 0.4f, 0.18f, 0.9f),

                        1,

                        true

                    ));

                }

                // Chat paneli (Savaş Günlüğünün sağında - X = 2f + _msgOutputWidth)

                chatRT.sizeDelta = new Vector2(60f, 20f);
                chatRT.anchoredPosition = new Vector2((2f + _msgOutputWidth * UIScaleMultiplier) / s, bottomY / s);

                if (chatBtn != null)

                {

                    var btnRT = chatBtn.GetComponent<RectTransform>();

                    if (btnRT != null)

                    {

                        btnRT.anchorMin = new Vector2(0, 1);

                        btnRT.anchorMax = new Vector2(0, 1);

                        btnRT.pivot = new Vector2(0, 1);

                        btnRT.anchoredPosition = Vector2.zero;

                        btnRT.sizeDelta = new Vector2(60f, 20f);

                    }

                    SetFoldButtonLabel(chatBtn, "Chat");

                    SetUIElementThemeSprite(chatBtn.gameObject, GetSkillThemeRoundedRectSprite("chat_btn_collapsed_60_20", 60, 20, 0,

                        new Color(0.04f, 0.03f, 0.02f, 0.95f),

                        new Color(0.5f, 0.4f, 0.18f, 0.8f),

                        1

                    ));

                }

            }

            else if (!_chatFolded && _msgOutputFolded)

            {

                // SENARYO 3: Chat açık, Savaş Günlüğü kapalı (Chat solda, Savaş Günlüğü butonu sağında)

                // Chat paneli (Solda - X = 2f)

                chatRT.sizeDelta = new Vector2(_chatWidth, _chatHeight);

                chatRT.anchoredPosition = new Vector2(2f / s, bottomY / s);

                if (chatBtn != null)

                {

                    var btnRT = chatBtn.GetComponent<RectTransform>();

                    if (btnRT != null)

                    {

                        btnRT.anchorMin = new Vector2(0, 1);

                        btnRT.anchorMax = new Vector2(0, 1);

                        btnRT.pivot = new Vector2(0, 1);

                        btnRT.anchoredPosition = new Vector2(_chatWidth - 20f, -_chatHeight + 20f);

                        btnRT.sizeDelta = new Vector2(20f, 20f);

                    }

                    RemoveFoldButtonLabel(chatBtn);

                    SetUIElementThemeSprite(chatBtn.gameObject, GetSkillThemeArrowSprite("chat_btn_off_arrow_20_20", 20, 20,

                        new Color(0.18f, 0.14f, 0.10f, 1f),

                        new Color(0.5f, 0.4f, 0.18f, 0.9f),

                        1,

                        true

                    ));

                }

                // Savaş Günlüğü (Chat'in sağında - X = 2f + _chatWidth)

                msgRT.sizeDelta = new Vector2(60f, 20f);
                msgRT.anchoredPosition = new Vector2((2f + _chatWidth * UIScaleMultiplier) / s, bottomY / s);

                if (msgBtn != null)

                {

                    var btnRT = msgBtn.GetComponent<RectTransform>();

                    if (btnRT != null)

                    {

                        btnRT.anchorMin = new Vector2(0, 1);

                        btnRT.anchorMax = new Vector2(0, 1);

                        btnRT.pivot = new Vector2(0, 1);

                        btnRT.anchoredPosition = Vector2.zero;

                        btnRT.sizeDelta = new Vector2(60f, 20f);

                    }

                    SetFoldButtonLabel(msgBtn, "Info");

                    SetUIElementThemeSprite(msgBtn.gameObject, GetSkillThemeRoundedRectSprite("chat_btn_collapsed_60_20", 60, 20, 0,

                        new Color(0.04f, 0.03f, 0.02f, 0.95f),

                        new Color(0.5f, 0.4f, 0.18f, 0.8f),

                        1

                    ));

                }

            }

            else

            {

                // SENARYO 4: İki panel de açık (Varsayılan düzen)

                // Chat paneli (Solda - X = 2f)

                chatRT.sizeDelta = new Vector2(_chatWidth, _chatHeight);

                chatRT.anchoredPosition = new Vector2(2f / s, bottomY / s);

                if (chatBtn != null)

                {

                    var btnRT = chatBtn.GetComponent<RectTransform>();

                    if (btnRT != null)

                    {

                        btnRT.anchorMin = new Vector2(0, 1);

                        btnRT.anchorMax = new Vector2(0, 1);

                        btnRT.pivot = new Vector2(0, 1);

                        btnRT.anchoredPosition = new Vector2(_chatWidth - 20f, -_chatHeight + 20f);

                        btnRT.sizeDelta = new Vector2(20f, 20f);

                    }

                    RemoveFoldButtonLabel(chatBtn);

                    SetUIElementThemeSprite(chatBtn.gameObject, GetSkillThemeArrowSprite("chat_btn_off_arrow_20_20", 20, 20,

                        new Color(0.18f, 0.14f, 0.10f, 1f),

                        new Color(0.5f, 0.4f, 0.18f, 0.9f),

                        1,

                        true

                    ));

                }

                // Savaş Günlüğü (Chat'in sağında - X = 2f + _chatWidth)

                msgRT.sizeDelta = new Vector2(_msgOutputWidth, _msgOutputHeight);

                msgRT.anchoredPosition = new Vector2((2f + _chatWidth * UIScaleMultiplier) / s, bottomY / s);

                if (msgBtn != null)

                {

                    var btnRT = msgBtn.GetComponent<RectTransform>();

                    if (btnRT != null)

                    {

                        btnRT.anchorMin = new Vector2(0, 1);

                        btnRT.anchorMax = new Vector2(0, 1);

                        btnRT.pivot = new Vector2(0, 1);

                        btnRT.anchoredPosition = new Vector2(_msgOutputWidth - 20f, -_msgOutputHeight + 20f);

                        btnRT.sizeDelta = new Vector2(20f, 20f);

                    }

                    RemoveFoldButtonLabel(msgBtn);

                    SetUIElementThemeSprite(msgBtn.gameObject, GetSkillThemeArrowSprite("msg_btn_off_arrow_20_20", 20, 20,

                        new Color(0.18f, 0.14f, 0.10f, 1f),

                        new Color(0.5f, 0.4f, 0.18f, 0.9f),

                        1,

                        true

                    ));

                }

            }

        }

        private void UpdateMsgOutputPanelLayout(Transform root, float width, float height)

        {

            var panelRT = root.GetComponent<RectTransform>();

            if (panelRT != null)

            {

                panelRT.sizeDelta = new Vector2(width, height);

            }

            var rootImg = root.GetComponent<Image>();

            if (rootImg != null)

            {

                rootImg.sprite = GetSkillThemePanelBgSprite("msg_output_panel_bg", (int)width, (int)height, 0,

                    new Color(0.06f, 0.05f, 0.04f, 0.60f), // Şeffaf bronz

                    new Color(0.04f, 0.03f, 0.02f, 0.60f),

                    new Color(0.5f, 0.4f, 0.18f, 0.7f),    // Altın çerçeve

                    1

                );

                rootImg.color = Color.white;

            }

            var container = root.Find("MsgOutput_ScrollContainer");

            if (container != null)

            {

                var containerRT = container.GetComponent<RectTransform>();

                if (containerRT != null)

                {

                    // Sol, sağ, üst ve alttan tam 8px boşluk kalacak şekilde uzatıldı (Y bottom = -height + 8f).

                    // Yazılar butonun arkasından akacaktır.

                    containerRT.anchoredPosition = new Vector2(8f, -8f);

                    containerRT.sizeDelta = new Vector2(width - 16f, height - 16f);

                    // Viewport'un container boyutuna tam kilitlenmesini garanti altına al

                    var viewport = container.Find("MsgOutput_Viewport");

                    if (viewport != null)

                    {

                        var viewportRT = viewport.GetComponent<RectTransform>();

                        if (viewportRT != null)

                        {

                            viewportRT.anchorMin = Vector2.zero;

                            viewportRT.anchorMax = Vector2.one;

                            viewportRT.offsetMin = Vector2.zero;

                            viewportRT.offsetMax = Vector2.zero;

                            viewportRT.sizeDelta = Vector2.zero;

                        }

                    }

                }

            }

            // Kaydırma çubuğunun (scrollbar) yüksekliğini ve konumunu dikey boyuta göre ayarla

            var scrollTransform = root.Find("scroll");

            if (scrollTransform != null)

            {

                var scrollRT = scrollTransform.GetComponent<RectTransform>();

                if (scrollRT != null)

                {

                    scrollRT.anchorMin = new Vector2(0, 1);

                    scrollRT.anchorMax = new Vector2(0, 1);

                    scrollRT.pivot = new Vector2(0, 1);

                    scrollRT.anchoredPosition = new Vector2(width - 16f, -8f); // Buton sol sınırıyla hizalı, 8px üst boşluk

                    scrollRT.sizeDelta = new Vector2(10f, height - 28f); // Katlama butonunun hemen üstünde biter

                }

            }

            var btnFold = KOUIRenderer.FindChildButton(root, "btn_off");

            if (btnFold != null)

            {

                var btnRT = btnFold.GetComponent<RectTransform>();

                if (btnRT != null)

                {

                    // Katlama butonu tam kare (20x20) yapıldı ve panelin en sağ alt köşesine yapıştırıldı (X = width - 20f, Y = -height + 20f)

                    btnRT.anchoredPosition = new Vector2(width - 20f, -height + 20f);

                    btnRT.sizeDelta = new Vector2(20f, 20f);

                }

                SetUIElementThemeSprite(btnFold.gameObject, GetSkillThemeArrowSprite("msg_btn_off_arrow_20_20", 20, 20,

                    new Color(0.18f, 0.14f, 0.10f, 1f), // Bronz zemin

                    new Color(0.5f, 0.4f, 0.18f, 0.9f),   // Altın çerçeve

                    1,

                    true // Sola bakan ok (<) - Katlamak için

                ));

            }

        }

        private void AddResizeHandle(Transform panelRoot, Vector2 minSize, Vector2 maxSize, System.Action<float, float> onSizeChanged)

        {

            if (panelRoot == null) return;

            Transform targetParent = panelRoot;

            var chatBg = panelRoot.Find("Chat_Background");

            if (chatBg != null)

            {

                targetParent = chatBg;

            }

            var handleTransform = targetParent.Find("ResizeHandle");

            GameObject handleGO;

            if (handleTransform == null)

            {

                handleGO = new GameObject("ResizeHandle");

                handleGO.transform.SetParent(targetParent, false);

            }

            else

            {

                handleGO = handleTransform.gameObject;

            }

            // Katmanı ebeveyn nesneyle (UI layer) eşitleyerek her cihazda görünmesini sağlıyoruz

            handleGO.layer = targetParent.gameObject.layer;

            handleGO.SetActive(true);

            var img = handleGO.GetComponent<Image>();

            if (img == null) img = handleGO.AddComponent<Image>();

            img.enabled = true;

            img.sprite = GetResizeIconSprite();

            img.color = Color.white;

            img.raycastTarget = true;

            var rt = handleGO.GetComponent<RectTransform>();

            if (rt != null)

            {

                rt.anchorMin = new Vector2(1, 1);

                rt.anchorMax = new Vector2(1, 1);

                rt.pivot = new Vector2(1, 1);

                rt.anchoredPosition = new Vector2(-2f, -2f);

                rt.sizeDelta = new Vector2(12f, 12f);

            }

            var dragHandler = handleGO.GetComponent<UIResizeDragHandler>();

            if (dragHandler == null) dragHandler = handleGO.AddComponent<UIResizeDragHandler>();

            dragHandler.Initialize(panelRoot.GetComponent<RectTransform>(), minSize, maxSize, onSizeChanged);

        }

        private Sprite GetResizeIconSprite()

        {

            int w = 12;

            int h = 12;

            Texture2D tex = new Texture2D(w, h, TextureFormat.RGBA32, false);

            tex.filterMode = FilterMode.Point;

            Color[] clearColors = new Color[w * h];

            for (int i = 0; i < clearColors.Length; i++) clearColors[i] = Color.clear;

            tex.SetPixels(clearColors);

            Color gold = new Color(0.75f, 0.62f, 0.35f, 1f);

            // Sağa yatık diagonal /

            for (int i = 1; i <= 10; i++)

            {

                tex.SetPixel(i, i, gold);

            }

            // Sağ üst ok

            tex.SetPixel(10, 10, gold); tex.SetPixel(10, 9, gold); tex.SetPixel(10, 8, gold);

            tex.SetPixel(9, 10, gold); tex.SetPixel(8, 10, gold);

            // Sol alt ok

            tex.SetPixel(1, 1, gold); tex.SetPixel(1, 2, gold); tex.SetPixel(1, 3, gold);

            tex.SetPixel(2, 1, gold); tex.SetPixel(3, 1, gold);

            tex.Apply();

            return Sprite.Create(tex, new Rect(0, 0, w, h), new Vector2(0.5f, 0.5f));

        }

        private Transform GetOrCreateButton(Transform root, string btnName)

        {

            var trans = root.Find(btnName);

            if (trans != null) return trans;

            var refTrans = root.Find("btn_map");

            if (refTrans != null)

            {

                var go = UnityEngine.Object.Instantiate(refTrans.gameObject, root, false);

                go.name = btnName;

                return go.transform;

            }

            return null;

        }

        private void RepositionAndStyleButton(Transform btnTrans, float posX, string customLabel = null)

        {

            if (btnTrans == null) return;

            var rt = btnTrans.GetComponent<RectTransform>();

            if (rt != null)

            {

                rt.sizeDelta = new Vector2(72f, 28f);

                rt.anchorMin = new Vector2(0f, 0f);

                rt.anchorMax = new Vector2(0f, 0f);

                rt.pivot = new Vector2(0f, 0f);

                rt.anchoredPosition = new Vector2(posX, 10f);

            }

            var btn = btnTrans.GetComponent<Button>();

            if (btn != null)

            {

                var bgSprite = GetSkillThemeRoundedRectSprite(btnTrans.name + "_themed_bg_72_28", 72, 28, 0,

                    new Color(0.06f, 0.05f, 0.04f, 0.60f), // Yarı şeffaf bronz

                    new Color(0.5f, 0.4f, 0.18f, 0.7f),    // Altın sarısı çerçeve

                    1                                      // Çerçeve kalınlığı

                );

                SetUIElementThemeSprite(btn.gameObject, bgSprite);

                btn.transition = Selectable.Transition.ColorTint;
                var colors = btn.colors;
                colors.normalColor = Color.white;
                colors.highlightedColor = new Color(1.1f, 1.1f, 1.1f, 1f);
                colors.pressedColor = new Color(0.6f, 0.5f, 0.4f, 1f);
                colors.selectedColor = Color.white;
                colors.disabledColor = new Color(0.5f, 0.5f, 0.5f, 0.5f);
                colors.colorMultiplier = 1f;
                colors.fadeDuration = 0.05f;
                btn.colors = colors;

            }

            // Metin nesnesi yoksa çalışma zamanında oluştur (Sit/Stand gibi butonlar için)

            var txt = btnTrans.GetComponentInChildren<Text>(true);

            if (txt == null)

            {

                var txtGO = new GameObject("Text_Label");

                txtGO.transform.SetParent(btnTrans, false);

                txt = txtGO.AddComponent<Text>();

                var txtRT = txtGO.GetComponent<RectTransform>();

                if (txtRT != null)

                {

                    txtRT.anchorMin = Vector2.zero;

                    txtRT.anchorMax = Vector2.one;

                    txtRT.offsetMin = Vector2.zero;

                    txtRT.offsetMax = Vector2.zero;

                }

            }

            if (txt != null)

            {

                if (customLabel != null)

                {

                    txt.text = customLabel;

                }

                txt.font = GetSafeFont(11);

                txt.color = new Color(1f, 0.82f, 0.42f, 1f); // Seçili All Chat sarısı

                txt.alignment = TextAnchor.MiddleCenter;

            }

        }

        private System.Collections.IEnumerator ExecuteDelayedTown(KONetworkManager netMgr)
        {
            yield return new WaitForSeconds(1.0f);
            if (netMgr != null)
            {
                using var packet = new KOPacketWriter(WizOpcode.WIZ_HOME);
                netMgr.SendPacket(packet);
            }
        }

        private void BindCmdBarPrefab(Transform root)

        {

            CleanLegacyPrefabImages(root);

            BindCmdBarButtons(root);

            StyleModernCmdBarButtons(root);

        }

        private void StyleModernCmdBarButtons(Transform root)

        {

            var buttons = root.GetComponentsInChildren<Button>(true);

            foreach (var btn in buttons)

            {

                var bgSprite = GetSkillThemeRoundedRectSprite(btn.gameObject.name + "_themed_bg_72_28", 72, 28, 0,

                    new Color(0.06f, 0.05f, 0.04f, 0.60f), // Yarı şeffaf bronz

                    new Color(0.5f, 0.4f, 0.18f, 0.7f),    // Altın sarısı çerçeve

                    1

                );

                SetUIElementThemeSprite(btn.gameObject, bgSprite);

                btn.transition = Selectable.Transition.ColorTint;
                var colors = btn.colors;
                colors.normalColor = Color.white;
                colors.highlightedColor = new Color(1.1f, 1.1f, 1.1f, 1f);
                colors.pressedColor = new Color(0.6f, 0.5f, 0.4f, 1f);
                colors.selectedColor = Color.white;
                colors.disabledColor = new Color(0.5f, 0.5f, 0.5f, 0.5f);
                colors.colorMultiplier = 1f;
                colors.fadeDuration = 0.05f;
                btn.colors = colors;

                var txt = btn.GetComponentInChildren<Text>(true);

                if (txt != null)

                {

                    txt.font = GetSafeFont(11);

                    txt.color = new Color(1f, 0.82f, 0.42f, 1f); // Parlak altın sarısı (Draco Online ile uyumlu)

                    txt.alignment = TextAnchor.MiddleCenter;

                }

            }

            var dracoTrans = root.Find("label_draco_online");

            if (dracoTrans != null)

            {

                var img = dracoTrans.GetComponent<Image>();

                if (img != null)

                {

                    img.sprite = GetFadeGradientSprite("draco_online_fade_bg_232_28_double_border_thin", 232, 28,

                        new Color(0.06f, 0.05f, 0.04f, 0.60f),

                        new Color(0.85f, 0.70f, 0.30f, 0.95f),

                        1

                    );

                }

                var txt = dracoTrans.GetComponentInChildren<Text>(true);

                if (txt != null)

                {

                    txt.font = GetSafeFont(11);

                    txt.color = new Color(1f, 0.82f, 0.42f, 1f);

                    txt.alignment = TextAnchor.MiddleCenter;

                }

            }

        }

        private void RestructureCmdBar(Transform root)

        {

            if (root == null) return;

            // 1. Root üzerindeki Image veya RawImage'ı kapatarak ana çerçeveyi temizle

            var rootImg = root.GetComponent<Image>();

            if (rootImg != null) rootImg.enabled = false;

            var rootRaw = root.GetComponent<RawImage>();

            if (rootRaw != null) rootRaw.enabled = false;

            // 2. İlk iki sırada yer alan arka plan çerçeve resimlerini doğrudan indeksleri üzerinden kapat

            if (root.childCount > 0) root.GetChild(0).gameObject.SetActive(false);

            if (root.childCount > 1) root.GetChild(1).gameObject.SetActive(false);

            // 3. Parti davet/ayrılma ve kullanılmayan orta bölge butonlarını gizle

            var inviteTrans = root.Find("btn_invite");

            if (inviteTrans != null) inviteTrans.gameObject.SetActive(false);

            var disbandTrans = root.Find("btn_disband");

            if (disbandTrans != null) disbandTrans.gameObject.SetActive(false);

            var attackTrans = root.Find("btn_attack");

            if (attackTrans != null) attackTrans.gameObject.SetActive(false);

            var walkTrans = root.Find("btn_walk");

            if (walkTrans != null) walkTrans.gameObject.SetActive(false);

            var runTrans = root.Find("btn_run");

            if (runTrans != null) runTrans.gameObject.SetActive(false);

            var cameraTrans = root.Find("btn_camera");

            if (cameraTrans != null) cameraTrans.gameObject.SetActive(false);

            // 4. btn_pm ve btn_town butonlarını klonla/oluştur

            var pmTrans = GetOrCreateButton(root, "btn_pm");

            if (pmTrans != null)

            {

                pmTrans.gameObject.SetActive(true);

                var btn = pmTrans.GetComponent<Button>();

                if (btn != null)

                {

                    btn.onClick.RemoveAllListeners();

                    btn.onClick.AddListener(() => {

                        KOWhisperManager.Instance?.ShowWhisperDirectory();

                    });

                }

            }

            var townTrans = GetOrCreateButton(root, "btn_town");

            if (townTrans != null)

            {

                townTrans.gameObject.SetActive(true);

                var btn = townTrans.GetComponent<Button>();

                if (btn != null)

                {

                    btn.onClick.RemoveAllListeners();

                    btn.onClick.AddListener(() => {

                        ParseChattingCommand("/town");

                    });

                }

            }

            // 5. Butonları Konumlandır ve Stil Giydir

            // Sol bölme (PM, Character, Map, Skill, Sit)

            RepositionAndStyleButton(pmTrans, 20f, "PM");

            RepositionAndStyleButton(root.Find("btn_character"), 96f);

            RepositionAndStyleButton(root.Find("btn_map"), 172f);

            RepositionAndStyleButton(root.Find("btn_skill"), 248f);

            // Sit/Stand butonları (duruma göre biri görünür, ikisini de aynı yere koyuyoruz)

            RepositionAndStyleButton(root.Find("btn_sit"), 324f, "Sit");

            RepositionAndStyleButton(root.Find("btn_stand"), 324f, "Stand");

            // Sağ bölme (Town, Command, Inventory, Trade, Exit)

            RepositionAndStyleButton(townTrans, 628f, "Town");

            RepositionAndStyleButton(root.Find("btn_option"), 704f); // Command butonu

            RepositionAndStyleButton(root.Find("btn_inventory"), 780f);

            RepositionAndStyleButton(root.Find("btn_control"), 856f); // Trade butonu

            RepositionAndStyleButton(root.Find("btn_exit"), 932f);

            // 6. Orta bölgede DRACO ONLINE yazısını sıfırdan ve temiz bir şekilde oluştur

            var dracoTrans = root.Find("label_draco_online");

            if (dracoTrans != null)

            {

                DestroyImmediate(dracoTrans.gameObject);

            }

            var dracoGO = new GameObject("label_draco_online", typeof(RectTransform));

            dracoGO.transform.SetParent(root, false);

            dracoTrans = dracoGO.transform;

            if (dracoTrans != null)

            {

                var rt = dracoTrans as RectTransform;

                rt.sizeDelta = new Vector2(232f, 28f);

                rt.anchorMin = new Vector2(0f, 0f);

                rt.anchorMax = new Vector2(0f, 0f);

                rt.pivot = new Vector2(0f, 0f);

                rt.anchoredPosition = new Vector2(396f, 10f);

                // Arka plan resmi ekle (Yatayda sönümlenen bronz zemin ve üst altın sarısı ayraç)

                var img = dracoTrans.GetComponent<Image>();

                if (img == null) img = dracoTrans.gameObject.AddComponent<Image>();

                img.sprite = GetFadeGradientSprite("draco_online_fade_bg_232_28_double_border_thin", 232, 28,

                    new Color(0.06f, 0.05f, 0.04f, 0.60f), // Yarı şeffaf bronz dolgu

                    new Color(0.85f, 0.70f, 0.30f, 0.95f), // Belirgin altın sarısı ayraç rengi

                    1                                      // 1px ayraç kalınlığı (üst ve alt)

                );

                // Yazı ekle

                var txt = dracoTrans.GetComponentInChildren<Text>(true);

                if (txt == null)

                {

                    var txtGO = new GameObject("Text_Label");

                    txtGO.transform.SetParent(dracoTrans, false);

                    txt = txtGO.AddComponent<Text>();

                    var txtRT = txtGO.GetComponent<RectTransform>();

                    if (txtRT != null)

                    {

                        txtRT.anchorMin = Vector2.zero;

                        txtRT.anchorMax = Vector2.one;

                        txtRT.offsetMin = Vector2.zero;

                        txtRT.offsetMax = Vector2.zero;

                    }

                }

                if (txt != null)

                {

                    txt.text = "DRACO ONLINE";

                    txt.font = GetSafeFont(11); // Buton yazı tipi boyutuyla uyumlu (11)

                    txt.color = new Color(1f, 0.82f, 0.42f, 1f); // Seçili All Chat sarısı

                    txt.alignment = TextAnchor.MiddleCenter;

                }

            }

        }

        public void SetPMButtonBlinking(bool blink)

        {

            if (_uiCmdBar == null) return;

            if (_pmBlinker == null)

            {

                var pmBtnTrans = _uiCmdBar.transform.Find("btn_pm");

                if (pmBtnTrans != null)

                {

                    _pmBlinker = pmBtnTrans.gameObject.GetComponent<KOPMButtonBlinker>();

