                else _pmBlinker.StopBlinking();

            }

        }

        /// <summary>

        /// C++ birebir: UIMessageWnd.cpp CreateLines() + m_pScrollbar

        /// Doğru Unity ScrollRect hiyerarşisi:

        ///   parentRT (ScrollRect component) — UIF container, sabit boyut

        ///     └ viewport (yeni GO, RectMask2D, stretch-fill) — klipleme

        ///          └ textRT (Content, ContentSizeFitter) — içerik büyür

        /// C++ karşılıkları:

        ///   m_ppUILines[] + SetTopLine() → Unity ContentSizeFitter + scroll

        ///   m_pScrollbar → Unity ScrollRect auto-scroll

        ///   m_rcChatOutRegion → Unity RectMask2D klipleme

        /// </summary>

        private void SetupMsgOutputScrollRect(Text textComp)

        {

            var textRT = textComp.GetComponent<RectTransform>();

            var parentTransform = textComp.transform.parent;

            if (textRT == null || parentTransform == null) return;

            // C++ birebir: UIMessageWnd.cpp:134

            // m_rcChatOutRegion = m_pChatOut->GetRegion();

            // text_message'ın KENDİ orijinal boyutu klipleme bölgesi olarak kullanılır.

            // Parent panelin boyutu DEĞİL — text_message UIF'te tam olarak belirlenmiş bir bölge.

            Vector2 originalSize = textRT.sizeDelta;

            Vector2 originalAnchoredPos = textRT.anchoredPosition;

            Vector2 originalAnchorMin = textRT.anchorMin;

            Vector2 originalAnchorMax = textRT.anchorMax;

            Vector2 originalPivot = textRT.pivot;

            // 1. ScrollContainer GO oluştur — 160f genişliğindeki yeni panele tam oturacak şekilde

            var containerGO = new GameObject("MsgOutput_ScrollContainer");

            containerGO.transform.SetParent(parentTransform, false);

            var containerRT = containerGO.AddComponent<RectTransform>();

            containerRT.anchorMin = new Vector2(0, 1);

            containerRT.anchorMax = new Vector2(0, 1);

            containerRT.pivot = new Vector2(0, 1);

            containerRT.anchoredPosition = new Vector2(10f, -10f); // Sol üstten 10px boşluk

            containerRT.sizeDelta = new Vector2(140f, 115f); // Genişlik 140px, Yükseklik 115px

            // 2. Viewport GO oluştur (container'ın child'ı)

            var viewportGO = new GameObject("MsgOutput_Viewport");

            viewportGO.transform.SetParent(containerRT, false);

            var viewportRT = viewportGO.AddComponent<RectTransform>();

            viewportRT.anchorMin = Vector2.zero;

            viewportRT.anchorMax = Vector2.one;

            viewportRT.offsetMin = Vector2.zero;

            viewportRT.offsetMax = Vector2.zero;

            // 3. Viewport'a RectMask2D — C++ m_rcChatOutRegion dışını kliple

            viewportGO.AddComponent<RectMask2D>();

            // Raycast detection background to allow dragging anywhere in the area

            var viewImg = viewportGO.GetComponent<Image>();

            if (viewImg == null) viewImg = viewportGO.AddComponent<Image>();

            if (viewImg != null)

            {

                viewImg.color = new Color(0f, 0f, 0f, 0.005f); // Görünmez ama raycast algılar

                viewImg.raycastTarget = true;

            }

            // 4. Text'i viewport'un child'ı yap

            textRT.SetParent(viewportRT, false);

            // 5. Text anchor: top-stretch, yukarıdan aşağı büyüsün

            textRT.anchorMin = new Vector2(0, 1);

            textRT.anchorMax = new Vector2(1, 1);

            textRT.pivot = new Vector2(0, 1);

            textRT.anchoredPosition = Vector2.zero;

            textRT.offsetMin = new Vector2(2, 0);  // sol padding

            textRT.offsetMax = new Vector2(-2, 0); // sağ padding

            // 6. ContentSizeFitter — text içeriğine göre dikey boyut

            var fitter = textComp.gameObject.GetComponent<ContentSizeFitter>();

            if (fitter == null)

                fitter = textComp.gameObject.AddComponent<ContentSizeFitter>();

            fitter.verticalFit = ContentSizeFitter.FitMode.PreferredSize;

            fitter.horizontalFit = ContentSizeFitter.FitMode.Unconstrained;

            // 7. Root (Panel) nesnesine ScrollRect ekle (Böylece dokunmalar panel geneline yayılır ve joystick'i bloklar)

            var scrollRect = parentTransform.gameObject.GetComponent<ScrollRect>();

            if (scrollRect == null) scrollRect = parentTransform.gameObject.AddComponent<ScrollRect>();

            scrollRect.content = textRT;          // content = text (büyüyen)

            scrollRect.viewport = viewportRT;     // viewport = mask'lı container

            scrollRect.horizontal = false;

            scrollRect.vertical = true;

            scrollRect.movementType = ScrollRect.MovementType.Clamped;

            scrollRect.scrollSensitivity = 20f;

            scrollRect.inertia = false;           // C++ scroll'da inertia yok

            _msgOutputScrollRect = scrollRect;

        }

        private ScrollRect _chatScrollRect;

        private void SetupChatScrollRect(Text textComp)

        {

            var textRT = textComp.GetComponent<RectTransform>();

            var parentTransform = textComp.transform.parent;

            if (textRT == null || parentTransform == null) return;

            Vector2 originalSize = textRT.sizeDelta;

            Vector2 originalAnchoredPos = textRT.anchoredPosition;

            Vector2 originalAnchorMin = textRT.anchorMin;

            Vector2 originalAnchorMax = textRT.anchorMax;

            Vector2 originalPivot = textRT.pivot;

            var containerGO = new GameObject("Chat_ScrollContainer");

            containerGO.transform.SetParent(parentTransform, false);

            var containerRT = containerGO.AddComponent<RectTransform>();

            containerRT.anchorMin = new Vector2(0, 1);

            containerRT.anchorMax = new Vector2(0, 1);

            containerRT.pivot = new Vector2(0, 1);

            containerRT.anchoredPosition = new Vector2(15f, -34f); // Sekmelerin altından başlasın (NOWA Online yerleşimi - 24f header)

            containerRT.sizeDelta = new Vector2(283f, 85f); // Genişlik 283px (313px panel için), Yükseklik 85px (mesaj kutusunun altı)

            var viewportGO = new GameObject("Chat_Viewport");

            viewportGO.transform.SetParent(containerRT, false);

            var viewportRT = viewportGO.AddComponent<RectTransform>();

            viewportRT.anchorMin = Vector2.zero;

            viewportRT.anchorMax = Vector2.one;

            viewportRT.offsetMin = Vector2.zero;

            viewportRT.offsetMax = Vector2.zero;

            viewportGO.AddComponent<RectMask2D>();

            // Raycast detection background to allow dragging anywhere in the area

            var viewImg = viewportGO.GetComponent<Image>();

            if (viewImg == null) viewImg = viewportGO.AddComponent<Image>();

            if (viewImg != null)

            {

                viewImg.color = new Color(0f, 0f, 0f, 0.005f); // Görünmez ama raycast algılar

                viewImg.raycastTarget = true;

            }

            textRT.SetParent(viewportRT, false);

            textRT.anchorMin = new Vector2(0, 1);

            textRT.anchorMax = new Vector2(1, 1);

            textRT.pivot = new Vector2(0, 1);

            textRT.anchoredPosition = Vector2.zero;

            textRT.offsetMin = new Vector2(2, 0);

            textRT.offsetMax = new Vector2(-2, 0);

            var fitter = textComp.gameObject.GetComponent<ContentSizeFitter>();

            if (fitter == null)

                fitter = textComp.gameObject.AddComponent<ContentSizeFitter>();

            fitter.verticalFit = ContentSizeFitter.FitMode.PreferredSize;

            fitter.horizontalFit = ContentSizeFitter.FitMode.Unconstrained;

            // 7. Root (Panel) nesnesine ScrollRect ekle (Böylece dokunmalar panel geneline yayılır ve joystick'i bloklar)

            var scrollRect = parentTransform.gameObject.GetComponent<ScrollRect>();

            if (scrollRect == null) scrollRect = parentTransform.gameObject.AddComponent<ScrollRect>();

            scrollRect.content = textRT;

            scrollRect.viewport = viewportRT;

            scrollRect.horizontal = false;

            scrollRect.vertical = true;

            scrollRect.movementType = ScrollRect.MovementType.Clamped;

            scrollRect.scrollSensitivity = 20f;

            scrollRect.inertia = false;

            _chatScrollRect = scrollRect;

        }

