        /// <summary>

        /// Sistem mesajı ekle.

        /// C++ GameProcMain.cpp satır 4929-4932 birebir:

        /// void CGameProcMain::MsgOutput(const string& szMsg, D3DCOLOR crMsg)

        /// { m_pUIMsgDlg->AddMsg(szMsg, crMsg); }

        ///

        /// C++ UIMessageWnd.cpp AddMsg() satır 210-268:

        /// - ChatBuffer'a ekle (255 max FIFO)

        /// - AddLineBuffer ile satır bazlı parçala

        /// - ScrollBar auto-scroll (en alta)

        /// </summary>

        public void AddMsgOutput(string message, Color color)

        {

            if (string.IsNullOrEmpty(message)) return;

            string colorHex = ColorUtility.ToHtmlStringRGB(color);

            string richLine = $"<color=#{colorHex}>{message}</color>";

            _msgOutputLines.Add(richLine);

            while (_msgOutputLines.Count > MAX_MSG_OUTPUT_LINES)

                _msgOutputLines.RemoveAt(0);

            _msgOutputDirty = true;

        }

        private void UpdateMsgOutputTextImmediate()

        {

            if (_msgOutputText != null)

            {

                _msgOutputText.text = string.Join("\n", _msgOutputLines);

                if (_msgOutputScrollRect != null)

                {

                    Canvas.ForceUpdateCanvases();

                    _msgOutputScrollRect.verticalNormalizedPosition = 0f; // 0 = en alt

                }

            }

        }

