        // BUFF/DEBUFF ICONS (C++ UIStateBar birebir)

        // ============================

        private bool IsScrollBuff(int magicNum)

        {

            return magicNum >= 300000;

        }

        private void EnsureBuffBarContainer()
        {
            if (_buffBarContainer != null) return;
            if (_canvas == null) return;

            // Create parent container on the main Canvas (or HUDContainer to render behind other panels)
            GameObject containerObj = new GameObject("BuffBarContainer");
            containerObj.transform.SetParent(_hudContainer != null ? _hudContainer.transform : _canvas.transform, false);
            containerObj.transform.SetAsFirstSibling();
            _buffBarContainer = containerObj.AddComponent<RectTransform>();
            _buffBarContainer.pivot = new Vector2(1, 1);
            _buffBarContainer.sizeDelta = new Vector2(300, 72); // Height for 2 rows (32 each + padding)

            // Load saved position (normalized relative to the main Canvas) or use default
            float canvasWidth = _canvas.GetComponent<RectTransform>().rect.width;
            float canvasHeight = _canvas.GetComponent<RectTransform>().rect.height;

            if (PlayerPrefs.HasKey("BuffBar_NormX"))
            {
                float normX = PlayerPrefs.GetFloat("BuffBar_NormX");
                float normY = PlayerPrefs.GetFloat("BuffBar_NormY");
                _buffBarContainer.anchorMin = new Vector2(normX, normY);
                _buffBarContainer.anchorMax = new Vector2(normX, normY);
                _buffBarContainer.anchoredPosition = Vector2.zero;
            }
            else
            {
                _buffBarContainer.anchorMin = new Vector2(1, 1);
                _buffBarContainer.anchorMax = new Vector2(1, 1);
                float savedX = PlayerPrefs.GetFloat("BuffBar_X", -160f);
                float savedY = PlayerPrefs.GetFloat("BuffBar_Y", -2f);
                _buffBarContainer.anchoredPosition = new Vector2(savedX, savedY);
            }

            // Create Drag Handle 1 (For Row 1 - Top Row, positioned next to Row 1)
            GameObject handle1Obj = new GameObject("DragHandle1");
            handle1Obj.transform.SetParent(_buffBarContainer.transform, false);
            RectTransform handle1RT = handle1Obj.AddComponent<RectTransform>();
            handle1RT.anchorMin = new Vector2(1, 1);
            handle1RT.anchorMax = new Vector2(1, 1);
            handle1RT.pivot = new Vector2(1, 1);
            handle1RT.sizeDelta = new Vector2(10, 32); // Small vertical rectangle matching row height
            handle1RT.anchoredPosition = new Vector2(0, 0);

            // Create Drag Handle 2 (For Row 2 - Bottom Row, positioned next to Row 2)
            GameObject handle2Obj = new GameObject("DragHandle2");
            handle2Obj.transform.SetParent(_buffBarContainer.transform, false);
            RectTransform handle2RT = handle2Obj.AddComponent<RectTransform>();
            handle2RT.anchorMin = new Vector2(1, 1);
            handle2RT.anchorMax = new Vector2(1, 1);
            handle2RT.pivot = new Vector2(1, 1);
            handle2RT.sizeDelta = new Vector2(10, 32); // Small vertical rectangle matching row height
            handle2RT.anchoredPosition = new Vector2(0, -36); // Positioned next to row 2

            // Draw a subtle gold/bronze border and dark background using dynamic rounded rect
            var handleSprite = GetSkillThemeRoundedRectSprite("buff_handle", 10, 32, 2, 
                new Color(0.12f, 0.10f, 0.08f, 0.9f), 
                new Color(0.6f, 0.48f, 0.22f, 0.9f), 1);

            if (handleSprite != null)
            {
                var img1 = handle1Obj.AddComponent<UnityEngine.UI.Image>();
                img1.sprite = handleSprite;
                img1.color = Color.white;

                var img2 = handle2Obj.AddComponent<UnityEngine.UI.Image>();
                img2.sprite = handleSprite;
                img2.color = Color.white;
            }
            else
            {
                var img1 = handle1Obj.AddComponent<UnityEngine.UI.Image>();
                img1.color = new Color(0.6f, 0.48f, 0.22f, 0.8f);

                var img2 = handle2Obj.AddComponent<UnityEngine.UI.Image>();
                img2.color = new Color(0.6f, 0.48f, 0.22f, 0.8f);
            }

            // Add Drag Handler to DragHandle1
            var drag1 = handle1Obj.AddComponent<KOSkillBarMoveHandler>();
            drag1.DragTarget = _buffBarContainer;
            drag1.BypassEditModeCheck = true;

            // Add Drag Handler to DragHandle2
            var drag2 = handle2Obj.AddComponent<KOSkillBarMoveHandler>();
            drag2.DragTarget = _buffBarContainer;
            drag2.BypassEditModeCheck = true;

            // Create Row 1 (Normal Skills - Bottom row)
            GameObject row1Obj = new GameObject("BuffRow1");
            row1Obj.transform.SetParent(_buffBarContainer.transform, false);
            _buffRow1 = row1Obj.AddComponent<RectTransform>();
            _buffRow1.anchorMin = new Vector2(0, 1);
            _buffRow1.anchorMax = new Vector2(1, 1);
            _buffRow1.pivot = new Vector2(1, 1);
            _buffRow1.sizeDelta = new Vector2(0, 32);
            _buffRow1.anchoredPosition = new Vector2(-12, -36); // Shifted left of the handle and aligned at -36

            // Create Row 2 (Scrolls - Top row)
            GameObject row2Obj = new GameObject("BuffRow2");
            row2Obj.transform.SetParent(_buffBarContainer.transform, false);
            _buffRow2 = row2Obj.AddComponent<RectTransform>();
            _buffRow2.anchorMin = new Vector2(0, 1);
            _buffRow2.anchorMax = new Vector2(1, 1);
            _buffRow2.pivot = new Vector2(1, 1);
            _buffRow2.sizeDelta = new Vector2(0, 32);
            _buffRow2.anchoredPosition = new Vector2(-12, 0); // Shifted left of the handle
        }

        private void RepositionBuffIcons()

        {

            EnsureBuffBarContainer();

            if (_buffRow1 == null || _buffRow2 == null) return;

            int row1Count = 0;

            int row2Count = 0;

            for (int i = 0; i < _activeBuffs.Count; i++)

            {

                var buff = _activeBuffs[i];

                if (buff.IconObj == null) continue;

                var rt = buff.IconObj.GetComponent<RectTransform>();

                if (rt == null) continue;

                bool isScroll = IsScrollBuff(buff.MagicNum);

                RectTransform targetRow = isScroll ? _buffRow2 : _buffRow1;

                if (buff.IconObj.transform.parent != targetRow)

                {

                    buff.IconObj.transform.SetParent(targetRow, false);

                }

                rt.anchorMin = new Vector2(1, 0.5f);

                rt.anchorMax = new Vector2(1, 0.5f);

                rt.pivot = new Vector2(1, 0.5f);

                rt.sizeDelta = new Vector2(32, 32);

                if (isScroll)

                {

                    rt.anchoredPosition = new Vector2(-(row2Count * 34), 0);

                    row2Count++;

                }

                else

                {

                    rt.anchoredPosition = new Vector2(-(row1Count * 34), 0);

                    row1Count++;

                }

            }

        }

        public bool IsBuffActive(int magicNum)
        {
            foreach (var buff in _activeBuffs)
            {
                if (buff.MagicNum == magicNum)
                    return true;
            }
            return false;
        }

        public void AddBuff(int magicNum, byte buffType, float duration, string skillName)
        {
            // Aynı buff zaten varsa süresini güncelle
            foreach (var existing in _activeBuffs)
            {
                if (existing.MagicNum == magicNum)
                {
                    existing.Duration = duration;
                    return;
                }
            }

            var buff = new BuffIconInfo
            {
                MagicNum = magicNum,
                BuffType = buffType,
                Duration = duration,
                SkillName = skillName
            };

            var icon = KOItemIconLoader.LoadSkillIcon(magicNum);

            EnsureBuffBarContainer();

            if (_canvas != null)
            {
                var iconObj = new GameObject($"Buff_{magicNum}");
                
                bool isScroll = IsScrollBuff(magicNum);
                RectTransform targetRow = isScroll ? _buffRow2 : _buffRow1;
                iconObj.transform.SetParent(targetRow, false);

                var rt = iconObj.AddComponent<RectTransform>();
                rt.anchorMin = new Vector2(1, 0.5f);
                rt.anchorMax = new Vector2(1, 0.5f);
                rt.pivot = new Vector2(1, 0.5f);
                rt.sizeDelta = new Vector2(32, 32);

                var img = iconObj.AddComponent<UnityEngine.UI.Image>();
                if (icon != null)
                {
                    img.sprite = icon;
                    img.preserveAspect = true;
                }
                else
                {
                    img.color = new Color(0.5f, 0.3f, 0.8f, 0.7f);
                }
                buff.IconObj = iconObj;

                var btn = iconObj.AddComponent<UnityEngine.UI.Button>();
                btn.onClick.AddListener(() => OnBuffIconClicked(buff));

                // Create Duration Text child object
                var textObj = new GameObject("DurationText");
                textObj.transform.SetParent(iconObj.transform, false);

                var txtRect = textObj.AddComponent<RectTransform>();
                txtRect.anchorMin = new Vector2(1f, 0f);
                txtRect.anchorMax = new Vector2(1f, 0f);
                txtRect.pivot = new Vector2(1f, 0f);
                txtRect.anchoredPosition = new Vector2(-1f, 1f);
                txtRect.sizeDelta = new Vector2(32f, 16f);

                var txt = textObj.AddComponent<Text>();
                txt.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");
                txt.fontSize = 12;
                txt.fontStyle = FontStyle.Bold;
                txt.alignment = TextAnchor.LowerRight;
                txt.color = Color.white;
                txt.text = "";

                var shadow = textObj.AddComponent<Shadow>();
                shadow.effectColor = Color.black;
                shadow.effectDistance = new Vector2(1f, -1f);

                buff.DurationText = txt;
            }

            _activeBuffs.Add(buff);
            RepositionBuffIcons();
        }

        public void RemoveBuff(int magicNum)
        {
            int removeIdx = -1;
            for (int i = 0; i < _activeBuffs.Count; i++)
            {
                if (_activeBuffs[i].MagicNum == magicNum)
                {
                    removeIdx = i;
                    break;
                }
            }

            if (removeIdx < 0) return;

            if (_selectedBuffForMenu != null && _selectedBuffForMenu.MagicNum == magicNum)
            {
                HideBuffContextMenu();
            }

            var removed = _activeBuffs[removeIdx];
            if (removed.IconObj != null) Destroy(removed.IconObj);

            _activeBuffs.RemoveAt(removeIdx);
            RepositionBuffIcons();
        }

        public void ClearBuffs()
        {
            HideBuffContextMenu();
            foreach (var buff in _activeBuffs)
            {
                if (buff.IconObj != null) Destroy(buff.IconObj);
            }
            _activeBuffs.Clear();
        }

        private void TickBuffIcons()
        {
            if (_activeBuffs.Count == 0) return;

            BuffIconInfo expiredBuff = null;
            foreach (var buff in _activeBuffs)
            {
                buff.Duration -= Time.deltaTime;
                if (buff.Duration <= 0f)
                {
                    expiredBuff = buff;
                    break;
                }

                if (buff.DurationText != null)
                {
                    if (buff.Duration < 60f)
                    {
                        buff.DurationText.text = $"{Mathf.CeilToInt(buff.Duration)}s";
                    }
                    else if (buff.Duration < 3600f)
                    {
                        buff.DurationText.text = $"{Mathf.CeilToInt(buff.Duration / 60f)}m";
                    }
                    else
                    {
                        buff.DurationText.text = $"{Mathf.CeilToInt(buff.Duration / 3600f)}h";
                    }
                }
            }

            if (expiredBuff != null)
            {
                if (_selectedBuffForMenu != null && _selectedBuffForMenu.MagicNum == expiredBuff.MagicNum)
                {
                    HideBuffContextMenu();
                }
                if (expiredBuff.IconObj != null) Destroy(expiredBuff.IconObj);
                _activeBuffs.Remove(expiredBuff);
                RepositionBuffIcons();
            }
        }

