        /// <summary>

        /// D3DCOLOR (0xAARRGGBB) formatından Unity Color'a dönüştürme helper.

        /// C++ MsgOutput() çağrılarında kullanılan renkler:

        /// 0xffffff00 = sarı, 0xffff3b3b = kırmızı, 0xff6565ff = mavi,

        /// 0xff00ff00 = yeşil, 0xff00ffff = cyan, 0xffa2a0c8 = lavanta

        /// </summary>

        public static Color D3DColorToUnity(uint d3dColor)

        {

            float a = ((d3dColor >> 24) & 0xFF) / 255f;

            float r = ((d3dColor >> 16) & 0xFF) / 255f;

            float g = ((d3dColor >> 8) & 0xFF) / 255f;

            float b = (d3dColor & 0xFF) / 255f;

            return new Color(r, g, b, a);

        }

        public Font GetSafeFont(int fontSize)

        {

            Font font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");

            if (font == null)

                font = Resources.GetBuiltinResource<Font>("Arial.ttf");

            if (font == null)

                font = Font.CreateDynamicFontFromOSFont("Arial", fontSize);

            if (font == null)

            {

                string[] fallbackFonts = Font.GetOSInstalledFontNames();

                if (fallbackFonts != null && fallbackFonts.Length > 0)

                    font = Font.CreateDynamicFontFromOSFont(fallbackFonts[0], fontSize);

            }

            return font;

        }

