        /// <summary>

        /// Open-KO birebir: CUIPerTradeDlg slot icon g\u00fcncelleme.

        /// isMine=true \u2192 m_pPerTradeMy[slotIndex], false \u2192 m_pPerTradeOther[slotIndex]

        /// C++ SetTex(szIconFN) + SetRegion(pArea->GetRegion())

        /// </summary>

        public void UpdateTradeSlot(bool isMine, int slotIndex, int itemId, int count, short durability)

        {

            if (_uiPersonalTrade == null || slotIndex < 0 || slotIndex >= 12) return;

            var slotArray = isMine ? _tradeMySlotIcons : _tradeOtherSlotIcons;

            // Mevcut icon varsa count g\u00fcncelle

            if (slotArray[slotIndex] != null)

            {

                var countText = slotArray[slotIndex].GetComponentInChildren<Text>();

                if (countText != null && count > 1)

                    countText.text = count.ToString();

                return;

            }

            // Yeni icon oluştur

            var icon = KOItemIconLoader.LoadItemIcon(ResolveIconId(itemId));

            var iconObj = new GameObject($"TradeSlot_{(isMine ? "My" : "Other")}_{slotIndex}");

            iconObj.transform.SetParent(_uiPersonalTrade.transform, false);

            var rt = iconObj.AddComponent<RectTransform>();

            rt.sizeDelta = new Vector2(32, 32);

            // C++ birebir: GetChildAreaByiOrder(UI_AREA_TYPE_PER_TRADE_MY/OTHER, slotIndex)

            // .uif dosyasından area konumlarını oku

            // Area type: 4=PER_TRADE_MY, 5=PER_TRADE_OTHER (N3UIArea.h:13-29)

            int areaTypeId = isMine ? 4 : 5;

            var areaRT = KOUIRenderer.FindChildAreaByiOrder(_uiPersonalTrade.transform, areaTypeId, slotIndex);

            if (areaRT != null)

            {

                rt.anchorMin = areaRT.anchorMin;

                rt.anchorMax = areaRT.anchorMax;

                rt.offsetMin = areaRT.offsetMin;

                rt.offsetMax = areaRT.offsetMax;

            }

            else

            {

                Debug.LogWarning($"[KOUIMGR] Trade area bulunamadi: type={areaTypeId} order={slotIndex}");

            }

            var img = iconObj.AddComponent<UnityEngine.UI.Image>();

            if (icon != null)

            {

                img.sprite = icon;

                img.preserveAspect = true;

            }

            else

            {

                img.color = new Color(0.4f, 0.4f, 0.4f, 0.6f);

            }

            // C++ birebir: tüm slot icon'ları raycast alır (tooltip için)

            img.raycastTarget = true;

            // Count text (countable item'lar i\u00e7in)

            if (count > 1)

            {

                var countObj = new GameObject("Count");

                countObj.transform.SetParent(iconObj.transform, false);

                var countRT = countObj.AddComponent<RectTransform>();

                countRT.anchorMin = new Vector2(0, 0);

                countRT.anchorMax = new Vector2(1, 0.4f);

                countRT.offsetMin = Vector2.zero;

                countRT.offsetMax = Vector2.zero;

                var countTxt = countObj.AddComponent<Text>();

                countTxt.text = count.ToString();

                countTxt.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");

                countTxt.fontSize = 10;

                countTxt.color = Color.white;

                countTxt.alignment = TextAnchor.LowerRight;

                countTxt.raycastTarget = false;

            }

            // Mobil adaptasyon: single-tap=tooltip

            var tradeHandler = iconObj.AddComponent<KOItemSlotHandler>();

            tradeHandler.slotType = KOItemSlotHandler.SlotType.BagSlot;

            tradeHandler.slotIndex = slotIndex;

            tradeHandler.tooltipItemDefId = itemId;

            tradeHandler.tooltipShowPrice = false;

            slotArray[slotIndex] = iconObj;

        }

