        // GOLD EDIT POPUP — Open-KO CUITradeEditDlg birebir portu

        // UITradeEditDlg.cpp:72-103 (Open/Close) + SubProcPerTrade.cpp:480-563

        // ================================================

        private void BindCountableEdit(Transform root)

        {

            // C++ satır 184: GetChildByID<CN3UIString>("String_PersonTradeEdit_Msg")

            _countableEditMsg = KOUIRenderer.FindChildText(root, "String_PersonTradeEdit_Msg");

            // C++ satır 197: GetChildByID<CN3UIEdit>("edit_trade")

            var editObj = KOUIRenderer.FindChildByID(root, "edit_trade");

            if (editObj != null)

            {

                _countableEditInput = editObj.GetComponent<InputField>();

                if (_countableEditInput != null)

                {

                    // CreateEdit tarafından zaten oluşturuldu.

                    // Ama textComponent olarak kendi yarattığı "EditText"'i kullanıyor.

                    // UIF'nin String child'ı (edit_trade) ayrı render edildi ve o görünür olan.

                    // InputField.textComponent'i UIF'nin String Text'ine bağla — C++ birebir:

                    // CN3UIEdit kendi String child'ını input text olarak kullanır.

                    var uifStringText = KOUIRenderer.FindChildText(editObj, "edit_trade");

                    if (uifStringText != null)

                    {

                        _countableEditInput.textComponent = uifStringText;

                        uifStringText.supportRichText = false;

                        uifStringText.alignment = TextAnchor.MiddleLeft;

                        // CreateEdit'in yarattığı ekstra "EditText" nesnesini kaldır

                        var extraEditText = editObj.Find("EditText");

                        if (extraEditText != null)

                            Destroy(extraEditText.gameObject);

                    }

                    _countableEditInput.contentType = InputField.ContentType.Standard;

                    _countableEditInput.characterLimit = 15;

                }

                else

                {

                    // InputField yoksa oluştur — UIF String child'ını kullan

                    var existingText = editObj.GetComponentInChildren<Text>();

                    if (existingText == null)

                    {

                        var textObj = new GameObject("InputText");

                        textObj.transform.SetParent(editObj, false);

                        var txtRT = textObj.AddComponent<RectTransform>();

                        txtRT.anchorMin = Vector2.zero; txtRT.anchorMax = Vector2.one;

                        txtRT.offsetMin = new Vector2(2, 0); txtRT.offsetMax = new Vector2(-2, 0);

                        existingText = textObj.AddComponent<Text>();

                        existingText.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");

                        existingText.fontSize = 12;

                        existingText.color = Color.white;

                        existingText.alignment = TextAnchor.MiddleLeft;

                    }

                    existingText.supportRichText = false;

                    var existingImg = editObj.GetComponent<Image>();

                    _countableEditInput = editObj.gameObject.AddComponent<InputField>();

                    _countableEditInput.textComponent = existingText;

                    _countableEditInput.contentType = InputField.ContentType.Standard;

                    _countableEditInput.characterLimit = 15;

                    if (existingImg != null)

                        _countableEditInput.targetGraphic = existingImg;

                }

            }

            else

            {

                Debug.LogWarning("[KOUIMGR] ⚠ edit_trade bulunamadı!");

            }

            // C++ satır 288: m_pBtnOk = GetChildByID<CN3UIButton>("btn_ok")

            var btnOk = KOUIRenderer.FindChildButton(root, "btn_ok");

            if (btnOk != null)

            {

                btnOk.onClick.AddListener(OnCountableEditOK);

            }

            else

            {

                Debug.LogWarning("[KOUIMGR] ⚠ btn_ok bulunamadı!");

            }

            // C++ satır 289: m_pBtnCancel = GetChildByID<CN3UIButton>("btn_cancel")

            var btnCancel = KOUIRenderer.FindChildButton(root, "btn_cancel");

            if (btnCancel != null)

            {

                btnCancel.onClick.AddListener(OnCountableEditCancel);

            }

            else

            {

                Debug.LogWarning("[KOUIMGR] ⚠ btn_cancel bulunamadı!");

            }

            // Apply modern UI theme to the countable edit popup

            ModernizeCountableEditPanel(root);

        }

        private void ModernizeCountableEditPanel(Transform root)

        {

            try

            {

                // Use the existing message box style helper

                ModernizeMessageBoxUI(root);

                // 1. Force the background to be fully opaque (alpha = 1.0) and sharp corners (radius = 0)

                var customBg = root.Find("MsgBoxCustomBg")?.gameObject;

                if (customBg != null)

                {

                    var bgImg = customBg.GetComponent<Image>();

                    if (bgImg != null)

                    {

                        var panelRT = root.GetComponent<RectTransform>();

                        int w = panelRT != null ? (int)panelRT.rect.width : 313;

                        int h = panelRT != null ? (int)panelRT.rect.height : 130;

                        bgImg.sprite = GetSkillThemePanelBgSprite("countable_edit_full_opaque_bg", w, h, 0, // Radius 0 = sharp corners

                            new Color(0.12f, 0.10f, 0.08f, 1.0f), // Fully opaque background

                            new Color(0.05f, 0.04f, 0.04f, 1.0f), 

                            new Color(0.55f, 0.45f, 0.20f, 1.0f), // Gold border

                            2);

                        bgImg.color = Color.white;

                    }

                }

                // 1a. Format and center the message text label

                if (_countableEditMsg != null)

                {

                    _countableEditMsg.alignment = TextAnchor.MiddleCenter;

                    _countableEditMsg.color = Color.white;

                    _countableEditMsg.fontStyle = FontStyle.Bold;

                    _countableEditMsg.fontSize = 15;

                    var msgRT = _countableEditMsg.GetComponent<RectTransform>();

                    if (msgRT != null)

                    {

                        msgRT.anchorMin = new Vector2(0.5f, 1f);

                        msgRT.anchorMax = new Vector2(0.5f, 1f);

                        msgRT.pivot = new Vector2(0.5f, 0.5f);

                        msgRT.sizeDelta = new Vector2(290f, 25f);

                        msgRT.anchoredPosition = new Vector2(0f, -22f); // Place it near the top

                    }

                }

                var btnOkObj = KOUIRenderer.FindChildByID(root, "btn_ok");

                var btnCancelObj = KOUIRenderer.FindChildByID(root, "btn_cancel");

                // 1b. Reparent and center loose text components (OK / Cancel) to their respective button GameObjects.

                // In converted UIF layouts, text strings are separate sibling objects which swallow raycasts and block clicks.

                var allTextsInRoot = root.GetComponentsInChildren<Text>(true);

                foreach (var t in allTextsInRoot)

                {

                    if (t.transform.parent == root) // Only loose root level children

                    {

                        string cleanText = t.text.Replace(" ", "").Trim().ToUpper();

                        if (cleanText == "OK" || cleanText == "YES" || cleanText == "BTN_YES")

                        {

                            if (btnOkObj != null)

                            {

                                t.text = "OK";

                                t.transform.SetParent(btnOkObj.transform, false);

                                var textRT = t.GetComponent<RectTransform>();

                                if (textRT != null)

                                {

                                    textRT.anchorMin = Vector2.zero;

                                    textRT.anchorMax = Vector2.one;

                                    textRT.anchoredPosition = Vector2.zero;

                                    textRT.sizeDelta = Vector2.zero;

                                }

                                t.color = new Color(0.95f, 0.92f, 0.85f);

                                t.alignment = TextAnchor.MiddleCenter;

                                t.raycastTarget = false; // Prevent text from swallowing clicks

                            }

                        }

                        else if (cleanText == "CANCEL" || cleanText == "NO" || cleanText == "BTN_NO")

                        {

                            if (btnCancelObj != null)

                            {

                                t.text = "Cancel";

                                t.transform.SetParent(btnCancelObj.transform, false);

                                var textRT = t.GetComponent<RectTransform>();

                                if (textRT != null)

                                {

                                    textRT.anchorMin = Vector2.zero;

                                    textRT.anchorMax = Vector2.one;

                                    textRT.anchoredPosition = Vector2.zero;

                                    textRT.sizeDelta = Vector2.zero;

                                }

                                t.color = new Color(0.95f, 0.92f, 0.85f);

                                t.alignment = TextAnchor.MiddleCenter;

                                t.raycastTarget = false; // Prevent text from swallowing clicks

                            }

                        }

                    }

                }

                // 2. Style, lengthen, and center the input field socket background

                var editObj = KOUIRenderer.FindChildByID(root, "edit_trade");

                if (editObj != null)

                {

                    var editRT = editObj.GetComponent<RectTransform>();

                    if (editRT != null)

                    {

                        // Center input box (width 180, height 24) horizontally using middle anchor

                        editRT.anchorMin = new Vector2(0.5f, 1f);

                        editRT.anchorMax = new Vector2(0.5f, 1f);

                        editRT.pivot = new Vector2(0.5f, 0.5f);

                        editRT.sizeDelta = new Vector2(180f, 24f);

                        editRT.anchoredPosition = new Vector2(0f, -55f);

                    }

                    var img = editObj.GetComponent<Image>() ?? editObj.gameObject.AddComponent<Image>();

                    img.sprite = GetSkillThemeRoundedRectSprite("countable_edit_bg_socket_sharp", 180, 24, 0, // Radius 0 = sharp corners

                        new Color(0.06f, 0.06f, 0.06f, 1.0f), // Fully opaque inside

                        new Color(0.55f, 0.45f, 0.20f, 1.0f), // Gold border

                        1);

                    img.color = Color.white;

                    img.enabled = true; // Force enabled since ModernizeMessageBoxUI disables all panel images

                    // Ensure child text components stretch to match the new size

                    for (int i = 0; i < editObj.transform.childCount; i++)

                    {

                        var childRT = editObj.transform.GetChild(i).GetComponent<RectTransform>();

                        if (childRT != null)

                        {

                            childRT.anchorMin = Vector2.zero;

                            childRT.anchorMax = Vector2.one;

                            childRT.offsetMin = new Vector2(8f, 0); // Padding left

                            childRT.offsetMax = new Vector2(-8f, 0); // Padding right

                        }

                    }

                    var txt = editObj.GetComponentInChildren<Text>();

                    if (txt != null)

                    {

                        txt.color = new Color(0.95f, 0.92f, 0.85f);

                        txt.alignment = TextAnchor.MiddleCenter;

                    }

                }

                // 3. Style, align and enable interaction on OK and Cancel buttons

                if (btnOkObj != null)

                {

                    var okBtn = btnOkObj.GetComponent<Button>();

                    if (okBtn != null)

                    {

                        SetButtonThemeSprite(okBtn, GetSkillThemeRoundedRectSprite("countable_btn_ok_sharp", 90, 24, 0, // Radius 0 = sharp corners

                             new Color(0.12f, 0.28f, 0.12f, 0.95f), // Green

                             new Color(0.25f, 0.55f, 0.25f, 0.95f), // Green border

                             1));

                        var okImg = btnOkObj.GetComponent<Image>();

                        if (okImg != null)

                        {

                            okImg.enabled = true;

                            okImg.raycastTarget = true;

                        }

                        var okRT = btnOkObj.GetComponent<RectTransform>();

                        if (okRT != null)

                        {

                            okRT.anchorMin = new Vector2(0.5f, 1f);

                            okRT.anchorMax = new Vector2(0.5f, 1f);

                            okRT.pivot = new Vector2(0.5f, 0.5f);

                            okRT.sizeDelta = new Vector2(90f, 24f);

                            okRT.anchoredPosition = new Vector2(-55f, -92f); // Align perfectly left of center

                        }

                    }

                }

                if (btnCancelObj != null)

                {

                    var cancelBtn = btnCancelObj.GetComponent<Button>();

                    if (cancelBtn != null)

                    {

                        SetButtonThemeSprite(cancelBtn, GetSkillThemeRoundedRectSprite("countable_btn_cancel_sharp", 90, 24, 0, // Radius 0 = sharp corners

                             new Color(0.45f, 0.05f, 0.08f, 0.95f), // Red

                             new Color(0.75f, 0.15f, 0.15f, 0.95f), // Red border

                             1));

                        var cancelImg = btnCancelObj.GetComponent<Image>();

                        if (cancelImg != null)

                        {

                            cancelImg.enabled = true;

                            cancelImg.raycastTarget = true;

                        }

                        var cancelRT = btnCancelObj.GetComponent<RectTransform>();

                        if (cancelRT != null)

                        {

                            cancelRT.anchorMin = new Vector2(0.5f, 1f);

                            cancelRT.anchorMax = new Vector2(0.5f, 1f);

                            cancelRT.pivot = new Vector2(0.5f, 0.5f);

                            cancelRT.sizeDelta = new Vector2(90f, 24f);

                            cancelRT.anchoredPosition = new Vector2(55f, -92f); // Align perfectly right of center

                        }

                    }

                }

            }

            catch (System.Exception ex)

            {

                Debug.LogError($"[KOUIMGR] Error in ModernizeCountableEditPanel: {ex.Message}");

            }

        }

        /// <summary>

        /// C++ birebir: CountableItemEditDlg::Open() (CountableItemEditDlg.cpp:175-230)

        /// bCountGold=true → IDS_EDIT_BOX_GOLD ("Enter the amount of gold.")

        /// bCountGold=false → IDS_EDIT_BOX_COUNT ("Enter the quantity.")

        /// </summary>

        public void ShowCountableEdit(bool bCountGold = false)

        {

            if (bCountGold)

            {

                if (_countableEditMode != CountableEditMode.WarehouseDeposit &&

                    _countableEditMode != CountableEditMode.WarehouseWithdraw &&

                    _countableEditMode != CountableEditMode.MerchantItemPrice &&

                    _countableEditMode != CountableEditMode.AHRegisterItemCount &&

                    _countableEditMode != CountableEditMode.AHRegisterItemPrice)

                {

                    _countableEditMode = CountableEditMode.PersonalTrade;

                }

            }

            if (_uiCountableEdit == null)

            {

                Debug.LogWarning("[KOUIMGR] CountableEdit UIF yüklenmemiş!");

                return;

            }

            // C++ satır 178-181: mesaj text'ini set et

            if (_countableEditMsg != null)

            {

                _countableEditMsg.text = bCountGold

                    ? "Enter the amount of gold."

                    : "Enter the quantity.";

            }

            // C++ satır 192: SetQuantity(-1) → boş string

            if (_countableEditInput != null)

            {

                if (_countableEditMode == CountableEditMode.WarehouseItemDeposit || 

                    _countableEditMode == CountableEditMode.WarehouseItemWithdraw ||

                    _countableEditMode == CountableEditMode.ShopSell)

                {

                    _countableEditInput.text = _itemCountMax.ToString();

                }

                else

                {

                    _countableEditInput.text = "";

                }

                _countableEditInput.Select();

                _countableEditInput.ActivateInputField();

                _countableEditInput.onValueChanged.RemoveListener(OnCountableEditValueChanged);

                _countableEditInput.onValueChanged.AddListener(OnCountableEditValueChanged);

            }

            // C++ satır 194: SetVisible(true)

            _uiCountableEdit.SetActive(true);

            _uiCountableEdit.transform.SetAsLastSibling();

            var canvas = _uiCountableEdit.GetComponent<Canvas>();

            if (canvas == null)

            {

                canvas = _uiCountableEdit.AddComponent<Canvas>();

                _uiCountableEdit.AddComponent<UnityEngine.UI.GraphicRaycaster>();

            }

            canvas.overrideSorting = true;

            canvas.sortingOrder = 999;

            // C++ birebir: CountableItemEditDlg.cpp:205-228

            // Caller panel (Transaction/WareHouse/PerTrade) merkezine konumlandır

            GameObject callerPanel = null;

            switch (_countableEditMode)

            {

                case CountableEditMode.ShopBuy:

                case CountableEditMode.ShopSell:

                    // C++ satır 207-208: UIWND_TRANSACTION → m_pUITransactionDlg->GetRegion()

                    callerPanel = _uiTransaction;

                    break;

                case CountableEditMode.WarehouseDeposit:

                case CountableEditMode.WarehouseWithdraw:

                case CountableEditMode.WarehouseItemDeposit:

                case CountableEditMode.WarehouseItemWithdraw:

                    // C++ satır 215-216: UIWND_WARE_HOUSE → m_pUIWareHouseDlg->GetRegion()

                    callerPanel = _uiWarehouse;

                    break;

                case CountableEditMode.PersonalTrade:

                case CountableEditMode.TradeItemCount:

                    callerPanel = _uiPersonalTrade;

                    break;

                case CountableEditMode.AHRegisterItemCount:

                case CountableEditMode.AHRegisterItemPrice:

                    if (_uiAuctionHouse != null)

                    {

                        var frameTrans = _uiAuctionHouse.transform.Find("AH_InventoryModal/Frame");

                        if (frameTrans != null)

                            callerPanel = frameTrans.gameObject;

                        else

                            callerPanel = _uiAuctionHouse.gameObject;

                    }

                    break;

            }

            _countableEditCallerPanel = callerPanel;

            // Ensure parent is canvas to prevent size collapse

            if (_uiCountableEdit.transform.parent != _canvas.transform)

            {

                _uiCountableEdit.transform.SetParent(_canvas.transform, false);

                float s = CanvasScaleFactor;

                if (s > 0f)

                {

                    _uiCountableEdit.transform.localScale = new Vector3(1f / s, 1f / s, 1f / s);

                }

            }

            var rtCountable = _uiCountableEdit.GetComponent<RectTransform>();

            if (rtCountable != null)

            {

                rtCountable.anchorMin = new Vector2(0.5f, 0.5f);

                rtCountable.anchorMax = new Vector2(0.5f, 0.5f);

                rtCountable.pivot = new Vector2(0.5f, 0.5f);

                rtCountable.anchoredPosition = Vector2.zero;

            }

        }

        /// <summary>

        /// C++ birebir: CountableItemEditDlg::Close() (CountableItemEditDlg.cpp:232-241)

        /// </summary>

        public void HideCountableEdit()

        {

            _countableEditCallerPanel = null;

            if (_uiCountableEdit != null)

                _uiCountableEdit.SetActive(false);

        }

        private void OnCountableEditValueChanged(string val)

        {

            if (string.IsNullOrEmpty(val)) return;

            string digits = "";

            foreach (char c in val)

            {

                if (char.IsDigit(c)) digits += c;

            }

            if (digits == "")

            {

                _countableEditInput.onValueChanged.RemoveListener(OnCountableEditValueChanged);

                _countableEditInput.text = "";

                _countableEditInput.onValueChanged.AddListener(OnCountableEditValueChanged);

                return;

            }

            if (ulong.TryParse(digits, out ulong parsed))

            {

                string formatted = parsed.ToString("N0", new System.Globalization.CultureInfo("tr-TR"));

                if (formatted != val)

                {

                    _countableEditInput.onValueChanged.RemoveListener(OnCountableEditValueChanged);

                    _countableEditInput.text = formatted;

                    _countableEditInput.caretPosition = formatted.Length;

                    _countableEditInput.onValueChanged.AddListener(OnCountableEditValueChanged);

                }

            }

        }

        private GameObject _activeWarningToast;

        public void ShowWarningToast(string message)

        {

            Canvas targetCanvas = _canvas;

            if (targetCanvas == null)

            {

                targetCanvas = FindAnyObjectByType<Canvas>();

            }

            if (targetCanvas == null)

            {

                Debug.LogError("[KOUIMGR] ShowWarningToast failed: targetCanvas is null. Msg: " + message);

                return;

            }

            if (_activeWarningToast != null)

            {

                Destroy(_activeWarningToast);

            }

            StartCoroutine(ShowWarningToastCoroutine(targetCanvas, message));

        }

        private System.Collections.IEnumerator ShowWarningToastCoroutine(Canvas canvas, string message)

        {

            Transform parentTransform = canvas.transform;

            bool parentIsCountableEdit = false;

            if (_uiCountableEdit != null && _uiCountableEdit.activeInHierarchy)

            {

                parentTransform = _uiCountableEdit.transform;

                parentIsCountableEdit = true;

            }

            var toastObj = new GameObject("AHWarningToast", typeof(RectTransform));

            toastObj.layer = parentTransform.gameObject.layer;

            toastObj.transform.SetParent(parentTransform, false);

            _activeWarningToast = toastObj;

            // Add CanvasGroup

            var canvasGroup = toastObj.AddComponent<CanvasGroup>();

            var toastRT = toastObj.GetComponent<RectTransform>();

            if (parentIsCountableEdit)

            {

                toastRT.anchorMin = new Vector2(0.5f, 0.5f);

                toastRT.anchorMax = new Vector2(0.5f, 0.5f);

                toastRT.pivot = new Vector2(0.5f, 0.5f);

                toastRT.anchoredPosition = new Vector2(0f, 220f);

            }

            else

            {

                toastRT.anchorMin = new Vector2(0.5f, 0.85f);

                toastRT.anchorMax = new Vector2(0.5f, 0.85f);

                toastRT.pivot = new Vector2(0.5f, 0.5f);

                toastRT.anchoredPosition = Vector2.zero;

            }

            toastRT.sizeDelta = new Vector2(800, 100);

            var textObj = new GameObject("Text", typeof(RectTransform));

            textObj.layer = toastObj.layer;

            textObj.transform.SetParent(toastObj.transform, false);

            var textRT = textObj.GetComponent<RectTransform>();

            textRT.anchorMin = Vector2.zero;

            textRT.anchorMax = Vector2.one;

            textRT.sizeDelta = Vector2.zero;

            var textComp = textObj.AddComponent<Text>();

            textComp.text = message;

            var font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");

            if (font == null) font = Resources.GetBuiltinResource<Font>("Arial.ttf");

            textComp.font = font;

            textComp.fontSize = 18;

            textComp.alignment = TextAnchor.MiddleCenter;

            textComp.color = Color.red;

            textComp.fontStyle = FontStyle.Bold;

            textComp.horizontalOverflow = HorizontalWrapMode.Wrap;

            textComp.verticalOverflow = VerticalWrapMode.Overflow;

            canvasGroup.alpha = 0f;

            float elapsed = 0f;

            float duration = 0.3f;

            while (elapsed < duration)

            {

                if (toastObj == null) yield break;

                elapsed += Time.deltaTime;

                canvasGroup.alpha = Mathf.Lerp(0f, 1f, elapsed / duration);

                yield return null;

            }

            if (canvasGroup != null) canvasGroup.alpha = 1f;

            yield return new WaitForSeconds(2.4f);

            elapsed = 0f;

            while (elapsed < duration)

            {

                if (toastObj == null) yield break;

                elapsed += Time.deltaTime;

                canvasGroup.alpha = Mathf.Lerp(1f, 0f, elapsed / duration);

                yield return null;

            }

            if (canvasGroup != null) canvasGroup.alpha = 0f;

            if (toastObj != null)

            {

                Destroy(toastObj);

                if (_activeWarningToast == toastObj) _activeWarningToast = null;

            }

        }

        // HideGoldEditPopup kaldırıldı → HideCountableEdit() kullanılıyor

        /// <summary>

        /// OK butonuna basıldığında — edit değerini oku, ilgili işlemi yap.

        /// C++ birebir: CountableItemEditDlg::ReceiveMessage (btn_ok) → caller'a yönlendir

        /// </summary>

        private void OnCountableEditOK()

        {

            if (_countableEditMode == CountableEditMode.AHRegisterItemPrice)

            {

                long priceAmount = 0;

                if (_countableEditInput != null)

                {

                    string cleanText = _countableEditInput.text.Replace(".", "").Replace(",", "");

                    long.TryParse(cleanText, out priceAmount);

                }

                if (priceAmount <= 0)

                {

                    HideCountableEdit();

                    return;

                }

                if (priceAmount < 2100000000L || priceAmount > 50000000000L)

                {

                    ShowWarningToast("Invalid price entered. The price must be between 2.100.000.000 gb and 50.000.000.000 gb.");

                    if (_countableEditInput != null)

                    {

                        long clamped = priceAmount;

                        if (priceAmount < 2100000000L) clamped = 2100000000L;

                        else if (priceAmount > 50000000000L) clamped = 50000000000L;

                        _countableEditInput.text = clamped.ToString("N0", new System.Globalization.CultureInfo("tr-TR"));

                    }

                    return;

                }

                _ahPendingItemPrice = priceAmount;

                HideCountableEdit();

                if (KOAuctionHouseUI.Instance != null && KOAuctionHouseUI.Instance.isActiveAndEnabled)

                {

                    KOAuctionHouseUI.Instance.RegisterItemDirect(_ahPendingSrcSlot, _ahPendingItemId, _ahPendingItemCount, (ulong)_ahPendingItemPrice);

                }

                return;

            }

            int amount = 0;

            if (_countableEditInput != null)

            {

                string cleanText = _countableEditInput.text.Replace(".", "").Replace(",", "");

                int.TryParse(cleanText, out amount);

            }

            else

            {

                Debug.LogWarning("[KOUIMGR] OnCountableEditOK — _countableEditInput null!");

            }

            // C++ birebir: CountableItemEditDlg.cpp:553/587 — iGold <= 0 ise return (Close çağrılmaz)

            // Ama mobilde InputField düzgün çalışmazsa sonsuz takılma olur.

            // Güvenlik: amount <= 0 ise dialog'u kapat (C++ Cancel davranışı).

            if (amount <= 0)

            {

                HideCountableEdit();

                return;

            }

            switch (_countableEditMode)

            {

                case CountableEditMode.AHRegisterItemCount:

                {

                    if (amount > _itemCountMax) amount = _itemCountMax;

                    _ahPendingItemCount = amount;

                    HideCountableEdit();

                    PromptAHRegisterItemPrice();

                    return;

                }

                case CountableEditMode.WarehouseDeposit:

                {

                    var wareMgr = KOWarehouseManager.Instance;

                    if (wareMgr != null)

                    {

                        wareMgr.GoldDepositToWare(amount);

                        RefreshWarehouseGoldDisplay();

                        HideCountableEdit();

                    }

                    return;

                }

                case CountableEditMode.WarehouseWithdraw:

                {

                    var wareMgr = KOWarehouseManager.Instance;

                    if (wareMgr != null)

                    {

                        wareMgr.GoldWithdrawFromWare(amount);

                        RefreshWarehouseGoldDisplay();

                        HideCountableEdit();

                    }

                    return;

                }

                case CountableEditMode.WarehouseItemDeposit:

                {

                    ExecuteWareDeposit(_warePendingSrcSlot, _warePendingDstSlot, amount);

                    HideCountableEdit();

                    return;

                }

                case CountableEditMode.WarehouseItemWithdraw:

                {

                    ExecuteWareWithdraw(_warePendingSrcSlot, _warePendingDstSlot, amount);

                    HideCountableEdit();

                    return;

                }

                case CountableEditMode.ShopBuy:

                case CountableEditMode.ShopSell:

                {

                    var shopUI = ShopUI.Instance;

                    if (shopUI != null)

                    {

                        _shopPendingAmount = amount;

                        if (_shopPendingIsBuy)

                        {

                            HideCountableEdit();

                            string itemName = GetFormattedItemName(_shopPendingItemDefId);

                            long unitPrice = 0;

                            if (_currentShopItems != null)

                            {

                                foreach (var shopItem in _currentShopItems)

                                {

                                    if (shopItem != null && shopItem.ItemDefId == _shopPendingItemDefId)

                                    {

                                        unitPrice = shopItem.BuyPrice;

                                        break;

                                    }

                                }

                            }

                            long totalCost = unitPrice * amount;

                            string msg = $"Do you want to buy {amount:N0} {itemName} for {totalCost:N0} Coins?";

                            if (KOMessageBox.Instance != null)

                            {

                                KOMessageBox.Instance.ShowYesNo(msg, "Buy Item", MsgBoxBehavior.BEHAVIOR_NOTHING, onYes: () => {

                                    _shopPendingAmount = amount;

                                    ApplyPendingTradeToInventory();

                                    RefreshShopInventory();

                                    shopUI.BuyItem(_shopPendingTradeId, (byte)_shopPendingSlotIndex,

                                        (uint)_shopPendingItemDefId, (short)amount);

                                }, callerPanel: _uiTransaction);

                            }

                            else

                            {

                                ApplyPendingTradeToInventory();

                                RefreshShopInventory();

                                shopUI.BuyItem(_shopPendingTradeId, (byte)_shopPendingSlotIndex,

                                    (uint)_shopPendingItemDefId, (short)amount);

                            }

                        }

                        else

                        {

                            HideCountableEdit();

                            string itemName = GetFormattedItemName(_shopPendingItemDefId);

                            long totalCost = GetItemSellPrice(_shopPendingItemDefId, amount);

                            string msg = $"Do you want to sell {amount:N0} {itemName} for {totalCost:N0} Coins?";

                            if (KOMessageBox.Instance != null)

                            {

                                KOMessageBox.Instance.ShowYesNo(msg, "Sell Item", MsgBoxBehavior.BEHAVIOR_NOTHING, onYes: () => {

                                    _shopPendingAmount = amount;

                                    ApplyPendingTradeToInventory();

                                    RefreshShopInventory();

                                    shopUI.SellItem(_shopPendingTradeId, (byte)_shopPendingSlotIndex,

                                        (uint)_shopPendingItemDefId, (short)amount);

                                }, callerPanel: _uiTransaction);

                            }

                            else

                            {

                                ApplyPendingTradeToInventory();

                                RefreshShopInventory();

                                shopUI.SellItem(_shopPendingTradeId, (byte)_shopPendingSlotIndex,

                                    (uint)_shopPendingItemDefId, (short)amount);

                            }

                        }

                    }

                    return;

                }

                case CountableEditMode.TradeItemCount:

                {

                    // C++ UIPerTradeDlg::ItemCountOK() birebir

                    bool tradeSuccess = false;

                    if (EntropyOnline.Trade.KOTradeManager.Instance != null)

                        tradeSuccess = EntropyOnline.Trade.KOTradeManager.Instance.CountableItemCountOK(amount);

                    if (!tradeSuccess)

                    {

                        return;

                    }

                    HideCountableEdit();

                    RefreshTradeMyPanel();

                    return;

                }

                case CountableEditMode.MerchantItemCount:

                {

                    if (amount > _itemCountMax) amount = _itemCountMax;

                    _merchantPendingItemCount = amount;

                    HideCountableEdit();

                    PromptMerchantItemPrice();

                    return;

                }

                case CountableEditMode.MerchantItemPrice:

                {

                    _merchantPendingItemPrice = amount;

                    HideCountableEdit();

                    EntropyOnline.Trade.KOMerchantManager.Instance?.SendMerchantItemAdd(

                        _merchantPendingItemId,

                        _merchantPendingItemCount,

                        _merchantPendingItemPrice,

                        (byte)_merchantPendingSrcSlot,

                        (byte)_merchantPendingDstSlot

                    );

                    return;

                }

                case CountableEditMode.StallBuyCount:

                {

                    if (amount > _itemCountMax) amount = _itemCountMax;

                    HideCountableEdit();

                    int destSlot = _stallPendingDestSlot;

                    if (destSlot < 0)

                    {

                        destSlot = GetStallInvDestinationIndex(_stallPendingItemId, 0);

                    }

                    if (destSlot >= 0)

                    {

                        var manager = KOMerchantManager.Instance;

                        var targetItems = manager?.TargetMerchantItems;

                        if (targetItems != null && _stallPendingSlot >= 0 && _stallPendingSlot < targetItems.Length)

                        {

                            var item = targetItems[_stallPendingSlot];

                            if (item != null && !item.IsEmpty)

                            {

                                string itemName = GetFormattedItemName(item.ItemId);

                                long totalCost = (long)amount * item.Price;

                                string msg = $"Do you want to buy {amount:N0} {itemName} for {totalCost:N0} Gold?";

                                if (KOMessageBox.Instance != null)

                                {

                                    KOMessageBox.Instance.ShowYesNo(msg, "Buy Item", MsgBoxBehavior.BEHAVIOR_NOTHING, onYes: () => {

                                        KOMerchantManager.Instance?.SendMerchantItemBuy(

                                            _stallPendingItemId,

                                            amount,

                                            (byte)_stallPendingSlot,

                                            (byte)destSlot

                                        );

                                    }, countdownDuration: 5, forceFixedCenter: true);

                                }

                                else

                                {

                                    Debug.LogWarning("[KOUIMGR] KOMessageBox.Instance is null! Buying instantly without confirmation dialog.");

                                    KOMerchantManager.Instance?.SendMerchantItemBuy(

                                        _stallPendingItemId,

                                        amount,

                                        (byte)_stallPendingSlot,

                                        (byte)destSlot

                                    );

                                }

                            }

                        }

                    }

                    return;

                }

                default: // PersonalTrade

                    break;

            }

            // C++ SubProcPerTrade.cpp:490-552 — ItemCountEditOK

            bool success = false;

            if (EntropyOnline.Trade.KOTradeManager.Instance != null)

            {

                success = EntropyOnline.Trade.KOTradeManager.Instance.ItemCountEditOK(amount);

            }

            if (!success)

            {

                return;

            }

            HideCountableEdit();

            // Gold display güncelle — SubProcPerTrade.cpp:522-528

            var mgr = EntropyOnline.Trade.KOTradeManager.Instance;

            if (mgr != null)

            {

                UpdateTradeGoldDisplay(true, mgr.MyTradeGold);

                var gm = EntropyOnline.Core.GameManager.Instance;

                if (gm != null)

                {

                    var goldInvText = _uiPersonalTrade != null

                        ? KOUIRenderer.FindChildText(_uiPersonalTrade.transform, "string_money_inv")

                        : null;

                    if (goldInvText != null)

                        goldInvText.text = gm.Gold.ToString("N0");

                }

            }

        }

