        public void PopulateTradeInventory()

        {

            try

            {

                // 1. Clear existing icons

                foreach (var obj in _tradeInvItems)

                {

                    if (obj != null) Destroy(obj);

                }

                _tradeInvItems.Clear();

                if (_uiPersonalTrade == null || !_uiPersonalTrade.activeSelf) return;

                var inv = KOInventory.Instance;

                if (inv == null) return;

                // UI_AREA_TYPE_TRADE_MY = 12 is the area type of player inventory slots at the bottom in personal trade prefab

                const int UI_AREA_TYPE_TRADE_MY = 12;

                bool hasTradeMyAreas = KOUIRenderer.FindChildAreaByiOrder(_uiPersonalTrade.transform, UI_AREA_TYPE_TRADE_MY, 0) != null;

                for (int i = 0; i < KOInventory.MAX_ITEM_INVENTORY; i++)

                {

                    var invItem = inv.m_pMyInvWnd[i];

                    bool hasItem = invItem != null && invItem.itemId != 0;

                    RectTransform areaRT = hasTradeMyAreas

                        ? KOUIRenderer.FindChildAreaByiOrder(_uiPersonalTrade.transform, UI_AREA_TYPE_TRADE_MY, i)

                        : null;

                    if (areaRT != null)

                    {

                        if (hasItem)

                        {

                            var itemObj = CreateWarehouseIconInArea(areaRT, $"TradeInvSlot_{i}",

                                invItem.itemId, invItem.count > 0 ? invItem.count : 1,

                                KOItemSlotHandler.SlotType.BagSlot, i, (short)invItem.durability);

                            if (itemObj != null)

                            {

                                _tradeInvItems.Add(itemObj);

                                if (itemObj.GetComponent<KOItemDragDrop>() == null)

                                {

                                    itemObj.AddComponent<KOItemDragDrop>();

                                }

                            }

                        }

                    }

                }

            }

            catch (System.Exception ex)

            {

                Debug.LogError($"[KOUIMGR] Error in PopulateTradeInventory: {ex.Message}");

            }

        }

        /// <summary>Trade MY panelini yenile (slot ikonları güncelle).</summary>

        private void RefreshTradeMyPanel()

        {

            PopulateTradeInventory();

        }

        // ================================================

        // CHAT KOMUT İŞLEYİCİ — C++ ParseChattingCommand birebir

        // GameProcMain.cpp satır 5745-5873

        // ================================================

        /// <summary>

        /// C++ GameProcMain.cpp ParseChattingCommand satır 5745-5873 birebir port.

        /// '/' ile başlayan chat mesajlarını komut olarak işler.

        ///

        /// Komutlar:

        ///   /town — Eve dön (CMD_TOWN). Guard: m_bStun, HP >= %50.

        ///   /save — Manuel veri kaydetme (CMD_DATASAVE).

        /// </summary>

        public void ParseChattingCommand(string text)

        {

            if (string.IsNullOrEmpty(text) || text.Length < 2) return;

            // C++ satır 5815-5821 birebir: sscanf(szCmd, "/%s %s %s %s", szCmds[0-3])

            string raw = text.Substring(1).Trim();

            string[] parts = raw.Split(new[] { ' ' }, 4, System.StringSplitOptions.RemoveEmptyEntries);

            if (parts.Length == 0) return;

            string cmdStr = parts[0].ToLowerInvariant();

            string arg1 = parts.Length > 1 ? parts[1] : "";

            string arg2 = parts.Length > 2 ? parts[2] : "";

            var gm = EntropyOnline.Core.GameManager.Instance;

            var netMgr = KONetworkManager.Instance;

            // C++ satır 5823-5834: /goto x z — GM warp komutu

            if (cmdStr == "goto" && parts.Length >= 3)

            {

                if (float.TryParse(arg1, System.Globalization.NumberStyles.Float,

                    System.Globalization.CultureInfo.InvariantCulture, out float fX) &&

                    float.TryParse(arg2, System.Globalization.NumberStyles.Float,

                    System.Globalization.CultureInfo.InvariantCulture, out float fZ))

                {

                    if (netMgr != null)

                    {

                        using var packet = new KOPacketWriter(WizOpcode.WIZ_WARP_LIST);

                        packet.WriteInt16((short)(fX * 10));

                        packet.WriteInt16((short)(fZ * 10));

                        netMgr.SendPacket(packet);

                    }

                }

                return;

            }

            // C++ satır 5836-5844: g_szCmdMsg eşleştirmesi — enum e_ChatCmd birebir

            switch (cmdStr)

            {

                // ========================================

                // CMD_WHISPER — Fısıltı hedef değiştir

                // C++ satır 5848-5852 birebir

                // ========================================

                                case "whisper":

                case "w":

                case "pm":

                {

                    if (!string.IsNullOrEmpty(arg1) && netMgr != null)

                    {

                        netMgr.SendChatSelectTarget(arg1);

                    }

                    break;

                }

                // ========================================

                // CMD_TOWN — Eve dön

                // C++ satır 5854-5873 birebir

                // ========================================

                case "town":

                {

                    // C++ satır 5856: if (s_pPlayer->m_bStun) return;

                    // NOT: C++ return kullanır (function'dan çıkar), break DEĞİL

                    var player = GameObject.FindWithTag("Player");

                    if (player != null)

                    {

                        var pc = player.GetComponent<EntropyOnline.Character.PlayerController>();

                        if (pc != null && pc.IsStunned)

                        {

                            return; // C++ birebir: return, break değil

                        }

                    }

                    if (gm == null) break;

                    // C++ satır 5859: if (s_pPlayer->m_InfoBase.iHP * 2 >= s_pPlayer->m_InfoBase.iHPMax)

                    if (gm.CurrentHp * 2 >= gm.MaxHp)

                    {

                        if (netMgr != null)

                        {

                            StartCoroutine(ExecuteDelayedTown(netMgr));

                        }

                    }

                    else

                    {

                        // C++ birebir: text_resources.h:76 IDS_ERR_GOTO_TOWN_OUT_OF_HP (1903)

                        // "You cannot teleport back to town when you have half the HP or less"

                        AddMsgOutput("You cannot teleport back to town when you have half the HP or less", D3DColorToUnity(0xffff00ff));

                    }

                    break;

                }

                // ========================================

                // CMD_EXIT — Oyundan çıkış menüsü

                // C++ satır 5909-5911 birebir

                // ========================================

                case "exit":

                case "quit":

                {

                    // C++ RequestExit() → m_pUIExitMenu->SetVisible(true)

                    // Mobilde çıkış menüsünü göster — henüz UI yoksa log

                    break;

                }

                // ========================================

                // CMD_GREETING / CMD_GREETING2 / CMD_GREETING3 — Selam emote'ları

                // C++ satır 5978-5987 birebir:

                // if (PSA_BASIC && PSM_STOP) MsgSend_StateChange(N3_SP_STATE_CHANGE_ACTION, 1+(eCmd-CMD_GREETING))

                // ========================================

                case "greet":

                case "greeting":

                {

                    SendEmoteAction(1); // CMD_GREETING → action=1

                    break;

                }

                case "greet2":

                case "greeting2":

                {

                    SendEmoteAction(2); // CMD_GREETING2 → action=2

                    break;

                }

                case "greet3":

                case "greeting3":

                {

                    SendEmoteAction(3); // CMD_GREETING3 → action=3

                    break;

                }

                // ========================================

                // CMD_PROVOKE / CMD_PROVOKE2 / CMD_PROVOKE3 — Kışkırtma emote'ları

                // C++ satır 5989-5998 birebir:

                // MsgSend_StateChange(N3_SP_STATE_CHANGE_ACTION, 11+(eCmd-CMD_PROVOKE))

                // ========================================

                case "provoke":

                {

                    SendEmoteAction(11); // CMD_PROVOKE → action=11

                    break;

                }

                case "provoke2":

                {

                    SendEmoteAction(12); // CMD_PROVOKE2 → action=12

                    break;

                }

                case "provoke3":

                {

                    SendEmoteAction(13); // CMD_PROVOKE3 → action=13

                    break;

                }

                // ========================================

                // CMD_TRADE — Kişisel takas başlat

                // C++ satır 5876-5907 birebir

                // ========================================

                case "trade":

                {

                    // C++ satır 5878-5905 birebir guard'lar

                    if (gm == null || gm.TargetId < 0 || netMgr == null) break;

                    // C++ satır 5878: CPlayerOther* pOPC = s_pOPMgr->UPCGetByID(target, true);

                    var entityMgrTrade = EntropyOnline.World.EntityManager.Instance;

                    if (entityMgrTrade == null) break;

                    var tradeTarget = entityMgrTrade.GetRemotePlayer(gm.TargetId);

                    if (tradeTarget == null) break; // hedef UPC olmalı (NPC değil)

                    // C++ satır 5882: mesafe kontrolü — (pOPC->Position() - s_pPlayer->Position()).Magnitude() < (pOPC->Height() + 5.0f)

                    var playerObj = GameObject.FindWithTag("Player");

                    if (playerObj != null && tradeTarget.Root != null)

                    {

                        float dist = Vector3.Distance(playerObj.transform.position, tradeTarget.Root.transform.position);

                        float maxDist = 5.0f + 1.8f; // pOPC->Height() yaklaşık 1.8f

                        if (dist >= maxDist)

                        {

                            break;

                        }

                    }

                    // C++ satır 5887: uluslar arası ticaret kontrolü

                    if (gm.Nation != tradeTarget.Nation && !gm.CanTradeWithOtherNation)

                    {

                        return; // C++ birebir: return

                    }

                    // C++ birebir: text_resources.h:244 IDS_PERSONAL_TRADE_REQUEST (3503)

                    // pOPC->IDString() + " is requesting to trade."

                    string tradeTargetName2 = tradeTarget.Name ?? $"Player#{gm.TargetId}";

                    AddMsgOutput($"{tradeTargetName2} is requesting to trade.", D3DColorToUnity(0xffffff00));

                    // C++ satır 5893: MsgSend_PerTradeReq(pOPC->IDNumber())

                    using var packetTrade = new KOPacketWriter(WizOpcode.WIZ_EXCHANGE);

                    packetTrade.WriteByte(0x01); // EXCHANGE_REQ

                    packetTrade.WriteInt16((short)gm.TargetId);

                    netMgr.SendPacket(packetTrade);

                    break;

                }

                // ========================================

                // CMD_PARTY — Parti davet et

                // C++ satır 5913-5926 birebir

                // ========================================

                case "party":

                {

                    if (gm != null && gm.TargetId >= 0 && gm.TargetIsPlayer && PartyUI.Instance != null)

                    {

                        PartyUI.Instance.SendPartyInvite(gm.TargetId);

                        AddMsgOutput("Player was invited into the party. Waiting for a response.", D3DColorToUnity(0xffffff00));

                    }

                    break;

                }

                // ========================================

                // CMD_LEAVEPARTY — Partiden ayrıl

                // C++ satır 5928-5930 birebir

                // ========================================

                case "leaveparty":

                case "quitparty":

                case "quit_party":

                {

                    if (netMgr != null)

                    {

                        using var packet = new KOPacketWriter(WizOpcode.WIZ_PARTY);

                        packet.WriteByte(0x03); // N3_SP_PARTY_OR_FORCE_REMOVE

                        netMgr.SendPacket(packet);

                    }

                    break;

                }

                // ========================================

                // CMD_RECRUITPARTY — Parti BBS kaydı toggle

                // C++ satır 5932-5944 birebir

                // ========================================

                case "recruitparty":

                case "seekingparty":

                case "seeking_party":

                case "recruit_party":

                {

                    if (_uiPartyBBS != null)

                    {

                        bool isVisible = _uiPartyBBS.activeSelf;

                        ShowPartyBBS(!isVisible);

                    }

                    break;

                }

                // ========================================

                // CMD_JOINCLAN — Klan davet et (Chief/ViceChief only)

                // C++ satır 5947-5952 birebir

                // ========================================

                case "joinclan":

                case "join_clan":

                {

                    // C++ satır 5949 birebir: eKnightsDuty == CHIEF || VICECHIEF guard

                    var knightsMgrJoin = KOKnightsManager.Instance;

                    if (knightsMgrJoin == null || (!knightsMgrJoin.IsChief && !knightsMgrJoin.IsViceChief))

                    {

                        break;

                    }

                    if (gm != null && gm.TargetId >= 0 && gm.TargetIsPlayer && netMgr != null)

                    {

                        using var packet = new KOPacketWriter(WizOpcode.WIZ_KNIGHTS_PROCESS);

                        packet.WriteByte(0x06); // N3_SP_KNIGHTS_ADMIT

                        packet.WriteInt64(gm.TargetId);

                        netMgr.SendPacket(packet);

                    }

                    break;

                }

                // ========================================

                // CMD_WITHDRAWCLAN — Klandan ayrıl

                // C++ satır 5954-5956 birebir

                // ========================================

                case "withdrawclan":

                case "withdraw_clan":

                case "quitclan":

                case "quit_clan":

                {

                    if (netMgr != null)

                    {

                        using var packet = new KOPacketWriter(WizOpcode.WIZ_KNIGHTS_PROCESS);

                        packet.WriteByte(0x03); // N3_SP_KNIGHTS_WITHDRAW

                        netMgr.SendPacket(packet);

                    }

                    break;

                }

                // ========================================

                // CMD_FIRECLAN — Klandan at (Chief only)

                // C++ satır 5958-5966 birebir

                // ========================================

                case "fireclan":

                case "fire_clan":

                case "ban_from_clan":

