                    // C++ satır 5960 birebir: eKnightsDuty == CHIEF guard

                    var knightsMgrFire = KOKnightsManager.Instance;

                    if (knightsMgrFire == null || !knightsMgrFire.IsChief)

                    {

                        break;

                    }

                    if (!string.IsNullOrEmpty(arg1) && netMgr != null)

                    {

                        using var packet = new KOPacketWriter(WizOpcode.WIZ_KNIGHTS_PROCESS);

                        packet.WriteByte(0x04); // N3_SP_KNIGHTS_MEMBER_REMOVE

                        packet.WriteString(arg1);

                        netMgr.SendPacket(packet);

                    }

                    break;

                }

                // ========================================

                // CMD_APPOINTVICECHIEF — Başkan yardımcısı ata (Chief only)

                // C++ satır 5968-5976 birebir

                // ========================================

                case "appointvicechief":

                case "appoint_as_assistant_clan_leader":

                case "appointasassistantclanleader":

                {

                    // C++ satır 5970 birebir: eKnightsDuty == CHIEF guard

                    var knightsMgrAppoint = KOKnightsManager.Instance;

                    if (knightsMgrAppoint == null || !knightsMgrAppoint.IsChief)

                    {

