                    }

                    if (!string.IsNullOrEmpty(arg1) && netMgr != null)

                    {

                        using var packet = new KOPacketWriter(WizOpcode.WIZ_KNIGHTS_PROCESS);

                        packet.WriteByte(0x10); // N3_SP_KNIGHTS_DUTY_CHANGE

                        packet.WriteString(arg1);

                        netMgr.SendPacket(packet);

                    }

                    break;

                }

                // ========================================

                // CMD_VISIBLE / CMD_INVISIBLE — GM görünürlük

                // C++ satır 6000-6010 birebir

                // ========================================

                case "visible":

                {

                    if (netMgr != null)

                    {

                        // C++ MsgSend_StateChange(N3_SP_STATE_CHANGE_VISIBLE, 0)

                        using var packet = new KOPacketWriter(WizOpcode.WIZ_STATE_CHANGE);

                        packet.WriteByte(5); // N3_SP_STATE_CHANGE_VISIBLE=5

                        packet.WriteInt32(0);

                        netMgr.SendPacket(packet);

                    }

                    break;

                }

                case "invisible":

                {

                    if (netMgr != null)

                    {

                        // C++ MsgSend_StateChange(N3_SP_STATE_CHANGE_VISIBLE, 255)

                        using var packet = new KOPacketWriter(WizOpcode.WIZ_STATE_CHANGE);

                        packet.WriteByte(5);

                        packet.WriteInt32(255);

                        netMgr.SendPacket(packet);

                    }

                    break;

                }

                // ========================================

                // CMD_CLEAN / CMD_RAINING / CMD_SNOWING — Hava durumu (GM)

                // C++ satır 6012-6031 birebir

                // ========================================

                case "clean":

                {

                    // C++ MsgSend_Weather(1, iPercent)

                    int percent = 0;

                    if (!string.IsNullOrEmpty(arg1)) int.TryParse(arg1, out percent);

                    if (netMgr != null)

                    {

                        using var packet = new KOPacketWriter(WizOpcode.WIZ_WEATHER);

                        packet.WriteByte(1); // type=1 clean

                        packet.WriteInt16((short)percent);

                        netMgr.SendPacket(packet);

                    }

                    break;

                }

                case "rain":

                case "raining":

                {

                    int percent = 0;

                    if (!string.IsNullOrEmpty(arg1)) int.TryParse(arg1, out percent);

                    if (netMgr != null)

                    {

                        using var packet = new KOPacketWriter(WizOpcode.WIZ_WEATHER);

                        packet.WriteByte(2); // type=2 rain

                        packet.WriteInt16((short)percent);

                        netMgr.SendPacket(packet);

