                        packet.WriteByte(3); // type=3 snow

                        packet.WriteInt16((short)percent);

                        netMgr.SendPacket(packet);

                    }

                    break;

                }

                // ========================================

                // CMD_TIME — Saat ayarla (GM)

                // C++ satır 6033-6039 birebir

                // ========================================

                case "time":

                {

                    int hour = 0, min = 0;

                    if (!string.IsNullOrEmpty(arg1)) int.TryParse(arg1, out hour);

                    if (!string.IsNullOrEmpty(arg2)) int.TryParse(arg2, out min);

                    if (netMgr != null)

                    {

                        using var packet = new KOPacketWriter(WizOpcode.WIZ_TIME);

                        packet.WriteInt16((short)hour);

                        packet.WriteInt16((short)min);

                        netMgr.SendPacket(packet);

                    }

                    break;

                }

                // ========================================

                // CMD_CU_COUNT — Çevrimiçi kullanıcı sayısı

                // C++ satır 6041-6047 birebir

                // ========================================

                case "count":

                case "cu":

                {

                    if (netMgr != null)

                    {

                        using var packet = new KOPacketWriter(WizOpcode.WIZ_CONCURRENTUSER);

                        netMgr.SendPacket(packet);

                    }

                    break;

                }

                // ========================================

                // CMD_NOTICE — Genel bildirim gönder (GM)

                // C++ satır 6049-6057 birebir

                // ========================================

                case "notice":

                {

                    // C++ birebir: "/notice " sonrasını ayır — szCmd.substr(g_szCmdMsg[CMD_NOTICE].size() + 2)

                    int noticeStart = text.IndexOf(' ');

                    if (noticeStart > 0)

                    {

                        string noticeMsg = text.Substring(noticeStart + 1).Trim();

                        if (!string.IsNullOrEmpty(noticeMsg) && netMgr != null)

                        {

                            // C++ MsgSend_Chat(N3_CHAT_PUBLIC, szChat)

                            using var packet = new KOPacketWriter(WizOpcode.WIZ_CHAT);

                            packet.WriteByte(7); // N3_CHAT_PUBLIC=7

                            packet.WriteString(noticeMsg);

                            netMgr.SendPacket(packet);

                        }

                    }

                    break;

                }

                // ========================================

                // CMD_ARREST — Oyuncu takibi (GM)

                // C++ satır 6059-6063 birebir

                // ========================================

                case "arrest":

                {

                    if (!string.IsNullOrEmpty(arg1) && netMgr != null)

                    {

                        using var packet = new KOPacketWriter(WizOpcode.WIZ_OPERATOR);

                        packet.WriteByte(1); // N3_SP_ADMINISTRATOR_ARREST=1

                        packet.WriteString(arg1);

                        netMgr.SendPacket(packet);

                    }

                    break;

                }

                // ========================================

                // CMD_FORBIDCONNECT — Bağlantı yasakla (GM)

                // C++ satır 6065-6068 birebir

                // ========================================

                case "forbidconnect":

                {

                    if (!string.IsNullOrEmpty(arg1) && netMgr != null)

                    {

                        using var packet = new KOPacketWriter(WizOpcode.WIZ_OPERATOR);

                        packet.WriteByte(2); // N3_SP_ADMINISTRATOR_FORBID_CONNECT=2

                        packet.WriteString(arg1);

                        netMgr.SendPacket(packet);

                    }

                    break;

                }

                // ========================================

                // CMD_FORBIDCHAT — Chat yasakla (GM)

                // C++ satır 6071-6074 birebir

                // ========================================

                case "forbidchat":

                {

                    if (!string.IsNullOrEmpty(arg1) && netMgr != null)

                    {

                        using var packet = new KOPacketWriter(WizOpcode.WIZ_OPERATOR);

                        packet.WriteByte(3); // N3_SP_ADMINISTRATOR_CHAT_FORBID=3

                        packet.WriteString(arg1);

                        netMgr.SendPacket(packet);

                    }

                    break;

                }

                // ========================================

                // CMD_PERMITCHAT — Chat yasağını kaldır (GM)

                // C++ satır 6077-6081 birebir

                // ========================================

                case "permitchat":

                {

                    if (!string.IsNullOrEmpty(arg1) && netMgr != null)

                    {

                        using var packet = new KOPacketWriter(WizOpcode.WIZ_OPERATOR);

                        packet.WriteByte(4); // N3_SP_ADMINISTRATOR_CHAT_PERMIT=4

                        packet.WriteString(arg1);

                        netMgr.SendPacket(packet);

                    }

                    break;

                }

                // ========================================

                // CMD_GAME_SAVE — Manuel kaydetme

                // C++ satır 6083-6101 birebir

                // ========================================

                case "save":

                {

                    // C++ satır 6085-6100: cooldown kontrolü (300s) — client tarafı

                    float now = Time.unscaledTime;

                    if (now - _lastSaveTime > 300f)

                    {

                        if (netMgr != null)

                        {

                            using var packet = new KOPacketWriter(WizOpcode.WIZ_DATASAVE);

                            netMgr.SendPacket(packet);

                            _lastSaveTime = now;

                            // C++ birebir: text_resources.h:499 IDS_REQUEST_GAME_SAVE (6525)

                            AddMsgOutput("Saved character information.", D3DColorToUnity(0xffffff00));

                        }

                    }

                    else

                    {

                        // C++ satır 6098: IDS_DELAY_GAME_SAVE — 5 dakika beklenmeli

                        // C++ birebir: text_resources.h:500 IDS_DELAY_GAME_SAVE (6526)

                        AddMsgOutput("You can save every 5 minutes.", D3DColorToUnity(0xffffff00));

                    }

                    break;

                }

                case "block":

                {

                    if (!string.IsNullOrEmpty(arg1) && GameOptionsManager.Instance != null)

                    {

                        bool isBlocked = GameOptionsManager.Instance.IsPlayerBlocked(arg1);

                        if (isBlocked)

                        {

                            GameOptionsManager.Instance.RemoveBlockedPlayer(arg1);

                            AddMsgOutput($"Blocked player {arg1} has been unblocked.", D3DColorToUnity(0xffffff00));

                        }

                        else

                        {

                            GameOptionsManager.Instance.AddBlockedPlayer(arg1);

                            AddMsgOutput($"Player {arg1} is now blocked.", D3DColorToUnity(0xffffff00));

                        }

                        // Update visual checkmark of the whisper panel if open

                        KOWhisperManager.Instance?.UpdateWhisperPanelBlockState(arg1);

                    }

                    break;

                }

                // ========================================

                // CMD_MERCHANT — Merchant modunu aç

                // ========================================

                case "merchant":

                {

                    EntropyOnline.Trade.KOMerchantManager.Instance?.SendMerchantOpen();

                    break;

                }

                default:

                    if (netMgr != null)

                    {

                        using var packet = new KOPacketWriter(WizOpcode.WIZ_CHAT);

                        packet.WriteByte(1); // N3_CHAT_NORMAL

                        packet.WriteString(text); // Send original full command string, e.g., "/zone 1"

                        netMgr.SendPacket(packet);

                    }

                    break;

            }

        }

        /// <summary>

        /// C++ birebir: MsgSend_StateChange(N3_SP_STATE_CHANGE_ACTION, iAction)

        /// GameProcMain.cpp satır 5982-5986:

        /// if (PSA_BASIC && PSM_STOP) MsgSend_StateChange(N3_SP_STATE_CHANGE_ACTION, 1+(eCmd-CMD_GREETING))

        /// </summary>

        private void SendEmoteAction(int iAction)

        {

            var netMgr = KONetworkManager.Instance;

            if (netMgr == null) return;

            // C++ satır 5982-5983 birebir: PSA_BASIC && PSM_STOP guard

            // if (s_pPlayer->State() == PSA_BASIC && s_pPlayer->StateMove() == PSM_STOP)

            var playerEmote = GameObject.FindWithTag("Player");

            if (playerEmote != null)

            {

                var pcEmote = playerEmote.GetComponent<EntropyOnline.Character.PlayerController>();

                if (pcEmote != null)

                {

                    if (pcEmote.State() != EntropyOnline.Character.PlayerStateAction.PSA_BASIC ||

                        pcEmote.StateMove() != EntropyOnline.Character.PlayerStateMove.PSM_STOP)

                    {

                        return;

                    }

                }

            }

            using var packet = new KOPacketWriter(WizOpcode.WIZ_STATE_CHANGE);

            packet.WriteByte(3); // N3_SP_STATE_CHANGE_ACTION=3

            packet.WriteInt32(iAction);

            netMgr.SendPacket(packet);

        }

        // ================================================

        // ShowOkCancelDialog kaldırıldı → KOMessageBox.Instance.ShowYesNo() kullanılıyor (co_MsgBoxOkCancel_us.uif)

        // ================================================

        // Mobil Adaptasyon: Toast mesajı — kullanıcıya kısa bilgilendirme

        // Mevcut chat sistemini kullanarak SYSTEM mesajı gösterir.

        // ================================================

        /// <summary>

        /// Kullanıcıya kısa bilgilendirme mesajı göster.

        /// Chat alanına SYSTEM mesajı olarak eklenir.

        /// </summary>

        public void ShowToast(string message)

        {

            // Chat sistemine SYSTEM mesajı olarak ekle (channel 0 = system)

            AddChatMessage(0, $"<color=#FFCC00>[System]</color> {message}");

        }

