        private void BindMerchantSetupElements(Transform root)

        {

            ModernizeMerchantSetupPanel(root);

            var btnOk = KOUIRenderer.FindChildButton(root, "btn_ok");

            if (btnOk != null)

            {

                btnOk.onClick.AddListener(() =>

                {

                    var editMsg = KOUIRenderer.FindChildByID(root, "edit_message")?.GetComponent<InputField>();

                    string msg = editMsg != null ? editMsg.text : string.Empty;

                    KOMerchantManager.Instance?.SendMerchantInsert(msg);

                });

            }

            var btnCancel = KOUIRenderer.FindChildButton(root, "btn_cancel");

            if (btnCancel != null)

            {

                btnCancel.onClick.AddListener(() =>

                {

                    KOMerchantManager.Instance?.SendMerchantClose();

                    ShowMerchantSetup(false);

                });

            }

            // Bind inventory slots (a0..a27)

            for (int i = 0; i < 28; i++)

            {

                var slotObj = KOUIRenderer.FindChildByID(root, $"a{i}");

                if (slotObj != null)

                {

                    var img = slotObj.gameObject.GetComponent<Image>();

                    if (img == null)

                    {

                        img = slotObj.gameObject.AddComponent<Image>();

                        img.color = new Color(0f, 0f, 0f, 0.005f); // invisible but raycast target

                    }

                    img.raycastTarget = true;

                    var handler = slotObj.gameObject.GetComponent<KOItemSlotHandler>();

                    if (handler == null) handler = slotObj.gameObject.AddComponent<KOItemSlotHandler>();

                    handler.slotType = KOItemSlotHandler.SlotType.MerchantSetupInvSlot;

                    handler.slotIndex = i;

                    var dragHandler = slotObj.gameObject.GetComponent<KOItemDragHandler>();

                    if (dragHandler == null) dragHandler = slotObj.gameObject.AddComponent<KOItemDragHandler>();

                    dragHandler.district = (KOItemDragHandler.SlotDistrict)3; // MerchantSetupInvSlot fallback

                    dragHandler.slotIndex = i;

                }

            }

            // Bind merchant slots (at0..at11)

            for (int i = 0; i < 12; i++)

            {

                var slotObj = KOUIRenderer.FindChildByID(root, $"at{i}");

                if (slotObj != null)

                {

                    var img = slotObj.gameObject.GetComponent<Image>();

                    if (img == null)

                    {

                        img = slotObj.gameObject.AddComponent<Image>();

                        img.color = new Color(0f, 0f, 0f, 0.005f); // invisible but raycast target

                    }

                    img.raycastTarget = true;

                    var handler = slotObj.gameObject.GetComponent<KOItemSlotHandler>();

                    if (handler == null) handler = slotObj.gameObject.AddComponent<KOItemSlotHandler>();

                    handler.slotType = KOItemSlotHandler.SlotType.MerchantSetupSlot;

                    handler.slotIndex = i;

                    var dropTarget = slotObj.gameObject.GetComponent<KOMerchantDropTarget>();

                    if (dropTarget == null) dropTarget = slotObj.gameObject.AddComponent<KOMerchantDropTarget>();

                    dropTarget.merchantSlotIndex = i;

                }

            }

        }

        private void BindStallViewElements(Transform root)

        {

            ModernizeStallViewPanel(root);

            var btnOk = KOUIRenderer.FindChildButton(root, "btn_ok");

            if (btnOk != null)

            {

                btnOk.onClick.AddListener(() =>

                {

                    KOMerchantManager.Instance?.SendMerchantTradeCancel();

                    ShowStallView(false);

                });

            }

            // Bind buyer inventory slots (a0..a27)

            for (int i = 0; i < 28; i++)

            {

                var slotObj = KOUIRenderer.FindChildByID(root, $"a{i}");

                if (slotObj != null)

                {

                    var img = slotObj.gameObject.GetComponent<Image>();

                    if (img == null)

                    {

                        img = slotObj.gameObject.AddComponent<Image>();

                        img.color = new Color(0f, 0f, 0f, 0.005f); // invisible but raycast target

                    }

                    img.raycastTarget = true;

                    var handler = slotObj.gameObject.GetComponent<KOItemSlotHandler>();

                    if (handler == null) handler = slotObj.gameObject.AddComponent<KOItemSlotHandler>();

                    handler.slotType = KOItemSlotHandler.SlotType.BagSlot;

                    handler.slotIndex = i;

                    if (slotObj.gameObject.GetComponent<KOItemDragDrop>() == null)

                        slotObj.gameObject.AddComponent<KOItemDragDrop>();

                }

            }

            // Bind stall slots (at0..at11)

            for (int i = 0; i < 12; i++)

            {

                var slotObj = KOUIRenderer.FindChildByID(root, $"at{i}");

                if (slotObj != null)

                {

                    var img = slotObj.gameObject.GetComponent<Image>();

                    if (img == null)

                    {

                        img = slotObj.gameObject.AddComponent<Image>();

                        img.color = new Color(0f, 0f, 0f, 0.005f); // invisible but raycast target

                    }

                    img.raycastTarget = true;

                    var handler = slotObj.gameObject.GetComponent<KOItemSlotHandler>();

                    if (handler == null) handler = slotObj.gameObject.AddComponent<KOItemSlotHandler>();

                    handler.slotType = KOItemSlotHandler.SlotType.StallViewSlot;

                    handler.slotIndex = i;

                    if (slotObj.gameObject.GetComponent<KOItemDragDrop>() == null)

                        slotObj.gameObject.AddComponent<KOItemDragDrop>();

                }

            }

        }

        public void ShowMerchantSetup(bool show)

        {

            if (_uiMerchantSetup == null) return;

            _uiMerchantSetup.SetActive(show);

            if (show)

            {

                OnPanelOpened(_uiMerchantSetup);

                var editMsg = KOUIRenderer.FindChildByID(_uiMerchantSetup.transform, "edit_message")?.GetComponent<InputField>();

                if (editMsg != null) editMsg.text = "Selling Merchant";

                RefreshMerchantSetupUI();

