        private List<GameObject> _merchantSetupIcons = new List<GameObject>();

        public void RefreshMerchantSetupUI()

        {

            if (_uiMerchantSetup == null || !_uiMerchantSetup.activeSelf) return;

            // Clear old icons

            foreach (var icon in _merchantSetupIcons)

            {

                if (icon != null) Destroy(icon);

            }

            _merchantSetupIcons.Clear();

            // Refresh merchant slots (at0..at11)

            var setupItems = KOMerchantManager.Instance?.SellingSetupItems;

            for (int i = 0; i < 12; i++)

            {

                var slotObj = KOUIRenderer.FindChildByID(_uiMerchantSetup.transform, $"at{i}");

                var priceText = KOUIRenderer.FindChildText(_uiMerchantSetup.transform, $"st{i}");

                if (setupItems != null && i < setupItems.Length && !setupItems[i].IsEmpty)

                {

                    var item = setupItems[i];

                    var iconSprite = KOItemIconLoader.LoadItemIcon(ResolveIconId(item.ItemId));

                    var iconObj = new GameObject($"MerchantSetupIcon_{i}");

                    iconObj.transform.SetParent(slotObj, false);

                    _merchantSetupIcons.Add(iconObj);

                    var rt = iconObj.AddComponent<RectTransform>();

                    rt.anchorMin = Vector2.zero; rt.anchorMax = Vector2.one;

                    rt.offsetMin = Vector2.zero; rt.offsetMax = Vector2.zero;

                    var img = iconObj.AddComponent<Image>();

                    img.sprite = iconSprite;

                    img.preserveAspect = true;

                    img.raycastTarget = false; // so slot handler click gets it

                    // Update slot handler data

                    var handler = slotObj.GetComponent<KOItemSlotHandler>();

                    if (handler != null)

                    {

                        handler.tooltipItemDefId = item.ItemId;

                        handler.itemData = new InventoryItemData { ItemDefId = item.ItemId, StackCount = (short)item.Count };

                    }

                    if (priceText != null)

                        priceText.text = item.Price.ToString("N0");

                    // Count text for stackable

                    if (item.Count > 1)

                    {

                        var countObj = new GameObject("Count");

                        countObj.transform.SetParent(iconObj.transform, false);

                        var countRT = countObj.AddComponent<RectTransform>();

                        countRT.anchorMin = new Vector2(0, 0); countRT.anchorMax = new Vector2(1, 0.4f);

                        countRT.offsetMin = Vector2.zero; countRT.offsetMax = Vector2.zero;

                        var countTxt = countObj.AddComponent<Text>();

                        countTxt.text = item.Count.ToString();

                        countTxt.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");

                        countTxt.fontSize = 10;

                        countTxt.color = Color.white;

                        countTxt.alignment = TextAnchor.LowerRight;

                        countTxt.raycastTarget = false;

                    }

                }

                else

                {

                    var handler = slotObj?.GetComponent<KOItemSlotHandler>();

                    if (handler != null)

                    {

                        handler.tooltipItemDefId = 0;

                        handler.itemData = null;

                    }

                    if (priceText != null)

                        priceText.text = "";

                }

            }

            // Refresh inventory slots (a0..a27)

            var koInv = KOInventory.Instance;

            for (int i = 0; i < 28; i++)

            {

                var slotObj = KOUIRenderer.FindChildByID(_uiMerchantSetup.transform, $"a{i}");

                if (slotObj == null) continue;

                var slotItem = koInv != null ? koInv.m_pMyInvWnd[i] : null;

                if (slotItem != null && !slotItem.IsEmpty)

                {

                    var item = slotItem.serverData;

                    var iconSprite = KOItemIconLoader.LoadItemIcon(ResolveIconId(slotItem.itemId));

                    var iconObj = new GameObject($"MerchantSetupInvIcon_{i}");

                    iconObj.transform.SetParent(slotObj, false);

                    _merchantSetupIcons.Add(iconObj);

                    var rt = iconObj.AddComponent<RectTransform>();

                    rt.anchorMin = Vector2.zero; rt.anchorMax = Vector2.one;

                    rt.offsetMin = Vector2.zero; rt.offsetMax = Vector2.zero;

                    var img = iconObj.AddComponent<Image>();

                    img.sprite = iconSprite;

                    img.preserveAspect = true;

                    img.raycastTarget = false;

                    // If item is already on merchant setup list, gray it out

                    bool isOnStall = false;

                    if (setupItems != null)

                    {

                        foreach (var setupItem in setupItems)

                        {

                            if (!setupItem.IsEmpty && setupItem.InvPos == i)

                            {

                                isOnStall = true;

                                break;

                            }

                        }

                    }

                    if (isOnStall)

                    {

                        img.color = new Color(0.6f, 0.6f, 0.6f, 0.8f);

                    }

                    var handler = slotObj.GetComponent<KOItemSlotHandler>();

                    if (handler != null)

                    {

                        handler.tooltipItemDefId = slotItem.itemId;

                        handler.itemData = item;

                    }

                    if (slotItem.count > 1)

                    {

                        var countObj = new GameObject("Count");

                        countObj.transform.SetParent(iconObj.transform, false);

                        var countRT = countObj.AddComponent<RectTransform>();

                        countRT.anchorMin = new Vector2(0, 0); countRT.anchorMax = new Vector2(1, 0.4f);

                        countRT.offsetMin = Vector2.zero; countRT.offsetMax = Vector2.zero;

                        var countTxt = countObj.AddComponent<Text>();

                        countTxt.text = slotItem.count.ToString();

                        countTxt.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");

                        countTxt.fontSize = 10;

                        countTxt.color = Color.white;

                        countTxt.alignment = TextAnchor.LowerRight;

                        countTxt.raycastTarget = false;

                    }

                }

                else

                {

                    var handler = slotObj.GetComponent<KOItemSlotHandler>();

                    if (handler != null)

                    {

                        handler.tooltipItemDefId = 0;

                        handler.itemData = null;

                    }

                }

            }

        }

