        private string GetFormattedItemName(int itemId)

        {

            var basic = KOImport.ItemDataManager.GetItemBasic(itemId);

            if (basic == null) return $"Item #{itemId}";

            var ext = KOImport.ItemDataManager.GetItemExt(itemId);

            byte magicOrRare = ext != null ? ext.ByMagicOrRare : (byte)0;

            string nameText;

            if (magicOrRare != 4) // 4 = ITEM_ATTRIB_UNIQUE

            {

                string suffix = "";

                int extMod = 0;

                if (ext != null)

                {

                    extMod = ext.DwID % 10;

                    if (extMod == 0)

                    {

                        int lastTwo = ext.DwID % 100;

                        if (lastTwo == 10 || lastTwo == 20 || lastTwo == 30 || lastTwo == 40 || lastTwo == 50)

                            extMod = 10;

                    }

                }

                if (extMod != 0)

                    suffix = $"(+{extMod})";

                nameText = basic.SzName + suffix;

            }

            else

            {

                nameText = (ext != null && !string.IsNullOrEmpty(ext.SzHeader)) ? ext.SzHeader : basic.SzName;

            }

            return nameText;

        }

        public void PromptMerchantItemAdd(int srcInvPos, int destMerchantSlot)

        {

            var koInv = KOInventory.Instance;

            if (koInv == null || srcInvPos < 0 || srcInvPos >= 28) return;

            var slotItem = koInv.m_pMyInvWnd[srcInvPos];

            if (slotItem == null || slotItem.IsEmpty) return;

            _merchantPendingSrcSlot = srcInvPos;

            _merchantPendingDstSlot = destMerchantSlot;

            _merchantPendingItemId = slotItem.itemId;

            // Check if item is already placed on a merchant slot

            var setupItems = KOMerchantManager.Instance?.SellingSetupItems;

            if (setupItems != null)

            {

                foreach (var sItem in setupItems)

                {

                    if (!sItem.IsEmpty && sItem.InvPos == srcInvPos)

                    {

                        ShowToast("This item is already placed in the stall.");

                        return;

                    }

                }

            }

            bool isCountable = slotItem.count > 1;

            if (isCountable)

            {

                _countableEditMode = CountableEditMode.MerchantItemCount;

                _itemCountMax = (short)slotItem.count;

                ShowCountableEdit(false);

            }

            else

            {

                _merchantPendingItemCount = 1;

                PromptMerchantItemPrice();

            }

        }

        private void PromptMerchantItemPrice()

        {

            _countableEditMode = CountableEditMode.MerchantItemPrice;

            ShowCountableEdit(true); // input unit price, so show gold message

        }

        public void PromptAHRegisterItem(int srcInvPos)

        {

            var koInv = KOInventory.Instance;

            if (koInv == null || srcInvPos < 0 || srcInvPos >= 28) return;

            var slotItem = koInv.m_pMyInvWnd[srcInvPos];

            if (slotItem == null || slotItem.IsEmpty) return;

            _ahPendingSrcSlot = srcInvPos;

            _ahPendingItemId = slotItem.itemId;

            bool isCountable = false;

            if (KOInventory.s_pTbl_Items_Basic.TryGetValue((uint)(slotItem.itemId / 1000 * 1000), out var basic))

            {

                isCountable = (basic.byClass == 95 || basic.byClass == 97 || basic.byClass == 98 || basic.byClass == 255); // potions, arrows, scrolls, stackables

            }

            if (isCountable && slotItem.count > 1)

            {

                _countableEditMode = CountableEditMode.AHRegisterItemCount;

                _itemCountMax = (short)slotItem.count;

                ShowCountableEdit(false);

            }

            else

            {

                _ahPendingItemCount = slotItem.count;

                PromptAHRegisterItemPrice();

            }

        }

        private void PromptAHRegisterItemPrice()

        {

            _countableEditMode = CountableEditMode.AHRegisterItemPrice;

            ShowCountableEdit(true);

        }

        public void HandleMerchantSetupInvDoubleTap(int slotIndex)

        {

            // Find first empty merchant slot

            int emptySetupSlot = -1;

            var setupItems = KOMerchantManager.Instance?.SellingSetupItems;

            if (setupItems != null)

            {

                for (int i = 0; i < 12; i++)

                {

                    if (setupItems[i] == null || setupItems[i].IsEmpty)

                    {

                        emptySetupSlot = i;

                        break;

                    }

                }

            }

            if (emptySetupSlot >= 0)

            {

                PromptMerchantItemAdd(slotIndex, emptySetupSlot);

            }

            else

            {

                ShowToast("Stall slots are full.");

            }

        }

        public void HandleStallViewSlotDoubleTap(int slotIndex)

        {

            var manager = KOMerchantManager.Instance;

            if (manager == null) return;

            var targetItems = manager.TargetMerchantItems;

            if (targetItems == null || slotIndex < 0 || slotIndex >= targetItems.Length) return;

            var item = targetItems[slotIndex];

            if (item == null || item.IsEmpty || item.Count <= 0) return;

            // Find first empty inventory slot

            int emptyInvSlot = GetStallInvDestinationIndex(item.ItemId, 0); // fallback mode = 0

            if (emptyInvSlot < 0)

            {

                ShowToast("Not enough space in inventory.");

                return;

            }

            _stallPendingSlot = slotIndex;

            _stallPendingItemId = item.ItemId;

            _stallPendingDestSlot = -1; // -1 means auto-find slot on confirm

            var itemTbl = KOImport.ItemDataManager.GetItemBasic(item.ItemId);

            bool isCountable = item.Count > 1 || (itemTbl != null && itemTbl.ByContable > 0);

            if (isCountable)

            {

                _countableEditMode = CountableEditMode.StallBuyCount;

                _itemCountMax = item.Count;

                ShowCountableEdit(false); // input quantity

            }

            else

            {

                // Buy 1 with confirmation dialog

                string itemName = GetFormattedItemName(item.ItemId);

                string msg = $"Do you want to buy {itemName} for {item.Price:N0} Gold?";

                if (KOMessageBox.Instance != null)

                {

                    KOMessageBox.Instance.ShowYesNo(msg, "Buy Item", MsgBoxBehavior.BEHAVIOR_NOTHING, onYes: () => {

                        KOMerchantManager.Instance?.SendMerchantItemBuy(item.ItemId, 1, (byte)slotIndex, (byte)emptyInvSlot);

                    }, countdownDuration: 5, forceFixedCenter: true);

                }

                else

                {

                    Debug.LogWarning("[KOUIMGR] KOMessageBox.Instance is null! Buying instantly without confirmation dialog.");

                    KOMerchantManager.Instance?.SendMerchantItemBuy(item.ItemId, 1, (byte)slotIndex, (byte)emptyInvSlot);

                }

            }

        }

        public void HandleStallViewSlotDragDrop(int stallSlot, int destInvSlot)

        {

            var manager = KOMerchantManager.Instance;

            if (manager == null) return;

            var targetItems = manager.TargetMerchantItems;

            if (targetItems == null || stallSlot < 0 || stallSlot >= targetItems.Length) return;

            var item = targetItems[stallSlot];

            if (item == null || item.IsEmpty || item.Count <= 0) return;

            // Check if target slot is empty in inventory

            if (KOInventory.Instance != null)

            {

                var slotItem = KOInventory.Instance.m_pMyInvWnd[destInvSlot];

                if (slotItem != null && !slotItem.IsEmpty && slotItem.itemId != item.ItemId)

                {

                    ShowToast("Target inventory slot is not empty.");

                    return;

                }

            }

            _stallPendingSlot = stallSlot;

            _stallPendingItemId = item.ItemId;

            _stallPendingDestSlot = destInvSlot; // Save target slot!

            var itemTbl = KOImport.ItemDataManager.GetItemBasic(item.ItemId);

            bool isCountable = item.Count > 1 || (itemTbl != null && itemTbl.ByContable > 0);

            if (isCountable)

            {

                _countableEditMode = CountableEditMode.StallBuyCount;

                _itemCountMax = item.Count;

                ShowCountableEdit(false); // input quantity

            }

            else

            {

                // Buy 1 with confirmation dialog

                string itemName = GetFormattedItemName(item.ItemId);

                string msg = $"Do you want to buy {itemName} for {item.Price:N0} Gold?";

                if (KOMessageBox.Instance != null)

                {

                    KOMessageBox.Instance.ShowYesNo(msg, "Buy Item", MsgBoxBehavior.BEHAVIOR_NOTHING, onYes: () => {

                        KOMerchantManager.Instance?.SendMerchantItemBuy(item.ItemId, 1, (byte)stallSlot, (byte)destInvSlot);

                    }, countdownDuration: 5, forceFixedCenter: true);

                }

                else

                {

                    Debug.LogWarning("[KOUIMGR] KOMessageBox.Instance is null! Buying instantly without confirmation dialog.");

                    KOMerchantManager.Instance?.SendMerchantItemBuy(item.ItemId, 1, (byte)stallSlot, (byte)destInvSlot);

                }

            }

        }

        public void ToggleQuestJournal()

        {

            if (_uiQuestJournal == null)

            {

                _uiQuestJournal = QuestJournalUI.CreatePanel(_canvas.transform);

                _uiQuestJournal.SetActive(false);

            }

            if (_uiQuestJournal != null)

            {

                bool nextState = !_uiQuestJournal.activeSelf;

                _uiQuestJournal.SetActive(nextState);

                if (nextState)

                {

                    _uiQuestJournal.GetComponent<QuestJournalUI>()?.RefreshJournal();

                }

            }

        }

        public void OpenQuestJournalWithQuest(int questId)

        {

            if (_uiQuestJournal == null)

            {

                _uiQuestJournal = QuestJournalUI.CreatePanel(_canvas.transform);

                _uiQuestJournal.SetActive(false);

            }

            if (_uiQuestJournal != null)

            {

                _uiQuestJournal.SetActive(true);

                var journal = _uiQuestJournal.GetComponent<QuestJournalUI>();

                if (journal != null)

                {

                    journal.ShowQuestAndExpand(questId);

                }

            }

        }

        private void CreateQuestTracker()

        {

            if (_uiQuestTracker != null) return;

            _uiQuestTracker = new GameObject("QuestTrackerHUD");

            _uiQuestTracker.transform.SetParent(_hudContainer != null ? _hudContainer.transform : _canvas.transform, false);

            _uiQuestTracker.AddComponent<QuestTrackerHUD>();

            // Position it below the party list at x=5, y=200

            SetKOPosition(_uiQuestTracker, 5, 200);

            if (_canvas != null && _canvas.scaleFactor > 0f)

            {

                float s = _canvas.scaleFactor;

                _uiQuestTracker.transform.localScale = new Vector3(1f / s, 1f / s, 1f / s);

                var rt = _uiQuestTracker.GetComponent<RectTransform>();

                if (rt != null)

                {

                    rt.anchoredPosition = new Vector2(5f / s, -200f / s);

                }

            }

        }

