        private Dictionary<string, Sprite> _skillThemeSpriteCache = new Dictionary<string, Sprite>();

        private Sprite GetVerticalGradientSprite(string key, int w, int h, Color topColor, Color bottomColor)

        {

            if (_skillThemeSpriteCache.TryGetValue(key, out Sprite sp))

                return sp;

            Texture2D tex = new Texture2D(w, h, TextureFormat.RGBA32, false);

            tex.filterMode = FilterMode.Bilinear;

            tex.wrapMode = TextureWrapMode.Clamp;

            for (int y = 0; y < h; y++)

            {

                float t = y / (float)(h - 1);

                Color c = Color.Lerp(bottomColor, topColor, t); // y=0 is bottom, y=h-1 is top

                for (int x = 0; x < w; x++)

                {

                    tex.SetPixel(x, y, c);

                }

            }

            tex.Apply();

            var newSp = Sprite.Create(tex, new Rect(0, 0, w, h), new Vector2(0.5f, 0.5f));

            _skillThemeSpriteCache[key] = newSp;

            return newSp;

        }

        public Sprite GetFadeGradientSprite(string key, int w, int h, Color fillColor, Color borderGoldColor, int borderWidth)

        {

            if (_skillThemeSpriteCache.TryGetValue(key, out Sprite sp) && sp != null)

                return sp;

            Texture2D tex = new Texture2D(w, h, TextureFormat.RGBA32, false);

            tex.filterMode = FilterMode.Bilinear;

            tex.wrapMode = TextureWrapMode.Clamp;

            for (int y = 0; y < h; y++)

            {

                for (int x = 0; x < w; x++)

                {

                    // Merkezden yatayda uzaklık oranı (0.0 merkezde, 1.0 en uçlarda)

                    float distRatio = Mathf.Abs(x - w / 2f) / (w / 2f);

                    // Cosine tabanlı pürüzsüz sönümlenme çarpanı

                    float fade = Mathf.Cos(distRatio * Mathf.PI / 2f);

                    Color c = Color.clear;

                    // Üst veya alt sınırda ayraç çizgisi varsa

                    if (y >= h - borderWidth || y < borderWidth)

                    {

                        c = new Color(borderGoldColor.r, borderGoldColor.g, borderGoldColor.b, borderGoldColor.a * fade);

                    }

                    else

                    {

                        c = new Color(fillColor.r, fillColor.g, fillColor.b, fillColor.a * fade);

                    }

                    tex.SetPixel(x, y, c);

                }

            }

            tex.Apply();

            var newSp = Sprite.Create(tex, new Rect(0, 0, w, h), new Vector2(0.5f, 0.5f));

            _skillThemeSpriteCache[key] = newSp;

            return newSp;

        }

        public Sprite GetOneSidedFadeGradientSprite(string key, int w, int h, Color fillColor, Color borderGoldColor, int borderWidth)
        {
            if (_skillThemeSpriteCache.TryGetValue(key, out Sprite sp) && sp != null)
                return sp;

            Texture2D tex = new Texture2D(w, h, TextureFormat.RGBA32, false);
            tex.filterMode = FilterMode.Bilinear;
            tex.wrapMode = TextureWrapMode.Clamp;

            for (int y = 0; y < h; y++)
            {
                for (int x = 0; x < w; x++)
                {
                    float t = (float)x / w;
                    float fade = Mathf.Cos(t * Mathf.PI / 2f); // Fades from 1.0 at x=0 to 0.0 at x=w

                    Color c = Color.clear;
                    if (y >= h - borderWidth || y < borderWidth)
                    {
                        c = new Color(borderGoldColor.r, borderGoldColor.g, borderGoldColor.b, borderGoldColor.a * fade);
                    }
                    else
                    {
                        c = new Color(fillColor.r, fillColor.g, fillColor.b, fillColor.a * fade);
                    }
                    tex.SetPixel(x, y, c);
                }
            }
            tex.Apply();

            var newSp = Sprite.Create(tex, new Rect(0, 0, w, h), new Vector2(0.5f, 0.5f));
            _skillThemeSpriteCache[key] = newSp;
            return newSp;
        }

        public Sprite GetSkillThemeRoundedRectSprite(string key, int w, int h, int radius, Color fillColor, Color borderColor, int borderWidth)

        {

            if (_skillThemeSpriteCache.TryGetValue(key, out Sprite sp) && sp != null)

                return sp;

            Texture2D tex = new Texture2D(w, h, TextureFormat.RGBA32, false);

            tex.filterMode = FilterMode.Bilinear;

            tex.wrapMode = TextureWrapMode.Clamp;

            for (int y = 0; y < h; y++)

            {

                for (int x = 0; x < w; x++)

                {

                    float alpha = 1.0f;

                    if (radius > 0)

                    {

                        float dx = 0, dy = 0;

                        bool inCorner = false;

                        if (x < radius && y < radius) { dx = radius - x; dy = radius - y; inCorner = true; }

                        else if (x >= w - radius && y < radius) { dx = radius - (w - x - 1); dy = radius - y; inCorner = true; }

                        else if (x < radius && y >= h - radius) { dx = radius - x; dy = radius - (h - y - 1); inCorner = true; }

                        else if (x >= w - radius && y >= h - radius) { dx = radius - (w - x - 1); dy = radius - (h - y - 1); inCorner = true; }

                        if (inCorner)

                        {

                            float dist = Mathf.Sqrt(dx * dx + dy * dy);

                            // Kenar yumuşatma (Anti-Aliasing): 1 piksellik geçiş alanı

                            alpha = Mathf.Clamp01(radius + 0.5f - dist);

                        }

                    }

                    if (alpha > 0f)

                    {

                        bool isBorder = false;

                        if (borderWidth > 0)

                        {

                            if (x < borderWidth || x >= w - borderWidth || y < borderWidth || y >= h - borderWidth)

                                isBorder = true;

                            else if (radius > 0)

                            {

                                float dx = 0, dy = 0;

                                bool inCorner = false;

                                if (x < radius && y < radius) { dx = radius - x; dy = radius - y; inCorner = true; }

                                else if (x >= w - radius && y < radius) { dx = radius - (w - x - 1); dy = radius - y; inCorner = true; }

                                else if (x < radius && y >= h - radius) { dx = radius - x; dy = radius - (h - y - 1); inCorner = true; }

                                else if (x >= w - radius && y >= h - radius) { dx = radius - (w - x - 1); dy = radius - (h - y - 1); inCorner = true; }

                                if (inCorner)

                                {

                                    float dist = Mathf.Sqrt(dx * dx + dy * dy);

                                    if (dist >= radius - borderWidth)

                                        isBorder = true;

                                }

                            }

                        }

                        Color c = isBorder ? borderColor : fillColor;

                        c.a *= alpha; // Saydamlık geçişini uygula

                        tex.SetPixel(x, y, c);

                    }

                    else

                    {

                        tex.SetPixel(x, y, Color.clear);

                    }

                }

            }

            tex.Apply();

            Sprite sprite = Sprite.Create(tex, new Rect(0, 0, w, h), new Vector2(0.5f, 0.5f));

            _skillThemeSpriteCache[key] = sprite;

            return sprite;

        }

        private Sprite GetSkillThemeArrowSprite(string key, int w, int h, Color fillColor, Color borderColor, int borderWidth, bool pointingLeft)

        {

            if (_skillThemeSpriteCache.TryGetValue(key, out Sprite sp))

                return sp;

            Texture2D tex = new Texture2D(w, h, TextureFormat.RGBA32, false);

            tex.filterMode = FilterMode.Bilinear;

            tex.wrapMode = TextureWrapMode.Clamp;

            int centerY = h / 2;

            int arrowTipX = pointingLeft ? (w / 3) : (2 * w / 3);

            int arrowBaseX = pointingLeft ? (2 * w / 3) : (w / 3);

            for (int y = 0; y < h; y++)

            {

                for (int x = 0; x < w; x++)

                {

                    Color pxColor = fillColor;

                    bool isBorder = false;

                    if (x < borderWidth || x >= w - borderWidth || y < borderWidth || y >= h - borderWidth)

                    {

                        isBorder = true;

                    }

                    bool inArrow = false;

                    int dy = Mathf.Abs(y - centerY);

                    if (pointingLeft)

                    {

                        if (x >= arrowTipX && x <= arrowBaseX)

                        {

                            int allowedWidth = x - arrowTipX;

                            if (dy <= allowedWidth)

                                inArrow = true;

                        }

                    }

                    else

                    {

                        if (x >= arrowBaseX && x <= arrowTipX)

                        {

                            int allowedWidth = arrowTipX - x;

                            if (dy <= allowedWidth)

                                inArrow = true;

                        }

                    }

                    if (inArrow)

                    {

                        pxColor = borderColor;

                    }

                    else if (isBorder)

                    {

                        pxColor = borderColor;

                    }

                    tex.SetPixel(x, y, pxColor);

                }

            }

            tex.Apply();

            Sprite newSp = Sprite.Create(tex, new Rect(0, 0, w, h), new Vector2(0.5f, 0.5f));

            _skillThemeSpriteCache[key] = newSp;

            return newSp;

        }

        private Sprite GetSkillThemeGlassPanelBgSprite(string key, int w, int h, Color centerColor, Color edgeColor, Color borderColor, int borderWidth)

        {

            if (_skillThemeSpriteCache.TryGetValue(key, out Sprite sp))

                return sp;

            Texture2D tex = new Texture2D(w, h, TextureFormat.RGBA32, false);

            tex.filterMode = FilterMode.Bilinear;

            tex.wrapMode = TextureWrapMode.Clamp;

            float cx = w / 2f;

            float cy = h / 2f;

            float maxDist = Mathf.Sqrt(cx * cx + cy * cy);

            for (int y = 0; y < h; y++)

            {

                for (int x = 0; x < w; x++)

                {

                    bool isBorder = false;

                    bool isInnerHighlight = false;

                    // 1. Check outer border

                    if (borderWidth > 0)

                    {

                        if (x < borderWidth || x >= w - borderWidth || y < borderWidth || y >= h - borderWidth)

                        {

                            isBorder = true;

                        }

                        // Inner light refraction edge (left and top inner border)

                        else if ((x == borderWidth || y == h - borderWidth - 1) && x < w - borderWidth - 1 && y > borderWidth)

                        {

                            isInnerHighlight = true;

                        }

                    }

                    if (isBorder)

                    {

                        tex.SetPixel(x, y, borderColor);

                    }

                    else if (isInnerHighlight)

                    {

                        // Soft white refraction highlight on the inner edge of top and left

                        Color innerHighlightCol = new Color(1f, 1f, 1f, 0.42f); // 42% opaque white refraction edge

                        tex.SetPixel(x, y, innerHighlightCol);

                    }

                    else

                    {

                        // 2. Radial gradient background (center to edges)

                        float dx = x - cx;

                        float dy = y - cy;

                        float dist = Mathf.Sqrt(dx * dx + dy * dy);

                        float t = Mathf.Clamp01(dist / maxDist);

                        Color fillColor = Color.Lerp(centerColor, edgeColor, t);

                        // 3. Circular/Spherical glass specular highlight (Top-Left)

                        float hx = w * 0.22f;

                        float hy = h * 0.82f;

                        float hdx = x - hx;

                        float hdy = y - hy;

                        float distToHighlight = Mathf.Sqrt(hdx * hdx + hdy * hdy);

                        float highlightRadius = w * 0.45f; // size of the highlight circle

                        if (distToHighlight < highlightRadius)

                        {

                            float factor = 1f - (distToHighlight / highlightRadius);

                            factor = factor * factor * (3f - 2f * factor); // Smoothstep

                            float gloss = factor * 0.16f; // Max 16% soft white circular specular highlight

                            fillColor.r = Mathf.Clamp01(fillColor.r + gloss);

                            fillColor.g = Mathf.Clamp01(fillColor.g + gloss * 0.95f);

                            fillColor.b = Mathf.Clamp01(fillColor.b + gloss * 0.90f);

                            fillColor.a = Mathf.Clamp01(fillColor.a + gloss * 0.3f);

                        }

                        tex.SetPixel(x, y, fillColor);

                    }

                }

            }

            tex.Apply();

            Sprite sprite = Sprite.Create(tex, new Rect(0, 0, w, h), new Vector2(0.5f, 0.5f));

            _skillThemeSpriteCache[key] = sprite;

            return sprite;

        }

        public Sprite GetSkillThemeGlassSlotSprite(string key, int size)

        {

            if (_skillThemeSpriteCache.TryGetValue(key, out Sprite sp))

                return sp;

            Texture2D tex = new Texture2D(size, size, TextureFormat.RGBA32, false);

            tex.filterMode = FilterMode.Bilinear;

            tex.wrapMode = TextureWrapMode.Clamp;

            float center = size / 2f;

            float radius = center;

            float borderWidth = 1f;

            // Clean, deep dark anthracite-black background

            Color centerColor = new Color(0.10f, 0.10f, 0.10f, 0.85f);

            Color edgeColor = new Color(0.04f, 0.04f, 0.04f, 0.95f);

            // Soft, faded bronze tint for horizontal & corners

            Color horizontalColor = new Color(0.24f, 0.20f, 0.12f, 0.80f);

            // Theme bronze/gold for vertical highlight (muted/dimmed)

            Color brightBronzeColor = new Color(0.48f, 0.38f, 0.18f, 0.85f);

            for (int y = 0; y < size; y++)

            {

                for (int x = 0; x < size; x++)

                {

                    bool isBorder = false;

                    bool isVertical = false;

                    if (x < borderWidth || x >= size - borderWidth)

                    {

                        isBorder = true;

                        isVertical = true;

                    }

                    if (y < borderWidth || y >= size - borderWidth)

                    {

                        isBorder = true;

                    }

                    if (isBorder)

                    {

                        Color borderPixelColor;

                        if (isVertical)

                        {

                            // Calculate normalized vertical distance from vertical center

                            float cy = (size - 1) / 2f;

                            float distY = Mathf.Abs(y - cy) / cy;

                            // Quadratic fade factor (1 at center, 0 at top/bottom ends)

                            float fade = Mathf.Clamp01(1f - distY * distY);

                            borderPixelColor = Color.Lerp(horizontalColor, brightBronzeColor, fade);

                        }

                        else

                        {

                            borderPixelColor = horizontalColor;

                        }

                        tex.SetPixel(x, y, borderPixelColor);

                    }

                    else

                    {

                        // Radial LERP

                        float dx = x - center;

                        float dy = y - center;

                        float dist = Mathf.Sqrt(dx * dx + dy * dy);

                        float maxDist = Mathf.Sqrt(2f) * center;

                        float t = Mathf.Clamp01(dist / maxDist);

                        Color fillColor = Color.Lerp(centerColor, edgeColor, t);

                        // Extremely subtle glass gloss reflection (Option 2 - max 4.5% opacity)

                        float hx = size * 0.35f;

                        float hy = size * 0.65f;

                        float hdx = x - hx;

                        float hdy = y - hy;

                        float distToHighlight = Mathf.Sqrt(hdx * hdx + hdy * hdy);

                        float highlightRadius = size * 0.35f;

                        if (distToHighlight < highlightRadius)

                        {

                            float factor = 1f - (distToHighlight / highlightRadius);

                            factor = factor * factor * (3f - 2f * factor);

                            float gloss = factor * 0.045f; // Max 4.5% extremely soft white highlight

                            fillColor.r = Mathf.Clamp01(fillColor.r + gloss);

                            fillColor.g = Mathf.Clamp01(fillColor.g + gloss * 0.95f);

                            fillColor.b = Mathf.Clamp01(fillColor.b + gloss * 0.90f);

                            fillColor.a = Mathf.Clamp01(fillColor.a + gloss * 0.15f);

                        }

                        tex.SetPixel(x, y, fillColor);

                    }

                }

            }

            tex.Apply();

            Sprite sprite = Sprite.Create(tex, new Rect(0, 0, size, size), new Vector2(0.5f, 0.5f));

            _skillThemeSpriteCache[key] = sprite;

            return sprite;

        }

        public Sprite GetSkillThemeHorizontalFadeLineSprite(string key, int w, int h, Color centerColor)

        {

            if (_skillThemeSpriteCache.TryGetValue(key, out Sprite sp))

                return sp;

            Texture2D tex = new Texture2D(w, h, TextureFormat.RGBA32, false);

            tex.filterMode = FilterMode.Bilinear;

            tex.wrapMode = TextureWrapMode.Clamp;

            for (int x = 0; x < w; x++)

            {

                float t = (float)x / (w - 1);

                float alpha = 1f - Mathf.Abs(t - 0.5f) * 2f;

                alpha = Mathf.SmoothStep(0f, 1f, alpha);

                Color col = new Color(centerColor.r, centerColor.g, centerColor.b, centerColor.a * alpha);

                for (int y = 0; y < h; y++)

                {

                    tex.SetPixel(x, y, col);

                }

            }

            tex.Apply();

            Sprite sprite = Sprite.Create(tex, new Rect(0, 0, w, h), new Vector2(0.5f, 0.5f));

            _skillThemeSpriteCache[key] = sprite;

            return sprite;

        }

        public void ForceEnableUIComponents(Transform root)

        {

            if (root == null) return;

            string name = root.gameObject.name;

            bool isOldBg = name.StartsWith("ui_Image_") || 

                           name.StartsWith("img_personaltrade_") || 

                           name.StartsWith("img_lowpart_") || 

                           name == "img_upgrade" || 

                           name == "img_inven01" || 

                           name == "img_result";

            if (!isOldBg)

            {

                var img = root.GetComponent<UnityEngine.UI.Image>();

                if (img != null) img.enabled = true;

                var raw = root.GetComponent<UnityEngine.UI.RawImage>();

                if (raw != null) raw.enabled = true;

            }

            var txt = root.GetComponent<UnityEngine.UI.Text>();

            if (txt != null) txt.enabled = true;

            var btn = root.GetComponent<UnityEngine.UI.Button>();

            if (btn != null) btn.enabled = true;

            for (int i = 0; i < root.childCount; i++)

            {

                ForceEnableUIComponents(root.GetChild(i));

            }

        }

        public Sprite GetSkillThemePanelBgSprite(string key, int w, int h, int radius, Color topColor, Color bottomColor, Color borderColor, int borderWidth)

        {

            if (_skillThemeSpriteCache.TryGetValue(key, out Sprite sp) && sp != null)

                return sp;

            int scale = 4; // 4x Supersampling for crystal-clear vector quality

            int sw = w * scale;

            int sh = h * scale;

            int sradius = radius * scale;

            int sborderWidth = borderWidth * scale;

            Texture2D tex = new Texture2D(sw, sh, TextureFormat.RGBA32, false);

            tex.filterMode = FilterMode.Bilinear;

            tex.wrapMode = TextureWrapMode.Clamp;

            for (int y = 0; y < sh; y++)

            {

                float t = (float)y / sh;

                Color fillColor = Color.Lerp(bottomColor, topColor, t);

                for (int x = 0; x < sw; x++)

                {

                    bool isCorner = false;

                    float dx = 0, dy = 0;

                    if (sradius > 0)

                    {

                        if (x < sradius && y < sradius) { dx = sradius - x; dy = sradius - y; isCorner = true; }

                        else if (x >= sw - sradius && y < sradius) { dx = sradius - (sw - x); dy = sradius - y; isCorner = true; }

                        else if (x < sradius && y >= sh - sradius) { dx = sradius - x; dy = sradius - (sh - y); isCorner = true; }

                        else if (x >= sw - sradius && y >= sh - sradius) { dx = sradius - (sw - x); dy = sradius - (sh - y); isCorner = true; }

                    }

                    if (isCorner)

                    {

                        float dist = Mathf.Sqrt(dx * dx + dy * dy);

                        float outerEdgeTransition = 1.5f; // Transition band in high-res pixels

                        float delta = dist - sradius;

                        if (delta >= outerEdgeTransition)

                        {

                            tex.SetPixel(x, y, Color.clear);

                        }

                        else

                        {

                            bool isBorder = false;

                            if (sborderWidth > 0 && dist >= (sradius - sborderWidth))

                            {

                                isBorder = true;

                            }

                            Color baseColor = isBorder ? borderColor : fillColor;

                            if (delta > -outerEdgeTransition)

                            {

                                float alphaPct = 1f - ((delta + outerEdgeTransition) / (2f * outerEdgeTransition));

                                baseColor.a *= Mathf.Clamp01(alphaPct);

                            }

                            tex.SetPixel(x, y, baseColor);

                        }

                    }

                    else

                    {

                        bool isBorder = false;

                        if (sborderWidth > 0)

                        {

                            if (x < sborderWidth || x >= sw - sborderWidth || y < sborderWidth || y >= sh - sborderWidth)

                                isBorder = true;

                        }

                        tex.SetPixel(x, y, isBorder ? borderColor : fillColor);

                    }

                }

            }

            tex.Apply();

            Sprite sprite = Sprite.Create(tex, new Rect(0, 0, sw, sh), new Vector2(0.5f, 0.5f));

            _skillThemeSpriteCache[key] = sprite;

            return sprite;

        }

        public Sprite GetSkillThemePanelBgSpriteBottomRound(string key, int w, int h, int radius, Color topColor, Color bottomColor, Color borderColor, int borderWidth)

        {

            if (_skillThemeSpriteCache.TryGetValue(key, out Sprite sp) && sp != null)

                return sp;

            int scale = 4; // 4x Supersampling for crystal-clear vector quality

            int sw = w * scale;

            int sh = h * scale;

            int sradius = radius * scale;

            int sborderWidth = borderWidth * scale;

            Texture2D tex = new Texture2D(sw, sh, TextureFormat.RGBA32, false);

            tex.filterMode = FilterMode.Bilinear;

            tex.wrapMode = TextureWrapMode.Clamp;

            for (int y = 0; y < sh; y++)

            {

                float t = (float)y / sh;

                Color fillColor = Color.Lerp(bottomColor, topColor, t);

                for (int x = 0; x < sw; x++)

                {

                    bool isCorner = false;

                    float dx = 0, dy = 0;

                    if (sradius > 0)

                    {

                        // Only round bottom corners

                        if (x < sradius && y < sradius) { dx = sradius - x; dy = sradius - y; isCorner = true; }

                        else if (x >= sw - sradius && y < sradius) { dx = sradius - (sw - x); dy = sradius - y; isCorner = true; }

                    }

                    if (isCorner)

                    {

                        float dist = Mathf.Sqrt(dx * dx + dy * dy);

                        float outerEdgeTransition = 1.5f; // Transition band in high-res pixels

                        float delta = dist - sradius;

                        if (delta >= outerEdgeTransition)

                        {

                            tex.SetPixel(x, y, Color.clear);

                        }

                        else

                        {

                            bool isBorder = false;

                            if (sborderWidth > 0 && dist >= (sradius - sborderWidth))

                            {

                                isBorder = true;

                            }

                            Color baseColor = isBorder ? borderColor : fillColor;

                            if (delta > -outerEdgeTransition)

                            {

                                float alphaPct = 1f - ((delta + outerEdgeTransition) / (2f * outerEdgeTransition));

                                baseColor.a *= Mathf.Clamp01(alphaPct);

                            }

                            tex.SetPixel(x, y, baseColor);

                        }

                    }

                    else

                    {

                        bool isBorder = false;

                        if (sborderWidth > 0)

                        {

                            if (x < sborderWidth || x >= sw - sborderWidth || y < sborderWidth || y >= sh - sborderWidth)

                                isBorder = true;

                        }

                        tex.SetPixel(x, y, isBorder ? borderColor : fillColor);

                    }

                }

            }

            tex.Apply();

            Sprite sprite = Sprite.Create(tex, new Rect(0, 0, sw, sh), new Vector2(0.5f, 0.5f));

            _skillThemeSpriteCache[key] = sprite;

            return sprite;

        }

        public Sprite GetSkillThemeFadingDividerSprite(string key, int w, int h, Color color)

        {

            if (_skillThemeSpriteCache.TryGetValue(key, out Sprite sp) && sp != null)

                return sp;

            Texture2D tex = new Texture2D(w, h, TextureFormat.RGBA32, false);

            tex.filterMode = FilterMode.Bilinear;

            tex.wrapMode = TextureWrapMode.Clamp;

            int center = w / 2;

            for (int y = 0; y < h; y++)

            {

                for (int x = 0; x < w; x++)

                {

                    float distFromCenter = Mathf.Abs(x - center);

                    float alpha = 1f - (distFromCenter / center);

                    alpha = Mathf.Clamp01(alpha);

                    tex.SetPixel(x, y, new Color(color.r, color.g, color.b, color.a * alpha));

                }

            }

            tex.Apply();

            Sprite sprite = Sprite.Create(tex, new Rect(0, 0, w, h), new Vector2(0.5f, 0.5f));

            _skillThemeSpriteCache[key] = sprite;

            return sprite;

        }

        private void AddSkillThemeTextShadow(Text txt)

        {

            if (txt == null || txt.gameObject.GetComponent<Shadow>() != null) return;

            var shadow = txt.gameObject.AddComponent<Shadow>();

            shadow.effectColor = new Color(0, 0, 0, 0.85f);

            shadow.effectDistance = new Vector2(1, -1);

        }

        private void SetButtonThemeSprite(Button btn, Sprite sprite)

        {

            if (btn == null) return;

            btn.transition = Selectable.Transition.ColorTint;

            var cb = btn.colors;

            cb.normalColor = Color.white;

            cb.highlightedColor = new Color(0.9f, 0.9f, 0.9f, 1f);

            cb.pressedColor = new Color(0.7f, 0.7f, 0.7f, 1f);

            cb.selectedColor = Color.white;

            btn.colors = cb;

            var raw = btn.GetComponent<RawImage>();

            if (raw != null)

            {

                DestroyImmediate(raw);

            }

            var img = btn.GetComponent<Image>();

            if (img == null) img = btn.gameObject.AddComponent<Image>();

            if (img != null)
            {
                img.sprite = sprite;
                img.color = Color.white;
                img.enabled = true;
                img.raycastTarget = true;
                btn.targetGraphic = img;
            }

        }

        private List<Button> FindChildButtons(Transform root, string name)

        {

            List<Button> results = new List<Button>();

            FindChildButtonsRecursive(root, name, results);

            return results;

        }

        private void FindChildButtonsRecursive(Transform current, string name, List<Button> results)

        {

            if (current.name == name)

            {

                var btn = current.GetComponent<Button>();

                if (btn != null) results.Add(btn);

            }

            for (int i = 0; i < current.childCount; i++)

            {

                FindChildButtonsRecursive(current.GetChild(i), name, results);

            }

        }

        private void SetChildActiveExact(Transform root, string name, bool bActive)

        {

            Transform[] children = root.GetComponentsInChildren<Transform>(true);

            foreach (var child in children)

            {

                if (child.name == name)

                {

                    child.gameObject.SetActive(bActive);

                }

            }

        }

