            var btnReset = CreateSkillBookButton(root, "btn_reset_skills", "Reset Skills", new Vector2(254f, -79f), new Vector2(106f, 22f), 10); // Eşit boyut (106f), yumuşatılmış köşe (radius = 10)

            btnReset.onClick.RemoveAllListeners();

            btnReset.onClick.AddListener(() => {

                var netMgr = KONetworkManager.Instance;

                if (netMgr != null && netMgr.IsConnected)

                {

                    using var pkt = new KOPacketWriter(WizOpcode.WIZ_CLASS_CHANGE);

                    pkt.WriteByte(0x04); // CLASS_RESET_SKILL_REQ

                    netMgr.SendPacket(pkt);

                }

            });

            var titleLine = root.Find("img_title_line")?.gameObject;

            if (titleLine != null)

            {

                titleLine.SetActive(false); // Butonlar geldiği için eski çizgiyi gizle

            }

            var confirmObj = root.Find("SkillTreeResetConfirm")?.gameObject;

            if (confirmObj != null)

            {

                confirmObj.SetActive(false); // Panel açıldığında onay kutusunu kapalı başlat

            }

            // Reposition skilltree elements to match Karus layout (378px layout width)

            if (!isModern)

            {

                RepositionSkillTreeLayout(root);

            }

            CreateSkillDistributionPanel(root);

        }

        private void FixSkillTreePrefabHierarchy(Transform root)

        {

            // string_0..3 (Basic Stat - kullanılmayanlar) tamamen gizlenir.
            for (int i = 0; i < 4; i++)
            {
                var s = root.Find("string_" + i);
                if (s != null) s.gameObject.SetActive(false);
            }

            // Büyücü/Rahip/Savaşçı/Okçu (4, 5, 6, 7) -> (img_mage_0/1/2, img_cleric_0/1/2, img_blade_0/1/2, img_ranger_0/1/2, img_hunter_0/1/2, img_master)
            ParentChildIfExist(root, "string_4", "img_mage_0", "img_cleric_0", "img_sorcerer_0", "img_shaman_0", "img_blade_0", "img_ranger_0", "img_berserker_0", "img_hunter_0");
            ParentChildIfExist(root, "string_5", "img_mage_1", "img_cleric_1", "img_sorcerer_1", "img_shaman_1", "img_blade_1", "img_ranger_1", "img_berserker_1", "img_hunter_1");
            ParentChildIfExist(root, "string_6", "img_mage_2", "img_cleric_2", "img_sorcerer_2", "img_shaman_2", "img_blade_2", "img_ranger_2", "img_berserker_2", "img_hunter_2");
            ParentChildIfExist(root, "string_7", "img_master");

        }

        private void ParentChildIfExist(Transform root, string childName, params string[] possibleParentNames)

        {

            Transform child = root.Find(childName);

            if (child == null)

            {

                var children = root.GetComponentsInChildren<Transform>(true);

                foreach (var c in children)

                {

                    if (c.name == childName) { child = c; break; }

                }

            }

            if (child == null) return;

            foreach (var pName in possibleParentNames)

            {

                Transform parentObj = root.Find(pName);

                if (parentObj == null)

                {

                    var children = root.GetComponentsInChildren<Transform>(true);

                    foreach (var c in children)

                    {

                        if (c.name == pName) { parentObj = c; break; }

                    }

                }

                if (parentObj != null && parentObj.gameObject.activeSelf)

                {

                    RectTransform childRT = child.GetComponent<RectTransform>();

                    RectTransform parentRT = parentObj.GetComponent<RectTransform>();

                    if (childRT != null && parentRT != null)

                    {

                        Vector2 localPos = childRT.anchoredPosition - parentRT.anchoredPosition;

                        child.SetParent(parentObj, false);

                        childRT.anchoredPosition = localPos;

                    }

                    break;

                }

            }

        }

        private void RepositionSkillTreeLayout(Transform root)

        {

            // 1. Tab buttons

            var btnPublic = root.Find("btn_public")?.GetComponent<RectTransform>();

            if (btnPublic != null) btnPublic.anchoredPosition = new Vector2(12f, btnPublic.anchoredPosition.y);

            string[] classTabPrefixes = { "btn_ranger", "btn_blade", "btn_mage", "btn_cleric", "btn_hunter", "btn_berserker", "btn_sorcerer", "btn_shaman" };

            foreach (var prefix in classTabPrefixes)

            {

                for (int t = 0; t < 3; t++)

                {

                    var btn = root.Find($"{prefix}{t}")?.GetComponent<RectTransform>();

                    if (btn != null)

                    {

                        float targetX = t == 0 ? 83f : (t == 1 ? 155f : 226f);

                        btn.anchoredPosition = new Vector2(targetX, btn.anchoredPosition.y);

                    }

                }

            }

            var btnMaster = root.Find("btn_master")?.GetComponent<RectTransform>();

            if (btnMaster != null) btnMaster.anchoredPosition = new Vector2(298f, btnMaster.anchoredPosition.y);

            // 2. Navigation buttons

            var btnLeft = root.Find("btn_left")?.GetComponent<RectTransform>();

            if (btnLeft != null) btnLeft.anchoredPosition = new Vector2(117f, btnLeft.anchoredPosition.y);

            var btnRight = root.Find("btn_right")?.GetComponent<RectTransform>();

            if (btnRight != null) btnRight.anchoredPosition = new Vector2(229f, btnRight.anchoredPosition.y);

            var pageTxt = root.Find("string_page")?.GetComponent<RectTransform>();

            if (pageTxt != null) pageTxt.anchoredPosition = new Vector2(162f, pageTxt.anchoredPosition.y);

            // 3. Columns values & buttons

            for (int i = 0; i < 8; i++)

            {

                bool isLeftCol = (i % 2 == 0); // 0, 2, 4, 6 are left column

                var valTxt = root.Find($"string_{i}")?.GetComponent<RectTransform>();

                if (valTxt != null)

                {

                    valTxt.anchoredPosition = new Vector2(isLeftCol ? 100f : 280f, valTxt.anchoredPosition.y);

                }

                var btnPt = root.Find($"btn_{i}")?.GetComponent<RectTransform>();

                if (btnPt != null)

                {

                    btnPt.anchoredPosition = new Vector2(isLeftCol ? 163f : 341f, btnPt.anchoredPosition.y);

                }

            }

            // 4. Branch labels (all matching names)

            Transform[] children = root.GetComponentsInChildren<Transform>(true);

            foreach (var child in children)

            {

                string name = child.name.ToLower().Trim();

                bool isCol1 = name.Contains("_0") || name.Contains("_2");

                bool isCol2 = name.Contains("_1") || name == "img_master";

                if (name.Contains("img_ranger") || name.Contains("img_blade") || name.Contains("img_mage") || name.Contains("img_cleric") ||

                    name.Contains("img_hunter") || name.Contains("img_berserker") || name.Contains("img_sorcerer") || name.Contains("img_shaman") ||

                    name == "img_master")

                {

                    var rt = child.GetComponent<RectTransform>();

                    if (rt != null)

                    {

                        if (isCol1) rt.anchoredPosition = new Vector2(12f, rt.anchoredPosition.y);

                        else if (isCol2) rt.anchoredPosition = new Vector2(192f, rt.anchoredPosition.y);

                    }

                }

            }

        }

        private Button CreateSkillBookButton(Transform parent, string name, string label, Vector2 pos, Vector2 size, int radius)

        {

            var btnObj = parent.Find(name)?.gameObject;

            if (btnObj == null)

            {

                btnObj = new GameObject(name, typeof(RectTransform));

                btnObj.transform.SetParent(parent, false);

            }

            var rt = btnObj.GetComponent<RectTransform>();

            rt.anchorMin = new Vector2(0, 1);

            rt.anchorMax = new Vector2(0, 1);

            rt.pivot = new Vector2(0, 0.5f);

            rt.anchoredPosition = pos;

            rt.sizeDelta = size;

            var img = btnObj.GetComponent<Image>();

            if (img == null) img = btnObj.AddComponent<Image>();

            // Boyut ve yarıçapı içeren dinamik cache anahtarı (rebuild tetiklemek için)

            string cacheKey = $"{name}_bg_{(int)size.x}_{(int)size.y}_{radius}";

            img.sprite = GetSkillThemeRoundedRectSprite(cacheKey, (int)size.x, (int)size.y, radius,

                new Color(0.18f, 0.14f, 0.10f, 1f),

                new Color(0.5f, 0.4f, 0.18f, 0.9f),

                1);

            var btn = btnObj.GetComponent<Button>();

            if (btn == null) btn = btnObj.AddComponent<Button>();

            var txtObj = btnObj.transform.Find("Text")?.gameObject;

            if (txtObj == null)

            {

                txtObj = new GameObject("Text", typeof(RectTransform));

                txtObj.transform.SetParent(btnObj.transform, false);

            }

            var txtRT = txtObj.GetComponent<RectTransform>();

            txtRT.anchorMin = Vector2.zero;

            txtRT.anchorMax = Vector2.one;

            txtRT.offsetMin = Vector2.zero;

            txtRT.offsetMax = Vector2.zero;

            var txt = txtObj.GetComponent<Text>();

            if (txt == null) txt = txtObj.AddComponent<Text>();

            txt.text = label;

            txt.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");

            txt.fontSize = 11;

            txt.fontStyle = FontStyle.Bold;

            txt.color = new Color(0.95f, 0.85f, 0.5f, 1);

            txt.alignment = TextAnchor.MiddleCenter;

            // Text shadow/glow

            var shadow = txtObj.GetComponent<Shadow>();

            if (shadow == null) shadow = txtObj.AddComponent<Shadow>();

            shadow.effectColor = new Color(0f, 0f, 0f, 0.8f);

            shadow.effectDistance = new Vector2(1f, -1f);

            return btn;

        }

        private void ShowSkillTreeResetConfirmation(Transform root)

        {

            var confirmObj = root.Find("SkillTreeResetConfirm")?.gameObject;

