            }

            confirmObj = new GameObject("SkillTreeResetConfirm", typeof(RectTransform));

            confirmObj.transform.SetParent(root, false);

            confirmObj.transform.SetAsLastSibling(); // Katman sorunu çözümü: Daima en önde çizilsin

            var rt = confirmObj.GetComponent<RectTransform>();

            rt.anchorMin = new Vector2(0.5f, 0.5f);

            rt.anchorMax = new Vector2(0.5f, 0.5f);

            rt.pivot = new Vector2(0.5f, 0.5f);

            rt.sizeDelta = new Vector2(280f, 140f); // Genişlik ve yükseklik artırıldı

            rt.anchoredPosition = new Vector2(0f, 0f);

            var img = confirmObj.AddComponent<Image>();

            img.sprite = GetSkillThemeRoundedRectSprite("skill_reset_confirm_bg_280_140_8", 280, 140, 8,

                new Color(0.12f, 0.09f, 0.07f, 0.95f),

