            txt.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");

            txt.fontSize = 11;

            txt.fontStyle = FontStyle.Bold;

            txt.color = new Color(0.95f, 0.85f, 0.5f, 1f);

            txt.alignment = TextAnchor.MiddleCenter;

            var shadow = txtObj.AddComponent<Shadow>();

            shadow.effectColor = new Color(0f, 0f, 0f, 0.8f);

            shadow.effectDistance = new Vector2(1f, -1f);

            // YES ve NO butonları hizalandı, boyutları 90x24 yapıldı ve kayma/çakışma sorunları giderildi

            var btnYes = CreateSkillBookButton(confirmObj.transform, "btn_yes", "YES", new Vector2(40f, -105f), new Vector2(90f, 24f), 6);

            btnYes.onClick.RemoveAllListeners();

            btnYes.onClick.AddListener(() => {

                var netMgr = KONetworkManager.Instance;

                if (netMgr != null && netMgr.IsConnected)

