            var btnNo = CreateSkillBookButton(confirmObj.transform, "btn_no", "NO", new Vector2(150f, -105f), new Vector2(90f, 24f), 6);

            btnNo.onClick.RemoveAllListeners();

            btnNo.onClick.AddListener(() => {

                confirmObj.SetActive(false);

            });

