        private void UpdateTabButtonStyles(Transform root, int currentKindOf)

        {

            string[] tabs = {

                "btn_public", "btn_master",

                "btn_berserker3", "btn_hunter3", "btn_sorcerer3", "btn_shaman3",

                "btn_blade3", "btn_ranger3", "btn_mage3", "btn_cleric3",

                "btn_ranger0", "btn_ranger1", "btn_ranger2",

                "btn_blade0", "btn_blade1", "btn_blade2",

                "btn_mage0", "btn_mage1", "btn_mage2",

                "btn_cleric0", "btn_cleric1", "btn_cleric2",

                "btn_hunter0", "btn_hunter1", "btn_hunter2",

                "btn_berserker0", "btn_berserker1", "btn_berserker2",

                "btn_sorcerer0", "btn_sorcerer1", "btn_sorcerer2",

                "btn_shaman0", "btn_shaman1", "btn_shaman2"

            };

            if (_stTabButtons == null)

            {

                _stTabButtons = new List<Button>();

                Button[] allButtons = root.GetComponentsInChildren<Button>(true);

                foreach (var tabName in tabs)

                {

                    foreach (var btn in allButtons)

                    {

                        if (btn.name == tabName)

                        {

                            _stTabButtons.Add(btn);

                        }

                    }

                }

            }

            var activeSprite = GetSkillThemeRoundedRectSprite("tab_active", 75, 22, 0, new Color(0.28f, 0.22f, 0.08f, 1), Color.clear, 0);

            var inactiveSprite = GetSkillThemeRoundedRectSprite("tab_inactive", 75, 22, 0, new Color(0.08f, 0.08f, 0.08f, 0.9f), Color.clear, 0);

            foreach (var btn in _stTabButtons)

            {

                string tabName = btn.name;

                int tabKindOf = 0;

                if (tabName == "btn_master" || tabName.EndsWith("3")) tabKindOf = 4;

                else if (tabName == "btn_public") tabKindOf = 0;

                else if (tabName.EndsWith("0")) tabKindOf = 1;

                else if (tabName.EndsWith("1")) tabKindOf = 2;

                else if (tabName.EndsWith("2")) tabKindOf = 3;

                bool isActive = (tabKindOf == currentKindOf);

                SetButtonThemeSprite(btn, isActive ? activeSprite : inactiveSprite);

                var txt = btn.GetComponentInChildren<Text>();

                if (txt != null)

                {

                    txt.color = isActive ? new Color(0.95f, 0.85f, 0.35f, 1) : new Color(0.6f, 0.6f, 0.6f, 1);

                    txt.fontStyle = isActive ? FontStyle.Bold : FontStyle.Normal;

                    txt.fontSize = 12;

                    AddSkillThemeTextShadow(txt);

                }

            }

        }

        private void CreateStatDistributionPanel(Transform variousRoot)

        {

            if (_uiStatDistPanel != null) return;

            var existing = variousRoot.Find("StatDistributionPanel")?.gameObject;

            if (existing != null)

            {

                _uiStatDistPanel = existing;

                var bgImg = _uiStatDistPanel.GetComponent<Image>();

                if (bgImg != null && bgImg.sprite == null)

                {

                    bgImg.sprite = GetSkillThemeRoundedRectSprite("stat_dist_panel_bg_v2_180_192_0", 180, 192, 0,

                        new Color(0.08f, 0.08f, 0.08f, 0.95f), // Dark semi-transparent

                        new Color(0.45f, 0.35f, 0.15f, 0.9f),  // Gold border

                        1); // Border width 1

                }

            }

            else

            {

                // 1. Create container object

                _uiStatDistPanel = new GameObject("StatDistributionPanel");

                _uiStatDistPanel.transform.SetParent(variousRoot, false);

                var rt = _uiStatDistPanel.AddComponent<RectTransform>();

                rt.anchorMin = new Vector2(1f, 0.5f);

                rt.anchorMax = new Vector2(1f, 0.5f);

                rt.pivot = new Vector2(0f, 0.5f);

                rt.anchoredPosition = new Vector2(2f, -10f); // Closer to main panel (2 pixels)

                rt.sizeDelta = new Vector2(180f, 192f); // Perfect total height: 5 * 32px rows + 4 * 3px gaps + 2 * 10px margins = 192px

                // Add background image (unique cache key, radius = 0 for sharp corners)

                var bgImg = _uiStatDistPanel.AddComponent<Image>();

                bgImg.sprite = GetSkillThemeRoundedRectSprite("stat_dist_panel_bg_v2_180_192_0", 180, 192, 0,

                    new Color(0.08f, 0.08f, 0.08f, 0.95f), // Dark semi-transparent

                    new Color(0.45f, 0.35f, 0.15f, 0.9f),  // Gold border

                    1); // Border width 1

            }

            // Clear any pre-existing dynamic row objects

            for (int i = _uiStatDistPanel.transform.childCount - 1; i >= 0; i--)

            {

                var child = _uiStatDistPanel.transform.GetChild(i);

                if (child.name.StartsWith("Row_Stat_"))

                {

                    DestroyImmediate(child.gameObject);

                }

            }

            string[] statNames = { "STR", "HP", "DEX", "INT", "MP" };

            byte[] statTypes = { 0x01, 0x02, 0x03, 0x04, 0x05 };

            float rowHeight = 35f; // 32px height + 3px gap = 35px spacing

            float startY = 70f; // Symmetrical starting Y: Row 0 at 70, 1 at 35, 2 at 0, 3 at -35, 4 at -70

            for (int i = 0; i < 5; i++)

            {

                string sName = statNames[i];

                byte sType = statTypes[i];

                // Create row container

                var rowObj = new GameObject($"Row_Stat_{sName}");

                rowObj.transform.SetParent(_uiStatDistPanel.transform, false);

                var rowRT = rowObj.AddComponent<RectTransform>();

                rowRT.anchorMin = new Vector2(0.5f, 0.5f);

                rowRT.anchorMax = new Vector2(0.5f, 0.5f);

                rowRT.pivot = new Vector2(0.5f, 0.5f);

                rowRT.anchoredPosition = new Vector2(0f, startY - (i * rowHeight));

                rowRT.sizeDelta = new Vector2(160f, 32f); // Shortened Row Height to 32px

                // Add row background (unique cache key, radius = 0 for sharp corners)

                var rowBg = rowObj.AddComponent<Image>();

                rowBg.sprite = GetSkillThemeRoundedRectSprite($"row_bg_stat_{sName}_160_32_0", 160, 32, 0,

                    new Color(0.12f, 0.12f, 0.12f, 0.8f),

                    new Color(0.25f, 0.2f, 0.05f, 0.5f),

                    1);

                // Create Plus Button on the left

                var btnObj = new GameObject($"Btn_Plus_Stat_{sName}");

                btnObj.transform.SetParent(rowObj.transform, false);

                var btnRT = btnObj.AddComponent<RectTransform>();

                btnRT.anchorMin = new Vector2(0f, 0.5f);

                btnRT.anchorMax = new Vector2(0f, 0.5f);

                btnRT.pivot = new Vector2(0f, 0.5f);

                btnRT.anchoredPosition = new Vector2(4f, 0f); // 4px padding from left edge of row box

                btnRT.sizeDelta = new Vector2(24f, 24f); // Smaller square button (24x24)

                var btn = btnObj.AddComponent<Button>();

                btn.transition = Selectable.Transition.None; // Prevent automatic tinting from overriding colors

                var btnImg = btnObj.AddComponent<Image>();

                btnImg.sprite = GetSkillThemeRoundedRectSprite($"btn_plus_stat_{sName}_24_24_0", 24, 24, 0,

                    new Color(0.22f, 0.18f, 0.08f, 1f),

                    new Color(0.55f, 0.45f, 0.20f, 1f),

                    1);

                btn.targetGraphic = btnImg;

                // Plus text inside button

                var btnTxtObj = new GameObject("Text");

                btnTxtObj.transform.SetParent(btnObj.transform, false);

                var btnTxtRT = btnTxtObj.AddComponent<RectTransform>();

                btnTxtRT.anchorMin = Vector2.zero;

                btnTxtRT.anchorMax = Vector2.one;

                btnTxtRT.sizeDelta = Vector2.zero;

                btnTxtRT.offsetMin = Vector2.zero;

                btnTxtRT.offsetMax = Vector2.zero;

                var btnTxt = btnTxtObj.AddComponent<Text>();

                btnTxt.text = "+";

                btnTxt.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");

                btnTxt.alignment = TextAnchor.MiddleCenter;

                btnTxt.horizontalOverflow = HorizontalWrapMode.Overflow;

                btnTxt.verticalOverflow = VerticalWrapMode.Overflow;

                btnTxt.fontSize = 32;

                btnTxt.fontStyle = FontStyle.Bold;

                btnTxt.color = new Color(0.95f, 0.85f, 0.35f, 1f);

                // Create Stat Label (Centered inside the remaining row space)

                var labelObj = new GameObject($"Label_Stat_{sName}");

                labelObj.transform.SetParent(rowObj.transform, false);

                var labelRT = labelObj.AddComponent<RectTransform>();

                labelRT.anchorMin = new Vector2(0.2f, 0f); // Starts right past the 24px button space

                labelRT.anchorMax = new Vector2(1f, 1f);

                labelRT.pivot = new Vector2(0.5f, 0.5f);

                labelRT.anchoredPosition = Vector2.zero;

                labelRT.sizeDelta = Vector2.zero;

                var labelTxt = labelObj.AddComponent<Text>();

                labelTxt.text = sName;

                labelTxt.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");

                labelTxt.alignment = TextAnchor.MiddleCenter; // Centered text

                labelTxt.fontSize = 16;

                labelTxt.fontStyle = FontStyle.Bold;

                labelTxt.color = new Color(0.9f, 0.8f, 0.5f, 1f);

                // Add AutoRepeatButton for fast distribution on long press

                var autoRepeat = btnObj.AddComponent<AutoRepeatButton>();

                autoRepeat.CanRepeat = () => EntropyOnline.Core.GameManager.Instance != null && EntropyOnline.Core.GameManager.Instance.StatPoints > 0;

                autoRepeat.OnClickAction = () =>

                {

                    var gm = EntropyOnline.Core.GameManager.Instance;

                    if (gm != null && gm.StatPoints <= 0) return;

                    using var packet = new KOPacketWriter(WizOpcode.WIZ_POINT_CHANGE);

                    packet.WriteByte(sType);

                    packet.WriteInt16(1); // delta = +1

                    KONetworkManager.Instance?.SendPacket(packet);

                };

            }

            UpdateStatDistributionPanelVisibility();

        }

        private void UpdateStatDistributionPanelVisibility()

        {

            if (_uiStatDistPanel == null) return;

            var gm = EntropyOnline.Core.GameManager.Instance;

            bool shouldShow = _uiVarious != null && _uiVarious.activeSelf &&

                              _activeVariousPageId == "page_state" &&

                              gm != null && gm.StatPoints > 0;

            _uiStatDistPanel.SetActive(shouldShow);

        }

        private string[] GetActiveSkillBranchNames(Transform root)

        {

            string[] names = new string[4];

            names[0] = "Branch 1";

            names[1] = "Branch 2";

            names[2] = "Branch 3";

            names[3] = "Mastery";

            string[] classTabPrefixes = { "btn_ranger", "btn_blade", "btn_mage", "btn_cleric", "btn_hunter", "btn_berserker", "btn_sorcerer", "btn_shaman" };

            foreach (var prefix in classTabPrefixes)

            {

                var b0 = root.Find($"{prefix}0");

                if (b0 != null && b0.gameObject.activeSelf)

                {

                    for (int t = 0; t < 3; t++)

                    {

                        var btn = root.Find($"{prefix}{t}");

                        if (btn != null)

                        {

                            var txt = btn.GetComponentInChildren<Text>();

                            if (txt != null && !string.IsNullOrEmpty(txt.text))

                                names[t] = txt.text.Trim();

                        }

                    }

                    break;

                }

            }

            var bm = root.Find("btn_master");

            if (bm != null)

            {

                var txt = bm.GetComponentInChildren<Text>();

                if (txt != null && !string.IsNullOrEmpty(txt.text))

                    names[3] = txt.text.Trim();

            }

            return names;

        }

        private void CreateSkillDistributionPanel(Transform skillTreeRoot)

        {

            if (_uiSkillDistPanel != null) return;

            var existing = skillTreeRoot.Find("SkillDistributionPanel")?.gameObject;

            if (existing != null)

            {

                _uiSkillDistPanel = existing;

                var bgImg = _uiSkillDistPanel.GetComponent<Image>();

                if (bgImg != null && bgImg.sprite == null)

                {

                    bgImg.sprite = GetSkillThemeRoundedRectSprite("skill_dist_panel_bg_180_157_0", 180, 157, 0,

                        new Color(0.08f, 0.08f, 0.08f, 0.95f), // Dark semi-transparent

                        new Color(0.45f, 0.35f, 0.15f, 0.9f),  // Gold border

                        1); // Border width 1

                }

            }

            else

            {

                // 1. Create container object

                _uiSkillDistPanel = new GameObject("SkillDistributionPanel");

                _uiSkillDistPanel.transform.SetParent(skillTreeRoot, false);

                var rt = _uiSkillDistPanel.AddComponent<RectTransform>();

                rt.anchorMin = new Vector2(0f, 1f);

                rt.anchorMax = new Vector2(0f, 1f);

                rt.pivot = new Vector2(1f, 1f);

                rt.anchoredPosition = new Vector2(-4f, 0f); // 4 pixels offset to the left, aligned to the top edge

                rt.sizeDelta = new Vector2(180f, 157f); // Height: 4 rows * 32px + 3 gaps * 3px + 20px margins = 157px

                // Add background image (unique cache key, radius = 0 for sharp corners)

                var bgImg = _uiSkillDistPanel.AddComponent<Image>();

                bgImg.sprite = GetSkillThemeRoundedRectSprite("skill_dist_panel_bg_180_157_0", 180, 157, 0,

                    new Color(0.08f, 0.08f, 0.08f, 0.95f), // Dark semi-transparent

                    new Color(0.45f, 0.35f, 0.15f, 0.9f),  // Gold border

                    1); // Border width 1

            }

            // Clear any pre-existing dynamic row objects

            for (int i = _uiSkillDistPanel.transform.childCount - 1; i >= 0; i--)

            {

                var child = _uiSkillDistPanel.transform.GetChild(i);

                if (child.name.StartsWith("Row_Skill_"))

                {

                    DestroyImmediate(child.gameObject);

                }

            }

            string[] statNames = GetActiveSkillBranchNames(skillTreeRoot);

            float rowHeight = 35f; // 32px height + 3px gap = 35px spacing

            float startY = 52.5f; // Symmetrical Y coordinate inside 157 height panel

            for (int i = 0; i < 4; i++)

            {

                string sName = statNames[i];

                int sIndex = i; // 0 for Row 0, 1 for Row 1, 2 for Row 2, 3 for Row 3

                int iValue = sIndex + 5; // Corresponding subclass index in PointPushUpButton (5, 6, 7, 8)

                // Create row container

                var rowObj = new GameObject($"Row_Skill_{sName}");

                rowObj.transform.SetParent(_uiSkillDistPanel.transform, false);

                var rowRT = rowObj.AddComponent<RectTransform>();

                rowRT.anchorMin = new Vector2(0.5f, 0.5f);

                rowRT.anchorMax = new Vector2(0.5f, 0.5f);

                rowRT.pivot = new Vector2(0.5f, 0.5f);

                rowRT.anchoredPosition = new Vector2(0f, startY - (i * rowHeight));

                rowRT.sizeDelta = new Vector2(160f, 32f); // Shortened Row Height to 32px

                // Add row background (unique cache key, radius = 0 for sharp corners)

                var rowBg = rowObj.AddComponent<Image>();

                rowBg.sprite = GetSkillThemeRoundedRectSprite($"row_bg_skill_{sName}_160_32_0", 160, 32, 0,

                    new Color(0.12f, 0.12f, 0.12f, 0.8f),

                    new Color(0.25f, 0.2f, 0.05f, 0.5f),

                    1);

                // Create Plus Button on the left

                var btnObj = new GameObject($"Btn_Plus_Skill_{sName}");

                btnObj.transform.SetParent(rowObj.transform, false);

                var btnRT = btnObj.AddComponent<RectTransform>();

                btnRT.anchorMin = new Vector2(0f, 0.5f);

                btnRT.anchorMax = new Vector2(0f, 0.5f);

                btnRT.pivot = new Vector2(0f, 0.5f);

                btnRT.anchoredPosition = new Vector2(4f, 0f); // 4px padding from left edge of row box

                btnRT.sizeDelta = new Vector2(24f, 24f); // Smaller square button (24x24)

                var btn = btnObj.AddComponent<Button>();

                var btnImg = btnObj.AddComponent<Image>();

                btnImg.sprite = GetSkillThemeRoundedRectSprite($"btn_plus_skill_{sName}_24_24_0", 24, 24, 0,

                    new Color(0.22f, 0.18f, 0.08f, 1f),

                    new Color(0.55f, 0.45f, 0.20f, 1f),

                    1);

                btn.targetGraphic = btnImg;

                // Plus text inside button

                var btnTxtObj = new GameObject("Text");

                btnTxtObj.transform.SetParent(btnObj.transform, false);

                var btnTxtRT = btnTxtObj.AddComponent<RectTransform>();

                btnTxtRT.anchorMin = Vector2.zero;

                btnTxtRT.anchorMax = Vector2.one;

                btnTxtRT.sizeDelta = Vector2.zero;

                var btnTxt = btnTxtObj.AddComponent<Text>();

                btnTxt.text = "+";

                btnTxt.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");

                btnTxt.alignment = TextAnchor.MiddleCenter;

                btnTxt.horizontalOverflow = HorizontalWrapMode.Overflow;

                btnTxt.verticalOverflow = VerticalWrapMode.Overflow;

                btnTxt.fontSize = 32;

                btnTxt.fontStyle = FontStyle.Bold;

                btnTxt.color = new Color(0.95f, 0.85f, 0.35f, 1f);

                // Create Skill Label (Centered inside the remaining row space)

                var labelObj = new GameObject($"Label_Skill_{sName}");

                labelObj.transform.SetParent(rowObj.transform, false);

                var labelRT = labelObj.AddComponent<RectTransform>();

                labelRT.anchorMin = new Vector2(0.2f, 0f); // Starts right past the 24px button space

                labelRT.anchorMax = new Vector2(1f, 1f);

                labelRT.pivot = new Vector2(0.5f, 0.5f);

                labelRT.anchoredPosition = Vector2.zero;

                labelRT.sizeDelta = Vector2.zero;

                var labelTxt = labelObj.AddComponent<Text>();

                labelTxt.text = sName;

                labelTxt.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");

                labelTxt.alignment = TextAnchor.MiddleCenter; // Centered text

                labelTxt.fontSize = 16;

                labelTxt.fontStyle = FontStyle.Bold;

                labelTxt.color = new Color(0.9f, 0.8f, 0.5f, 1f);

                // Add AutoRepeatButton for fast distribution on long press

                var autoRepeat = btnObj.AddComponent<AutoRepeatButton>();

                autoRepeat.CanRepeat = () => KOSkillTreeManager.Instance != null && KOSkillTreeManager.Instance.SkillInfo[0] > 0;

                autoRepeat.OnClickAction = () =>

                {

                    KOSkillTreeManager.Instance?.PointPushUpButton(iValue);

                    RefreshSkillTreeUI();

                };

            }

            UpdateSkillDistributionPanelVisibility();

        }

        private void UpdateSkillDistributionPanelVisibility()

        {

            if (_uiSkillDistPanel == null) return;

            bool shouldShow = _uiSkillTree != null && _uiSkillTree.activeSelf &&

                              KOSkillTreeManager.Instance != null && KOSkillTreeManager.Instance.SkillInfo[0] > 0;

            _uiSkillDistPanel.SetActive(shouldShow);

        }

        private void StartSetupCharacterPreviewDelayed()

        {

            StartCoroutine(SetupCharacterPreviewDelayedCoroutine());

        }

        private System.Collections.IEnumerator SetupCharacterPreviewDelayedCoroutine()

        {

            yield return new UnityEngine.WaitForSeconds(0.25f);

            if (KOInventory.Instance != null && _uiInventory.activeSelf)

            {

                KOInventory.Instance.SetupCharacterPreview();

            }

        }

        private static void CreateColumnText(Transform parent, string name, float posX, float width, string content, Font font)
        {
            var colGo = new GameObject(name, typeof(RectTransform), typeof(UnityEngine.UI.Text));
            colGo.transform.SetParent(parent, false);

            var rt = colGo.GetComponent<RectTransform>();
            rt.anchorMin = new Vector2(0f, 0f);
            rt.anchorMax = new Vector2(0f, 1f); // Dikeyde satırı tamamen kaplar
            rt.pivot = new Vector2(0f, 0.5f);
            rt.anchoredPosition = new Vector2(posX, 0f);
            rt.sizeDelta = new Vector2(width, 0f);

            var txt = colGo.GetComponent<UnityEngine.UI.Text>();
            // Prefab fontunu kullanıyoruz, eğer null ise LegacyRuntime.ttf'e düşüyoruz
            txt.font = font != null ? font : Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");
            txt.fontSize = 11;
            txt.alignment = TextAnchor.MiddleCenter; // Dikey ve yatayda tam ortalar
            txt.supportRichText = true;
            txt.text = content;

            // Tıklamaların arkadaki Row butonuna geçmesi için
            txt.raycastTarget = false;
        }

        public void ApplyUIScalingAndMargins()
        {
            if (GameOptionsManager.Instance == null) return;

            // 1. General UI Scale
            float scaleMultiplier = Mathf.Lerp(1.3f, 0.7f, GameOptionsManager.Instance.Graphic3_UIScale);
            UIScaleMultiplier = Mathf.Lerp(0.7f, 1.3f, GameOptionsManager.Instance.Graphic3_UIScale);

            if (_canvas != null)
            {
                var scaler = _canvas.GetComponent<CanvasScaler>();
                if (scaler != null)
                {
                    scaler.referenceResolution = new Vector2(KO_SCREEN_W * scaleMultiplier, KO_SCREEN_H * scaleMultiplier);

                    // 1b. Dynamically update localScale of all loaded panels (chat, hp/mp, inventory, etc.)
                    float refX = KO_SCREEN_W * scaleMultiplier;
                    float refY = KO_SCREEN_H * scaleMultiplier;
                    float expectedScale = Mathf.Min(Screen.width / refX, Screen.height / refY);

                    if (expectedScale > 0f && _loadedPanels != null)
                    {
                        foreach (var kvp in _loadedPanels)
                        {
                            var panel = kvp.Value;
                            if (panel == null) continue;

                            var rt = panel.GetComponent<RectTransform>();
                            if (rt != null)
                            {
                                float finalScale = UIScaleMultiplier / expectedScale;
                                rt.localScale = new Vector3(finalScale, finalScale, finalScale);
                            }
                        }
                    }
                }
            }

            if (_mobileTopRightCanvas != null)
            {
                var trScaler = _mobileTopRightCanvas.GetComponent<CanvasScaler>();
                float scale = Mathf.Lerp(0.7f, 1.3f, GameOptionsManager.Instance.Graphic3_UIScale);
                if (trScaler != null)
                {
                    trScaler.scaleFactor = scale;
                }
                _mobileTopRightCanvas.scaleFactor = scale;
            }

            // 2. Safe Area Padding (Reset to zero as UI Expand settings are disabled)
            if (_hudContainer != null)
            {
                _hudContainer.offsetMin = Vector2.zero;
                _hudContainer.offsetMax = Vector2.zero;
            }

            // 3. Update skill bar margins
            if (MobileSkillBar.Instance != null)
            {
                MobileSkillBar.Instance.ApplyExpandMargins();

                var skillBarCanvas = MobileSkillBar.Instance.GetComponentInChildren<Canvas>();
                if (skillBarCanvas != null)
                {
                    float scale = Mathf.Lerp(0.7f, 1.3f, GameOptionsManager.Instance.Graphic2_SkillBarSize);
                    var skillBarScaler = skillBarCanvas.GetComponent<CanvasScaler>();
                    if (skillBarScaler != null)
                    {
                        skillBarScaler.scaleFactor = scale;
                    }
                    skillBarCanvas.scaleFactor = scale;
                }
            }

            // 4. Update party UI scale
            if (_uiParty != null)
            {
                float mainScale = _canvas != null ? _canvas.scaleFactor : 1f;
                float partyScale = Mathf.Lerp(0.7f, 1.3f, GameOptionsManager.Instance.Graphic2_PartyUIScale);
                _uiParty.transform.localScale = new Vector3(partyScale / mainScale, partyScale / mainScale, 1f);
            }

            // 5. Update top-right UI margins
            var topRightUI = FindAnyObjectByType<KOMobileTopRightUI>();
            if (topRightUI != null)
            {
                topRightUI.ApplyExpandMargins();
            }

            // 6. Force update next Update frame scale check and reposition skillbar immediately
            _lastScaleFactor = 0f;
            RepositionSkillBarForPanel(true);
        }

        public void ApplyPostProcessingSettings()
        {
            if (GameOptionsManager.Instance == null) return;

            var volumes = FindObjectsByType<Volume>();
            foreach (var vol in volumes)
            {
                if (vol.profile == null) continue;

                if (vol.profile.TryGet<ColorAdjustments>(out var colorAdjustments))
                {
                    float exposureValue = Mathf.Lerp(-2f, 2f, GameOptionsManager.Instance.Graphic3_PostExposure);
                    colorAdjustments.postExposure.value = exposureValue;

                    float contrastValue = Mathf.Lerp(-50f, 50f, GameOptionsManager.Instance.Graphic3_Contrast);
                    colorAdjustments.contrast.value = contrastValue;
                }
            }
        }


}

