    public class KOListSelectionHandler : MonoBehaviour, UnityEngine.EventSystems.IPointerClickHandler

    {

        public System.Action<int> OnLineSelected;

        public void OnPointerClick(UnityEngine.EventSystems.PointerEventData eventData)

        {

            var txt = GetComponent<Text>();

            if (txt == null || string.IsNullOrEmpty(txt.text)) return;

            RectTransform rectTransform = GetComponent<RectTransform>();

            if (RectTransformUtility.ScreenPointToLocalPointInRectangle(rectTransform, eventData.position, eventData.pressEventCamera, out Vector2 localPoint))

            {

                float topY = rectTransform.rect.yMax;

                float distanceFromTop = topY - localPoint.y;

                float estimatedLineHeight = txt.fontSize * txt.lineSpacing;

                if (estimatedLineHeight <= 0) estimatedLineHeight = 12f;

                int lineIndex = Mathf.FloorToInt(distanceFromTop / estimatedLineHeight);

                if (lineIndex >= 0)

                {

                    OnLineSelected?.Invoke(lineIndex);

                }

            }

        }

    }

    public class AutoRepeatButton : MonoBehaviour, UnityEngine.EventSystems.IPointerDownHandler, UnityEngine.EventSystems.IPointerUpHandler, UnityEngine.EventSystems.IPointerExitHandler

    {

        public System.Action OnClickAction;

        public System.Func<bool> CanRepeat;

        private bool _isPressed = false;

        private float _pressTime = 0f;

        private float _lastRepeatTime = 0f;

        private const float DelayToRepeat = 1.0f;

        private const float RepeatInterval = 0.08f;

        public void OnPointerDown(UnityEngine.EventSystems.PointerEventData eventData)

        {

            if (CanRepeat != null && !CanRepeat()) return;

            _isPressed = true;

            _pressTime = Time.unscaledTime;

            _lastRepeatTime = Time.unscaledTime;

            OnClickAction?.Invoke();

        }

        public void OnPointerUp(UnityEngine.EventSystems.PointerEventData eventData)

        {

            _isPressed = false;

        }

        public void OnPointerExit(UnityEngine.EventSystems.PointerEventData eventData)

        {

            _isPressed = false;

        }

        private void Update()

        {

            if (!_isPressed) return;

            if (CanRepeat != null && !CanRepeat())

            {

                _isPressed = false;

                return;

            }

            float heldDuration = Time.unscaledTime - _pressTime;

            if (heldDuration >= DelayToRepeat)

            {

                if (Time.unscaledTime - _lastRepeatTime >= RepeatInterval)

                {

                    OnClickAction?.Invoke();

                    _lastRepeatTime = Time.unscaledTime;

                }

            }
        }
    }

    public class KOURaycastDebugger : MonoBehaviour
    {
        private void Update()
        {
            var pointer = UnityEngine.InputSystem.Pointer.current;
            if (pointer == null) return;

            if (pointer.press.wasPressedThisFrame)
            {
                if (UnityEngine.EventSystems.EventSystem.current == null) return;
                var mousePos = pointer.position.ReadValue();
                var pointerData = new UnityEngine.EventSystems.PointerEventData(UnityEngine.EventSystems.EventSystem.current)
                {
                    position = mousePos
                };

                var results = new System.Collections.Generic.List<UnityEngine.EventSystems.RaycastResult>();
                UnityEngine.EventSystems.EventSystem.current.RaycastAll(pointerData, results);


            }
        }
    }
